    -- every PAINT is the blunt one. Only turn this on if a paint-driven crash survives the soar
    -- block, and if you do, expect to owe the exit a dedicated release path.
    route3_node_lockout_paint = false,
    -- ⭐ LOOP CAMERA -- takes the camera for the duration of a node so the loop is actually visible.
    -- blend 1.0 = follow her, dead-centre. Lower = she arcs through frame against a held anchor
    -- (the cinematic look). side_deg 80-90 films side-on, which is the only angle a loop reads from.
    route3_loopcam = true,
    route3_loopcam_dist = 14.0,
    route3_loopcam_height = 2.0,
    route3_loopcam_side_deg = 80.0,
    route3_loopcam_elev_deg = 6.0,
    route3_loopcam_blend = 1.0,
    route3_loopcam_ease = 0.25,
    route3_loopcam_max = 3.5,   -- seconds the camera is held, INDEPENDENT of the (longer) node lockout
    route3_loopcam_track_joint = true,  -- aim at the seat JOINT (the thing that actually moves in a loop)
    -- "player" | "joint" | "body". PLAYER is the default: the rider is PROVEN to travel the loop
    -- arc, so following him cannot fail the way following the (never-moving) body did.
    route3_loopcam_target = "player",
    route3_loopcam_min_above = 1.5,  -- ⛔ hard floor: never film from BELOW the subject (= inside terrain)
    route3_loopcam_snap_dist = 4.0,  -- past this the camera hard-cuts instead of easing (a dive covers 30m+)
    -- ⭐⭐ SWITCH THE CAMERA CONTROLLER OFF while we film (2026-08-04, learned from Puppeteer).
    -- Every "doesn't follow / teleports at the end" round shared one cause: the game's follow-camera
    -- controller re-poses the camera every frame, so our write and its write FIGHT -- the winner
    -- depends on frame order, which is exactly what "worked once, then never again" looks like.
    -- Nick does not fight it: PuppetSetup.lua:144 calls switchCamera(2,...) FIRST, which parks the
    -- controller in a mode that leaves the transform alone, and only THEN writes positions -- and
    -- his camera visibly tracks node moves. Type 11 = the oxcart sweep cam (BetterOxcartsRedux), 0
    -- = the normal player camera (our July probe's restore value).
    route3_loopcam_cam_type = 2,
    -- ⭐⭐ PAN MODE (2026-08-05, Aurora's design, and it is the better one): "the camera kind of
    -- just needs to not be following the griffin natively and just pan downward (or upward for
    -- ascend)". Tracking a live target inherits every glitch of the thing tracked -- the rider
    -- snap at node-end IS the camera jump. So: FIXED side-on vantage, and only the LOOK direction
    -- sweeps vertically over the shot. Nothing tracks, so nothing can lag or jump. "track" keeps
    -- the old live-follow for comparison.
    route3_loopcam_mode = "pan",
    route3_loopcam_pan_m = 9.0,     -- ASCEND: vertical metres the aim sweeps over the shot
    route3_loopcam_pan_secs = 2.2,  -- ASCEND: how long the sweep takes (smoothstepped)
    -- ⭐ DESCEND gets its OWN pair (Aurora 2026-08-05: 25m/0.8s was right for ascend, "didn't
    -- really work for descend"): a quick-descend covers more sky faster, so it wants a longer
    -- sweep. Starting guesses -- hers to tune.
    route3_loopcam_pan_m_desc = 25.0,
    route3_loopcam_pan_secs_desc = 1.4,
    -- ⭐ horizontal follow (Aurora 2026-08-05): holding forward during a loop drifts her ahead;
    -- the planted camera ROTATES to keep her framed by tracking the BODY transform's horizontal
    -- drift. Safe in pan mode: the body transform is drive-moved and smooth -- the end-of-node
    -- snap that caused the old jumps was the rider/JOINT, which pan mode never reads.
    route3_loopcam_pan_follow = true,
    route3_ride_hud_force_show = true,  -- un-hide a prompt slot we have written (B only shows with L1 held)
    -- ⭐⭐ FAKE B PROMPT (2026-08-05). The cling context withholds the B slot and writing PlayStates
    -- to un-hide it = CTD ×2 (see the law in griffin_ride_hud_tick). So we DRAW our own "B <label>"
    -- line beside the cluster with the IrisFont d2d layer -- ours from pixel one, no shared state.
    -- It only draws while the game's own B slot is suppressed, so the moment LB reveals the real
    -- prompt the fake vanishes (never two Bs on screen). Offsets are 1080p-authored px from the
