    -- (route3_flight_toggle_buttons), so Fly/Land is a truthful prompt. The carry label is BLANK
    -- on purpose: no EAT action exists yet, and a prompt describing an action that does not
    -- happen is lying (the file's own carrying-override law). Wire eating first, then label it.
    route3_hud_faker3 = true,
    route3_hud_r3_ground = "Fly",
    route3_hud_r3_flight = "Land",
    route3_hud_r3_carry = "",
    route3_hud_faker3_dy = 27.0,   -- px ABOVE the fake B line (1080p-authored, scales)
    route3_hud_faker3_dx = 245.0,  -- R3's OWN distance in from the right edge (independent column)
    route3_hud_fakel3 = true,      -- ⭐ L3 line (Aurora: ground-only "Dismount")
    route3_hud_l3_ground = "Dismount",
    route3_hud_l3_flight = "",     -- blank = no L3 line while airborne
    route3_hud_fakel3_dy = 54.0,   -- one row above the R3 line
    route3_hud_fakel3_dx = 245.0,
