    route3_hud_fakelt_dy = 158.0,
    route3_hud_fakerb = true,
    route3_hud_fakerb_dx = 385.0,
    route3_hud_fakerb_dy = 125.0,
    -- the game's shoulder rows use smaller type than the face buttons -- and its LT/RB glyphs are
    -- dimmed near-invisible in this context, so we draw our own bright glyph + word pair
    route3_hud_fake_px_shoulder = 18.0,
    -- ⭐⭐ NODE EXIT: hand her back to a neutral flight node when the burst ends. Without this she
    -- STAYS in the fired node forever (measured), which leaves a residual pose that displaces both
    -- riders permanently AND makes the next press a no-op because she is already in that node.
    -- Ch253SoaringFlight is our own already-proven travelling-flight node (oxtame_buck uses it).
    -- ⛔⛔ WRONG FIRST CHOICE, 2026-08-04: I defaulted this to Ch253SoaringFlight, which is the AI's
    -- TRAVELLING flight node -- it does not neutralise her, it actively flies her somewhere. Aurora
    -- immediately got "the griffin is trying to take control", shaking/vibration (our transform
    -- drive fighting the node's own motion) and occasional T-poses. That is swapping a stuck node
    -- for a worse one.
    -- ⛔ HoverWait was my second wrong answer and it CTD'd (22:36): Fly.Hovering.* is a STATIONARY
    -- family and our drive keeps flying her through it = clip-5010 signature at node level.
    -- ⭐⭐ LAW: the exit node must be the PUPPET NEUTRAL -- the state she is parked in while WE fly
    -- her by transform -- not whatever the AI or another mod uses as its neutral. For this rig that
    -- is Locomotion.Wait, which the crash tape itself identified ("from-node=Locomotion.Wait" on a
    -- clean fire) and which is proven safe for the whole of every normal flight.
    -- ⚠ Set route3_node_exit_node = "" to disable the retire entirely if it misbehaves.
    route3_node_exit_enabled = true,
    route3_node_exit_node = "Locomotion.Wait",
    route3_node_exit_secs = 1.5,   -- keep retrying the retire for this long, then give up cleanly
    -- ⭐ RIDE HUD: rename the on-screen prompts to her abilities while mounted. Blank = leave the
    -- game's own label alone. R1/R2 = RB/RT, L1/L2 = LB/LT.
    route3_ride_hud = true,
