    route3_hud_R1 = "Ascend",
    route3_hud_L1 = "Descend",
    route3_hud_A  = "Loop the Loop",
    route3_hud_Y  = "Grab",
    route3_hud_X  = "Dive Bomb",
    route3_hud_B  = "Soar",
    route3_hud_R2 = "",
    route3_hud_L2 = "",
    -- ⭐ GROUND set: the same buttons do different things with her feet down, so a single label
    -- set is wrong half the time. Blank falls back to the flight label above.
    route3_hudg_R1 = "Take Off",
    route3_hudg_L1 = "",
    route3_hudg_A  = "Take Off",
    route3_hudg_Y  = "Grab",
    route3_hudg_X  = "Gale",
    route3_hudg_B  = "Sprint",
    route3_hudg_R2 = "",
    route3_hudg_L2 = "",
