    -- how far our y may diverge from FlightControl's per frame before the native side AVs.
    -- DOWNED/REVIVE SLICE-0 PROBE (button-only; see griffin_probe_fc_start / griffin_probe_down_node)
    route3_downed_probe_node = "Damage.Damage_Root.DmgDownLoop", -- down-node candidate to audition on a FRIENDLY body
    route3_downed_probe_secs = 6.0,          -- FC-disable watch window; the probe ALWAYS restores FC after this
    route3_downed_probe_verify_delay = 0.5,  -- ⛔ the action slot is NOT populated in the firing frame; wait, then read
    -- DOWNED / REVIVE (slice 1, ground). A companion at the floor goes DOWN instead of dying.
    route3_downed_enabled = true,            -- master switch for the whole downed/revive system
    route3_downed_floor_hp = 1.0,            -- ⛔ NEVER 0: a character at 0 HP cannot be revived
    route3_downed_window_secs = 30.0,        -- how long you have to reach it before it goes to the stable
    route3_downed_revive_key = 0x52,         -- R -- hold near the body to revive
    route3_downed_revive_pad_mask = 0x40080, -- B/Circle (same constant the rodeo uses for gallop)
    route3_downed_revive_range = 2.5,        -- metres you must be within
    route3_downed_revive_hold_secs = 2.0,    -- hold duration to fill the revive bar
    route3_downed_revive_frac = 0.10,        -- fraction of max HP it gets up with
    route3_revive_health_fix_version = 0,    -- one-shot migration: old saved FULL-health revive
    route3_downed_clip_node = "Damage.Damage_Root.DmgDownLoop", -- PROVEN safe on a friendly (rabbit, 07-21)
    route3_downed_getup_node = "",           -- optional get-up node on revive; blank = let the AI sort itself out
    route3_downed_regen_pct_per_min = 10.0,  -- stable regen while benched (rest shortcut = slice 3)
    route3_stable_regen_hp_per_sec = 1.0,    -- timestamped recovery while dismissed; no polling loop
    -- ⭐ DROWNING = PERMANENT (08-09, Aurora's call: "it does give people more
    -- incentive to go out and tame more creatures or breed them"). ⛔ This is the
