    route3_mount_damage_scale = 0.25,          -- horse only: 250 HP otherwise makes one cyclops hit lethal
    -- A native griffin body on this setup has 105,000 HP because it retains its
    -- boss stat sheet. Enemy-vs-player attacks are far too small for that pool.
    -- Incoming damage is converted as maxHP / this effective companion pool,
    -- while still being subtracted from the griffin's REAL native HP.
    route3_griffin_effective_hp = 7000.0,
    -- A healthy griffin does not helplessly plummet: mount jumps, ledge drops and ordinary
