    route3_damage_fallback = true,             -- apply computed hit only if native HP stayed unchanged
    mount_hp_bar = true,                     -- companion health bar while summoned
    jump_max_air = 4.0,                      -- r92: seconds airborne before the arc hands to gravity
    jump_sync_character = false,             -- r92: also write app.Character position (opt-in, unproven)
    -- r84 bar geometry (1080p reference; scales with resolution)
    mount_hp_w = 552.0,                      -- width, matched to the Arisen's pair
    mount_hp_h = 9.0,                        -- thickness
    mount_hp_y = 112.0,                      -- pixels UP from the bottom edge
    mount_hp_x = 0.0,                        -- offset from centre (0 = centred)
    route3_mounted_combat = true,            -- mounted rider does not pacify nearby combat
    route3_companion_can_be_attacked = true, -- active tame remains targetable, mounted or not
    route3_ride_damage_immune = false,
    route3_hit_reactions = true,
    route3_hit_react_cooldown = 0.9,         -- min gap so a flurry cannot pin the clip at frame 0
    -- ⭐ DOWNED SLICE 2 (08-09). Aurora rode a horse off a big drop: the horse went
