    route3_downed_force_dismount = true,     -- a mount that goes down throws you off (you cannot ride a corpse)
    route3_downed_clip_fallback = true,      -- if the FSM down-node does not take, play the species' own die/down clip
    route3_downed_player_revive_anim = true, -- the Arisen kneels (com_revive_start/loop/end) while reviving
    -- FALL SHIELD. Falling WHILE MOUNTED: the horse takes the landing, so the rider
