    route3_rise_ascend_start_clip = -1,      -- bank-0 hover is a standalone loop -> no start needed
    route3_rise_ascend_clip = 5101,          -- ⛔ WAS 5010 (com_hover_idle_loop_heavey) = an eleven-CTD stationary-pose clip. 5101 = com_flight_loop_flapping, the flap's own loop, proven safe under movement. See the migration below.
    route3_rise_descend_start_clip = -1,
