    route3_dive_swoop_speed = 16.0,         -- forward follow-through speed (metres/sec)
    route3_dive_ground_clearance = 1.2,     -- hard floor clamp during drop / forward follow-through
    route3_dive_motion_enabled = false,     -- bank-50 clips carry persistent camera/impact notifies; movement stays enabled
    route3_dive_motion_bank = 50,           -- resident direct-motion bank (never enters a native action node)
    route3_dive_drop_clip = 551,            -- landing_dush_descent_loop_F (field-proven safe while moving)
    route3_dive_swoop_bank = 50,            -- separate from the drop so the finish can return to an aerial pose
