    route3_predation_small_exclude = "ch253", -- comma-separated name patterns NEVER caught (wild griffins; add big-monster ids as scans reveal them)
    route3_predation_small_include = "",    -- optional include filter (blank = any eligible; e.g. one species id to isolate a test)
    -- Victim "carry" vocabulary (goblin/small-humanoid; captured 2026-07-10 from a player grab).
