    route3_predation_eat_enabled = true,                           -- land while natively carrying -> set the prey down (real ragdoll) + eat it
    route3_predation_eat_grace = 1.5,                              -- min secs carried before a LANDING triggers eat (a low snatch shouldn't insta-eat)
