    route3_predation_eat_start_clip = 5300,                        -- "talons on the body" START clip (bank 20 get_eat_start), plays BEFORE the eat loop
    route3_predation_eat_start_secs = 1.5,-- how long the talons-on start plays before the eat LOOP takes over (eat-nearest uses ~3.8)
    route3_predation_eat_max_secs = 60.0,                          -- safety: end the eat after this even if the player never moves
