    route3_predation_clip_bank = 30,                               -- manual clip override BANK (used only if clip_id >= 0)
    route3_predation_clip_id = -1,                                 -- manual clip override ID (-1 = auto-resolve per species; goblin auto = bank 30 id 501)
    route3_predation_max_radius = 0.0,      -- refuse prey whose CharacterController radius exceeds this (0 = OFF); deer/stag jam the talon carry -- INSPECT a goblin vs a deer to pick a threshold between them
