end

local function make_position(x, y, z)
    local p = ValueType.new(sdk.find_type_definition("via.Position"))
    p.x = x or 0
    p.y = y or 0
    p.z = z or 0
    return p
end

local function sane_position(pos)
    if not pos then return false end
    local x, y, z = tonumber(pos.x), tonumber(pos.y), tonumber(pos.z)
    if not (x and y and z) then return false end
    if x ~= x or y ~= y or z ~= z then return false end
    local limit = 100000.0
    return math.abs(x) < limit and math.abs(y) < limit and math.abs(z) < limit
end

local function make_vec3(x, y, z)
    local v = ValueType.new(sdk.find_type_definition("via.vec3"))
    v.x = x or 0
    v.y = y or 0
    v.z = z or 0
    return v
end

function make_float2(x, y)
    local ok, v = pcall(function()
        local td = sdk.find_type_definition("via.Float2")
        if not td then return nil end
        local out = ValueType.new(td)
        out.x = x or 0
        out.y = y or 0
        return out
    end)
    return ok and v or nil
end

route3_ray = {}

function route3_ensure_ray()
    if route3_ray.ready then return true end
    local ok = pcall(function()
        route3_ray.system = sdk.get_native_singleton("via.physics.System")
        route3_ray.method = sdk.find_type_definition("via.physics.System")
            :get_method("castRay(via.physics.CastRayQuery, via.physics.CastRayResult)")
        route3_ray.contact_td = sdk.find_type_definition("via.physics.ContactPoint")
        route3_ray.query = sdk.create_instance("via.physics.CastRayQuery"):add_ref()
        route3_ray.result = sdk.create_instance("via.physics.CastRayResult"):add_ref()
        route3_ray.query:clearOptions()
        route3_ray.query:enableAllHits()
        route3_ray.query:enableNearSort()
        route3_ray.filter = route3_ray.query:get_FilterInfo()
    end)
    route3_ray.ready = ok and route3_ray.system ~= nil and route3_ray.method ~= nil
        and route3_ray.query ~= nil and route3_ray.result ~= nil and route3_ray.filter ~= nil
    return route3_ray.ready == true
end

function route3_cast_ground_ray(x, y, z, up, down)
    if not route3_ensure_ray() then return nil end
    local hit = nil
    pcall(function()
        route3_ray.filter:set_Group(0)
        route3_ray.filter:set_Layer(2)
        route3_ray.filter:set_MaskBits(0)
        route3_ray.result:clear()
        route3_ray.query:call(
            "setRay(via.vec3, via.vec3)",
            make_vec3(x, y + (tonumber(up) or 2.5), z),
            make_vec3(x, y - (tonumber(down) or 8.0), z)
        )
        route3_ray.method:call(route3_ray.system, route3_ray.query, route3_ray.result)
        local count = route3_ray.result:get_NumContactPoints() or 0
        if count > 0 then
            local contact = route3_ray.result:call("getContactPoint(System.UInt32)", 0)
            hit = contact and sdk.get_native_field(contact, route3_ray.contact_td, "Position") or nil
        end
    end)
    return hit
end

function route3_y_space_offset()
    -- GLOBAL vertical offset between UNIVERSAL and RENDER space (universal_y = render_y + offset).
    -- ⚠⚠ Y IS NOT SHARED between the spaces. The landing probe (2026-07-07) caught universal
    -- y=14.7 vs render y=-113.3 -- a 128m VERTICAL tile offset that varies by session (it depends
    -- on where the floating render origin last rebased, so the same spot can be fine one session
    -- and broken the next). The old "y is shared" assumption made every ground ray read floors
    -- ~offset metres wrong = landing inside the ground / taking off above it. The offset is
    -- scene-global, so read it off the player, cached for a tick.
    local now = os.clock()
    if now - (tonumber(S._yoff_clock) or -1.0) < 0.1 then return tonumber(S._yoff_cache) or 0.0 end
    S._yoff_clock = now
    pcall(function()
        local pgo = char_go(get_player())
        local u = pgo and transform_pos(pgo)
        local r = pgo and transform_render_pos(pgo)
        local uy, ry = u and tonumber(u.y), r and tonumber(r.y)
        if uy and ry then S._yoff_cache = uy - ry end
    end)
    return tonumber(S._yoff_cache) or 0.0
end

function route3_cast_ground_below(x, y, z, up, down)
    -- like route3_cast_ground_ray but returns the highest contact that is NOT
    -- overhead: a long upward reach otherwise reports tree canopies as "ground"
    -- and clamps the griffin onto treetops.
    -- CONTRACT: x/z arrive RENDER space; y arrives UNIVERSAL and the returned contact's y is
    -- UNIVERSAL. The ray itself runs fully in RENDER space -- route3_y_space_offset converts.
    if not route3_ensure_ray() then return nil end
    local yoff = route3_y_space_offset()
    local ry = (tonumber(y) or 0.0) - yoff        -- universal in -> render for the ray
    local best, best_y = nil, nil
    pcall(function()
        route3_ray.filter:set_Group(0)
        route3_ray.filter:set_Layer(2)
        route3_ray.filter:set_MaskBits(0)
        route3_ray.result:clear()
        route3_ray.query:call(
            "setRay(via.vec3, via.vec3)",
            make_vec3(x, ry + (tonumber(up) or 60.0), z),
            make_vec3(x, ry - (tonumber(down) or 120.0), z)
        )
        route3_ray.method:call(route3_ray.system, route3_ray.query, route3_ray.result)
        local count = route3_ray.result:get_NumContactPoints() or 0
        for i = 0, count - 1 do
            local contact = route3_ray.result:call("getContactPoint(System.UInt32)", i)
            local p = contact and sdk.get_native_field(contact, route3_ray.contact_td, "Position") or nil
            local py = p and tonumber(p.y)
            if py and py <= ry + 1.0 then
                if (not best_y) or py > best_y then best, best_y = p, py end
            end
        end
    end)
    if not best then return nil end
    -- render contact -> universal out (offset 0 = exactly the old behavior)
    return { x = tonumber(best.x), y = (best_y or 0.0) + yoff, z = tonumber(best.z) }
end

-- ⭐⭐ FULLY-UNIVERSAL ground cast (07-25). route3_cast_ground_below takes RENDER x/z (it converts
-- only Y), but almost every caller outside the ray code holds UNIVERSAL coords -- transform_pos is
-- get_UniversalPosition, and IrisTaming is universal throughout. Feeding universal x/z to a render
-- ray casts it somewhere else in the world entirely, and the failure is SILENT and two-faced: it
-- either finds nothing (nil -- the `float=-1.00m` sentinel) or, worse, hits unrelated terrain and
-- reports a bogus floor. The latter is what sent her climbing: the ferry's terrain-follow read a
-- "floor" from a hill elsewhere on the map and chased `floor_y + clearance` upward forever, roaring
-- (the stall re-seize's ThreatAir) once per stalled window as it went.
-- ⛔ The offset is NOT constant -- it moves whenever the floating render origin rebases -- so it
-- must be sampled live, not cached across sessions. Take it off the player, readable in both spaces.
function route3_ground_below_uni(x, y, z, up, down)
    local dx, dz = 0.0, 0.0
    pcall(function()
        local pgo = char_go(get_player())
        if not pgo then return end
        local u, r = transform_pos(pgo), transform_render_pos(pgo)
        if not (u and r) then return end
        dx = (tonumber(u.x) or 0.0) - (tonumber(r.x) or 0.0)
        dz = (tonumber(u.z) or 0.0) - (tonumber(r.z) or 0.0)
    end)
    local hit = route3_cast_ground_below((tonumber(x) or 0.0) - dx, y, (tonumber(z) or 0.0) - dz, up, down)
    if hit then
        hit.x = (tonumber(hit.x) or 0.0) + dx
        hit.z = (tonumber(hit.z) or 0.0) + dz
    end
    return hit
end

local function make_quat_yaw(yaw)
    local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
    q.x = 0
    q.y = math.sin(yaw / 2.0)
    q.z = 0
    q.w = math.cos(yaw / 2.0)
    return q
end

local function make_quat_yaw_pitch_roll(yaw, pitch, roll)
    -- q = yaw(Y) * pitch(X) * roll(Z). Zero pitch/roll is exactly make_quat_yaw.
    local hy, hp, hr = (tonumber(yaw) or 0.0) * 0.5,
        (tonumber(pitch) or 0.0) * 0.5, (tonumber(roll) or 0.0) * 0.5
    local cy, sy = math.cos(hy), math.sin(hy)
    local cp, sp = math.cos(hp), math.sin(hp)
    local cr, sr = math.cos(hr), math.sin(hr)
    local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
    q.x = cy * sp * cr + sy * cp * sr
    q.y = -cy * sp * sr + sy * cp * cr
    q.z = cy * cp * sr - sy * sp * cr
    q.w = cy * cp * cr + sy * sp * sr
    return q
end

local function make_quat_identity()
    local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
    q.x = 0
    q.y = 0
    q.z = 0
    q.w = 1
    return q
end

function griffin_make_quat_raw(x, y, z, w)
    local ok, q = pcall(function() return Quaternion.new(x, y, z, w) end)
    if ok and q then return q end
    q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
    q.x = x
    q.y = y
    q.z = z
    q.w = w
    return q
end

function griffin_q_axis_angle(ax, ay, az, deg)
    local r = math.rad(tonumber(deg) or 0.0) * 0.5
    local s = math.sin(r)
    return ax * s, ay * s, az * s, math.cos(r)
end

function griffin_q_mul(ax, ay, az, aw, bx, by, bz, bw)
    return aw * bx + ax * bw + ay * bz - az * by,
           aw * by - ax * bz + ay * bw + az * bx,
           aw * bz + ax * by - ay * bx + az * bw,
           aw * bw - ax * bx - ay * by - az * bz
end

function griffin_q_normalize(x, y, z, w)
    local len = math.sqrt(x * x + y * y + z * z + w * w)
    if len <= 0.0001 then return 0.0, 0.0, 0.0, 1.0 end
    return x / len, y / len, z / len, w / len
end

function griffin_q_read(q)
    if not q then return 0.0, 0.0, 0.0, 1.0 end
    local x, y, z, w = 0.0, 0.0, 0.0, 1.0
    pcall(function() x, y, z, w = q.x, q.y, q.z, q.w end)
    return x, y, z, w
end

function griffin_q_table_mul(a, b)
    if not (a and b) then return { x = 0.0, y = 0.0, z = 0.0, w = 1.0 } end
    local x, y, z, w = griffin_q_mul(
        tonumber(a.x) or 0.0, tonumber(a.y) or 0.0, tonumber(a.z) or 0.0, tonumber(a.w) or 1.0,
        tonumber(b.x) or 0.0, tonumber(b.y) or 0.0, tonumber(b.z) or 0.0, tonumber(b.w) or 1.0
    )
    x, y, z, w = griffin_q_normalize(x, y, z, w)
    return { x = x, y = y, z = z, w = w }
end

function griffin_q_rotate_vec(q, v)
    -- v' = v + 2*w*(q_xyz x v) + 2*(q_xyz x (q_xyz x v)); accepts any {x,y,z}-likes
    local qx = tonumber(q.x) or 0.0
    local qy = tonumber(q.y) or 0.0
    local qz = tonumber(q.z) or 0.0
    local qw = tonumber(q.w) or 1.0
    local vx = tonumber(v.x) or 0.0
    local vy = tonumber(v.y) or 0.0
    local vz = tonumber(v.z) or 0.0
    local tx = 2.0 * (qy * vz - qz * vy)
    local ty = 2.0 * (qz * vx - qx * vz)
    local tz = 2.0 * (qx * vy - qy * vx)
    return {
        x = vx + qw * tx + (qy * tz - qz * ty),
        y = vy + qw * ty + (qz * tx - qx * tz),
        z = vz + qw * tz + (qx * ty - qy * tx),
    }
end

-- 3x3 matrix kit for the saddle weld (row-major, m[row][col]). Joint get_Rotation LIED on the
-- griffin rig (rider rendered upside down), so the saddle frame is built from JOINT POSITIONS
-- only -- the truth channel (wilds pipeline law: helper orientations lie, positions are truth).
function griffin_m3_mul(a, b)
    local m = { {}, {}, {} }
    for i = 1, 3 do for j = 1, 3 do
        m[i][j] = a[i][1] * b[1][j] + a[i][2] * b[2][j] + a[i][3] * b[3][j]
    end end
    return m
end

function griffin_m3_mulv(m, v)
    return {
        x = m[1][1] * v.x + m[1][2] * v.y + m[1][3] * v.z,
        y = m[2][1] * v.x + m[2][2] * v.y + m[2][3] * v.z,
        z = m[3][1] * v.x + m[3][2] * v.y + m[3][3] * v.z,
    }
end

function griffin_m3_tmulv(m, v)   -- transpose(m) * v  (world -> saddle-local)
    return {
        x = m[1][1] * v.x + m[2][1] * v.y + m[3][1] * v.z,
        y = m[1][2] * v.x + m[2][2] * v.y + m[3][2] * v.z,
        z = m[1][3] * v.x + m[2][3] * v.y + m[3][3] * v.z,
    }
end


function griffin_m3_ypr(yaw, pitch, roll)
    -- Ry(yaw) @ Rx(pitch) @ Rz(roll) -- same order as make_quat_yaw_pitch_roll
    local cy, sy = math.cos(yaw or 0.0), math.sin(yaw or 0.0)
    local cx, sx = math.cos(pitch or 0.0), math.sin(pitch or 0.0)
    local cz, sz = math.cos(roll or 0.0), math.sin(roll or 0.0)
    local Ry = { { cy, 0, sy }, { 0, 1, 0 }, { -sy, 0, cy } }
    local Rx = { { 1, 0, 0 }, { 0, cx, -sx }, { 0, sx, cx } }
    local Rz = { { cz, -sz, 0 }, { sz, cz, 0 }, { 0, 0, 1 } }
    return griffin_m3_mul(Ry, griffin_m3_mul(Rx, Rz))
end

function griffin_m3_to_quat(m)
    -- Shepperd's method; matches make_quat_yaw for a pure-yaw matrix (verified by hand).
    local t = m[1][1] + m[2][2] + m[3][3]
    local x, y, z, w
    if t > 0.0 then
        local s = math.sqrt(t + 1.0) * 2.0
        w = 0.25 * s
        x = (m[3][2] - m[2][3]) / s
        y = (m[1][3] - m[3][1]) / s
        z = (m[2][1] - m[1][2]) / s
    elseif m[1][1] > m[2][2] and m[1][1] > m[3][3] then
        local s = math.sqrt(1.0 + m[1][1] - m[2][2] - m[3][3]) * 2.0
        w = (m[3][2] - m[2][3]) / s
        x = 0.25 * s
        y = (m[1][2] + m[2][1]) / s
        z = (m[1][3] + m[3][1]) / s
    elseif m[2][2] > m[3][3] then
        local s = math.sqrt(1.0 + m[2][2] - m[1][1] - m[3][3]) * 2.0
        w = (m[1][3] - m[3][1]) / s
        x = (m[1][2] + m[2][1]) / s
        y = 0.25 * s
        z = (m[2][3] + m[3][2]) / s
    else
        local s = math.sqrt(1.0 + m[3][3] - m[1][1] - m[2][2]) * 2.0
        w = (m[2][1] - m[1][2]) / s
        x = (m[1][3] + m[3][1]) / s
        y = (m[2][3] + m[3][2]) / s
        z = 0.25 * s
    end
    x, y, z, w = griffin_q_normalize(x, y, z, w)
    return griffin_make_quat_raw(x, y, z, w)
end


function griffin_q_nlerp(a, b, f)
    if not a then return b end
    if not b then return a end
    f = math.min(1.0, math.max(0.0, tonumber(f) or 0.0))
    local ax, ay, az, aw = tonumber(a.x) or 0.0, tonumber(a.y) or 0.0, tonumber(a.z) or 0.0, tonumber(a.w) or 1.0
    local bx, by, bz, bw = tonumber(b.x) or 0.0, tonumber(b.y) or 0.0, tonumber(b.z) or 0.0, tonumber(b.w) or 1.0
    -- take the short way round: same rotation has two quat signs
    if ax * bx + ay * by + az * bz + aw * bw < 0.0 then
        bx, by, bz, bw = -bx, -by, -bz, -bw
    end
    local x = ax + (bx - ax) * f
    local y = ay + (by - ay) * f
    local z = az + (bz - az) * f
    local w = aw + (bw - aw) * f
    x, y, z, w = griffin_q_normalize(x, y, z, w)
    return { x = x, y = y, z = z, w = w }
end

local function yaw_from_transform(go)
    local yaw = nil
    pcall(function()
        local fwd = go and go:call("get_Transform"):call("get_AxisZ")
        if fwd then yaw = math.atan(fwd.x, fwd.z) end
    end)
    return yaw
end

local function wrap_angle(a)
    while a > math.pi do a = a - math.pi * 2.0 end
    while a < -math.pi do a = a + math.pi * 2.0 end
    return a
end

local function clamp_drive_delta(dx, dy, dz, max_step)
    local max_len = tonumber(max_step) or 0
    if max_len <= 0 then return dx, dy, dz end
    local len = math.sqrt(dx * dx + dy * dy + dz * dz)
    if len <= max_len or len <= 0.0001 then return dx, dy, dz end
    local scale = max_len / len
    return dx * scale, dy * scale, dz * scale
end

local function set_transform(go, pos, rot)
    if not (go and pos and sane_position(pos)) then return false end
    local ok = false
    -- TXI ours-flag (round-47): while the seat-rewrite intercept is live, every write
    -- that flows through this helper is BY DEFINITION ours -- flag it so the intercept
    -- hooks pass it through. Nesting-safe (only the outermost setter clears) and set
    -- OUTSIDE the pcall so an engine error can't leave it latched.
    local txi_flag = (S.route3_txi_live == true and S.route3_our_write ~= true)
    if txi_flag then S.route3_our_write = true end
    ok = pcall(function()
        local tf = go:call("get_Transform")
        tf:call("set_UniversalPosition", pos)
        if rot then tf:call("set_Rotation", rot) end
    end) or ok
    if txi_flag then S.route3_our_write = false end
    return ok
end

local function set_character_transform(ch, pos, rot)
    if not (ch and pos and sane_position(pos)) then return false end
    local ok = false
    local txi_flag = (S.route3_txi_live == true and S.route3_our_write ~= true)
    if txi_flag then S.route3_our_write = true end
    pcall(function()
        local tf = ch:call("get_Transform")
        if tf then
            ok = set_transform({ call = function(_, name) if name == "get_Transform" then return tf end end }, pos, rot) or ok
        end
    end)
    pcall(function() ch:call("set_UniversalPosition", pos); ok = true end)
    if rot then
        pcall(function() ch:call("set_Rotation", rot); ok = true end)
    end
    if txi_flag then S.route3_our_write = false end
    return ok
end

local function set_object_rotation_only(go, rot)
    if not (go and rot) then return false end
    local ok = false
    pcall(function()
        local tf = go:call("get_Transform")
        if tf then
            tf:call("set_Rotation", rot)
            ok = true
        end
    end)
    return ok
end

local function set_character_rotation_only(ch, rot)
    if not (ch and rot) then return false end
    local ok = false
    pcall(function() ch:call("set_Rotation", rot); ok = true end)
    local go = char_go(ch)
    if go then ok = set_object_rotation_only(go, rot) or ok end
    return ok
end

local function apply_griffin_transform(pos, rot)
    local ch, go = reacquire_griffin()
    local ok = false
    if go then ok = set_transform(go, pos, rot) or ok end
    if C.write_griffin_character_transform and ch then ok = set_character_transform(ch, pos, rot) or ok end
    S.last_griffin_set_ok = ok
    return ok
end

-- Pin the drive architecture at the moment a ride begins.
--
-- These flags choose which backend owns her body, and a saved config must never get a vote:
-- a json carried over from an old experiment (or a dev-UI toggle left flipped) would silently
-- hand the ride to a backend the flight path was never built against. Both mount routes -- the
-- proxy saddle and the parented seat -- call this, so there is exactly one place that decides.
--
-- "rootmove" is the pin that matters: it is what makes native_climb_uses_root_move() true and
-- every other drive-mode predicate false, so route3's transform drive is the sole position writer.
local function arm_ride_drive()
    C.drive_enabled = true
    C.require_native_climb_for_drive = false
    C.native_climb_drive_mode = "rootmove"
    C.character_root_move_enabled = false
    C.root_motion_enabled = false   -- root motion would fight the transform drive for locomotion
end

local function drive_writes_griffin_transform()
    local mode = tostring(C.native_climb_drive_mode or "")
    return C.drive_griffin_transform == true
        or (S.native_climb_mount == true and C.native_climb_drive_griffin_transform == true and mode == "transform")
end

local function native_climb_uses_nav_drive()
    return S.native_climb_mount == true and tostring(C.native_climb_drive_mode or "") == "nav" and C.native_climb_enable_dangerous_nav_tests == true
end

local function native_climb_uses_flight_control()
    local mode = tostring(C.native_climb_drive_mode or ""):lower()
    return S.native_climb_mount == true and (mode == "flightcontrol" or mode == "flight_control" or mode == "fc")
end

local function native_climb_uses_root_move()
    local mode = tostring(C.native_climb_drive_mode or ""):lower()
    return S.native_climb_mount == true and (mode == "rootmove" or mode == "root_move" or mode == "root")
end

local function native_climb_uses_calm_drive()
    local mode = tostring(C.native_climb_drive_mode or "")
    return S.native_climb_mount == true and (mode == "calm" or (mode == "nav" and C.native_climb_enable_dangerous_nav_tests ~= true))
end

local function nav_pulse_active(now)
    return S.native_climb_mount == true and (tonumber(S.nav_pulse_until_clock) or 0.0) > (now or os.clock())
end

local function apply_rider_transform(pos, rot)
    local player = get_player()
    local pgo = char_go(player)
    local ok = false
    if pgo then ok = set_transform(pgo, pos, rot) or ok end
    if C.write_rider_character_transform and player then ok = set_character_transform(player, pos, rot) or ok end
    S.last_rider_set_ok = ok
    return ok
end

local function distance_sq(a, b)
    if not (a and b) then return nil end
    local dx = (tonumber(a.x) or 0) - (tonumber(b.x) or 0)
    local dy = (tonumber(a.y) or 0) - (tonumber(b.y) or 0)
    local dz = (tonumber(a.z) or 0) - (tonumber(b.z) or 0)
    return dx * dx + dy * dy + dz * dz
end

local function flat_axis_from_vec(v, fallback_x, fallback_z)
    local x = v and tonumber(v.x) or fallback_x or 0.0
    local z = v and tonumber(v.z) or fallback_z or 0.0
    local len = math.sqrt(x * x + z * z)
    if len <= 0.0001 then return { x = fallback_x or 0.0, y = 0.0, z = fallback_z or 1.0 } end
    return { x = x / len, y = 0.0, z = z / len }
end

local function transform_flat_axes(go, fallback_yaw)
    local axis_x, axis_z = nil, nil
    pcall(function()
        local tf = go and go:call("get_Transform")
        axis_x = tf and tf:call("get_AxisX")
        axis_z = tf and tf:call("get_AxisZ")
    end)
    local yaw = fallback_yaw or 0.0
    local fallback_fwd_x, fallback_fwd_z = math.sin(yaw), math.cos(yaw)
    local fallback_right_x, fallback_right_z = math.cos(yaw), -math.sin(yaw)
    return flat_axis_from_vec(axis_z, fallback_fwd_x, fallback_fwd_z),
        flat_axis_from_vec(axis_x, fallback_right_x, fallback_right_z)
end

local function same_obj(a, b)
    if not (a and b) then return false end
    local aa, bb = nil, nil
    pcall(function() aa = a:get_address() end)
    pcall(function() bb = b:get_address() end)
    return aa ~= nil and bb ~= nil and aa == bb
end

local function player_front(distance)
    local pgo = char_go(get_player())
    if not pgo then return nil, nil end
    local pos, rot = nil, nil
    pcall(function()
        local tf = pgo:call("get_Transform")
        local pp = tf:call("get_UniversalPosition")
        local fwd = tf:call("get_AxisZ")
        rot = tf:call("get_Rotation")
        pos = make_position(
            pp.x + (fwd and fwd.x or 0) * (distance or 6.0),
            pp.y + 0.2,
            pp.z + (fwd and fwd.z or 0) * (distance or 6.0)
        )
    end)
    return pos, rot
end

-- Find a close, level-enough patch of real collision floor for a stable
-- companion. A single centre ray is not sufficient: it happily accepts the
-- last few centimetres of a cliff, leaving most of a large creature over air.
-- Sample the footprint and refuse the placement unless every point agrees.
function route3_find_safe_stable_spawn(distance)
    local pgo = char_go(get_player())
    local ppos = pgo and transform_pos(pgo)
    local prp = pgo and transform_render_pos(pgo)
    if not (pgo and ppos and prp) then return nil, nil, "no positioned player" end

    local yaw = yaw_from_transform(pgo) or 0.0
    local preferred = math.max(3.5, math.min(
        tonumber(C.route3_stable_spawn_max_distance) or 10.0,
        tonumber(distance) or tonumber(C.route3_stable_spawn_distance) or 5.5))
    local max_dist = math.max(preferred, tonumber(C.route3_stable_spawn_max_distance) or 10.0)
    local footprint = math.max(0.5, tonumber(C.route3_stable_spawn_footprint) or 1.6)
    local max_surface = math.max(0.2, tonumber(C.route3_stable_spawn_max_surface_delta) or 1.2)
    local max_height = math.max(1.0, tonumber(C.route3_stable_spawn_max_height_delta) or 3.5)
    local cast_up = math.max(2.0, tonumber(C.route3_stable_spawn_ground_up) or 8.0)
    local cast_down = math.max(10.0, tonumber(C.route3_stable_spawn_ground_down) or 80.0)
    local offset = tonumber(C.route3_stable_spawn_ground_offset) or 0.15

    local player_hit = route3_cast_ground_below(
        tonumber(prp.x) or 0.0,
        (tonumber(ppos.y) or 0.0) + 1.0,
        tonumber(prp.z) or 0.0,
        cast_up,
        cast_down)
    local player_ground = tonumber(player_hit and player_hit.y) or tonumber(ppos.y) or 0.0
    local reference_y = player_ground + max_height + 0.25

    local rings, ring_seen = {}, {}
    local function add_ring(v)
        v = math.max(3.5, math.min(max_dist, tonumber(v) or preferred))
        local key = string.format("%.2f", v)
        if not ring_seen[key] then ring_seen[key] = true; rings[#rings + 1] = v end
    end
    add_ring(preferred)
    add_ring(preferred - 1.5)
    add_ring(preferred + 2.0)
    add_ring(max_dist)

    -- Front first, then fan around the player. Back is deliberately last.
    local angles = { 0.0, -math.pi / 4.0, math.pi / 4.0, -math.pi / 2.0,
        math.pi / 2.0, -3.0 * math.pi / 4.0, 3.0 * math.pi / 4.0, math.pi }
    local samples = {
        { footprint, 0.0 }, { -footprint, 0.0 },
        { 0.0, footprint }, { 0.0, -footprint },
    }
    local tested = 0
    for _, radius in ipairs(rings) do
        for _, angle in ipairs(angles) do
            tested = tested + 1
            local a = yaw + angle
            local ux = (tonumber(ppos.x) or 0.0) + math.sin(a) * radius
            local uz = (tonumber(ppos.z) or 0.0) + math.cos(a) * radius
            local rx = (tonumber(prp.x) or 0.0) + ux - (tonumber(ppos.x) or 0.0)
            local rz = (tonumber(prp.z) or 0.0) + uz - (tonumber(ppos.z) or 0.0)
            local centre = route3_cast_ground_below(rx, reference_y, rz, cast_up, cast_down)
            local cy = tonumber(centre and centre.y)
            if cy and math.abs(cy - player_ground) <= max_height then
                local min_y, max_y, valid = cy, cy, true
                for _, sample in ipairs(samples) do
                    local hit = route3_cast_ground_below(
                        rx + sample[1], reference_y, rz + sample[2], cast_up, cast_down)
                    local sy = tonumber(hit and hit.y)
                    if not sy then valid = false; break end
                    min_y = math.min(min_y, sy)
                    max_y = math.max(max_y, sy)
                    if math.abs(sy - cy) > max_surface then valid = false; break end
                end
                if valid and (max_y - min_y) <= max_surface then
                    local face_player = make_quat_yaw(wrap_angle(a + math.pi))
                    local pos = make_position(ux, cy + offset, uz)
                    local detail = string.format("safe floor %.1fm away, spread %.2fm", radius, max_y - min_y)
                    S.route3_stable_spawn_status = detail
                    return pos, face_player, detail
                end
            end
        end
    end
    local detail = string.format("no safe floor in %d sampled spots", tested)
    S.route3_stable_spawn_status = detail
    return nil, nil, detail
end

local function is_dead(ch)
    local dead = false
    pcall(function() dead = ch and ch:call("get_IsDead") == true end)
    if dead then return true end
    pcall(function()
        local hp = ch and ch:call("get_Hp")
        if hp ~= nil and tonumber(hp) <= 0 then dead = true end
    end)
    return dead
end

local function is_player_or_party(ch)
    if not ch then return false end
    if same_obj(ch, get_player()) then return true end
    local ok = false
    pcall(function()
        local human = ch:get_field("<Human>k__BackingField")
        ok = human and human:call("isPlayerOrPartyPawn") == true
    end)
    if ok then return true end

    local pm = singleton("app.PawnManager")
    if not pm then return false end
    for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
        local list = nil
        pcall(function() list = pm:call(getter) end)
        local n = 0
        pcall(function() n = list and list:call("get_Count") or 0 end)
        for i = 0, (tonumber(n) or 0) - 1 do
            local item = nil
            pcall(function() item = list:call("get_Item", i) end)
            if same_obj(ch, item) then return true end
        end
    end
    return false
end

local function set_enabled(obj, enabled)
    if not obj then return false end
    local ok = pcall(function() obj:call("set_Enabled", enabled) end)
    if not ok then ok = pcall(function() obj:call("set_Enabled(System.Boolean)", enabled) end) end
    return ok
end

local function disable_record(obj, label)
    if not obj or S.disabled[obj] then return false end
    local was = true
    pcall(function()
        local v = obj:call("get_Enabled")
        if type(v) == "boolean" then was = v end
    end)
    if set_enabled(obj, false) then
        S.disabled[obj] = { obj = obj, label = label or "?", was = was }
        return true
    end
    return false
end

local function disable_rider_record(obj, label)
    if not obj or S.rider_disabled[obj] then return false end
    local was = true
    pcall(function()
        local v = obj:call("get_Enabled")
        if type(v) == "boolean" then was = v end
    end)
    if set_enabled(obj, false) then
        S.rider_disabled[obj] = { obj = obj, label = label or "?", was = was }
        return true
    end
    return false
end

restore_disabled = function()
    for obj, rec in pairs(S.disabled) do
        if rec and rec.was ~= false then set_enabled(obj, true) end
        S.disabled[obj] = nil
    end
end

local function restore_rider_disabled()
    for obj, rec in pairs(S.rider_disabled) do
        if rec and rec.was ~= false then set_enabled(obj, true) end
        S.rider_disabled[obj] = nil
    end
end

local function method_exists(obj, name)
    local td = nil
    pcall(function() td = obj and obj:get_type_definition() end)
    local method = nil
    pcall(function() method = td and td:get_method(name) end)
    return method
end

local function table_count(t)
    local n = 0
    for _ in pairs(t or {}) do n = n + 1 end
    return n
end

local function set_think_stop(ch, enabled)
    if not ch then return false end
    local ok = false
    local td = nil
    pcall(function() td = ch:get_type_definition() end)

    local function set_field_if_exists(name)
        local field = nil
        pcall(function() field = td and td:get_field(name) end)
        if field then
            ok = pcall(function() ch:set_field(name, enabled == true) end) or ok
        end
    end

    local function call_method_if_exists(name)
        local method = nil
        pcall(function() method = td and td:get_method(name) end)
        if method then
            ok = pcall(function() method:call(ch, enabled == true) end) or ok
        end
    end

    set_field_if_exists("_IsThinkStop")
    set_field_if_exists("<IsThinkStop>k__BackingField")
    call_method_if_exists("set_IsThinkStop(System.Boolean)")
    call_method_if_exists("set_IsThinkStop")
    return ok
end

local function name_matches_csv(name, csv)
    local lo = tostring(name or ""):lower()
    for raw in tostring(csv or ""):gmatch("[^,]+") do
        local pat = raw:gsub("^%s+", ""):gsub("%s+$", ""):lower()
        if pat ~= "" and lo:find(pat, 1, true) then return true end
    end
    return false
end

local function set_rider_hard_lock(enabled)
    local player = get_player()
    if not player then return false end
    local on = enabled == true and C.hard_lock_rider == true

    if C.freeze_rider then set_think_stop(player, on) end

    if C.disable_rider_fsm or S.rider_fsm_locked then
        local fsm = nil
        pcall(function()
            local human = player:call("get_Human")
            fsm = human and human.Fsm
        end)
        if fsm and on and not S.rider_fsm_locked then
            pcall(function() fsm:set_Enabled(false) end)
            S.rider_fsm_locked = true
        elseif fsm and (not on) and S.rider_fsm_locked then
            pcall(function() fsm:set_Enabled(true) end)
            S.rider_fsm_locked = false
        end
    end

    if C.disable_rider_controller or S.rider_controller_locked then
        if on and not S.rider_controller_locked then
            local m = method_exists(player, "setCharacterControllerEnable(System.Boolean)") or method_exists(player, "setCharacterControllerEnable")
            if m then pcall(function() m:call(player, false) end) end
            S.rider_controller_locked = true
        elseif (not on) and S.rider_controller_locked then
            local m = method_exists(player, "setCharacterControllerEnable(System.Boolean)") or method_exists(player, "setCharacterControllerEnable")
            if m then pcall(function() m:call(player, true) end) end
            S.rider_controller_locked = false
        end
    end

    if on then
        local pgo = char_go(player)
        pcall(function()
            local comps = pgo and pgo:call("get_Components")
            for _, c in ipairs(system_array_to_table(comps)) do
                local td = c and c:get_type_definition()
                local full = td and td:get_full_name() or ""
                local short = full:match("([^%.]+)$") or full
                if name_matches_csv(full, C.rider_disable_components) or name_matches_csv(short, C.rider_disable_components) then
                    disable_rider_record(c, full)
                end
            end
        end)
    else
        restore_rider_disabled()
    end
    return true
end

local function call_bool_methods(obj, value, names)
    if not obj then return false end
    local any = false
    for _, name in ipairs(names or {}) do
        local ok = false
        pcall(function() obj:call(name, value); ok = true end)
        if not ok then pcall(function() obj[name](obj, value); ok = true end) end
        if ok then any = true end
    end
    return any
end

local function call_noarg_methods(obj, names)
    if not obj then return false end
    local any = false
    for _, name in ipairs(names or {}) do
        local ok = false
        pcall(function() obj:call(name); ok = true end)
        if not ok then pcall(function() obj[name](obj); ok = true end) end
        if ok then any = true end
    end
    return any
end

local function get_climb_ctrl(ch)
    local ctrl = nil
    pcall(function() ctrl = ch and ch:call("get_ClimbCtrl") end)
    if not ctrl then pcall(function() ctrl = ch and ch:get_ClimbCtrl() end) end
    return ctrl
end

local function set_character_controller_enabled(ch, enabled)
    if not ch then return false end
    local ok = false
    pcall(function() ch:call("setCharacterControllerEnable", enabled == true); ok = true end)
    if not ok then pcall(function() ch:call("setCharacterControllerEnable(System.Boolean)", enabled == true); ok = true end) end
    return ok
end

local function suppress_climb_motion_tick(player, suppress)
    if not player then return false end
    local any = false
    if suppress then
        any = call_noarg_methods(player, {
            "notifyStopClimbMovingOnCh259Spike",
            "disableNextRootInterpolationOnAbortClimb",
        }) or any
        any = call_bool_methods(player, true, {
            "set_IsPrevStopClimbMovingOnCh259Spike",
        }) or any
    else
        any = call_bool_methods(player, false, {
            "set_IsPrevStopClimbMovingOnCh259Spike",
        }) or any
    end

    local ctrl = get_climb_ctrl(player)
    if ctrl then
        any = call_bool_methods(ctrl, not suppress, {
            "set_Enabled",
            "setEnable",
            "set_Enable",
            "set_IsEnable",
            "set_IsActive",
            "set_InputEnable",
            "set_EnableInput",
            "set_MoveEnable",
            "set_EnableMove",
            "set_IsMoveEnable",
        }) or any
        if suppress then
            any = call_bool_methods(ctrl, true, {
                "set_IsStop",
                "set_Stop",
                "set_IsPause",
                "set_Pause",
            }) or any
            any = call_noarg_methods(ctrl, {
                "stop",
                "stopMove",
                "stopMoving",
                "notifyStopClimbMovingOnCh259Spike",
            }) or any
        else
            any = call_bool_methods(ctrl, false, {
                "set_IsStop",
                "set_Stop",
                "set_IsPause",
                "set_Pause",
            }) or any
        end
    end
    return any
end

-- Stop voluntary crawling without stopping the attachment solver.  ClimbCtrl is not merely an
-- input controller: its follower is the native parent that rebases the rider as a climbed monster
-- moves.  The old generic suppressor disabled/paused that entire component every frame.  Dogfight
-- then translated the griffin tens of metres while the follower's private anchor remained stale;
-- LoopTheLoop exposed the resulting logical/visual split and the camera correctly followed the
-- displaced player.  These are the same three movement writes used by the proven pawn seat path.
local function hold_native_climb_position_tick(player)
    local ctrl = get_climb_ctrl(player)
    if not ctrl then return false end
    local any = false
    pcall(function() ctrl:call("set_IsClimbMoving", false); any = true end)
    pcall(function() ctrl:call("set_ClimbMotionSpeed", 0.0); any = true end)
    pcall(function() ctrl:call("set_ClimbMoveAngleDeg", 0.0); any = true end)
    return any
end

local function set_native_rider_suppressed(enabled)
    local player = get_player()
    if not player then return false end
    local on = enabled == true
    local ok = set_think_stop(player, on)

    if C.native_climb_suppress_controller or S.native_rider_controller_suppressed then
        if on and not S.native_rider_controller_suppressed then
            ok = set_character_controller_enabled(player, false) or ok
            S.native_rider_controller_suppressed = true
        elseif (not on) and S.native_rider_controller_suppressed then
            ok = set_character_controller_enabled(player, true) or ok
            S.native_rider_controller_suppressed = false
        end
    end

    if C.native_climb_suppress_climb_ctrl == true then
        ok = suppress_climb_motion_tick(player, on) or ok
        S.native_climb_ctrl_suppressed = on
    elseif S.native_climb_ctrl_suppressed == true then
        -- Hot-reload recovery from builds which already disabled the follower this ride.
        ok = suppress_climb_motion_tick(player, false) or ok
        S.native_climb_ctrl_suppressed = false
    end

    if on and C.native_climb_stop_move_each_tick then
        ok = hold_native_climb_position_tick(player) or ok
    end

    S.native_rider_suppressed = on
    if on then
        S.native_suppress_hits = S.native_suppress_hits + 1
        S.native_suppress_last = ok and "ok" or "no method took"
    else
        S.native_suppress_last = "released"
    end
    return ok
end

