    if not nav then nav = get_component(char_go(ch), "app.NavigationAI") end
    if not nav then return false end

    local ok = false
    local td = nil
    pcall(function() td = nav:get_type_definition() end)

    local function call_method_if_exists(name)
        local method = nil
        pcall(function() method = td and td:get_method(name) end)
        if method then
            ok = pcall(function() method:call(nav, stop == true) end) or ok
        end
    end

    local function set_field_if_exists(name)
        local field = nil
        pcall(function() field = td and td:get_field(name) end)
        if field then
            ok = pcall(function() nav:set_field(name, stop == true) end) or ok
        end
    end

    call_method_if_exists("set_IsStopCalled(System.Boolean)")
    call_method_if_exists("set_IsStopCalled")
    call_method_if_exists("set_isStopCalled(System.Boolean)")
    call_method_if_exists("set_isStopCalled")
    set_field_if_exists("IsStopCalled")
    set_field_if_exists("_IsStopCalled")
    set_field_if_exists("<IsStopCalled>k__BackingField")
    set_field_if_exists("isStopCalled")
    set_field_if_exists("_isStopCalled")
    return ok
end

