-- ==== NICK-BORROW: app.ActionInterface (2026-07-26) ====
-- SAFETY FIRST: we do not know that app.ActionInterface is a separate object from
-- app.ActionManager -- and killing ActionManager would kill every requestActionCore
-- the whole flight drive is built on. So the first thing this does is compare the two
-- addresses ONCE and REFUSE to touch it if they are the same object. Verdict is cached
-- in S so the diag panel can show it and we never re-pay the lookup.
local function griffin_action_interface_apply(go, on)
    if not go then return false end
    local ai = get_component(go, "app.ActionInterface")
    if not ai then
        S.griffin_action_interface_status = "no app.ActionInterface on this GO"
        return false
    end
    if S.griffin_action_interface_same == nil then
        local ai_addr, am_addr = nil, nil
        pcall(function() ai_addr = ai:get_address() end)
        pcall(function()
            local am = get_component(go, "app.ActionManager")
            if am then am_addr = am:get_address() end
        end)
        S.griffin_action_interface_same = (ai_addr ~= nil and ai_addr == am_addr)
        S.griffin_action_interface_addr = string.format("AI=%s AM=%s",
            ai_addr and string.format("%X", ai_addr) or "?",
            am_addr and string.format("%X", am_addr) or "?")
    end
    if S.griffin_action_interface_same == true then
        S.griffin_action_interface_status =
            "REFUSED: same object as ActionManager -- disabling it would kill the drive (" ..
            tostring(S.griffin_action_interface_addr) .. ")"
        return false
    end
    if on == true then
        -- disable_record early-returns when it is already in S.disabled, so calling this
        -- every tick is cheap AND self-healing: a catch's restore_disabled() wakes it back
        -- up (same failure mode griffin_predation_rearm_ride_suppression exists for) and
        -- the next tick puts it straight back down.
        local did = disable_record(ai, "app.ActionInterface")
        if did then
            S.griffin_action_interface_status = "DISABLED (" .. tostring(S.griffin_action_interface_addr) .. ")"
        end
        return did
    end
    -- Explicit re-enable. Must also drop the S.disabled record, otherwise a later
    -- restore_disabled() has nothing to do and the reconcile loses track of it.
    local rec = S.disabled[ai]
    if rec then
        if rec.was ~= false then set_enabled(ai, true) end
        S.disabled[ai] = nil
    else
        pcall(function() set_enabled(ai, true) end)
    end
    S.griffin_action_interface_status = "enabled (" .. tostring(S.griffin_action_interface_addr or "?") .. ")"
    return true
end

-- Single reconciler rather than sprinkling this next to all five AI-disable sites:
-- one place that decides, one place to rip out if it turns out to be H1.
-- Suspended during predation on purpose -- the catch runs on CatchController + the
-- action stack, so under H1 leaving this on would break the grab.
function griffin_action_interface_tick()
    -- ⛔⛔ HARD INTERLOCK (2026-07-26). This toggle was present in ALL THREE CTDs and was
    -- re-ticked by hand between tests, silently poisoning every fc-lift result. It is
    -- SUSPECTED HARMFUL and has already answered its own question (AI and AM are distinct
    -- objects; disabling it does NOT stop actions executing). So it is not allowed to be on
    -- at the same time as the fc-lift experiment -- an instruction not to tick it is not a
    -- control, this is.
    if C.disable_griffin_action_interface == true and C.route3_rise_fc_lift == true then
        C.disable_griffin_action_interface = false
        S.griffin_action_interface_status = "FORCED OFF: cannot be on during an FC-LIFT test (interlock)"
    end
    local want = (C.disable_griffin_action_interface == true)
        and (S.mounted == true)
        and not griffin_predation_window_active()
    if want then
        local _, go = reacquire_griffin()
        griffin_action_interface_apply(go, true)
        S.griffin_action_interface_on = true
    elseif S.griffin_action_interface_on == true then
        local _, go = reacquire_griffin()
        griffin_action_interface_apply(go, false)
        S.griffin_action_interface_on = false
        if C.disable_griffin_action_interface == true then
            S.griffin_action_interface_status = "suspended (predation/dismounted)"
        end
    end
end

local function set_griffin_puppet(enabled)
    -- ⛔ REMOVED 08-09: a Stage-1 gate here used to refuse puppeting while native-nav follow
    -- held a heartbeat. Native nav turned out not to drive a tamed monster at all (see the
    -- config note on route3_companion_native_follow), so the gate guarded nothing -- and
    -- set_griffin_puppet is on the RIDE path, where refusing to puppet mid-mount could leave
    -- the ride half-initialised. Not worth carrying a risk on the mount path for a disproven
    -- experiment, especially with a mount-time crash outstanding.
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    if enabled then
        set_think_stop(ch, false)
        stop_navigation(ch, true)
        set_motion_fsm_puppet(go, C.puppet_motion_fsm == true)
        if C.disable_griffin_ai then
            disable_record(get_component(go, "app.AIDecisionMaker"), "app.AIDecisionMaker")
            disable_record(get_component(go, "app.NavigationAI"), "app.NavigationAI")
        end
        clear_griffin_hate()
    else
        set_motion_fsm_puppet(go, false)
        restore_disabled()
        stop_navigation(ch, false)
        set_think_stop(ch, false)
        pcall(function() ch:call("resetActionAndAI") end)
    end
    return true
end

local function griffin_hate_system()
    local ch, go = reacquire_griffin()
    local hs = nil
    pcall(function() hs = ch and ch:call("get_HateSystem") end)
