    local hs = nil
    pcall(function() hs = ch and ch:call("get_HateSystem") end)
    if not hs then hs = get_component(go or char_go(ch), "app.HateSystem") end
    return hs
end

function clear_character_hate(ch, go)
    local hs = character_hate_system(ch, go)
    local ok = false
    if hs then pcall(function() hs:call("clearAllHate"); ok = true end) end
