end

clear_griffin_hate = function()
    local hs = griffin_hate_system()
    if hs then pcall(function() hs:call("clearAllHate") end) end
end

-- ⭐⭐ CIVILIAN HATE SHIELD (2026-08-08, Aurora: NPCs/stray pawns "keep running at the
-- griffin constantly and following me until I despawn it" -- her ground attacks register
-- her in bystanders' HATE lists as a combatant they can't legally hit, so they orbit her
-- forever). The party friend-shield's exact mechanism, extended to every NON-enemy
-- character within 50m: zero the hate RATE toward her + clear existing hate, every beat.
-- Enemies (ch2xx) are exempt -- they are SUPPOSED to hate her.
function griffin_civilian_hate_shield()
    if C.route3_civilian_hate_shield == false then return end
    if S.mounted ~= true then return end
    local now = os.clock()
    if now < (tonumber(S.route3_civshield_at) or 0.0) then return end
    S.route3_civshield_at = now + 1.5
    local _, ggo = reacquire_griffin()
    local gp = ggo and transform_pos(ggo)
    if not gp then return end
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ench in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                if griffin_is_self(ench) or is_dead(ench) then return end
                local cgo = char_go(ench)
                local nm = go_name(cgo) or ""
                if nm:sub(1, 3) == "ch2" then return end   -- enemies keep their grudge
                local ep = transform_pos(cgo)
                if not ep then return end
                local dx = (tonumber(ep.x) or 0.0) - (tonumber(gp.x) or 0.0)
                local dz = (tonumber(ep.z) or 0.0) - (tonumber(gp.z) or 0.0)
                if dx * dx + dz * dz > 2500.0 then return end   -- 50m
                local hs = character_hate_system(ench, cgo)
                if hs then
                    pcall(function() hs:call("setCustomRate(via.GameObject, System.Single)", ggo, 0.0) end)
                    pcall(function() hs:call("clear(via.GameObject)", ggo) end)
                end
            end)
        end
    end)
end

function clear_party_hate()
    clear_character_hate(get_player(), char_go(get_player()))
    local pm = singleton("app.PawnManager")
    if not pm then return false end
    local any = false
    for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
        local list = nil
        pcall(function() list = pm:call(getter) end)
        local n = 0
        pcall(function() n = list and list:call("get_Count") or 0 end)
        for i = 0, (tonumber(n) or 0) - 1 do
            local pawn = nil
            pcall(function() pawn = list:call("get_Item", i) end)
            if pawn then any = clear_character_hate(pawn, char_go(pawn)) or any end
        end
    end
    return any
end

function clear_griffin_hate_toward_party()
    -- AURORA'S CATCH (2026-07-05): the friend-shield only stops the PARTY hating
    -- the griffin; it never stops the GRIFFIN accruing hate toward the player/
    -- pawns. Passive Distance-hate (category 0) builds just from standing near
    -- them, so her hate list fills with FRIENDS she is forbidden to attack, and
    -- her #1 target can end up being the player -> she postures and never commits
    -- to the real enemy. Zero the hate RATE toward each party member (so it can't
    -- re-accrue) AND clear the hate already on them, every beat.
    local hs = griffin_hate_system()
    if not hs then return end
    local function neutralize(go)
        if not go then return end
        pcall(function() hs:call("setCustomRate(via.GameObject, System.Single)", go, 0.0) end)
        pcall(function() hs:call("clear(via.GameObject)", go) end)
    end
    neutralize(char_go(get_player()))
    local pm = singleton("app.PawnManager")
    if pm then
        for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
            local list = nil
            pcall(function() list = pm:call(getter) end)
            local n = tonumber(list and list:call("get_Count")) or 0
            for i = 0, n - 1 do
                local pawn = nil
                pcall(function() pawn = list:call("get_Item", i) end)
                if pawn then neutralize(char_go(pawn)) end
            end
        end
    end
end

local function clear_griffin_targets()
    local _, go = reacquire_griffin()
    if not go then return end
    local lock_on = get_component(go, "app.LockOnTarget")
    if lock_on then pcall(function() lock_on:set_field("TargetData", nil) end) end
    local bb = get_component(go, "app.AIBlackBoardController")
    if bb then
        pcall(function() bb:call("clearEnemyTargetList") end)
        pcall(function() bb:call("updateEnemyTargetList") end)
    end
end

local function set_griffin_native_climb_calm(ch, go)
    ch = ch or S.griffin
    go = go or S.griffin_go
    if not (ch and go) then return false end
    clear_griffin_hate()
    clear_griffin_targets()
    stop_navigation(ch, true)
    set_motion_fsm_puppet(go, C.puppet_motion_fsm == true)
    if C.disable_griffin_ai then
        disable_record(get_component(go, "app.AIDecisionMaker"), "app.AIDecisionMaker")
        disable_record(get_component(go, "app.NavigationAI"), "app.NavigationAI")
    end
    if C.native_climb_force_calm_fsm then
        set_griffin_fsm_node_silent(C.native_climb_calm_fsm_node, C.native_climb_calm_fsm_tree)
    end
    if C.native_climb_hard_calm_think_stop then
        set_think_stop(ch, true)
    else
        set_think_stop(ch, false)
    end
    return true
end

local function pacify_griffin(reason)
    clear_griffin_hate()
    clear_griffin_targets()
    set_griffin_puppet(true)
    if reason then status("griffin pacified: " .. tostring(reason)) end
end

system_array_to_table = function(sys_array)
    if not sys_array then return {} end
    local out = {}
    local ok = false
    pcall(function()
        if sys_array.get_elements then
            out = sys_array:get_elements() or {}
            ok = true
        end
    end)
    if ok then return out end

    local count = nil
    pcall(function() count = sys_array:call("get_Count") end)
    if count == nil then pcall(function() count = sys_array:get_Count() end) end
    if count == nil then pcall(function() count = sys_array:call("get_Length") end) end
    if count == nil then pcall(function() count = sys_array:get_Length() end) end
    count = tonumber(count) or 0
    for i = 0, count - 1 do
        local item = nil
        pcall(function() item = sys_array[i] end)
        if not item then pcall(function() item = sys_array:call("get_Item", i) end) end
        if item then table.insert(out, item) end
    end
    return out
end

local function get_griffin_motion_component()
    local ch = reacquire_griffin()
    local motion = nil
    pcall(function() motion = ch and ch:call("get_Motion") end)
    if not motion then
        local _, go = reacquire_griffin()
        motion = get_component(go, "via.motion.Motion")
    end
    return motion
end

local function motion_component_key(motion)
    local key = nil
    pcall(function() key = motion and motion:get_address() end)
    return tostring(key or "no-motion")
end

local function motion_bank_label(bank)
    if not bank then return nil end
    local id, name = nil, nil
    pcall(function() id = bank:get_BankID() end)
    pcall(function()
        local list = bank:get_MotionList()
        name = list and list:ToString():match("^.+%[.+/(.+)%.motlist%]")
    end)
    return tonumber(id), name
end

local function refresh_motion_catalog(force)
    local motion = get_griffin_motion_component()
    local key = motion_component_key(motion)
    if not force and S.motion_catalog and S.motion_catalog_key == key then return S.motion_catalog end

    local catalog = { items = {}, names = {}, by_tag = {} }
    S.motion_catalog = catalog
    S.motion_catalog_key = key

    if not motion then
        S.motion_catalog_status = "no via.motion.Motion on griffin"
        return catalog
    end

    local minfo = nil
    pcall(function() minfo = sdk.create_instance("via.motion.MotionInfo"):add_ref() end)
    if not minfo then
        S.motion_catalog_status = "could not create via.motion.MotionInfo"
        return catalog
    end

    local seen_banks = {}
    local function scan_bank(bank_id, bank_name)
        bank_id = tonumber(bank_id)
        if bank_id == nil or seen_banks[bank_id] then return end
        seen_banks[bank_id] = true

        local count = 0
        pcall(function() count = motion:getMotionCount(bank_id) end)
        count = tonumber(count) or 0
        for i = 0, count - 1 do
            local ok = pcall(function()
                motion:call("getMotionInfoByIndex(System.UInt32, System.UInt32, via.motion.MotionInfo)", bank_id, i, minfo)
            end)
            if ok then
                local id, name = nil, nil
                pcall(function() id = minfo:get_MotionID() end)
                pcall(function() name = minfo:get_MotionName() end)
                id = tonumber(id)
                name = tostring(name or ("motion_" .. tostring(id or i)))
                if id ~= nil then
                    local clean_name = name:gsub("^esf%d%d%d_", "")
                    local item = {
                        bank = bank_id,
                        id = id,
                        name = clean_name,
                        bank_name = bank_name or ("bank " .. tostring(bank_id)),
                    }
                    table.insert(catalog.items, item)
                    catalog.by_tag[tostring(bank_id) .. ":" .. tostring(id)] = #catalog.items
                end
            end
        end
    end

    for _, holder_name in ipairs({ "ActiveMotionBank", "DynamicMotionBank" }) do
        local banks = nil
        pcall(function() banks = motion:call("get_" .. holder_name) end)
        for _, bank in ipairs(system_array_to_table(banks)) do
            local bank_id, bank_name = motion_bank_label(bank)
            scan_bank(bank_id, bank_name)
        end
    end

    if #catalog.items == 0 then
        scan_bank(C.motion_bank, "manual bank")
    end

    table.sort(catalog.items, function(a, b)
        if a.bank == b.bank then return a.id < b.id end
        return a.bank < b.bank
    end)
    catalog.by_tag = {}
    for i, item in ipairs(catalog.items) do
        catalog.by_tag[tostring(item.bank) .. ":" .. tostring(item.id)] = i
        catalog.names[i] = string.format("%03d:%04d  %s", item.bank, item.id, item.name)
    end

    S.motion_catalog_status = string.format("scanned %d valid motions", #catalog.items)
    pcall(function() json.dump_file(MOD .. "_motions.json", catalog.items) end)
    S.audition_index = catalog.by_tag[tostring(C.motion_bank) .. ":" .. tostring(C.audition_motion)] or math.min(S.audition_index or 1, math.max(#catalog.items, 1))
    return catalog
end

local audition_griffin_motion

local function motion_tag(bank_id, motion_id)
    return tostring(math.floor(tonumber(bank_id) or 0)) .. ":" .. tostring(math.floor(tonumber(motion_id) or 0))
end

local function motion_is_skipped(bank_id, motion_id)
    local tag = motion_tag(bank_id, motion_id)
    for raw in tostring(C.audition_skip_motions or ""):gmatch("[^,%s]+") do
        if tostring(raw) == tag then return true end
    end
    return false
end

local function apply_griffin_motion_root_mode()
    local ch = reacquire_griffin()
    local motion = nil
    pcall(function() motion = ch and ch:call("get_Motion") end)
    if not motion then
        S.last_motion_root_mode_set_ok = false
        S.last_motion_root_mode = "no motion"
        return false
    end

    local current = nil
    pcall(function() current = motion:call("get_RootMotion") end)
    S.last_motion_root_mode = tostring(current or "(nil)")

    if C.root_motion_suppress_clip_locomotion ~= true then
        S.last_motion_root_mode_set_ok = false
        return false
    end

    local mode = math.max(0, math.floor(tonumber(C.root_motion_suppressed_play_mode) or 0))
    local ok = false
    pcall(function()
        motion:call("set_RootMotion(via.motion.RootPlayMode)", mode)
        ok = true
    end)
    if not ok then
        pcall(function()
            motion:call("set_RootMotion", mode)
            ok = true
        end)
    end
    if C.root_motion_disable_root_scale == true then
        pcall(function() motion:call("set_RootScaleDisabled(System.Boolean)", true) end)
        pcall(function() motion:call("set_RootScaleDisabled", true) end)
    end
    local after = nil
    pcall(function() after = motion:call("get_RootMotion") end)
    S.last_motion_root_mode = tostring(after or mode)
    S.last_motion_root_mode_set_ok = ok == true
    return ok == true
end

local function play_griffin_motion(motion_id, bank_id, force, owner)
    if not motion_id or motion_id < 0 then return false end
    -- BASE-LAYER OWNER GATE (Fable P2 diagnosis: movement "cancels" the gust because an ungated
    -- painter repaints the base layer over the gust clips). While a special move OWNS the base
    -- layer, every non-owner paint is a no-op. Owner sets S.base_owner={name,until_clock} and
    -- refreshes it while active; the stale timeout guarantees a dead owner can never wedge the
    -- whole animation system.
    -- ⭐⭐ NODE LOCKOUT (2026-08-04) -- sits ABOVE the base-owner gate on purpose.
    -- base_owner is a 0.6s lease and a real node outlives it by seconds; once it lapsed, any
    -- painter could repaint L0 over a body whose root motion the node still owned. That is the
    -- two-owners condition that AV'd on clip 5010 and it is what crashed Aurora's hold-B-mid-loop.
    -- While a node is genuinely current on her FSM, the ONLY paint allowed is the rise's own.
    if C.route3_node_lockout_paint ~= false and owner ~= "rise" and owner ~= "risenode" then
        local locked = false
        pcall(function() locked = griffin_node_lockout_active() == true end)
        if locked then
            S.base_owner_blocked = string.format("NODE LOCKOUT blocked %s:%s (%s) @%.1f",
                tostring(bank_id), tostring(motion_id), tostring(owner or "?"), os.clock())
            return false
        end
    end
    local own = S.base_owner
    if own and os.clock() > (tonumber(own.until_clock) or 0.0) then S.base_owner = nil; own = nil end
    if own and owner ~= own.name then
        S.base_owner_blocked = string.format("%s blocked %s:%s @%.1f", tostring(own.name),
            tostring(bank_id), tostring(motion_id), os.clock())
        return false
    end
    bank_id = tonumber(bank_id)
    if bank_id == nil then bank_id = C.motion_bank end
    local key = tostring(bank_id) .. ":" .. tostring(motion_id)
    local now = os.clock()
    local repeat_seconds = tonumber(C.same_motion_repeat_seconds) or 2.0
    if not force and key == S.last_forced_motion_key and now - (S.last_forced_motion_clock or 0.0) < repeat_seconds then
        return true
    end
    local ch = reacquire_griffin()
    local motion = nil
    local layer = nil
    pcall(function() motion = ch and ch:call("get_Motion") end)
    pcall(function() layer = motion and motion:call("getLayer", 0) end)
    if not layer then return false end
    return pcall(function()
        if C.root_motion_suppress_clip_locomotion == true then apply_griffin_motion_root_mode() end
        pcall(function() motion:call("set_PlaySpeed", 1.0) end)
        pcall(function() motion:call("set_PlayState", 0) end)
        layer:call(
            "changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
            bank_id, motion_id, 0.0, 8.0, 1, 1
        )
        -- re-assert AFTER the motion change too: a clip swap can reset root handling
        if C.root_motion_suppress_clip_locomotion == true then apply_griffin_motion_root_mode() end
        S.last_forced_motion = key
        S.last_forced_motion_key = key
        S.last_forced_motion_clock = now
    end)
end

local function pause_griffin_motion()
    local ch = reacquire_griffin()
    local motion = nil
    pcall(function() motion = ch and ch:call("get_Motion") end)
    if not motion then return false end
    local ok = false
    pcall(function()
        motion:call("set_PlaySpeed", 0.0)
        ok = true
    end)
    return ok
end

local function set_griffin_motion_speed(speed)
    local ch = reacquire_griffin()
    local motion = nil
    pcall(function() motion = ch and ch:call("get_Motion") end)
    if not motion then return false end
    local ok = false
    pcall(function()
        motion:call("set_PlaySpeed", tonumber(speed) or 1.0)
        ok = true
    end)
    return ok
end

function griffin_set_player_motion_speed(speed)
    local player = get_player()
    local motion = nil
    pcall(function() motion = player and player:call("get_Motion") end)
    if not motion then
        local pgo = char_go(player)
        if pgo then motion = get_component(pgo, "via.motion.Motion") end
    end
    if not motion then return false end
    local ok = false
    pcall(function()
        motion:call("set_PlaySpeed", tonumber(speed) or 1.0)
        ok = true
    end)
    return ok
end

function griffin_set_player_fsm_enabled(on)
    -- taming law: PlaySpeed 0 does NOT stop MotionFsm2 -- transitions still swap
    -- clips (round-7 field: parked b20:100 still marched to clip 190). The FSM itself
    -- must be disabled while the ride pose owns the visuals; restored on stop/dismount.
    local pgo = char_go(get_player())
    local fsm = pgo and get_component(pgo, "via.motion.MotionFsm2")
    S.route3_rider_motfsm_found = fsm ~= nil
    if not fsm then return false end
    local ok = false
    pcall(function() fsm:call("set_Enabled", on == true); ok = true end)
    return ok
end

function griffin_player_motion_state()
    local player = get_player()
    local motion = nil
    pcall(function() motion = player and player:call("get_Motion") end)
    if not motion then
        local pgo = char_go(player)
        if pgo then motion = get_component(pgo, "via.motion.Motion") end
    end
    local out = { bank = nil, clip = nil, frame = nil, ending = nil }
    pcall(function()
        local layer = motion and motion:call("getLayer", 0)
        if layer then
            out.bank = tonumber(layer:call("get_MotionBankID"))
            out.clip = tonumber(layer:call("get_MotionID"))
            out.frame = tonumber(layer:call("get_Frame"))
            out.ending = tonumber(layer:call("get_EndFrame"))
        end
    end)
    return out, motion
end

-- Has the rider's animation stopped changing?
--
-- The cling pose is held by setting the player's motion speed to zero, which freezes whatever
-- frame is on screen at that instant -- so if the mount clip is still transitioning when it
-- fires, the Arisen locks into a half-pose and stays contorted for the whole flight. That was
-- rare and random, which is the signature of a race, and the fixed delay it used to rely on was
-- a timer racing an animation: it narrowed the window without ever closing it.
--
-- The animation can answer the question itself. When the same bank/clip has been playing for a
-- sustained stretch and is past its first frame, the mount transition is over and the steady
-- cling loop is running -- freezing there is safe by construction rather than by timing.
function griffin_rider_pose_settled(now)
    if not S.rider_pose_wait_since then S.rider_pose_wait_since = now end
    local cur = griffin_player_motion_state()
    local bank, clip = tonumber(cur.bank), tonumber(cur.clip)
    local settled = false
    if bank and clip then
        local sig = string.format("%d:%d", math.floor(bank), math.floor(clip))
        local frame = tonumber(cur.frame) or 0.0
        if S.rider_pose_settle_sig ~= sig then   -- a different clip: the transition is still moving
            S.rider_pose_settle_sig = sig
            S.rider_pose_settle_since = now
            S.rider_pose_settle_frame = frame
            S.rider_pose_settle_still = nil
            S.rider_pose_settle_moved = nil
        else
            -- ⛔ "The same clip for N seconds" is NOT the same as "finished moving", which is why
            -- the first version of this still let her lock in contorted: a mount clip that runs
            -- for three seconds satisfies it three quarters of a second in, mid-climb. The FRAME
            -- says what the clip id cannot -- a pose is steady once the frame stops advancing
            -- (a one-shot that has played out and is holding) or wraps (a loop running its cycle).
            -- Both mean the transition is behind us; a frame still climbing means it is not.
            local last = tonumber(S.rider_pose_settle_frame) or frame
            local wrapped = frame < last - 1.0
            local advancing = frame > last + 0.01
            S.rider_pose_settle_frame = frame
            if advancing or wrapped then S.rider_pose_settle_moved = true end
            -- ⛔ "The frame is not advancing" means finished ONLY if it ever started. A clip that
            -- has been requested but has not begun playing looks exactly like one that has played
            -- out -- both sit still -- so the previous version froze within the first fraction of
            -- a second, mid-climb, which the probe caught red-handed: F on the very first sample
            -- at +0.4s on every mount. Require movement to have been SEEN before believing that
            -- stillness means anything. A wrap counts, since a clip cannot loop without advancing.
            if wrapped or (S.rider_pose_settle_moved == true and not advancing) then
                S.rider_pose_settle_still = S.rider_pose_settle_still or now
                settled = (now - S.rider_pose_settle_still)
                    >= math.max(0.0, tonumber(C.route3_rider_pose_settle) or 0.75)
            else
                S.rider_pose_settle_still = nil   -- still playing through: keep waiting
            end
        end
    else
        S.rider_pose_settle_sig = nil
    end
    if settled then return true end
    -- Never wait forever. If her clip genuinely will not settle, an unfrozen rider is a running
    -- animation strapped to a flying griffin, which is worse than an imperfect held pose -- so
    -- fall back to the old behaviour, but say so, because reaching here means something upstream
    -- is restarting her motion and that is the real bug to chase.
    if now - (tonumber(S.rider_pose_wait_since) or now) > 6.0 then
        pcall(function() log.info("[GriffinRide] rider clip never settled in 6s -- freezing anyway (bank/clip kept changing)") end)
        return true
    end
    return false
end

-- ⭐ YAW LOCK (experiment, default OFF -- Aurora 2026-07-26, from the probe's own data).
--
-- The probe showed her facing delta DRIFTING on every mount, including the ones that looked fine:
-- 50 degrees on one, 200 on another. A seated rider locked to her mount would hold that delta
-- constant whichever way the mount turns. She does not, so the griffin turns underneath her while
-- she keeps her own heading, until she is looking at its tail. That is the actual "faces the wrong
-- way", and no amount of mount-timing was ever going to touch it.
--
-- It CAPTURES the relationship rather than imposing one: whatever angle the climb settled her at
-- is the angle it holds. So it cannot invent a new wrong facing -- at worst it preserves the one
-- the climb produced, which is what already happens. The only exception is a captured offset that
-- is already past 90 degrees, i.e. she latched backwards; there is nothing worth preserving in
-- that, so it falls back to the configured trim.
--
-- ⛔ ROTATION ONLY. The documented "pendulum" -- her body orbiting under the griffin -- came from
-- two authorities writing her POSITION. Position is left entirely to the native climb here; this
-- writes nothing but yaw, which is the one channel the climb demonstrably is not holding.
function griffin_rider_yaw_lock_tick()
    if C.route3_rider_yaw_lock ~= true then
        S.rider_yaw_lock_offset = nil            -- flag off: forget everything, byte-identical to before
        S.route3_rider_yaw_lock_status = "off"
        return
    end
    if S.mounted ~= true or S.route3_proxy_ride_active ~= true then
        S.rider_yaw_lock_offset = nil
        S.route3_rider_yaw_lock_status = "not riding"
        return
    end
    local pgo = char_go(get_player())
    local _, ggo = reacquire_griffin()
    if not (pgo and ggo) then return end
    local gyaw = yaw_from_transform(ggo)
    if not gyaw then return end

    if S.rider_yaw_lock_offset == nil then
        -- Wait for the same settle the pose freeze waits for: an offset measured mid-climb would
        -- be the very transition angle we are trying not to inherit.
        if not griffin_rider_pose_settled(os.clock()) then
            S.route3_rider_yaw_lock_status = "waiting for her pose to settle"
            return
        end
        local pyaw = yaw_from_transform(pgo)
        if not pyaw then return end
        local off = wrap_angle(pyaw - gyaw)
        local trim = math.rad(tonumber(C.route3_rider_yaw_lock_offset_deg) or 0.0)
        if math.abs(off) > math.pi * 0.5 then off = trim end   -- latched backwards: nothing to keep
        S.rider_yaw_lock_offset = off
        S.route3_rider_yaw_lock_status = string.format("locked at %+.0f deg", math.deg(off))
    end
    pcall(function()
        transform_of(pgo):call("set_Rotation",
            make_quat_yaw(wrap_angle(gyaw + (tonumber(S.rider_yaw_lock_offset) or 0.0))))
    end)
end

function griffin_apply_captured_rider_pose()
    local wanted_bank = math.floor(tonumber(C.route3_rider_pose_bank) or -1)
    local wanted_clip = math.floor(tonumber(C.route3_rider_pose_clip) or -1)
    local wanted_frame = tonumber(C.route3_rider_pose_frame) or -1.0
    if wanted_bank < 0 or wanted_clip < 0 or wanted_frame < 0.0 then return false, "no captured pose" end
    local cur, motion = griffin_player_motion_state()
    if not motion or cur.bank == nil or cur.clip == nil then return false, "player motion unavailable" end
    -- Do not swap the Arisen's clip under the native climb FSM. Only pin a recorded frame
    -- when the same authored climb clip is already live; changing banks here can break mount state.
    if math.floor(cur.bank) ~= wanted_bank or math.floor(cur.clip) ~= wanted_clip then
        return false, string.format("waiting for b%d:%d (live b%s:%s)", wanted_bank, wanted_clip,
            tostring(cur.bank), tostring(cur.clip))
    end
    local ok = false
    pcall(function()
        local layer = motion:call("getLayer", 0)
        layer:call("set_Frame", wanted_frame)
        motion:call("set_PlaySpeed", 0.0)
        ok = true
    end)
    if ok then
        S.rider_pose_frozen = true
        S.route3_rider_pose_status = string.format("captured b%d:%d f%.1f", wanted_bank, wanted_clip, wanted_frame)
    end
    return ok, ok and S.route3_rider_pose_status or "frame pin failed"
end

-- ROUND-47 ENGAGE-RACE GATE (an EXPERIMENT, per work-order review: the storm's
-- per-mount coin flip correlates with native systems surviving a puppet engage that
-- raced the mount transition -- IkLeg2/JointConstraints re-enablers only appear on
-- storm rides). The gate delays the WHOLE pose start (pose + puppet together --
-- delaying only the puppet would leave the Wilds clip fighting the live climb =
-- round 0-8 chaos); while waiting she sits in the plain native climb-mount, the
-- known-safe pre-Wilds state. Ready = player L0 in the climb bank (20) with the
-- clip STABLE ~0.35s (a single-frame b20:100 poll could miss -- round-8: the FSM
-- marches through clips); 2.0s timeout proceeds anyway and logs what it saw.
function griffin_rider_engage_gate_ready(now)
    local st = nil
    pcall(function() st = griffin_player_motion_state() end)
    local bank = st and tonumber(st.bank) or -1
    local clip = st and tonumber(st.clip) or -1
    local last = S.route3_rider_gate_last
    if type(last) ~= "table" or last.bank ~= bank or last.clip ~= clip then
        S.route3_rider_gate_last = { bank = bank, clip = clip, since = now }
        return false, string.format("b%d:%d (unstable)", bank, clip)
    end
    local held = now - (tonumber(last.since) or now)
    if bank == 20 and held >= 0.35 then
        return true, string.format("engaged on b%d:%d stable %.2fs", bank, clip, held)
    end
    return false, string.format("b%d:%d held %.2fs", bank, clip, held)
end

function griffin_rider_engage_gate_tick()
    local deadline = tonumber(S.route3_rider_pose_gate_until)
    if not deadline then return end
    if S.mounted ~= true or S.route3_wilds_rider_pose_active == true then
        S.route3_rider_pose_gate_until = nil
        S.route3_rider_gate_last = nil
        return
    end
    local now = os.clock()
    local ready, why = griffin_rider_engage_gate_ready(now)
    if ready or now >= deadline then
        S.route3_rider_pose_gate_until = nil
        S.route3_rider_gate_last = nil
        pcall(function() log.info(string.format("[GriffinRide] engage gate: %s%s",
            ready and "" or "TIMED OUT on ", tostring(why))) end)
        pcall(route3_wilds_rider_pose_start)
    end
end

-- The primary Wilds RideMove_000 loop is the authored neutral mounted idle.  It is replayed
-- full-body: mixing its torso with a frozen DD2 climb frame produced a one-knee-up crouch, not a
-- riding pose.  The native climb FSM remains live for gameplay ownership while the render-time
-- bone overlay supplies the visible saddle pose.
function route3_wilds_rider_pose_start()
    if iris_puppet_seat_active() then return false end -- 07-24: the puppet seat paints the rider
    if C.route3_wilds_rider_pose_enabled ~= true or S.mounted ~= true then return false end
    if S.route3_wilds_rider_pose_active == true then return true end
    local pose = _G.NB_Pose
    if type(pose) ~= "table" or type(pose.play) ~= "function" then
        S.route3_wilds_rider_pose_status = "rs_anim_lab / NB_Pose unavailable"
        return false
    end
    local apply_set = tostring(C.route3_wilds_rider_pose_set or "Full")
    local hybrid_lower = apply_set == "Upper"
    if not hybrid_lower then
        -- PARK the native climb clip (PlaySpeed 0). Left live, the mount-wait clip
        -- (b20:100, 300f) runs to its end and the FSM transitions into the hang/cling
        -- state (b20:0, 585f) whose controller re-orients the whole character against
        -- the surface = "fine for a second, then upside down". Frozen playback never
        -- fires the end-transition. The old unfreeze-for-Full existed because the
        -- frozen climb frame's legs showed through -- the root/feet cleanup pass owns
        -- those joints now, so nothing of the frozen frame is visible.
        -- ⛔ ROUND-50c: LEGACY (puppet-off) = PURE JOINT OVERLAY -- the round-0
        -- configuration, finally clean. Aurora's bisect: ALL checkboxes off = flight
        -- is perfect, so the native climb must stay FULLY alive: no PlaySpeed park
        -- (R7 sediment), no FSM-off (R8 sediment), no clip pin -- the game owns
        -- clips, states, position, orientation; we own only the 19 pose joints
        -- (lab, PrepareRendering) + root/feet cleanup + limbfit + hand magnet.
        -- Every R0-era bug this config once had (poisoned quat, weld math, lab
        -- locals trap) has since been individually fixed. Park/FSM-off remain
        -- puppet-mode-only (route3_rider_puppet handles them).
        if C.route3_rider_puppet_enabled ~= false then
            if griffin_set_player_fsm_enabled(false) then S.route3_rider_fsm_off = true end
            pcall(route3_rider_puppet, true)
        end
    end
    local lower_ok, lower_status = false, "full-body Wilds legs"
    if hybrid_lower then
        lower_ok, lower_status = griffin_apply_captured_rider_pose()
        S.route3_rider_lower_retry_at = os.clock() + 0.25
    end
    local clip = tostring(C.route3_wilds_rider_pose_clip or "rs_wilds_ride_neutral")
    local ok, played = pcall(function()
        return pose.play(clip, "Arisen", apply_set, true,
            math.max(0.05, tonumber(C.route3_wilds_rider_pose_speed) or 1.0), true)
    end)
    if ok and played ~= false then
        S.route3_wilds_rider_pose_active = true
        S.route3_wilds_rider_pose_status = string.format("playing %s (%s)", clip, apply_set)
        S.route3_rider_pose_status = hybrid_lower
            and string.format("Wilds upper + native legs: %s", tostring(lower_status))
            or ("Wilds loop: " .. clip)
        -- Register the render-only finishing pass for BOTH ride architectures.  The
        -- old registration lived inside the rigid transform-lock branch, so the safe
        -- native-climb path got the Wilds eulers but not its root/feet cleanup, limb
        -- fit or hand IK.  All of these are joint writes at PrepareRendering; none
        -- changes the player GameObject/app.Character transform or gameplay state.
        if S.route3_limbfit_registered ~= true then
            S.route3_limbfit_registered = true
            re.on_application_entry("PrepareRendering", function()
                safe_run("griffin_rider_safe_visual", griffin_rider_safe_visual_tick)
                safe_run("griffin_rider_seat_hold", griffin_rider_seat_hold_tick)
                safe_run("griffin_rider_limbfit", griffin_rider_limbfit_apply)
                safe_run("griffin_rider_hand_magnet", griffin_rider_hand_magnet_apply)
            end)
        end
        return true
    end
    S.route3_wilds_rider_pose_status = "failed to play " .. clip
    return false
end

function route3_wilds_rider_pose_stop(reason)
    if S.route3_wilds_rider_pose_active ~= true then
        pcall(griffin_rider_safe_motion_yaw_restore)
        S.route3_rider_weld = nil
        S.route3_rider_weld_key = nil
        S.route3_rider_weld_stab = nil
        S.route3_rider_weld_dp = nil
        S.route3_rider_yaw0 = nil
        S.route3_rider_yaw_delta = nil
        S.route3_rider_yaw_acc = nil
        S.route3_rider_hip_rest = nil
        S.route3_rider_safe_hip_world0 = nil
        S.route3_rider_safe_yaw_version = nil
        S.route3_hand_seed = nil
        S.route3_rider_body_yaw = nil
        S.route3_rider_body0 = nil
        S.route3_rider_body_up = nil
        S.route3_rider_seat_last = nil
        if S.rider_pose_frozen == true then
            griffin_set_player_motion_speed(1.0)
            S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
        end
        if S.route3_rider_fsm_off == true then
            griffin_set_player_fsm_enabled(true)
            S.route3_rider_fsm_off = false
        end
        pcall(route3_rider_puppet, false)
        return
    end
    local pose = _G.NB_Pose
    pcall(griffin_rider_safe_motion_yaw_restore)
    if type(pose) == "table" and type(pose.stop) == "function" then pcall(pose.stop) end
    S.route3_wilds_rider_pose_active = false
    S.route3_wilds_rider_pose_status = "stopped: " .. tostring(reason or "ride ended")
    S.route3_rider_weld = nil
    S.route3_rider_weld_key = nil
    S.route3_rider_weld_stab = nil
    S.route3_rider_weld_dp = nil
    S.route3_rider_yaw0 = nil
    S.route3_rider_yaw_delta = nil
    S.route3_rider_yaw_acc = nil
    S.route3_rider_hip_rest = nil
    S.route3_rider_safe_hip_world0 = nil
    S.route3_rider_safe_yaw_version = nil
    S.route3_hand_seed = nil
    S.route3_rider_body_yaw = nil
    S.route3_rider_body0 = nil
    S.route3_rider_body_up = nil
    S.route3_rider_seat_last = nil
    if S.rider_pose_frozen == true then
        griffin_set_player_motion_speed(1.0)
        S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
    end
    if S.route3_rider_fsm_off == true then
        griffin_set_player_fsm_enabled(true)
        S.route3_rider_fsm_off = false
    end
    pcall(route3_rider_puppet, false)
end


function griffin_rider_audition_tick()
    -- CLIP-SWAP TEST (Aurora's theory): instead of PAINTING a pose over the climb (rs_anim_lab
    -- = the jitter), force the climb's own motion layer (L0) to PLAY a chosen clip, re-asserted
    -- each frame. The readout reports HELD vs "climb re-asserted" -- i.e. whether a native
    -- animated ride is even possible over a LIVE climb. Turn the MH Wilds loop OFF while testing.
    if C.route3_rider_audition ~= true then S.route3_audition_live = nil; return end
    if not (S.mounted == true or S.native_climb_mount == true or S.player_climb_on_character == true) then
        S.route3_audition_live = "not mounted"; return
    end
    local want_bank = math.floor(tonumber(C.route3_rider_audition_bank) or 0)
    local want_clip = math.floor(tonumber(C.route3_rider_audition_clip) or 0)
    local player = get_player()
    local motion = nil
    pcall(function() motion = player and player:call("get_Motion") end)
    if not motion then
        local pgo = char_go(player)
        motion = pgo and get_component(pgo, "via.motion.Motion") or nil
    end
    if not motion then S.route3_audition_live = "no Motion component"; return end
    pcall(function()
        local layer = motion:call("getLayer", 0)
        if not layer then return end
        local lb = tonumber(layer:call("get_MotionBankID")) or -1   -- what is LIVE at frame start
        local lc = tonumber(layer:call("get_MotionID")) or -1
        local lf = tonumber(layer:call("get_Frame")) or -1
        local held = (lb == want_bank and lc == want_clip)
        S.route3_audition_live = string.format("want b%d:%d | live b%d:%d f%.0f -> %s",
            want_bank, want_clip, lb, lc, lf, held and "HELD :)" or "climb re-asserted")
        if not held then
            layer:call(
                "changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                want_bank, want_clip, 6.0, 0.0, 1, 1)
        end
        layer:call("set_Speed", 1.0)   -- let it ANIMATE so we can judge the look
    end)
end

function route3_wilds_rider_pose_tick()
    if iris_puppet_seat_active() then -- 07-24: puppet seat owns the rider
        if S.route3_wilds_rider_pose_active == true then
            route3_wilds_rider_pose_stop("iris puppet seat")
        end
        return
    end
    if S.route3_wilds_rider_pose_active ~= true then return end
    if C.route3_wilds_rider_pose_enabled ~= true then route3_wilds_rider_pose_stop("disabled"); return end
    if S.mounted ~= true then route3_wilds_rider_pose_stop("not mounted"); return end
    if tostring(C.route3_wilds_rider_pose_set or "Full") == "Upper"
        and S.rider_pose_frozen ~= true
        and os.clock() >= (tonumber(S.route3_rider_lower_retry_at) or 0.0) then
        local lower_ok, lower_status = griffin_apply_captured_rider_pose()
        S.route3_rider_lower_retry_at = os.clock() + 0.25
        if lower_ok then
            S.route3_rider_pose_status = "Wilds upper + native legs: " .. tostring(lower_status)
        end
    else
        -- ROUND-50c: legacy = pure joint overlay -- NOTHING native is parked,
        -- disabled, or pinned (Aurora's bisect: all-off flight is perfect; the R7/R8
        -- park + FSM-off sediment was breaking the live climb). Puppet mode keeps
        -- its full per-tick assertion set.
        if S.route3_rider_puppet_on == true then
            if griffin_set_player_fsm_enabled(false) then S.route3_rider_fsm_off = true end
            griffin_rider_neutral_motion_tick()
        end
    end
    local pose = _G.NB_Pose
    if type(pose) ~= "table" or type(pose.is_playing) ~= "function" then
        S.route3_wilds_rider_pose_active = false
        S.route3_wilds_rider_pose_status = "player bridge lost"
        return
    end
    local ok, playing = pcall(pose.is_playing)
    if not ok or playing ~= true then
        S.route3_wilds_rider_pose_active = false
        S.route3_wilds_rider_pose_status = "clip ended unexpectedly"
    end
end

local function stop_griffin_animation()
    local ch, go = reacquire_griffin()
    local ok = set_griffin_motion_speed(1.0)
    if C.root_motion_stop_uses_idle_motion == true then
        local idle_bank = tonumber(C.root_motion_idle_bank) or tonumber(C.idle_bank) or 0
        local idle_motion = tonumber(C.root_motion_idle)
        if idle_motion == nil or idle_motion < 0 then idle_motion = tonumber(C.idle_motion) or 0 end
        ok = play_griffin_motion(idle_motion, idle_bank, true) or ok
    end
    ok = set_griffin_native_climb_calm(ch, go) or ok
    ok = set_griffin_fsm_node_silent(C.native_climb_calm_fsm_node, C.native_climb_calm_fsm_tree) or ok
    if not ok then ok = pause_griffin_motion() end
    S.audition_until_clock = 0.0
    S.last_root_motion_state = "idle"
    S.last_root_motion_played = false
    S.last_root_motion_stopped = ok == true
    S.last_root_motion_error = ok and "stopped/reset" or "stop failed"
    return ok
end

local function root_motion_params_for_state(state)
    if state == "run" then
        return tonumber(C.root_motion_run_bank) or 0, tonumber(C.root_motion_run) or -1
    elseif state == "walk" then
        return tonumber(C.root_motion_walk_bank) or 0, tonumber(C.root_motion_walk) or -1
    end
    return tonumber(C.root_motion_idle_bank) or 0, tonumber(C.root_motion_idle) or -1
end

local function route3_visual_animation_tick(now)
    if C.route3_visual_animation_enabled ~= true then
        S.last_root_motion_played = false
        S.last_root_motion_error = "(route3 visual disabled)"
        return false
    end
    if now <= (S.audition_until_clock or 0) then
        -- a one-shot clip (landing, jump leap) is playing: don't stomp it
        S.last_root_motion_error = "(holding for one-shot clip)"
        return true
    end
    if S.route3_motion_blocked == true then
        if S.last_root_motion_state ~= "idle" and C.root_motion_stop_on_idle == true then
            S.last_root_motion_stopped = stop_griffin_animation()
            S.last_root_motion_stop_clock = now
        else
            S.last_root_motion_stopped = false
        end
        S.last_root_motion_state = "idle"
        S.last_root_motion_key = "(blocked)"
        S.last_root_motion_played = false
        S.last_root_motion_error = "route3 blocked"
        return false
    end
    if now <= (S.audition_until_clock or 0) then
        S.last_root_motion_played = false
        S.last_root_motion_error = "audition active"
        return true
    end

    local forward = tonumber(S.last_character_root_forward) or 0.0
    local moving_forward = forward > 0.05
    local moving_any = math.abs(forward) + math.abs(tonumber(S.last_character_root_side) or 0.0) > 0.05
    if C.route3_visual_animation_forward_only == true and not moving_forward then
        moving_any = false
    end

    if not moving_any then
        if S.last_root_motion_state ~= "idle" and C.root_motion_stop_on_idle == true then
            S.last_root_motion_stopped = stop_griffin_animation()
            S.last_root_motion_stop_clock = now
            S.last_root_motion_error = S.last_root_motion_stopped and "route3 stopped idle" or "route3 stop failed"
        else
            S.last_root_motion_error = "route3 idle"
            S.last_root_motion_stopped = false
        end
        S.last_root_motion_state = "idle"
        S.last_root_motion_key = "(none)"
        S.last_root_motion_played = false
        return false
    end

    local state = S.last_character_root_move_run and "run" or "walk"
    local bank, motion = root_motion_params_for_state(state)
    local key = tostring(bank) .. ":" .. tostring(motion)
    local previous_state = S.last_root_motion_state
    local previous_key = S.last_root_motion_key
    S.last_root_motion_state = state
    S.last_root_motion_key = key
    if not motion or motion < 0 then
        S.last_root_motion_played = false
        S.last_root_motion_error = "route3 motion off"
        return false
    end

    local state_changed = key ~= previous_key or state ~= previous_state
    local tick_seconds = math.max(0.05, tonumber(C.root_motion_tick_seconds) or 0.4)
    local elapsed = now - (S.last_root_motion_clock or 0.0)
    if not state_changed and elapsed < tick_seconds then
        S.last_root_motion_played = false
        S.last_root_motion_error = "route3 holding"
        return true
    end

    -- ⛔⛔ THE GROUND-SPRINT JITTER (Aurora 2026-08-08: "about 2 full loops and there's a
    -- small but noticeable jitter on the third" -- GROUND sprint, not the air soar).
    -- This tick re-issues the locomotion clip every root_motion_tick_seconds. That is a
    -- no-op inside play_griffin_motion's same_motion_repeat_seconds window (2.0s) -- and
    -- the moment that window lapses the call FALLS THROUGH to a real changeMotion, which
    -- RESTARTS the running clip mid-cycle. A ~1s run clip therefore gets two clean loops
    -- and a hitch on the third: exactly the reported cadence.
    -- The re-assert exists to win the layer back when the FSM steals it, so keep that --
    -- but a clip that is ALREADY live needs no paint at all. Verify against the layer
    -- instead of re-painting on a timer; if the layer drifted, the paint still happens.
    if not state_changed then
        local live_id, live_bank = nil, nil
        pcall(function()
            local mo = get_griffin_motion_component()
            local layer = mo and mo:call("getLayer", 0)
            if layer then
                live_id = tonumber(layer:call("get_MotionID"))
                live_bank = tonumber(layer:call("get_MotionBankID"))
            end
        end)
        if live_id ~= nil and live_id == motion
            and (live_bank == nil or live_bank == bank) then
            S.last_root_motion_clock = now
            S.last_root_motion_played = false
            S.last_root_motion_error = "route3 clip already live (no repaint)"
            return true
        end
    end

    local ok = play_griffin_motion(motion, bank, state_changed)
    S.last_root_motion_clock = now
    S.last_root_motion_played = ok == true
    S.last_root_motion_stopped = false
    S.last_root_motion_error = ok and "route3 visual" or "route3 play failed"
    return true
end

local function route3_air_visual_animation_tick(now)
    if C.route3_air_visual_animation_enabled ~= true or S.airborne ~= true then
        S.route3_air_visual_status = "(disabled)"
        return false
    end
    if now <= (S.audition_until_clock or 0) then
        S.route3_air_visual_status = "audition active"
        return true
    end
    if now < (tonumber(S.route3_air_visual_block_until) or 0.0) then
        S.route3_air_visual_status = "transition grace"
        return true
    end
    if C.route3_air_visual_native_fsm_enabled == true then
        local native_interval = math.max(0.1, tonumber(C.route3_air_visual_native_fsm_interval) or 1.0)
        if now - (tonumber(S.route3_air_visual_last_native_fsm) or 0.0) >= native_interval then
            local _, go = reacquire_griffin()
            if C.route3_air_visual_native_fsm_unpuppet == true and go then set_motion_fsm_puppet(go, false) end
            local native_ok = set_griffin_fsm_node_silent(C.route3_air_visual_native_fsm_node, C.route3_air_visual_native_fsm_tree)
            S.route3_air_visual_last_native_fsm = now
            S.route3_air_visual_native_status = (native_ok and "native fsm ok " or "native fsm failed ") .. tostring(C.route3_air_visual_native_fsm_node)
        end
    else
        S.route3_air_visual_native_status = "(off)"
    end
    if native_flight_control_probe_tick then
        native_flight_control_probe_tick(now)
    end

    local forward = math.abs(tonumber(S.last_character_root_forward) or 0.0)
    local side = math.abs(tonumber(S.last_character_root_side) or 0.0)
    local vertical = math.abs(tonumber(S.last_character_root_vertical) or 0.0)
    local turning = math.abs(tonumber(S.last_character_root_turn_input) or 0.0)
    local moving = forward + side + vertical + turning > 0.05
    local sprinting = S.last_character_root_move_run == true and moving
    local state = moving and "air-flight" or "air-hover"
    if S.route3_landing_requested == true then state = "air-hover" end

    local bank = moving and tonumber(C.route3_air_visual_flight_bank) or tonumber(C.route3_air_visual_hover_bank)
    local motion = moving and tonumber(C.route3_air_visual_flight_motion) or tonumber(C.route3_air_visual_hover_motion)
    if sprinting and tonumber(C.route3_air_visual_sprint_motion) and tonumber(C.route3_air_visual_sprint_motion) >= 0 then
        state = "air-sprint"
        bank = tonumber(C.route3_air_visual_sprint_bank)
        motion = tonumber(C.route3_air_visual_sprint_motion)
        if S.route3_air_visual_sprint_was_active ~= true then
            S.route3_air_visual_sprint_started_at = now
            S.route3_air_visual_sprint_was_active = true
        end
        local start_motion = tonumber(C.route3_air_visual_sprint_start_motion)
        local start_seconds = math.max(0.0, tonumber(C.route3_air_visual_sprint_start_seconds) or 0.8)
        if start_motion and start_motion >= 0 and now - (tonumber(S.route3_air_visual_sprint_started_at) or 0.0) <= start_seconds then
            state = "air-sprint-start"
            bank = tonumber(C.route3_air_visual_sprint_start_bank)
            motion = start_motion
        end
    elseif C.route3_air_visual_burst_mode == true and moving then
        S.route3_air_visual_sprint_was_active = false
        local interval = math.max(0.25, tonumber(C.route3_air_visual_flap_interval) or 2.0)
        local due = now - (tonumber(S.route3_air_visual_last_flap) or 0.0) >= interval
        if due then
            state = "air-flap"
            S.route3_air_visual_last_flap = now
        else
            state = "air-glide"
            bank = tonumber(C.route3_air_visual_hover_bank)
            motion = tonumber(C.route3_air_visual_hover_motion)
        end
    else
        S.route3_air_visual_sprint_was_active = false
    end
    if S.route3_landing_requested == true then
        bank = tonumber(C.route3_air_visual_hover_bank)
        motion = tonumber(C.route3_air_visual_hover_motion)
    end
    bank = bank or 0
    if C.route3_air_visual_allow_native_clips ~= true and bank == 0 and (motion == 5000 or motion == 5101) then
        S.route3_air_visual_status = state .. " blocked unsafe 0:" .. tostring(motion)
        S.last_root_motion_error = S.route3_air_visual_status
        return false
    end
    if not motion or motion < 0 then
        S.route3_air_visual_status = state .. " motion off"
        S.last_root_motion_error = S.route3_air_visual_status
        return C.route3_air_visual_native_fsm_enabled == true
    end

    local key = tostring(bank) .. ":" .. tostring(motion)
    local previous_state = S.last_root_motion_state
    local previous_key = S.last_root_motion_key
    local state_changed = key ~= previous_key or state ~= previous_state
    local tick_seconds = math.max(0.05, tonumber(C.route3_air_visual_tick_seconds) or 0.45)
    local elapsed = now - (S.last_root_motion_clock or 0.0)
    if not state_changed and elapsed < tick_seconds then
        S.route3_air_visual_status = "holding " .. state
        S.last_root_motion_played = false
        S.last_root_motion_error = S.route3_air_visual_status
        return true
    end

    S.last_root_motion_state = state
    S.last_root_motion_key = key
    local ok = play_griffin_motion(motion, bank, state_changed)
    S.last_root_motion_clock = now
    S.last_root_motion_played = ok == true
    S.last_root_motion_stopped = false
    S.route3_air_visual_status = ok and (state .. " " .. key) or ("failed " .. state .. " " .. key)
    S.last_root_motion_error = ok and "route3 air visual" or "route3 air visual failed"
    return ok == true
end












-- Paint her airborne wing animation, whichever flap backend is configured.
--
-- suppress_native: during a native carry the catch node already drives her body, so the two
-- "let the native FSM animate her" options must stand down for this one call -- leave them on
-- and the node and our resident flap fight over the same layers. The flag is restored straight
-- away rather than saved, so the player's configured preference is never actually changed.
--
-- Global, not local, for the same reason route3_flap_takeoff_tick above it is: this file sits on
-- Lua's hard ceiling of 200 locals in a chunk. Splitting into modules is what actually fixes that.
function route3_air_flap_tick(now, suppress_native)
    if C.flap_mode == 1 then
        local native_anim = C.route3_native_flight_anim
        if suppress_native then C.route3_native_flight_anim = false end
        route3_flap_takeoff_tick(now)
        C.route3_native_flight_anim = native_anim
    else
        local native_fsm = C.route3_air_visual_native_fsm_enabled
        if suppress_native then C.route3_air_visual_native_fsm_enabled = false end
        route3_air_visual_animation_tick(now)
        C.route3_air_visual_native_fsm_enabled = native_fsm
    end
end

local function clear_motion_queue()
    S.motion_queue = {}
    S.motion_chain_until = 0.0
end

local function queue_griffin_motion(delay, bank_id, motion_id)
    if not motion_id or motion_id < 0 then return end
    local due = os.clock() + math.max(0.0, tonumber(delay) or 0.0)
    table.insert(S.motion_queue, { due = due, bank = tonumber(bank_id) or 0, motion = tonumber(motion_id) or 0 })
    S.motion_chain_until = math.max(S.motion_chain_until or 0.0, due + 0.25)
end


local function griffin_action_manager()
    local ch = reacquire_griffin()
    local am = nil
    pcall(function() am = ch and ch:call("get_ActionManager") end)
    if not am then pcall(function() am = ch and ch:get_field("<ActionManager>k__BackingField") end) end
    return am
end

local function request_griffin_action(node, layer)
    local am = griffin_action_manager()
    if not am then status("no griffin ActionManager"); return false end
    -- our own requests go through the SAME requestActionCore our action hook
    -- intercepts — flag them so the hook waves them through (we were
    -- blocking our own attack requests)
    S.route3_self_action = true
    local ok = pcall(function()
        am:call("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)", 10, tostring(node or ""), tonumber(layer) or 0)
    end)
    S.route3_self_action = false
    status("native action request " .. tostring(node) .. " layer=" .. tostring(layer or 0) .. " ok=" .. tostring(ok))
    return ok
end



function route3_trigger_wing_flap_visual()
    if C.route3_wing_joint_auto_audio_visual ~= true then
        S.route3_wing_joint_pose_status = "(fake flap disabled)"
        return false
    end
    local now = os.clock()
    S.route3_wing_flap_pulse_start = now
    S.route3_wing_flap_pulse_until = now + math.max(0.1, tonumber(C.route3_wing_joint_flap_pulse_seconds) or 0.75)
    if C.route3_wing_joint_flap_sync_audio == true then
        C.route3_wing_joint_visual_enabled = true
        C.route3_wing_joint_pose_enabled = false
        C.route3_wing_joint_visual_mode = 1
    end
    return true
end


function route3_read_wing_capture_sample(tf, names)
    local sample = {}
    local hits = 0
    for _, name in ipairs(names or {}) do
        pcall(function()
            local joint = tf and tf:call("getJointByName", name)
            if not joint then return end
            local q = joint:call("get_LocalRotation")
            local p = joint:call("get_LocalPosition")
            local item = {}
            if q then
                local x, y, z, w = griffin_q_read(q)
                item.rot = { x = x, y = y, z = z, w = w }
            end
            if p then
                item.pos = { x = tonumber(p.x) or 0.0, y = tonumber(p.y) or 0.0, z = tonumber(p.z) or 0.0 }
            end
            if item.rot or item.pos then
                sample[name] = item
                hits = hits + 1
            end
        end)
    end
    return sample, hits
end




function route3_write_wing_delta_sample(tf, baseline, delta_sample, strength)
    if not (tf and baseline and delta_sample) then return 0 end
    local hits = 0
    strength = math.max(0.0, math.min(1.0, tonumber(strength) or 1.0))
    for name, delta in pairs(delta_sample) do
        pcall(function()
            local joint = tf:call("getJointByName", name)
            local base = baseline[name]
            if not (joint and base and delta) then return end
            local q = griffin_q_table_mul(base, delta)
            local tx, ty, tz, tw = tonumber(q.x) or 0.0, tonumber(q.y) or 0.0, tonumber(q.z) or 0.0, tonumber(q.w) or 1.0
            if strength < 0.999 then
                local bx, by, bz, bw = tonumber(base.x) or 0.0, tonumber(base.y) or 0.0, tonumber(base.z) or 0.0, tonumber(base.w) or 1.0
                tx = bx + (tx - bx) * strength
                ty = by + (ty - by) * strength
                tz = bz + (tz - bz) * strength
                tw = bw + (tw - bw) * strength
                local len = math.sqrt(tx * tx + ty * ty + tz * tz + tw * tw)
                if len > 0.0001 then
                    tx, ty, tz, tw = tx / len, ty / len, tz / len, tw / len
                end
            end
            joint:call("set_LocalRotation", griffin_make_quat_raw(tx, ty, tz, tw))
            hits = hits + 1
        end)
    end
    return hits
end

function route3_write_wing_exact_sample(tf, sample, strength)
    if not (tf and sample) then return 0 end
    local hits = 0
    strength = math.max(0.0, math.min(1.0, tonumber(strength) or 1.0))
    for name, item in pairs(sample) do
        pcall(function()
            local joint = tf:call("getJointByName", name)
            if not (joint and item) then return end

            -- captured local positions bake in the capture-time skeleton/scale;
            -- replayed on a differently-scaled griffin they splay the feathers,
            -- so replay rotations only unless positions are explicitly enabled
            local pos = C.route3_wing_replay_write_positions == true and route3_wing_sample_pos(item) or nil
            if pos then
                local px, py, pz = tonumber(pos.x) or 0.0, tonumber(pos.y) or 0.0, tonumber(pos.z) or 0.0
                if strength < 0.999 then
                    local current = joint:call("get_LocalPosition")
                    if current then
                        px = (tonumber(current.x) or 0.0) + (px - (tonumber(current.x) or 0.0)) * strength
                        py = (tonumber(current.y) or 0.0) + (py - (tonumber(current.y) or 0.0)) * strength
                        pz = (tonumber(current.z) or 0.0) + (pz - (tonumber(current.z) or 0.0)) * strength
                    end
                end
                joint:call("set_LocalPosition", make_vec3(px, py, pz))
            end

            local rot = route3_wing_sample_rot(item)
            if rot then
                local tx, ty, tz, tw = tonumber(rot.x) or 0.0, tonumber(rot.y) or 0.0, tonumber(rot.z) or 0.0, tonumber(rot.w) or 1.0
                if strength < 0.999 then
                    local cq = joint:call("get_LocalRotation")
                    local cx, cy, cz, cw = griffin_q_read(cq)
                    tx = cx + (tx - cx) * strength
                    ty = cy + (ty - cy) * strength
                    tz = cz + (tz - cz) * strength
                    tw = cw + (tw - cw) * strength
                end
                tx, ty, tz, tw = griffin_q_normalize(tx, ty, tz, tw)
                joint:call("set_LocalRotation", griffin_make_quat_raw(tx, ty, tz, tw))
            end
            hits = hits + 1
        end)
    end
    return hits
end

function route3_blend_wing_samples(a, b, f)
    if not a then return b end
    if not b then return a end
    f = math.min(1.0, math.max(0.0, tonumber(f) or 0.0))
    if f <= 0.0001 then return a end
    if f >= 0.9999 then return b end
    local out = {}
    for name, item in pairs(a) do
        local other = b[name]
        if not other then
            out[name] = item
        else
            local blended = {}
            local pa = route3_wing_sample_pos(item)
            local pb = route3_wing_sample_pos(other)
            if pa and pb then
                blended.pos = {
                    x = (tonumber(pa.x) or 0.0) + ((tonumber(pb.x) or 0.0) - (tonumber(pa.x) or 0.0)) * f,
                    y = (tonumber(pa.y) or 0.0) + ((tonumber(pb.y) or 0.0) - (tonumber(pa.y) or 0.0)) * f,
                    z = (tonumber(pa.z) or 0.0) + ((tonumber(pb.z) or 0.0) - (tonumber(pa.z) or 0.0)) * f,
                }
            elseif pa then
                blended.pos = pa
            end
            local ra = route3_wing_sample_rot(item)
            local rb = route3_wing_sample_rot(other)
            if ra and rb then
                blended.rot = griffin_q_nlerp(ra, rb, f)
            elseif ra then
                blended.rot = ra
            end
            if blended.pos or blended.rot then out[name] = blended end
        end
    end
    return out
end

function route3_close_wing_capture_loop(data)
    -- the capture source (takeoff clip) is not cyclic: ease the tail of the
    -- captured samples back toward the first sample so the replay loop has no seam
    local samples = data and data.samples
    if not (samples and #samples >= 4) then return false end
    if data.loop_closed == true then return false end
    local first = samples[1]
    local t_first = tonumber(first.t) or 0.0
    local t_last = tonumber(samples[#samples].t) or t_first
    local span = t_last - t_first
    if span <= 0.05 or not first.joints then return false end
    local blend_from = t_first + span * 0.75
    for i = 2, #samples do
        local s = samples[i]
        local st = tonumber(s.t) or t_first
        if st > blend_from and s.joints then
            local w = (st - blend_from) / math.max(0.0001, t_last - blend_from)
            w = math.min(1.0, math.max(0.0, w))
            w = w * w * (3.0 - 2.0 * w)
            s.joints = route3_blend_wing_samples(s.joints, first.joints, w)
        end
    end
    data.loop_closed = true
    return true
end



function route3_load_wing_capture()
    local data = nil
    pcall(function() data = json.load_file(MOD .. "_wing_capture.json") end)
    if not (data and data.samples and #data.samples > 0) then
        S.route3_wing_capture_status = "load failed: no wing capture json"
        status(S.route3_wing_capture_status)
        return false
    end
    if data.mode ~= "exact-local-posrot-v1" and data.mode ~= "delta-local-v1" then
        S.route3_wing_capture_status = "load rejected: old capture, recapture"
        status(S.route3_wing_capture_status)
        return false
    end
    route3_close_wing_capture_loop(data)
    S.route3_wing_capture_data = data
    S.route3_wing_capture_status = string.format("loaded %d %s wing frames from capture", #(data.samples or {}), tostring(data.mode))
    status(S.route3_wing_capture_status)
    return true
end

function route3_load_wing_snapshot()
    local data = nil
    pcall(function() data = json.load_file(MOD .. "_wing_snapshot.json") end)
    if not (data and data.sample) then return false end
    S.route3_wing_snapshot = data.sample
    S.route3_wing_snapshot_names = data.joints or {}
    S.route3_wing_snapshot_status = string.format("loaded wing snapshot hits=%s", tostring(data.hits or "?"))
    return true
end



function route3_apply_wing_snapshot_hold(now)
    if griffin_predation_window_active(now) or griffin_predation_carry_wings_standdown() then return false end
    if C.route3_wing_snapshot_hold_enabled ~= true then return false end
    if not S.route3_wing_snapshot then
        if not route3_load_wing_snapshot() then
            C.route3_wing_snapshot_hold_enabled = false
            S.route3_wing_snapshot_status = "hold stopped: no snapshot"
            return false
        end
    end
    local _, go = reacquire_griffin()
    local tf = go and go:call("get_Transform")
    if not tf then
        S.route3_wing_snapshot_status = "hold failed: no transform"
        return false
    end
    local hits = route3_write_wing_exact_sample(tf, S.route3_wing_snapshot, 1.0)
    now = now or os.clock()
    if now - (tonumber(S.route3_wing_snapshot_last_status) or 0.0) > 0.5 then
        S.route3_wing_snapshot_last_status = now
        S.route3_wing_snapshot_status = string.format("holding wing snapshot hits=%d", hits)
    end
    return hits > 0
end


function route3_enable_captured_wing_replay()
    if not (S.route3_wing_capture_data and S.route3_wing_capture_data.samples and #S.route3_wing_capture_data.samples > 0) then
        if not route3_load_wing_capture() then return false end
    end
    C.route3_wing_joint_pose_enabled = false
    C.route3_wing_joint_visual_enabled = false
    C.route3_wing_replay_enabled = true
    S.route3_wing_replay_started_at = os.clock()
    S.route3_wing_replay_baseline = nil
    local _, go = reacquire_griffin()
    local tf = go and go:call("get_Transform")
    local names = S.route3_wing_capture_data and S.route3_wing_capture_data.joints or {}
    local baseline, hits = route3_read_wing_capture_sample(tf, names)
    if hits <= 0 then
        C.route3_wing_replay_enabled = false
        S.route3_wing_replay_status = "replay failed: no baseline"
        status(S.route3_wing_replay_status)
        return false
    end
    S.route3_wing_replay_baseline = baseline
    S.route3_wing_replay_user_stopped = false
    S.route3_wing_replay_status = string.format("captured delta replay armed base=%d", hits)
    save_config()
    status(S.route3_wing_replay_status)
    return true
end

function route3_apply_captured_wing_replay(now, phase)
    -- stand down during a swoop so a real attack node/clip can drive her pose instead
    if griffin_predation_window_active(now)
        or griffin_predation_carry_wings_standdown()
        or (griffin_grab_active() and S.route3_grab and S.route3_grab.anim == true)
        or griffin_unleash_striking() then return false end
    if C.route3_wing_replay_enabled ~= true then return false end
    if C.route3_wing_replay_late_update == true and phase ~= "late" then
        S.route3_wing_replay_status = "waiting for late update"
        return false
    end
    if C.route3_wing_replay_airborne_only == true and S.airborne ~= true then
        S.route3_wing_replay_status = "waiting for flight"
        return false
    end
    local data = S.route3_wing_capture_data
    if not (data and data.samples and #data.samples > 0) then
        if not route3_load_wing_capture() then return false end
        data = S.route3_wing_capture_data
    end
    local _, go = reacquire_griffin()
    local tf = go and go:call("get_Transform")
    if not tf then
        S.route3_wing_replay_status = "replay failed: no transform"
        return false
    end
    if not S.route3_wing_replay_baseline then
        local baseline, hits = route3_read_wing_capture_sample(tf, data.joints or {})
        if hits <= 0 then
            S.route3_wing_replay_status = "replay failed: no baseline"
            return false
        end
        S.route3_wing_replay_baseline = baseline
    end
    now = now or os.clock()
    local samples = data.samples
    local duration = tonumber(data.duration) or tonumber(samples[#samples].t) or 1.0
    duration = math.max(0.1, duration)
    local rate = math.max(0.1, tonumber(C.route3_wing_replay_rate) or 1.0)
    local t = ((now - (tonumber(S.route3_wing_replay_started_at) or now)) * rate) % duration
    -- interpolate between the two bracketing captured samples (capture rate is
    -- only ~22Hz; picking a single nearest sample reads as visible stepping)
    local n = #samples
    local t_first = tonumber(samples[1].t) or 0.0
    local t_last = tonumber(samples[n].t) or t_first
    local sa, sb, frac = samples[n], samples[1], 0.0
    if t >= t_first and t <= t_last then
        for i = 1, n - 1 do
            local t0 = tonumber(samples[i].t) or 0.0
            local t1 = tonumber(samples[i + 1].t) or t0
            if t >= t0 and t <= t1 then
                sa, sb = samples[i], samples[i + 1]
                frac = (t1 > t0) and ((t - t0) / (t1 - t0)) or 0.0
                break
            end
        end
    else
        -- wrap across the loop seam: blend last sample back into the first
        local gap = (duration - t_last) + t_first
        if gap > 0.0001 then
            local into = (t > t_last) and (t - t_last) or (t + (duration - t_last))
            frac = math.min(1.0, math.max(0.0, into / gap))
        end
    end
    local joints = route3_blend_wing_samples(sa and sa.joints, sb and sb.joints, frac)
    local hits = 0
    if data.mode == "exact-local-posrot-v1" or C.route3_wing_replay_exact == true then
        hits = route3_write_wing_exact_sample(tf, joints, C.route3_wing_replay_strength)
    else
        hits = route3_write_wing_delta_sample(tf, S.route3_wing_replay_baseline, joints, C.route3_wing_replay_strength)
    end
    S.route3_wing_replay_status = string.format("replay %s t=%.2f/%.2f hits=%d", tostring(data.mode), t, duration, hits)
    return hits > 0
end

function route3_native_flight_fsm_tick(now)
    if griffin_predation_window_active(now) then return false end
    -- The quick-rise choreography deliberately auditions an attack/catch node while the
    -- root is held still. Do not let the ordinary flight FSM painter replace that node;
    -- the choreography performs and verifies its own neutral hand-off before moving.
    if type(S.route3_quick_burst) == "table" then return false end
    if C.route3_native_flight_anim ~= true then return false end
    if S.airborne ~= true then return false end
    now = now or os.clock()
    -- let the one-shot takeoff clip finish first
    if now < (tonumber(S.route3_air_visual_block_until) or 0.0) then return false end
    local _, go = reacquire_griffin()
    if not go then return false end

    -- native animation needs a LIVE FSM: undo the puppet freeze while airborne.
    -- AI stays suppressed separately (AIDecisionMaker/NavigationAI disabled),
    -- and the per-frame transform reapply keeps engine root motion from steering.
    set_motion_fsm_puppet(go, false)
    if C.route3_wing_replay_enabled == true then
        C.route3_wing_replay_enabled = false
        S.route3_wing_replay_status = "(off: native flight anim owns the wings)"
    end

    local moving = math.abs(tonumber(S.last_drive_axis_x) or 0.0) + math.abs(tonumber(S.last_drive_axis_z) or 0.0) > 0.1
        or S.raw_ascend_down == true or S.raw_descend_down == true
    local node = moving and tostring(C.route3_native_flight_fly_node or "Fly.Flying.FlyForward")
        or tostring(C.route3_native_flight_hover_node or "Fly.Hovering.HoverForward")
    if S.route3_landing_requested == true then
        node = tostring(C.route3_native_flight_hover_node or "Fly.Hovering.HoverForward")
    end

    local interval = math.max(0.1, tonumber(C.route3_air_visual_native_fsm_interval) or 1.0)
    local desired_changed = node ~= S.route3_native_flight_node
    local check_due = now - (tonumber(S.route3_native_flight_last_check) or 0.0) >= interval
    if desired_changed or check_due then
        S.route3_native_flight_last_check = now
        -- full wake-up, same recipe the wing-probe tool proved in-game:
        -- clear think-stop AND restore motion playback speed (the freeze/baseline
        -- systems park it at 0, which keeps the pose static no matter the FSM)
        local ch = reacquire_griffin()
        if ch then set_think_stop(ch, false) end
        set_griffin_motion_speed(1.0)
        -- engage the NATIVE flight controller: without a fly state the engine
        -- classifies a held-in-air griffin as FALLING (endless FrontFall requests)
        -- and no fly action ever reaches layer 0 to drive the motion FSM
        local fc = get_component(go, "app.FlightControl")
        if fc then
            pcall(function()
                fc:call("onFlyState(app.FlightControl.FlyStateNo)",
                    math.max(0, math.floor(tonumber(C.flight_control_fly_state) or 1)))
            end)
            pcall(function() fc:call("set_FlagGroundNotFound(System.Boolean)", false) end)
            local hit = route3_ground_hit_under(go, nil)
            local gy = tonumber(hit and hit.y)
            if gy then
                pcall(function() fc:call("setGroundHeight(System.Single, System.Single)", gy, 0.0) end)
                pcall(function() fc:call("set_GroundHeight(System.Single)", gy) end)
            end
        end
        local current = read_griffin_fsm_node()
        local leaf = node:match("[^%.]+$") or node
        -- only re-assert when the FSM is not already on the node we want,
        -- so the flight clip is never pointlessly restarted (no visual pops)
        local on_node = current == node or current == leaf
            or (current and current:find(leaf, 1, true) ~= nil)
        if desired_changed or not on_node then
            local ok = set_griffin_fsm_node_silent(node, tonumber(C.route3_air_visual_native_fsm_tree) or 0)
            if C.route3_native_flight_request_action == true then
                -- wake the action layer alongside the FSM (probe recipe: layer 4)
                request_griffin_action("CombatStateNormal", 4)
            end
            S.route3_native_flight_node = node
            S.route3_air_visual_native_status = (ok and "native flight: " or "native flight FAILED: ")
                .. node .. " (was " .. tostring(current) .. ")"
        else
            S.route3_air_visual_native_status = "native flight holding: " .. tostring(current)
        end
        route3_dump_native_flight_state("tick")
    end
    return true
end

function route3_dump_native_flight_state(reason)
    local ch, go = reacquire_griffin()
    local out = {
        time = os.date("%Y-%m-%d %H:%M:%S"),
        reason = tostring(reason or "manual"),
        airborne = S.airborne == true,
        native_mode = C.route3_native_flight_anim == true,
        asserting_node = tostring(S.route3_native_flight_node or "(none)"),
        native_status = tostring(S.route3_air_visual_native_status or "(none)"),
        last_griffin_action = tostring(S.last_griffin_action or "(none)"),
        griffin_action_history = S.griffin_action_history or {},
        blocked_griffin_actions = tonumber(S.blocked_griffin_actions) or 0,
        allowed_actions = tonumber(S.flight_control_allowed_actions) or 0,
        last_allowed_action = tostring(S.last_flight_control_allowed_action or "(none)"),
    }
    local fsm = get_motion_fsm(go)
    if fsm then
        pcall(function() out.fsm_puppet = fsm:call("get_PuppetMode") end)
        pcall(function() out.fsm_enabled = fsm:call("get_Enabled") end)
        out.fsm_nodes = {}
        for tree = 0, 3 do
            pcall(function()
                local n = fsm:call("getCurrentNodeName", tree)
                if n ~= nil then out.fsm_nodes["tree" .. tostring(tree)] = tostring(n) end
            end)
        end
    else
        out.fsm_puppet = "(no MotionFsm2)"
    end
    local motion = get_griffin_motion_component()
    if motion then
        pcall(function() out.motion_speed = motion:call("get_PlaySpeed") end)
        pcall(function() out.motion_enabled = motion:call("get_Enabled") end)
        for li = 0, 1 do
            pcall(function()
                local layer = motion:call("getLayer", li)
                if layer then
                    local info = {}
                    pcall(function() info.bank = tonumber(layer:call("get_MotionBankID")) end)
                    pcall(function() info.motion = tonumber(layer:call("get_MotionID")) end)
                    pcall(function() info.frame = tonumber(layer:call("get_Frame")) end)
                    pcall(function() info.end_frame = tonumber(layer:call("get_EndFrame")) end)
                    pcall(function() info.speed = tonumber(layer:call("get_Speed")) end)
                    out["layer" .. tostring(li)] = info
                end
            end)
        end
    else
        out.motion_speed = "(no Motion)"
    end
    pcall(function()
        local am = ch and ch:call("get_ActionManager")
        if am then
            out.action_names = {}
            for li = 0, 5 do
                pcall(function()
                    local n = am:call("getCurrentActionName(System.UInt32)", li)
                    if n ~= nil and tostring(n) ~= "" then out.action_names["layer" .. tostring(li)] = tostring(n) end
                end)
            end
        end
    end)
    pcall(function()
        local fc = get_component(go, "app.FlightControl")
        if fc then
            local info = {}
            pcall(function() info.fly_status = tostring(fc:call("get_FlyStatusValue")) end)
            pcall(function() info.can_fly = fc:call("get_IsCanFly") end)
            pcall(function() info.enabled = fc:call("get_Enabled") end)
            out.flight_control = info
        else
            out.flight_control = "(no app.FlightControl)"
        end
    end)
    -- rolling history so consecutive snapshots show whether the clip frame advances
    S.route3_native_probe_hist = S.route3_native_probe_hist or {}
    local l0 = out.layer0 or {}
    table.insert(S.route3_native_probe_hist, 1, string.format(
        "%s puppet=%s speed=%s node0=%s clip=%s:%s frame=%s/%s",
        os.date("%H:%M:%S"), tostring(out.fsm_puppet), tostring(out.motion_speed),
        tostring(out.fsm_nodes and out.fsm_nodes.tree0 or "?"),
        tostring(l0.bank), tostring(l0.motion), tostring(l0.frame), tostring(l0.end_frame)
    ))
    while #S.route3_native_probe_hist > 12 do table.remove(S.route3_native_probe_hist) end
    out.recent = S.route3_native_probe_hist
    pcall(function() json.dump_file(MOD .. "_native_flight_probe.json", out) end)
    S.route3_native_flight_probe_status = string.format(
        "puppet=%s speed=%s node0=%s frame=%s",
        tostring(out.fsm_puppet), tostring(out.motion_speed),
        tostring(out.fsm_nodes and out.fsm_nodes.tree0 or "?"), tostring(l0.frame)
    )
    if reason ~= "tick" then status("native flight state dumped: " .. S.route3_native_flight_probe_status) end
    return true
end

function route3_air_authority_tick()
    -- runs in LateUpdateBehavior, AFTER UpdateMotion: re-assert our flight
    -- position so a clip's root motion is cancelled before the frame renders.
    -- This is what makes ANY animation safe to play in the air.
    if S.world_paused == true then return false end
    if griffin_predation_window_active() then return false end
    -- ⭐⭐ FC-LIFT STANDDOWN -- and this tick is the WORST offender of the three. Cancelling a
    -- clip's root motion every frame is right for a COSMETIC clip (no displacement, our
    -- position stays true). For a native node that genuinely moves the body it is the exact
    -- mechanism of the CTD: the node displaces, we drag her back, FC integrates a third
    -- opinion, and the divergence AVs. During a node window she is allowed to actually move.
    if griffin_rise_fc_window_active() then return false end
    if S.airborne ~= true then return false end
    griffin_rise_stage("air_authority enter (LateUpdateBehavior)")
    if not (S.route3_proxy_ride_active == true or S.route3_seat_parented == true) then return false end
    if C.route3_transform_drive_after_parent ~= true then return false end
    local pos = S.route3_air_pos
    if not pos then return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    -- backstop: flight must never write the griffin below the terrain,
    -- whatever the drive/input state was this tick. LONG-REACH ray (60m up)
    -- so being under the surface never blinds it, but only BELOW-us contacts
    -- count as ground (canopy hits were clamping the griffin onto treetops)
    local rpos = transform_render_pos(go)
    local hit = route3_cast_ground_below(
        tonumber(rpos and rpos.x) or tonumber(pos.x) or 0.0,
        tonumber(pos.y) or 0.0,
        tonumber(rpos and rpos.z) or tonumber(pos.z) or 0.0,
        60.0, 400.0
    )
    local gy = tonumber(hit and hit.y)
    if gy then
        S.route3_last_ground_probe = { x = tonumber(pos.x) or 0.0, z = tonumber(pos.z) or 0.0, y = gy }
        S.route3_air_blind_floor = nil
    else
        local lp = S.route3_last_ground_probe
        if lp then
            local dxp = (tonumber(pos.x) or 0.0) - (tonumber(lp.x) or 0.0)
            local dzp = (tonumber(pos.z) or 0.0) - (tonumber(lp.z) or 0.0)
            if dxp * dxp + dzp * dzp <= 225.0 then gy = tonumber(lp.y) end
        end
        if not gy then
            -- NO ground in sight (water/void below — rays don't hit water):
            -- refuse to descend further than 2m below the last-sighted altitude
            local floor_y = tonumber(S.route3_air_blind_floor)
            if not floor_y then
                floor_y = tonumber(pos.y) or 0.0
                S.route3_air_blind_floor = floor_y
            end
            if (tonumber(pos.y) or 0.0) < floor_y - 2.0 then
                pos = make_position(tonumber(pos.x) or 0.0, floor_y - 2.0, tonumber(pos.z) or 0.0)
                S.route3_air_pos = pos
            end
        end
    end
    -- never clamp during the takeoff lock: the griffin is still at/near ground
    -- level and slope/rock contacts above its origin read as "buried",
    -- teleporting it into the air before the takeoff animation even starts
    if gy and not route3_takeoff_lock_active() and (tonumber(pos.y) or 0.0) < gy + 0.3 then
        pos = make_position(tonumber(pos.x) or 0.0, gy + 0.3, tonumber(pos.z) or 0.0)
        S.route3_air_pos = pos
    end
    local rot = S.route3_air_rot or make_quat_yaw(S.heading_yaw or yaw_from_transform(go) or 0.0)
    griffin_rise_stage("air_authority before re-assert write")
    local applied = route3_apply_air_transform(ch, go, pos, rot)
    griffin_rise_stage("air_authority write OK -- now the ROOT-JOINT pitch")
    -- visual pitch: tilt the ROOT JOINT after animation evaluation — the
    -- character logic never sees it, so nothing flips or syncs it away.
    -- ABSOLUTE set from a captured base pose: multiplying the current local
    -- each frame compounds our own offset (clips don't re-drive the root
    -- joint) and barrel-rolls the griffin.
    local pitch = tonumber(S.route3_air_pitch) or 0.0
    pcall(function()
        local tf = go:call("get_Transform")
        local joint = tf and tf:call("getJointByName", tostring(C.route3_pitch_joint or "root"))
        if not joint then griffin_rise_stage("pitch: NO JOINT -- skipped"); return end
        griffin_rise_stage(string.format("pitch: joint ok, pitch=%.3f applied=%s base=%s",
            pitch, tostring(S.route3_pitch_applied), tostring(S.route3_pitch_base ~= nil)))
        if math.abs(pitch) <= 0.2 then
            -- level flight: refresh the clean base and restore it once
            local cx, cy, cz, cw = griffin_q_read(joint:call("get_LocalRotation"))
            if S.route3_pitch_applied == true and S.route3_pitch_base then
                local b = S.route3_pitch_base
                griffin_rise_stage("pitch: about to RESTORE base rotation")
                joint:call("set_LocalRotation", griffin_make_quat_raw(b.x, b.y, b.z, b.w))
                S.route3_pitch_applied = false
                griffin_rise_stage("pitch: base restored OK")
            else
                S.route3_pitch_base = { x = cx, y = cy, z = cz, w = cw }
                griffin_rise_stage("pitch: base captured (no write)")
            end
            return
        end
        local b = S.route3_pitch_base
        if not b then griffin_rise_stage("pitch: no base captured -- skipped"); return end
        local half = math.rad(pitch) * 0.5
        local nx, ny, nz, nw = griffin_q_mul(b.x, b.y, b.z, b.w, math.sin(half), 0.0, 0.0, math.cos(half))
        griffin_rise_stage("pitch: about to set_LocalRotation (TILT)")
        joint:call("set_LocalRotation", griffin_make_quat_raw(nx, ny, nz, nw))
        S.route3_pitch_applied = true
        griffin_rise_stage("pitch: tilt applied OK")
    end)
    griffin_rise_stage("air_authority DONE -- returning")
    return applied
end

function route3_dump_ally_probe()
    -- side-by-side identity dump: griffin (enemy-spawned) vs player vs pawn
    -- (native ally). The pawn-vs-griffin DIFF is the faction lever.
    local out = { time = os.date("%Y-%m-%d %H:%M:%S") }
    local function dump_obj(obj)
        if not obj then return "(nil)" end
        local d = { fields = {}, methods = {} }
        pcall(function() d.type = obj:get_type_definition():get_full_name() end)
        pcall(function() d.tostring = tostring(obj:call("ToString()")) end)
        pcall(function()
            local td = obj:get_type_definition()
            while td do
                for _, f in ipairs(td:get_fields() or {}) do
                    local name = tostring(f:get_name() or "")
                    if d.fields[name] == nil then
                        pcall(function()
                            local v = obj:get_field(name)
                            local tv = tostring(v)
                            local vtype = ""
                            pcall(function() vtype = v:get_type_definition():get_full_name() end)
                            if vtype:find("Nullable", 1, true) then
                                -- unwrap boxed Nullable: the pointer is useless,
                                -- the value inside is the team id we care about
                                local has, val = nil, nil
                                pcall(function() has = v:get_field("_HasValue") end)
                                if has == nil then pcall(function() has = v:get_field("HasValue") end) end
                                pcall(function() val = v:get_field("_Value") end)
                                if val == nil then pcall(function() val = v:get_field("Value") end) end
                                if val == nil then pcall(function() val = v:get_field("mValue") end) end
                                tv = string.format("nullable has=%s value=%s", tostring(has), tostring(val))
                            elseif vtype ~= "" then
                                tv = tv .. " [" .. vtype .. "]"
                            end
                            d.fields[name] = tv
                        end)
                    end
                end
                td = td:get_parent_type()
            end
        end)
        pcall(function()
            local td = obj:get_type_definition()
            while td do
                for _, m in ipairs(td:get_methods() or {}) do
                    local name = tostring(m:get_name() or "")
                    local lname = name:lower()
                    if lname:find("group", 1, true) or lname:find("kind", 1, true) or lname:find("hash", 1, true) then
                        d.methods[#d.methods + 1] = name .. "(" .. tostring(m:get_num_params()) .. ")"
                    end
                end
                td = td:get_parent_type()
            end
        end)
        return d
    end
    local function scan(ch)
        if not ch then return "(none)" end
        local info = { group_getters = {} }
        pcall(function() info.type = ch:get_type_definition():get_full_name() end)
        local ctx = nil
        pcall(function() ctx = ch:get_field("<Context>k__BackingField") end)
        if not ctx then pcall(function() ctx = ch:call("get_Context") end) end
        if not ctx then info.holder = "(no Context)"; return info end
        info.holder = dump_obj(ctx)
        local gc = nil
        pcall(function() gc = ctx:get_field("GroupContext") end)
        if not gc then pcall(function() gc = ctx:call("get_GroupContext") end) end
        if gc then
            info.group_context = dump_obj(gc)
            for _, m in ipairs({
                "get_Group", "get_GroupId", "get_GroupNo", "get_GroupName", "getGroupName",
                "get_Force", "get_Belong", "get_Category", "get_Kind",
                "get_Hostility", "get_IsEnemy", "get_DefaultGroup",
            }) do
                pcall(function()
                    local v = gc:call(m)
                    if v ~= nil then
                        local tv = tostring(v)
                        pcall(function() tv = tv .. " [" .. v:get_type_definition():get_full_name() .. "]" end)
                        info.group_getters[m] = tv
                    end
                end)
            end
        end
        return info
    end
    out.griffin = scan(reacquire_griffin())
    out.player = scan(get_player())
    pcall(function()
        local pm = singleton("app.PawnManager")
        local list = pm and pm:call("get_PawnCharacterList")
        local n = list and list:call("get_Count") or 0
        if n > 0 then out.pawn = scan(list:call("get_Item", 0)) end
    end)
    pcall(function() json.dump_file(MOD .. "_ally_probe.json", out) end)
    status("ally probe dumped: griffin vs player vs pawn identity fields")
    return true
end

function griffin_world_paused()
    -- pause menu or photo mode: nothing of ours may move or act.
    -- Flag names VERIFIED by the pause probe (round 61): photo mode flips
    -- PauseManager.isPausedAny + GuiManager get_IsDispPhotoModeAll/isPausedGUI.
    local paused = false
    pcall(function()
        local pm = singleton("app.PauseManager")
        if pm and pm:call("isPausedAny") == true then paused = true end
    end)
    if not paused then
        pcall(function()
            local gm = singleton("app.GuiManager")
            if gm then
                if gm:call("get_IsDispPhotoModeAll") == true
                    or gm:call("get_IsDispPhotoMode") == true
                    or gm:call("isPausedGUI") == true then
                    paused = true
                end
            end
        end)
    end
    return paused
end

function griffin_pause_probe_tick()
    local until_t = tonumber(S.pause_probe_until) or 0.0
    if until_t <= 0.0 or os.clock() > until_t then return false end
    local now = os.clock()
    if now - (tonumber(S.pause_probe_last) or 0.0) < 1.0 then return false end
    S.pause_probe_last = now
    local sample = { t = os.date("%H:%M:%S") }
    for _, name in ipairs({ "app.PauseManager", "app.PhotoModeManager", "app.PhotoManager", "app.SnapShotManager", "app.GuiManager" }) do
        pcall(function()
            local mgr = singleton(name)
            if not mgr then sample[name] = "(missing)"; return end
            local vals = {}
            local td = mgr:get_type_definition()
            local count = 0
            while td and count < 25 do
                for _, m in ipairs(td:get_methods() or {}) do
                    local n = tostring(m:get_name() or "")
                    local ln = n:lower()
                    -- getters only: calling verb-methods blind is dangerous
                    if m:get_num_params() == 0
                        and (ln:find("^get_") or ln:find("^is"))
                        and (ln:find("pause") or ln:find("photo") or ln:find("active") or ln:find("snap")) then
                        count = count + 1
                        pcall(function()
                            local v = mgr:call(n)
                            if type(v) == "boolean" then vals[n] = v end
                        end)
                    end
                end
                td = td:get_parent_type()
            end
            sample[name] = vals
        end)
    end
    S.pause_probe_samples = S.pause_probe_samples or {}
    table.insert(S.pause_probe_samples, 1, sample)
    while #S.pause_probe_samples > 30 do table.remove(S.pause_probe_samples) end
    pcall(function() json.dump_file(MOD .. "_pause_probe.json", { samples = S.pause_probe_samples }) end)
    return true
end

function route3_ally_group_ctx(ch)
    local ctx = nil
    pcall(function() ctx = ch and ch:get_field("<Context>k__BackingField") end)
    if not ctx then pcall(function() ctx = ch and ch:call("get_Context") end) end
    local gc = nil
    if ctx then pcall(function() gc = ctx:get_field("GroupContext") end) end
    return ctx, gc
end

function route3_ally_join_party()
    -- copy the PLAYER's team id (group hash) onto the griffin — probe showed
    -- player+pawn share 2385506540 while the griffin carries monster groups
    local gch = reacquire_griffin()
    if not gch then S.route3_ally_status = "need a griffin"; status(S.route3_ally_status); return false end
    local _, sgc = route3_ally_group_ctx(get_player())
    local gctx, ggc = route3_ally_group_ctx(gch)
    if not (sgc and ggc) then S.route3_ally_status = "contexts missing"; status(S.route3_ally_status); return false end
    if not S.route3_ally_orig then
        local orig = {}
        pcall(function() orig.group = ggc:get_field("GroupHash") end)
        pcall(function() orig.default_group = ggc:get_field("DefaultGroupHash") end)
        pcall(function() orig.kind = gctx and gctx:get_field("CharacterKind") end)
        S.route3_ally_orig = orig
    end
    local applied = {}
    for _, fname in ipairs({ "GroupHash", "DefaultGroupHash" }) do
        pcall(function()
            local box = sgc:get_field(fname)
            if box ~= nil then
                ggc:set_field(fname, box)
                applied[#applied + 1] = fname
            end
        end)
    end
    if C.route3_companion_can_be_attacked == true and gctx then
        -- Kind 2 is socially calm but is excluded from native monster target
        -- selection. Keep the copied party group (party/guard safety) while
        -- restoring monster kind so hostile AI can select and genuinely hit
        -- the companion. Relationship/hate hooks below remain pair-scoped.
        pcall(function()
            local kind = tonumber(S.route3_ally_orig and S.route3_ally_orig.kind)
            if not kind or kind == 2 then kind = 8 end
            gctx:set_field("CharacterKind", kind)
            applied[#applied + 1] = "Kind=" .. tostring(kind) .. " (attackable)"
        end)
    elseif C.route3_ally_set_kind == true and gctx then
        pcall(function()
            gctx:set_field("CharacterKind", 2)
            applied[#applied + 1] = "Kind=2"
        end)
    end
    -- a claimed creature is no boss: drop the boss HP gauge if one is up
    -- ⚠ r69: gauge-killing is GLOBAL (see the note in stable.lua's calm tick --
    -- it cost every boss healthbar in the game). This one only fires ONCE, at
    -- the moment of the claim, so it is far less harmful than the 0.5s version
    -- -- but it rides the same switch so both go quiet together.
    if C.route3_kill_boss_gauge == true then
        pcall(function() singleton("app.GuiManager"):call("unregistBossGauge") end)
    end
    -- purge every existing grudge from the pre-tame fight (hooks only block
    -- NEW hate) and keep purging briefly while the combat AI disengages —
    -- pawns stop attacking, and battle music ends with the battle
    pcall(function() clear_party_hate() end)
    pcall(function() clear_griffin_hate() end)
    pcall(function() clear_griffin_targets() end)
    S.route3_ally_calm_until = os.clock() + 12.0
    S.route3_ally_status = #applied > 0 and ("joined party: " .. table.concat(applied, ", ")) or "no fields written"
    status("ally switch: " .. S.route3_ally_status)
    return #applied > 0
end

function route3_ally_auto_tick()
    local due = tonumber(S.route3_ally_auto_at) or 0.0
    if due <= 0.0 or os.clock() < due then return false end
    if S.player_climb_on_character == true then
        -- context writes while the player clings to the body are crash
        -- territory: wait until they're off (registration itself is safe)
        S.route3_ally_auto_at = os.clock() + 1.0
        return false
    end
    S.route3_ally_auto_at = 0.0
    -- a recall always restores party identity, even if ally-auto is off
    if C.route3_ally_auto ~= true and S.route3_recall_pending ~= true then return false end
    S.route3_recall_pending = nil
    local ok = route3_ally_join_party()
    -- gently settle her after a full-combat unleash: pacify once she's a
    -- citizen again (deferred = safe, body is past its native action now)
    pcall(function()
        local gch = reacquire_griffin()
        if gch then pacify_griffin(nil) end
    end)
    return ok
end



function griffin_is_self(ch)
    -- robust "is this OUR companion griffin?" test. UNLEASH flips her to kind 8
    -- (a monster), which puts her in the enemy list -- so the target-finder could
    -- grab HER OWN BODY as the nearest enemy and she attacks herself at 0m (100k
    -- HP, goblin untouched). Match by live body, stored ref, AND go-name (guid) so
    -- a reacquired/renamed body can't slip through.
    if not ch then return false end
    local gch, ggo = reacquire_griffin()
    if gch and same_obj(ch, gch) then return true end
    if S.griffin and same_obj(ch, S.griffin) then return true end
    local sname = ggo and go_name(ggo)
    if sname and sname ~= "" then
        local nm = go_name(char_go(ch))
        if nm and nm == sname then return true end
    end
    return false
end

function griffin_find_enemy(radius)
    -- nearest live hostile to the player (never party, never our companions)
    radius = tonumber(radius) or 40.0
    local pgo = char_go(get_player())
    local ppos = pgo and transform_pos(pgo)
    if not ppos then return nil end
    local best, best_d = nil, radius * radius
    local function consider(ch)
        if not ch then return end
        if mounts[ch] == true then return end
        if griffin_is_self(ch) then return end
        if is_player_or_party(ch) then return end
        if is_dead(ch) then return end
        local go = char_go(ch)
        local pos = go and transform_pos(go)
        if not pos then return end
        local d = distance_sq(pos, ppos)
        if d and d < best_d then best, best_d = ch, d end
    end
    pcall(function()
        local em = singleton("app.EnemyManager")
        if not em then return end
        for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
            local list = nil
            pcall(function() list = em:call(getter) end)
            local n = 0
            pcall(function() n = list and list:call("get_Count") or 0 end)
            if (tonumber(n) or 0) > 0 then
                for i = 0, n - 1 do pcall(function() consider(list:call("get_Item", i)) end) end
                return
            end
        end
    end)
    return best
end

function griffin_find_prey_or_enemy(radius)
    -- nearest hostile OR wildlife: the enemy list excludes wildlife (deer,
    -- boar, rabbit = ch299), so unleash "found nothing" on a deer. Scene-sweep
    -- for ch299 prey too so we can test whether her PREDATOR AI hunts food.
    local enemy = griffin_find_enemy(radius)
    local pgo = char_go(get_player())
    local ppos = pgo and transform_pos(pgo)
    if not ppos then return enemy end
    radius = tonumber(radius) or 60.0
    local best, best_d = enemy, enemy and (function()
        local ep = transform_pos(char_go(enemy))
        return ep and distance_sq(ep, ppos) or (radius * radius)
    end)() or (radius * radius)
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                if mounts[ch] == true then return end
                if griffin_is_self(ch) then return end
                if is_player_or_party(ch) or is_dead(ch) then return end
                local nm = tostring(go_name(char_go(ch)) or "")
                -- ch299* = DD2 wildlife (deer/fowl/fish/rabbit/boar/ox)
                if not nm:find("ch299", 1, true) then return end
                local pos = transform_pos(char_go(ch))
                local d = pos and distance_sq(pos, ppos)
                if d and d < best_d then best, best_d = ch, d end
            end)
        end
    end)
    return best
end

function griffin_find_predation_ox(radius)
    -- Keep the clean replay species-exact. The generic prey helper legitimately
    -- prefers a nearer goblin/deer, which made an "ox" test silently exercise a
    -- different target. Successful tape prey: ch299003_A_*.
    radius = math.max(5.0, tonumber(radius) or 40.0)
    local _, ggo = reacquire_griffin()
    local origin = ggo and transform_pos(ggo)
    if not origin then return nil end
    local pattern = tostring(C.route3_predation_prey_pattern or "ch299003"):lower()
    local best, best_d = nil, radius * radius
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                if ch == nil or mounts[ch] == true or griffin_is_self(ch) or is_dead(ch) then return end
                local go = char_go(ch)
                local name = tostring(go_name(go) or ""):lower()
                if pattern ~= "" and not name:find(pattern, 1, true) then return end
                local pos = transform_pos(go)
                local d = pos and distance_sq(pos, origin)
                if d and d < best_d then best, best_d = ch, d end
            end)
        end
    end)
    return best
end

function griffin_search_origin()
    -- Search center for the predation finders. The ACTUAL catch needs the griffin
    -- near the prey, so prefer the griffin's position -- but the diagnostics
    -- (INSPECT / SCAN) are run on foot next to a spawned target with the griffin
    -- dismissed or elsewhere, which used to make them find nothing. Fall back to
    -- the player so those always work. Returns (pos, "griffin"|"player") or nil.
    local _, ggo = reacquire_griffin()
    local o = ggo and transform_pos(ggo)
    if o then return o, "griffin" end
    local pgo = char_go(get_player())
    o = pgo and transform_pos(pgo)
    if o then return o, "player" end
    return nil, nil
end

function griffin_as_character(ref)
    -- CRITICAL NORMALIZER. EnemyManager hands back the monster BEHAVIOR
    -- (app.Ch220000 etc.), NOT the app.Character component -- and
    -- get_CaughtController / get_CatchController / startCatch's param type all
    -- live on app.Character. Checking them on the raw enemy ref always returns
    -- nil (method absent on the monster class), which silently made every
    -- EnemyManager target look "uncatchable". Resolve any character-ish ref to
    -- its app.Character component so the catch machinery is queried correctly.
    if not ref then return nil end
    local is_char = false
    pcall(function() is_char = ref:get_type_definition():is_a("app.Character") end)
    if is_char then return ref end
    local go = char_go(ref)
    local c = go and get_component(go, "app.Character")
    return c or ref
end

function griffin_predation_small_gate(ch, origin, r2, allow_dead)
    -- Eligibility gate for the GENERIC small-target native catch (Lyra handoff
    -- 2026-07-10 filter): party/tame/self never pass; live victims must OWN an
    -- INACTIVE CaughtController (the native constraint's other half); corpses
    -- may opt in for the rigid talon-pin path, which does not touch native Catch.
    -- exclude patterns keep bosses/large species out until proven one by one.
    -- Returns dist2 on pass, or nil + a human-readable skip reason.
    if ch == nil then return nil, "nil" end
    if mounts[ch] == true then return nil, "tamed ally" end
    if griffin_is_self(ch) then return nil, "self" end
    if is_player_or_party(ch) then return nil, "player/party" end
    local dead = is_dead(ch)
    if dead and allow_dead ~= true then return nil, "dead" end
    -- The native Catch transaction is only safe for bodies accepted by the same hard gate as the
    -- home-grown grab. The old code applied this to CORPSES ONLY, allowing a living Ogre/Cyclops/
    -- Drake to reach startCatch and crash while their large-body catch graph fought the talon carry.
    if not route3_grab_is_grabbable(ch, allow_dead == true) then
        return nil, dead and "protected/oversized corpse" or "protected/oversized"
    end
    local go = char_go(ch)
    local name = tostring(go_name(go) or ""):lower()
    if name == "" then return nil, "unnamed" end
    for pat in tostring(C.route3_predation_small_exclude or ""):gmatch("[^,%s]+") do
        if name:find(pat:lower(), 1, true) then return nil, "excluded (" .. pat .. ")" end
    end
    local inc = tostring(C.route3_predation_small_include or ""):lower():gsub("%s+", "")
    if inc ~= "" and not name:find(inc, 1, true) then return nil, "filtered" end
    if not dead then
        local chara = griffin_as_character(ch)  -- normalize BEFORE querying the catch machinery
        local caught = nil
        pcall(function() caught = chara:call("get_CaughtController") end)
        if not caught then return nil, "no CaughtController" end
        local busy = false
        pcall(function() busy = caught:call("get_IsActive") == true end)
        if busy then return nil, "already caught" end
        pcall(function()
            local cc = chara:call("get_CatchController")
            busy = cc and cc:call("get_IsActive") == true or false
        end)
        if busy then return nil, "mid-catch (catcher)" end
    end
    local maxr = tonumber(C.route3_predation_max_radius) or 0.0
    if maxr > 0.0 then
        local r = nil
        pcall(function() local cc = get_component(go, "via.physics.CharacterController"); r = cc and tonumber(cc:call("get_Radius")) end)
        if r and r > maxr then return nil, string.format("too large r=%.2f (talon jam)", r) end
    end
    local pos = transform_pos(go)
    local d2 = pos and distance_sq(pos, origin)
    if not d2 then return nil, "no position" end
    if d2 > r2 then return nil, string.format("out of range %.0fm", math.sqrt(d2)) end
    return d2, nil
end

function griffin_find_predation_small_target(radius, collect, allow_dead)
    -- Nearest ELIGIBLE small victim for the wild-Setting replay (generalising
    -- beyond oxen). Candidates = EnemyManager hostiles (goblins/bandits/wolves
    -- -- friendly NPCs and wandering rift pawns are never in that list) + ch299
    -- wildlife scene sweep (deer/boar/rabbit/fowl/ox). Manual buttons only --
    -- never call this per frame (full-scene sweep). Optional collect table gets
    -- one {d, line} verdict row per candidate for the panel scan readout.
    radius = math.max(5.0, tonumber(radius) or 15.0)
    local origin = griffin_search_origin()
    if not origin then return nil end
    local r2 = radius * radius
    local best, best_d = nil, r2 + 1.0
    local function consider(ch, src)
        pcall(function()
            local d2, why = griffin_predation_small_gate(ch, origin, r2, allow_dead)
            if collect then
                local go = char_go(ch)
                local pos = go and transform_pos(go)
                local dd = pos and distance_sq(pos, origin) or nil
                collect[#collect + 1] = {
                    d = dd or 1e9,
                    line = string.format("[%s] %s %s %s", src, tostring(go_name(go) or "?"),
                        dd and string.format("%.1fm", math.sqrt(dd)) or "?m",
                        d2 and "ELIGIBLE" or ("skip: " .. tostring(why))),
                }
            end
            if d2 and d2 < best_d then best, best_d = ch, d2 end
        end)
    end
    pcall(function()
        local em = singleton("app.EnemyManager")
        if not em then return end
        for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
            local list = nil
            pcall(function() list = em:call(getter) end)
            local n = 0
            pcall(function() n = list and list:call("get_Count") or 0 end)
            if (tonumber(n) or 0) > 0 then
                for i = 0, n - 1 do pcall(function() consider(list:call("get_Item", i), "enemy") end) end
                return
            end
        end
    end)
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                local nm = tostring(go_name(char_go(ch)) or ""):lower()
                if nm:find("ch2", 1, true) and not nm:find("ch253", 1, true) then
                    consider(ch, nm:find("ch299", 1, true) and "wild" or "monster")
                end
            end)
        end
    end)
    return best
end

function griffin_find_small_target_raw(radius)
    -- Nearest catch CANDIDATE ignoring the CaughtController pre-gate. This is
    -- how we reach a freshly-spawned goblin that the eligibility filter would
    -- skip -- so we can INSPECT it and TEST whether startCatch creates the
    -- caught side on demand. Still excludes self/tame/party/dead + patterns.
    radius = math.max(5.0, tonumber(radius) or 20.0)
    local origin = griffin_search_origin()
    if not origin then return nil end
    local r2 = radius * radius
    local best, best_d = nil, r2 + 1.0
    local function consider(ch)
        pcall(function()
            if ch == nil or mounts[ch] == true or griffin_is_self(ch) then return end
            if is_player_or_party(ch) or is_dead(ch) then return end
            local go = char_go(ch)
            local name = tostring(go_name(go) or ""):lower()
            if name == "" then return end
            for pat in tostring(C.route3_predation_small_exclude or ""):gmatch("[^,%s]+") do
                if name:find(pat:lower(), 1, true) then return end
            end
            local pos = transform_pos(go)
            local d2 = pos and distance_sq(pos, origin)
            if d2 and d2 < best_d then best, best_d = ch, d2 end
        end)
    end
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then
            for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
                local list = nil
                pcall(function() list = em:call(getter) end)
                local n = 0
                pcall(function() n = list and list:call("get_Count") or 0 end)
                if (tonumber(n) or 0) > 0 then
                    for i = 0, n - 1 do pcall(function() consider(list:call("get_Item", i)) end) end
                    return
                end
            end
        end
    end)
    if best then return best end
    -- No hostile in the enemy list: fall back to a scene sweep for any ch2* body.
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                local nm = tostring(go_name(char_go(ch)) or ""):lower()
                if nm:find("ch2", 1, true) then consider(ch) end
            end)
        end
    end)
    return best
end

function griffin_dump_victim_motion_catalog()
    -- NON-restart route to the struggle clip (Fable design 2026-07-11): the goblin
    -- DOES struggle under PLAYER carry, so its caught/struggle clip lives in its
    -- OWN loaded motion banks. Scan them for caught/carry/struggle names -> feed
    -- the (bank,id) to CatchController.setCaughtMotion (the push the empty caught
    -- node needs). Manual button (heavy scan). Reuses the file's motion enumerator.
    local prey = S.route3_predation_victim or S.companion_target
        or (S.route3_grab and S.route3_grab.carried) or griffin_find_small_target_raw(40.0)
    if not prey then S.route3_predation_status = "scan: no creature nearby (fly near one, or catch it)"; status(S.route3_predation_status); return nil end
    local go = char_go(prey)
    local motion = nil
    pcall(function() motion = prey:call("get_Motion") end)
    if not motion then motion = get_component(go, "via.motion.Motion") end
    if not motion then S.route3_predation_status = "victim scan: no via.motion.Motion"; status(S.route3_predation_status); return nil end
    local minfo = nil
    pcall(function() minfo = sdk.create_instance("via.motion.MotionInfo"):add_ref() end)
    if not minfo then S.route3_predation_status = "victim scan: no MotionInfo instance"; return nil end
    local out = { time = os.date("%Y-%m-%d %H:%M:%S"), name = tostring(go_name(go) or "?"), hits = {}, all = {} }
    local seen = {}
    local function scan_bank(bank_id, bank_name)
        bank_id = tonumber(bank_id)
        if bank_id == nil or seen[bank_id] then return end
        seen[bank_id] = true
        local count = 0
        pcall(function() count = motion:getMotionCount(bank_id) end)
        for i = 0, (tonumber(count) or 0) - 1 do
            pcall(function()
                motion:call("getMotionInfoByIndex(System.UInt32, System.UInt32, via.motion.MotionInfo)", bank_id, i, minfo)
                local id = tonumber(minfo:get_MotionID())
                local name = tostring(minfo:get_MotionName() or "")
                if id ~= nil then
                    local item = { bank = bank_id, id = id, name = name, bank_name = tostring(bank_name or "") }
                    out.all[#out.all + 1] = item
                    local l = name:lower()
                    if l:find("caught", 1, true) or l:find("carry", 1, true) or l:find("struggle", 1, true)
                        or l:find("bring", 1, true) or l:find("catch", 1, true) then
                        out.hits[#out.hits + 1] = item
                    end
                end
            end)
        end
    end
    for _, holder in ipairs({ "ActiveMotionBank", "DynamicMotionBank" }) do
        local banks = nil
        pcall(function() banks = motion:call("get_" .. holder) end)
        for _, bank in ipairs(system_array_to_table(banks) or {}) do
            local bid, bname = motion_bank_label(bank)
            scan_bank(bid, bname)
        end
    end
    pcall(function() json.dump_file(MOD .. "_victim_motions.json", out) end)
    pcall(function()
        local safe = tostring(out.name or "unknown"):gsub("[^%w]", "_")
        json.dump_file(MOD .. "_victim_motions_" .. safe .. ".json", out)   -- per-species: accumulate a library
    end)
    local lines = { string.format("VICTIM %s: %d clips, %d caught/carry hits", out.name, #out.all, #out.hits) }
    for i = 1, math.min(#out.hits, 12) do
        local h = out.hits[i]
        lines[#lines + 1] = string.format("  bank %s id %s : %s", tostring(h.bank), tostring(h.id), tostring(h.name))
    end
    if #out.hits == 0 then lines[#lines + 1] = "  (no caught/carry clip in loaded banks -> needs the tape hook / restart)" end
    lines[#lines + 1] = "(full -> data/" .. MOD .. "_victim_motions.json)"
    S.route3_victim_motions = lines
    S.route3_victim_motions_at = os.date("%H:%M:%S")
    status(lines[1])
    return out
end

function griffin_predation_resolve_victim_clip(prey)
    -- Find the victim's OWN carried/struggle clip to push into the empty caught
    -- node (goblin = bank 30 id 501 carry_idle_loop_shake). Config override wins;
    -- else scan the victim's loaded banks, cached per species prefix.
    if not prey then return nil end
    local cid = math.floor(tonumber(C.route3_predation_clip_id) or -1)
    if cid >= 0 then return { bank = math.floor(tonumber(C.route3_predation_clip_bank) or 30), id = cid, name = "config override" } end
    local nm = tostring(go_name(char_go(prey)) or ""):lower()
    local prefix = nm:match("^(ch%d+)") or nm:sub(1, 6)
    S.route3_predation_clip_cache = S.route3_predation_clip_cache or {}
    local cached = S.route3_predation_clip_cache[prefix]
    if cached ~= nil then if cached == false then return nil else return cached end end
    local cat = griffin_dump_victim_motion_catalog()
    local hits = (cat and cat.hits) or {}
    local prefs = { tostring(C.route3_predation_struggle_clip_pref or ""):lower(),
        "carry_idle_loop_shake", "carry_idle_loop", "carry_loop", "struggle", "caught_carry", "carry",
        "pin_hold_attack_loop", "pin_hold_loop", "pin_hold", "pin_carry" }   -- ox = ch99_003_pin_hold_attack_loop (b30:6000), the "dangling caught" loop (tape 2026-07-13)
    local best = nil
    for _, key in ipairs(prefs) do
        if key ~= "" then
            for _, h in ipairs(hits) do
                if tostring(h.name):lower():find(key, 1, true) then best = { bank = h.bank, id = h.id, name = h.name }; break end
            end
        end
        if best then break end
    end
    S.route3_predation_clip_cache[prefix] = best or false
    return best
end

function griffin_caughtmotion_tape_sample()
    -- while the tape is armed, log the carried victim's L0 state at 4Hz so we see
    -- whether the game pushes a real clip or just advances 6001 under player carry.
    if (tonumber(S.route3_caughtmotion_tape_until) or 0.0) <= os.clock() then return end
    if os.clock() - (tonumber(S.route3_cm_sample_last) or 0.0) < 0.25 then return end
    S.route3_cm_sample_last = os.clock()
    if type(_G.griffin_cm_tape) ~= "function" then return end
    pcall(function()
        local prey = S.route3_predation_victim or S.companion_target
        if not prey then return end
        local m = prey:call("get_Motion")
        local l = m and m:call("getLayer", 0)
        if l then
            _G.griffin_cm_tape("SAMPLE", string.format("%s L0 bank=%s id=%s f=%.1f/%.1f",
                tostring(go_name(char_go(prey)) or "?"),
                tostring(l:call("get_MotionBankID")), tostring(l:call("get_MotionID")),
                tonumber(l:call("get_Frame")) or -1, tonumber(l:call("get_EndFrame")) or -1))
        end
    end)
end

function griffin_predation_drive_victim_struggle()
    -- WHY: every caught victim reaches the correct Caught node, but ONLY the real
    -- ox animates on it -- the griffin's native ox-carry drives the ox's struggle,
    -- and nothing drives any other species' (verified 2026-07-11: goblin/stag/
    -- rabbit all frozen on their correct node). Drive it ourselves each frame:
    -- keep the victim's motion advancing and ask its CaughtController to run its
    -- native struggle. Skips the real ox (self-animates); no-op when uncaught.
    -- Fable-reviewed 2026-07-11. Dedicated victim ref (S.companion_target is
    -- reassigned by the attack retargeter mid-carry); ox derived by NAME here (the
    -- attach-time flag goes stale across catch/release); EDGE-triggered w/ cooldown
    -- + cap + interp-skip (per-frame useStruggleMotion can PIN frame 0 = the very
    -- freeze we cure); bail if the transform-grab holds this same body.
    local prey = S.route3_predation_victim
    if not prey then return end
    -- HOLD-SAFE GATE (Fable 2026-07-11): when the struggle drive is disabled, do NOTHING. The
    -- OLD gate sat AFTER the think-stop + FSM-puppet + playspeed writes below, so "disabled"
    -- STILL tampered with the caught victim every frame -- which knocked it out of the native
    -- caught HOLD and dropped it out of the talon (the goblin "falls to the ground" bug). Gate FIRST.
    if C.route3_predation_struggle_enabled == false then return end
    if tostring(go_name(char_go(prey)) or ""):lower():find("ch299003", 1, true) then return end  -- ox self-animates
    local grab = S.route3_grab
    if grab and grab.carried and same_obj(prey, grab.carried) then return end
    local caught = nil
    pcall(function() caught = prey:call("get_CaughtController") end)
    if not caught then return end
    local active = false
    pcall(function() active = caught:call("get_IsActive") == true end)
    if not active then
        pcall(function() set_motion_fsm_puppet(char_go(prey), false) end)   -- restore the dropped victim's FSM
        S.route3_struggle_tries = 0; S.route3_struggle_pushed = false; S.route3_struggle_active_since = 0
        S.route3_struggle_interp_ended = false; S.route3_struggle_used_native = false
        return
    end
    -- AGGRESSIVELY un-freeze the victim's OWN motion each frame. Diagnostics proved
    -- its caught clips ARE loaded (e.g. L0=6001 L1=999) but FROZEN at frame 0 --
    -- a carried non-ox victim's motion FSM has no driver (the ox's is driven by
    -- OxCatchSetCarryedMotion). So keep it think-alive, un-pause its MotionFsm2,
    -- and pin playspeed=1 so the loaded clips actually advance. Gated behind the
    -- struggle toggle -- flip route3_predation_struggle_enabled off if it ever
    -- lets the victim wriggle free of the catch.
    local vgo = char_go(prey)
    pcall(function() set_think_stop(prey, false) end)
    -- PUPPET the victim FSM (default): with the FSM LIVE, painting L0 let the caught
    -- node advance to its RELEASE and the goblin DROPPED. Freezing the FSM holds the
    -- caught node (catch stays) while we paint L0 directly. unpuppet=true = FSM live.
    if C.route3_predation_struggle_unpuppet == true then
        pcall(function() set_motion_fsm_puppet(vgo, false) end)
    else
        pcall(function() set_motion_fsm_puppet(vgo, true) end)
    end
    pcall(function()
        local m = prey:call("get_Motion") or get_component(vgo, "via.motion.Motion")
        if m then m:call("set_PlaySpeed", tonumber(C.route3_predation_struggle_speed) or 1.0) end
    end)
    -- ===== FABLE FIX 2026-07-11: the caught clips are EMPTY, not frozen =====
    -- L0=6001 endframe=0 = a ZERO-LENGTH/missing clip (6001 isn't in the goblin's
    -- banks -- confirmed by the motion-ID catalog); playspeed/puppet/think cannot
    -- advance an empty clip. The caught node only samples the caught-motion
    -- registers ON ENTRY and never transitions (the empty clip never "ends"), so
    -- setCaughtMotion 0.35s later was never consumed. FIX: put a REAL clip on the
    -- victim's L0 directly (the proven play_griffin_motion / carry-walk pattern),
    -- guarded so we don't re-pin frame 0. The joint constraint owns the victim's
    -- transform, so a body clip on L0 can't detach it (same as the ox's clip).
    local clip = S.route3_predation_victim_clip
    if not clip then
        clip = griffin_predation_resolve_victim_clip(prey)   -- lazy (cache hit after first scan)
        S.route3_predation_victim_clip = clip
        if not clip then return end
    end
    local bank = math.floor(tonumber(clip.bank) or 30)
    local id = math.floor(tonumber(clip.id) or 501)
    local now = os.clock()
    -- settle grace: let the ~8-frame constraint interp finish first
    if (tonumber(S.route3_struggle_active_since) or 0.0) == 0.0 then S.route3_struggle_active_since = now end
    if now - (tonumber(S.route3_struggle_active_since) or now) < 0.35 then return end

    -- ONE-SHOT at settle: end the latched interpolation (interp=true forever is a
    -- SYMPTOM, but ending it is cheap and may unstick the node) + FIX 3, the
    -- untried "immediate" setCaughtMotion overload.
    if S.route3_struggle_interp_ended ~= true then
        S.route3_struggle_interp_ended = true
        -- endInterpolation is GATED off by default: it may end the catch (the drop).
        -- The direct-L0 drive plays the clip without it; flip end_interp on only to test.
        if C.route3_predation_struggle_end_interp == true then
            pcall(function() caught:call("endInterpolation") end)
            pcall(function()
                local ch0 = reacquire_griffin()
                local cc0 = ch0 and ch0:call("get_CatchController")
                if cc0 then cc0:call("endInterpolation") end
            end)
        end
    end

    -- PER-FRAME, GUARDED: put a REAL clip on the victim's L0. Only (re)push when L0
    -- isn't already our clip, or ours has finished -- an unconditional per-frame
    -- changeMotion restarts at frame 0 every frame (self-inflicted freeze).
    pcall(function()
        local m = prey:call("get_Motion") or get_component(vgo, "via.motion.Motion")
        if not m then return end
        pcall(function() m:call("set_PlayState", 0) end)   -- griffin recipe always does this; victim driver never did
        local layer = m:call("getLayer", 0)
        if not layer then return end
        local mid = tonumber(layer:call("get_MotionID")) or -1
        local endf = tonumber(layer:call("get_EndFrame")) or 0.0
        local fr = tonumber(layer:call("get_Frame")) or 0.0
        if (mid ~= id) or (endf > 0.0 and fr >= endf - 0.5) then
            layer:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                bank, id, 0.0, 8.0, 1, 1)   -- (bank, id, startF, interpF, mode, curve)
            S.route3_struggle_pushed = true
            S.route3_struggle_tries = (tonumber(S.route3_struggle_tries) or 0) + 1
        end
    end)
    -- insurance: keep the caught link's per-frame update budget alive
    pcall(function()
        local ch0 = reacquire_griffin()
        local cc0 = ch0 and ch0:call("get_CatchController")
        if cc0 then cc0:call("multiplyCaughtNextWorkRate(System.Single)", 1.0) end
    end)
    -- once our clip actually advances, ask for the native struggle dressing
    pcall(function()
        if S.route3_struggle_used_native ~= true then
            local m = prey:call("get_Motion"); local l = m and m:call("getLayer", 0)
            if l and (tonumber(l:call("get_Frame")) or 0) > 1.0 then
                S.route3_struggle_used_native = true
                pcall(function() caught:call("useStruggleMotion") end)
            end
        end
    end)
    S.route3_predation_status = string.format("struggle L0 drive b%d i%d | PINdist=%s", bank, id, tostring(S.route3_predation_pin_dist or "?"))
end

function griffin_predation_setting_for(prey)
    -- Pick the victim vocabulary by species FAMILY: ch299 wildlife (ox/deer/boar)
    -- use the proven pure-ox Setting (Caught_Default + ox carry-motion); everything
    -- else (goblins/humanoids/monsters) uses the "carry" hybrid so it plays its own
    -- struggle. This is why a deer fed the goblin's carry vocab stayed frozen.
    local nm = tostring(go_name(char_go(prey)) or ""):lower()
    if nm:find("ch299", 1, true) then return griffin_predation_build_wild_ox_setting() end
    return griffin_predation_build_hybrid_setting()
end

function griffin_predation_release_setting_for(prey)
    -- RELEASE-scoped Setting (Fable 2026-07-11). CLONE setting_for(prey) so the predation
    -- REPLAY BUTTONS keep their validated shared Setting, then tweak the copy only:
    --   Q1a: IsNoCheckCaughtStartAndCancelAction=true -> startCatch stops validating the victim's
    --        CaughtStart/CaughtCancelAction names, so a monster (goblin) whose grafted name doesn't
    --        resolve still ESTABLISHES. We abort the same beat, so it falls natively regardless.
    --        (No-op for the deer: its names already validate.)
    --   Q4:  blank the griffin's cosmetic CATCH half (Catch*, catcher-side) so the establish
    --        doesn't play her swoop-catch flap. The VICTIM's Caught* half (the natural fall) is
    --        untouched -- Catch* = catcher, Caught* = victim.
    local base = griffin_predation_setting_for(prey)
    if not base then return nil end
    local setting = nil
    pcall(function()
        setting = sdk.create_instance("app.CatchController.Setting"):add_ref()
        pcall(function() setting:call(".ctor()") end)
        local td = base:get_type_definition()
        while td do
            for _, f in ipairs(td:get_fields() or {}) do
                if not f:is_static() then
                    local n = f:get_name()
                    pcall(function() setting:set_field(n, base:get_field(n)) end)
                end
            end
            td = td:get_parent_type()
        end
        pcall(function() setting:set_field("IsNoCheckCaughtStartAndCancelAction", true) end)
        if C.route3_grab_release_blank_catcher ~= false then
            pcall(function() setting:set_field("CatchStartAction", sdk.create_managed_string("")) end)
            pcall(function() setting:set_field("CatchCancelAction", sdk.create_managed_string("")) end)
            pcall(function() setting:set_field("IsDisableCatchCancelActionOnAbort", true) end)
        end
    end)
    return setting or base
end

function griffin_predation_grab_approach_start()
    -- NATIVE grab, CLOSE ONLY (Aurora 2026-07-12): the rider flies to the prey, presses grab,
    -- and it grabs what's in reach. The homing dive is REMOVED -- both CTDs traced to
    -- dive-then-catch (catch-from-hover was always stable), and the finder picking far
    -- wildlife made her "home to nowhere". Far prey = status message, nothing else.
    if griffin_grab_active() then return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    local radius = math.max(2.0, tonumber(C.route3_predation_grab_reach) or 8.0)
    local rows = {}
    local prey = griffin_find_predation_small_target(radius, rows, C.route3_grab_allow_corpses == true)
    pcall(function()
        -- per-press candidate census (manual press only): every candidate + its skip reason,
        -- so "she ignored the goblin" reads off disk instead of needing the SCAN button.
        local lines = {}
        for _, r in ipairs(rows) do lines[#lines + 1] = r.line end
        json.dump_file(MOD .. "_grab_census.json", { time = os.date("%H:%M:%S"),
            picked = tostring(prey and go_name(char_go(prey)) or "NONE"), rows = lines })
    end)
    if not prey then
        S.route3_predation_status = string.format("grab: nothing catchable within %.0fm -- fly closer", radius)
        status("Nothing in reach to grab")
        return false
    end
    -- Defence in depth: the candidate can change state between the finder and the native Catch
    -- transaction. Never let an oversized boss chassis reach attach_probe/startCatch.
    if not route3_grab_is_grabbable(prey, C.route3_grab_allow_corpses == true) then
        S.route3_predation_status = "grab refused: target is protected or too large"
        status("That creature is too large to grab")
        return false
    end
    if is_dead(prey) then
        -- A death ragdoll cannot safely become the victim half of native Catch:
        -- CaughtController and the ragdoll both try to own the corpse transform.
        -- Reuse the proven rigid talon approach for this target only; living prey
        -- continues through attach_probe/native predation exactly as before.
        local gp = transform_pos(go)
        S.route3_grab = {
            phase = "dive", t0 = os.clock(), last = os.clock(),
            target = prey, corpse = true, native_catch = false,
            yaw = yaw_from_transform(go) or S.heading_yaw or 0.0,
            entry_y = gp and tonumber(gp.y) or 0.0,
        }
        S.route3_grab_status = "closing to snatch corpse"
        status(tostring(C.route3_griffin_name or "Griffin") .. " closes on the carcass")
        return true
    end
    -- (ox/large-prey RE-ENABLED 2026-07-12 for testing: the wing-jam after an ox carry is very
    -- likely the same stuck-FSM-node issue as the eat; toggle route3_grab_big_prefixes matching
    -- back to a refuse if it regresses badly.)
    pcall(function() griffin_grab_crash_mark("PRESS prey=" .. tostring(go_name(char_go(prey)) or "?") .. " (close grab)") end)
    return griffin_predation_attach_probe(prey, griffin_predation_setting_for(prey))
end

function griffin_battle_relationship_enemy_value()
    -- resolve app.Character.BattleRelationship's hostile value ONCE. The
    -- getRelationshipFromTo return probe suggested 1=enemy, but enums lie —
    -- read the field named Enemy/Hostile/Aggressive directly.
    if GRIFFIN_IRIS_BATTLE_ENEMY ~= nil then return GRIFFIN_IRIS_BATTLE_ENEMY end
    local found = nil
    pcall(function()
        local td = sdk.find_type_definition("app.Character.BattleRelationship")
        if not td then return end
        for _, f in ipairs(td:get_fields() or {}) do
            local n = tostring(f:get_name() or ""):lower()
            if n:find("enemy", 1, true) or n:find("hostile", 1, true) or n:find("aggress", 1, true) then
                -- LAW (postpatch-gotchas): enum fields resolve with get_data()
                -- NO ARG; get_data(nil) returned garbage in a past bug
                pcall(function() found = f:get_data() end)
                if found == nil then pcall(function() found = f:get_data(nil) end) end
                if found ~= nil then break end
            end
        end
    end)
    GRIFFIN_IRIS_BATTLE_ENEMY = found ~= nil and found or 1
    return GRIFFIN_IRIS_BATTLE_ENEMY
end

function griffin_relationship_holder()
    -- app.BattleRelationshipHolder is a get_Instance() singleton (not a via
    -- native singleton) per the method dump
    local holder = nil
    pcall(function() holder = sdk.find_type_definition("app.BattleRelationshipHolder"):get_method("get_Instance"):call(nil) end)
    if not holder then pcall(function() holder = singleton("app.BattleRelationshipHolder") end) end
    return holder
end

function griffin_force_hostile_to_target()
    -- THE damage-filter fix (2026-07-03): the hit path never queries
    -- getRelationshipFromTo(Character,Character) (rel=x0 always), so forcing
    -- that answer did nothing. Instead PERSIST a hostile relationship in the
    -- holder's own registry with requestSetBidirectionalRelationship — the
    -- same table every damage check reads.
    local gch = reacquire_griffin()
    local tch = S.companion_target
    if not (gch and tch) then return false end
    local holder = griffin_relationship_holder()
    if not holder then S.route3_attack_rel_set = "no holder"; return false end
    local enemy = griffin_battle_relationship_enemy_value()
    local ok = false
    pcall(function()
        holder:call("requestSetBidirectionalRelationship(app.Character, app.Character, app.Character.BattleRelationship)", gch, tch, enemy)
        ok = true
    end)
    if not ok then
        pcall(function()
            holder:call("requestSetRelationshipFromTo(app.Character, app.Character, app.Character.BattleRelationship)", gch, tch, enemy)
            holder:call("requestSetRelationshipFromTo(app.Character, app.Character, app.Character.BattleRelationship)", tch, gch, enemy)
            ok = true
        end)
    end
    S.route3_attack_rel_set = ok and ("hostile=" .. tostring(enemy)) or "set FAILED"
    return ok
end

function griffin_attack_assert_hate()
    local tgt_go = S.companion_target_go
    if not tgt_go then return false end
    -- persist mutual hostility in the relationship registry the DAMAGE path
    -- actually reads (the query-hook route was a dead end — rel=x0)
    pcall(function() griffin_force_hostile_to_target() end)
    -- THE MISSING REGISTRATION (combat reference probe, 2026-07-03): every
    -- character actually FIGHTING is a member of an EnemyManager
    -- BattleGroupInfo — the wild attacking griffin was registered, our
    -- ordered tame never was. registBattleGroup(app.Character) is the door.
    -- register ONCE per order: re-registering every beat reshuffles her
    -- battle group and rebuilds the AI target list in a loop = frozen statue
    -- (2026-07-03 test). Re-try only while the read-back says NO.
    pcall(function()
        if tostring(S.route3_attack_battle_reg or ""):find("members", 1, true) then return end
        local gch = reacquire_griffin()
        griffin_regist_battle_once(gch)
        griffin_regist_battle_once(S.companion_target)
    end)
    local hs = griffin_hate_system()
    if not hs then S.route3_attack_hate_ok = "no hate system"; return false end
    local ok = 0
    for _, combo in ipairs({ { 0, 0 }, { 0, 1 }, { 1, 0 }, { 0, 2 } }) do
        pcall(function()
            hs:call(
                "addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
                tgt_go, combo[1], combo[2], 1000.0, 1000.0, 0.0, 0.0
            )
            ok = ok + 1
        end)
    end
    -- MUTUAL combat: the target hates her back — retaliation is the most
    -- well-worn escalation path in the game
    pcall(function()
        local tgt_ch = S.companion_target
        local ths = tgt_ch and character_hate_system(tgt_ch, tgt_go)
        local ggo = S.griffin and char_go(S.griffin)
        if ths and ggo then
            ths:call(
                "addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
                ggo, 0, 0, 1000.0, 1000.0, 0.0, 0.0
            )
            ok = ok + 1
        end
    end)
    -- refresh her AI's target list from the hate we just wrote
    pcall(function()
        local go = S.griffin and char_go(S.griffin)
        local bb = go and get_component(go, "app.AIBlackBoardController")
        if bb then bb:call("updateEnemyTargetList") end
    end)
    -- pawns must not mob a monster-kind companion mid-order: drop the
    -- party's hate every beat — they spectate her kill
    pcall(function() clear_party_hate() end)
    -- wire the battle relationship at the manager level (threat -> combat
    -- escalation is gated by the em battle system)
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then em:call("setupBattleRelationship") end
    end)
    pcall(function() griffin_wake_natural_combat(reacquire_griffin(), S.companion_target) end)
    -- read the registration back: this line on the telemetry row is the
    -- test's verdict — "reg=members:N" means we're IN the battle bookkeeping
    S.route3_attack_battle_reg = "reg=?"
    pcall(function()
        local em = singleton("app.EnemyManager")
        local gch = reacquire_griffin()
        local info = em and gch and em:call("getBattleGroupInfo(app.Character)", gch)
        if info then
            local n = nil
            pcall(function() n = info:get_field("Members"):call("get_Count") end)
            S.route3_attack_battle_reg = "reg=members:" .. tostring(n)
        else
            S.route3_attack_battle_reg = "reg=NO"
        end
    end)
    S.route3_attack_hate_ok = "hate calls ok=" .. tostring(ok) .. "/5"
    return ok > 0
end

function griffin_set_relationship(a_ch, b_ch, enemy_or_friend, bidir)
    -- write a relationship into the holder's registry (the table combat AND
    -- damage read). enemy_or_friend: "enemy" | "friend". bidir = both ways.
    if not (a_ch and b_ch) then return false end
    local holder = griffin_relationship_holder()
    if not holder then return false end
    local val
    if enemy_or_friend == "enemy" then
        val = griffin_battle_relationship_enemy_value()
    else
        -- resolve Friend/Ally the same way the enemy value is resolved
        if GRIFFIN_IRIS_BATTLE_FRIEND == nil then
            local found = nil
            pcall(function()
                local td = sdk.find_type_definition("app.Character.BattleRelationship")
                for _, f in ipairs(td and td:get_fields() or {}) do
                    local n = tostring(f:get_name() or ""):lower()
                    if n:find("friend", 1, true) or n:find("ally", 1, true) then
                        pcall(function() found = f:get_data() end)
                        if found == nil then pcall(function() found = f:get_data(nil) end) end
                        if found ~= nil then break end
                    end
                end
            end)
            GRIFFIN_IRIS_BATTLE_FRIEND = found ~= nil and found or 2
        end
        val = GRIFFIN_IRIS_BATTLE_FRIEND
    end
    local ok = false
    if bidir then
        pcall(function()
            holder:call("requestSetBidirectionalRelationship(app.Character, app.Character, app.Character.BattleRelationship)", a_ch, b_ch, val)
            ok = true
        end)
    end
    if not ok then
        pcall(function()
            holder:call("requestSetRelationshipFromTo(app.Character, app.Character, app.Character.BattleRelationship)", a_ch, b_ch, val)
            if bidir then holder:call("requestSetRelationshipFromTo(app.Character, app.Character, app.Character.BattleRelationship)", b_ch, a_ch, val) end
            ok = true
        end)
    end
    return ok
end

function griffin_escalate_combat(gch, tgt_go)
    -- THE THREAT->ATTACK ESCALATION (2026-07-05): the dump proved she DOES accrue
    -- hate but stalls in the aerial THREAT display (Ch253ThreatAir). Push her over
    -- with the griffin's OWN combat machinery: max the anger gauge + force the
    -- enraged state (threat -> enrage -> attack). Only re-anger if she is not
    -- already angry (no roar-loop). Read back her decision module + rage state +
    -- combat-status flag so we SEE whether the escalation actually flips her.
    gch = gch or reacquire_griffin()
    if not gch then return false end
    local csc = nil
    pcall(function() csc = gch:get_field("<CombatStateControl>k__BackingField") end)
    if not csc then pcall(function() csc = gch:call("get_CombatStateControl") end) end
    local is_angry, attitude, cstate = "?", "?", "?"
    if csc then
        local angry = false
        pcall(function() angry = csc:call("get_IsAngry") == true end)
        if not angry then
            pcall(function() if csc:call("get_IsEnableRequsetAngry") == true then csc:call("increaseAngryGaugeMax") end end)
            pcall(function() csc:call("startAngryForce") end)
        end
        pcall(function() is_angry = tostring(csc:call("get_IsAngry")) end)
        pcall(function() attitude = tostring(csc:call("isActiveAngryAttitude")) end)
        pcall(function()
            local flag = csc:call("get_CombatStatusFlag")
            if flag then cstate = tostring(flag:get_field("Data")) end
        end)
    end
    local mod = "?"
    pcall(function()
        local adm = get_component(char_go(gch), "app.AIDecisionMaker")
        if adm then mod = tostring(adm:call("get_CurrentModuleType")) end
    end)
    S.route3_escalate = string.format("angry=%s attitude=%s cstate=%s module=%s  hate>enemy=%s hate>YOU=%s rank=%s",
        is_angry, attitude, cstate, mod,
        tostring(S.route3_hate_total or "?"), tostring(S.route3_hate_player or "?"),
        tostring(S.route3_hate_rank or "?"))
    return true
end

function griffin_provoke_from_target(gch, tgt)
    -- NATIVE AGGRO the way a WILD griffin actually gets it. The combat_real dump
    -- showed a fighting griffin carries a ForceDamageInfo (it was just HIT) + real
    -- hate; our synthetic addHateParam reads as ~0 and never triggers a fight. So
    -- FORGE the provocation: build a damage record whose ATTACKER is the goblin and
    -- feed it to HER hate system -> she believes the goblin struck her -> she fights
    -- back with her own AI, picking her own attack. No driving, no puppeting.
    gch = gch or reacquire_griffin()
    local ggo = gch and char_go(gch)
    local tgo = tgt and char_go(tgt)
    local hs = gch and character_hate_system(gch, ggo)
    if not (hs and ggo and tgo) then S.route3_provoke = "provoke: no actors"; return false end
    local di = nil
    pcall(function() di = sdk.create_instance("app.HitController.DamageInfo") end)
    if not di then pcall(function() di = sdk.create_instance("app.HitController.DamageInfo", true) end) end
    if not di then S.route3_provoke = "provoke: no DamageInfo"; return false end
    -- the goblin is the ATTACKER, she is the VICTIM (mirror of our own hit packet)
    pcall(function() di:set_field("<AttackGameObject>k__BackingField", tgo) end)
    pcall(function() di:set_field("<AttackOwnerObject>k__BackingField", tgo) end)
    pcall(function() di:set_field("<DamageGameObject>k__BackingField", ggo) end)
    -- FULL BLOW PACKET (match the real fighting griffin's ForceDamageInfo: ~50 blow dmg,
    -- IsBlowAttack, BlownReactionRate, AttackVec). A toothless 1-dmg packet bumped hate
    -- but never STAGGERED her into combat -- a real hit carries a blow.
    pcall(function() di:set_field("Damage", 50.0) end)
    pcall(function() di:set_field("FixedDamage", 50.0) end)
    pcall(function() di:set_field("BlowDamage", 50.0) end)
    pcall(function() di:set_field("IsBlowAttack", true) end)
    pcall(function() di:set_field("BlownReactionRate", 1.0) end)
    pcall(function()
        local gp, tp = transform_pos(ggo), transform_pos(tgo)
        if gp and tp then
            di:set_field("AttackVec", make_vec3((tonumber(gp.x) or 0.0) - (tonumber(tp.x) or 0.0), 0.0,
                (tonumber(gp.z) or 0.0) - (tonumber(tp.z) or 0.0)))
        end
    end)
    local hits = {}
    pcall(function() hs:call("set_ForceDamageInfo(app.HitController.DamageInfo)", di); hits[#hits + 1] = "force" end)
    -- THE COMBAT-ENTRY IGNITION the old provoke never called: onReceiveForce +
    -- applyAngryGaugeByDamage push the ANGRY/combat state machine (the R2-grab analog).
    pcall(function() hs:call("onReceiveForce(app.HitController.DamageInfo)", di); hits[#hits + 1] = "recvForce" end)
    pcall(function()
        local csc = gch:get_field("<CombatStateControl>k__BackingField")
        if not csc then csc = gch:call("get_CombatStateControl") end
        if csc then csc:call("applyAngryGaugeByDamage(app.HitController.DamageInfo)", di); hits[#hits + 1] = "angryDmg" end
    end)
    pcall(function() hs:call("onDamageReaction(app.HitController.DamageInfo)", di); hits[#hits + 1] = "react" end)
    -- onUnbalance = the GRAB/stagger signal (what made her attack the PLAYER when
    -- grabbed). Now that the goblin is a real enemy (faction fixed), fire it FROM the
    -- goblin so her AI treats it as a live attacker and engages -- the same reaction
    -- the grab produced, aimed at the goblin. (args: pos, unbalancer, unbalanced.)
    pcall(function()
        local gp = transform_pos(tgo)
        if gp then
            local pos = make_vec3(tonumber(gp.x) or 0.0, tonumber(gp.y) or 0.0, tonumber(gp.z) or 0.0)
            hs:call("onUnbalance(via.vec3, via.GameObject, via.GameObject)", pos, tgo, ggo)
            hits[#hits + 1] = "unbal"
        end
    end)
    pcall(function() hs:call("updateHateRanking"); hits[#hits + 1] = "rank" end)
    pcall(function() hs:call("updateHateTrackRequest"); hits[#hits + 1] = "track" end)
    S.route3_provoke = "provoke: " .. table.concat(hits, ",") .. " rank=" .. tostring(griffin_hate_rank_count(hs))
    return #hits > 0
end

function griffin_seat_enemy_target(gch, tgt)
    -- SEAT the goblin directly into her AI's ENEMY ACTION-TARGET LIST + recompute
    -- her approach positions. Her hate ranking is populated but her
    -- EnemyActionTargetList / _AIPositionTargetDict (the WHERE-to-go positions her
    -- ThinkTable brain walks to) are empty, so she has no enemy AITarget to resolve
    -- into an approach = she idles. The engine's OWN GameObject->AITarget converter
    -- builds the AITarget for us (we NEVER hand-build app.AITargetGameObject, which
    -- would null-crash on the next AI update). Every call is pcall-guarded; the
    -- generic-List construction is the one real crash surface (.ctor before Add).
    local ggo = gch and char_go(gch)
    local tgo = tgt and char_go(tgt)
    local bb = ggo and get_component(ggo, "app.AIBlackBoardController")
    if not (bb and tgo) then S.route3_seat = "seat: no bb/tgt"; return false end
    local el0, pd0 = -1, -1
    pcall(function() el0 = tonumber(bb:call("get_EnemyActionTargetList"):call("get_Count")) or -1 end)
    pcall(function() pd0 = tonumber(bb:get_field("_AIPositionTargetDict"):call("get_Count")) or -1 end)
    local srcList, mkinfo = nil, "?"
    local makers = {
        { "ci2", function() return sdk.create_instance("System.Collections.Generic.List`1<via.GameObject>", true) end },
        { "ci1", function() return sdk.create_instance("System.Collections.Generic.List`1<via.GameObject>") end },
        { "td2", function() local td = sdk.find_type_definition("System.Collections.Generic.List`1<via.GameObject>"); return td and td:create_instance(true) end },
        { "td1", function() local td = sdk.find_type_definition("System.Collections.Generic.List`1<via.GameObject>"); return td and td:create_instance() end },
    }
    for _, m in ipairs(makers) do
        if not srcList then
            pcall(function() local l = m[2](); if l then srcList = l:add_ref(); mkinfo = m[1] end end)
        end
    end
    if not srcList then S.route3_seat = string.format("seat: NO LIST [ci/td all failed] (el=%d pd=%d)", el0, pd0); return false end
    pcall(function() srcList:call(".ctor()") end)
    local added = false
    pcall(function() srcList:call("Add(via.GameObject)", tgo); added = true end)
    if not added then pcall(function() srcList:call("Add", tgo); added = true end) end
    if not added then S.route3_seat = "seat: add failed"; return false end
    local seated = false
    pcall(function()
        local dst = bb:call("get_EnemyActionTargetList")
        if dst then
            bb:call("updateSourceActionTargetListFromEnemiesEnumerable(System.Collections.Generic.List`1<via.GameObject>, System.Collections.Generic.List`1<app.AITarget>)", srcList, dst)
            seated = true
        end
    end)
    pcall(function() bb:call("setupAITargetPosition") end)
    local el1, pd1 = -1, -1
    pcall(function() el1 = tonumber(bb:call("get_EnemyActionTargetList"):call("get_Count")) or -1 end)
    pcall(function() pd1 = tonumber(bb:get_field("_AIPositionTargetDict"):call("get_Count")) or -1 end)
    S.route3_seat = string.format("seat=%s[%s]  enemyList %d->%d  posDict %d->%d", seated and "ok" or "FAIL", mkinfo, el0, el1, pd0, pd1)
    return seated
end

function griffin_focus_hate_tick()
    -- THE RiftSpeak [FOCUS] BREAKTHROUGH, ported: a companion's combat target
    -- follows HATE DOMINANCE, and the AI re-ranks ~60x/sec, so a 1Hz hate write
    -- gets out-competed and decays = no committed target (our hate>enemy kept
    -- reading 0). Re-assert DOMINANT hate on the target EVERY FRAME with the exact
    -- proven recipe: wipe all hate, then slam the target to the top with FarDamage/
    -- Overwrite and the trailing SUSTAIN values (9999,9999,9999,60 -- we'd been
    -- zeroing the last two). This is what makes RiftSpeak's [FOCUS] hold.
    local tgt = S.companion_target
    local tgo = S.companion_target_go or (tgt and char_go(tgt))
    if not tgo then return false end
    local hs = griffin_hate_system()
    if not hs then return false end
    pcall(function() hs:call("clearAllHate") end)
    pcall(function()
        hs:call("addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
            tgo, 2, 1, 9999.0, 9999.0, 9999.0, 60.0)
    end)
    pcall(function() hs:call("updateHateRanking") end)
    S.route3_focus_rank = griffin_hate_rank_count(hs)
    return true
end


function griffin_set_combat_target(gch, tgo)
    -- BMI-style targeting port: mark the goblin as the griffin's _LastDamageHitObject
    -- (via EnemyCtrl.Ch2) so her target/retaliation system engages it -- the mod's
    -- actual mechanism. Paired with the TargetType=19 hook. (The mod lives in a data/
    -- subfolder so REFramework never loaded it; we replicate it here.)
    if not (gch and tgo) then S.route3_combat_target = "ct: no actors"; return false end
    local ok = false
    pcall(function()
        local ec = gch:get_field("EnemyCtrl")
        if not ec then pcall(function() ec = gch:call("get_EnemyCtrl") end) end
        if not ec then S.route3_combat_target = "ct: no EnemyCtrl"; return end
        local ch2 = ec:get_field("Ch2")
        if not ch2 then pcall(function() ch2 = ec:call("get_Ch2") end) end
        if not ch2 then S.route3_combat_target = "ct: no Ch2"; return end
        pcall(function() ch2:set_field("_LastDamageHitObject", tgo); ok = true end)
        S.route3_combat_target = ok and "ct: set" or "ct: set failed"
    end)
    return ok
end

function griffin_group_hash_value(hctx, ggc)
    -- GroupHash is a boxed Nullable<uint>: get_field returns a FRESH box each frame
    -- (address flickers "like crazy"), so unwrap to the actual number for a stable
    -- readout. party=2385506540, wild-monster=1895570358.
    -- The METHOD getters (get_GroupHash/get_GroupHashProp) return a Nullable<uint>
    -- that REFramework mis-marshals to 1 (the HasValue byte) -- THAT was "GROUP=1".
    -- Read the box FIELD's _Value directly (the recipe route3_dump_ally_probe uses).
    local out = nil
    pcall(function()
        local box = ggc and ggc:get_field("GroupHash")
        if box then
            local v = box:get_field("_Value")
            if v == nil then v = box:get_field("Value") end
            if type(v) == "number" then out = v end
        end
    end)
    if type(out) == "number" then return math.floor(out) end
    return -1
end

function griffin_ai_state_diag(gch)
    -- Aurora's hypothesis: her AI "shuts down after the initial animations". READ
    -- her actual live brain state every frame -- if think-stop is ON, or the
    -- decision-maker/nav is DISABLED, or the FSM is PUPPETED, her AI is frozen and
    -- no amount of hate can make a corpse fight. This tells us WHICH (if any).
    gch = gch or reacquire_griffin()
    local go = gch and char_go(gch)
    if not go then return end
    local ts, adm, nav, pup, spd = "?", "?", "?", "?", "?"
    -- think-stop: a failed method read returns nil and LIES ("nil" looked like false
    -- all session). Try the method, then fall back to the backing field.
    pcall(function() ts = tostring(gch:call("get_IsThinkStop")) end)
    if ts == "nil" then pcall(function() ts = tostring(gch:get_field("<IsThinkStop>k__BackingField")) end) end
    pcall(function() local c = get_component(go, "app.AIDecisionMaker"); if c then adm = tostring(c:call("get_Enabled")) end end)
    pcall(function() local c = get_component(go, "app.NavigationAI"); if c then nav = tostring(c:call("get_Enabled")) end end)
    -- PUPPET: use the SAME type the SETTER uses (via.motion.MotionFsm2). The old read
    -- queried "app.MotionFsm2" (wrong type) so puppet ALWAYS read nil AND was never even
    -- printed -> we were blind to a puppet-freeze the whole time. THIS is the field to watch.
    pcall(function()
        local fsm = get_component(go, "via.motion.MotionFsm2")
        if fsm then
            local pm = nil
            pcall(function() pm = fsm:call("get_PuppetMode") end)
            if pm == nil then pcall(function() pm = fsm:get_field("<PuppetMode>k__BackingField") end) end
            pup = tostring(pm)
        end
    end)
    -- MOTION PLAY SPEED: 0 = frozen animation even while the FSM node advances to Attack01.
    pcall(function() local m = gch:call("get_Motion"); if m then spd = tostring(m:call("get_PlaySpeed")) end end)
    -- POSITION DELTA since last frame (mm): ~0 while unleashed = she is PINNED / not
    -- physically moving -- the decisive "is she actually stuck" readout.
    local moved = "?"
    pcall(function()
        local p = transform_pos(go)
        if p and tonumber(p.x) then
            local lp = S.route3_ai_last_pos
            if lp then
                local dx = (tonumber(p.x) or 0.0) - lp.x
                local dy = (tonumber(p.y) or 0.0) - lp.y
                local dz = (tonumber(p.z) or 0.0) - lp.z
                moved = string.format("%.0f", math.sqrt(dx * dx + dy * dy + dz * dz) * 1000.0)
            end
            S.route3_ai_last_pos = { x = tonumber(p.x) or 0.0, y = tonumber(p.y) or 0.0, z = tonumber(p.z) or 0.0 }
        end
    end)
    local grp = griffin_group_hash_value(route3_ally_group_ctx(gch))
    local el = -1
    pcall(function()
        local bb = get_component(go, "app.AIBlackBoardController")
        if bb then el = tonumber(bb:call("get_EnemyActionTargetList"):call("get_Count")) or -1 end
    end)
    S.route3_ai_state = string.format("GROUP=%s  enemyList=%s (0->1=sees goblin)  [think=%s AI=%s Nav=%s PUPPET=%s spd=%s moved=%smm/f]",
        tostring(grp), tostring(el), ts, adm, nav, pup, spd, moved)
end

function griffin_unleash_point_hate()
    -- lightweight target-pointing for unleash: make HER hate the target.
    -- Battle registration is handled separately so it can be toggled while
    -- we test native combat. Also scrub party hate toward her each beat.
    local tgt_go = S.companion_target_go
    local gch, ggo = reacquire_griffin()
    if not (tgt_go and gch) then return end
    pcall(function()
        local hs = griffin_hate_system()
        if hs then
            hs:call("addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
                tgt_go, 0, 0, 1000.0, 1000.0, 0.0, 0.0)
        end
    end)
    pcall(function()
        local bb = ggo and get_component(ggo, "app.AIBlackBoardController")
        if bb then bb:call("updateEnemyTargetList") end
    end)
    -- the party must not treat her as prey: wipe their hate toward her each beat
    pcall(function() clear_party_hate() end)
    -- Nail the target as dominant hate with the RIGHT category: the dump revealed
    -- Provoke=5 / Overwrite=1 (we had been spraying Distance=0 = the wrong bucket).
    local hs2 = griffin_hate_system()
    pcall(function()
        hs2:call("addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
            tgt_go, 5, 1, 3000.0, 3000.0, 0.0, 0.0)
    end)
    -- addHateParam only stacked her goblin-hate to ~12 (read via getTotalHate) --
    -- far too low to trigger native PURSUIT (she hovers instead of flying to it).
    -- setForceTotalHate OVERWRITES the accumulated total, so slam it sky-high and
    -- let her own predator instinct pull her toward the target. Pure AI.
    pcall(function()
        hs2:call("setForceTotalHate(via.GameObject, System.Nullable`1<System.Single>, System.Nullable`1<System.Single>, System.Nullable`1<System.Single>)",
            tgt_go, 9000.0, 9000.0, 9000.0)
    end)
    -- Aurora's catch: strip her hate toward the friend-shielded player/pawns so
    -- the ENEMY is her only (and therefore top) hate target, not a friend she
    -- can't attack. Runs every beat (proximity re-adds friend hate constantly).
    pcall(function() clear_griffin_hate_toward_party() end)
    S.route3_hate_rank = griffin_hate_rank_count(hs2)
    S.route3_hate_total = -1
    S.route3_hate_player = -1
    pcall(function() S.route3_hate_total = tonumber(hs2:call("getTotalHate(via.GameObject)", tgt_go)) or -1 end)
    pcall(function() S.route3_hate_player = tonumber(hs2:call("getTotalHate(via.GameObject)", char_go(get_player()))) or -1 end)
    -- She has hate but stalls in the THREAT display -> force the enrage escalation
    -- every beat (the native threat -> attack path) + read her state back.
    pcall(function() griffin_escalate_combat(gch, tgt_go) end)
end

function griffin_battle_group_status(ch)
    local info = nil
    pcall(function()
        local em = singleton("app.EnemyManager")
        info = em and ch and em:call("getBattleGroupInfo(app.Character)", ch)
    end)
    if not info then return false, "reg=NO", 0 end
    local n = nil
    pcall(function() n = info:get_field("Members"):call("get_Count") end)
    return true, "reg=members:" .. tostring(n), tonumber(n) or 0
end

function griffin_regist_battle_once(ch)
    if not ch then return false, "reg=no actor" end
    local present, status_text = griffin_battle_group_status(ch)
    if present then return true, status_text end
    local ok = false
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then em:call("registBattleGroup(app.Character)", ch); ok = true end
    end)
    local _, after = griffin_battle_group_status(ch)
    return ok, after
end

function griffin_unleash_register_battle(gch, target)
    if C.route3_unleash_register_battle ~= true then
        S.route3_unleash_battle_reg = "reg=off"
        return false
    end
    if not (gch and target) then
        S.route3_unleash_battle_reg = "reg=no actors"
        return false
    end
    local ok = false
    pcall(function()
        local em = singleton("app.EnemyManager")
        if not em then return end
        local gok = griffin_regist_battle_once(gch)
        local tok = griffin_regist_battle_once(target)
        em:call("setupBattleRelationship")
        ok = gok or tok
    end)
    S.route3_unleash_battle_reg = ok and "reg=requested" or "reg=failed"
    pcall(function()
        local _, st = griffin_battle_group_status(gch)
        S.route3_unleash_battle_reg = st
    end)
    return ok
end

function route3_proxy_delete(reason)
    if S.route3_proxy_spawner then pcall(function() S.route3_proxy_spawner:deleteAll() end) end
    S.route3_proxy_spawner = nil
    S.route3_proxy_pending = false
    S.route3_proxy = nil
    S.route3_proxy_go = nil
    S.route3_proxy_target = nil
    S.route3_proxy_target_go = nil
    S.route3_proxy_started = 0.0
    S.route3_proxy_hate_at = 0.0
    S.route3_proxy_action = "(none)"
    S.route3_proxy_action_history = {}
    S.route3_proxy_attack_count = 0
    S.route3_proxy_last_attack_at = 0.0
    S.route3_proxy_mode = "nearest"
    S.route3_proxy_status = reason or "proxy=idle"
    status(S.route3_proxy_status)
    return true
end

function route3_proxy_reacquire()
    if S.route3_proxy and char_go(S.route3_proxy) and not is_dead(S.route3_proxy) then
        S.route3_proxy_go = char_go(S.route3_proxy)
        return S.route3_proxy, S.route3_proxy_go
    end
    if S.route3_proxy_spawner and S.route3_proxy_spawner.instances then
        for i = #S.route3_proxy_spawner.instances, 1, -1 do
            local inst = S.route3_proxy_spawner.instances[i]
            local ch = nil
            pcall(function() ch = inst.instance and inst.instance:get_Chara() end)
            if ch and not is_dead(ch) then
                S.route3_proxy = ch
                S.route3_proxy_go = char_go(ch)
                S.route3_proxy_pending = false
                S.route3_proxy_status = "proxy=live"
                return S.route3_proxy, S.route3_proxy_go
            end
        end
    end
    return nil, nil
end

function route3_proxy_friend_shield(proxy_ch)
    proxy_ch = proxy_ch or S.route3_proxy
    if not proxy_ch then return false end
    pcall(function() griffin_set_relationship(proxy_ch, get_player(), "friend", true) end)
    pcall(function()
        local pm = singleton("app.PawnManager")
        for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
            local list = nil
            pcall(function() list = pm and pm:call(getter) end)
            local n = tonumber(list and list:call("get_Count")) or 0
            for i = 0, n - 1 do
                local pawn = nil
                pcall(function() pawn = list:call("get_Item", i) end)
                if pawn then griffin_set_relationship(proxy_ch, pawn, "friend", true) end
            end
        end
    end)
    return true
end

function route3_proxy_hate_system()
    return character_hate_system(S.route3_proxy, S.route3_proxy_go)
end

function route3_party_hate_system(hs)
    if not hs then return false end
    if same_obj(hs, character_hate_system(get_player(), char_go(get_player()))) then return true end
    local pm = singleton("app.PawnManager")
    if not pm then return false end
    for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
        local list = nil
        pcall(function() list = pm:call(getter) end)
        local n = tonumber(list and list:call("get_Count")) or 0
        for i = 0, n - 1 do
            local pawn = nil
            pcall(function() pawn = list:call("get_Item", i) end)
            if pawn and same_obj(hs, character_hate_system(pawn, char_go(pawn))) then return true end
        end
    end
    return false
end

function route3_proxy_scale_value()
    local scale = tonumber(C.route3_proxy_combat_scale)
    if not scale or scale <= 0.0 then
        local gch, ggo = reacquire_griffin()
        pcall(function()
            local tf = ggo and ggo:call("get_Transform")
            local cur = tf and tf:call("get_LocalScale")
            if cur and tonumber(cur.x) and tonumber(cur.x) > 0.05 then scale = tonumber(cur.x) end
        end)
    end
    if not scale or scale <= 0.0 then scale = tonumber(C.spawn_scale) or tonumber(C.route3_tame_scale) or 0.75 end
    if scale < 0.15 then scale = 0.15 end
    if scale > 1.5 then scale = 1.5 end
    return scale
end

function route3_proxy_apply_scale(proxy_ch)
    local go = proxy_ch and char_go(proxy_ch)
    if not go then return false end
    local scale = route3_proxy_scale_value()
    local ok = false
    pcall(function()
        local tf = go:call("get_Transform")
        if tf then
            tf:call("set_LocalScale", make_vec3(scale, scale, scale))
            ok = true
        end
    end)
    return ok
end

function route3_proxy_target_distance(proxy_ch, target)
    local pgo = proxy_ch and char_go(proxy_ch)
    local tgo = target and char_go(target)
    local pp = pgo and transform_pos(pgo)
    local tp = tgo and transform_pos(tgo)
    if not (pp and tp) then return nil end
    local dx = (tonumber(pp.x) or 0.0) - (tonumber(tp.x) or 0.0)
    local dy = (tonumber(pp.y) or 0.0) - (tonumber(tp.y) or 0.0)
    local dz = (tonumber(pp.z) or 0.0) - (tonumber(tp.z) or 0.0)
    return math.sqrt(dx * dx + dy * dy + dz * dz), pp, tp
end

function route3_proxy_push_nav_to_target(proxy_ch, target)
    local pgo = proxy_ch and char_go(proxy_ch)
    local tgo = target and char_go(target)
    local tpos = tgo and transform_pos(tgo)
    if not (proxy_ch and pgo and tpos) then return false end
    local nav = get_navigation_ai(proxy_ch)
    local ctrl = get_navigation_controller(proxy_ch)
    local dest = make_position(tpos.x, tpos.y, tpos.z)
    local ok = false
    if nav then
        pcall(function() nav:call("set_IsStopCalled", false) end)
        pcall(function() nav:call("setNavigationPos", make_vec3(dest.x, dest.y, dest.z)); ok = true end)
        pcall(function() nav:call("navigationRequest(via.vec3)", make_vec3(dest.x, dest.y, dest.z)); ok = true end)
    end
    if ctrl then
        pcall(function() ctrl:call("setDestination(via.Position)", dest); ok = true end)
        if not ok then pcall(function() ctrl:call("setDestination", dest); ok = true end) end
    end
    return ok
end

function route3_proxy_force_hate(proxy_ch, target)
    local pgo = proxy_ch and char_go(proxy_ch)
    local tgo = target and char_go(target)
    if not (proxy_ch and pgo and target and tgo) then return false end
    route3_proxy_apply_scale(proxy_ch)
    set_think_stop(proxy_ch, false)
    set_motion_fsm_puppet(pgo, false)
    stop_navigation(proxy_ch, false)
    route3_proxy_friend_shield(proxy_ch)
    clear_party_hate()
    pcall(function()
        local hs = character_hate_system(proxy_ch, pgo)
        if hs then hs:call("clearAllHate") end
    end)
    pcall(function() griffin_set_relationship(proxy_ch, target, "enemy", true) end)
    pcall(function() griffin_regist_battle_once(proxy_ch) end)
    pcall(function() griffin_regist_battle_once(target) end)
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then em:call("setupBattleRelationship") end
    end)
    local ok = 0
    pcall(function()
        local hs = character_hate_system(proxy_ch, pgo)
        if hs then
            -- BMI hate recipe: FarDamage=2 / Overwrite=1 + sustain values (not the old
            -- Distance=0 / zeroed trailing params that never held).
            hs:call("addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
                tgo, 2, 1, 9999.0, 9999.0, 9999.0, 60.0)
            pcall(function() hs:call("updateHateRanking") end)
            ok = ok + 1
        end
    end)
    pcall(function()
        local ths = character_hate_system(target, tgo)
        if ths then
            ths:call("addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
                pgo, 2, 1, 9999.0, 9999.0, 9999.0, 60.0)
            pcall(function() ths:call("updateHateRanking") end)
            ok = ok + 1
        end
    end)
    -- BMI targeting port for the proxy: mark the goblin as its _LastDamageHitObject so
    -- the shared TargetType=19 hook engages it (the mod's actual targeting mechanism).
    pcall(function() griffin_set_combat_target(proxy_ch, tgo) end)
    pcall(function()
        local bb = get_component(pgo, "app.AIBlackBoardController")
        if bb then bb:call("updateEnemyTargetList") end
    end)
    pcall(function() route3_proxy_push_nav_to_target(proxy_ch, target) end)
    S.route3_proxy_status = "proxy=hate " .. tostring(ok) .. "/2"
    return ok > 0
end

function route3_proxy_tick()
    if not S.route3_proxy_spawner then return false end
    local proxy_ch, proxy_go = route3_proxy_reacquire()
    local target = S.route3_proxy_target
    if S.route3_proxy_pending == true then
        S.route3_proxy_status = "proxy=pending"
        return true
    end
    if not proxy_ch then
        route3_proxy_delete("proxy=lost")
        return true
    end
    if not target or griffin_target_is_dead(target) then
        route3_proxy_delete("proxy=target dead")
        return true
    end
    if os.clock() - (tonumber(S.route3_proxy_started) or 0.0) > math.max(10.0, tonumber(C.route3_proxy_combat_timeout) or 90.0) then
        route3_proxy_delete("proxy=timeout")
        return true
    end
    local pdist = route3_proxy_target_distance(proxy_ch, target)
    local tether = math.max(12.0, tonumber(C.route3_proxy_combat_tether_distance) or 45.0)
    local max_dist = math.max(tether + 5.0, tonumber(C.route3_proxy_combat_max_distance) or 90.0)
    if pdist and pdist > max_dist then
        route3_proxy_delete(string.format("proxy=fled %.1fm", tonumber(pdist) or 0.0))
        return true
    end
    if pdist and pdist > tether then
        pcall(function() route3_proxy_push_nav_to_target(proxy_ch, target) end)
        S.route3_proxy_status = string.format("proxy=tether %.1fm", tonumber(pdist) or 0.0)
    end
    if os.clock() - (tonumber(S.route3_proxy_hate_at) or 0.0) > 1.0 then
        S.route3_proxy_hate_at = os.clock()
        route3_proxy_force_hate(proxy_ch, target)
        pcall(function()
            local fsm = "(?)"
            local csc = proxy_ch:get_field("<CombatStateControl>k__BackingField")
            if csc then
                local flag = csc:get_field("<CombatStatusFlag>k__BackingField")
                if flag then fsm = "cstate=" .. tostring(flag:get_field("Data")) end
            end
            local dist_txt = pdist and string.format(" dist=%.1fm", tonumber(pdist) or 0.0) or ""
            local elapsed = os.clock() - (tonumber(S.route3_proxy_started) or os.clock())
            local attacks = tonumber(S.route3_proxy_attack_count) or 0
            local patience = math.max(2.0, tonumber(C.route3_proxy_native_patience) or 8.0)
            local mood = (attacks > 0) and ("attacks=" .. tostring(attacks))
                or ((elapsed > patience) and "posturing" or "watching")
            S.route3_proxy_status = tostring(S.route3_proxy_status)
                .. dist_txt .. " " .. fsm
                .. " action=" .. tostring(S.route3_proxy_action or "?")
                .. " " .. mood
        end)
    end
    return true
end

function griffin_wake_natural_combat(gch, target, force_action)
    if C.route3_natural_combat_wake ~= true then
        S.route3_natural_wake = "wake=off"
        return false
    end
    gch = gch or reacquire_griffin()
    if not gch then
        S.route3_natural_wake = "wake=no griffin"
        return false
    end
    local hits = 0
    local detail = {}
    pcall(function()
        local bsc = gch:get_field("BattleStateCtrl")
        if not bsc then bsc = gch:call("get_BattleStateCtrl") end
        if bsc then
            bsc:set_field("<IsDetectArisenParty>k__BackingField", true)
            hits = hits + 1
            detail[#detail + 1] = "detectParty"
            -- These already match the wild griffin in the dump, but asserting
            -- them keeps reclaimed bodies from carrying odd controller state.
            pcall(function() bsc:set_field("CharaControllerType", 1) end)
            pcall(function() bsc:set_field("_CautionReactionTypeHash", 3038677550) end)
        end
    end)
    pcall(function()
        local csc = gch:get_field("<CombatStateControl>k__BackingField")
        if not csc then csc = gch:call("get_CombatStateControl") end
        if csc then
            csc:set_field("<StopNatualDecreaseStamina>k__BackingField", false)
            hits = hits + 1
            detail[#detail + 1] = "staminaNatural"
            local flag = csc:get_field("<CombatStatusFlag>k__BackingField")
            if flag then
                -- 0 was the observed idle value. Do not invent an enum here;
                -- just clear stale previous status and let the combat tree pick.
                pcall(function() flag:set_field("PrevData", 0) end)
            end
        end
    end)
    pcall(function()
        local go = char_go(gch)
        local bb = go and get_component(go, "app.AIBlackBoardController")
        if bb then
            bb:call("updateEnemyTargetList")
            hits = hits + 1
            detail[#detail + 1] = "bb"
        end
    end)
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then
            em:call("updateBattleGroupInfo(System.Single)", 0.016)
            hits = hits + 1
            detail[#detail + 1] = "emUpdate"
        end
    end)
    if target then pcall(function() griffin_set_relationship(gch, target, "enemy", true) end) end
    local fsm = tostring(S.last_fsm_node or "")
    local active_attack = fsm:lower():find("attack", 1, true) ~= nil
        or fsm:lower():find("damage", 1, true) ~= nil
        or fsm:lower():find("catch", 1, true) ~= nil
    -- "stuck" now also covers the aerial NON-attack combat states she loops in
    -- (hover/turn-to-target/threat/idle): her native AI engages then just hovers
    -- and never pulls the trigger on a lone ground target, so we force her OWN
    -- attack move on the wake cadence. She still plays her real gale/flight
    -- attack animation -- we only decide WHEN, not puppet HOW.
    local flo = fsm:lower()
    local stuck_locomotion = fsm == "" or fsm == "(unknown)"
        or flo:find("locomotion", 1, true) ~= nil
        or flo:find("wait", 1, true) ~= nil
        or flo:find("hover", 1, true) ~= nil
        or flo:find("turn", 1, true) ~= nil
        or flo:find("threat", 1, true) ~= nil
        or flo:find("idle", 1, true) ~= nil
    local now = os.clock()
    -- UNLEASHED: tight cadence + ATTACK-ONLY nodes. Her AI hovers indefinitely, so
    -- pull the trigger often and only on moves that actually strike -- the gale
    -- blast and the dive-slam -- not the takeoff/neutral filler in the config list.
    -- 'active_attack' gates re-fire, so this never interrupts her mid-swing.
    local unleashed = S.route3_unleashed == true
    local retry = unleashed and 2.0 or math.max(1.5, tonumber(C.route3_natural_wake_action_period) or 6.0)
    local due = force_action == true or ((not active_attack) and stuck_locomotion
        and now - (tonumber(S.route3_natural_wake_action_at) or 0.0) >= retry)
    if due then
        S.route3_natural_wake_action_at = now
        local node
        if unleashed then
            -- NO forced attacks: the proxy proved a monster-team griffin with the
            -- relationship override + TargetType=19 + hate fights NATURALLY (posture,
            -- gale gust, knockdown, stomp). Forcing nodes was the ugly fly/crash cycle.
            node = nil
        else
            node = griffin_attack_node_from_list(
                C.route3_natural_wake_action_nodes,
                "route3_natural_wake_node_index",
                "CombatStateNormal"
            )
        end
        if node then
            local leaf = tostring(node):match("([^%.]+)$") or tostring(node)
            pcall(function() request_griffin_action(leaf, 4) end)
            if leaf ~= "CombatStateNormal" then
                pcall(function() request_griffin_action(leaf, 0) end)
            end
            if tostring(node):find(".", 1, true) then
                pcall(function() set_griffin_fsm_node_silent(node, 0) end)
            else
                pcall(function() set_griffin_fsm_node_silent("Locomotion.SwitchBattleMode", 0) end)
            end
            detail[#detail + 1] = "wakeAction:" .. tostring(node)
        end
    end
    S.route3_natural_wake = string.format("wake=%d %s", hits, table.concat(detail, ","))
    return hits > 0
end

function griffin_natural_damage_assist_tick()
    if C.route3_natural_damage_assist ~= true then
        S.route3_natural_damage_status = "assist=off"
        return false
    end
    -- ⛔ STAND DOWN during the mounted ground attacks (2026-08-08, Aurora: "the damage is
    -- happening literally at button press rather than at impact"): this assist drains the
    -- target the moment an attack ACTION begins -- it killed the foe at press, so the gatk's
    -- properly-timed impact (damage + sound + flinch at the tuned frame) found only a corpse
    -- and stayed silent. The timed systems own their own damage.
    if griffin_gatk_active() or griffin_gust_active() or griffin_gustair_active()
        or griffin_dogfight_active() then
        S.route3_natural_damage_status = "assist=standdown (timed attack owns damage)"
        return false
    end
    local gch, go = reacquire_griffin()
    local tgt = S.companion_target
    local tgo = S.companion_target_go or char_go(tgt)
    if not (gch and go and tgt and tgo) then
        S.route3_natural_damage_status = "assist=no actors"
        return false
    end
    pcall(function() read_griffin_fsm_node() end)
    local fsm = tostring(S.last_fsm_node or "")
    local live_action = tostring(S.route3_attack_live_action or "")
    local forced_node = ""
    if os.clock() < (tonumber(S.route3_attack_hold_until) or 0.0) + 0.2 then
        forced_node = tostring(S.route3_attack_last_forced_node or "")
    end
    local probe = table.concat({ fsm, live_action, forced_node }, " ")
    local lo = probe:lower()
    local attackish = lo:find("attack", 1, true) ~= nil
        or lo:find("catch", 1, true) ~= nil
        or lo:find("damage", 1, true) ~= nil
        or lo:find("rush", 1, true) ~= nil
        or lo:find("swoop", 1, true) ~= nil
        or lo:find("gale", 1, true) ~= nil
        or lo:find("press", 1, true) ~= nil
        or lo:find("default", 1, true) ~= nil
    if not attackish then
        S.route3_natural_damage_status = "assist=waiting fsm=" .. fsm .. " action=" .. live_action
        return false
    end
    local gp, tp = transform_pos(go), transform_pos(tgo)
    local d2 = distance_sq(gp, tp)
    if not d2 then return false end
    local range = math.max(3.0, tonumber(C.route3_natural_damage_range) or 9.0)
    -- UNLEASHED aerial combat: her gale blast is a ranged wind attack and she
    -- strikes from the air, so a tight ground range would whiff on a technicality.
    -- Give the hit a generous reach so an aimed aerial attack actually connects.
    if S.route3_unleashed == true then range = math.max(range, 22.0) end
    local dist = math.sqrt(d2)
    S.route3_natural_damage_dist = math.floor(dist * 10) / 10
    if dist > range then
        S.route3_natural_damage_status = string.format("assist=out %.1fm fsm=%s action=%s", dist, fsm, live_action)
        return false
    end
    local now = os.clock()
    local period = math.max(0.35, tonumber(C.route3_natural_damage_period) or 1.4)
    if now - (tonumber(S.route3_natural_damage_at) or 0.0) < period then
        return false
    end
    S.route3_natural_damage_at = now
    local before = nil
    pcall(function() before = griffin_read_target_hp(tgt) end)
    local ok = false
    pcall(function() ok = griffin_apply_damage_to_target(C.route3_attack_damage_per_hit or 60.0) == true end)
    local after = nil
    pcall(function() after = griffin_read_target_hp(tgt) end)
    S.route3_natural_damage_hits = (tonumber(S.route3_natural_damage_hits) or 0) + (ok and 1 or 0)
    S.route3_natural_damage_status = string.format(
        "assist=%s %.1fm fsm=%s action=%s hp=%s>%s",
        ok and "hit" or "fail",
        dist,
        fsm,
        live_action,
        tostring(before or "?"),
        tostring(after or "?")
    )
    return ok
end

function route3_aerial_attack_clear(reason)
    S.route3_aerial_attack = nil
    S.route3_aerial_status = reason or "idle"
    S.route3_aerial_phase = nil
    S.route3_companion_moving = false
    S.airborne = false
    S.flying = false
end

function route3_aerial_ground_y(pos)
    if not pos then return nil end
    local y = tonumber(pos.y) or 0.0
    local hit = route3_cast_ground_below(tonumber(pos.x) or 0.0, y + 6.0, tonumber(pos.z) or 0.0, 12.0, 80.0)
    return hit and tonumber(hit.y) or y
end

function route3_aerial_move_to(gch, go, dest, face_pos, step)
    local pos = go and transform_pos(go)
    if not (gch and go and pos and dest) then return false, 9999.0 end
    local dx = (tonumber(dest.x) or 0.0) - (tonumber(pos.x) or 0.0)
    local dy = (tonumber(dest.y) or 0.0) - (tonumber(pos.y) or 0.0)
    local dz = (tonumber(dest.z) or 0.0) - (tonumber(pos.z) or 0.0)
    local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
    local max_step = math.max(0.05, tonumber(step) or 1.0)
    local scale = dist > max_step and (max_step / dist) or 1.0
    local nx = (tonumber(pos.x) or 0.0) + dx * scale
    local ny = (tonumber(pos.y) or 0.0) + dy * scale
    local nz = (tonumber(pos.z) or 0.0) + dz * scale
    local fdx, fdz = dx, dz
    if face_pos then
        fdx = (tonumber(face_pos.x) or nx) - nx
        fdz = (tonumber(face_pos.z) or nz) - nz
    end
    local rot = make_quat_yaw(math.atan(fdx, fdz))
    local new_pos = make_position(nx, ny, nz)
    pcall(function() set_transform(go, new_pos, rot) end)
    pcall(function() set_character_transform(gch, new_pos, rot) end)
    S.route3_companion_moving = true
    S.airborne = true
    S.flying = true
    return dist <= max_step, dist
end

function route3_aerial_frame_step(st, speed, scale)
    local now = os.clock()
    local last = tonumber(st and st.last_tick) or now
    local dt = now - last
    if dt < 0.008 then dt = 0.016 end
    if dt > 0.05 then dt = 0.05 end
    if st then st.last_tick = now end
    return math.max(0.03, (tonumber(speed) or 8.0) * dt * (tonumber(scale) or 1.0))
end

function route3_aerial_attack_start(gch, go, tgt, tgo, agpos, tpos, adist)
    local now = os.clock()
    S.route3_aerial_attack = {
        phase = "rise",
        started = now,
        phase_at = now,
        last_tick = now,
        hit = false,
        dir_x = 0.0,
        dir_z = 1.0,
        launch_x = tonumber(agpos.x) or 0.0,
        launch_y = tonumber(agpos.y) or 0.0,
        launch_z = tonumber(agpos.z) or 0.0,
    }
    local dx = (tonumber(tpos.x) or 0.0) - (tonumber(agpos.x) or 0.0)
    local dz = (tonumber(tpos.z) or 0.0) - (tonumber(agpos.z) or 0.0)
    local len = math.sqrt(dx * dx + dz * dz)
    if len > 0.001 then
        S.route3_aerial_attack.dir_x = dx / len
        S.route3_aerial_attack.dir_z = dz / len
    end
    S.route3_aerial_status = string.format("swoop=rise %.1fm", tonumber(adist) or 0.0)
    S.route3_aerial_phase = "rise"
    S.route3_attack_air_at = now
    play_griffin_motion(math.floor(tonumber(C.route3_aerial_attack_takeoff_clip) or 5210), 0, true)
    return true
end

function route3_aerial_attack_finish(gch, go, tpos)
    local st = S.route3_aerial_attack
    local dx = st and tonumber(st.dir_x) or 0.0
    local dz = st and tonumber(st.dir_z) or 1.0
    local lx = st and tonumber(st.launch_x) or (tonumber(tpos.x) or 0.0) - dx * 4.0
    local lz = st and tonumber(st.launch_z) or (tonumber(tpos.z) or 0.0) - dz * 4.0
    local ly = route3_aerial_ground_y(make_position(lx, st and tonumber(st.launch_y) or tonumber(tpos.y) or 0.0, lz))
        or st and tonumber(st.launch_y)
        or tonumber(tpos.y)
        or 0.0
    local land = make_position(lx, ly + (tonumber(C.route3_ground_follow_offset) or 0.0), lz)
    local rot = make_quat_yaw(math.atan(-dx, -dz))
    pcall(function() set_transform(go, land, rot) end)
    pcall(function() set_character_transform(gch, land, rot) end)
    pcall(function() play_griffin_motion(tonumber(C.landing_end_motion) or 5032, 0, true) end)
    S.route3_aerial_cooldown_at = os.clock()
    S.route3_aerial_status = "swoop=done"
    route3_aerial_attack_clear("swoop=done")
end

function route3_aerial_attack_tick(gch, go, tgt, tgo, agpos, tpos, adist)
    if C.route3_aerial_attack_enabled ~= true then
        if S.route3_aerial_attack then route3_aerial_attack_clear("swoop=off") end
        return false
    end
    if not (gch and go and tgt and tgo and agpos and tpos) then
        route3_aerial_attack_clear("swoop=no actors")
        return false
    end
    local now = os.clock()
    local st = S.route3_aerial_attack
    local min_dist = math.max(4.0, tonumber(C.route3_aerial_attack_min_distance) or 10.0)
    local cooldown = math.max(1.0, tonumber(C.route3_aerial_attack_cooldown) or 9.0)
    if not st then
        if (tonumber(adist) or 0.0) < min_dist then return false end
        if now - (tonumber(S.route3_aerial_cooldown_at) or -999.0) < cooldown then return false end
        route3_aerial_attack_start(gch, go, tgt, tgo, agpos, tpos, adist)
        st = S.route3_aerial_attack
    end
    if not st then return false end

    local height = math.max(3.0, tonumber(C.route3_aerial_attack_height) or 9.0)
    local dive_h = math.max(0.5, tonumber(C.route3_aerial_attack_dive_height) or 1.4)
    local recover_h = math.max(2.0, tonumber(C.route3_aerial_attack_recover_height) or 5.0)
    local speed = math.max(1.0, tonumber(C.route3_aerial_attack_step) or 8.0)
    local ground_y = route3_aerial_ground_y(tpos) or tonumber(tpos.y) or 0.0
    local phase = tostring(st.phase or "rise")
    S.route3_aerial_phase = phase

    if now - (tonumber(st.started) or now) > 12.0 then
        route3_aerial_attack_finish(gch, go, tpos)
        return true
    end

    if phase == "rise" then
        local dest = make_position(tonumber(agpos.x) or 0.0, ground_y + height, tonumber(agpos.z) or 0.0)
        local done, dist = route3_aerial_move_to(gch, go, dest, tpos, route3_aerial_frame_step(st, speed, 0.65))
        S.route3_aerial_status = string.format("swoop=rise %.1fm", tonumber(dist) or 0.0)
        if done or now - (tonumber(st.phase_at) or now) > 1.4 then
            st.phase = "approach"
            st.phase_at = now
            play_griffin_motion(math.floor(tonumber(C.route3_aerial_attack_glide_clip) or 5190), 0, true)
        end
        return true
    end

    if phase == "approach" then
        local dest = make_position(tonumber(tpos.x) or 0.0, ground_y + height, tonumber(tpos.z) or 0.0)
        local _, dist = route3_aerial_move_to(gch, go, dest, tpos, route3_aerial_frame_step(st, speed, 1.0))
        S.route3_aerial_status = string.format("swoop=approach %.1fm", tonumber(dist) or 0.0)
        local gp = transform_pos(go)
        local hdx = gp and ((tonumber(tpos.x) or 0.0) - (tonumber(gp.x) or 0.0)) or 999.0
        local hdz = gp and ((tonumber(tpos.z) or 0.0) - (tonumber(gp.z) or 0.0)) or 999.0
        local hdist = math.sqrt(hdx * hdx + hdz * hdz)
        if hdist < 7.0 or now - (tonumber(st.phase_at) or now) > 3.5 then
            st.phase = "dive"
            st.phase_at = now
            local node = tostring(C.route3_aerial_attack_strike_node or "")
            if node ~= "" then griffin_swing_once(node) end
        end
        return true
    end

    if phase == "dive" then
        local dest = make_position(tonumber(tpos.x) or 0.0, ground_y + dive_h, tonumber(tpos.z) or 0.0)
        local _, dist = route3_aerial_move_to(gch, go, dest, tpos, route3_aerial_frame_step(st, speed, 1.35))
        local gp = transform_pos(go)
        local d2 = gp and distance_sq(gp, tpos) or nil
        local pass_dist = d2 and math.sqrt(d2) or dist
        S.route3_aerial_dist = math.floor((tonumber(pass_dist) or 0.0) * 10) / 10
        S.route3_aerial_status = string.format("swoop=dive %.1fm", tonumber(pass_dist) or 0.0)
        local hit_range = math.max(1.5, tonumber(C.route3_aerial_attack_hit_range) or 4.5)
        if st.hit ~= true and pass_dist <= hit_range then
            st.hit = true
            S.route3_aerial_hits = (tonumber(S.route3_aerial_hits) or 0) + 1
            local dmg = (tonumber(C.route3_attack_damage_per_hit) or 60.0)
                * math.max(0.1, tonumber(C.route3_aerial_attack_damage_scale) or 1.5)
            pcall(function() griffin_apply_damage_to_target(dmg) end)
            S.route3_aerial_status = string.format("swoop=hit %.1fm", tonumber(pass_dist) or 0.0)
        end
        if pass_dist < 1.8 or now - (tonumber(st.phase_at) or now) > 2.2 then
            st.phase = "recover"
            st.phase_at = now
        end
        return true
    end

    if phase == "recover" then
        local lx = tonumber(st.launch_x) or (tonumber(tpos.x) or 0.0)
        local lz = tonumber(st.launch_z) or (tonumber(tpos.z) or 0.0)
        local ly = route3_aerial_ground_y(make_position(lx, tonumber(st.launch_y) or ground_y, lz)) or ground_y
        local dest = make_position(lx, ly + recover_h, lz)
        local done, dist = route3_aerial_move_to(gch, go, dest, tpos, route3_aerial_frame_step(st, speed, 0.9))
        S.route3_aerial_status = string.format("swoop=recover %.1fm", tonumber(dist) or 0.0)
        if done or now - (tonumber(st.phase_at) or now) > 1.6 then
            route3_aerial_attack_finish(gch, go, tpos)
        end
        return true
    end

    route3_aerial_attack_clear("swoop=bad phase")
    return false
end

function griffin_target_gone(tgt)
    -- "no valid target anymore" for the unleash auto-recall decision. A target whose
    -- GameObject was destroyed (despawn/cull) keeps a live managed ref but is_dead
    -- reads false -- so we ALSO treat a nil GO / nil position as gone. Without this
    -- the combat beat keeps firing native calls on a dangling target (AV crash class)
    -- and never routes to find-next-or-recall.
    if not tgt then return true end
    if griffin_target_is_dead(tgt) then return true end
    local tgo = char_go(tgt)
    if not tgo then return true end
    if not transform_pos(tgo) then return true end
    return false
end

function griffin_unleash_striking()
    -- true while we are force-driving her combat strike clip (the combat-phase idle
    -- fallback) -- lets the wing-pose systems stand down like they do for the swoop.
    return (tonumber(S.route3_unleash_strike_until) or 0.0) > os.clock()
end

function griffin_unleash_enter_combat()
    -- ARRIVAL: she's been flown to the target -- now hand off to her NATIVE combat
    -- AI. Her "won't pursue, fights in place" limitation stops mattering because
    -- she IS in place, on top of the foe. Ignite exactly like the proxy: free body,
    -- reset the action/AI machine ONCE, friend-shield you, forge the provocation.
    local gch, go = reacquire_griffin()
    local tgt = S.companion_target
    if not (gch and go) then return false end
    S.route3_unleash_phase = "combat"
    S.route3_unleash_combat_at = os.clock()
    S.route3_unleash_approach = nil
    S.route3_unleash_far_since = nil
    -- prime a quick FIRST strike on arrival: native won't engage a tamed body even
    -- point-blank (enemyList stays 0), so WE drive the fight from the first beat.
    S.route3_unleash_last_native_atk = os.clock() - 1.0
    S.route3_unleash_strike_playing = false
    -- native AI owns her position now: drop every drive pin + flight flag
    S.drive_pos = nil; S.drive_rot = nil
    S.route3_air_pos = nil; S.route3_air_rot = nil
    S.airborne = false; S.flying = false
    S.route3_companion_moving = false
    S.audition_until_clock = 0.0
    -- FULLY free her body -- her native combat AI drives the fight
    restore_disabled()
    set_think_stop(gch, false)
    stop_navigation(gch, false)
    set_motion_fsm_puppet(go, false)
    set_griffin_motion_speed(1.0)
    -- re-init her action/AI state machine ONCE on the just-arrived body. She was
    -- being DRIVEN (pacified), not mid native-swing, so this is the safe window --
    -- resetting a mid-action body is the known native-crash class.
    pcall(function() gch:call("resetActionAndAI") end)
    -- break the approach's looped flap clip so she settles to idle instead of holding
    -- the spread-wing glide pose; from here the strike cycle drives her (native won't engage)
    pcall(function() stop_griffin_animation() end)
    -- friend-shield the player + every pawn so a kind-8 monster never turns on you
    pcall(function() griffin_set_relationship(gch, get_player(), "friend", true) end)
    pcall(function()
        local pm = singleton("app.PawnManager")
        for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
            local list = nil
            pcall(function() list = pm and pm:call(getter) end)
            local n = tonumber(list and list:call("get_Count")) or 0
            for i = 0, n - 1 do
                local pawn = nil
                pcall(function() pawn = list:call("get_Item", i) end)
                if pawn then griffin_set_relationship(gch, pawn, "friend", true) end
            end
        end
    end)
    -- ignite: target enemy + battle bookkeeping + hate + forged provocation
    if tgt then
        pcall(function() griffin_set_relationship(gch, tgt, "enemy", true) end)
        pcall(function() griffin_unleash_register_battle(gch, tgt) end)
        pcall(function() griffin_wake_natural_combat(gch, tgt, true) end)
        pcall(function() griffin_provoke_from_target(gch, tgt) end)
    end
    pcall(function() griffin_unleash_point_hate() end)
    if not S.route3_hate_ai_dumped then pcall(function() griffin_dump_hate_ai() end) end
    status(tostring(C.route3_griffin_name or "Companion") .. " strikes!")
    return true
end

function griffin_unleash_approach_tick()
    -- APPROACH: fly her to the target the same way the whistle fly-in flies her to
    -- the player -- pacified + transform-driven + flapping, OVER the terrain
    -- (airborne = she can't snag on scenery, the fly-over cheat). At strike range
    -- she settles in and native combat lights up. THIS supplies the one thing her
    -- AI refuses to do: travel to a lone target.
    local gch = reacquire_griffin()
    local go = gch and char_go(gch)
    local tgt = S.companion_target
    local tgo = S.companion_target_go or (tgt and char_go(tgt))
    if not (gch and go and tgt and tgo) then return false end
    local gpos = transform_pos(go)
    local tpos = transform_pos(tgo)
    if not (gpos and tpos) then return false end

    -- give-up timeout: if she can't reach the target (unreachable perch, target
    -- fled endlessly, etc.) return to the player rather than fly at it forever
    -- (the whistle fly-in had a 25s cap for the same reason).
    local st = S.route3_unleash_approach
    if type(st) ~= "table" then st = { last_tick = os.clock() }; S.route3_unleash_approach = st end
    if not st.t0 then st.t0 = os.clock() end
    if os.clock() - st.t0 > (tonumber(C.route3_unleash_approach_timeout) or 20.0) then
        griffin_recall()
        return false
    end

    local engage = tonumber(C.route3_unleash_engage_range) or 4.0
    local dxh = (tonumber(tpos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
    local dzh = (tonumber(tpos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
    local hdist = math.sqrt(dxh * dxh + dzh * dzh)

    -- real ground under the target. The ray works in RENDER space (universal x/z
    -- carry a tile offset up to 1152m -> a km-away probe), so cast at the TARGET's
    -- render x/z via route3_ground_hit_under; Y is shared between the two spaces.
    local ghit = route3_ground_hit_under(tgo)
    local tground = (ghit and tonumber(ghit.y)) or (tonumber(tpos.y) or 0.0)

    if hdist <= engage then
        -- ARRIVED: face the target, settle onto its ground, hand to native combat
        local face = make_quat_yaw(math.atan(dxh, dzh))
        local landed = make_position(tonumber(gpos.x) or 0.0, tground, tonumber(gpos.z) or 0.0)
        pcall(function() set_transform(go, landed, face) end)
        pcall(function() set_character_transform(gch, landed, face) end)
        griffin_unleash_enter_combat()
        return true
    end

    -- cruise high while far, ease down to the target's ground over the last 15m
    local clearance = tonumber(C.route3_unleash_cruise_clear) or 5.0
    local ease = math.min(1.0, hdist / 15.0)
    local dest = make_position(tonumber(tpos.x) or 0.0, tground + clearance * ease, tonumber(tpos.z) or 0.0)

    -- FLY toward it with an eased INLINE step (mirrors the PROVEN whistle fly-in).
    -- Deliberately NOT route3_aerial_move_to: that sets S.airborne=true, which wakes
    -- the airborne flight/wing systems on an unmounted body and re-pins her every
    -- frame -> she flaps in place and never travels (the test-2 "moved=0mm/f" symptom).
    S.airborne = false
    S.flying = false
    local step = route3_aerial_frame_step(st, tonumber(C.route3_unleash_approach_speed) or 16.0, 1.0)
    local dx = (tonumber(dest.x) or 0.0) - (tonumber(gpos.x) or 0.0)
    local dy = (tonumber(dest.y) or 0.0) - (tonumber(gpos.y) or 0.0)
    local dz = (tonumber(dest.z) or 0.0) - (tonumber(gpos.z) or 0.0)
    local d3 = math.sqrt(dx * dx + dy * dy + dz * dz)
    if d3 > 0.001 then
        local sc = math.min(step, d3) / d3
        local face = make_quat_yaw(math.atan(dxh, dzh))
        local npos = make_position((tonumber(gpos.x) or 0.0) + dx * sc,
            (tonumber(gpos.y) or 0.0) + dy * sc, (tonumber(gpos.z) or 0.0) + dz * sc)
        pcall(function() set_transform(go, npos, face) end)
        pcall(function() set_character_transform(gch, npos, face) end)
    end

    -- keep the flap alive so she reads as flying. Re-play only every ~3.5s (the clip
    -- runs ~4.5s) so it doesn't visibly restart every second (the "spamming the same
    -- animation" symptom). Most approaches finish before the first re-play.
    if (tonumber(S.route3_unleash_flap_at) or 0.0) + 3.5 < os.clock() then
        S.route3_unleash_flap_at = os.clock()
        pcall(function() play_griffin_motion(math.floor(tonumber(C.flap_takeoff_clip) or 5210), 0, true) end)
    end
    S.route3_unleash_status = string.format("flying in %.0fm", hdist)
    return true
end

function griffin_unleash_combat_strike_tick()
    -- THE FIGHT. Native combat won't commit on a tamed body even delivered to point-
    -- blank (in-game: fsm=Locomotion.Wait, enemyList=0, cstate=0 -- she never
    -- classifies the target as an enemy). So WE run the whole fight (Aurora's
    -- "translator"): a repeated lunge-strike cycle on the delivered target --
    --   FIRE: face it, play her real bank-50 clip (audition + wing-suppress), land the
    --         PROVEN swoop damage; then hold the strike window, then
    --   RECOVER: stop the (looping) clip -> back to idle (else she freezes in the loop),
    --   WAIT idle_force, repeat -- until it's dead (the beat retargets/recalls).
    if C.route3_unleash_strike_fallback == false then return false end
    local now = os.clock()
    local strike_until = tonumber(S.route3_unleash_strike_until) or 0.0
    -- RECOVERY: the strike window ended -> stop the looping clip, settle to idle
    if S.route3_unleash_strike_playing == true and now >= strike_until then
        S.route3_unleash_strike_playing = false
        pcall(function() stop_griffin_animation() end)
    end
    if S.route3_unleash_strike_playing == true then return true end   -- mid-strike: let it play
    local gch, go = reacquire_griffin()
    local tgt = S.companion_target
    local tgo = S.companion_target_go or (tgt and char_go(tgt))
    if not (gch and go and tgt and tgo) then return false end
    local gp, tp = transform_pos(go), transform_pos(tgo)
    if not (gp and tp) then return false end
    local d2 = distance_sq(gp, tp)
    local dist = d2 and math.sqrt(d2) or 999.0
    local engage = tonumber(C.route3_unleash_engage_range) or 4.0
    if dist > engage + 6.0 then return false end   -- too far: the re-approach flies her back
    -- NO native deference. Native combat never actually EXECUTES on a tamed body: it
    -- enters an attack node (e.g. Ch253WingWindAttackStartLoop) then FREEZES in the
    -- windup (enemyList=0, no committed target). The old code stood down whenever the
    -- fsm name contained "attack" -> it waited forever on that frozen node = deadlock
    -- ("nothing happens" when unleashed point-blank). We ALWAYS drive the strike now.
    local idle_for = now - (tonumber(S.route3_unleash_last_native_atk) or 0.0)
    if idle_for < (tonumber(C.route3_unleash_idle_force) or 1.2) then return false end
    -- FIRE a strike: face the target, play her real bank-50 clip over the idle pose,
    -- land the PROVEN swoop damage (griffin_hp_from_component + updateDamageHp cascade;
    -- griffin_apply_damage_to_target used to read Hp=0 and no-op).
    local dxh = (tonumber(tp.x) or 0.0) - (tonumber(gp.x) or 0.0)
    local dzh = (tonumber(tp.z) or 0.0) - (tonumber(gp.z) or 0.0)
    pcall(function()
        local face = make_quat_yaw(math.atan(dxh, dzh))
        set_transform(go, gp, face)
        set_character_transform(gch, gp, face)
    end)
    local clip = math.floor(tonumber(C.route3_unleash_strike_clip) or 511)
    local bank = math.floor(tonumber(C.route3_unleash_strike_bank) or 50)
    local dur = math.max(0.4, tonumber(C.route3_unleash_strike_duration) or 0.85)
    pcall(function() play_griffin_motion(clip, bank, true) end)
    S.route3_unleash_strike_playing = true
    S.route3_unleash_strike_until = now + dur
    S.audition_until_clock = now + dur + 0.15
    S.route3_unleash_last_native_atk = now
    pcall(function() griffin_apply_attack_damage(tgt, tonumber(C.route3_attack_damage_per_hit) or 120.0) end)
    S.route3_unleash_status = string.format("STRIKE %.1fm  %s", dist, tostring(S.route3_swoop_last_dmg or "?"))
    return true
end

function griffin_unleash()
    -- FULL COMBAT MODE: stop puppeting — let her NATIVE monster AI fly, swoop
    -- and snatch prey. We restore her monster identity + stand every one of
    -- our peace systems down (relationship/action/hate hooks, calm burst,
    -- root-motion skip, order driver), keep the PLAYER + PARTY protected via
    -- forced-friendly relationships, point her at a target, and get out of
    -- the way. RECALL leashes her back to companion.
    if S.mounted == true then status("dismount before unleashing"); return false end
    local gch, go = reacquire_griffin()
    if not (gch and go) then status("no companion to unleash"); return false end
    local target = griffin_find_prey_or_enemy(60.0)
    if not target then status("no enemy or prey in range to unleash on"); return false end
    S.companion_order = nil
    S.route3_companion_moving = false
    S.route3_whistle_flyin = nil
    -- CLEAR THE PIN: a stale drive/air transform forces her back every frame
    -- (= "walk cycle on the spot"). Her native AI owns position now.
    S.drive_pos = nil
    S.drive_rot = nil
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    S.airborne = false
    S.flying = false
    S.route3_follow_clip = nil
    -- cancel any pending ally-rejoin: it calls route3_ally_join_party which
    -- would stomp our kind-8 back to kind 2 mid-hunt (= she reverts to a
    -- peaceful party member and just postures)
    S.route3_ally_auto_at = 0.0
    S.route3_ally_calm_until = 0.0
    S.companion_target = target
    S.companion_target_go = char_go(target)
    S.route3_unleashed = true
    S.route3_unleash_started = os.clock()
    pcall(function() griffin_tamed_save() end)
    -- ensure her original MONSTER identity is on record; if this session
    -- never ally-joined (so we lack the monster hashes) she stays kind 8
    -- with whatever group she has — still her monster AI
    -- ALIGNMENT FIX (Aurora's insight 2026-07-05): a griffin and a goblin are BOTH
    -- "enemy" faction, so the game aligns them as ALLIES and she will NOT attack it
    -- (proven: grabbing her makes her attack the PLAYER -- a DIFFERENT faction --
    -- while she ignores the same-faction goblin). Put her on the PLAYER's faction
    -- (which IS hostile to goblins) but keep kind=8 so she still fights like an
    -- aggressive monster, then recompute battle relationships from the new group.
    pcall(function()
        local hctx, ggc = route3_ally_group_ctx(gch)
        if hctx then hctx:set_field("CharacterKind", 8) end
        S.route3_unleash_group = 2385506540
        -- COMBAT-ENTRY FIX (investigation 2026-07-05, converged): a STATIC tamed body
        -- enters combat ONLY when its detector PERCEIVES a hostile enemy. On the monster
        -- team the goblin is same-faction = ally = NEVER perceived (why she idled). Put
        -- her on the PLAYER faction so the monster-faction goblin becomes a genuine
        -- CROSS-faction enemy she detects -> IsDetectArisenParty latches -> she enters
        -- combat. BONUS: same group as the player = she can't aggro YOU. (The proxy only
        -- tolerates the monster team because it spawned already-combat-active.)
        local _, sgc = route3_ally_group_ctx(get_player())
        if ggc and sgc then
            for _, f in ipairs({ "GroupHash", "DefaultGroupHash" }) do
                local srcbox = nil
                pcall(function() srcbox = sgc:get_field(f) end)
                if srcbox then pcall(function() ggc:set_field(f, srcbox) end) end
            end
        end
    end)
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then em:call("setupBattleRelationship") end
    end)
    pcall(function()
        local bb = get_component(char_go(gch), "app.AIBlackBoardController")
        if bb then bb:call("updateEnemyTargetList") end
    end)
    -- Don't ignite combat yet: FLY HER TO THE TARGET first (the one thing her AI
    -- won't do -- pursue a lone foe). Pacify + drive her in as a flight; on arrival
    -- griffin_unleash_enter_combat frees her body and lights up native combat AT the
    -- target, where "fights in place" = "fights the goblin".
    pacify_griffin(nil)
    stop_navigation(gch, true)
    set_griffin_motion_speed(1.0)
    S.route3_unleash_phase = "approach"
    S.route3_unleash_approach = { last_tick = os.clock() }
    S.route3_unleash_flap_at = 0.0
    S.route3_unleash_far_since = nil
    pcall(function() play_griffin_motion(math.floor(tonumber(C.flap_takeoff_clip) or 5210), 0, true) end)
    pcall(function() route3_flap_seek(tonumber(C.flap_seg_start) or 138.0) end)
    status(tostring(C.route3_griffin_name or "Companion") .. " takes wing -- inbound!")
    return true
end






-- ============================================================================
-- COMBAT REFERENCE PROBE: the attack-escalation investigation tool.
-- Dump once during a REAL wild fight (spawn a wild griffin near goblins, let
-- nature take its course) and once during our ORDERED attack. The diff between
-- the two files IS the missing battle registration.
-- ============================================================================

function griffin_hp_from_component(comp)
    -- pull a current-HP number out of a health/hitpoint component: try the
    -- common getters, then any field named current/now/value/hp
    if not comp then return nil end
    for _, m in ipairs({ "get_CurrentHitPoint", "get_Current", "get_CurrentHp", "get_Hp", "get_HP",
        "get_Value", "get_Now", "get_NowHitPoint", "getCurrentHitPoint" }) do
        local v = nil
        pcall(function() v = comp:call(m) end)
        if tonumber(v) then return tonumber(v) end
    end
    local out = nil
    pcall(function()
        local td = comp:get_type_definition()
        while td and not out do
            for _, f in ipairs(td:get_fields() or {}) do
                local ln = tostring(f:get_name() or ""):lower()
                if ln:find("current", 1, true) or ln == "_hp" or ln == "hp" or ln:find("nowhitpoint", 1, true)
                    or (ln:find("hitpoint", 1, true) and not ln:find("max", 1, true)) then
                    local v = nil
                    pcall(function() v = comp:get_field(f:get_name()) end)
                    if tonumber(v) then out = tonumber(v); break end
                end
            end
            td = td:get_parent_type()
        end
    end)
    return out
end

function griffin_target_is_dead(tch)
    -- robust death check: get_IsDead/get_Hp often lag on enemies. The real
    -- fight dumps showed a slain enemy sits in FSM Damage.*.Die* — that's the
    -- reliable signal she must stop pecking the corpse on.
    if not tch then return true end
    if is_dead(tch) then return true end
    local dead = false
    pcall(function()
        local go = char_go(tch)
        local fsm = go and get_motion_fsm(go)
        local node = fsm and fsm:call("getCurrentNodeName", 0)
        local n = tostring(node or ""):lower()
        if n:find("die", 1, true) or n:find("dead", 1, true) or n:find("collapse", 1, true) then dead = true end
    end)
    if dead then return true end
    -- HP read (now that the reader is stronger): 0 or less = gone
    local hp = griffin_read_target_hp(tch)
    if hp ~= "?" and tonumber(hp) and tonumber(hp) <= 0 then return true end
    return false
end

function griffin_target_hit_controller(tch)
    -- app.HitController is the DAMAGE authority (target dump confirmed: it
    -- carries get_Hp()=650 AND setHp/updateDamage). char.get_HitController
    -- first, then the component.
    if not tch then return nil end
    local hc = nil
    pcall(function() hc = tch:call("get_HitController") end)
    if not hc then hc = get_component(char_go(tch), "app.HitController") end
    return hc
end

function griffin_read_target_hp(tch)
    -- KNOWN path (target dump): app.HitController.get_Hp(). Character get_Hp
    -- as backup. No broad getter-scan (that risked a native crash mid-call).
    if not tch then return "?" end
    local hc = griffin_target_hit_controller(tch)
    local hp = nil
    if hc then pcall(function() hp = hc:call("get_Hp") end) end
    if not tonumber(hp) then pcall(function() hp = tch:call("get_Hp") end) end
    return tonumber(hp) and tostring(math.floor(tonumber(hp))) or "?"
end

function griffin_apply_damage_to_target(amount)
    -- DIRECT DAMAGE: her native attack colliders are shrunk and never connect
    -- (round 96), so on each swing we drain the target's HP ourselves via the
    -- HitController's own setHp — the game's HP monitor triggers death at 0.
    local tch = S.companion_target
    if not tch then
        S.route3_attack_damage_status = "damage=no target"
        return false
    end
    if griffin_target_is_dead(tch) then
        S.route3_attack_damage_status = "damage=target dead"
        return false
    end
    local hc = griffin_target_hit_controller(tch)
    if not hc then
        S.route3_attack_damage_status = "damage=no HitController"
        return false
    end
    local hp = nil
    pcall(function() hp = hc:call("get_Hp") end)
    hp = tonumber(hp)
    if not hp then
        S.route3_attack_damage_status = "damage=no hp read"
        return false
    end
    local new = math.max(0.0, hp - (tonumber(amount) or 60.0))
    local ok = false
    local after = hp
    local tried = {}
    local function read_after(label)
        local rb = nil
        pcall(function() rb = hc:call("get_Hp") end)
        rb = tonumber(rb)
        tried[#tried + 1] = tostring(label) .. ":" .. tostring(rb or "?")
        if rb and rb < hp then
            after = rb
            ok = true
            return true
        end
        return false
    end
    -- PREFERRED: run a real DamageInfo through the pipeline so the target
    -- FLINCHES/STAGGERS/dies naturally (not a silent HP drain that looks
    -- fake). Falls back to setHp if the pipeline construction fails.
    pcall(function()
        if griffin_damage_via_pipeline(hc, hp - new) then
            read_after("pipeline")
        else
            tried[#tried + 1] = "pipeline:skip"
        end
    end)
    if not ok then
        if griffin_damage_via_update(hc, hp - new) then
            read_after("updateDamageHp")
        else
            tried[#tried + 1] = "updateDamageHp:skip"
        end
    end
    if not ok then
        pcall(function() hc:call("set_IsDamageZero", false) end)
        pcall(function() hc:call("set_IsIgnoreDamageHit", false) end)
        pcall(function() hc:call("set_DamageCollisionOff", false) end)
        pcall(function() hc:call("setHp(System.Single, System.Boolean, System.Int32)", new, true, 0) end)
        if not read_after("setHp3") then
            pcall(function() hc:call("setHp(System.Single, System.Boolean)", new, true) end)
            if not read_after("setHp2") then
                pcall(function() hc:call("setHp(System.Single)", new) end)
                if not read_after("setHp1") then
                    pcall(function() hc:call("set_Hp(System.Single)", new) end)
                    if not read_after("set_Hp") then
                        pcall(function() hc:call("setHpValue(System.Single, System.Boolean)", new, true) end)
                        if not read_after("setHpValue2") then
                            pcall(function() hc:call("setHpValue(System.Single)", new) end)
                            if not read_after("setHpValue1") then
                                pcall(function() tch:call("setHp(System.Single, System.Boolean, System.Int32)", new, true, 0) end)
                                if not read_after("char.setHp3") then
                                    pcall(function() tch:call("set_Hp(System.Single)", new) end)
                                    read_after("char.set_Hp")
                                end
                            end
                        end
                    end
                end
            end
        end
        -- best-effort flinch so a raw HP drain still shows a reaction
        pcall(function() hc:call("setDamageReaction") end)
    end
    S.route3_attack_target_hp = tostring(math.floor(tonumber(after) or hp))
    if ok then
        S.route3_attack_dmg_dealt = (tonumber(S.route3_attack_dmg_dealt) or 0) + math.max(0.0, hp - after)
        S.route3_attack_damage_status = string.format("damage=hit %.1f>%s via %s",
            hp, tostring(after), table.concat(tried, " "))
    else
        S.route3_attack_damage_status = string.format("damage=fail %.1f->%.1f tried %s",
            hp, new, table.concat(tried, " "))
    end
    return ok
end

function griffin_damage_via_pipeline(hc, dmg)
    -- construct a DamageInfo and run damageProc: the native hit path (real
    -- reaction + death). Returns true only if the pipeline actually ran.
    if not hc then return false end
    local di = nil
    pcall(function() di = sdk.create_instance("app.HitController.DamageInfo") end)
    if not di then pcall(function() di = sdk.create_instance("app.HitController.DamageInfo", true) end) end
    if not di then return false end
    local gch, ggo = reacquire_griffin()
    local victim_go = nil
    pcall(function() victim_go = hc:call("get_GameObject") end)
    pcall(function() di:set_field("Damage", tonumber(dmg) or 60.0) end)
    pcall(function() di:set_field("FixedDamage", tonumber(dmg) or 60.0) end)
    pcall(function() di:set_field("DamageRate", 1.0) end)
    pcall(function() di:set_field("DamageRateReaction", 1.0) end)
    pcall(function() di:set_field("IsDirectDamage", true) end)
    pcall(function() di:set_field("IsDirectDamageEnableAllDamageType", true) end)
    pcall(function()
        if victim_go then
            di:set_field("<DamageGameObject>k__BackingField", victim_go)
        end
    end)
    pcall(function() if ggo then di:set_field("<AttackGameObject>k__BackingField", ggo) end end)
    pcall(function() if ggo then di:set_field("<AttackOwnerObject>k__BackingField", ggo) end end)
    local ran = false
    pcall(function() hc:call("damageProc(app.HitController.DamageInfo)", di); ran = true end)
    if not ran then pcall(function() hc:call("setDamageInfo(app.HitController.DamageInfo)", di); hc:call("setDamageReaction"); ran = true end) end
    return ran
end

function griffin_damage_via_update(hc, dmg)
    -- Target dump showed the goblin exposes updateDamageHp(DamageInfo, amount,
    -- bool). This is safer than raw field writes and more direct than guessing
    -- private HP storage.
    if not hc then return false end
    local di = nil
    pcall(function() di = sdk.create_instance("app.HitController.DamageInfo") end)
    if not di then pcall(function() di = sdk.create_instance("app.HitController.DamageInfo", true) end) end
    if not di then return false end
    local amount = tonumber(dmg) or 60.0
    local gch, ggo = reacquire_griffin()
    local victim_go = nil
    pcall(function() victim_go = hc:call("get_GameObject") end)
    pcall(function() di:set_field("Damage", amount) end)
    pcall(function() di:set_field("FixedDamage", amount) end)
    pcall(function() di:set_field("DamageRate", 1.0) end)
    pcall(function() di:set_field("DamageRateReaction", 1.0) end)
    pcall(function() di:set_field("IsDirectDamage", true) end)
    pcall(function() di:set_field("IsDirectDamageEnableAllDamageType", true) end)
    pcall(function() di:set_field("IsSlashAttack", true) end)
    pcall(function() di:set_field("SlashDamage", amount) end)
    pcall(function()
        if victim_go then
            di:set_field("<DamageGameObject>k__BackingField", victim_go)
        end
    end)
    pcall(function() if ggo then di:set_field("<AttackGameObject>k__BackingField", ggo) end end)
    pcall(function() if ggo then di:set_field("<AttackOwnerObject>k__BackingField", ggo) end end)
    local ran = false
    pcall(function() hc:call("updateDamageHp(app.HitController.DamageInfo, System.Single, System.Boolean)", di, amount, true); ran = true end)
    if not ran then pcall(function() hc:call("updateDamage(app.HitController.DamageInfo, System.UInt32, System.Single, System.Boolean)", di, 0, amount, true); ran = true end) end
    if ran then pcall(function() hc:call("updateDamageReaction(app.HitController.DamageInfo)", di) end) end
    return ran
end

function griffin_dump_hate_ai()
    -- ONE-SHOT capture of the hate/combat API so we learn EXACTLY how to land a
    -- hate entry. The real-vs-ordered diff named the gate (empty _HateCalculators)
    -- but the dumps never captured HateSystem's METHODS or the hate ENUMS, so we
    -- don't yet know the correct add-hate call. Dumps: the griffin's HateSystem/
    -- CombatStateControl/BattleStateController/AIBlackBoard/Retarget/Decision
    -- method surfaces, the HateRecvCategory + WriteType enum values, and a LIVE
    -- nearby enemy's HateSystem as a working reference (its rank should be > 0).
    local gch, ggo = reacquire_griffin()
    local enemy = griffin_find_enemy(60.0)
    local ego = enemy and char_go(enemy)
    local out = {
        time = os.date("%Y-%m-%d %H:%M:%S"),
        griffin = { name = tostring(go_name(ggo) or "?") },
        enemy = { name = tostring(go_name(ego) or "(none within 60m)") },
    }
    local function comp_methods(go, typename)
        local rec = { methods = {} }
        pcall(function()
            local comp = get_component(go, typename)
            if not comp then rec.missing = true; return end
            local td = comp:get_type_definition()
            rec.type = tostring(td:get_full_name())
            local seen = {}
            while td do
                for _, m in ipairs(td:get_methods() or {}) do
                    local mn = tostring(m:get_name() or "")
                    local sig = mn
                    pcall(function()
                        local names = {}
                        for _, pt in ipairs(m:get_param_types() or {}) do names[#names + 1] = tostring(pt:get_full_name() or "?") end
                        sig = mn .. "(" .. table.concat(names, ", ") .. ")"
                    end)
                    if not seen[sig] then seen[sig] = true; rec.methods[#rec.methods + 1] = sig end
                end
                td = td:get_parent_type()
            end
        end)
        return rec
    end
    local function enum_values(typename)
        local rec = {}
        pcall(function()
            local td = sdk.find_type_definition(typename)
            if not td then rec.missing = true; return end
            for _, f in ipairs(td:get_fields() or {}) do
                local nm = tostring(f:get_name() or "?")
                local v = nil
                pcall(function() v = f:get_data() end)
                if v ~= nil then rec[nm] = tostring(v) end
            end
        end)
        return rec
    end
    for _, tn in ipairs({ "app.HateSystem", "app.CombatStateControl", "app.BattleStateController",
        "app.AIBlackBoardController", "app.RetargetController", "app.AIDecisionMaker" }) do
        out.griffin[tn] = comp_methods(ggo, tn)
    end
    out.enemy["app.HateSystem"] = comp_methods(ego, "app.HateSystem")
    out.enums = {
        HateRecvCategory = enum_values("app.HateRecvCategory"),
        WriteType = enum_values("app.HateSystem.WriteType"),
        DecisionModuleType = enum_values("app.AIDecisionMaker.DecisionModuleTypesEnum"),
        CombatStateNo = enum_values("app.CombatStateControl.CombatStateNo"),
    }
    -- live ground truth: griffin should read 0 (the bug); a real fighting enemy > 0
    out.griffin.hate_rank = griffin_hate_rank_count(griffin_hate_system())
    out.enemy.hate_rank = griffin_hate_rank_count(character_hate_system(enemy, ego))
    pcall(function() json.dump_file(MOD .. "_hate_ai.json", out) end)
    S.route3_hate_ai_dumped = string.format("hate/AI dumped (griffin rank=%s, enemy rank=%s) -> %s_hate_ai.json",
        tostring(out.griffin.hate_rank), tostring(out.enemy.hate_rank), MOD)
    status(S.route3_hate_ai_dumped)
    return true
end

function griffin_attack_node_from_list(csv, index_key, fallback)
    local nodes = {}
    for raw in tostring(csv or ""):gmatch("[^,%s]+") do
        local n = tostring(raw or "")
        if n ~= "" then nodes[#nodes + 1] = n end
    end
    if #nodes == 0 then return tostring(fallback or C.route3_attack_node or "Attack.Attack01") end
    local idx = (tonumber(S[index_key]) or 0) + 1
    if idx > #nodes then idx = 1 end
    S[index_key] = idx
    return nodes[idx]
end

function griffin_attack_next_ground_node()
    return griffin_attack_node_from_list(C.route3_attack_nodes, "route3_attack_node_index", C.route3_attack_node)
end

function griffin_attack_next_air_node()
    if tostring(C.route3_attack_air_nodes or "") == "" then return nil end
    return griffin_attack_node_from_list(C.route3_attack_air_nodes, "route3_attack_air_node_index", nil)
end

function griffin_swing_once(name)
    -- one attack, two delivery routes: requestActionCore with the LEAF name
    -- (the route her own AI uses — hitboxes included), and for dotted paths
    -- also poke the FSM node directly (harmless when ignored)
    name = tostring(name or griffin_attack_next_ground_node() or C.route3_attack_node or "Attack.Attack01")
    -- an idle companion sits under pacify's FSM puppet where nothing can
    -- play (round-84 law) — free the FSM before swinging
    pcall(function()
        local _, sgo = reacquire_griffin()
        if sgo then set_motion_fsm_puppet(sgo, false) end
    end)
    local leaf = name:match("([^%.]+)$") or name
    request_griffin_action(leaf, 0)
    if name:find(".", 1, true) then
        set_griffin_fsm_node_silent(name, 0)
    end
    S.route3_attack_last_forced_node = name
    S.route3_attack_swings = (tonumber(S.route3_attack_swings) or 0) + 1
    return true
end

function griffin_body_is_ours(ch)
    -- Attackable companions deliberately remain CharacterKind 8, so kind can
    -- no longer be used as the ownership marker. The copied player group hash
    -- is the stable discriminator: a wild same-species body keeps its monster
    -- group, while our parked/active body keeps the party group.
    local ours = false
    pcall(function()
        local _, hgc = route3_ally_group_ctx(ch)
        local _, pgc = route3_ally_group_ctx(get_player())
        if not (hgc and pgc) then return end
        local hg = hgc:get_field("GroupHash")
        local pg = pgc:get_field("GroupHash")
        local hd = hgc:get_field("DefaultGroupHash")
        local pd = pgc:get_field("DefaultGroupHash")
        ours = hg ~= nil and pg ~= nil and hg == pg
            and (hd == nil or pd == nil or hd == pd)
    end)
    return ours
end

function griffin_destroy_character_body(ch, reason)
    local go = ch and char_go(ch)
    if not go then return false end
    local name = tostring(go_name(go))
    local ok = false
    pcall(function() go:destroy(go); ok = true end)
    if not ok then pcall(function() go:call("destroy(via.GameObject)", go); ok = true end) end
    if not ok then pcall(function() go:call("destroy"); ok = true end) end
    if ok then
        mounts[ch] = nil
        S.route3_preload_destroy_detail = tostring(reason or "destroyed") .. " " .. name
    end
    return ok
end

function griffin_preload_destroy_scene_bodies(reason)
    -- Preload hooks can fire after S.griffin has already been dropped by the
    -- world sentry. Sweep the live scene for stable-owned bodies and destroy
    -- them directly before the engine tears the scene down.
    local stable = S.route3_stable
    if not stable then pcall(function() stable = json.load_file(MOD .. "_stable.json") end) end
    local wanted = {}
    local function add_comp(comp, active)
        if type(comp) ~= "table" then return end
        local guid = tostring(comp.guid or "")
        local parked = comp.parked
        if guid:find("@", 1, true) then wanted[#wanted + 1] = { exact = guid, parked = parked, active = active == true } end
        local prefix = tostring(comp.species or ""):match("ch%d+")
        if prefix and prefix ~= "" then wanted[#wanted + 1] = { prefix = prefix, parked = parked, active = active == true } end
    end
    if type(stable) == "table" and type(stable.companions) == "table" then
        for _, comp in ipairs(stable.companions) do add_comp(comp, comp.id ~= nil and comp.id == stable.active) end
    end
    add_comp(S.route3_tamed_record, true)
    if #wanted == 0 then return 0 end

    local destroyed = 0
    local seen = {}
    local scanned = 0
    local matched = 0
    local samples = {}
    local function consider(ch)
        if not ch or is_dead(ch) then return end
        scanned = scanned + 1
        local go = char_go(ch)
        if not go then return end
        local name = tostring(go_name(go) or "")
        if #samples < 8 and name ~= "" then samples[#samples + 1] = name end
        local pos = transform_pos(go)
        local match_exact, match_prefix = false, false
        local close_to_active_parked = false
        for _, w in ipairs(wanted) do
            if w.exact and name:find(w.exact, 1, true) then match_exact = true end
            if w.prefix and name:find(w.prefix, 1, true) then
                match_prefix = true
                if w.active == true and type(w.parked) == "table" and pos then
                    local parked = make_position(tonumber(w.parked.x) or 0.0, tonumber(w.parked.y) or 0.0, tonumber(w.parked.z) or 0.0)
                    local d = distance_sq(pos, parked)
                    if d and d <= (180.0 * 180.0) then close_to_active_parked = true end
                end
            end
        end
        if not (match_exact or match_prefix) then return end
        matched = matched + 1
        -- Prefix matches are only safe when the body still carries our ally
        -- identity. At preload, active-species bodies near the saved parked
        -- spot are also destroyed: a same-species false positive is better
        -- than a guaranteed stale native body crash.
        if (not match_exact) and not griffin_body_is_ours(ch) and not close_to_active_parked then return end
        local addr = nil
        pcall(function() addr = ch:get_address() end)
        if addr and seen[addr] then return end
        if addr then seen[addr] = true end
        if griffin_destroy_character_body(ch, reason or "preload scene sweep") then destroyed = destroyed + 1 end
    end

    pcall(function() consider(S.griffin) end)
    pcall(function() consider(S.critter) end)
    pcall(function()
        local cm = singleton("app.CharacterManager")
        if not cm then return end
        for _, getter in ipairs({ "get_CharacterList", "getCharacterList", "get_AllCharacterList", "get_CharacterAll" }) do
            local list = nil
            pcall(function() list = cm:call(getter) end)
            local n = 0
            pcall(function() n = list and list:call("get_Count") or 0 end)
            if (tonumber(n) or 0) > 0 then
                for i = 0, n - 1 do pcall(function() consider(list:call("get_Item", i)) end) end
            end
        end
    end)
    pcall(function()
        local em = singleton("app.EnemyManager")
        if not em then return end
        for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
            local list = nil
            pcall(function() list = em:call(getter) end)
            local n = 0
            pcall(function() n = list and list:call("get_Count") or 0 end)
            if (tonumber(n) or 0) > 0 then
                for i = 0, n - 1 do pcall(function() consider(list:call("get_Item", i)) end) end
            end
        end
    end)
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        if not scene then return end
        local comps = scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, comp in ipairs(system_array_to_table(comps) or {}) do
            pcall(function() consider(comp) end)
        end
    end)
    S.route3_preload_scan_detail = string.format("scanned=%d matched=%d samples=%s", scanned, matched, table.concat(samples, " | "))
    return destroyed
end

function griffin_drop_live_refs(reason)
    -- forget every live managed reference. The bodies themselves are fine —
    -- reclaim re-links the active companion by GUID once the world is back.
    S.companion_order = nil
    S.companion_target = nil
    S.companion_target_go = nil
    S.route3_companion_moving = false
    S.route3_whistle_flyin = nil
    S.route3_follow_running = false
    S.route3_scale_target = nil
    S.route3_restore_warp_pending = nil
    S.route3_spawn_request = false
    S.pending_spawn = false
    S.pending_critter_spawn = false
    S.route3_ally_auto_at = 0.0
    S.route3_ally_calm_until = 0.0
    -- spawner handles hold refs to their spawned instances: after a reload
    -- those are stale, and the per-frame spawner tick would call into them
    S.spawner = nil
    S.wild_spawner = nil
    S.critter_spawner = nil
    S.griffin = nil
    S.griffin_go = nil
    S.critter = nil
    for k in pairs(mounts) do mounts[k] = nil end
    S.route3_tamed_restore_tries = 0
    S.route3_tame_status = "live refs dropped (" .. tostring(reason or "?") .. ")"
end

function griffin_on_player_death()
    -- the world is about to reload from the last save: spawner-owned bodies
    -- (wild test spawns, whistle-minted companions) are NOT in that save, so
    -- destroy them cleanly NOW while they're still valid — a live spawner
    -- instance carried into the reload is a stale-ref crash. Claimed wild
    -- bodies belong to the game's own generators and are left alone. Souls
    -- and stable records are untouched; the whistle rebuilds any lost body.
    if S.companion_order == "attack" then pcall(function() griffin_order_disengage("rider died") end) end
    -- ⭐ 08-09 (Aurora fell off a cliff into water: brine took her, the horse
    -- stayed DOWN and stuck underwater, and she respawned into the water to be
    -- taken again, over and over). A downed body is held alive on purpose --
    -- HP pinned at the floor, AI off, animation claimed, all re-asserted every
    -- frame -- and that hold has no business surviving the rider's death. It
    -- keeps a body pinned somewhere unreachable across the reload, and if that
    -- somewhere is brine it is unreachable forever.
    -- Bench it instead: the stable record and the soul both persist, so the
    -- companion is recoverable, and nothing is left pinned in the water.
    -- ⚠ This fixes OUR half. Where the game chooses to put the Arisen after a
    -- brine death is the game's own respawn logic and is not something this
    -- mod sets -- if the loop survives this, that is the next thing to probe.
    pcall(function()
        local st = S.downed
        if type(st) == "table" and next(st) ~= nil then
            for _, e in pairs(st) do
                pcall(function()
                    griffin_downed_stable_write_hp(e,
                        tonumber(C.route3_downed_floor_hp) or 1.0)
                end)
            end
            griffin_downed_release_all("rider died")
        end
    end)
    for _, key in ipairs({ "wild_spawner", "spawner", "critter_spawner", "route3_proxy_spawner" }) do
        local sp = S[key]
        if sp then pcall(function() sp:deleteAll() end) end
    end
    griffin_drop_live_refs("rider died")
end

function griffin_preload_cleanup(reason)
    -- a scene teardown (return-to-title / load) is imminent: destroy every
    -- spawner-born body NOW, while the world is still valid — they crash the
    -- teardown otherwise (confirmed environmental, mod hooks off still crashes).
    -- DISK-LOG each fire so the evidence SURVIVES the crash (an in-memory flag
    -- dies with the process, which is why we couldn't see if this ran).
    S.route3_preload_fired = tostring(reason or "?") .. " @ " .. os.date("%H:%M:%S")
    pcall(function()
        local log = nil
        pcall(function() log = json.load_file(MOD .. "_preload_log.json") end)
        if type(log) ~= "table" then log = {} end
        log[#log + 1] = { reason = tostring(reason or "?"), time = os.date("%Y-%m-%d %H:%M:%S") }
        while #log > 30 do table.remove(log, 1) end
        json.dump_file(MOD .. "_preload_log.json", log)
    end)
    status("PRE-LOAD CLEANUP fired (" .. tostring(reason or "?") .. ") - spawner bodies despawned")
    for _, key in ipairs({ "wild_spawner", "spawner", "critter_spawner" }) do
        local sp = S[key]
        if sp then pcall(function() sp:deleteAll() end) end
    end
    -- CRITICAL: a RECLAIMED body is NOT in any spawner table (reclaim just
    -- re-registers a standing body), so deleteAll misses it and it survives to
    -- teardown = crash. Destroy the tracked companion body DIRECTLY too.
    -- Safe: the SOUL persists, the whistle re-mints a body after the load.
    for _, ch in ipairs({ S.griffin, S.critter, S.route3_proxy }) do
        pcall(function()
            if griffin_destroy_character_body(ch, "preload tracked") then destroyed = destroyed + 1 end
        end)
    end
    pcall(function()
        destroyed = destroyed + (tonumber(griffin_preload_destroy_scene_bodies(reason or "preload scene sweep")) or 0)
    end)
    S.route3_preload_destroyed = destroyed
    -- record destroy count to the disk log's last entry so we can see if the
    -- body destroy actually ran (crash persists = maybe it's deferred/failed)
    pcall(function()
        local log = json.load_file(MOD .. "_preload_log.json")
        if type(log) == "table" and #log > 0 then
            log[#log].bodies_destroyed = destroyed
            log[#log].destroy_detail = tostring(S.route3_preload_destroy_detail or "")
            log[#log].scan_detail = tostring(S.route3_preload_scan_detail or "")
            json.dump_file(MOD .. "_preload_log.json", log)
        end
    end)
    pcall(function() griffin_drop_live_refs(reason or "game load requested") end)
end


function griffin_world_sentry()
    -- THE gate for every per-frame system. Player death or a missing player
    -- (title screen, load) makes all held managed refs stale — one method
    -- call on a stale ref is a native crash pcall can't catch. Called from
    -- EVERY frame callback; one-shot latches make repeat calls free.
    local pgo = char_go(get_player())
    local live = (pgo and transform_pos(pgo)) ~= nil
    -- a tearing-down player can still "read" for a few frames: trust the
    -- engine's own validity bit when it says no
    if live then
        pcall(function()
            if pgo:call("get_Valid") == false then live = false end
        end)
    end
    S.route3_world_live = live
    if live then
        S.route3_world_drop_done = false
        local rider_dead = false
        pcall(function() rider_dead = is_dead(get_player()) == true end)
        if rider_dead then
            -- while mounted, the ride-safety watchdog unwinds the ride FIRST
            -- (it needs the live refs); cleanup runs on the next frame
            if S.route3_death_cleanup_done ~= true and S.mounted ~= true then
                S.route3_death_cleanup_done = true
                pcall(function() griffin_on_player_death() end)
            end
        else
            S.route3_death_cleanup_done = false
        end
        return true
    end
    -- world gone: drop refs IMMEDIATELY — a one-frame flicker only costs a
    -- reclaim (guid re-link within seconds); a held stale ref costs a crash
    if S.route3_world_drop_done ~= true then
        S.route3_world_drop_done = true
        pcall(function() griffin_drop_live_refs("world dropped") end)
    end
    return false
end


function route3_apply_wing_joint_pose()
    -- stand down during a swoop so a real attack node/clip can drive her pose instead
    if griffin_predation_window_active()
        or griffin_predation_carry_wings_standdown()
        or (griffin_grab_active() and S.route3_grab and S.route3_grab.anim == true)
        or griffin_unleash_striking() then return false end
    if C.route3_wing_joint_pose_enabled ~= true and C.route3_wing_joint_visual_enabled ~= true then return false end
    if C.route3_wing_joint_visual_enabled == true and C.route3_wing_joint_auto_audio_visual ~= true then
        S.route3_wing_joint_pose_status = "(fake flap disabled)"
        return false
    end
    if C.route3_wing_joint_visual_enabled == true and C.route3_wing_joint_visual_airborne_only == true and S.airborne ~= true then
        S.route3_wing_joint_pose_status = "visual waiting for flight"
        return false
    end
    if C.route3_wing_joint_pose_enabled == true and C.route3_wing_joint_pose_airborne_only == true and S.airborne ~= true then
        S.route3_wing_joint_pose_status = "waiting for flight"
        return false
    end

    local _, go = reacquire_griffin()
    if not go then
        S.route3_wing_joint_pose_status = "NO griffin"
        return false
    end

    local tf = nil
    pcall(function() tf = go:call("get_Transform") end)
    if not tf then
        S.route3_wing_joint_pose_status = "NO transform"
        return false
    end

    local names = route3_wing_joint_names()
    if #names == 0 then
        S.route3_wing_joint_pose_status = "NO joints configured"
        return false
    end

    local ax, ay, az, axis_name = route3_wing_joint_axis()
    local base_angle = tonumber(C.route3_wing_joint_pose_angle) or 0.0
    local visual = C.route3_wing_joint_visual_enabled == true
    local visual_mode = math.floor(tonumber(C.route3_wing_joint_visual_mode) or 0)
    if visual then
        if visual_mode == 1 then
            local amp = tonumber(C.route3_wing_joint_flap_amp) or 28.0
            local mid = tonumber(C.route3_wing_joint_flap_mid_angle) or 0.0
            if C.route3_wing_joint_flap_sync_audio == true then
                local limit = math.max(1.0, tonumber(C.route3_wing_joint_flap_max_degrees) or 16.0)
                if amp > limit then amp = limit end
                if amp < -limit then amp = -limit end
                if mid > limit then mid = limit end
                if mid < -limit then mid = -limit end
                local now = os.clock()
                local start_t = tonumber(S.route3_wing_flap_pulse_start) or 0.0
                local until_t = tonumber(S.route3_wing_flap_pulse_until) or 0.0
                local dur = math.max(0.1, until_t - start_t)
                if now <= until_t and start_t > 0.0 then
                    local phase = math.max(0.0, math.min(1.0, (now - start_t) / dur))
                    local wave = math.sin(phase * math.pi)
                    base_angle = mid + amp * wave
                else
                    local rest = tonumber(C.route3_wing_joint_flap_rest_angle) or 0.0
                    if rest > limit then rest = limit end
                    if rest < -limit then rest = -limit end
                    base_angle = rest
                end
                if C.route3_wing_joint_flap_invert == true then
                    base_angle = -base_angle
                end
            else
                local rate = math.max(0.05, tonumber(C.route3_wing_joint_flap_rate) or 0.85)
                base_angle = mid + math.sin(os.clock() * rate * math.pi * 2.0) * amp
                if C.route3_wing_joint_flap_invert == true then
                    base_angle = -base_angle
                end
            end
        else
            base_angle = tonumber(C.route3_wing_joint_glide_angle) or 18.0
        end
    end
    local hits = 0
    local last_error = "(none)"

    for _, joint_name in ipairs(names) do
        local ok, err = pcall(function()
            local joint = tf:call("getJointByName", joint_name)
            if not joint then return end
            local sign = 1.0
            if C.route3_wing_joint_pose_mirror == true and tostring(joint_name):sub(1, 2) == "L_" then
                sign = -1.0
            end
            local bx, by, bz, bw = griffin_q_read(joint:call("get_BaseLocalRotation"))
            local ox, oy, oz, ow = griffin_q_axis_angle(ax, ay, az, base_angle * sign)
            local rx, ry, rz, rw = griffin_q_mul(bx, by, bz, bw, ox, oy, oz, ow)
            joint:call("set_LocalRotation", griffin_make_quat_raw(rx, ry, rz, rw))
            hits = hits + 1
        end)
        if not ok then last_error = tostring(err) end
    end

    S.route3_wing_joint_pose_hits = hits
    S.route3_wing_joint_pose_error = last_error
    S.route3_wing_joint_pose_status = string.format(
        "%s hits=%d mode=%s axis=%s angle=%.1f mirror=%s",
        hits > 0 and "YES" or "NO",
        hits,
        visual and (visual_mode == 1 and "flap" or "glide") or "pose",
        axis_name,
        base_angle,
        C.route3_wing_joint_pose_mirror == true and "YES" or "NO"
    )
    if visual and visual_mode == 1 then
        S.route3_wing_joint_pose_status = S.route3_wing_joint_pose_status
            .. " invert=" .. (C.route3_wing_joint_flap_invert == true and "YES" or "NO")
    end
    return hits > 0
end

function griffin_fsm_node_exists(node)
    -- validate a node name against the LIVE tree before setCurrentNode: a typo'd/unknown
    -- name is a NATIVE CRASH, not a lua error. Node set cached per griffin body.
    node = tostring(node or "")
    if node == "" then return false end
    local _, go = reacquire_griffin()
    if not go then return false end
    local key = tostring(go:get_address())
    local cache = S.route3_fsm_node_set
    if not (cache and cache.key == key) then
        cache = { key = key, set = {}, count = 0 }
        pcall(function()
            local fsm = get_motion_fsm(go)
            local layer = fsm and fsm:call("getLayer", 0)
            local tree = layer and layer:get_tree_object()
            for i, nd in ipairs((tree and tree:get_nodes()) or {}) do
                if i > 3000 then break end
                local nm = nil
                pcall(function() nm = nd:get_full_name() end)
                if not nm then pcall(function() nm = nd:get_name() end) end
                if nm then cache.set[tostring(nm)] = true; cache.count = cache.count + 1 end
            end
        end)
        S.route3_fsm_node_set = cache
    end
    -- fail-OPEN only when enumeration itself failed (0 nodes read): can't validate = old behavior
    if cache.count == 0 then return true end
    return cache.set[node] == true
end

function griffin_fsm_node_names()
    -- Sorted list of the LIVE tree's node names, for the picker. Reuses the exact cache
    -- griffin_fsm_node_exists builds (keyed on the body address), so it follows whichever
    -- creature is actually mounted instead of a stale ch253 dump.
    griffin_fsm_node_exists("__warm_the_cache__")
    local cache = S.route3_fsm_node_set
    if not cache then return {} end
    if S.fsm_node_list_key == cache.key and S.fsm_node_list then return S.fsm_node_list end
    local out = {}
    for name, _ in pairs(cache.set or {}) do out[#out + 1] = name end
    table.sort(out)
    S.fsm_node_list = out
    S.fsm_node_list_key = cache.key
    return out
end

function griffin_fsm_node_is_blocked(name)
    for pat in tostring(C.route3_rise_node_blocklist or ""):gmatch("[^,%s]+") do
        if tostring(name or ""):find(pat, 1, true) then return true, pat end
    end
    return false
end

set_griffin_fsm_node_silent = function(node, tree)
    local _, go = reacquire_griffin()
    local fsm = get_motion_fsm(go)
    if not fsm then return false end
    -- TYPO GUARD: refuse unknown nodes (a bad name in setCurrentNode = native crash)
    if not griffin_fsm_node_exists(node) then
        S.route3_fsm_node_refused = tostring(node or "?")
        return false
    end
    local ok = false
    pcall(function()
        fsm:call("setCurrentNode(System.String, System.UInt32, via.behaviortree.SetNodeInfo)", tostring(node or ""), tonumber(tree) or 0, nil)
        ok = true
    end)
    return ok
end

-- ⭐ Static node-risk classifier (2026-07-20)
-- The RE behaviortree exposes NO "requires target" flag, so a definitive crash-list isn't
-- queryable. This reads each FSM node's NAME category + (best-effort) its attached action
-- component TYPE names, and heuristically tags it safe / risky / unknown for FORCING on a
-- think-stopped, targetless griffin. Metadata-only: it never fires a node, so it cannot
-- crash the game. Writes <MOD>_node_classify.json for review. Degrades to name-only
-- classification if the action introspection isn't exposed by the API.
audition_griffin_motion = function(delta)
    delta = tonumber(delta) or 0
    if delta ~= 0 then
        local step = math.max(1, math.floor(tonumber(C.audition_step) or 1))
        C.audition_motion = math.max(0, math.floor((tonumber(C.audition_motion) or 0) + delta * step))
    end
    local catalog = refresh_motion_catalog(false)
    if catalog and #catalog.items > 0 then
        local idx = catalog.by_tag[tostring(C.motion_bank) .. ":" .. tostring(C.audition_motion)]
        if idx then S.audition_index = idx end
    end

    if motion_is_skipped(C.motion_bank, C.audition_motion) then
        status("skipped unsafe audition motion " .. motion_tag(C.motion_bank, C.audition_motion))
        return false
    end
    C.last_audition_attempt_bank = math.floor(tonumber(C.motion_bank) or 0)
    C.last_audition_attempt_motion = math.floor(tonumber(C.audition_motion) or 0)
    C.last_audition_attempt = motion_tag(C.last_audition_attempt_bank, C.last_audition_attempt_motion)
    save_config()
    pacify_griffin(nil)
    local ok = play_griffin_motion(C.audition_motion, C.motion_bank, true)
    C.last_audition_completed = C.last_audition_attempt
    S.audition_until_clock = os.clock() + math.max(0.1, tonumber(C.audition_hold_seconds) or 3.0)
    save_config()
    status("audition griffin motion " .. tostring(C.motion_bank) .. ":" .. tostring(C.audition_motion) .. " ok=" .. tostring(ok))
end

-- ⭐ 08-11 per-body species-profile apply, cheap enough for reacquire's hot path: acts only
-- when the resolved body's IDENTITY changes (script reset, stable switch, summon). This is
-- what actually cures cross-species C contamination -- register_griffin alone missed the
-- post-reset path, where the live body returns via reacquire's fast path (field-proven:
-- griffin jumping with the drake's wind-up after a reset). Global, not local (200-local cap).
function griffin_profile_ensure()
    local now = os.clock()
    if now < (tonumber(S.route3_profile_ensure_at) or 0.0) then return end
    S.route3_profile_ensure_at = now + 0.5
    local addr = nil
    pcall(function() addr = S.griffin_go and S.griffin_go:get_address() end)
    if not addr or addr == S.route3_profile_applied_addr then return end
    local raw = tostring(go_name(S.griffin_go) or ""):match("^[^@]+") or ""
    local skey = raw:match("ch%d+_%a_%d+") or raw:match("ch%d+_%d+")
    if not skey then return end
    S.route3_profile_applied_addr = addr
    S.route3_tamed_species = skey
    pcall(function() griffin_species_profile_apply(skey) end)
end

local function register_griffin(ch)
    if not ch then return false end
    -- mounts ACCUMULATES: parked companions keep their protection (relationship
    -- + hate hooks read this table) even when another companion is active
    mounts[ch] = true
    S.griffin = ch
    S.griffin_go = char_go(ch)
    S.griffin_name = char_name(ch)
    S.relation_hits = 0
    S.friend_hits = 0
    -- ⭐ 08-11 LIVE-RECORD IDENTITY (Aurora: selecting Shadow in the stable re-statted +
    -- re-scaled the summoned Tails): st.active is the PANEL SELECTION and moves on every
    -- click; the body keeps belonging to the record it was summoned/tamed from. Stamp that
    -- identity here -- register_griffin is the one gate every route (summon, tame, reclaim)
    -- passes through while its own record is still the active one. Body-facing systems
    -- read griffin_stable_live_rec(), never the selection.
    pcall(function()
        local ar = griffin_stable_active()
        S.live_rec_id = ar and ar.id or nil
    end)
    pcall(function()
        if griffin_stable_prepare_summon then griffin_stable_prepare_summon(ch) end
    end)
    -- ⭐ 08-11 PER-REGISTER PROFILE APPLY (the griffin-jumped-like-a-drake bug): C is SHARED
    -- and profiles only applied at TAME time, so switching the active creature carried the
    -- previous species' tuning across (drake's 2s jump wind-up on the griffin; the drake
    -- retire flag arming the hold pump = her double loops). This is the one gate every route
    -- (summon, tame, reclaim, stable switch) passes through -- apply the body's OWN species
    -- profile here, keyed off its live name. Also keeps griffin_species_key() honest so a
    -- later SAVE writes to the right species instead of whoever was applied last.
    S.route3_profile_applied_addr = nil   -- force the ensure to re-apply for this body
    S.route3_profile_ensure_at = 0.0
    pcall(griffin_profile_ensure)
    -- EnemySpawner's ovrScale is not reliable for these large-character
    -- templates (the body can arrive at native 1.0 even though cfg says 0.55).
    -- Reassert the active species profile once the spawned body has finished
    -- constructing. This is a delayed SNAP for a returning companion; a newly
    -- tamed wild creature replaces it with the deliberate gradual shrink below.
    local stable_scale = tonumber(C.spawn_scale)
    -- ⛔ THE CHOKE-POINT RULE APPLIES HERE TOO (the 0.55 stable rabbit, second recurrence):
    -- this direct write BYPASSED griffin_apply_body_scale, and C.spawn_scale is a GLOBAL
    -- still holding the last big companion's shrink. Judge by the body being registered.
    pcall(function()
        local nm0 = tostring(go_name(char_go(ch)) or "")
        local big0 = nm0:find("ch253", 1, true) == 1 or nm0:find("ch257", 1, true) == 1
            or nm0:find("ch254", 1, true) == 1 or nm0:find("ch258", 1, true) == 1
        if not big0 and stable_scale and stable_scale <= 1.0 then stable_scale = iris_species_base_scale(nm0) end
    end)
    if stable_scale and stable_scale > 0.05 and stable_scale <= 3.0 then
        S.route3_scale_target = stable_scale
        S.route3_scale_snap_at = os.clock() + 0.75
    end
    -- NOTE: spawner-born bodies stay in their spawner's instance table on
    -- purpose — they are SESSION-SCOPED (a live spawner instance at scene
    -- teardown crashes the game, confirmed with mod hooks disabled), so the
    -- death/pre-load cleanups must be able to destroy them. The SOUL is
    -- what persists; the whistle re-mints a body after any load.
    pacify_griffin(nil)
    if C.route3_ally_auto == true then
        -- NEVER apply inline: the character is still half-built at register
        -- time and touching its group context crashes natively. Delay instead.
        S.route3_ally_orig = nil
        S.route3_ally_auto_at = os.clock() + 1.5
    end
    if S.route3_restore_warp_pending then
        -- restored soul: walk the body back to its parked spot once settled
        S.route3_restore_warp_at = os.clock() + 2.5
    end
    if C.critter_reference_auto_spawn == true and S.pending_critter_spawn ~= true and not (S.critter and char_go(S.critter)) then
        local now = os.clock()
        if now - (tonumber(S.last_critter_auto_spawn_clock) or 0.0) > 2.0 then
            S.last_critter_auto_spawn_clock = now
            pcall(function() spawn_critter_reference() end)
        end
    end
    pcall(function()
        if S.route3_stable ~= nil and griffin_tamed_save then griffin_tamed_save() end
    end)
    status("registered griffin " .. S.griffin_name)
    return true
end

function register_critter_reference(ch)
    if not ch then return false end
    S.critter = ch
    S.critter_go = char_go(ch)
    S.critter_name = char_name(ch)
    S.pending_critter_spawn = false
    S.critter_neutral_status = "registered " .. tostring(S.critter_name)
    status(S.critter_neutral_status)
    return true
end

function reacquire_critter_reference()
    if S.critter and char_go(S.critter) then
        S.critter_go = char_go(S.critter)
        return S.critter, S.critter_go
    end
    if S.critter_spawner and S.critter_spawner.instances then
        for i = #S.critter_spawner.instances, 1, -1 do
            local inst = S.critter_spawner.instances[i]
            local ch = nil
            pcall(function() ch = inst.instance and inst.instance:get_Chara() end)
            if ch and not is_dead(ch) then
                register_critter_reference(ch)
                return S.critter, S.critter_go
            end
        end
    end
    return nil, nil
end

function spawn_critter_reference()
    if not ok_spawn then
        S.critter_neutral_status = "critter spawn failed: EnemySpawner unavailable"
        status(S.critter_neutral_status)
        return false
    end
    if not S.critter_spawner then
        S.critter_spawner = SpawnRequest:new()
        S.critter_spawner:updateConfig({
            spawnIdle = true,
            instLimit = 1,
            spawnMultiple = { enable = false, qty = 1 },
        })
    end
    local pos, rot = player_front(tonumber(C.critter_reference_spawn_distance) or ((tonumber(C.spawn_distance) or 8.0) + 4.0))
    if not pos then
        S.critter_neutral_status = "critter spawn failed: no player position"
        status(S.critter_neutral_status)
        return false
    end
    S.critter_spawner:deleteAll()
    S.critter = nil
    S.critter_go = nil
    S.critter_name = "(pending)"
    S.pending_critter_spawn = true
    S.critter_spawner:requestAddInstances(tostring(C.critter_reference_code or "ch299003_A_00"), pos, rot, {
        spawnIdle = true,
        ovrScale = { enable = false, scale = 1.0, normalizeSpeed = false },
    }, 1)
    S.critter_neutral_status = "requested critter " .. tostring(C.critter_reference_code)
    status(S.critter_neutral_status)
    return true
end

function managed_context_group(obj)
    local ctx = managed_field(obj, "<Context>k__BackingField") or managed_field(obj, "Context")
    if not ctx then return nil, nil end
    local group = managed_field(ctx, "GroupContext")
    return ctx, group
end

function set_context_group_names(ctx)
    if not ctx then return 0 end
    local hits = 0
    pcall(function() ctx:call("resetGroup"); hits = hits + 1 end)
    for raw in tostring(C.critter_group_names or ""):gmatch("[^,%s]+") do
        local name = tostring(raw or "")
        if name ~= "" then
            pcall(function() ctx:call("setDefaultGroup(System.String)", name); hits = hits + 1 end)
            pcall(function() ctx:call("setDefaultGroup", name); hits = hits + 1 end)
        end
    end
    return hits
end

function copy_primitive_matching_fields(src, dst, patterns)
    if not (src and dst) then return 0 end
    local td = nil
    pcall(function() td = src:get_type_definition() end)
    local copied = 0
    local seen = {}
    while td do
        pcall(function()
            for _, f in ipairs(td:get_fields() or {}) do
                local name = tostring(f:get_name() or "")
                if not seen[name] and matches_any(name, patterns) then
                    seen[name] = true
                    local value = nil
                    local ok_read = pcall(function() value = src:get_field(name) end)
                    if (not ok_read) or value == nil then pcall(function() value = f:get_data(src) end) end
                    local tv = type(value)
                    if tv == "boolean" or tv == "number" or tv == "string" then
                        local ok_write = pcall(function() dst:set_field(name, value) end)
                        if not ok_write then ok_write = pcall(function() f:set_data(dst, value) end) end
                        if ok_write then copied = copied + 1 end
                    end
                end
            end
        end)
        local parent = nil
        pcall(function() parent = td:get_parent_type() end)
        td = parent
    end
    return copied
end

function disable_griffin_combat_noise_components(go)
    local hits = 0
    for raw in tostring(C.critter_neutral_disable_components or ""):gmatch("[^,%s]+") do
        local name = tostring(raw or "")
        if name ~= "" then
            local comp = get_component(go, name)
            if comp and disable_record(comp, name) then hits = hits + 1 end
        end
    end
    return hits
end

function apply_critter_neutrality()
    local ch, go = reacquire_griffin()
    local critter, cgo = reacquire_critter_reference()
    if not (ch and go) then
        S.critter_neutral_status = "neutral failed: no griffin"
        return false
    end
    if not (critter and cgo) then
        local disabled = disable_griffin_combat_noise_components(go)
        local calls = 0
        local gadm = get_component(go, "app.AIDecisionMaker")
        local gctx = nil
        pcall(function() gctx = select(1, managed_context_group(gadm)) end)
        calls = calls + set_context_group_names(gctx)
        clear_griffin_hate()
        clear_griffin_targets()
        set_griffin_native_climb_calm(ch, go)
        S.critter_neutral_hits = (S.critter_neutral_hits or 0) + 1
        S.last_critter_neutral_clock = os.clock()
        S.critter_neutral_status = string.format("neutral static no-ox calls=%d disabled=%d", calls, disabled)
        return true
    end

    local patterns = {
        "group", "camp", "team", "relation", "friend", "enemy", "battle", "combat",
        "hostile", "hate", "target", "attack", "notice", "guard", "reaction"
    }
    local copied = 0
    local calls = 0
    local disabled = disable_griffin_combat_noise_components(go)

    local gadm = get_component(go, "app.AIDecisionMaker")
    local cadm = get_component(cgo, "app.AIDecisionMaker")
    local gctx, ggrp = managed_context_group(gadm)
    local cctx, cgrp = managed_context_group(cadm)
    calls = calls + set_context_group_names(gctx)
    copied = copied + copy_primitive_matching_fields(cgrp, ggrp, patterns)
    copied = copied + copy_primitive_matching_fields(cctx, gctx, patterns)

    for _, typename in ipairs({
        "app.ContextHolder",
        "app.CombatStateControl",
        "app.AIBlackBoardController",
        "app.HateSystem",
    }) do
        copied = copied + copy_primitive_matching_fields(get_component(cgo, typename), get_component(go, typename), patterns)
    end

    local ccombat = get_component(cgo, "app.CombatStateControl")
    local gcombat = get_component(go, "app.CombatStateControl")
    local flag = nil
    pcall(function() flag = ccombat and ccombat:call("get_CombatStatusFlag") end)
    if flag ~= nil and gcombat then
        pcall(function() gcombat:call("set_CombatStatusFlag", flag); calls = calls + 1 end)
    end

    clear_griffin_hate()
    clear_griffin_targets()
    set_griffin_native_climb_calm(ch, go)
    S.critter_neutral_hits = (S.critter_neutral_hits or 0) + 1
    S.last_critter_neutral_clock = os.clock()
    S.critter_neutral_status = string.format("neutral copied=%d calls=%d disabled=%d", copied, calls, disabled)
    return true
end

reacquire_griffin = function()
    if S.griffin and char_go(S.griffin) then
        S.griffin_go = char_go(S.griffin)
        pcall(griffin_profile_ensure)   -- post-reset/switch: body identity changed -> re-apply profile
        return S.griffin, S.griffin_go
    end
    if S.spawner and S.spawner.instances then
        -- ⛔ 08-11 (Aurora: "Tails is still getting big when I select Shadow"): this loop
        -- used to re-register ANY live spawner instance, species-blind. A stable-list
        -- click forgets the body (S.griffin = nil) and activates the clicked record --
        -- the very next reacquire then re-adopted the still-standing OLD body under the
        -- NEW record: Tails the drake became "Shadow", took her species-profile scale,
        -- her IVs, her name. Adopt ONLY a body matching the ACTIVE record's species;
        -- a mismatched body stays parked until the whistle summons the real one.
        local want = nil
        pcall(function()
            local ar = griffin_stable_active()
            want = ar and tostring(ar.species or ""):match("ch%d+") or nil
        end)
        for i = #S.spawner.instances, 1, -1 do
            local inst = S.spawner.instances[i]
            local ch = nil
            pcall(function() ch = inst.instance and inst.instance:get_Chara() end)
            if ch and not is_dead(ch) then
                -- a RELEASED body is the world's now -- never re-adopt it (08-11)
                local freed = false
                pcall(function()
                    local go9 = char_go(ch)
                    local a9 = go9 and go9:get_address()
                    freed = a9 ~= nil and (S.iris_released or {})[a9] ~= nil
                end)
                local ok_species = not freed
                if ok_species and want then
                    local nm = ""
                    pcall(function() nm = tostring(go_name(char_go(ch)) or "") end)
                    ok_species = nm:find(want, 1, true) == 1
                end
                if ok_species then
                    register_griffin(ch)
                    return S.griffin, S.griffin_go
                end
            end
        end
    end
    return nil, nil
end

-- the record the LIVE body belongs to -- NOT the panel selection.
-- ⛔ 08-11 ROUND 2 (Aurora: "tails is still getting big when I select shadow" -- the drake
-- was summoned BEFORE the stamp existed, so the old fallback-to-selection reproduced the
-- whole bug): the live BODY's species band is GROUND TRUTH, and no answer leaves this
-- function without matching it. A stamped or selected record of the wrong species is
-- DISTRUSTED; when nothing verifiable matches, return nil -- body-facing systems doing
-- NOTHING is always safer than applying another soul's genes/scale to this body.
function griffin_stable_live_rec()
    local st = S.route3_stable
    if not (st and st.companions) then return nil end
    local band = nil
    pcall(function()
        local _, ago = reacquire_griffin()
        local nm = ago and tostring(go_name(ago) or "") or ""
        band = nm:match("ch%d+")
    end)
    local function band_ok(r)
        if not band then return true end   -- no live body readable: trust the pointer
        return tostring(r and r.species or ""):find(band, 1, true) == 1
    end
    -- 1. the stamp (set at register/tame) -- but only if it fits the body
    if S.live_rec_id then
        for _, r in ipairs(st.companions) do
            if r.id == S.live_rec_id then
                if band_ok(r) then return r end
                break   -- stamped record is the wrong species for this body: distrust it
            end
        end
    end
    -- 2. the selection, if (and only if) it fits the body
    local ar = griffin_stable_active()
    if ar and band_ok(ar) then
        -- heal the stamp so the next read is direct
        if band then S.live_rec_id = ar.id end
        return ar
    end
    -- 3. a UNIQUE species match anywhere in the stable (one drake record + a drake body
    --    out = unambiguous, whatever the panel has selected)
    if band then
        local hit = nil
        for _, r in ipairs(st.companions) do
            if band_ok(r) then
                if hit then return nil end   -- two same-species records: ambiguous, do nothing
                hit = r
            end
        end
        if hit then
            S.live_rec_id = hit.id   -- heal the stamp
            return hit
        end
    end
    return nil
end

local function clear_griffin()
    set_rider_hard_lock(false)
    restore_disabled()
    -- only forget the ACTIVE body: parked companions keep hook protection
    if S.griffin then mounts[S.griffin] = nil end
    S.griffin = nil
    S.griffin_go = nil
    S.live_rec_id = nil
    S.griffin_name = "(none)"
    S.pending_spawn = false
    S.mounted = false
    S.flying = false
    S.airborne = false
    S.jump_prev = false
    S.heading_yaw = nil
    S.ground_y = nil
    S.ride_origin = nil
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    S.last_drive_write_clock = 0.0
    S.nav_pulse_request = false
    S.nav_pulse_until_clock = 0.0
    clear_motion_queue()
end

local function spawn_griffin()
    if not ok_spawn then
        status("EnemySpawner/spawnRequest could not be required")
        return
    end
    -- ⛔ NEVER BIRTH A BODY WHILE THE GAME IS PAUSED (Aurora 2026-07-25: "I've crashed the game so
    -- many times by accident because I forget this"). Pause and photo mode stop the systems a new
    -- character needs in order to finish constructing -- it lands half-built, and the next frame
    -- that touches it is a native crash pcall cannot catch.
    --
    -- Queue instead of refusing: the click was still a real intent, so it fires the moment play
    -- resumes. This is the single choke-point every spawn route reaches, so guarding it here
    -- covers the panel buttons, the stable summon, the whistle and the soul restore at once.
    if griffin_world_paused() then
        S.route3_spawn_request = true
        status("the menu is open -- " .. tostring(C.route3_griffin_name or "your companion")
            .. " will appear when you close it")
        return
    end
    local pos, rot, detail = route3_find_safe_stable_spawn(C.route3_stable_spawn_distance)
    if not pos then
        status("spawn refused: " .. tostring(detail or "no safe floor near the Arisen"))
        return false
    end

    if S.spawner then pcall(function() S.spawner:deleteAll() end) end
    clear_griffin()

    S.spawner = SpawnRequest:new()
    -- the tame-shrink scale exists to fit the GIANT rideables (griffin/drake/chimera/wyvern);
    -- everything else spawns TRUE SIZE (the 0.55 global made the rabbit a kitten -- Aurora).
    -- Same big-family test tame_creature uses.
    local code7 = tostring(C.spawn_code or "")
    local big7 = code7:find("ch253", 1, true) == 1 or code7:find("ch257", 1, true) == 1
        or code7:find("ch254", 1, true) == 1 or code7:find("ch258", 1, true) == 1
    local sc7 = big7 and (tonumber(C.spawn_scale) or 1.0) or 1.0
    -- ⭐ BORN AT SIZE (2026-08-08, Aurora: "have them appear at the exact scale instead of
    -- shrinking down"): a hatchling's body used to spawn at the ADULT scale and get
    -- scale-written down a beat later -- the visible shrink pop. Ask the growth curve for
    -- its CURRENT size and hand THAT to the spawner's ovrScale, so the baby is literally
    -- born tiny; the growth tick keeps easing from there seamlessly.
    pcall(function()
        local rec7 = griffin_stable_active()
        local h7 = rec7 and rec7.hatch
        if h7 then
            local baby7 = tonumber(h7.baby_scale) or 0.12
            local full7 = tonumber(h7.full) or (tonumber(C.spawn_scale) or 0.45)
            local t7 = 0.0
            local igh7 = iris_bridge_igh()
            if igh7 and tonumber(h7.igh0) then
                t7 = math.max(0.0, math.min(1.0,
                    (igh7 - tonumber(h7.igh0)) / math.max(0.1, (tonumber(h7.growth_days) or 10.0) * 24.0)))
            end
            sc7 = baby7 + (full7 - baby7) * t7
        end
    end)
    local cfg = {
        spawnIdle = C.spawn_idle == true,
        instLimit = 1,
        spawnMultiple = { enable = false, qty = 1 },
        ovrScale = {
            enable = sc7 ~= 1.0,
            scale = sc7,
            normalizeSpeed = false,
        },
    }
    S.spawner:updateConfig(cfg)
    -- 08-08 (Aurora: "Shadow the WOLF came out a PANTHER -- the stable
    -- is giving the wolf the 25% cat chance"): a stable summon is a
    -- fresh ch223 spawn, and IrisWildCats rolls its conversion on
    -- every fresh ch223. Claim the next roll as VANILLA so a summoned
    -- companion is exactly its recorded species. (Cat companions are
    -- distinct _01/_00 dog-prefab bodies -- pak-skinned, no roll
    -- needed -- so vanilla is correct for every ch223 record.)
    if tostring(C.spawn_code or ""):find("ch223", 1, true) then
        pcall(function()
            local capi = rawget(_G, "__iris_wild_cats_api")
            if capi and capi.claim_next then
                capi.claim_next("vanilla")
            end
        end)
    end
    -- RESOLVE the spawn code against the CharacterID enum FIRST: saved species strings can
    -- carry @guid suffixes or variant spellings (critters = ch299200_A_00@...) the enum does
    -- not know -- an unknown string used to flow nil into getPfbCtrl and CRASH (the rabbit).
    local code9 = tostring(C.spawn_code or "")
    local band9 = code9:match("ch%d+")
    local cid9 = nil
    pcall(function() cid9 = S.spawner:getCharID(code9) end)
    -- ⛔ a BARE band name (ch299200) RESOLVES in the enum but is NOT a spawnable body -- the
    -- catalog holds the lettered variants (ch299200_A_00 = the rabbit Aurora actually tamed).
    -- The old "shortest name" pick chose the bare band and poisoned the saved code. Rule:
    -- prefer band_A_00; else the shortest REAL variant; never settle for the bare band.
    if band9 and (not cid9 or code9 == band9) then
        pcall(function()
            local byName9 = S.spawner.enums and S.spawner.enums.charID and S.spawner.enums.charID.byName
            if not byName9 then return end
            local pick9 = byName9[band9 .. "_A_00"] and (band9 .. "_A_00") or nil
            if not pick9 then
                for nm9, _ in pairs(byName9) do
                    nm9 = tostring(nm9)
                    if nm9:find(band9, 1, true) == 1 and nm9 ~= band9 then
                        if not pick9 or #nm9 < #pick9 then pick9 = nm9 end
                    end
                end
            end
            if pick9 then
                code9 = pick9
                C.spawn_code = pick9   -- heal the saved code for next time
                pcall(function() cid9 = S.spawner:getCharID(code9) end)
            end
        end)
    end
    if not cid9 then
        status("spawn refused: '" .. tostring(C.spawn_code) .. "' is not in the spawner's CharacterID enum (no crash, no spawn)")
        return false
    end
    local ok8 = pcall(function() S.spawner:requestAddInstances(code9, pos, rot, cfg, 1) end)
    if not ok8 then
        -- the CharacterID EXISTS but the ENEMY catalog refuses it (wildlife like the rabbit
        -- lives outside the enemy list): refuse cleanly + dump forensics for the next lever
        pcall(function()
            local band8 = tostring(code9):match("ch%d+")
            local names8 = {}
            local byName8 = S.spawner.enums and S.spawner.enums.charID and S.spawner.enums.charID.byName
            if byName8 and band8 then
                for nm8, id8 in pairs(byName8) do
                    if tostring(nm8):find(band8, 1, true) then names8[#names8 + 1] = tostring(nm8) .. "=" .. tostring(id8) end
                end
            end
            local cats8 = {}
            pcall(function() for k8 in pairs(S.spawner.catalogs or {}) do cats8[#cats8 + 1] = tostring(k8) end end)
            log.info("[GriffinRideProbe] spawn catalog refusal: code=" .. tostring(code9)
                .. " band_enum={" .. table.concat(names8, ", ") .. "} catalogs={" .. table.concat(cats8, ", ") .. "}")
        end)
        status("spawn refused: the ENEMY catalog has no '" .. tostring(code9) .. "' (wildlife) -- forensics in the log")
        S.pending_spawn = nil
        return false
    end
    S.pending_spawn = true
    status("spawn requested: " .. tostring(code9) .. " (" .. tostring(detail or "safe floor") .. ")")
    return true
end

local function delete_griffin()
    S.mounted = false
    S.flying = false
    S.airborne = false
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    S.route3_takeoff_lock_until = 0.0
    S.route3_takeoff_lock_status = "(stopped)"
    if route3_clear_landing_request then route3_clear_landing_request() end
    set_native_rider_suppressed(false)
    set_rider_hard_lock(false)
    if route3_recover_rider_state then route3_recover_rider_state("delete") end
    set_griffin_puppet(false)
    if S.spawner then pcall(function() S.spawner:deleteAll() end) end
    clear_griffin()
    -- a deliberate delete releases the active companion's soul too
    griffin_stable_remove_active()
    status("griffin deleted")
end

-- === THE STABLE: multi-companion souls =======================================
-- Bodies are disposable; each companion's identity {name, species, parked
-- spot} lives as a record in MOD_stable.json. One ACTIVE companion at a time:
-- the active record doubles as the legacy single-soul (S.route3_tamed_record
-- shim) so all the crash-hardened restore machinery works unchanged.







-- per-species tuning: every creature keeps its own clip set, seat and scale.
-- Saved to MOD_species_profiles.json keyed by spawn code; applied on tame and
-- on soul-restore so tuning the drake never un-tunes the griffin.
griffin_profile_keys = {
    "flap_takeoff_clip", "flap_seg_start", "flap_seg_end", "flap_glide_clip",
    "flap_clip_loops", "flap_loop_seconds",
    "takeoff_motion", "landing_motion", "landing_end_motion",
    "route3_jump_clip_start", "route3_jump_clip_mid", "route3_jump_clip_fall", "route3_jump_clip_land", "route3_landing_descent_clip",
    "route3_jump_native_bank", "route3_jump_native_clip",
    "flap_glide_bank", "route3_rise_node_up", "route3_rise_node_down",
    "route3_rise_ascend_clip", "route3_rise_ascend_start_clip",
    "route3_rise_descend_clip", "route3_rise_descend_start_clip", "route3_rise_clip_bank",
    "route3_ground_jump_windup", "route3_rise_secs", "route3_pawn_ride_back",
    "route3_rise_retire_at_window", "route3_loopcam_dist", "route3_soar_directional",
    "route3_flap_blend_frames", "route3_allow_sprint", "route3_allow_flight",
    "route3_mountable",
    "route3_seat_offset_x", "route3_seat_offset_y", "route3_seat_offset_z",
    "route3_air_seat",
    "spawn_scale", "route3_landing_height_offset",
    "root_motion_walk", "root_motion_run", "root_motion_idle", "idle_motion",
}

function griffin_species_key()
    return tostring(S.route3_tamed_species or C.spawn_code or "ch253000_00")
end

function griffin_species_profile_save()
    local key = griffin_species_key()
    local all = nil
    pcall(function() all = json.load_file(MOD .. "_species_profiles.json") end)
    all = all or {}
    local p = {}
    for _, k in ipairs(griffin_profile_keys) do p[k] = C[k] end
    all[key] = p
    pcall(function() json.dump_file(MOD .. "_species_profiles.json", all) end)
    S.route3_profile_status = "saved profile: " .. key
    return true
end

function griffin_species_profile_apply(key)
    key = tostring(key or griffin_species_key())
    local all = nil
    pcall(function() all = json.load_file(MOD .. "_species_profiles.json") end)
    local p = all and all[key]
    if not p then
        S.route3_profile_status = "no saved profile for " .. key .. " (using current tuning)"
        return false
    end
    local migrated = false
    if key:find("ch253", 1, true)
        and math.floor(tonumber(p.route3_landing_descent_clip) or -1) == 5210 then
        p.route3_landing_descent_clip = 5031
        migrated = true
    end
    -- DRAKE (ch257) 2026-08-11: the profile was born as a raw griffin copy and most
    -- griffin ids don't exist in ch57 banks (= the T-poses). Every id below is
    -- name-verified against Animal Atlas ch257000. Guarded on the copy signature
    -- (glide 5190 = griffin add_pose_F, no such clip on ch57) so hand tuning after
    -- the migration is never overwritten.
    if key:find("ch257", 1, true)
        and math.floor(tonumber(p.flap_glide_clip) or -1) == 5190 then
        p.flap_glide_clip = 5100              -- com_flight_loop (steady soar)
        p.flap_glide_bank = 0
        p.landing_motion = 400                -- com_Landing_Front (ch57 has no hover_landing family)
        p.landing_end_motion = 401
        p.route3_landing_descent_clip = 5101  -- com_flight_loop_Flapping (safe under movement)
        p.route3_jump_clip_start = 5210       -- com_Takeoff_normal: ch57 has no jump clips -> wing hop
        p.route3_jump_clip_mid = 5101
        p.route3_jump_clip_fall = 5101
        p.route3_jump_clip_land = 401
        p.route3_jump_native_bank = 0
        p.route3_jump_native_clip = 5210
        p.root_motion_run = 100               -- ch57 has NO run/dash clip; walk until the
        p.route3_allow_sprint = false         -- Furious-Charge gallop is built
        migrated = true
    end
    -- per-species keys added 2026-08-11 (glide bank + rise/dive nodes): backfill any
    -- profile saved before they existed, otherwise applying species A leaks species
    -- B's last values through the shared C.
    if p.flap_glide_bank == nil then
        p.flap_glide_bank = key:find("ch257", 1, true) and 0 or 50
        migrated = true
    end
    if p.route3_rise_node_up == nil then
        if key:find("ch257", 1, true) then
            p.route3_rise_node_up = "Fly.Hovering.Ch257_HoverUp"    -- quick ascend (verified in the
            p.route3_rise_node_down = "Fly.Hovering.Ch257_HoverDown" -- live ch257 node-tree dump)
        else
            p.route3_rise_node_up = "Fly.Flight.Ch253LoopTheLoopFlight"
            p.route3_rise_node_down = "Fly.Flight.Ch253LoopTheLoopFlight"
        end
        migrated = true
    end
    -- v3 2026-08-11 (field round 3, from Aurora's recordings): ⛔ STREAMED-CLIP LAW EXTENDS
    -- TO THE DRAKE -- 5100/5101 evaluate to NULL on her parked FSM (flat-splayed wing T-pose
    -- on video, exactly at the jump-mid/glide/descent phases that painted them). Resident-only
    -- everywhere: glide -1 (flap.lua's own drake design: "just keep flapping through a
    -- sprint" -- also stops the soar machinery painting griffin bank-50 dush clips), jump =
    -- launch clip held through the arc, landing descent = the front-landing approach clip.
    -- ⛔ v11 guard: node_up ~= "" limits this to PRE-v10 profiles. v10 deliberately sets
    -- glide back to 5100 (nodeless flight) -- without the guard this block re-fired on every
    -- auto-apply and ate v10's values (ascend -1 = dead A-press, glide -1 = dead soar).
    if key:find("ch257", 1, true)
        and math.floor(tonumber(p.flap_glide_clip) or -1) == 5100
        and tostring(p.route3_rise_node_up or "") ~= "" then
        p.flap_glide_clip = -1
        p.route3_landing_descent_clip = 400   -- com_Landing_Front approach (5101 = null T-pose)
        p.route3_jump_clip_mid = -1           -- hold the 5210 launch flap through the arc
        p.route3_jump_clip_fall = -1
        p.route3_rise_ascend_clip = -1        -- ascend clip was invisible (same clip as cruise
                                              -- flap); movement-only until Aurora picks a NODE
        migrated = true
    end
    -- v4 2026-08-11 (field round 4, Aurora's timing notes): jump wind-up + rise duration go
    -- per-species. Drake: her takeoff clip preps ~3s before the leap, so the arc waits for it;
    -- rise nodes retire with the burst window, so a longer burst = the node animation actually
    -- plays out. Landing descent 400 was the FULL landing clip = a mid-air impact -- descend on
    -- wing-beats (5210) instead; 401 stays the single touchdown.
    if p.route3_ground_jump_windup == nil then
        if key:find("ch257", 1, true) then
            p.route3_ground_jump_windup = 2.0
            p.route3_rise_secs = 3.5
            p.route3_landing_descent_clip = 5210
            -- Aurora's field picks (round 4): travel nodes with the good flight animation
            p.route3_rise_node_up = "Fly.Flight.FlightPathTraceTarget"
            p.route3_rise_node_down = "Fly.Flight.FlightTarget"
        else
            p.route3_ground_jump_windup = tonumber(C.route3_ground_jump_windup) or 0.5
            p.route3_rise_secs = tonumber(C.route3_rise_secs) or 1.75
        end
        migrated = true
    end
    -- v7 2026-08-11: window-end retire per-species (drake ON -- her travel nodes sustain
    -- forever; griffin OFF -- LoopTheLoop must outlive its window).
    if p.route3_rise_retire_at_window == nil then
        p.route3_rise_retire_at_window = (key:find("ch257", 1, true) ~= nil)
        migrated = true
    end
    -- v6 2026-08-11: pawn seat goes per-species. Aurora's knock theory: player + pawn colliding
    -- on the back when nodes pitch the body. The drake's back is long -- seat the pawn well aft.
    if p.route3_pawn_ride_back == nil then
        p.route3_pawn_ride_back = key:find("ch257", 1, true) and 3.0
            or (tonumber(C.route3_pawn_ride_back) or 0.0)
        migrated = true
    end
    -- ⭐ SELF-HEAL 2026-08-11: Aurora accidentally SAVED the drake's live tuning over the
    -- griffin's profile (SAVE captures the shared C under whichever body is active -- a design
    -- trap, see note at the SAVE button). A ch253 profile carrying drake fingerprints is
    -- corrupt: restore the known-good griffin block (captured from disk 2026-08-11, pre-
    -- corruption, plus this file's own migration backfills).
    if key:find("ch253", 1, true)
        and (tostring(p.route3_rise_node_up or ""):find("FlightPathTrace", 1, true)
            or tostring(p.route3_rise_node_up or ""):find("Ch257", 1, true)
            or p.route3_rise_retire_at_window == true) then
        p.flap_takeoff_clip = 5210; p.flap_seg_start = 127.0; p.flap_seg_end = 230.0
        p.flap_glide_clip = 501; p.flap_glide_bank = 50
        p.flap_clip_loops = false; p.flap_loop_seconds = 1.5
        p.route3_flap_blend_frames = 20.0
        p.takeoff_motion = 5210; p.landing_motion = 5030; p.landing_end_motion = 5032
        p.route3_landing_descent_clip = 5031
        p.route3_jump_clip_start = 422; p.route3_jump_clip_mid = 423
        p.route3_jump_clip_fall = 416; p.route3_jump_clip_land = 401
        p.route3_jump_native_bank = 0; p.route3_jump_native_clip = 440
        p.route3_rise_node_up = "Fly.Flight.Ch253LoopTheLoopFlight"
        p.route3_rise_node_down = "Fly.Flight.Ch253LoopTheLoopFlight"
        p.route3_rise_ascend_clip = 702; p.route3_rise_ascend_start_clip = 700
        p.route3_rise_descend_clip = 551; p.route3_rise_descend_start_clip = 550
        p.route3_rise_clip_bank = 50
        p.route3_ground_jump_windup = 0.5; p.route3_rise_secs = 1.75
        p.route3_pawn_ride_back = 0.0; p.route3_rise_retire_at_window = false
        p.route3_loopcam_dist = 14.0
        p.route3_allow_sprint = true; p.route3_allow_flight = true; p.route3_mountable = true
        p.root_motion_walk = 100; p.root_motion_run = 200; p.root_motion_idle = -1
        p.idle_motion = 0
        p.route3_seat_offset_x = 0.0; p.route3_seat_offset_y = 2.3; p.route3_seat_offset_z = 1.6
        p.spawn_scale = 0.55
        migrated = true
    end
    -- ⭐⭐ v10 2026-08-12 -- NODELESS FLIGHT (Aurora's call, and the right one): held travel
    -- nodes flicker the climb state natively (unhookable -- getter pin AND setter veto both
    -- failed on instruments), and that flicker IS the close-up camera AND the knocking. Drop
    -- the nodes entirely: ascend/descend/soar = movement + clip 5100 (com_flight_loop, the
    -- majestic locked-wing soar). ⚠ FIELD TEST: 5100 is in the streamed family -- if it
    -- paints as T-pose airborne, fall back to flap-base + additive hover poses (L1).
    if key:find("ch257", 1, true)
        and tostring(p.route3_rise_node_up or "") == "Fly.Flight.FlightPathTraceTarget" then
        p.route3_rise_node_up = ""
        p.route3_rise_node_down = ""
        p.route3_rise_ascend_clip = 5100
        p.route3_rise_ascend_start_clip = -1
        p.route3_rise_descend_clip = 5100
        p.route3_rise_descend_start_clip = -1
        p.route3_rise_clip_bank = 0
        p.flap_glide_clip = 5100          -- B-soar = the same glide loop
        p.flap_glide_bank = 0
        p.route3_rise_retire_at_window = false   -- nothing to retire anymore
        p.route3_soar_directional = false -- directional soar sub-clips are griffin bank-50 ids
        migrated = true
    end
    if p.route3_soar_directional == nil then
        p.route3_soar_directional = not key:find("ch257", 1, true)
        migrated = true
    end
    -- ⭐ v12 2026-08-12 AIR SEAT: drake flight releases the native climb (10 instrumented rounds:
    -- the climb is geometrically unable to hold a rider on ch257 in flight -- grip blinks, abort
    -- storm, cling camera). nil-guard = idempotent (the v11 lesson: value-matched migrations
    -- must be era-guarded; nil-backfills can't re-fire).
    if p.route3_air_seat == nil then
        p.route3_air_seat = key:find("ch257", 1, true) ~= nil
        migrated = true
    end
    -- v13 (Aurora: "a long R3 descend has the drake start doing a take off animation"):
    -- 5210 IS her takeoff clip -- it was the landing-descent pick back when nothing else
    -- painted airborne. 5100 (the glide loop) paints reliably now (v10+ field-proven).
    -- Era-guarded on the air-seat key existing (v11 law: value matches need era guards).
    if key:find("ch257", 1, true) and p.route3_air_seat ~= nil
        and math.floor(tonumber(p.route3_landing_descent_clip) or -1) == 5210 then
        p.route3_landing_descent_clip = 5100
        migrated = true
    end
    -- ⭐ v11 2026-08-12 REPAIR: v3 re-fired after v10 (its glide==5100 trigger matched v10's
    -- intended value) and clobbered three v10 values on the very next auto-apply. Restore them.
    -- Signature = post-v10 (nodes cleared) but ascend dead -- exactly the clobbered state.
    if key:find("ch257", 1, true)
        and tostring(p.route3_rise_node_up or "") == ""
        and math.floor(tonumber(p.route3_rise_ascend_clip) or -1) == -1 then
        p.route3_rise_ascend_clip = 5100
        p.route3_rise_descend_clip = 5100
        p.route3_rise_clip_bank = 0
        p.flap_glide_clip = 5100
        p.flap_glide_bank = 0
        if math.floor(tonumber(p.route3_landing_descent_clip) or -1) == 400 then
            p.route3_landing_descent_clip = 5210   -- v4's fix (400 = mid-air impact) re-asserted
        end
        migrated = true
    end
    -- ⭐ SELF-HEAL part 2 (08-11, found by full disk diff): the v4/v6 BACKFILLS seeded new keys
    -- from the live shared C "to preserve current tuning" -- but C held the DRAKE's tuning when
    -- the griffin's profile first gained those keys, so three drake values leaked in under the
    -- fingerprint radar. Heal them by exact leaked value (hand-tuning stays safe).
    if key:find("ch253", 1, true) then
        if tonumber(p.route3_ground_jump_windup) == 3.0 or tonumber(p.route3_ground_jump_windup) == 2.0 then
            p.route3_ground_jump_windup = 0.5; migrated = true
        end
        if tonumber(p.route3_rise_secs) == 3.5 then p.route3_rise_secs = 1.75; migrated = true end
        -- 0.9 = the ORIGINAL global tuning (recovered from the Wayfarer repo's 17:30 pre-chaos
        -- snapshot); my first heal's 0.0 stacked the pawn ON TOP of the Arisen
        if tonumber(p.route3_pawn_ride_back) == 3.0 or tonumber(p.route3_pawn_ride_back) == 0.0 then
            p.route3_pawn_ride_back = 0.9; migrated = true
        end
    end
    -- v8 2026-08-11 (camtrace verdict): the "native close-up" was TWO cameras both too close
    -- to a very large body -- the native cling cam locks to ~5.6m during Fly.* (measured), and
    -- OUR loopcam's griffin-tuned 14m is ALSO a close-up on a drake. Shot distance goes
    -- per-species; the drake films wide.
    if p.route3_loopcam_dist == nil then
        p.route3_loopcam_dist = key:find("ch257", 1, true) and 28.0
            or (tonumber(C.route3_loopcam_dist) or 14.0)
        migrated = true
    end
    -- v9 2026-08-11: pawn 3m-aft seat reverted (knocking was NOT the pawn -- solo test proved
    -- it -- and the aft seat looked odd). "Normal" = 0.9, the original pre-split global tuning
    -- (Wayfarer repo 17:30 snapshot), NOT 0.0 -- zero stacks the pawn on the Arisen.
    if key:find("ch257", 1, true)
        and (tonumber(p.route3_pawn_ride_back) == 3.0 or tonumber(p.route3_pawn_ride_back) == 0.0) then
        p.route3_pawn_ride_back = 0.9
        migrated = true
    end
    -- v5 2026-08-11: v4 shipped windup 3.0; Aurora field-timed it "about a second off" -> 2.0.
    -- Guarded on the exact v4 value so her own later hand-tuning is never overwritten.
    if key:find("ch257", 1, true) and tonumber(p.route3_ground_jump_windup) == 3.0 then
        p.route3_ground_jump_windup = 2.0
        migrated = true
    end
    -- v2 2026-08-11 (field round 2): the rise CLIP set goes per-species (griffin's are
    -- bank-50 ids that don't exist on other species). Guarded on the new key being absent.
    if p.route3_rise_ascend_clip == nil then
        if key:find("ch257", 1, true) then
            -- field verdict: Ch257_HoverUp fires+survives but is visually ~identical to
            -- normal flight. Ascend = the takeoff wing-burst CLIP instead (proven safe
            -- under movement -- it is her working takeoff); node cleared so the clip paints.
            p.route3_rise_node_up = ""
            p.route3_rise_ascend_start_clip = -1
            p.route3_rise_ascend_clip = 5210      -- com_Takeoff_normal wing burst
            p.route3_rise_descend_start_clip = -1
            p.route3_rise_descend_clip = -1       -- descend stays node-only (Ch257_HoverDown)
            p.route3_rise_clip_bank = 0
            p.route3_allow_sprint = true          -- v1 set false and that killed air-soar too; revert
            p.landing_motion = 5205               -- move_change_flight_to_hover = air-brake (400 was a
                                                  -- ground-impact clip painted MID-AIR = a knock source)
            p.idle_motion = 4                     -- com_idle_loop_watch: calm idle, no tail-lash
                                                  -- (knock-after-landing A/B test)
        else
            p.route3_rise_ascend_start_clip = 700 -- prior globals, unchanged behaviour
            p.route3_rise_ascend_clip = 702
            p.route3_rise_descend_start_clip = 550
            p.route3_rise_descend_clip = 551
            p.route3_rise_clip_bank = 50
        end
        migrated = true
    end
    for _, k in ipairs(griffin_profile_keys) do
        if p[k] ~= nil then C[k] = p[k] end
    end
    if migrated then pcall(function() json.dump_file(MOD .. "_species_profiles.json", all) end) end
    S.route3_profile_status = "applied profile: " .. key
    return true
end


function griffin_find_wild(radius)
    radius = tonumber(radius) or 25.0
    local pgo = char_go(get_player())
    local ppos = pgo and transform_pos(pgo)
    if not ppos then return nil, "no player" end
    local prefix = tostring(C.route3_tame_prefix or "ch253")
    local best, best_d, seen = nil, radius * radius, 0
    local names = {}
    local function consider(ch)
        if not ch then return end
        if S.griffin and same_obj(ch, S.griffin) then return end
        if is_dead(ch) then return end
        local go = char_go(ch)
        if not go then return end
        local name = tostring(go_name(go) or "")
        if #names < 8 then names[#names + 1] = name end
        if not name:find(prefix, 1, true) then return end
        local pos = transform_pos(go)
        if not pos then return end
        seen = seen + 1
        local d = distance_sq(pos, ppos)
        if d and d < best_d then best, best_d = ch, d end
    end
    local function sweep(mgr_name, getters)
        pcall(function()
            local mgr = singleton(mgr_name)
            if not mgr then return end
            for _, getter in ipairs(getters) do
                local list = nil
                pcall(function() list = mgr:call(getter) end)
                local n = 0
                pcall(function() n = list and list:call("get_Count") or 0 end)
                if (tonumber(n) or 0) > 0 then
                    for i = 0, n - 1 do
                        pcall(function() consider(list:call("get_Item", i)) end)
                    end
                    return
                end
            end
        end)
    end
    sweep("app.CharacterManager", { "get_CharacterList", "getCharacterList", "get_AllCharacterList", "get_CharacterAll" })
    if not best then
        sweep("app.EnemyManager", { "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" })
    end
    if not best then
        -- SCENE SWEEP (the RiftSpeak wildlife law): TAMED bodies are no longer
        -- enemies — the ally switch removes them from the enemy list, so the
        -- managers can't see them. Enumerate every app.Character in the scene.
        pcall(function()
            local sm = sdk.get_native_singleton("via.SceneManager")
            local smt = sdk.find_type_definition("via.SceneManager")
            local scene = sdk.call_native_func(sm, smt, "get_CurrentScene")
            if not scene then return end
            local comps = scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
            for _, comp in ipairs(system_array_to_table(comps) or {}) do
                pcall(function() consider(comp) end)
            end
        end)
    end
    S.route3_find_debug = table.concat(names, " | ")
    return best, string.format("candidates=%d seen: %s", seen, S.route3_find_debug ~= "" and S.route3_find_debug or "(none)")
end


-- ===== THE OX-TAME DESCENT (P2): fly a PACIFIED wild griffin to the offering =====
-- Preconditions guaranteed taming-side (grounded + full_pacify + AI off). Recipe = the
-- victim-carry combo: think ALIVE + motion-FSM puppet + direct L0 clip + transform drive.
-- ⛔ flight clips on a think-STOPPED griffin = native AV; never that.
function iris_oxtame_ceremony_cut_native(D, ch, go)
    -- Full puppet ownership needs all THREE locomotion authorities cut. FlightControl controls lift,
    -- NavigationAI continues the old path even with its decision-maker off, and the character/
    -- ground controllers reconcile our root back onto their physics position. Record exact enabled
    -- states so every abort and the feeding hand-off can restore what this ceremony borrowed.
    if not (D and D.ceremony and ch and go) then return end
    D.native_cut = D.native_cut or {}
    D.native_cut_names = D.native_cut_names or {}
    local function cut_component(c, label)
        if not c then return end
        local key = tostring(c)
        if not D.native_cut[key] then
            local was = true
            pcall(function() local v = c:call("get_Enabled"); if type(v) == "boolean" then was = v end end)
            D.native_cut[key] = { obj = c, was = was }
            D.native_cut_names[#D.native_cut_names + 1] = tostring(label or "?")
        end
        pcall(function() c:call("set_Enabled", false) end)
    end
    cut_component(get_component(go, "app.NavigationAI"), "app.NavigationAI")
    pcall(function()
        for _, c in ipairs(system_array_to_table(go:call("get_Components")) or {}) do
            local full = ""
            pcall(function() full = tostring(c:get_type_definition():get_full_name() or "") end)
            if full:find("GroundFixer", 1, true) or full:find("CharacterController", 1, true) then
                cut_component(c, full)
            end
        end
    end)
    pcall(function() set_character_controller_enabled(ch, false) end)
    D.character_controller_cut = true
    if not D.native_cut_logged then
        D.native_cut_logged = true
        local n0 = 0
        for _ in pairs(D.native_cut) do n0 = n0 + 1 end
        pcall(function() log.info(string.format(
            "[OxTame] puppet ownership cut: %d components [%s] + Character controller API",
            n0, table.concat(D.native_cut_names, ", "))) end)
    end
end

function iris_oxtame_ceremony_restore_native(D)
    if not D then return end
    if D.native_cut then
        for _, rec in pairs(D.native_cut) do
            pcall(function()
                if rec.obj then rec.obj:call("set_Enabled", rec.was ~= false) end
            end)
        end
        D.native_cut = nil
    end
    if D.character_controller_cut and D.ch then
        pcall(function() set_character_controller_enabled(D.ch, true) end)
        D.character_controller_cut = nil
    end
end

function iris_oxtame_apply_transform(ch, go, pos, rot)
    -- The mounted air drive's proven ownership write updates BOTH position channels. Universal alone
    -- renders correctly for a few seconds, then the engine periodically reconciles from its cached
    -- ordinary Position and snaps a wild griffin hundreds of metres back onto its former route.
    if not (ch and go and pos and sane_position(pos)) then return false end
    local old_ours = S.route3_our_write
    S.route3_our_write = true
    local ok = false
    pcall(function()
        local tf = go:call("get_Transform")
        if tf then
            tf:call("set_UniversalPosition", pos)
            pcall(function() tf:call("set_Position", pos) end)
            if rot then tf:call("set_Rotation", rot) end
            ok = true
        end
    end)
    pcall(function()
        local tf = ch:call("get_Transform")
        if tf then
            tf:call("set_UniversalPosition", pos)
            pcall(function() tf:call("set_Position", pos) end)
            if rot then tf:call("set_Rotation", rot) end
            ok = true
        end
        pcall(function() ch:call("set_UniversalPosition", pos); ok = true end)
        if rot then pcall(function() ch:call("set_Rotation", rot); ok = true end) end
    end)
    S.route3_our_write = old_ours
    return ok
end

function iris_oxtame_descend_tick()
    -- ⭐ release a HELD reject flag once its window closes (see oxtame_buck's hold_secs). This runs
    -- before everything else and regardless of whether a drive exists, because leaving her rejecting
    -- default requests forever would wedge her AI completely.
    if S.oxtame_reject and os.clock() >= (tonumber(S.oxtame_reject.until_t) or 0.0) then
        local R = S.oxtame_reject
        S.oxtame_reject = nil
        pcall(function() R.am:call("set_IsRejectRequestOnDefault", R.orig == true) end)
        pcall(function() log.info("[OxTame] reject-hold released -- her decision maker has the wheel again") end)
    end
    local D = S.oxtame_fly
    if not D then
        -- ⭐⭐ POST-ARRIVAL KEEP-ALIVE (07-25, Aurora: "it dived down and when it got to the ground it
        -- just died xD"). An FC-off descent reads to the engine as FALLING, and the landing cashes
        -- the whole fall in as damage a few frames AFTER touchdown -- by which point the drive has
        -- already cleared itself and its per-tick HP top-up has stopped. Immunity does not cover it
        -- (fall damage is not a hit). So the top-up outlives the drive by a few seconds.
        local G = S.oxtame_alive
        if G and os.clock() < (tonumber(G.until_t) or 0.0) then
            pcall(function()
                if G.ch and not is_dead(G.ch) and tonumber(G.hp0) and G.hp0 > 0 then
                    route3_grab_keep_alive(G.ch, G.hp0)
                end
            end)
        elseif G then
            S.oxtame_alive = nil
        end
        return
    end
    if S.world_paused == true then return end
    local ch = D.ch
    local go = ch and char_go(ch)
    if not go or is_dead(ch) then
        -- say so: a mid-drive death used to vanish the drive SILENTLY, leaving the log showing a
        -- healthy dive that simply stopped (and the scene later blaming "she left the sweep")
        if is_dead(ch) then pcall(function() log.info("[OxTame] ⛔ the griffin DIED mid-drive -- keep-alive failed to hold her") end) end
        pcall(function() iris_oxtame_ceremony_restore_native(D) end)
        S.oxtame_fly = nil
        return
    end
    local now = os.clock()
    local dt = now - (tonumber(D.last) or now)
    D.last = now
    if dt <= 0.0 or dt > 0.1 then dt = 0.033 end
    if not D.rodeo and not D.hold and now - (tonumber(D.t0) or now) > 90.0 then   -- watchdog: never fly her forever (90s = a nest 800m out at 13 m/s)
        -- ⭐ FULL RESTORE (07-23, Aurora: after the timed-out drive she "just flew down into the
        -- wall" and despawned): the old watchdog un-puppeted + gave FC back but LEFT the
        -- AIDecisionMaker off and the stale action latched -- a brainless body on bare flight
        -- physics. Same restore bundle as the runaway abort, so a timed-out griffin gets her
        -- whole wild brain back and the taming side can re-lure her.
        pcall(function() set_motion_fsm_puppet(go, false) end)
        pcall(function() iris_oxtame_ceremony_restore_native(D) end)
        pcall(function() set_think_stop(ch, false) end)
        pcall(function() ch:call("resetActionAndAI") end)
        pcall(function()
            local dm = go:call("getComponent(System.Type)", sdk.typeof("app.AIDecisionMaker"))
            if dm then dm:call("set_Enabled", true) end
        end)
        pcall(function()   -- undo a jump/ferry FC-cut: never leave a wild body flightless
            local fc = get_component(go, "app.FlightControl")
            if fc then fc:call("set_Enabled", true) end
        end)
        pcall(function() log.info("[OxTame] descent drive WATCHDOG (90s): full restore -- brain + flight handed back") end)
        S.oxtame_fly = nil
        return
    end
    local gp = transform_pos(go)
    if not gp then return end
    if D.ceremony then
        D.stage_radius = 250.0 -- commit before the near-player/full-simulation boundary can reclaim her
        iris_oxtame_ceremony_cut_native(D, ch, go) -- re-assert: native actions may re-enable these
    end
    -- ⭐ KEEP HER ALIVE THROUGH THE DRIVE (07-21, Aurora: "it flew down and when it touched the
    -- ground it DIED"): FC-off descents read as FALLING to the engine, and the landing cashes in
    -- the whole fall as damage -- immunity didn't cover it. The grab's proven keep-alive (per-frame
    -- HP top-up + revive-from-fall-death) runs for every oxtame drive leg.
    pcall(function()
        -- ⛔ RETRY A FAILED READ (07-25). This was `if not D.hp0` -- but in Lua **0 is truthy**, so
        -- one failed component read cached 0 forever, and the `> 0` guard below then silently
        -- skipped the keep-alive for the entire dive. A griffin whose hit controller was not ready
        -- on tick one got NO fall protection at all, which is how she died on touchdown.
        if (tonumber(D.hp0) or 0) <= 0 then
            local hc0 = griffin_target_hit_controller(ch)
            D.hp0 = hc0 and griffin_hp_max_from_component(hc0) or 0
        end
        if tonumber(D.hp0) and D.hp0 > 0 then
            route3_grab_keep_alive(ch, D.hp0)
            -- arm the post-arrival grace: the killing blow lands AFTER the drive clears itself
            S.oxtame_alive = { ch = ch, hp0 = D.hp0, until_t = now + 4.0 }
        end
    end)
    -- GROUND HOLD (07-18: the eat/palm/mount PIN). An air-seized griffin will not STAY planted --
    -- her flight physics floats her back up over a one-shot seat (images 144/145: she fed, sated,
    -- and reached the palm while HOVERING). So we keep the proven per-frame transform alive as a
    -- pin: hard-write her to the seat spot every frame. Position/rotation ONLY -- we never touch
    -- the motion here (the taming side owns the eat clips) and never kill her collision (the native
    -- mount-climb still needs it). Replaced when the rodeo lifts off; cleared on reset/scene end.
    if D.hold then
        -- ⛔ FC EVERY FRAME, NOT EVERY TICK (07-24, Aurora: "she's still vibrating through the
        -- lie-down and the lie loop"). The taming side re-cuts FlightControl on its 0.7s scene
        -- tick, which hands FC ~40 free frames to lift her between cuts -- and against a hard pin
        -- that reads as a buzz. A HELD griffin is by definition not flying, so silence it here,
        -- per frame, for every hold user (eat / palm / mount / pact) in one place.
        pcall(function()
            local fc = get_component(go, "app.FlightControl")
            if fc and fc:call("get_Enabled") == true then fc:call("set_Enabled", false) end
        end)
        -- ⭐ THE TURN (07-24, Aurora: "it just appears facing the other way -- can she rotate?").
        -- A one-shot set_Rotation teleported her through 180 degrees. The taming side now names a
        -- target heading and we SLEW to it here, per frame, so she visibly turns on the spot.
        if D.yaw_to then
            local cury = tonumber(D.yaw) or 0.0
            local diffy = wrap_angle((tonumber(D.yaw_to) or cury) - cury)
            local stepy = (tonumber(D.yaw_rate) or 1.6) * dt
            if math.abs(diffy) <= stepy then D.yaw = tonumber(D.yaw_to); D.yaw_to = nil
            else D.yaw = wrap_angle(cury + (diffy > 0.0 and stepy or -stepy)) end
        end
        pcall(function()
            -- SOFT MODE (07-18: the hard per-frame write FOUGHT the native mount-grab -- the climb
            -- would not latch, Aurora). In soft mode we only correct when she's ACTUALLY drifted
            -- (floated >0.6m, or slid >1.5m): while she sits grounded the pin is silent, so the
            -- grab can take AND the palm's turn-away rotation isn't snapped back to face the meal.
            local writeit = true
            if D.hold_soft then
                local gy = tonumber(gp.y) or D.ty
                local dxh = D.tx - (tonumber(gp.x) or D.tx)
                local dzh = D.tz - (tonumber(gp.z) or D.tz)
                writeit = (gy - D.ty > 0.6) or (gy - D.ty < -0.6) or (dxh * dxh + dzh * dzh > 2.25)
            end
            if writeit then
                local pos = make_position(D.tx, D.ty, D.tz)
                local rot = make_quat_yaw(tonumber(D.yaw) or 0.0)
                set_transform(go, pos, rot)
                set_character_transform(ch, pos, rot)
            end
        end)
        if now - (tonumber(D.t0) or now) > 120.0 then S.oxtame_fly = nil end   -- safety net; the scene clears it sooner
        return
    end
    -- ⭐ JUMP PHASE (relocate v3, 07-20): per-frame pin at the off-camera perch. v2's pin never
    -- held even per-frame -- the prime suspect is app.FlightControl: it INTEGRATES position from
    -- its own internal state (it's the very lift the hold pin fights), so the instant our writes
    -- stop she's "back" where FC thinks she is. v3 silences FC for the pin (the eat's proven
    -- disable) + pins longer (0.9s). Verify on release; a pin that STILL never held falls back to
    -- the FC-OFF FERRY: glide her in from her REAL spot with FC silenced the whole way -- the old
    -- ">180m native out-flies the drive" wall was measured BEFORE the FC-disable existed, and the
    -- last log's dh growth matched her cruise speed exactly = FC probably WAS the whole fight.
    if D.jump then
        if not D.jump.fc_cut then
            D.jump.fc_cut = true
            pcall(function()
                local fc = get_component(go, "app.FlightControl")
                if fc then fc:call("set_Enabled", false) end
            end)
        end
        if now < (tonumber(D.jump.until_t) or 0.0) then
            pcall(function()
                local pos = make_position(D.jump.x, D.jump.y, D.jump.z)
                local rot = make_quat_yaw(math.atan(D.tx - D.jump.x, D.tz - D.jump.z))   -- facing the meal
                set_transform(go, pos, rot)
                set_character_transform(ch, pos, rot)
            end)
            pcall(function() set_think_stop(ch, false) end)
            pcall(function() set_motion_fsm_puppet(go, true) end)
            return
        end
        -- release gate: this tick's read reflects the ENGINE's last word (not our own same-frame echo)
        local okj, drift = false, -1.0
        pcall(function()
            local gpj = transform_pos(go)
            if gpj then
                local dxj = (tonumber(gpj.x) or 0.0) - D.jump.x
                local dzj = (tonumber(gpj.z) or 0.0) - D.jump.z
                drift = math.sqrt(dxj * dxj + dzj * dzj)
                okj = drift < 30.0   -- still within 30m of the perch = the pin HELD
            end
        end)
        D.jump = nil
        if okj then
            -- pin held: hand FC back and run the PROVEN short glide, recipe unchanged
            pcall(function()
                local fc = get_component(go, "app.FlightControl")
                if fc then fc:call("set_Enabled", true) end
            end)
            pcall(function() log.info("[OxTame] JUMP pin HELD at the perch -- releasing into the short dive") end)
        else
            -- ⭐ FC-OFF FERRY FALLBACK: no teleport, no give-up -- glide her in from where she
            -- REALLY is with FlightControl silenced. Distance-loss leash below replaces the flat
            -- 450m guard for this mode (abort only if she's genuinely pulling AWAY from us).
            -- ⭐ WITH the ferry's terrain-following steering (07-20, img165: the straight-line glide
            -- wedged her flapping against a cliff at dh=192 forever) -- the ferry's old "spasm" WAS
            -- FlightControl fighting the drive, and FC is off here: the two fixes complete each other.
            D.fc_off = true
            D.ferry = true
            D.ferry_spd = tonumber(D.ferry_spd) or 45.0
            D.ferry_clear = tonumber(D.ferry_clear) or 55.0
            pcall(function() ch:call("resetActionAndAI") end)   -- drop the live hover action she kept through the failed pin
            pcall(function() log.info(string.format("[OxTame] JUMP pin never held (drift=%.0fm) -> FC-OFF terrain-following FERRY from her real spot", drift)) end)
        end
    end
    -- FC-OFF FERRY upkeep: keep FlightControl silenced every tick (native re-enables are cheap
    -- to counter here) and leash on distance-LOSS, not absolute range.
    if D.fc_off then
        pcall(function()
            local fc = get_component(go, "app.FlightControl")
            if fc and fc:call("get_Enabled") == true then fc:call("set_Enabled", false) end
        end)
    end
    -- THE RODEO FLIGHT (Act Two): rise off the pad, then a slow circle; stamina UNLIMITED
    -- until the bucks (P4 adds the waves + drain + outcomes). The rodeo only steers the
    -- TARGET -- the shared glide below does the flying.
    if D.rodeo then
        if not D.cy then
            D.cx = tonumber(gp.x) or 0.0; D.cy = tonumber(gp.y) or 0.0; D.cz = tonumber(gp.z) or 0.0
            D.ang = 0.0; D.phase = "lift"
        end
        pcall(function()   -- unlimited stamina for the mount + rise (Aurora's spec)
            local p9 = get_player()
            local sm9 = p9 and p9:call("get_StaminaManager")
            local mx9 = sm9 and sm9:call("get_MaxValue")
            if mx9 then sm9:call("set_RemainingAmount", mx9) end
        end)
        if D.phase == "lift" then
            D.tx = D.cx; D.ty = D.cy + 14.0; D.tz = D.cz
            if (tonumber(gp.y) or 0.0) >= D.cy + 13.0 then D.phase = "hold"; D.hold_t0 = now end
        elseif D.phase == "hold" then
            D.ang = (tonumber(D.ang) or 0.0) + 0.35 * dt
            D.tx = D.cx + math.sin(D.ang) * 9.0
            D.tz = D.cz + math.cos(D.ang) * 9.0
            D.ty = D.cy + 14.0
            if now - (tonumber(D.hold_t0) or now) > 120.0 then D.phase = "land" end   -- P4 replaces with outcomes
        elseif D.phase == "land" then
            -- back to the pad; the normal glide + arrival takes it from here
            D.rodeo = nil
            D.tx = D.cx; D.ty = D.cy; D.tz = D.cz
        end
    end
    -- LIVE PLAYER-DODGE (she landed on Aurora twice: dispatch-time offsets go stale over a
    -- 10s flight): every tick, if the player stands within 3.5m of the landing spot, the
    -- spot slides away from them
    pcall(function()
        if D.walk or D.rodeo then return end   -- stroll/rodeo don't dodge (the rider IS the player)
        -- STOP DODGING ON FINAL (07-18): you stand ON the ox you killed, so the landing spot sits
        -- ~1.5m from you -- the dodge then slides the target every tick and she can NEVER settle
        -- into the arrival window; she hovers over your head forever (images 141/142). Once she's
        -- within 5m of the spot she's committed: let it lock so she actually touches down.
        local ghx = D.tx - (tonumber(gp.x) or 0.0)
        local ghz = D.tz - (tonumber(gp.z) or 0.0)
        if (ghx * ghx + ghz * ghz) < 25.0 then return end
        local pgo = char_go(get_player())
        local pp = pgo and transform_pos(pgo)
        if not pp then return end
        local rx = D.tx - (tonumber(pp.x) or 0.0)
        local rz = D.tz - (tonumber(pp.z) or 0.0)
        local rd = math.sqrt(rx * rx + rz * rz)
        -- 1.6m: she lands BESIDE you, not INSIDE you -- the "move!" drama stays (Aurora's call)
        if rd < 1.6 then
            if rd < 0.1 then rx, rz, rd = 1.0, 0.0, 1.0 end
            D.tx = (tonumber(pp.x) or 0.0) + rx / rd * 1.6
            D.tz = (tonumber(pp.z) or 0.0) + rz / rd * 1.6
        end
    end)
    local dx = D.tx - (tonumber(gp.x) or 0.0)
    local dz = D.tz - (tonumber(gp.z) or 0.0)
    local dh = math.sqrt(dx * dx + dz * dz)
    -- FLYING CORRIDOR, not A*. A downward look-ahead can miss a sheer mountain because its ray
    -- starts inside the rock. Scan the entire straight route once from safely above it, choose a
    -- cruise ceiling above the highest sampled terrain, then fly three deterministic legs:
    -- rise vertically -> cross above the terrain -> descend inside the proven final 60m envelope.
    -- Thirteen raycasts once per dispatch are vastly cheaper and more reliable than maintaining a
    -- bespoke 3D navigation graph over streamed DD2 scenery.
    if D.ferry and not D.walk and not D.rodeo and (D.ceremony or dh > 60.0) and D.corridor_scanned ~= true then
        D.corridor_scanned = true
        local gx, gy, gz = tonumber(gp.x) or 0.0, tonumber(gp.y) or 0.0, tonumber(gp.z) or 0.0
        local max_floor = tonumber(D.ty) or gy
        local probe_top = math.max(gy, tonumber(D.ty) or gy) + 500.0
        local hits = 0
        for i = 0, 12 do
            local f = i / 12.0
            local sx = gx + (D.tx - gx) * f
            local sz = gz + (D.tz - gz) * f
            pcall(function()
                local gb = route3_ground_below_uni(sx, probe_top, sz, 10.0, 1000.0)
                if gb and tonumber(gb.y) then
                    max_floor = math.max(max_floor, tonumber(gb.y))
                    hits = hits + 1
                end
            end)
        end
        local clear = math.max(25.0, tonumber(D.ferry_clear) or 55.0)
        D.corridor_y = math.max(gy + 20.0, max_floor + clear)
        -- The offering ceremony is a fully authored flight. Establish a genuinely high staging
        -- lane above both the ox and every sampled obstruction, then keep that height until the
        -- final dive. This replaces the native PreSwoop relay which repeatedly wandered, hovered,
        -- or re-climbed after reaching the player.
        if D.ceremony then
            -- Fixed world staging height, not "current + 20". On a retry the griffin may already be
            -- 200m above the ox; demanding another relative climb created an unreachable latch.
            D.corridor_y = math.max(max_floor + clear,
                (tonumber(D.ty) or gy) + (tonumber(D.stage_height) or 200.0))
        end
        if hits < 3 then
            -- Streaming can make distant terrain unreadable. Do not interpret missing rays as flat
            -- country: take a conservative high corridor rather than flying blind through a ridge.
            D.corridor_y = math.max(D.corridor_y, gy + 120.0, (tonumber(D.ty) or gy) + 120.0)
        end
        D.corridor_phase = gy < D.corridor_y - 3.0 and "rise" or "cross"
        D.corridor_reached = D.corridor_phase == "cross"
        D.prog = { t = now, dh = dh }
        pcall(function() log.info(string.format(
            "[OxTame] flight corridor scanned: %d/13 terrain hits, ceiling %.0f (current %.0f, target %.0f) -> %s",
            hits, D.corridor_y, gy, tonumber(D.ty) or -1.0, D.corridor_phase)) end)
    end
    -- ⛔ RUNAWAY GUARD (07-20, img162 "spazzing on her side 1km away"): a dive running from beyond
    -- the proven envelope = the >400m fall-spam storm, and the 90s ceiling let it rage for a
    -- minute+. Two leashes: the flat 450m for normal short dives, and for the FC-OFF FERRY (which
    -- legitimately starts far out) a distance-LOSS leash -- abort only if she's genuinely pulling
    -- AWAY (150m past her closest approach = the drive is losing the tug-of-war, FC-off or not).
    local runaway = false
    if not D.walk and not D.rodeo and D.corridor_phase ~= "rise" then
        if D.fc_off then   -- the FC-off ferry starts far out: leash on distance-LOSS only
            D.min_dh = math.min(tonumber(D.min_dh) or dh, dh)
            runaway = dh > (tonumber(D.min_dh) or dh) + 150.0
        elseif not D.ferry then
            runaway = dh > 450.0
        end
        runaway = runaway or D.stall_dead == true   -- wedged past the climb cap = the drive is dead
    end
    if runaway then
        -- A wild Griffin can briefly publish its cached route position while the controller cut is
        -- settling. The old one-frame guard saw 310m -> 718m and immediately restored wild control,
        -- guaranteeing the loss. Keep owning/writing for a bounded recovery window; clear the timer
        -- as soon as the body returns inside the loss leash. The 90s drive watchdog remains absolute.
        if D.ceremony then
            D.runaway_t0 = D.runaway_t0 or now
            if now - D.runaway_t0 < 8.0 then runaway = false end
        end
    elseif D.ceremony then
        D.runaway_t0 = nil
    end
    if runaway then
        pcall(function() set_motion_fsm_puppet(go, false) end)
        pcall(function() iris_oxtame_ceremony_restore_native(D) end)
        pcall(function() set_think_stop(ch, false) end)
        pcall(function() ch:call("resetActionAndAI") end)
        pcall(function()
            local dm = go:call("getComponent(System.Type)", sdk.typeof("app.AIDecisionMaker"))
            if dm then dm:call("set_Enabled", true) end
        end)
        pcall(function()   -- never leave a wild body flightless
            local fc = get_component(go, "app.FlightControl")
            if fc then fc:call("set_Enabled", true) end
        end)
        pcall(function() log.info(string.format("[OxTame] descent drive ABORT: dh=%.0fm fc_off=%s (losing the body)", dh, tostring(D.fc_off == true))) end)
        S.oxtame_fly = nil
        return
    end
    -- ⭐ SEND-OFF ARRIVAL (07-21): far enough out -- hand her back to the wild HERE, well before
    -- the precision-landing arrival below could ever fire. Release order follows the field-tested
    -- flee recipe (un-puppet FIRST, then the travelling soar node -- forcing a node on a puppeted
    -- body is the T-pose root, oxtame_release_wild's lesson).
    if D.sendoff and dh < 40.0 then
        pcall(function() set_motion_fsm_puppet(go, false) end)
        pcall(function() set_think_stop(ch, false) end)
        pcall(function() ch:call("resetActionAndAI") end)
        pcall(function()
            local dm = go:call("getComponent(System.Type)", sdk.typeof("app.AIDecisionMaker"))
            if dm then dm:call("set_Enabled", true) end
        end)
        pcall(function()   -- never leave a wild body flightless
            local fc = get_component(go, "app.FlightControl")
            if fc then fc:call("set_Enabled", true) end
        end)
        pcall(function()   -- wing away, don't hover: the fail path's proven travelling node
            local b0 = _G.IrisGriffinBridge
            if b0 and b0.oxtame_buck then b0.oxtame_buck(ch, "Fly.Flight.Ch253SoaringFlight", true) end
        end)
        pcall(function() log.info(string.format("[OxTame] SEND-OFF complete at dh=%.0fm -- released to native flight", dh)) end)
        S.oxtame_fly = nil
        return
    end
    -- hold the safe combo every tick
    pcall(function() set_think_stop(ch, false) end)
    pcall(function() set_motion_fsm_puppet(go, true) end)
    -- KEEP NATIVE AI SUPPRESSED the whole flight (07-18, image 148: on a LONG escalated dive her
    -- native flight RE-ESTABLISHES and out-flies the transform pin -- she circled at 431m playing
    -- 5101, "it answers your gift" stuck true, never coming). One resetActionAndAI at dispatch wears
    -- off over ~20s; hold the decision-maker OFF every tick so the drive keeps ownership.
    if not D.walk and not D.rodeo then
        pcall(function()
            local dm = go:call("getComponent(System.Type)", sdk.typeof("app.AIDecisionMaker"))
            if dm then dm:call("set_Enabled", false) end
        end)
    end
    -- ⛔ THE 6s PROGRESS WATCHDOG WAS REMOVED (Fable review 07-19): it aborted any dive that didn't
    -- gain 1.5m in 6s -- but the relative drive is a TUG-OF-WAR that stalls momentarily on EVERY
    -- contested dive, so the watchdog killed the very dives it should protect (abort -> re-arm ->
    -- re-seize -> "THE ANSWER" again = the endless circle Aurora saw). The 90s ceiling already bounds
    -- a genuine runaway. Just log distance every ~2s.
    if not D.rodeo and now - (tonumber(D.log_at) or 0.0) > 2.0 then
        D.log_at = now
        pcall(function() log.info(string.format("[OxTame] descent drive: dh=%.0fm walk=%s", dh, tostring(D.walk == true))) end)
    end
    pcall(function()
        local mot = ch:call("get_Motion")
        local lay = mot and mot:call("getLayer", 0)
        if not lay then return end
        local want, want_bank, wsf = nil, 0, 0.0
        if D.walk then
            want = 100   -- com_walk_loop (the cross-rig convention; a stroll to the meal)
        elseif D.rodeo then
            -- Act Two flight clips (07-18 fix): the LIFT plays the REAL takeoff clip 5210
            -- (started at frame 100 = the airborne beat, skipping the ground crouch since the
            -- drive already has her rising), then the flap loop 5101 for the circle. The old
            -- code forced 5101 EVERY FRAME, restarting it at frame 0 forever = the splayed-leg
            -- "rise" spam (image 139). Now it's LATCHED (set once per phase).
            if D.phase == "lift" then want = 5210; wsf = 100.0 else want = 5101 end
        elseif D.ceremony and D.ceremony_phase == "settle" then
            want = 5032   -- authored hover-landing end while the feet are planted
        elseif D.ceremony and D.ceremony_phase == "dive" and dh > 7.0 then
            -- ch53 high-altitude attack start/loop: a real tucked aerial descent pose, but the
            -- transform drive owns its direction and cannot miss or acquire an unintended victim.
            want_bank = 50
            want = (now - (tonumber(D.dive_t0) or now) < 0.35) and 500 or 501
        else
            want = (dh < 6.0) and 5030 or 5101   -- glide flap; landing legs on final
        end
        local cur = nil
        pcall(function() cur = lay:call("get_MotionID") end)
        -- LATCH the clip (07-18): re-issuing changeMotion every frame restarts it at frame 0 =
        -- the hover/rise anim spam. Assert only on a real want-change, or a throttled self-heal
        -- if the native FSM actually stole it back. rodeo = slow throttle (climbed-monster FSM
        -- fights harder); descent/walk = 1s throttle so a clip flip still reads promptly.
        local want_key = tostring(want_bank) .. ":" .. tostring(want)
        local doset
        if D.rodeo then
            doset = (D.rodeo_mot ~= want)
                or (cur ~= want and (now - (tonumber(D.rodeo_mot_at) or 0.0)) > 2.5)
        else
            doset = (D.desc_mot ~= want_key)
                or (cur ~= want and (now - (tonumber(D.desc_mot_at) or 0.0)) > 1.0)
        end
        if doset then
            if D.rodeo then D.rodeo_mot = want; D.rodeo_mot_at = now
            else D.desc_mot = want_key; D.desc_mot_at = now end
            pcall(function() mot:call("set_PlaySpeed", 1.0) end)
            pcall(function() mot:call("set_PlayState", 0) end)
            lay:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                want_bank, want, wsf, 12.0, 1, 1)
        end
    end)

    -- Exact planted settle. During this bounded beat there is still only one owner: FC and AI stay
    -- cut, both transforms receive the same position, and no ground hold exists yet to fight an
    -- aerial action. Only after the body has remained at the ox for the whole beat is the approach
    -- released and IrisTaming allowed to begin the feeding scene.
    if D.ceremony and D.ceremony_phase == "settle" then
        local face0 = tonumber(D.face) or 0.0
        local pos0 = make_position(D.tx, D.ty, D.tz)
        local rot0 = make_quat_yaw(face0)
        pcall(function() iris_oxtame_apply_transform(ch, go, pos0, rot0) end)
        if not D.ceremony_done
            and now - (tonumber(D.settle_t0) or now) >= (tonumber(D.settle_secs) or 0.70) then
            pcall(function() ch:call("resetActionAndAI") end)
            pcall(function() log.info("[OxTame] puppet ceremony: touchdown held and stable -> feeding may begin") end)
            -- Keep the planted owner alive until IrisTaming consumes the ready signal and calls
            -- oxtame_fly_stop. That teardown deliberately releases MotionFsm puppet immediately
            -- before the feeding clips start; clearing the table here would strand puppet mode on.
            D.ceremony_done = true
        end
        return
    end
    -- STUCK-HOVER TIMEOUT (07-18): the tight arrival window can be missed forever when the
    -- horizontal won't settle (dodge oscillation, or a target atop uneven ground). Track how
    -- long she's been within 4.5m; if it drags past 2.5s, call it arrived -- the taming side
    -- HARD-SEATS her on the corpse (a ground snap), so a near-miss becomes a clean touchdown
    -- instead of an eternal hover (images 141/142).
    -- ⚠ altitude gate (Fable 07-19): the near_t0 timeout must ALSO require she's near the ground --
    -- a griffin circling directly OVERHEAD is within 4.5m HORIZONTAL but 100m up, and without this
    -- she'd be declared "arrived" mid-air 2.5s later (false touchdown -> re-arm -> circle).
    -- ⭐⭐ VERTICAL STALL -> CUT FLIGHTCONTROL (07-24, Aurora: "stuck floating and repeating the
    -- same animation over and over"; log: dh oscillating 3-6m for 70+ seconds while she hung ~13m
    -- ABOVE the landing spot, low=false throughout). The plain short dive is the ONE drive path
    -- that never silences app.FlightControl -- the ferry, the jump pin and the stall re-seize all
    -- do. It got away with that by being BRIEF. But FC integrates its OWN altitude and writes it
    -- back every frame, so the instant a short dive is NOT brief, FC out-writes our descent: she
    -- hangs at height (horizontal still tracks, which is why dh wobbles but never closes) while
    -- the clip latch re-asserts underneath = the repeating animation. FC-off is the PROVEN cure --
    -- it is exactly what made the long ferry converge at any range -- so apply it the moment a
    -- descent stops descending, instead of reserving it for the far legs.
    -- ⭐⭐ A GROUNDED GRIFFIN CANNOT BE FLOWN -- SWITCH TO THE STROLL (07-25, log-proven). She landed
    -- 56m short of the meal and the flight drive sat at `dh=58m walk=false` FOREVER: `low=true`, so
    -- she was on the dirt while the glide tried to lift her ~29m and fly her in. Ground collision
    -- and her controller win that argument every time, so she never moved a metre. The WALK variant
    -- exists for exactly this (feet on the dirt, 1.7 m/s, ground clip) and nothing ever switched to
    -- it. Detect it honestly -- grounded, not closing -- and hand the leg over to the stroll.
    if not D.walk and not D.rodeo and dh > 5.0 then
        local ga0 = nil
        pcall(function()
            local gb0 = route3_ground_below_uni(tonumber(gp.x) or 0.0, (tonumber(gp.y) or 0.0) + 2.0, tonumber(gp.z) or 0.0, 8.0, 400.0)
            if gb0 and tonumber(gb0.y) then ga0 = (tonumber(gp.y) or 0.0) - tonumber(gb0.y) end
        end)
        if ga0 and ga0 < 3.0 and D.ferry and dh > 60.0 then
            -- ⛔ A FAR-FIELD GRIFFIN MUST NEVER BECOME A WALKER. The 09:53 trace caught the
            -- corridor body being pulled onto the ground at dh=172m; this generic recovery then
            -- switched to a 1.7m/s stroll and she died before reaching the ox. Keep the aerial
            -- contract: re-arm the rise if she never reached the ceiling, otherwise the hard
            -- crossing-floor below restores her to it on this same tick.
            D.walk_dh = nil; D.walk_t = nil
            if D.corridor_reached ~= true then D.corridor_phase = "rise" end
            if now >= (tonumber(D.far_ground_log_at) or 0.0) then
                D.far_ground_log_at = now + 2.0
                pcall(function() log.info(string.format(
                    "[OxTame] FAR ferry pulled to ground at dh=%.0fm -- refusing walk; restoring flight corridor", dh)) end)
            end
        elseif ga0 and ga0 < 3.0 then   -- final/ordinary leg only: her feet are on the ground
            if (tonumber(D.walk_dh) == nil) or dh < (tonumber(D.walk_dh) or dh) - 1.0 then
                D.walk_dh = dh; D.walk_t = now          -- still closing on foot-height: leave it be
            elseif now - (tonumber(D.walk_t) or now) > 3.0 then
                D.walk = true
                pcall(function() log.info(string.format("[OxTame] GROUNDED and not closing (dh=%.0fm, %.1fm up) -> switching the drive to the WALK", dh, ga0)) end)
            end
        else
            D.walk_dh = nil; D.walk_t = nil
        end
    end
    -- ⚠ re-arms after each intervention (07-25) rather than firing once: FlightControl is only ONE
    -- of the things that can hold her up, so if the first cure does not take we must try again.
    if not D.walk and not D.rodeo then
        local dy0 = math.abs((tonumber(gp.y) or 0.0) - D.ty)
        -- ⛔ 60m, NOT 40 (07-25): the stall-climb stands down BELOW 60m and this cure only fired
        -- BELOW 40m, so 40-60m was a DEAD BAND where nothing helped her at all. Aurora's griffin sat
        -- frozen at exactly `dh=59m` for 14+ seconds, hovering over the meal, with neither cure
        -- eligible. The two thresholds must MEET, not overlap-with-a-gap.
        if dh < 60.0 and dy0 > 4.0 then   -- near the spot (so terrain is not the obstacle) but high
            if (tonumber(D.best_dy) == nil) or dy0 < (tonumber(D.best_dy) or dy0) - 1.0 then
                D.best_dy = dy0; D.dy_t = now          -- still losing height: healthy
            elseif now - (tonumber(D.dy_t) or now) > 3.0 then
                D.fc_off = true                        -- the upkeep above silences FC every tick
                -- ⛔ A LIVE NATIVE ACTION out-writes the puppet just as happily as FC does -- a
                -- force-fired swoop drives its own movement and will hold her in the air while our
                -- drive re-asserts a landing clip underneath it (the 0:5030 spam, stuck at dh=3m
                -- with 24m of air below her, where cutting FC alone changed nothing). Drop whatever
                -- she is running so the drive owns her alone.
                pcall(function() ch:call("resetActionAndAI") end)
                D.best_dy = nil; D.dy_t = now
                -- ⛔⛔ BOUNDED (07-25). Re-arming this with no limit made it an infinite reset loop:
                -- log showed `dh=37m` frozen for 25+ seconds with "FC cut + action reset" every 3s
                -- forever. Worse than useless -- it wedges the scene (the drive stays "active", so
                -- the call-down early-returns and the player has no way to intervene) and it keeps
                -- wiping any action she might have used to free herself. If three interventions have
                -- not made her lose a single metre, the cure is not working: give the body back and
                -- let the taming side re-arm, which is the proven recovery.
                D.stall_fixes = (tonumber(D.stall_fixes) or 0) + 1
                if D.stall_fixes >= 3 then D.stall_dead = true end   -- the runaway guard does the full restore
                pcall(function() log.info(string.format("[OxTame] descent STALLED vertically (%.0fm up, dh=%.0fm) -> FC cut + action reset (try %d)%s",
                    dy0, dh, D.stall_fixes, D.stall_dead and " -- GIVING THE BODY BACK" or "")) end)
            end
        else
            D.best_dy = nil; D.dy_t = nil
        end
    end
    if not D.rodeo then
        local low_enough0 = math.abs((tonumber(gp.y) or 0.0) - D.ty) < 6.0
        if dh < 4.5 and low_enough0 then D.near_t0 = D.near_t0 or now else D.near_t0 = nil end
    end
    local arrived = (not D.rodeo) and (
        (dh < (D.walk and 1.4 or 2.2) and math.abs((tonumber(gp.y) or 0.0) - D.ty) < 3.0)
        or (D.near_t0 and (now - D.near_t0) > 2.5))
    if D.ceremony then
        -- No "near enough" timeout for the ox dive. That shortcut is what handed a hovering body
        -- to the ground pin. Require the root to be truly at the landing point.
        arrived = dh < 0.75 and math.abs((tonumber(gp.y) or 0.0) - D.ty) < 0.75
    end
    if arrived then
        -- ARRIVED at the offering. The action state is RESET (a stale wild attack latched in
        -- the FSM played as "she fights me" at the landing -- Aurora) and the motion puppet
        -- STAYS HELD: the taming scene paints the eat within a tick; a live FSM in the gap
        -- replays old aggression.
        if D.ceremony then
            D.ceremony_phase = "settle"
            D.settle_t0 = now
            D.desc_mot = nil
            pcall(function() log.info("[OxTame] puppet ceremony: exact touchdown -> planted settle") end)
            return
        end
        pcall(function() ch:call("resetActionAndAI") end)
        pcall(function() log.info("[OxTame] descent complete: the griffin alights at the offering") end)
        S.oxtame_fly = nil
        return
    end
    -- the glide (07-18: 32 m/s flew her straight THROUGH the mountains and culled her -- "she just
    -- disappears", Aurora. Backed to a moderate 20 m/s -- still out-paces her native cruise drift so
    -- she converges rather than sailing to 431m, but not a violent stoop; tapers on final). She also
    -- flies HIGHER on the way in (40m clearance vs 22m) so she clears hills instead of clipping into
    -- them. No teleport, no controller-kill (that crashed) -- just a faster, higher puppet.
    -- ⭐ FERRY (07-19, the off-camera RELOCATE's long visible fly-in): dropped ~400m out, the moderate
    -- 20 m/s LOSES the drift race to native cruise -- so the far ferry leg flies FASTER (out-paces
    -- native and converges; the old 32 m/s test proved SPEED wins the race, it only culled on terrain)
    -- and TERRAIN-FOLLOWING (clearance above the ground AHEAD of her so she arcs OVER hills instead of
    -- through them -- the exact thing that culled 32 m/s). Tapers into the normal stoop inside 60m.
    -- ⭐ STALL-CLIMB (07-20, img165: wedged flapping against a cliff at dh=192 forever): a sheer
    -- face defeats even the ahead-probe (a downward cast from her altitude at the look-ahead point
    -- starts INSIDE the rock and reads nothing). The honest signal is PROGRESS: if dh stops
    -- improving, climb in +30m steps until it moves again; ease back down once she's making way.
    if not D.walk and not D.rodeo and not D.ceremony and D.corridor_phase ~= "rise" then
        local P = D.prog
        if not P then
            D.prog = { t = now, dh = dh }
        elseif now - (tonumber(P.t) or now) > 2.5 then
            -- ⛔⛔ FAR-FIELD ONLY (07-25). This climb exists to pop her over a CLIFF between her and
            -- the meal, so it must never run on final approach -- at close range there is nothing to
            -- clear, and it forms a FEEDBACK LOOP that eats the dive: the climb spends her motion
            -- budget on altitude, so she closes slower, so the 3m-per-2.5s progress test fails again,
            -- so it climbs again. Aurora's log, closing perfectly the whole way:
            --   dh=22 -> +80m | dh=19 -> +110m | dh=17 -> +140m | dh=15 -> +160m (DEAD -> bail)
            -- She was gaining ground every single window and it still stacked 160m onto her target
            -- and then abandoned the dive. The old 12m guard was far too tight; 60m matches the
            -- auto-ferry threshold, i.e. the range where real terrain obstacles actually live.
            -- ⛔⛔ RECEDING IS NOT STALLING (07-25, the water incident). This test fires on "she has
            -- not closed 3m", which is true both when she is WEDGED (the cliff this was written for)
            -- and when she is flying AWAY -- and those want opposite treatments. Her log read
            -- 68 -> 86 -> 107 -> 133 -> 157 -> 174m: she was receding at ~11 m/s, i.e. the pin had no
            -- ownership at all (`fc_off=false`) and her own AI was flying her. Climbing a body we do
            -- not own achieves nothing; it just logged "+160m" at a puppet that was moving nobody
            -- while she flew into the sea, and cost 15 seconds before the bail.
            -- ⇒ if she is GAINING ground on us, stop pretending it is terrain and give her back.
            if ((tonumber(P.dh) or dh) - dh) < -10.0 then
                D.stall_dead = true
                pcall(function() log.info(string.format(
                    "[OxTame] descent RECEDING (%.0fm -> %.0fm in %.1fs) -- we do not own this body, bailing",
                    tonumber(P.dh) or dh, dh, now - (tonumber(P.t) or now))) end)
            elseif ((tonumber(P.dh) or dh) - dh) < 3.0 and dh > 60.0 then
                -- ⭐ RE-SEIZE ON STALL (07-20 23:46 log: an OPEN-SKY ferry froze at dh=204 from tick
                -- one -- not geometry; the writes weren't taking on that body, same signature as a
                -- failed jump pin. The one body that DID obey had been through a prior drive cycle =
                -- ownership ACCUMULATES). Every stalled window, re-run the ownership bundle: drop her
                -- live action (the Hover*HomingHeight nodes actively re-position her every frame),
                -- re-cycle the motion puppet, re-cut FlightControl -- then climb.
                pcall(function() ch:call("resetActionAndAI") end)
                -- ⭐ KILL THE HOMING NODE (07-21 log: Fly.Hovering.Ch253HoverWaitHoHomingHeight stays
                -- ACTIVE through the whole drive -- resetActionAndAI does NOT exit it, and it re-computes
                -- her authoritative position every frame; on release she SNAPPED 300m to where it thought
                -- she was). Force the in-place non-homing ThreatAir (proven force-fire, every rodeo tell)
                -- to EXIT the homing action, then re-own the motion.
                -- ⛔ ThreatAir OFF here too (07-25). This was the OTHER firing site -- the stall
                -- re-seize hits it every stalled window, so a griffin who arrives overhead and stalls
                -- gets threat-postured on repeat and never stoops (Aurora: "still stuck at hovering
                -- ThreatAir for a while before the dive", after the descend-side one was disabled).
                -- It was only ever a lever to break the HOMING hover; resetActionAndAI + the FC cut
                -- below do that job without parking her in a display animation.
                if C.oxtame_exit_node == true then
                    pcall(function()
                        local b0 = _G.IrisGriffinBridge
                        if b0 and b0.oxtame_buck then b0.oxtame_buck(ch, "Fly.Hovering.Ch253ThreatAir") end
                    end)
                end
                pcall(function() set_motion_fsm_puppet(go, false) end)
                pcall(function() set_motion_fsm_puppet(go, true) end)
                pcall(function()
                    local fc = get_component(go, "app.FlightControl")
                    if fc then fc:call("set_Enabled", false) end
                end)
                -- climbed the whole cap and STILL pinned (07-20 log: +160 for 20s, dh frozen --
                -- embedded in geometry OR an unowned body): bail NOW; the taming re-arm + relocate
                -- retry is the proven recovery (it cracked that exact run).
                if (tonumber(D.stall_climb) or 0.0) >= 160.0 then D.stall_dead = true end
                D.stall_climb = math.min(160.0, (tonumber(D.stall_climb) or 0.0) + 30.0)
                pcall(function() log.info(string.format("[OxTame] glide STALL at dh=%.0fm -> climb +%.0fm%s", dh, D.stall_climb, D.stall_dead and " (DEAD -> bail)" or "")) end)
            else
                D.stall_climb = math.max(0.0, (tonumber(D.stall_climb) or 0.0) - 10.0)
            end
            D.prog = { t = now, dh = dh }
        end
    end
    local current_y = tonumber(gp.y) or 0.0
    if D.corridor_phase == "rise" and current_y >= (tonumber(D.corridor_y) or current_y) - 3.0 then
        D.corridor_phase = "cross"
        D.corridor_reached = true
        D.prog = { t = now, dh = dh }
        pcall(function() log.info("[OxTame] flight corridor: rise complete -> high crossing") end)
    end
    if D.ceremony and D.corridor_reached == true and D.ceremony_phase ~= "dive"
        and dh <= (tonumber(D.stage_radius) or 250.0) then
        D.corridor_phase = "dive"
        D.ceremony_phase = "dive"
        D.dive_t0 = now
        D.desc_mot = nil
        pcall(function() log.info(string.format(
            "[OxTame] puppet ceremony: high stage reached at %.0fm -> authored dive to the ox", dh)) end)
    elseif not D.ceremony and dh <= 60.0 and D.corridor_phase and D.corridor_phase ~= "descend" then
        D.corridor_phase = "descend"
        pcall(function() log.info("[OxTame] flight corridor: crossing complete -> precision descent") end)
    end
    local ceremony_cruise = D.ceremony and D.ceremony_phase ~= "dive"
    local ceremony_dive = D.ceremony and D.ceremony_phase == "dive"
    local ferry_far = D.ferry and not D.walk and not D.rodeo
        and ((not D.ceremony and dh > 60.0) or ceremony_cruise)
    local corridor_rising = ferry_far and D.corridor_phase == "rise"
    local spd = D.walk and 1.7
        or (ceremony_dive and (tonumber(D.dive_spd) or 36.0))
        or (ferry_far and (tonumber(D.ferry_spd) or 45.0))
        or ((dh > 10.0) and 20.0 or math.max(3.5, dh * 1.2))
    local step = corridor_rising and 0.0 or math.min(dh, spd * dt)
    local want_y
    if D.walk or D.rodeo then
        -- EXACT target height (07-18): the stroll keeps feet on the dirt; the RODEO circles at a
        -- FIXED altitude. The descent ARC below (extra height by distance) was bobbing the rodeo's
        -- target every circle-step, and the raised vcap turned that bob into a SLAM DOWN that threw
        -- the rider (Aurora: "went up and slammed down, knocked me off, repeats"). No arc here.
        want_y = D.ty
    elseif ceremony_dive then
        -- Straight controlled stoop from the 200m staging lane. Horizontal and vertical rates are
        -- matched so it cannot level out early, orbit the corpse, or drop elsewhere before returning.
        local sr0 = math.max(20.0, tonumber(D.stage_radius) or 180.0)
        local sh0 = math.max(40.0, tonumber(D.stage_height) or 200.0)
        want_y = D.ty + sh0 * math.min(1.0, math.max(0.0, dh / sr0))
    elseif ferry_far and D.corridor_y and (D.corridor_phase == "rise" or D.corridor_phase == "cross") then
        want_y = tonumber(D.corridor_y)
    elseif ferry_far then
        -- terrain-follow: probe the ground ~1.5s AHEAD so she starts climbing BEFORE the hill; hold
        -- ferry_clear above it, but never below the meal's own glide slope (already descending as she
        -- nears). The raised vcap below lets her actually crest a ridge in time.
        local look = math.min(dh, spd * 1.5)
        local px = (tonumber(gp.x) or 0.0) + (dh > 0.05 and dx / dh * look or 0.0)
        local pz = (tonumber(gp.z) or 0.0) + (dh > 0.05 and dz / dh * look or 0.0)
        local floor_y = D.ty
        pcall(function()
            -- ⛔ UNIVERSAL cast: px/pz derive from gp (get_UniversalPosition). Feeding those to the
            -- render-space ray read a "floor" off unrelated terrain and this branch then chased
            -- floor_y + clearance upward forever = the roar-and-climb-until-gone (07-25).
            local gb = route3_ground_below_uni(px, (tonumber(gp.y) or 0.0) + 5.0, pz, 8.0, 400.0)
            if gb and tonumber(gb.y) then floor_y = tonumber(gb.y) end
        end)
        want_y = math.max(floor_y + (tonumber(D.ferry_clear) or 55.0), D.ty + math.min(dh * 0.5, 70.0))
    elseif dh > 8.0 then
        want_y = D.ty + math.max(5.0, math.min(40.0, dh * 0.5))
        -- ⭐ TERRAIN-FOLLOW ON THE SHORT DIVE TOO (07-23, Aurora: ox killed by the aqueduct, not
        -- the open fields -- the straight-line arc descended INTO the wall between her and the
        -- meal until the drive gave up). Same ahead-probe as the ferry leg, smaller clearance,
        -- tapering on final so the stoop still lands at the corpse.
        pcall(function()
            local look9 = math.min(dh, spd * 1.5)
            local px9 = (tonumber(gp.x) or 0.0) + (dh > 0.05 and dx / dh * look9 or 0.0)
            local pz9 = (tonumber(gp.z) or 0.0) + (dh > 0.05 and dz / dh * look9 or 0.0)
            -- ⛔⛔ FAR APPROACH ONLY (07-25 REVERT). Aurora: "she would fly and land perfectly on the
            -- ox, why is that not happening anymore?" -- because of ME. This terrain-follow had
            -- NEVER ONCE EXECUTED: it called the ray with UNIVERSAL coords, which always returned
            -- nil, so the dive descended on its simple arc and landed on the meal. Fixing the
            -- coordinate space brought it to life, and at dh=58 it computes dh*0.4 = 23m of
            -- clearance -- holding her 23 METRES UP on final approach, so she can never settle onto
            -- the ox and ends up grounded short. It exists to stop her flying INTO a hill on the way
            -- in, which is a FAR-range concern; on final there is nothing to clear.
            local gb9 = (dh > 60.0) and route3_ground_below_uni(px9, (tonumber(gp.y) or 0.0) + 5.0, pz9, 8.0, 400.0) or nil
            if gb9 and tonumber(gb9.y) then
                want_y = math.max(want_y, tonumber(gb9.y) + math.min(30.0, math.max(6.0, dh * 0.4)))
            end
        end)
    else
        want_y = D.ty + math.max(0.0, dh * 0.35)
    end
    -- pop over the obstacle -- but SHED any accumulated climb once she is on final: a height gained
    -- to clear a ridge 200m out must not still be holding her up over the meal (07-25)
    if dh <= 60.0 then D.stall_climb = nil end
    if not D.walk and not D.rodeo then want_y = want_y + (tonumber(D.stall_climb) or 0.0) end
    local gy = tonumber(gp.y) or 0.0
    local vy = want_y - gy
    -- rodeo climbs/holds GENTLY (7 m/s) so the rise is smooth and the cling survives; the free
    -- descent can move faster (14).
    local vcap = (D.walk and 2.0 or (D.rodeo and 7.0
        or (ceremony_dive and 48.0 or (ferry_far and 22.0 or 14.0)))) * dt
    if vy > vcap then vy = vcap elseif vy < -vcap then vy = -vcap end
    local nx = (tonumber(gp.x) or 0.0) + (dh > 0.05 and dx / dh * step or 0.0)
    local nz = (tonumber(gp.z) or 0.0) + (dh > 0.05 and dz / dh * step or 0.0)
    local next_y = gy + vy
    if ferry_far and D.corridor_reached == true and tonumber(D.corridor_y) then
        -- Once the climb genuinely reached its surveyed ceiling, never let native flight/fall
        -- integration drag the direct-drive body back into terrain between ticks. This is a
        -- positional floor only during the high crossing; it is released at dh<=60 for the dive.
        next_y = math.max(next_y, tonumber(D.corridor_y) - 3.0)
    end
    local pos = make_position(nx, next_y, nz)
    -- ⭐ HEADING STABILITY (07-24, Aurora: on the yield descent "she oscillates and spins very
    -- quickly, it's not smooth"). Facing is derived from the horizontal delta -- but a ridden
    -- landing is a near-VERTICAL descent, so dx/dz collapse to numerical noise and atan2 of noise
    -- spins her on the spot. Under ~1.5m of horizontal offset the heading carries no real
    -- information: hold the last one that did.
    if dh > 1.5 then D.face = wrap_angle(math.atan(dx, dz)) end
    local face1 = tonumber(D.face) or wrap_angle(math.atan(dx, dz))
    local rot = make_quat_yaw(face1)
    if ceremony_dive and dh > 7.0 then
        -- Pitch follows the actual line to the ox (positive X pitch noses local +Z downward).
        local drop1 = math.max(0.0, gy - D.ty)
        local pitch1 = math.min(math.rad(58.0), math.atan(drop1, math.max(1.0, dh)))
        rot = make_quat_yaw_pitch_roll(face1, pitch1, 0.0)
    end
    if D.ceremony then
        pcall(function() iris_oxtame_apply_transform(ch, go, pos, rot) end)
    else
        pcall(function() set_transform(go, pos, rot) end)
        pcall(function() set_character_transform(ch, pos, rot) end)
    end
end

-- per-species TRUE SIZE for tames (Aurora's executive decisions live here): most species keep
-- their natural 1.0; the rat "is sooo big it can be kinda creepy" -- tamed rats run at 0.75
function iris_species_base_scale(nm0)
    nm0 = tostring(nm0 or "")
    if nm0:find("ch299210", 1, true) then return 0.75 end
    return 1.0
end

-- transient = this size belongs to ONE companion's growth clock (a hatchling easing toward full
-- size, or a wyrmfed swell), not to the species. Such a scale must NEVER reach C.spawn_scale.
--
-- ⛔ THIRD RECURRENCE, 2026-07-24 (Aurora: "my griffin is a baby"). C.spawn_scale is the size
-- EVERY companion is summoned at. An egg hatched in the stable, hatch() applied its 0.12 birth
-- scale, that write landed in the global, save_config() put it on disk -- and from then on every
-- griffin in the roster was born a hatchling, surviving script resets because the damage was
-- persisted. The two earlier fixes ("the 0.55 stable rabbit") both guarded by SPECIES, which
-- cannot help when the hatchling and the victim are the same species.
function griffin_apply_body_scale(scale, transient)
    -- sets the TARGET: the actual shrink eases over a few seconds in
    -- griffin_tamed_tick — taming magic, not a glitchy instant resize
    scale = tonumber(scale)
    if not scale or scale <= 0.05 or scale > 3.0 then return false end
    -- ⛔ CHOKE-POINT RULE (the 0.55 stable rabbit -- Aurora): the tame-shrink exists to fit
    -- the GIANT rideables (griffin/drake/chimera/wyvern). A small species NEVER shrinks, no
    -- matter which adopt/restore/spawn path asked -- every caller funnels through here.
    -- Judged by the LIVE BODY being scaled: the state fields (route3_tamed_species/spawn_code)
    -- go STALE across companion swaps -- a prior griffin left them saying ch253 while the
    -- stable summoned a rabbit, and 0.55 slipped through (Aurora, 07-15 second recurrence).
    pcall(function()
        local sp0 = nil
        pcall(function()
            local _, go0 = reacquire_griffin()
            if go0 then sp0 = tostring(go_name(go0) or "") end
        end)
        if not sp0 or sp0 == "" then sp0 = tostring(S.route3_tamed_species or C.spawn_code or "") end
        local big0 = sp0:find("ch253", 1, true) == 1 or sp0:find("ch257", 1, true) == 1
            or sp0:find("ch254", 1, true) == 1 or sp0:find("ch258", 1, true) == 1
        if not big0 and scale <= 1.0 then
            -- at-or-below true size normalizes to the SPECIES base (rat = 0.75); wyrm
            -- growth above 1.0 passes untouched
            scale = iris_species_base_scale(sp0)
        end
    end)
    S.route3_scale_target = scale
    S.route3_scale_snap_at = 0.0 -- fresh tame keeps the intentional eased shrink
    if not transient then C.spawn_scale = scale end
    return true
end



local function get_player_input()
    local input = nil
    pcall(function() input = get_player():call("get_Input") end)
    if not input then pcall(function() input = get_player():get_Input() end) end
    return input
end

local function get_player_input_processor()
    local player = get_player()
    local input_processor = nil
    pcall(function() input_processor = player and player:get_field("InputProcessor") end)
    if not input_processor then pcall(function() input_processor = player and player:get_field("<InputProcessor>k__BackingField") end) end
    if not input_processor then pcall(function() input_processor = player and player:call("get_InputProcessor") end) end
    if not input_processor then
        local input = get_player_input()
        pcall(function() input_processor = input and input:get_field("InputProcessor") end)
        if not input_processor then pcall(function() input_processor = input and input:get_field("<InputProcessor>k__BackingField") end) end
    end
    return input_processor
end

local function axis_magnitude(x, z)
    return math.abs(tonumber(x) or 0.0) + math.abs(tonumber(z) or 0.0)
end

local function read_keyboard_axis()
    local x, z = 0.0, 0.0
    pcall(function()
        if iris_kb(0x41) then x = x - 1.0 end -- A
        if iris_kb(0x44) then x = x + 1.0 end -- D
        if iris_kb(0x57) then z = z + 1.0 end -- W
        if iris_kb(0x53) then z = z - 1.0 end -- S
    end)
    if x ~= 0.0 and z ~= 0.0 then
        -- normalise diagonals so W+A is not ~41% faster than W
        x, z = x * 0.70710678, z * 0.70710678
    end
    return x, z
end

function griffin_apply_axis_deadzone(x, z, dz)
    x, z = tonumber(x) or 0.0, tonumber(z) or 0.0
    dz = math.min(0.9, math.max(0.0, tonumber(dz) or 0.15))
    if dz <= 0.0 then return x, z end
    local mag = math.sqrt(x * x + z * z)
    if mag <= dz then return 0.0, 0.0 end
    -- rescale so output still spans 0..1 smoothly above the deadzone
    local scale = math.min(1.0, (mag - dz) / math.max(0.0001, 1.0 - dz)) / mag
    return x * scale, z * scale
end

local function raw_gamepad_device()
    local dev = nil
    S.last_raw_device = "(none)"
    pcall(function()
        local gp = sdk.get_native_singleton("via.hid.GamePad")
        local td = sdk.find_type_definition("via.hid.GamePad")
        if gp and td then
            pcall(function() dev = sdk.call_native_func(gp, td, "get_MergedDevice"); if dev then S.last_raw_device = "get_MergedDevice" end end)
            if not dev then pcall(function() dev = sdk.call_native_func(gp, td, "getMergedDevice(System.UInt32)", 0); if dev then S.last_raw_device = "getMergedDevice(0)" end end) end
            if not dev then pcall(function() dev = sdk.call_native_func(gp, td, "get_Device"); if dev then S.last_raw_device = "get_Device" end end) end
        end
    end)
    return dev
end

local gamepad_button_cache = nil
local function gamepad_button_value(name)
    local text = tostring(name or "")
    local direct = tonumber(text)
    if direct then return direct end
    local hex = text:match("^0[xX]([0-9a-fA-F]+)$")
    if hex then return tonumber(hex, 16) or 0 end
    local alias = {
        l3 = 0x1000, leftstick = 0x1000, lstick = 0x1000, ls = 0x1000,
        r3 = 0x2000, rightstick = 0x2000, rstick = 0x2000, rs = 0x2000,
        dup = 0x1, dpadup = 0x1, up = 0x1,
        ddown = 0x2, dpaddown = 0x2, down = 0x2,
        dleft = 0x4, dpadleft = 0x4, left = 0x4,
        dright = 0x8, dpadright = 0x8, right = 0x8,
        l1 = 0x100, lb = 0x100, leftbumper = 0x100,
        l2 = 0x200, lt = 0x200, lefttrigger = 0x200,
        r1 = 0x400, rb = 0x400, rightbumper = 0x400,
        r2 = 0x800, rt = 0x800, righttrigger = 0x800,
        triangle = 0x10, y = 0x10, north = 0x10,
        circle = 0x40080, b = 0x40080, east = 0x40080,
        x = 0x20020, cross = 0x20020, south = 0x20020,
        square = 0x40, west = 0x40,
    }
    local aliased = alias[text:lower()]
    if aliased then return aliased end

    if not gamepad_button_cache then
        gamepad_button_cache = {}
        pcall(function()
            local td = sdk.find_type_definition("via.hid.GamePadButton")
            if td then
                for _, field in ipairs(td:get_fields()) do
                    local n = field:get_name()
                    local v = tonumber(field:get_data(nil)) or 0
                    gamepad_button_cache[n:lower()] = v
                end
            end
        end)
    end
    return gamepad_button_cache[text:lower()] or 0
end

local function raw_gamepad_button_down(names)
    local dev = raw_gamepad_device()
    S.last_raw_button_mask = 0
    if not dev then return false end
    local mask = 0
    pcall(function() mask = tonumber(dev:call("get_Button")) or 0 end)
    mask = math.floor(tonumber(mask) or 0)
    S.last_raw_button_mask = mask
    if mask == 0 then return false end
    for raw in tostring(names or ""):gmatch("[^,%s]+") do
        local bit = math.floor(tonumber(gamepad_button_value(raw)) or 0)
        if bit ~= 0 then
            local hit = false
            pcall(function() hit = (mask & bit) ~= 0 end)
            if hit then return true end
        end
    end
    return false
end

function raw_gamepad_mask_down(bind_mask)
    local mask = math.floor(tonumber(S.last_raw_button_mask) or 0)
    local bind = math.floor(tonumber(bind_mask) or 0)
    if bind <= 0 or mask <= 0 then return false end
    local hit = false
    pcall(function() hit = (mask & bind) ~= 0 end)
    return hit == true
end

local function keyboard_shift_down()
    local down = false
    pcall(function()
        down = iris_kb(0x10) or iris_kb(0xA0) or iris_kb(0xA1)
    end)
    return down == true
end

local function vec_axis(v)
    if not v then return nil, nil end
    local x, y, z = nil, nil, nil
    pcall(function() x = tonumber(v.x) end)
    pcall(function() y = tonumber(v.y) end)
    pcall(function() z = tonumber(v.z) end)
    if x ~= nil and z ~= nil then return x, z end
    if x ~= nil and y ~= nil then return x, -y end
    return nil, nil
end

local function read_raw_gamepad_axis()
    local dev = raw_gamepad_device()
    S.last_raw_axis_method = "(none)"
    local methods = {
        "get_AxisL", "get_DirectionL", "get_AxisLeft", "get_LStick", "get_LeftStick",
        "get_LStickAxis", "get_LeftStickAxis", "get_AnalogL", "get_LeftAnalog",
        "get_AnalogStickL", "get_LeftAnalogStick", "get_StickL",
    }
    if dev then
        for _, method in ipairs(methods) do
            local v = nil
            pcall(function() v = dev:call(method) end)
            if not v then pcall(function() v = dev[method] and dev[method](dev) end) end
            local x, z = vec_axis(v)
            if x ~= nil and z ~= nil and axis_magnitude(x, z) > 0.01 then
                S.last_raw_axis_method = method
                return x, z
            end
        end
    end

    local gp_axis_x, gp_axis_z, gp_method = nil, nil, nil
    pcall(function()
        local gp = sdk.get_native_singleton("via.hid.GamePad")
        local td = sdk.find_type_definition("via.hid.GamePad")
        if not (gp and td) then return end
        for _, method in ipairs(methods) do
            if gp_axis_x ~= nil then break end
            local v = nil
            pcall(function() v = sdk.call_native_func(gp, td, method) end)
            local x, z = vec_axis(v)
            if x ~= nil and z ~= nil and axis_magnitude(x, z) > 0.01 then
                gp_axis_x, gp_axis_z, gp_method = x, z, "GamePad." .. method
            end
        end
    end)
    if gp_axis_x ~= nil then
        S.last_raw_axis_method = gp_method or "GamePad"
        return gp_axis_x, gp_axis_z
    end

    if not dev then
        S.last_raw_axis_method = "(no device)"
    end
    return 0.0, 0.0
end

local function read_axis()
    local input = get_player_input()
    local dir = nil
    if input then
        pcall(function() dir = input:call("get_DirectionL") end)
        if not dir then pcall(function() dir = input:get_DirectionL() end) end
    end
    local char_x = dir and tonumber(dir.x) or 0.0
    local char_z = dir and tonumber(dir.z) or 0.0
    local key_x, key_z = read_keyboard_axis()
    local raw_x, raw_z = read_raw_gamepad_axis()
    raw_x, raw_z = griffin_apply_axis_deadzone(raw_x, raw_z, C.raw_axis_deadzone)

    local x, z = char_x, char_z
    S.last_axis_source = "character"
    if tostring(C.input_axis_source or "auto") == "keyboard" then
        x, z = key_x, key_z
        S.last_axis_source = "keyboard"
    elseif tostring(C.input_axis_source or "auto") == "raw" then
        x, z = raw_x, raw_z
        S.last_axis_source = "raw"
    elseif axis_magnitude(x, z) <= 0.01 and axis_magnitude(key_x, key_z) > 0.01 then
        x, z = key_x, key_z
        S.last_axis_source = "keyboard"
    elseif axis_magnitude(x, z) <= 0.01 and axis_magnitude(raw_x, raw_z) > 0.01 then
        x, z = raw_x, raw_z
        S.last_axis_source = "raw"
    end

    S.last_char_axis_x, S.last_char_axis_z = char_x, char_z
    S.last_raw_axis_x, S.last_raw_axis_z = raw_x, raw_z
    if C.invert_forward then z = -z end
    return x, z, input
end

local function button_on(input, flag)
    if not (input and flag) then return false end
    local down = false
    pcall(function() down = input:call("isButtonOn", flag) end)
    if not down then pcall(function() down = input:isButtonOn(flag) end) end
    return down == true
end


local function adopt_native_climb_mount()
    update_player_climb_state()
    if not S.player_climb_on_character then
        status("adopt failed: player is not climbing a character")
        return false
    end
    local ch, go = reacquire_griffin()
    if not (ch and go) then status("adopt failed: need griffin"); return false end
    local gp = transform_pos(go)
    if not gp then status("adopt failed: griffin has no readable position"); return false end

    S.mounted = true
    S.native_climb_mount = true
    S.flying = true
    S.airborne = false
    S.jump_prev = false
    S.heading_yaw = yaw_from_transform(go) or 0.0
    S.ground_y = gp.y
    S.ride_origin = { x = gp.x, y = gp.y, z = gp.z }
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    S.drive_pos = nil
    S.drive_rot = nil
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    if route3_clear_landing_request then route3_clear_landing_request() end
    S.last_drive_write_clock = 0.0
    S.nav_pulse_request = false
    S.nav_pulse_until_clock = 0.0
    S.last_forced_motion = "(none)"
    S.last_forced_motion_key = "(none)"
    S.last_forced_motion_clock = 0.0
    S.last_root_motion_state = "idle"
    S.last_root_motion_key = "(none)"
    S.last_root_motion_played = false
    S.last_root_motion_stopped = false
    S.last_root_motion_error = "adopt reset"
    S.climb_stamina_hold = read_player_stamina and (read_player_stamina() or 0.0) or 0.0
    S.last_stamina = S.climb_stamina_hold
    S.stamina_hold_active = true
    S.last_stamina_write_ok = false
    S.last_clock = os.clock()
    clear_motion_queue()
    if native_climb_uses_calm_drive() or native_climb_uses_nav_drive() then
        set_griffin_native_climb_calm(ch, go)
    else
        if C.puppet_on_mount then set_griffin_puppet(true) end
        pacify_griffin(nil)
    end
    append_observe_snapshot("adopt", ch, go, gp, os.clock())
    status("adopted native climb as ride; enable flight drive when ready")
    -- Warp-to-back RETIRED 2026-07-18: forcing set_UniversalPosition every frame fights the
    -- native climb (which re-writes her position each frame) = jitter/chaos. Replaced by the
    -- SCAN golden state + lock plan (Aurora). Left inert -- the checkbox no longer arms it.
    S.route3_warp_pending = false
    S.route3_mount_warp_until = nil
    if C.route3_auto_setup_on_adopt == true and S.route3_auto_start_in_progress ~= true then
        pcall(function() route3_start_auto_ride("auto adopt") end)
    end
    -- 07-24 IRIS PUPPET SEAT: hand the rider's body to the rodeo seat
    -- (it ends the native climb itself — exactly why its pin never
    -- fights; see the warp-to-back retirement note above). Our own
    -- rider pin/pose/camera are gated off while it reports active.
    pcall(function()
        local ps = iris_puppet_seat()
        if ps and type(ps.mount) == "function" then
            -- the rescue skip-hooks (rounds 40-45) match HER instance
            -- addresses — normally cached by the legacy puppet engage,
            -- which the bridge stands down. Cache them here instead.
            pcall(function()
                local pl = get_player()
                S.route3_rb_addr = pl:get_field(
                    "PosRotContextRollbacker"):get_address()
            end)
            pcall(function()
                local pl = get_player()
                S.route3_rec_addr = pl:get_field(
                    "<PosRotRecorder>k__BackingField"):get_address()
            end)
            local ok = ps.mount(go)
            if ok then status("adopted ride; rider = IRIS puppet seat") end
        end
    end)
    return true
end

local function dismount_griffin()
    -- round 6b: disarm the onAbortClimb veto BEFORE any teardown -- rejected aborts
    -- during dismount = "she stays glued to the body" (the steady-seat lesson below).
    S.route3_abort_veto_off_until = os.clock() + 3.0
    -- v12 air seat: the teardown below owns the puppet release; just drop the seat latch
    -- so the watcher can't fight the dismount (statue law, exit 1 of 3)
    S.route3_air_seat_on = false
    S.route3_air_seat_air_since = nil
    S.route3_air_relatch_check_at = nil
    if S.route3_airseat_cam_parked == true then
        S.route3_airseat_cam_parked = nil
        pcall(function()
            griffin_loopcam_cam_switch(tonumber(S.route3_loopcam_game_ct) or 0)
            S.route3_loopcam_cam_ct = nil
        end)
    end
    -- 07-24 IRIS PUPPET SEAT: release the rodeo seat FIRST (it restores
    -- the player body/pose/camera); the rest of this teardown then finds
    -- an ordinary standing player.
    pcall(function()
        local ps = rawget(_G, "IrisPuppetSeat")
        if type(ps) == "table" and type(ps.active) == "function"
            and ps.active() == true
            and type(ps.dismount) == "function" then
            ps.dismount()
        end
    end)
    -- STEADY SEAT v2 restores: the enforcer REJECTS climb aborts, which must clear
    -- BEFORE the teardown below ends the climb or the abort is refused and she stays
    -- glued to the body. The FREEZE must clear too -- a player left with MotionFsm2
    -- disabled and PlaySpeed 0 is a statue with no way back. Unconditional + idempotent.
    pcall(function()
        local ctrl = get_climb_ctrl(get_player())
        if ctrl then ctrl:set_field("<IsRejectAbortOnDefault>k__BackingField", false) end
    end)
    pcall(function() set_think_stop(get_player(), false) end)
    pcall(function()
        griffin_set_player_fsm_enabled(true)
        griffin_set_player_motion_speed(1.0)
        S.griffin_seat_frozen = false
    end)
    -- ⭐ EPONA-TEMPLATE SEAT teardown (work-order blocker #3: nothing else releases the
    -- puppet on dismount -- only script-reset did). Release FIRST so the climb-era
    -- teardown below finds an ordinary standing player; then place her beside the body
    -- AFTER the controller is back (CC snap-back law) and hold the spot briefly.
    if S.route3_rider_puppet_on == true then
        local land = nil
        pcall(function()
            local _, ggo2 = reacquire_griffin()
            local gtf = ggo2 and transform_of(ggo2)
            local gp = gtf and gtf:call("get_UniversalPosition")
            local right = gtf and gtf:call("get_AxisX")
            local side = tonumber(C.griffin_seat_dismount_side) or 2.2
            if gp and right then
                land = { x = gp.x + right.x * side, y = gp.y + 0.15, z = gp.z + right.z * side }
            end
        end)
        pcall(route3_rider_puppet, false)
        if land then
            pcall(function()
                local pgo2 = char_go(get_player())
                transform_of(pgo2):call("set_UniversalPosition",
                    make_position(land.x, land.y, land.z))
            end)
            griffin_seat_feed_recorder(land.x, land.y, land.z, true)
            S.griffin_seat_land = { x = land.x, y = land.y, z = land.z,
                until_t = os.clock() + 1.2 }
        end
    end
    -- Discard special-flight ownership while the mount relationship is still valid. Never
    -- carry a cancelled burst or retained velocity into the player's post-dismount fall.
    if route3_quick_burst_active and route3_quick_burst_active() then
        pcall(function() route3_quick_burst_end("dismount") end)
    end
    S.route3_rise_action_down = false
    S.route3_rise_btn = false
    S.route3_rise_until = 0.0
    S.route3_simple_rise_until = 0.0
    S.route3_rise_move_at = 0.0
    S.route3_rise_hold_until = 0.0
    S.route3_flight_forward_delta = 0.0
    S.route3_flight_vertical_delta = 0.0
    S.route3_soar_speed_clock = nil
    S.route3_soar_coasting = false
    route3_wilds_rider_pose_stop("dismount")
    S.mounted = false
    S.native_climb_mount = false
    S.detached_transform_ride = false
    S.route3_proxy_ride_active = false
    S.route3_seat_parented = false
    S.flying = false
    S.airborne = false
    S.jump_prev = false
    S.heading_yaw = nil
    S.ground_y = nil
    S.ride_origin = nil
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    S.manual_forward, S.manual_back = false, false
    S.manual_left, S.manual_right = false, false
    S.manual_up, S.manual_down = false, false
    S.drive_pos = nil
    S.drive_rot = nil
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    S.last_drive_write_clock = 0.0
    S.nav_pulse_request = false
    S.nav_pulse_until_clock = 0.0
    S.stamina_hold_active = false
    S.climb_stamina_hold = 0.0
    S.last_stamina_write_ok = false
    route3_clear_landing_request()
    S.route3_flap_phase = nil
    S.route3_post_landing_recover_at = 0.0
    clear_motion_queue()
    set_native_rider_suppressed(false)
    if S.route3_rider_controller_disabled then
        set_character_controller_enabled(get_player(), true)
        S.route3_rider_controller_disabled = false
    end
    set_rider_hard_lock(false)
    if route3_flap_set_root_controllers then route3_flap_set_root_controllers(true) end
    if route3_flap_clear_overlay then route3_flap_clear_overlay() end
    if S.rider_pose_frozen == true then
        griffin_set_player_motion_speed(1.0)
        S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
    end
    if route3_recover_rider_state then route3_recover_rider_state("dismount") end
    set_griffin_puppet(true)
    -- a dismount mid-walk otherwise leaves the walk clip looping in place
    stop_griffin_animation()
    griffin_tamed_save()
    griffin_species_profile_save()
    status("dismounted")
end

local function stop_ride_only(reason)
    -- 07-24 IRIS PUPPET SEAT: safety aborts must release the seat too
    -- (raw _G on purpose — even config-off, an active seat gets freed)
    pcall(function()
        local ps = rawget(_G, "IrisPuppetSeat")
        if type(ps) == "table" and type(ps.active) == "function"
            and ps.active() == true
            and type(ps.dismount) == "function" then
            ps.dismount()
        end
    end)
    -- v12 air seat (statue law, exit 2 of 3): drop the latch; the pose_stop below runs
    -- route3_rider_puppet(false) which restores CC/FSM/think
    S.route3_air_seat_on = false
    S.route3_air_seat_air_since = nil
    S.route3_air_relatch_check_at = nil
    S.route3_abort_veto_off_until = os.clock() + 3.0
    if S.route3_airseat_cam_parked == true then
        S.route3_airseat_cam_parked = nil
        pcall(function()
            griffin_loopcam_cam_switch(tonumber(S.route3_loopcam_game_ct) or 0)
            S.route3_loopcam_cam_ct = nil
        end)
    end
    if route3_quick_burst_active and route3_quick_burst_active() then
        pcall(function() route3_quick_burst_end(tostring(reason or "ride stopped")) end)
    end
    S.route3_rise_action_down = false
    S.route3_rise_btn = false
    S.route3_rise_until = 0.0
    S.route3_simple_rise_until = 0.0
    S.route3_rise_move_at = 0.0
    S.route3_rise_hold_until = 0.0
    S.route3_flight_forward_delta = 0.0
    S.route3_flight_vertical_delta = 0.0
    S.route3_soar_speed_clock = nil
    S.route3_soar_coasting = false
    route3_wilds_rider_pose_stop(tostring(reason or "ride stopped"))
    S.mounted = false
    S.native_climb_mount = false
    S.detached_transform_ride = false
    S.route3_proxy_ride_active = false
    S.route3_seat_parented = false
    S.flying = false
    S.airborne = false
    S.jump_prev = false
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    S.drive_pos = nil
    S.drive_rot = nil
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    S.route3_landing_requested = false
    S.route3_landing_ground_y = nil
    S.route3_post_landing_recover_at = 0.0
    S.nav_pulse_request = false
    S.nav_pulse_until_clock = 0.0
    S.stamina_hold_active = false
    S.climb_stamina_hold = 0.0
    S.ride_origin = nil
    set_native_rider_suppressed(false)
    if S.route3_rider_controller_disabled then
        set_character_controller_enabled(get_player(), true)
        S.route3_rider_controller_disabled = false
    end
    set_rider_hard_lock(false)
    if route3_flap_set_root_controllers then route3_flap_set_root_controllers(true) end
    if route3_flap_clear_overlay then route3_flap_clear_overlay() end
    if S.rider_pose_frozen == true then
        griffin_set_player_motion_speed(1.0)
        S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
    end
    if route3_recover_rider_state then route3_recover_rider_state(tostring(reason or "ride stopped")) end
    -- ⭐ EPONA-TEMPLATE SEAT: safety teardown must ALWAYS free a puppeted rider (death,
    -- griffin lost, fell-below) -- a component-suppressed PlayerLoop-starved body left
    -- behind here is unrecoverable for the player. Idempotent: no-op when puppet is off.
    pcall(function()
        if S.route3_rider_puppet_on == true then
            route3_rider_puppet(false)
            local pgo2 = char_go(get_player())
            local pp = pgo2 and transform_pos(pgo2)
            if pp then griffin_seat_feed_recorder(pp.x, pp.y, pp.z, true) end
        end
    end)
    -- STEADY SEAT v2: clear abort-reject, think-stop AND the animation freeze on every
    -- safety exit (death / griffin lost / fell-below). A frozen player who survives a
    -- safety teardown can never move again.
    pcall(function()
        local ctrl = get_climb_ctrl(get_player())
        if ctrl then ctrl:set_field("<IsRejectAbortOnDefault>k__BackingField", false) end
    end)
    pcall(function() set_think_stop(get_player(), false) end)
    pcall(function()
        griffin_set_player_fsm_enabled(true)
        griffin_set_player_motion_speed(1.0)
        S.griffin_seat_frozen = false
    end)
    S.last_drive_skip = tostring(reason or "ride stopped")
    status(tostring(reason or "ride stopped"))
end

local function ride_safety_tick()
    if not (S.mounted and S.native_climb_mount) then return end
    -- rider death while mounted: unwind EVERYTHING or the respawned player
    -- stays frozen in the mount pose with input suppressed
    local player = get_player()
    if player and is_dead(player) then
        local revived = false
        -- Automatic resurrection was a mitigation for the controller-less puppet's
        -- bogus accumulated fall bill.  A native-climb rider may die legitimately;
        -- do not turn the ordinary ride into unconditional god mode.
        if S.route3_rider_puppet_on == true then
            pcall(function() revived = griffin_rider_refuse_death("mounted puppet") end)
        end
        if not revived then
            if S.rider_pose_frozen == true then
                griffin_set_player_motion_speed(1.0)
                S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
            end
            stop_ride_only("ride safety: rider died")
            return
        end
    end
    local ch, go = reacquire_griffin()
    if not (ch and go) then stop_ride_only("ride safety: griffin lost"); return end
    if is_dead(ch) then stop_ride_only("ride safety: griffin dead"); return end
    local gp = transform_pos(go)
    if not gp then stop_ride_only("ride safety: no griffin position"); return end
    if S.airborne == true then
        -- flight may legitimately descend far below the mount/takeoff altitude;
        -- the air ground-clearance tick already keeps the griffin above terrain
        return
    end
    local gy = tonumber(S.ground_y)
    if gy and gp.y < gy - 5.0 then
        stop_ride_only(string.format("ride safety: griffin fell %.1fm below mount", gy - gp.y))
        return
    end
    -- grounded: follow the terrain so walking downhill never reads as a fall
    S.ground_y = tonumber(gp.y) or S.ground_y
end

rider_world_pos = function(gpos, right, up, fwd)
    return make_position(
        gpos.x + (right and right.x or 1) * C.rider_offset_x + (up and up.x or 0) * C.rider_offset_y + (fwd and fwd.x or 0) * C.rider_offset_z,
        gpos.y + (right and right.y or 0) * C.rider_offset_x + (up and up.y or 1) * C.rider_offset_y + (fwd and fwd.y or 0) * C.rider_offset_z,
        gpos.z + (right and right.z or 0) * C.rider_offset_x + (up and up.z or 0) * C.rider_offset_y + (fwd and fwd.z or 1) * C.rider_offset_z
    )
end

local matches_any

local function method_names_matching(obj, patterns, max_count)
    local out = {}
    local td = nil
    pcall(function() td = obj and obj:get_type_definition() end)
    if not td then return out end
    pcall(function()
        for _, m in ipairs(td:get_methods()) do
            local name = tostring(m:get_name() or "")
            local lo = name:lower()
            for _, pat in ipairs(patterns) do
                if lo:find(pat, 1, true) then
                    out[#out + 1] = name
                    break
                end
            end
            if max_count and #out >= max_count then break end
        end
    end)
    table.sort(out)
    return out
end

local function method_signatures_matching(obj, patterns, max_count)
    local out = {}
    local td = nil
    pcall(function() td = obj and obj:get_type_definition() end)
    if not td then return out end
    pcall(function()
        for _, m in ipairs(td:get_methods() or {}) do
            local name = tostring(m:get_name() or "")
            if matches_any(name, patterns) then
                local item = { name = name }
                pcall(function()
                    local rt = m:get_return_type()
                    item.returns = tostring(rt and rt:get_full_name() or "")
                end)
                local params = {}
                local names = {}
                pcall(function() names = m:get_param_names() or {} end)
                pcall(function()
                    for i, pt in ipairs(m:get_param_types() or {}) do
                        params[#params + 1] = {
                            name = tostring(names[i] or ""),
                            type = tostring(pt and pt:get_full_name() or ""),
                        }
                    end
                end)
                item.params = params
                item.signature = name .. "(" .. table.concat((function()
                    local pieces = {}
                    for _, p in ipairs(params) do pieces[#pieces + 1] = tostring(p.type) end
                    return pieces
                end)(), ", ") .. ")"
                out[#out + 1] = item
            end
            if max_count and #out >= max_count then break end
        end
    end)
    table.sort(out, function(a, b) return tostring(a.signature or a.name) < tostring(b.signature or b.name) end)
    return out
end

local function type_name_of(obj)
    local name = nil
    pcall(function()
        local td = obj and obj:get_type_definition()
        name = td and td:get_full_name()
    end)
    return tostring(name or "")
end

matches_any = function(text, patterns)
    local lo = tostring(text or ""):lower()
    for _, pat in ipairs(patterns or {}) do
        if lo:find(tostring(pat):lower(), 1, true) then return true end
    end
    return false
end
_G.matches_any = matches_any

local function value_summary(v)
    if v == nil then return nil end
    local tv = type(v)
    if tv == "number" or tv == "boolean" then return v end
    if tv == "string" then
        if #v > 160 then return v:sub(1, 157) .. "..." end
        return v
    end

    local x, y, z, w = nil, nil, nil, nil
    pcall(function() x = v.x; y = v.y; z = v.z; w = v.w end)
    if type(x) == "number" and type(y) == "number" then
        local out = { x = x, y = y }
        if type(z) == "number" then out.z = z end
        if type(w) == "number" then out.w = w end
        return out
    end

    local tn = type_name_of(v)
    if tn ~= "" then return "<" .. tn .. ">" end
    return tostring(v)
end

local function field_names_matching(obj, patterns, max_count)
    local out = {}
    local td = nil
    pcall(function() td = obj and obj:get_type_definition() end)
    if not td then return out end

    local seen = {}
    while td do
        pcall(function()
            for _, f in ipairs(td:get_fields() or {}) do
                local name = tostring(f:get_name() or "")
                if not seen[name] and matches_any(name, patterns) then
                    seen[name] = true
                    local item = { name = name }
                    pcall(function()
                        local ft = f:get_type()
                        item.type = tostring(ft and ft:get_full_name() or "")
                    end)
                    local val = nil
                    local ok = false
                    ok = pcall(function() val = obj:get_field(name) end)
                    if (not ok) or val == nil then pcall(function() val = f:get_data(obj) end) end
                    local sv = value_summary(val)
                    if sv ~= nil then item.value = sv end
                    out[#out + 1] = item
                end
                if max_count and #out >= max_count then break end
            end
        end)
        if max_count and #out >= max_count then break end
        local parent = nil
        pcall(function() parent = td:get_parent_type() end)
        td = parent
    end

    table.sort(out, function(a, b) return tostring(a.name) < tostring(b.name) end)
    return out
end

local function object_probe(obj, patterns, max_methods, max_fields)
    return {
        type = type_name_of(obj),
        methods = method_names_matching(obj, patterns, max_methods or 160),
        method_signatures = method_signatures_matching(obj, patterns, max_methods or 160),
        fields = field_names_matching(obj, patterns, max_fields or 120),
    }
end
_G.object_probe = object_probe

local function managed_call(obj, name, ...)
    if not obj then return nil end
    local args = { ... }
    local value = nil
    pcall(function() value = obj:call(name, table.unpack(args)) end)
    return value
end

local function managed_field(obj, name)
    if not obj then return nil end
    local value = nil
    pcall(function() value = obj:get_field(name) end)
    return value
end
_G.managed_field = managed_field

local function joint_name(joint)
    local name = managed_call(joint, "get_Name")
    return tostring(name or "")
end

local function transform_of(go)
    return managed_call(go, "get_Transform")
end

local function set_universal_position_any(tf, pos)
    if not (tf and pos) then return false end
    local ok = false
    pcall(function() tf:call("set_UniversalPosition", pos); ok = true end)
    if not ok then pcall(function() tf:call("set_Position", pos); ok = true end) end
    return ok
end

function route3_root_space_seat_position(go, ox, oy, oz)
    local gpos = transform_pos(go)
    if not gpos then return nil end
    local yaw = yaw_from_transform(go) or S.heading_yaw or 0.0
    local fwd, right = transform_flat_axes(go, yaw)
    return make_position(
        (tonumber(gpos.x) or 0.0) + (right.x * ox) + (fwd.x * oz),
        (tonumber(gpos.y) or 0.0) + oy,
        (tonumber(gpos.z) or 0.0) + (right.z * ox) + (fwd.z * oz)
    )
end

function route3_abort_native_climb(player)
    if not player then return false end
    local ok = false
    ok = call_noarg_methods(player, {
        "disableNextRootInterpolationOnAbortClimb",
        "notifyStopClimbMovingOnCh259Spike",
    }) or ok

    local ctrl = get_climb_ctrl(player)
    if ctrl then
        ok = call_bool_methods(ctrl, false, {
            "set_IsClimbMoving",
            "set_IsInterpolationToTarget",
            "set_IsRequestWaitStart",
        }) or ok
        ok = call_bool_methods(ctrl, true, {
            "set_IsIgnoreTaNonClimb",
        }) or ok
        ok = call_noarg_methods(ctrl, {
            "requestAbortClimb",
            "abortClimb",
            "abortClimbCommon",
            "forceChangeSquatToStand",
        }) or ok
    end

    S.native_climb_mount = false
    S.player_climb_on_character = false
    S.stamina_hold_active = false
    S.climb_stamina_hold = 0.0
    return ok
end

function route3_recover_rider_state(reason)
    local player = get_player()
    local ok = false

    set_native_rider_suppressed(false)
    set_rider_hard_lock(false)
    restore_rider_disabled()
    if player then
        ok = set_think_stop(player, false) or ok
        ok = set_character_controller_enabled(player, true) or ok
        ok = suppress_climb_motion_tick(player, false) or ok
        ok = route3_abort_native_climb(player) or ok
        ok = call_noarg_methods(player, {
            "disableNextRootInterpolationOnAbortClimb",
            "notifyStopClimbMovingOnCh259Spike",
            "forceChangeSquatToStand",
        }) or ok
    end

    S.native_climb_mount = false
    S.player_climb_on_character = false
    S.route3_rider_controller_disabled = false
    S.stamina_hold_active = false
    S.climb_stamina_hold = 0.0
    S.route3_air_rider_status = "rider writes off"
    S.route3_rider_recover_status = string.format("recover %s ok=%s", tostring(reason or "manual"), tostring(ok == true))
    status(S.route3_rider_recover_status)
    return ok == true
end

function route3_clear_landing_request()
    S.route3_landing_requested = false
    S.route3_landing_ground_y = nil
    S.route3_landing_started_at = nil
    S.route3_landing_deadline = nil
    S.route3_landing_missing_since = nil
    S.route3_flap_landing_loop_at = nil
    S.route3_landing_status = "(none)"
end

function route3_begin_landing(ch, go, ground_y, height, reason)
    local now = os.clock()
    local step = math.max(0.02, tonumber(C.route3_landing_auto_step) or 0.15)
    -- Movement is currently per-frame. Budget at a conservative 20 fps so a
    -- legitimate high descent is not mistaken for a hang, then cap it.
    local estimated = (math.max(0.0, tonumber(height) or 0.0) / (step * 20.0)) + 3.0
    local timeout = math.max(2.0, tonumber(C.route3_landing_timeout) or 8.0, estimated)
    timeout = math.min(math.max(timeout, 2.0), math.max(2.0, tonumber(C.route3_landing_max_timeout) or 30.0))
    S.route3_landing_requested = true
    S.route3_landing_started_at = now
    S.route3_landing_deadline = now + timeout
    S.route3_landing_ground_y = tonumber(ground_y)
    S.route3_landing_missing_since = nil
    S.route3_takeoff_lock_until = 0.0
    S.route3_takeoff_lock_status = "(landing)"
    S.route3_flap_phase = "landing"
    S.route3_flap_landing_loop_at = now + 0.9
    S.route3_soar_dir_clip = nil
    S.audition_until_clock = 0.0
    S.route3_air_visual_block_until = 0.0
    route3_flap_clear_overlay()
    route3_flap_set_root_controllers(false)
    clear_motion_queue()
    local start_clip = tonumber(C.landing_motion)
    if start_clip == nil or start_clip < 0 then start_clip = 5030 end
    play_griffin_motion(start_clip, tonumber(C.landing_bank) or 0, true)
    S.route3_landing_status = string.format("landing requested %.1fm (%.1fs budget)", tonumber(height) or 0.0, timeout)
    S.route3_flight_status = S.route3_landing_status
    status(S.route3_flight_status)
    return true
end

function route3_cancel_landing(ch, go, reason)
    route3_clear_landing_request()
    S.route3_flap_phase = nil
    S.route3_soar_dir_clip = nil
    S.audition_until_clock = 0.0
    clear_motion_queue()
    set_griffin_motion_speed(1.0)
    route3_flap_clear_overlay()
    route3_flap_set_root_controllers(false)
    if S.rider_pose_frozen == true then
        griffin_set_player_motion_speed(1.0)
        S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
    end
    local pos = (go and transform_pos(go)) or S.route3_air_pos
    local rot = (go and transform_rot(go)) or S.route3_air_rot
        or make_quat_yaw(S.heading_yaw or (go and yaw_from_transform(go)) or 0.0)
    if pos then S.route3_air_pos = pos end
    if rot then S.route3_air_rot = rot end
    local glide = math.floor(tonumber(C.flap_glide_clip) or 5190)
    if glide >= 0 then play_griffin_motion(glide, tonumber(C.flap_glide_bank) or 0, true) end
    S.route3_air_visual_block_until = 0.0
    S.route3_landing_status = "landing cancelled: " .. tostring(reason or "requested")
    S.route3_flight_status = S.route3_landing_status
    status(S.route3_flight_status)
    return true
end

function route3_landing_ground_or_cancel(ch, go, ground_y, now)
    now = tonumber(now) or os.clock()
    ground_y = tonumber(ground_y)
    if ground_y then
        S.route3_landing_ground_y = ground_y
        S.route3_landing_missing_since = nil
        return ground_y, false
    end
    if not S.route3_landing_missing_since then S.route3_landing_missing_since = now end
    local grace = math.max(0.0, tonumber(C.route3_landing_ground_loss_grace) or 0.75)
    if now - (tonumber(S.route3_landing_missing_since) or now) >= grace then
        route3_cancel_landing(ch, go, "floor lost")
        return nil, true
    end
    return tonumber(S.route3_landing_ground_y), false
end

function route3_takeoff_lock_active()
    return S.airborne == true
        and C.route3_takeoff_lock_enabled == true
        and (tonumber(S.route3_takeoff_lock_until) or 0.0) > os.clock()
end

function route3_release_takeoff_lock_if_due(ch, go)
    local until_t = tonumber(S.route3_takeoff_lock_until) or 0.0
    if S.airborne ~= true or until_t <= 0.0 then return false end
    local now = os.clock()
    if now < until_t then
        S.route3_takeoff_lock_status = string.format("locked %.2fs", until_t - now)
        return false
    end

    S.route3_takeoff_lock_until = 0.0
    local pos = S.route3_air_pos or transform_pos(go)
    local rot = S.route3_air_rot or transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
    local hit = route3_ground_hit_under(go, pos)
    local ground_y = tonumber(hit and hit.y) or tonumber(S.ground_y) or tonumber(pos and pos.y) or 0.0
    local release_height = math.max(0.0, tonumber(C.route3_takeoff_release_height) or 1.8)
    if pos and ground_y and ((tonumber(pos.y) or 0.0) - ground_y) < release_height then
        local lifted = make_position(tonumber(pos.x) or 0.0, ground_y + release_height, tonumber(pos.z) or 0.0)
        S.route3_air_pos = lifted
        S.route3_air_rot = rot
        route3_apply_air_transform(ch, go, lifted, rot)
        S.route3_takeoff_lock_status = string.format("released +%.1fm", release_height)
        return true
    end
    S.route3_takeoff_lock_status = "released"
    return false
end

function route3_air_ground_clearance_tick()
    if griffin_predation_window_active() then return false end
    -- FC-LIFT STANDDOWN: a clearance lift is still a transform write. ⚠ ACCEPTED RISK -- for
    -- the window's length (~1-2s) nothing stops her clipping terrain on a downward node.
    -- route3_rise_fc_cap is small on purpose for exactly this reason; test high up.
    if griffin_rise_fc_window_active() then return false end
    -- ⭐⭐⭐ DOGFIGHT STANDDOWN (2026-08-07, THE SKID-FLOAT THIEF, convicted by tape 19:48:
    -- stolen=+0.31..+0.33 with FC off, rm=0 AND AdjustTerrain on -- every engine suspect
    -- eliminated, and agl pinned at EXACTLY route3_air_ground_clearance = 1.9. It was THIS
    -- net all along, lifting her back to ground+1.9 every frame -- two days blamed on the
    -- engine. The dogfight owns its own floors in every phase (dive 1.0, dash 0.35, skid
    -- 0.15); while it lives, the net stands down.)
    if type(S.route3_dogfight) == "table" then return false end
    if not (S.route3_proxy_ride_active == true and S.airborne == true) then return false end
    if S.route3_landing_requested == true then return false end
    if route3_takeoff_lock_active() then return false end
    if C.route3_air_ground_clearance_enabled ~= true then return false end
    local ch, go = reacquire_griffin()
    if not go then return false end
    local pos = S.route3_air_pos or transform_pos(go)
    if not pos then return false end
    local hit = route3_ground_hit_under(go, pos)
    local ground_y = tonumber(hit and hit.y)
    if not ground_y then return false end
    local clearance = math.max(0.0, tonumber(C.route3_air_ground_clearance) or 3.0)
    local y = tonumber(pos.y) or 0.0
    if y - ground_y >= clearance then return false end
    local rot = S.route3_air_rot or transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
    local lifted = make_position(tonumber(pos.x) or 0.0, ground_y + clearance, tonumber(pos.z) or 0.0)
    S.route3_air_pos = lifted
    S.route3_air_rot = rot
    route3_apply_air_transform(ch, go, lifted, rot)
    S.route3_flight_status = string.format("air clearance %.2fm", clearance)
    return true
end

function route3_delete_saddle_proxy()
    local go = S.route3_saddle_go
    if not go then
        S.route3_seat_status = "saddle proxy: none"
        status(S.route3_seat_status)
        return false
    end
    S.route3_proxy_ride_active = false
    S.route3_seat_parented = false
    if S.route3_rider_controller_disabled then
        set_character_controller_enabled(get_player(), true)
        S.route3_rider_controller_disabled = false
    end
    local ok = false
    pcall(function() go:call("destroy(via.GameObject)", go); ok = true end)
    if not ok then pcall(function() go:call("destroy"); ok = true end) end
    S.route3_saddle_go = nil
    S.route3_seat_status = "saddle proxy deleted ok=" .. tostring(ok)
    status(S.route3_seat_status)
    return ok
end

function route3_update_saddle_proxy(go)
    local saddle = S.route3_saddle_go
    if not (saddle and go) then return false, nil, nil, -1.0 end
    local stf = transform_of(saddle)
    if not stf then return false, nil, nil, -1.0 end
    local ox = tonumber(C.route3_seat_offset_x) or 0.0
    local oy = tonumber(C.route3_seat_offset_y) or 2.3
    local oz = tonumber(C.route3_seat_offset_z) or 1.6
    local seat_pos = route3_root_space_seat_position(go, ox, oy, oz)
    if not seat_pos then return false, nil, nil, -1.0 end
    local rot = transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
    local ok = set_universal_position_any(stf, seat_pos)
    pcall(function() stf:call("set_Rotation", rot) end)
    local gpos = transform_pos(go)
    local dist = seat_pos and gpos and math.sqrt(math.max(0.0, distance_sq(seat_pos, gpos) or 0.0)) or -1.0
    S.route3_saddle_last_dist = dist
    return ok == true, seat_pos, rot, dist
end

function route3_create_saddle_proxy()
    local _, go = reacquire_griffin()
    local gtf = transform_of(go)
    if not gtf then
        S.route3_seat_status = "saddle proxy failed: no griffin transform"
        status(S.route3_seat_status)
        return false
    end

    if S.route3_saddle_go then route3_delete_saddle_proxy() end

    local saddle = nil
    pcall(function()
        saddle = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "GriffinRideProbeSaddle")
    end)
    if not saddle then
        S.route3_seat_status = "saddle proxy failed: GameObject.create failed"
        status(S.route3_seat_status)
        return false
    end

    local stf = transform_of(saddle)
    if not stf then
        S.route3_seat_status = "saddle proxy failed: no proxy transform"
        status(S.route3_seat_status)
        return false
    end

    S.route3_saddle_go = saddle
    local world_ok, _, _, dist = route3_update_saddle_proxy(go)
    S.route3_seat_status = string.format(
        "saddle proxy root-space world=%s dist=%.2f offset=(%.2f %.2f %.2f)",
        tostring(world_ok), dist,
        tonumber(C.route3_seat_offset_x) or 0.0,
        tonumber(C.route3_seat_offset_y) or 2.3,
        tonumber(C.route3_seat_offset_z) or 1.6)
    status(S.route3_seat_status)
    return world_ok == true
end

function route3_stop_proxy_ride(reason)
    S.route3_abort_veto_off_until = os.clock() + 3.0   -- round 6b: never reject aborts mid-teardown
    route3_wilds_rider_pose_stop(tostring(reason or "proxy stop"))
    S.route3_proxy_ride_active = false
    S.route3_seat_parented = false
    S.airborne = false
    S.flying = false
    S.mounted = false
    S.route3_post_landing_recover_at = 0.0
    if S.rider_pose_frozen == true then
        griffin_set_player_motion_speed(1.0)
        S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
    end
    if S.route3_rider_controller_disabled then
        set_character_controller_enabled(get_player(), true)
        S.route3_rider_controller_disabled = false
    end
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    if route3_clear_landing_request then route3_clear_landing_request() end
    if route3_recover_rider_state then route3_recover_rider_state("proxy stop") end
    S.route3_seat_status = "proxy drive stopped: " .. tostring(reason or "manual")
    status(S.route3_seat_status)
end

function route3_apply_air_transform(ch, go, pos, rot)
    if not (go and pos and sane_position(pos)) then
        S.route3_air_reapply_status = "no pos/go"
        return false
    end
    local ok = false
    pcall(function()
        local tf = go:call("get_Transform")
        tf:call("set_UniversalPosition", pos)
        pcall(function() tf:call("set_Position", pos) end)
        if rot then tf:call("set_Rotation", rot) end
        ok = true
    end)
    if ch then
        -- the CHARACTER's logic rotation must stay flat (yaw only): feeding it
        -- a pitched quat makes it re-derive orientation and flip upside down
        local char_rot = rot
        if math.abs(tonumber(S.route3_air_pitch) or 0.0) > 0.2 then
            char_rot = make_quat_yaw(S.heading_yaw or yaw_from_transform(go) or 0.0)
        end
        ok = set_character_transform(ch, pos, char_rot) or ok
    end
    if ok then
        S.route3_air_reapply_hits = (tonumber(S.route3_air_reapply_hits) or 0) + 1
        S.route3_air_reapply_status = "ok"
    else
        S.route3_air_reapply_status = "write failed"
    end
    if ok and C.route3_flight_write_rider == true then
        local player = get_player()
        local seat_pos = nil
        pcall(function()
            local ox = tonumber(C.route3_seat_offset_x) or 0.0
            local oy = tonumber(C.route3_seat_offset_y) or 2.3
            local oz = tonumber(C.route3_seat_offset_z) or 1.6
            local yaw = S.heading_yaw or yaw_from_transform(go) or 0.0
            local fwd = { x = math.sin(yaw), y = 0.0, z = math.cos(yaw) }
            local right = { x = math.cos(yaw), y = 0.0, z = -math.sin(yaw) }
            seat_pos = make_position(
                (tonumber(pos.x) or 0.0) + (right.x * ox) + (fwd.x * oz),
                (tonumber(pos.y) or 0.0) + oy,
                (tonumber(pos.z) or 0.0) + (right.z * ox) + (fwd.z * oz)
            )
        end)
        local rider_ok = false
        if seat_pos then
            rider_ok = set_character_transform(player, seat_pos, rot) or false
            local pgo = char_go(player)
            if pgo then rider_ok = set_transform(pgo, seat_pos, rot) or rider_ok end
        end
        S.route3_air_rider_status = rider_ok and "rider ok" or "rider failed"
    end
    return ok == true
end

function route3_ground_hit_under(go, pos)
    local p = pos or transform_pos(go)
    if not p then return nil end
    -- render x/z for the ray; y is UNIVERSAL -- route3_cast_ground_below converts y between
    -- spaces internally (⚠ y is NOT shared between spaces; see route3_y_space_offset).
    local rp = transform_render_pos(go)
    return route3_cast_ground_below(
        tonumber(rp and rp.x) or tonumber(p.x) or 0.0,
        tonumber(p.y) or 0.0,
        tonumber(rp and rp.z) or tonumber(p.z) or 0.0,
        10.0,
        120.0
    )
end

function route3_ground_y_robust(go, ref_hint)
    -- Ground Y under the griffin, robust to fast descents. The tight per-frame cast rejects any
    -- contact >1m above the ray origin, so a body that has dipped below the surface reads nil and
    -- keeps sinking/skimming. Try the tight cast first (avoids treetops while above), else cast
    -- from WELL above (entry altitude) so the floor is still found from over the top.
    if not go then return nil end
    local gy = nil
    pcall(function() local gh = route3_ground_hit_under(go); if gh and tonumber(gh.y) then gy = tonumber(gh.y) end end)
    if gy then return gy end
    pcall(function()
        local rp = transform_render_pos(go)
        local up = transform_pos(go)
        local gx = (rp and tonumber(rp.x)) or (up and tonumber(up.x)) or 0.0
        local gz = (rp and tonumber(rp.z)) or (up and tonumber(up.z)) or 0.0
        local base = math.max(tonumber(up and up.y) or 0.0, tonumber(ref_hint) or -1.0e9)
        local gh = route3_cast_ground_below(gx, base + 8.0, gz, 5.0, 500.0)
        if gh and tonumber(gh.y) then gy = tonumber(gh.y) end
    end)
    return gy
end

function route3_finish_landing(ch, go, ground_y, reason)
    local pos = transform_pos(go) or S.route3_air_pos
    local yaw = S.heading_yaw or yaw_from_transform(go) or 0.0
    local rot = make_quat_yaw(yaw)
    local y = (tonumber(ground_y) or tonumber(pos and pos.y) or 0.0)
        + (tonumber(C.route3_ground_follow_offset) or 0.0)
        + (tonumber(C.route3_landing_height_offset) or 0.0)
    local snap = pos and make_position(tonumber(pos.x) or 0.0, y, tonumber(pos.z) or 0.0) or nil

    if snap then
        set_transform(go, snap, rot)
        if ch then set_character_transform(ch, snap, rot) end
    end
    -- landing telemetry: compare coordinate spaces to catch tile-offset bugs
    pcall(function()
        local upos = transform_pos(go)
        local rpos = transform_render_pos(go)
        json.dump_file(MOD .. "_landing_probe.json", {
            time = os.date("%H:%M:%S"),
            reason = tostring(reason or "?"),
            ground_y_used = tonumber(ground_y),
            final_y = y,
            universal_pos = upos and { x = tonumber(upos.x), y = tonumber(upos.y), z = tonumber(upos.z) } or "(nil)",
            render_pos = rpos and { x = tonumber(rpos.x), y = tonumber(rpos.y), z = tonumber(rpos.z) } or "(nil)",
            debug = tostring(S.route3_landing_debug or "(none)"),
        })
    end)
    S.ground_y = y
    S.airborne = false
    S.flying = false
    S.route3_touchdown_at = os.clock()   -- AIR SEAT release signal: a REAL landing happened
                                         -- (reviewer issue 5: airborne=false alone is NOT touchdown)
    route3_flap_set_root_controllers(true)
    route3_flap_clear_overlay()
    -- CALM-NET AT TOUCHDOWN: landing stops flight_tick + re-enables root controllers, leaving a ~0.8s
    -- gap (until route3_post_landing_recover_tick) where any woken combat state (e.g. from an aerial
    -- attack action) drives her body UP (float) + surfaces battle BGM. Re-assert the exact calm calls
    -- the recover tick makes -- just now, at touchdown -- so a woken state can't slip through the seam.
    pcall(function() clear_griffin_hate() end)
    pcall(function() clear_griffin_targets() end)
    if S.mounted and C.disable_griffin_ai and go then
        pcall(function() disable_record(get_component(go, "app.AIDecisionMaker"), "app.AIDecisionMaker") end)
        pcall(function() disable_record(get_component(go, "app.NavigationAI"), "app.NavigationAI") end)
    end
    if S.rider_pose_frozen == true then
        griffin_set_player_motion_speed(1.0)
        S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil; S.rider_pose_wait_since = nil; S.rider_pose_settle_still = nil; S.rider_pose_settle_moved = nil
    end
    route3_clear_landing_request()
    S.route3_flap_phase = nil
    S.route3_air_pos = nil
    S.route3_air_rot = nil
    S.route3_takeoff_lock_until = 0.0
    S.route3_takeoff_lock_status = "(landed)"
    S.route3_audio_soar_started = false
    S.route3_air_visual_block_until = os.clock() + 1.0
    if C.route3_wing_replay_enabled == true then
        C.route3_wing_replay_enabled = false
        S.route3_wing_replay_status = "(off: landed)"
    end
    S.route3_wing_replay_user_stopped = false
    S.route3_native_flight_node = nil
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    S.route3_motion_blocked = false
    S.route3_stuck_since = 0.0
    clear_motion_queue()
    -- touchdown: play the landing END clip (the start/descent-loop already
    -- played during the R3 descent via the flap tick)
    -- ⭐ QUIET LANDING (2026-08-07, Aurora: the skid pounce ended with "a random landing hit
    -- the floor animation and impact" -- she is ALREADY on the ground there; the touchdown
    -- slam is redundant drama. One-shot flag: skip the clip, let the post-landing recover's
    -- idle be the settle.)
    if S.route3_landing_quiet == true then
        S.route3_landing_quiet = nil
    else
        local landing_motion = tonumber(C.landing_end_motion)
        if landing_motion == nil or landing_motion < 0 then landing_motion = 5032 end
        play_griffin_motion(landing_motion, tonumber(C.landing_end_bank) or 0, true)
        -- protect the landing clip from the ground visual tick for its duration
        S.audition_until_clock = os.clock() + 1.2
    end
    S.route3_post_landing_recover_at = os.clock() + math.max(0.1, tonumber(C.route3_post_landing_recover_seconds) or 0.8)
    S.route3_post_landing_recover_status = "waiting"
    S.route3_landing_status = "landed: " .. tostring(reason or "auto")
    S.route3_flight_status = S.route3_landing_status
    status(S.route3_flight_status)
    return true
end

function route3_post_landing_recover_tick()
    local recover_at = tonumber(S.route3_post_landing_recover_at) or 0.0
    if recover_at <= 0.0 or os.clock() < recover_at then return false end
    S.route3_post_landing_recover_at = 0.0

    local ch, go = reacquire_griffin()
    S.route3_motion_blocked = false
    S.route3_stuck_since = 0.0
    S.last_route3_edge_guard = "landing recovered"
    S.last_character_root_move_error = "landing recovered"
    clear_motion_queue()
    local ok = set_griffin_motion_speed(1.0)
    local idle_bank = tonumber(C.root_motion_idle_bank) or tonumber(C.idle_bank) or 0
    local idle_motion = tonumber(C.root_motion_idle)
    if idle_motion == nil or idle_motion < 0 then idle_motion = tonumber(C.idle_motion) or 0 end
    ok = play_griffin_motion(idle_motion, idle_bank, true) or ok
    clear_griffin_hate()
    clear_griffin_targets()
    stop_navigation(ch, true)
    -- Re-arm ridden AI suppression on EVERY landing: a native catch's
    -- set_griffin_puppet(false)->restore_disabled() wakes AIDecisionMaker/
    -- NavigationAI and nothing else puts them back -> ground skating. Idempotent,
    -- and the universal net for a drop that happened after hand-off.
    if S.mounted and C.disable_griffin_ai and go then
        disable_record(get_component(go, "app.AIDecisionMaker"), "app.AIDecisionMaker")
        disable_record(get_component(go, "app.NavigationAI"), "app.NavigationAI")
    end
    if go then set_motion_fsm_puppet(go, C.puppet_motion_fsm == true) end
    if C.native_climb_force_calm_fsm then set_griffin_fsm_node_silent(C.native_climb_calm_fsm_node, C.native_climb_calm_fsm_tree) end
    set_think_stop(ch, false)
    if S.route3_proxy_ride_active == true then
        ok = route3_start_proxy_ride() or ok
        set_think_stop(ch, false)
    end
    S.last_root_motion_state = "idle"
    S.last_root_motion_key = "(landing recovered)"
    S.last_root_motion_played = false
    S.route3_post_landing_recover_status = ok and "ok/rearmed" or "partial/rearmed"
    S.route3_flight_status = "ground: landing recovered"
    return ok == true
end

function route3_toggle_flight(reason)
    if C.route3_allow_flight ~= true then
        S.route3_flight_status = "this creature cannot fly"
        status(S.route3_flight_status)
        return false
    end
    local ch, go = reacquire_griffin()
    local gpos = transform_pos(go)
    if not (S.route3_proxy_ride_active == true and ch and go and gpos) then
        S.route3_flight_status = "flight failed: start ride first"
        status(S.route3_flight_status)
        return false
    end

    if S.airborne == true then
        if S.route3_landing_requested == true then
            -- second R3 press while descending = a complete return to flight,
            -- including motion/root-controller ownership.
            return route3_cancel_landing(ch, go, "R3")
        end
        local air_pos = S.route3_air_pos or gpos
        local hit = route3_ground_hit_under(go, air_pos)
        local ground_y = tonumber(hit and hit.y)
        if not ground_y then
            S.route3_landing_status = "landing refused: no floor below"
            S.route3_flight_status = S.route3_landing_status
            status(S.route3_flight_status)
            return false
        end
        local height = (tonumber(air_pos and air_pos.y) or tonumber(gpos.y) or 0.0) - ground_y
        -- CARRY -> MEAL HANDOFF (Fable HIGH): Catch.Ch253CarryCatchToFlight only exits to a flight
        -- node, so the release MUST happen while AIRBORNE (proven: drop-in-flight clears it; grounded
        -- it is unclearable). Release at landing intent, ragdoll the kill, arm a pending eat that
        -- fires after touchdown (in the clean neutral node where the L0 eat clip is visible).
        if C.route3_predation_eat_enabled ~= false and griffin_predation_native_carry_active() then
            local prey = S.route3_predation_carry_prey or S.route3_predation_victim or S.companion_target
            S.nt_allow_actions_until = os.clock() + 1.5   -- let the native end/cancel actions play
            pcall(function() griffin_predation_release_native_catch() end)  -- exit_cleanup airborne branch requests Fly.Flying.FlyForward (proven safe)
            S.route3_predation_mode = nil                 -- close the predation window so flight/descent works
            S.route3_predation_wake_until = 0.0
            S.route3_predation_probe_until = 0.0
            S.route3_predation_native_until = 0.0
            S.route3_predation_replay_stage = "handed-off"
            if prey then
                pcall(function() griffin_apply_attack_damage(prey, 99999.0) end)
                pcall(function() prey:call("EnableRagdoll(System.Boolean)", true) end)
                pcall(function() prey:call("startRagdoll") end)
                S.route3_predation_eat_pending = { prey = prey, t0 = os.clock() }
            end
        end
        if height <= math.max(0.05, tonumber(C.route3_flight_instant_land_height) or 0.6) then
            -- close enough to touch down directly without a visible pop
            return route3_finish_landing(ch, go, ground_y, reason or "toggle")
        end
        return route3_begin_landing(ch, go, ground_y, height, reason)
    end

    S.airborne = true
    -- Landing clears both airborne and flying.  Re-take-off can happen before the delayed
    -- landing recover calls route3_start_proxy_ride(), so take-off itself must restore both.
    -- Without this, the HUD says "Land" from airborne=true but flight_tick still returns on
    -- flying=false, leaving the body parked on take-off motion 5210.
    S.flying = true
    route3_clear_landing_request()
    S.route3_flap_phase = nil
    S.route3_flap_seeked = false
    S.route3_flap_load_request = 0.0
    S.route3_flap_landing_loop_at = nil
    S.base_owner = nil
    S.audition_until_clock = 0.0
    S.route3_post_landing_recover_at = 0.0
    S.route3_post_landing_recover_status = "(takeoff)"
    S.route3_audio_soar_started = false
    S.route3_audio_last_flap = os.clock()
    S.route3_audio_last_wind = 0.0
    S.ground_y = tonumber(gpos.y) or S.ground_y
    S.route3_air_pos = make_position(tonumber(gpos.x) or 0.0, tonumber(gpos.y) or 0.0, tonumber(gpos.z) or 0.0)
    S.route3_air_rot = transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
    S.route3_air_visual_block_until = os.clock() + 1.0
    S.route3_wing_replay_user_stopped = false
    S.route3_wing_replay_auto_failed = false
    S.route3_native_flight_node = nil
    S.route3_native_flight_last_check = 0.0
    if C.route3_takeoff_lock_enabled == true then
        S.route3_takeoff_lock_until = os.clock() + math.max(0.0, tonumber(C.route3_takeoff_lock_seconds) or 1.1)
        S.route3_takeoff_lock_status = string.format("locked %.2fs", tonumber(C.route3_takeoff_lock_seconds) or 1.1)
    else
        S.route3_takeoff_lock_until = 0.0
        S.route3_takeoff_lock_status = "(disabled)"
    end
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    clear_motion_queue()
    set_think_stop(ch, false)
    if C.route3_flight_play_takeoff_motion == true then
        local takeoff_motion = tonumber(C.takeoff_motion)
        if takeoff_motion == nil or takeoff_motion < 0 then
            takeoff_motion = 5210
            C.takeoff_bank = tonumber(C.takeoff_bank) or 0
            C.takeoff_motion = takeoff_motion
        end
        play_griffin_motion(takeoff_motion, C.takeoff_bank, true)
    else
        set_griffin_motion_speed(1.0)
        clear_griffin_hate()
        clear_griffin_targets()
        stop_navigation(ch, true)
        set_motion_fsm_puppet(go, C.puppet_motion_fsm == true)
        set_think_stop(ch, false)
    end
    route3_play_ride_audio("takeoff", C.route3_audio_takeoff_trigger_id)
    if C.route3_flight_play_takeoff_motion == true and C.use_motion_chain == true and C.route3_flight_use_motion_chain == true then
        queue_griffin_motion(C.takeoff_transition_seconds, C.takeoff_transition_bank, C.takeoff_transition_motion)
        queue_griffin_motion(C.takeoff_to_flight_seconds, C.flight_bank, C.flight_motion)
    end
    S.route3_flight_status = "takeoff: " .. tostring(reason or "toggle")
    status(S.route3_flight_status)
    return true
end

function route3_start_proxy_ride()
    local player = get_player()
    local ch, go = reacquire_griffin()
    if not (player and ch and go) then
        S.route3_seat_status = "proxy drive failed: need player + griffin"
        status(S.route3_seat_status)
        return false
    end
    update_player_climb_state()
    if not (S.native_climb_mount == true or S.player_climb_on_character == true) then
        S.route3_seat_status = "proxy drive failed: climb on/adopt first; no rider transform writes"
        status(S.route3_seat_status)
        return false
    end
    if not S.route3_saddle_go then
        if not route3_create_saddle_proxy() then return false end
    end
    local ok, seat_pos, rot, dist = route3_update_saddle_proxy(go)
    if not ok or not seat_pos then
        -- the saddle GameObject can go stale after a zone change: rebuild once and retry
        route3_delete_saddle_proxy()
        if route3_create_saddle_proxy() then
            ok, seat_pos, rot, dist = route3_update_saddle_proxy(go)
        end
    end
    if not ok or not seat_pos then
        S.route3_seat_status = "proxy drive failed: saddle update failed"
        status(S.route3_seat_status)
        return false
    end
    if dist > (tonumber(C.route3_proxy_max_saddle_distance) or 8.0) then
        S.route3_seat_status = string.format("proxy drive blocked: saddle %.1fm from griffin", dist)
        status(S.route3_seat_status)
        return false
    end

    arm_ride_drive()
    S.mounted = true
    S.flying = true
    S.airborne = false
    S.native_climb_mount = true
    S.route3_proxy_ride_active = true
    S.route3_seat_parented = false
    S.heading_yaw = yaw_from_transform(go) or S.heading_yaw or 0.0
    -- Safe path: the native climb relationship is the sole rider-position authority.
    -- Even a one-shot player transform correction is an ownership violation: the climb
    -- solver moves her back and can wake the rollback/stuck-player rescue machinery.
    -- The old snap remains available only with the explicitly unsafe puppet experiment.
    local rider_snap_ok = true
    if C.route3_rider_puppet_enabled == true then
        rider_snap_ok = apply_rider_transform(seat_pos, nil)
    end
    -- ROUND-47 engage-race gate: don't start the pose (and with it the puppet) in the
    -- same breath as the mount adopt -- on storm mounts native systems survive an
    -- engage that races the mount transition. Defer to griffin_rider_engage_gate_tick
    -- until the climb clip is stable (or 2.0s timeout).
    local rider_pose_ok = false
    if C.route3_rider_engage_gate ~= false and C.route3_wilds_rider_pose_enabled == true then
        S.route3_rider_gate_last = nil
        S.route3_rider_pose_gate_until = os.clock() + 2.0
        rider_pose_ok = "gated"
    else
        rider_pose_ok = route3_wilds_rider_pose_start() == true
    end
    save_config()
    S.route3_seat_status = string.format("proxy drive active dist=%.2f snap=%s pose=%s",
        dist, tostring(rider_snap_ok == true), tostring(rider_pose_ok))
    status(S.route3_seat_status)
    return true
end

function route3_start_auto_ride(reason)
    -- refuse to start a ride while she is mid EAT command: mounting her then would let
    -- griffin_eat_end run resetActionAndAI on a body the ride just placed in a native
    -- climb-mount = crash class. Let her finish (or recall her) first.
    if griffin_eat_active() then
        S.route3_auto_status = "she is feeding -- can't ride yet"
        status(S.route3_auto_status)
        return false
    end
    if C.route3_mountable ~= true then
        S.route3_auto_status = tostring(C.route3_griffin_name or "This creature") .. " is a companion, not a mount"
        status(S.route3_auto_status)
        return false
    end
    S.route3_auto_start_in_progress = true
    local adopted = false
    if S.native_climb_mount == true then
        adopted = true
    else
        adopted = adopt_native_climb_mount() == true
    end
    if not adopted then
        S.route3_auto_status = "auto ride failed: climb onto griffin first"
        status(S.route3_auto_status)
        S.route3_auto_start_in_progress = false
        return false
    end

    pcall(function() apply_critter_neutrality() end)

    local saddle_ok = S.route3_saddle_go ~= nil or route3_create_saddle_proxy() == true
    if not saddle_ok then
        S.route3_auto_status = "auto ride failed: saddle proxy"
        status(S.route3_auto_status)
        S.route3_auto_start_in_progress = false
        return false
    end

    local ride_ok = route3_start_proxy_ride() == true
    if ride_ok then
        S.route3_auto_status = "auto ride active: " .. tostring(reason or "manual")
    else
        S.route3_auto_status = "auto ride failed: proxy start"
    end
    status(S.route3_auto_status)
    S.route3_auto_start_in_progress = false
    return ride_ok
end

function route3_keyboard_key_down(vk)
    local key = math.floor(tonumber(vk) or 0)
    if key <= 0 then return false end
    local down = false
    pcall(function() down = iris_kb(key) end)
    return down == true
end

function route3_adopt_hotkey_down()
    if C.route3_adopt_hotkey_enabled ~= true then return false end
    local keyboard = route3_keyboard_key_down(C.route3_adopt_keyboard_key)
    local named_text = tostring(C.route3_adopt_gamepad_buttons or ""):gsub("%s+", "")
    local named_pad = false
    local mask_pad = false
    if named_text ~= "" then
        named_pad = raw_gamepad_button_down(C.route3_adopt_gamepad_buttons)
    else
        mask_pad = raw_gamepad_mask_down(C.route3_adopt_gamepad_mask)
    end
    if keyboard then S.route3_adopt_last_input = "keyboard" end
    if named_pad then S.route3_adopt_last_input = "named pad" end
    if mask_pad then S.route3_adopt_last_input = string.format("mask pad 0x%X", math.floor(tonumber(C.route3_adopt_gamepad_mask) or 0)) end
    return keyboard == true or named_pad == true or mask_pad == true
end

-- Horses share the IRIS stable, but not the griffin's native climb rig.
-- Detect them from the Wild Horses registry (authoritative for ch299011)
-- and backfill the stable kind on older horse records such as Chad.
function route3_active_horse_mount(ggo)
    if not ggo then return nil end
    local horse = false
    pcall(function()
        local api = rawget(_G, "__iris_wild_horses_api")
        horse = api and api.is_horse and api.is_horse(ggo) == true
    end)
    local active = nil
    local st = S.route3_stable
    if st and st.active and st.companions then
        for _, rec in ipairs(st.companions) do
            if rec.id == st.active then active = rec; break end
        end
    end
    if active and active.kind == "horse" then horse = true end
    if not horse then return nil end
    if active and active.kind ~= "horse" then
        -- ⛔ SPECIES AGREEMENT (2026-08-07): the wild-horses registry can hold a STALE
        -- GameObject handle that the engine reuses for a new spawn -- is_horse() then said
        -- yes to IRIS THE GRIFFIN, this stamp saved kind=horse onto a ch253 record, and the
        -- boot restore rebuilt her on the horse chassis ("Iris ♂ (Horse)", grip found no
        -- griffin to latch). Only a real horse-chassis species may ever be stamped.
        if tostring(active.species or ""):find("ch299011", 1, true) then
            active.kind = "horse"
            pcall(function() griffin_stable_write() end)
        else
            return nil   -- registry misfire on a non-horse: do NOT route her to the horse mount
        end
    end
    return rawget(_G, "IrisHorseMount")
end

function griffin_firmly_grounded()
    -- DISMOUNT GATE (Aurora 2026-07-20): she must be FIRMLY on the ground to unmount, else she floats.
    -- S.airborne alone missed the "hovering just above ground / mid-descent / mid-jump" cases, so ALSO
    -- raycast: her body must be within route3_dismount_ground_max of the real ground. Fails OPEN (allows
    -- dismount) if the griffin/ground can't be read, so a bad read never traps the player mounted.
    if S.airborne == true then return false end
    if S.route3_ground_jump_active == true then return false end
    local _, ggo = reacquire_griffin()
    if not ggo then return true end
    local up = transform_pos(ggo)
    local rp = transform_render_pos(ggo) or up
    if not (up and rp) then return true end
    local hit = route3_cast_ground_below(tonumber(rp.x) or 0.0, tonumber(up.y) or 0.0, tonumber(rp.z) or 0.0, 3.0, 120.0)
    if not (hit and tonumber(hit.y)) then return true end
    return ((tonumber(up.y) or 0.0) - (tonumber(hit.y) or 0.0)) <= (tonumber(C.route3_dismount_ground_max) or 0.6)
end

function route3_adopt_hotkey_tick()
    local down = route3_adopt_hotkey_down()
    if down == true and S.route3_adopt_hotkey_prev ~= true then
        local _, active_go = reacquire_griffin()
        local horse_mount = route3_active_horse_mount(active_go)
        if horse_mount then
            local mounted = false
            pcall(function()
                mounted = horse_mount.is_mounted
                    and horse_mount.is_mounted(active_go) == true
            end)
            local ok = false
            if mounted then
                pcall(function()
                    ok = horse_mount.dismount(active_go) == true
                end)
                S.route3_auto_status = ok and "horse dismounted"
                    or "horse dismount failed"
            else
                pcall(function()
                    ok = horse_mount.mount(active_go) == true
                end)
                S.route3_auto_status = ok and "horse mounted through Rodeo"
                    or "horse mount failed: Rodeo owner unavailable"
            end
            status(S.route3_auto_status)
            S.route3_adopt_hotkey_prev = down == true
            return
        end
        if S.route3_proxy_ride_active == true or S.mounted == true then
            if not griffin_firmly_grounded() and C.route3_adopt_hotkey_dismount_airborne ~= true then
                S.route3_auto_status = "dismount blocked: land first (not firmly grounded)"
                status(S.route3_auto_status)
            else
                dismount_griffin()
                S.route3_auto_status = "ride toggled off"
            end
        else
            route3_start_auto_ride("hotkey")
        end
    end
    S.route3_adopt_hotkey_prev = down == true
end

function route3_flight_hotkey_down()
    if C.route3_adopt_hotkey_enabled ~= true then return false end
    local named_text = tostring(C.route3_flight_toggle_buttons or ""):gsub("%s+", "")
    local named_pad = false
    local mask_pad = false
    if named_text ~= "" then
        named_pad = raw_gamepad_button_down(C.route3_flight_toggle_buttons)
    else
        mask_pad = raw_gamepad_mask_down(C.route3_flight_toggle_mask)
    end
    return named_pad == true or mask_pad == true
end

function route3_flight_hotkey_tick()
    local down = route3_flight_hotkey_down()
    if down == true and S.route3_flight_hotkey_prev ~= true then
        route3_toggle_flight("hotkey")
    end
    S.route3_flight_hotkey_prev = down == true
end

function route3_proxy_rider_tick(go)
    if S.route3_proxy_ride_active ~= true then return false end
    local ok, seat_pos, rot, dist = route3_update_saddle_proxy(go)
    if not ok or not seat_pos then
        route3_stop_proxy_ride("saddle update failed")
        return false
    end
    if dist > (tonumber(C.route3_proxy_max_saddle_distance) or 8.0) then
        route3_stop_proxy_ride(string.format("saddle %.1fm from griffin", dist))
        return false
    end
    -- Deliberately do not write the player transform here. Native climb is the rider attachment.
    return true
end


function route3_edge_guard_allows_move(go, dx, dz)
    if S.route3_ground_jump_active == true then return true end
    if C.route3_edge_guard_enabled ~= true or S.airborne == true then
        S.last_route3_edge_guard = "(disabled)"
        return true
    end
    if math.abs(tonumber(dx) or 0.0) + math.abs(tonumber(dz) or 0.0) < 0.001 then
        S.last_route3_edge_guard = "idle"
        return true
    end
    local rpos = transform_render_pos(go)
    if not rpos then
        S.last_route3_edge_guard = "no position"
        return true
    end
    local nx = (tonumber(rpos.x) or 0.0) + (tonumber(dx) or 0.0)
    local ny = tonumber(rpos.y) or 0.0
    local nz = (tonumber(rpos.z) or 0.0) + (tonumber(dz) or 0.0)
    local hit = route3_cast_ground_ray(
        nx, ny, nz,
        tonumber(C.route3_ground_follow_up) or 2.5,
        tonumber(C.route3_ground_follow_down) or 8.0
    )
    if not hit then
        S.last_route3_edge_guard = "BLOCK no ground"
        return false
    end
    local drop = ny - (tonumber(hit.y) or ny)
    local max_drop = math.max(0.0, tonumber(C.route3_edge_guard_max_drop) or 1.5)
    if drop > max_drop then
        S.last_route3_edge_guard = string.format("BLOCK drop %.2f", drop)
        return false
    end
    S.last_route3_edge_guard = string.format("ok drop %.2f", drop)
    return true
end

local function component_summary(go, patterns)
    local out = {}
    pcall(function()
        local comps = go and go:call("get_Components")
        for _, c in ipairs(system_array_to_table(comps)) do
            local td = c and c:get_type_definition()
            local full = td and td:get_full_name() or "?"
            local lo = full:lower()
            local matched = false
            for _, pat in ipairs(patterns) do
                if lo:find(pat, 1, true) then matched = true; break end
            end
            if matched then
                out[#out + 1] = {
                    type = full,
                    methods = method_names_matching(c, patterns, 80),
                }
            end
        end
    end)
    table.sort(out, function(a, b) return tostring(a.type) < tostring(b.type) end)
    return out
end
_G.component_summary = component_summary

update_player_climb_state = function()
    -- AIR SEAT (reviewer issue 2): while the flight seat owns the rider the climb is
    -- deliberately DEAD, but every ride gate keys on this flag -- report seated as climbing.
    if S.route3_air_seat_on == true then
        S.player_climb_on_character = true
        return true
    end
    local player = get_player()
    local climbing = false
    pcall(function() climbing = player and player:call("get_IsClimbOnCharacter") == true end)
    S.player_climb_on_character = climbing == true
    return S.player_climb_on_character
end

local function get_player_stamina_manager()
    local player = get_player()
    local sm = nil
    pcall(function() sm = player and player:call("get_StaminaManager") end)
    if not sm then pcall(function() sm = player and player:get_StaminaManager() end) end
    return sm
end

read_player_stamina = function()
    local sm = get_player_stamina_manager()
    local v = nil
    pcall(function() v = sm and sm:call("get_RemainingAmount") end)
    if v == nil then pcall(function() v = sm and sm:get_RemainingAmount() end) end
    return tonumber(v)
end

local function read_player_stamina_max()
    local sm = get_player_stamina_manager()
    local v = nil
    pcall(function() v = sm and sm:call("get_MaxValue") end)
    if v == nil then pcall(function() v = sm and sm:get_MaxValue() end) end
    return tonumber(v)
end

local function write_player_stamina(value)
    local sm = get_player_stamina_manager()
    local target = tonumber(value)
    if not (sm and target) then return false end

    local ok = false
    pcall(function() sm:call("set_RemainingAmount", target); ok = true end)
    if not ok then pcall(function() sm:set_RemainingAmount(target); ok = true end) end
    if not ok then
        local cur = read_player_stamina()
        if cur then
            local delta = target - cur
            pcall(function() sm:add(delta, false); ok = true end)
        end
    end
    return ok
end

hold_climb_stamina_tick = function()
    if not C.enabled then return end
    -- the GRIP AID (taming-side toggle) must work even with the tame-climb hold OFF
    local ga_on = false
    pcall(function()
        local t9 = _G.IrisTaming
        ga_on = (t9 and t9.grip_aid_on and t9.grip_aid_on()) == true
    end)
    if not (C.hold_climb_stamina or ga_on) then return end
    if S.player_climb_on_character ~= true then S.stamina_hold_active = false; return end
    -- Hold stamina while climbing a TAMED creature -- both the MOUNTED phase
    -- (native_climb_mount) AND the climb-UP before mounting (Aurora: climbing a tame
    -- shouldn't drain stamina, only climbing a wild monster should). get_IsClimbOnCharacter
    -- doesn't say WHAT we're on, so confirm a tamed body is right under the player by
    -- proximity -- never gives free stamina when climbing a wild monster in combat.
    local on_tame = S.native_climb_mount == true
    if not on_tame then
        local ppos = char_go(get_player()) and transform_pos(char_go(get_player()))
        if ppos then
            local near2 = math.max(4.0, tonumber(C.climb_stamina_tame_radius) or 6.0)
            near2 = near2 * near2
            local function close(ch)
                local pos = ch and char_go(ch) and transform_pos(char_go(ch))
                return pos and (distance_sq(pos, ppos) or 1e18) < near2
            end
            if close(S.griffin) then on_tame = true end
            if not on_tame then for ch in pairs(mounts) do if close(ch) then on_tame = true; break end end end
            -- NEST-HUNT exception (Aurora, image 52): with the taming side's GRIP AID on, a WILD
            -- GRIFFIN also holds your stamina -- riding the commuter to its nest is the survey
            -- technique, and running dry mid-sky is a death sentence. Griffins ONLY (ch253):
            -- this is a hitchhiking aid, never a free climb on combat monsters.
            if not on_tame then
                pcall(function()
                    local t9 = _G.IrisTaming
                    if not (t9 and t9.grip_aid_on and t9.grip_aid_on()) then return end
                    if os.clock() >= (tonumber(S.grip_aid_scan_at) or 0.0) or S.grip_aid_near == nil then
                        S.grip_aid_scan_at = os.clock() + 1.0
                        S.grip_aid_near = false
                        local sm9 = sdk.get_native_singleton("via.SceneManager")
                        local smt9 = sdk.find_type_definition("via.SceneManager")
                        local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                        local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                        local n9 = 0
                        pcall(function() n9 = comps9:call("get_Length") or 0 end)
                        if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                        for i9 = 0, (tonumber(n9) or 0) - 1 do
                            local hit9 = false
                            pcall(function()
                                local ch9 = comps9:call("get_Item", i9) or comps9[i9]
                                local go9 = ch9 and char_go(ch9)
                                if not go9 or is_dead(ch9) then return end
                                local nm9 = "" ; pcall(function() nm9 = tostring(go9:call("get_Name")) end)
                                if not nm9:find("ch253", 1, true) then return end
                                if close(ch9) then hit9 = true end
                            end)
                            if hit9 then S.grip_aid_near = true; break end
                        end
                    end
                    if S.grip_aid_near then on_tame = true end
                end)
            end
        end
    end
    if not on_tame then return end
    local cur = read_player_stamina()
    if not cur then return end

    if not S.stamina_hold_active then
        S.climb_stamina_hold = cur
        S.stamina_hold_active = true
    end

    S.last_stamina = cur
    local floor = math.max(tonumber(S.climb_stamina_hold) or cur, tonumber(C.climb_stamina_floor) or 0.0)
    local max_stamina = read_player_stamina_max()
    if max_stamina then floor = math.min(floor, max_stamina) end

    if cur + 0.01 < floor then
        S.last_stamina_write_ok = write_player_stamina(floor)
        if S.last_stamina_write_ok then S.last_stamina = floor end
    end
end

function route3_wwise_container()
    local ch = reacquire_griffin()
    local wwise_container = nil
    pcall(function() wwise_container = ch and ch:get_field("<WwiseContainer>k__BackingField") end)
    if not wwise_container then pcall(function() wwise_container = ch and ch:call("get_WwiseContainer") end) end
    return wwise_container
end

function route3_install_sfx_tap()
    -- DOUBLE-FLAP FORENSICS: hook the Wwise trigger methods game-wide and log every trigger fired
    -- while mounted. When a grab/dive bomb ends, the log auto-dumps with same-id-within-0.3s pairs
    -- flagged DOUBLE -- ground truth on which sound fires twice (code-reading exhausted: overlay is
    -- empty, paced audio off, so the doubler is NOT the known suspects).
    if S.sfx_tap_installed then return end
    S.sfx_tap_installed = true
    S.sfx_tap_log = {}
    local td = sdk.find_type_definition("via.wwise.WwiseContainer")
    if not td then return end
    for _, sig in ipairs({
        "trigger(System.UInt32)",
        "trigger(System.UInt32, via.GameObject)",
        "trigger(System.UInt32, via.GameObject, via.GameObject)",
        "trigger(System.UInt32, via.vec3, via.GameObject)",
        "triggerLogLess(System.UInt32, via.GameObject, via.GameObject)",
        "triggerLogLess(System.UInt32, via.vec3, via.GameObject)",
    }) do
        local m = nil
        pcall(function() m = td:get_method(sig) end)
        if m then
            local this_sig = sig
            sdk.hook(m, function(args)
                pcall(function()
                    if S.sfx_tap_active ~= true then return end
                    -- args[2]=this, args[3]=id, args[4]=go/pos (per this file's ActionManager hook layout)
                    local id = tonumber(sdk.to_int64(args[3])) or -1
                    if id < 0 then return end
                    local goname = ""
                    pcall(function()
                        local g = sdk.to_managed_object(args[4])
                        if g and g.call then goname = tostring(g:call("get_Name")) end
                    end)
                    local t = S.sfx_tap_log
                    t[#t + 1] = { t = os.clock(), id = id, go = goname, sig = this_sig }
                    if #t > 500 then table.remove(t, 1) end
                end)
            end, function(r) return r end)
        end
    end
end

-- ⭐ PAWN VOICE MUTE: while she's clinging to the griffin, block HER Wwise voice/SE triggers so the
-- landing jolt doesn't fire a hurt-grunt (Aurora: "sounds like being hurt, doesn't fit the mount").
-- Voice in RE Engine routes through via.wwise.WwiseContainer.trigger; we pre-hook the same methods the
-- sfx tap uses and SKIP_ORIGINAL when the container's owner GameObject is her and the mute is armed.
-- Scoped to her GO only (route3_pawn_go_addr) so the griffin + every other character are untouched.
function route3_install_pawn_voice_mute()
    if S.pawn_voice_mute_installed then return end
    S.pawn_voice_mute_installed = true
    local td = sdk.find_type_definition("via.wwise.WwiseContainer")
    if not td then return end
    for _, sig in ipairs({
        "trigger(System.UInt32)",
        "trigger(System.UInt32, via.GameObject)",
        "trigger(System.UInt32, via.GameObject, via.GameObject)",
        "trigger(System.UInt32, via.vec3, via.GameObject)",
        "triggerLogLess(System.UInt32, via.GameObject, via.GameObject)",
        "triggerLogLess(System.UInt32, via.vec3, via.GameObject)",
    }) do
        local m = nil
        pcall(function() m = td:get_method(sig) end)
        if m then
            sdk.hook(m,
                function(args)
                    local skip = false
                    pcall(function()
                        if S.route3_pawn_voice_mute ~= true then return end
                        local target = S.route3_pawn_go_addr
                        if not target then return end
                        local this = sdk.to_managed_object(args[2])
                        if not this then return end
                        local go = this:call("get_GameObject")
                        if go and go:get_address() == target then skip = true end
                    end)
                    if skip then return sdk.PreHookResult.SKIP_ORIGINAL end
                    return sdk.PreHookResult.CALL_ORIGINAL
                end,
                function(r) return r end)
        end
    end
end

function route3_sfx_tap_tick()
    route3_install_pawn_voice_mute()
    route3_install_sfx_tap()
    S.sfx_tap_active = S.mounted == true   -- record whenever mounted (cheap: table appends only)
    -- auto-dump a window when a grab / dive bomb / swoop ENDS (that's when Aurora heard the double)
    local busy = (griffin_grab_active and griffin_grab_active()) or (griffin_divebomb_active and griffin_divebomb_active())
    if busy then S.sfx_tap_busy_at = os.clock() end
    if (not busy) and S.sfx_tap_busy_at and (os.clock() - S.sfx_tap_busy_at) > 1.5 then
        local since = S.sfx_tap_busy_at - 6.0   -- the action + lead-in
        S.sfx_tap_busy_at = nil
        local out, prev = {}, {}
        for _, e in ipairs(S.sfx_tap_log or {}) do
            if e.t >= since then
                local dbl = prev[e.id] and (e.t - prev[e.id]) < 0.3
                prev[e.id] = e.t
                out[#out + 1] = string.format("%.3f id=%d go=%s%s", e.t, e.id, tostring(e.go), dbl and "  <== DOUBLE (<0.3s)" or "")
            end
        end
        pcall(function() json.dump_file(MOD .. "_sfx_tap.json", { time = os.date("%H:%M:%S"), events = out }) end)
        S.sfx_tap_log = {}
    end
end

-- ⭐⭐ NICK'S SOUND ROUTE (2026-08-08, the metallic hit 1075806062 stayed SILENT through
-- triggerLogLess on every emitter): his SoundPlayer -- where Aurora previewed the id -- does
-- NOT post a bare id. It finds the SoundTriggerInfo INSTANCE inside a body's
-- WwiseContainerApp user-data and triggers a BUILT RequestInfo through that same body's
-- soundlib.SoundContainer. Ported verbatim (depend-never-modify: reimplemented inline).
-- Scans player -> griffin -> the struck foe for the id's home bank; caches the find.
function route3_wwise_trigger_nick(id, target_go)
    id = math.floor(tonumber(id) or 0)
    if id <= 0 then return false end
    S.route3_sndfind = S.route3_sndfind or {}
    local hit = S.route3_sndfind[id]
    local function scan(go2)
        if not go2 then return nil end
        local found = nil
        pcall(function()
            local wwise = get_component(go2, "app.WwiseContainerApp")
            local udl = wwise and wwise._UserDataList
            if not udl then return end
            for ui = 0, udl:get_Count() - 1 do
                local inner = udl[ui] and udl[ui]._UserDataList
                if inner then
                    for ti = 0, inner:get_Count() - 1 do
                        local tl = inner[ti] and inner[ti]._TriggerInfoList
                        if tl then
                            for i = 0, tl:get_Count() - 1 do
                                local trig = tl[i]
                                if trig and tonumber(trig._TriggerId) == id then
                                    pcall(function() trig = trig:add_ref() end)
                                    found = { go = go2, trig = trig }
                                    return
                                end
                            end
                        end
                        if found then return end
                    end
                end
                if found then return end
            end
        end)
        return found
    end
    if not hit then
        local _, ggo = reacquire_griffin()
        hit = scan(char_go(get_player())) or scan(ggo) or scan(target_go)
        if hit then S.route3_sndfind[id] = hit end
    end
    if not hit then
        S.route3_audio_trigger_status = string.format("nick-route: id %d not in player/griffin/foe banks", id)
        return false
    end
    local ok = false
    pcall(function()
        local sc = get_component(hit.go, "soundlib.SoundContainer")
        if not sc then return end
        local tgt = target_go or hit.go
        local ri = sc:call("createRequestInfo(soundlib.SoundTriggerInfo, via.GameObject, via.GameObject, System.UInt32, System.Boolean, System.Boolean, System.UInt32, via.simplewwise.CallbackType, System.Action`1<soundlib.SoundManager.RequestInfo>, System.Action`1<soundlib.SoundManager.RequestInfo>, System.Action`1<soundlib.SoundManager.RequestInfo>, System.Action`1<soundlib.SoundManager.RequestInfo>)",
            hit.trig, tgt, tgt, hit.trig._OffsetJointHash, false, false, 0, 0, nil, nil, nil, nil)
        if ri then
            ri = ri:add_ref()
            ri["<Container>k__BackingField"] = sc
            sc:call("trigger(soundlib.SoundManager.RequestInfo)", ri)
            ok = true
        end
    end)
    S.route3_audio_trigger_status = string.format("nick-route id %d ok=%s bank=%s",
        id, tostring(ok), tostring(go_name(hit.go) or "?"))
    return ok
end

function route3_play_wwise_trigger_id(id, label, target_go)
    local wc = route3_wwise_container()
    local _, go = reacquire_griffin()
    -- optional emitter override (2026-08-08: trigger 1075806062 posted silently on the
    -- GRIFFIN's audio object -- ids from player/combat banks need a PLAYER-adjacent emitter;
    -- the rider sits on her, so the position is the same either way)
    if target_go then go = target_go end
    id = math.floor(tonumber(id) or 0)
    if not (wc and go and id > 0) then
        S.route3_audio_trigger_status = "play failed: need WwiseContainer + trigger id"
        status(S.route3_audio_trigger_status)
        return false
    end
    local ok = false
    pcall(function()
        ok = wc:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)", id, go, go) == true
    end)
    if not ok then
        pcall(function()
            local pos = transform_pos(go)
            ok = wc:call("triggerLogLess(System.UInt32, via.vec3, via.GameObject)", id, pos, go) == true
        end)
    end
    S.route3_audio_trigger_status = string.format("%s trigger %d ok=%s", tostring(label or "wwise"), id, tostring(ok == true))
    status(S.route3_audio_trigger_status)
    return ok == true
end

function route3_play_ride_audio(name, id)
    if C.route3_flight_audio_enabled ~= true then
        S.route3_audio_ride_status = "audio disabled"
        return false
    end
    local ok = route3_play_wwise_trigger_id(id, name)
    S.route3_audio_ride_status = tostring(name or "audio") .. "=" .. tostring(ok == true) .. " id=" .. tostring(math.floor(tonumber(id) or 0))
    return ok == true
end

function route3_flight_audio_tick()
    if C.route3_flight_audio_enabled ~= true then
        S.route3_audio_ride_status = "audio disabled"
        return false
    end
    if not (S.route3_proxy_ride_active == true and S.airborne == true) then
        S.route3_audio_soar_started = false
        return false
    end
    if route3_takeoff_lock_active() then return false end

    local now = os.clock()
    if C.route3_audio_soar_after_takeoff == true and S.route3_audio_soar_started ~= true then
        S.route3_audio_soar_started = true
        S.route3_audio_last_flap = now
        return route3_play_ride_audio("soar", C.route3_audio_soar_trigger_id)
    end

    local moving = math.abs(tonumber(S.last_character_root_forward) or 0.0)
        + math.abs(tonumber(S.last_character_root_side) or 0.0)
        + math.abs(tonumber(S.last_character_root_vertical) or 0.0)
        + math.abs(tonumber(S.last_drive_axis_x) or 0.0) > 0.2
    if C.route3_audio_flap_loop_enabled == true
        and (C.route3_audio_flap_only_when_moving ~= true or moving)
        and now - (tonumber(S.route3_audio_last_flap) or 0.0) >= math.max(0.5, tonumber(C.route3_audio_flap_interval) or 2.4) then
        S.route3_audio_last_flap = now
        route3_trigger_wing_flap_visual()
        return route3_play_ride_audio("flap", C.route3_audio_flap_trigger_id)
    end

    if C.route3_audio_wind_on_sprint == true
        and S.route3_flap_phase ~= "soar"   -- the soar (dush) anims carry their OWN baked SFX
        and S.last_character_root_move_run == true
        and moving
        and now - (tonumber(S.route3_audio_last_wind) or 0.0) >= math.max(1.0, tonumber(C.route3_audio_wind_interval) or 4.0) then
        S.route3_audio_last_wind = now
        return route3_play_ride_audio("wind", C.route3_audio_wind_trigger_id)
    end
    return false
end

local function pin_rider_to_griffin()
    if not (C.enabled and S.mounted) then return end
    if S.native_climb_mount and not C.drive_rider_transform then return end
    if not (C.pin_rider_while_mounted or C.late_pin_rider) then return end
    if C.pin_rider_airborne_only and not S.airborne then return end
    if (not C.pin_rider_while_mounted) and C.late_pin_airborne_only and not S.airborne then return end
    local _, go = reacquire_griffin()
    local pgo = char_go(get_player())
    if not (go and pgo) then return end
    local gpos = transform_pos(go)
    if not gpos then return end
    local yaw = S.heading_yaw or yaw_from_transform(go) or 0.0
    local fwd = { x = math.sin(yaw), y = 0.0, z = math.cos(yaw) }
    local right = { x = math.cos(yaw), y = 0.0, z = -math.sin(yaw) }
    local up = { x = 0.0, y = 1.0, z = 0.0 }
    apply_rider_transform(rider_world_pos(gpos, right, up, fwd), C.lock_player_rotation and make_quat_yaw(yaw) or nil)
    if C.hard_lock_rider then set_rider_hard_lock(true) end
end

local function reapply_drive_transform()
    if griffin_predation_window_active() then return end
    if griffin_rise_fc_window_active() then return end   -- FC-LIFT STANDDOWN (third writer)
    if not (C.enabled and S.mounted and S.drive_pos) then return end
    local heading_reapply = C.heading_transform_drive_enabled == true and C.heading_transform_reapply_on_frame == true and S.native_climb_mount == true and S.airborne ~= true
    local route3_air_reapply = C.route3_flight_reapply_on_frame == true and S.route3_proxy_ride_active == true and S.airborne == true
    if not (C.apply_drive_on_frame == true or heading_reapply or route3_air_reapply) then return end
    local heading_ch, heading_go = reacquire_griffin()
    if route3_air_reapply and heading_go then
        local pos = S.route3_air_pos or S.drive_pos
        local rot = S.route3_air_rot or S.drive_rot
        local ok = route3_apply_air_transform(heading_ch, heading_go, pos, rot)
        S.last_heading_transform_reapply = ok == true
        S.last_griffin_set_ok = ok == true
        return
    end
    if heading_reapply and heading_go then
        S.last_heading_transform_reapply = set_transform(heading_go, S.drive_pos, S.drive_rot)
        S.last_griffin_set_ok = S.last_heading_transform_reapply
        return
    end
    if not drive_writes_griffin_transform() then return end
    apply_griffin_transform(S.drive_pos, S.drive_rot)
    if not C.drive_rider_transform then return end
    local _, go = reacquire_griffin()
    if not go then return end
    local gpos = transform_pos(go) or S.drive_pos
    local yaw = S.heading_yaw or yaw_from_transform(go) or 0.0
    local fwd = { x = math.sin(yaw), y = 0.0, z = math.cos(yaw) }
    local right = { x = math.cos(yaw), y = 0.0, z = -math.sin(yaw) }
    local up = { x = 0.0, y = 1.0, z = 0.0 }
    apply_rider_transform(rider_world_pos(gpos, right, up, fwd), C.lock_player_rotation and make_quat_yaw(yaw) or nil)
end

local function get_griffin_flight_control(go)
    local fc = get_component(go, "app.FlightControl")
    if not fc then
        local ch = S.griffin
        pcall(function() fc = ch and ch:get_field("<FlightControl>k__BackingField") end)
    end
    return fc
end

local function call_flight_control(fc, name, ...)
    local ok = false
    local err = nil
    local args = { ... }
    local results = { pcall(function() return fc and fc:call(name, table.unpack(args)) end) }
    ok = results[1] == true
    if not ok then err = results[2] end
    return ok, err
end

local function set_flight_control_field(fc, name, value)
    local field = nil
    pcall(function()
        local td = fc and fc:get_type_definition()
        field = td and td:get_field(name)
    end)
    if not field then return false end

    local ok = false
    pcall(function() fc:set_field(name, value); ok = true end)
    return ok
end

local function summarise_flight_control_hits(hits)
    local field_count = 0
    local calls = {}
    local fsm = nil
    for _, hit in ipairs(hits or {}) do
        local text = tostring(hit)
        if text:sub(1, 6) == "field:" then
            field_count = field_count + 1
        elseif text:sub(1, 5) == "call:" then
            calls[#calls + 1] = text:gsub("^call:", "")
        elseif text:sub(1, 4) == "fsm:" then
            fsm = text:gsub("^fsm:", "")
        end
    end
    local out = {}
    if fsm then out[#out + 1] = "fsm=" .. fsm end
    if field_count > 0 then out[#out + 1] = "fields=" .. tostring(field_count) end
    if #calls > 0 then out[#out + 1] = "calls=" .. table.concat(calls, "|") end
    if #out == 0 then return "no accepted FlightControl writes/calls" end
    return table.concat(out, " ")
end

-- =====================================================================================
-- FC-LIFT (2026-07-26) -- the fix for "node + movement = CTD".
--
-- ROOT CAUSE, verified in-game three times (07-24 twice, 07-26 LoopTheLoop): the crash is
-- NOT the node. Firing Fly.* nodes airborne+standalone is safe via either door. The killer
-- is TWO WRITERS ON ONE via.Transform -- our route3_apply_air_transform setting absolute
-- position every frame, against app.FlightControl integrating its OWN altitude onto the
-- same body. Held still they agree (safe). MOVING makes our y and FC's y diverge -> AV.
-- 07-26 tape: node fired clean, ran 3 ticks at observeDelta=3.6/tick, died in the movement
-- frames. Textbook.
--
-- THE FIX: during a node window there is exactly ONE writer. Our transform drive stands
-- down (see the guard in route3_seat_transform_drive_tick) and we move her by changing
-- what FC BELIEVES -- ramping its _AirTargetPosY -- instead of out-writing it. That is the
-- standing law from [[griffin-flightcontrol-altitude-authority]]: never out-write FC.
--
-- The write core below is recovered verbatim-in-spirit from flight_control_drive_tick,
-- which the 07-24 slim-down orphaned and deleted (git tag devtools-last-intact:16249).
-- Only the altitude-target half is restored -- not the 40-call scattergun.
--
-- ⚠ SAFETY IS WELL-SUPPORTED; EFFICACY IS THE OPEN QUESTION. If FC stops integrating while
-- a node is force-fired she will play the anim and not move. That is a null result, not a
-- crash. route3_rise_fc_pump_update is the first rung of the fallback ladder.
-- =====================================================================================

function griffin_rise_fc_window_active(now)
    -- A/B CONTRACT: with C.route3_rise_fc_lift false this ALWAYS returns false, so every
    -- caller behaves exactly as it does today. One flag, zero behavioural difference off.
    if C.route3_rise_fc_lift ~= true then return false end
    return (tonumber(S.route3_rise_fc_until) or 0.0) > (tonumber(now) or os.clock())
end

function griffin_rise_fc_latch_write(open)
    -- CRASH LATCH. If the game dies mid-window this file is left saying open=true, and the
    -- load-time check disarms fc-lift on the next launch. json.dump_file flushes on write,
    -- which is the same property the crash tapes rely on. No os.remove (path-prefix trap).
    pcall(function()
        json.dump_file(MOD .. "_fc_lift_latch.json",
            { open = (open == true), time = os.date("%H:%M:%S") })
    end)
end

function route3_rise_fc_lift_begin(dir, dur, now, leaf)
    if C.route3_rise_fc_lift ~= true then return false end
    local _, go = reacquire_griffin()
    local pos = go and transform_pos(go)
    local y0 = tonumber(pos and pos.y)
    if not y0 then S.route3_rise_fc_status = "no griffin position"; return false end
    local cap = math.abs(tonumber(C.route3_rise_fc_cap) or 2.5)
    local sign = (tonumber(dir) or 1.0) < 0.0 and -1.0 or 1.0
    S.route3_rise_fc_y0 = y0
    S.route3_rise_fc_target_y = y0 + sign * cap
    S.route3_rise_fc_t0 = now
    S.route3_rise_fc_dur = math.max(0.2, tonumber(dur) or 1.0)
    S.route3_rise_fc_until = now + S.route3_rise_fc_dur + math.max(0.0, tonumber(C.route3_rise_fc_tail) or 0.35)
    S.route3_rise_fc_peak = 0.0
    -- NODE IS THE SOLE FLAPPER: our resident L1 flap loop beating alongside the node's own
    -- flap is the "double wing flap" bug. Clear the overlay and block the air visuals for
    -- the window (design memo, fix B).
    pcall(function() route3_flap_clear_overlay() end)
    S.route3_air_visual_block_until = math.max(tonumber(S.route3_air_visual_block_until) or 0.0, S.route3_rise_fc_until)
    griffin_rise_fc_latch_write(true)
    S.route3_rise_fc_status = string.format("window OPEN %s %.1fm over %.2fs (transform drive STOOD DOWN)",
        tostring(leaf or "?"), sign * cap, S.route3_rise_fc_dur)
    pcall(function() griffin_rise_crash_mark("FC-LIFT window OPEN " .. tostring(S.route3_rise_fc_status)) end)
    return true
end

function route3_rise_fc_lift_end(reason)
    if (tonumber(S.route3_rise_fc_until) or 0.0) <= 0.0 then return false end
    S.route3_rise_fc_until = 0.0
    -- ⛔ RE-SEED BEFORE THE DRIVE RESUMES. S.route3_air_pos is stale by exactly however far
    -- FC flew her during the window; letting the transform drive wake on it snaps her back
    -- to where the burst started (design memo, fix B).
    pcall(function()
        local _, go = reacquire_griffin()
        local live = go and transform_pos(go)
        if live then S.route3_air_pos = live end
    end)
    if type(S.base_owner) == "table" and S.base_owner.name == "rise" then S.base_owner = nil end
    -- A native node is allowed to borrow FlightControl while our transform drive is stood down,
    -- but the borrow must end with the node.  Do not cut it while a longer attack window still
    -- owns the body; mark it for the common mounted-FC guard instead.
    S.route3_fc_sanitise_pending = tostring(reason or "fc-lift ended")
    griffin_rise_fc_latch_write(false)
    S.route3_rise_fc_status = string.format("window closed (%s) -- FC moved her %.2fm",
        tostring(reason or "done"), tonumber(S.route3_rise_fc_peak) or 0.0)
    pcall(function() griffin_rise_crash_mark("FC-LIFT window CLOSED " .. tostring(S.route3_rise_fc_status)) end)
    return true
end

function route3_rise_fc_lift_tick()
    local now = os.clock()
    if not griffin_rise_fc_window_active(now) then
        if (tonumber(S.route3_rise_fc_until) or 0.0) > 0.0 then route3_rise_fc_lift_end("window elapsed") end
        return false
    end
    local ch, go = reacquire_griffin()
    if not (ch and go) then route3_rise_fc_lift_end("griffin lost"); return false end
    -- Stop the FC-only lease when the loop node really releases. Previously the ordinary
    -- transform drive ignored ascend/descend for the lease's full timer even if the animation
    -- had already ended, which made descend appear intermittently dead after LoopTheLoop.
    if now > (tonumber(S.route3_rise_fc_t0) or now) + 0.2
        and not griffin_node_lockout_active(now) then
        route3_rise_fc_lift_end("node released")
        return false
    end
    local fc = get_griffin_flight_control(go)
    if not fc then
        S.route3_rise_fc_status = "no app.FlightControl -- cannot lift"
        route3_rise_fc_lift_end("no FlightControl")
        return false
    end

    local y0 = tonumber(S.route3_rise_fc_y0) or 0.0
    local ty_target = tonumber(S.route3_rise_fc_target_y) or y0
    local dur = math.max(0.2, tonumber(S.route3_rise_fc_dur) or 1.0)
    local frac = math.min(1.0, math.max(0.0, (now - (tonumber(S.route3_rise_fc_t0) or now)) / dur))
    local eased = frac * frac * (3.0 - 2.0 * frac)          -- smoothstep, same easing the quick burst uses
    local ty = y0 + (ty_target - y0) * eased

    -- ONE WRITER. Both doors, because the 07-24 recovery shows the field route and the
    -- setter route are not equally available on every build.
    local hits = {}
    if set_flight_control_field(fc, "_AirTargetPosY", ty) then hits[#hits + 1] = "field:_AirTargetPosY" end
    if call_flight_control(fc, "set_AirTargetPosY(System.Single)", ty) then hits[#hits + 1] = "call:set_AirTargetPosY" end
    if C.route3_rise_fc_pump_update == true then
        -- FALLBACK RUNG 1 (only if she plays the anim and does not move): ask FC to
        -- integrate now rather than waiting for its own schedule.
        if call_flight_control(fc, "updateFlightAttitudeBeforePosition()") then hits[#hits + 1] = "call:updateAttitude" end
        if call_flight_control(fc, "updatePosition()") then hits[#hits + 1] = "call:updatePosition" end
    end

    local live = transform_pos(go)
    local moved = math.abs((tonumber(live and live.y) or y0) - y0)
    if moved > (tonumber(S.route3_rise_fc_peak) or 0.0) then S.route3_rise_fc_peak = moved end
    S.route3_rise_fc_status = string.format("LIFTING %.0f%% target=%.2f moved=%.2fm [%s]",
        frac * 100.0, ty, moved, #hits > 0 and table.concat(hits, "+") or "NO WRITE ACCEPTED")
    return true
end

native_flight_control_probe_tick = function(now)
    if C.route3_native_fc_probe_enabled ~= true then
        S.route3_native_fc_probe_status = "(off)"
        return false
    end
    if S.airborne ~= true then
        S.route3_native_fc_probe_status = "waiting for flight"
        return false
    end
    now = now or os.clock()
    local interval = math.max(0.05, tonumber(C.route3_native_fc_probe_interval) or 0.25)
    if now - (tonumber(S.route3_native_fc_probe_last) or 0.0) < interval then return true end
    S.route3_native_fc_probe_last = now

    local ch, go = reacquire_griffin()
    local fc = get_griffin_flight_control(go)
    if not fc then
        S.route3_native_fc_probe_status = "fc missing"
        return false
    end

    local hits = {}
    local gpos = transform_pos(go) or S.drive_pos
    local yaw = yaw_from_transform(go) or tonumber(S.heading_yaw) or 0.0
    local fwd = { x = math.sin(yaw), y = 0.0, z = math.cos(yaw) }
    local dist = math.max(0.0, tonumber(C.route3_native_fc_probe_target_distance) or 4.0)
    local height = tonumber(C.route3_native_fc_probe_target_height) or 0.0
    local target = make_vec3(
        (tonumber(gpos and gpos.x) or 0.0) + fwd.x * dist,
        (tonumber(gpos and gpos.y) or 0.0) + height,
        (tonumber(gpos and gpos.z) or 0.0) + fwd.z * dist
    )

    if C.route3_native_fc_probe_set_hover == true then
        for _, field in ipairs({ "_IsHover", "<IsHoverOld>k__BackingField" }) do
            if set_flight_control_field(fc, field, true) then hits[#hits + 1] = "field:" .. field end
        end
        for _, method in ipairs({ "set_IsHover(System.Boolean)", "set_IsHoverOld(System.Boolean)" }) do
            local ok = call_flight_control(fc, method, true)
            if ok then hits[#hits + 1] = "call:" .. method end
        end
    end

    for _, field in ipairs({ "<AirHoverMoveTargetPos>k__BackingField", "AirHoverMoveTargetPos" }) do
        if set_flight_control_field(fc, field, target) then hits[#hits + 1] = "field:" .. field end
    end
    for _, method in ipairs({
        "set_AirHoverMoveTargetPos(System.Nullable`1<via.vec3>)",
        "set_AirHoverMoveTargetPos(via.vec3)",
    }) do
        local ok = call_flight_control(fc, method, target)
        if ok then hits[#hits + 1] = "call:" .. method end
    end

    local x = tonumber(S.last_drive_axis_x) or 0.0
    local z = tonumber(S.last_drive_axis_z) or 0.0
    local ok_find = call_flight_control(fc, "findHoverMoveTargetPos(System.Single, via.Float2)", dist, make_float2(x, z))
    if ok_find then hits[#hits + 1] = "call:findHoverMoveTargetPos" end

    if C.route3_native_fc_probe_update_hover == true then
        for _, method in ipairs({ "updateHoverAttitude()", "updateMotionScalingHoverUp()" }) do
            local ok = call_flight_control(fc, method)
            if ok then hits[#hits + 1] = "call:" .. method end
        end
    end

    clear_griffin_hate()
    clear_griffin_targets()
    S.route3_native_fc_probe_status = string.format(
        "fc wake hits=%d hover=%s target=%s update=%s",
        #hits,
        C.route3_native_fc_probe_set_hover == true and "YES" or "NO",
        string.format("(%.1f %.1f %.1f)", tonumber(target.x) or 0.0, tonumber(target.y) or 0.0, tonumber(target.z) or 0.0),
        C.route3_native_fc_probe_update_hover == true and "YES" or "NO"
    )
    if #hits > 0 then
        S.last_flight_control = summarise_flight_control_hits(hits)
        S.last_flight_control_ok = true
    end
    return #hits > 0
end

local function yn(value)
    return value and "YES" or "NO"
end

local function compact_vec3(v)
    if not v then return "nil" end
    return string.format("(%.1f %.1f %.1f)", tonumber(v.x) or 0.0, tonumber(v.y) or 0.0, tonumber(v.z) or 0.0)
end

local OBSERVE_LOG_PATH = MOD .. "_observe.txt"

local function bool01(v)
    return v and "1" or "0"
end

local function write_observe_log_line(line)
    local ok, err = pcall(function()
        local f = io.open(OBSERVE_LOG_PATH, "a")
        if not f then error("open failed") end
        f:write(line, "\n")
        f:close()
    end)
    if ok then
        S.native_observe_log_lines = (tonumber(S.native_observe_log_lines) or 0) + 1
        S.native_observe_log_status = "writing " .. tostring(S.native_observe_log_lines) .. " lines"
    else
        S.native_observe_log_status = "write failed: " .. tostring(err)
    end
    return ok
end

local function clear_observe_log()
    local ok, err = pcall(function()
        local f = io.open(OBSERVE_LOG_PATH, "w")
        if not f then error("open failed") end
        f:write("time,event,mounted,climb,flying,airborne,axisX,axisZ,rootF,rootSide,axisMode,run,turn,rootMoved,rootDelta,rootError,animState,animKey,animPlayed,animStopped,animError,griffinMoved,observeDelta,headingYaw,actualYaw,pos,fc,nav,fsm,griffinAction\n")
        f:close()
    end)
    if ok then
        S.native_observe_log_lines = 0
        S.native_observe_log_status = "cleared"
        status("observe log cleared: " .. OBSERVE_LOG_PATH)
    else
        S.native_observe_log_status = "clear failed: " .. tostring(err)
    end
    return ok
end

local function csv_clean(value)
    local s = tostring(value or "")
    s = s:gsub("[\r\n]", " "):gsub(",", ";")
    return s
end

append_observe_snapshot = function(event, ch, go, gpos, now)
    if C.native_observer_log_enabled ~= true then return false end
    now = tonumber(now) or os.clock()
    local active = S.mounted == true or S.native_climb_mount == true
        or math.abs(tonumber(S.last_drive_axis_x) or 0.0) > 0.01
        or math.abs(tonumber(S.last_drive_axis_z) or 0.0) > 0.01
    if not active and event == "tick" then return false end
    if event == "tick" and now - (tonumber(S.native_observe_log_last_clock) or 0.0) < 0.25 then return false end
    S.native_observe_log_last_clock = now

    local actual_yaw = yaw_from_transform(go)
    local pos = gpos or transform_pos(go)
    local line = table.concat({
        string.format("%.3f", now),
        csv_clean(event or "tick"),
        bool01(S.mounted),
        bool01(S.native_climb_mount),
        bool01(S.flying),
        bool01(S.airborne),
        string.format("%.3f", tonumber(S.last_drive_axis_x) or 0.0),
        string.format("%.3f", tonumber(S.last_drive_axis_z) or 0.0),
        string.format("%.3f", tonumber(S.last_character_root_forward) or 0.0),
        string.format("%.3f", tonumber(S.last_character_root_side) or 0.0),
        tostring(math.floor(tonumber(C.character_root_move_axis_mode) or 0)),
        bool01(S.last_character_root_move_run),
        bool01(S.last_character_root_turn),
        bool01(S.last_character_root_move_moved),
        string.format("%.3f", tonumber(S.last_character_root_move_delta) or 0.0),
        csv_clean(S.last_character_root_move_error),
        csv_clean(S.last_root_motion_state),
        csv_clean(S.last_root_motion_key),
        bool01(S.last_root_motion_played),
        bool01(S.last_root_motion_stopped),
        csv_clean(S.last_root_motion_error),
        bool01(S.native_observe_moved),
        string.format("%.3f", tonumber(S.native_observe_delta) or 0.0),
        string.format("%.3f", tonumber(S.heading_yaw) or 0.0),
        actual_yaw and string.format("%.3f", actual_yaw) or "nil",
        csv_clean(compact_vec3(pos)),
        csv_clean(S.native_observe_fc),
        csv_clean(S.native_observe_nav),
        csv_clean(S.last_fsm_node),
        csv_clean(S.last_griffin_action),
    }, ",")
    return write_observe_log_line(line)
end

local function try_call_value(obj, name)
    local out = nil
    pcall(function() out = obj and obj:call(name) end)
    return out
end

local function try_field_value(obj, name)
    local out = nil
    pcall(function() out = obj and obj:get_field(name) end)
    return out
end

local function first_observed_value(obj, names)
    for _, name in ipairs(names or {}) do
        local value = nil
        if name:sub(1, 5) == "call:" then
            value = try_call_value(obj, name:sub(6))
        else
            value = try_field_value(obj, name)
        end
        if value ~= nil then return value, name end
    end
    return nil, nil
end

local function observe_bool(obj, names)
    local value = first_observed_value(obj, names)
    if value == nil then return "?" end
    return yn(value == true)
end

local function native_observe_tick(ch, go, gpos, now)
    if C.native_observer_enabled ~= true then return end
    now = tonumber(now) or os.clock()
    if now - (tonumber(S.native_observe_last_clock) or 0.0) < 0.2 then return end
    S.native_observe_last_clock = now

    if gpos and S.native_observe_last_pos then
        local dsq = distance_sq(gpos, S.native_observe_last_pos)
        S.native_observe_delta = dsq and math.sqrt(dsq) or 0.0
        S.native_observe_moved = (tonumber(S.native_observe_delta) or 0.0) > 0.01
    else
        S.native_observe_delta = 0.0
        S.native_observe_moved = false
    end
    if gpos then
        S.native_observe_last_pos = { x = tonumber(gpos.x) or 0.0, y = tonumber(gpos.y) or 0.0, z = tonumber(gpos.z) or 0.0 }
    end

    local fc = get_griffin_flight_control(go)
    if fc then
        local target = first_observed_value(fc, {
            "call:get_TargetPosition",
            "<TargetPosition>k__BackingField",
            "TargetPosition",
        })
        local move = first_observed_value(fc, {
            "FlightMoveVector",
            "HoveringAttitudeMoveVec",
            "ISMoveVector",
            "NowISMoveVector",
        })
        local fly_status = first_observed_value(fc, {
            "call:get_FlyStatus",
            "FlyStatus",
            "_FlyStatus",
            "<FlyStatus>k__BackingField",
        })
        S.native_observe_fc = string.format("fc=YES target=%s move=%s fly=%s",
            yn(target ~= nil),
            yn(move ~= nil),
            tostring(fly_status or "?"))
        S.native_observe_detail = string.format("target=%s move=%s", compact_vec3(target), compact_vec3(move))
    else
        S.native_observe_fc = "fc=NO"
        S.native_observe_detail = "(no FlightControl)"
    end

    local nav = get_navigation_ai(ch)
    local ctrl = get_navigation_controller(ch)
    if nav or ctrl then
        local nav_target = nil
        if nav then
            nav_target = first_observed_value(nav, {
                "call:get_NavigationPos",
                "NavigationPos",
                "<NavigationPos>k__BackingField",
                "TargetPosition",
                "<TargetPosition>k__BackingField",
            })
        end
        S.native_observe_nav = string.format("nav=YES stop=%s req=%s target=%s ctrl=%s",
            nav and observe_bool(nav, { "call:get_IsStopCalled", "IsStopCalled", "<IsStopCalled>k__BackingField", "isStopCalled" }) or "?",
            nav and observe_bool(nav, { "call:get_IsRequestNow", "IsRequestNow", "<IsRequestNow>k__BackingField", "isRequestNow" }) or "?",
            yn(nav_target ~= nil),
            yn(ctrl ~= nil))
    else
        S.native_observe_nav = "nav=NO"
    end
end

local function route3_seat_transform_drive_tick(ch, go, gpos, x, z, ascend, descend, input)
    if griffin_predation_window_active() then
        S.last_character_root_move_error = "(native predation owns transform)"
        return false
    end
    -- ⭐ FC-LIFT STANDDOWN. The ONE line that fixes "node + movement = CTD": while a node
    -- window is open we are not a writer at all -- FlightControl owns the body alone and we
    -- steer it by target instead. Identical in shape to the predation guard above, and a
    -- no-op unless C.route3_rise_fc_lift is on.
    if griffin_rise_fc_window_active() then
        S.last_character_root_move_error = "(fc-lift node window owns transform)"
        return false
    end
    -- ⭐ GROUNDED SKID STANDDOWN (2026-08-07): the pounce lands AT the strike and slides the
    -- grounded body through the carve. The airborne branch already zeroes scripted deltas for a
    -- live dogfight, but the GROUND path has no such guard -- it would write the pre-skid
    -- position straight back over the slide every frame. Same shape as the two guards above.
    if type(S.route3_dogfight) == "table" and S.airborne ~= true then
        S.last_character_root_move_error = "(grounded dogfight skid owns transform)"
        return false
    end
    if not ((S.route3_seat_parented == true or S.route3_proxy_ride_active == true) and C.route3_transform_drive_after_parent == true) then return false end
    if not (ch and go and gpos) then
        S.last_character_root_move_call_ok = false
        S.last_character_root_move_moved = false
        S.last_character_root_move_delta = 0.0
        S.last_character_root_move_error = "route3 no griffin"
        return false
    end

    local side = tonumber(x) or 0.0
    local forward = tonumber(z) or 0.0
    local vertical = C.character_root_move_include_vertical and ((tonumber(ascend) or 0.0) - (tonumber(descend) or 0.0)) or 0.0
    if S.airborne ~= true and C.route3_ground_vertical_enabled ~= true then vertical = 0.0 end
    if C.character_root_move_invert_strafe then side = -side end
    if math.abs(side) < 0.05 then side = 0.0 end
    if math.abs(forward) < 0.05 then forward = 0.0 end
    if math.abs(vertical) < 0.05 then vertical = 0.0 end
    -- Aurora: no flying/soaring BACKWARDS -- clamp reverse input while airborne + flag the intent so the
    -- flap system won't kick into the soar pose when holding B backwards
    S.route3_going_backward = (S.airborne == true and (tonumber(forward) or 0.0) < -0.05)
    if S.airborne == true and C.route3_flight_no_reverse ~= false and forward < 0.0 then forward = 0.0 end
    -- ⭐ NO WALKING BACKWARDS ON THE GROUND (Aurora 2026-08-08: "make sure the griffin
    -- can't walk backwards -- right now it just slides backwards"). The reverse clamp
    -- above was AIRBORNE-ONLY, so on the ground a back-stick fed a negative forward
    -- straight into the transform step: she has no reverse-walk clip, so the body slid
    -- backwards in its idle/walk pose. Quadrupeds turn to face where they are going;
    -- steering still works because yaw is a separate axis (turn_input), so back-stick
    -- now simply contributes nothing to translation.
    if S.airborne ~= true and C.route3_ground_no_reverse ~= false and forward < 0.0 then
        forward = 0.0
    end

    local run = raw_gamepad_button_down(C.character_root_move_run_buttons)
        or button_on(input, C.character_root_move_run_button_flag)
        or (C.character_root_move_keyboard_run == true and keyboard_shift_down())
    if S.airborne == true and C.route3_allow_sprint ~= true then
        -- species capability: this creature does not sprint in flight
        run = false
    end
    -- ⭐ NODE LOCKOUT: refuse SOAR while a node owns her body. Aurora, 2026-08-04: "if you try and
    -- soar (hold B) while the animation is happening it crashes". Soar is not just a speed change --
    -- it drives the whole soar pose family (add_pose_U 5194, the bank-50 directional banking clips)
    -- onto L0, which is a second owner of a node-driven body. The paint gate in play_griffin_motion
    -- already refuses those clips; this stops the SPEED half too, so she doesn't silently accelerate
    -- out of the node's own trajectory while it plays.
    if C.route3_node_lockout_soar ~= false and run == true then
        local locked = false
        pcall(function() locked = griffin_node_lockout_active() == true end)
        if locked then run = false end
    end
    -- ⭐ GLOBAL PACE (2026-08-06, Aurora: "slow the griffin down a bit, in all movements --
    -- walking, running (especially), soaring, ascend and descend"). One scale over every
    -- locomotion step + an extra one on the sprint modes. NEW keys so the saved json can't
    -- clobber them back to 1.0. Special moves (quick burst, dives, dogfight) keep their own
    -- tuned trajectories and are deliberately NOT scaled here.
    local pace = math.max(0.1, math.min(2.0, tonumber(C.route3_move_speed_scale) or 1.0))
    -- ⭐ 08-12 SPD gene = REAL legs (Aurora): the bloodline scales every locomotion step --
    -- ground walk/run, cruise, soar -- through this one pace scalar. Published for the
    -- active companion body by the IV publisher.
    pcall(function()
        local st9 = _G.IrisIVState
        if st9 and tonumber(st9.spd) then pace = pace * tonumber(st9.spd) end
    end)
    local run_pace = pace * math.max(0.1, math.min(2.0, tonumber(C.route3_run_speed_scale) or 1.0))
    local step = math.max(0.0, tonumber(run and C.route3_transform_run_step or C.route3_transform_walk_step) or 0.04)
        * (run and run_pace or pace)
    local retained_vertical_step = nil
    if S.airborne == true then
        local cruise_step = math.max(0.0, tonumber(C.route3_flight_forward_step) or 0.19) * pace
        local soar_step = math.max(cruise_step, (tonumber(C.route3_flight_run_step) or 0.69) * run_pace)
        step = run and soar_step or cruise_step

        -- FLIGHT INERTIA: smooth the actual forward displacement, not merely the sprint
        -- multiplier. That gives us all three desired transitions: cruise -> soar, soar ->
        -- cruise, and forward release -> a real coast to zero instead of an instant stop.
        -- Special moves own their exact trajectories and must never inherit this residual.
        local quick_normal_rise = type(S.route3_quick_burst) == "table"
            and S.route3_quick_burst.phase == "rise"
            and S.route3_quick_burst.normal_vertical_drive == true
        local scripted = (type(S.route3_quick_burst) == "table" and not quick_normal_rise)
            or type(S.route3_swoop) == "table" or type(S.route3_divebomb) == "table"
            or type(S.route3_dogfight) == "table"
            or (type(S.route3_grab) == "table"
                and (S.route3_grab.phase == "dive" or S.route3_grab.phase == "pickup"))
            or S.route3_landing_requested == true
            or route3_takeoff_lock_active()
        local snow = os.clock()
        local prev_clock = tonumber(S.route3_soar_speed_clock)
        local stale = not prev_clock or (snow - prev_clock) > 0.25
        local sdt = stale and 0.0 or math.max(0.001, math.min(0.05, snow - prev_clock))
        S.route3_soar_speed_clock = snow
        local current_delta = stale and 0.0 or (tonumber(S.route3_flight_forward_delta) or 0.0)
        local target_delta = scripted and 0.0 or forward * step
        if scripted then
            current_delta = 0.0
        else
            local increasing = math.abs(target_delta) > math.abs(current_delta)
            local secs = increasing and math.max(0.05, tonumber(C.route3_soar_accel_secs) or 1.0)
                or math.max(0.05, tonumber(C.route3_soar_decel_secs) or 1.25)
            local max_change = math.max(0.001, soar_step) * sdt / secs
            if current_delta < target_delta then current_delta = math.min(target_delta, current_delta + max_change)
            elseif current_delta > target_delta then current_delta = math.max(target_delta, current_delta - max_change) end
            if math.abs(current_delta) < 0.001 and math.abs(target_delta) < 0.001 then current_delta = 0.0 end
        end
        S.route3_flight_forward_delta = current_delta
        S.route3_soar_coasting = run ~= true and math.abs(current_delta) > cruise_step * 1.05
        S.route3_soar_speed_status = string.format("%.2f -> %.2f", current_delta, target_delta)
        -- The rest of the proven transform-drive pipeline still multiplies axis * step.
        -- Re-express our retained displacement as an effective axis so collision, rider and
        -- animation bookkeeping continue to use one shared movement path.
        forward = step > 0.0001 and (current_delta / step) or 0.0

        -- VERTICAL SOAR INERTIA: the same retained-velocity treatment for sprint-climb
        -- and sprint-dive. Ordinary non-soar ascent/descent stays responsive, but entering
        -- soar eases to its tuned vertical speed and releasing it eases back to normal/zero.
        -- ⭐ VERTICAL PACE (2026-08-07, Aurora: "the ground walk is fine but the air
        -- ascend/descend is too fast now"): dedicated scales ON TOP of the global pace --
        -- one for normal flight climbs/dives, one for soar climbs/dives.
        local vscale = math.max(0.1, math.min(2.0, tonumber(C.route3_vertical_speed_scale) or 1.0))
        local svscale = math.max(0.1, math.min(3.0, tonumber(C.route3_soar_vertical_speed_scale) or 1.0))
        local base_vstep = math.max(0.0, tonumber(C.route3_flight_vertical_step) or 0.3) * pace
        local normal_vstep = base_vstep * vscale
        local ascend_vstep = (tonumber(C.route3_soar_ascend_step) or 0.0) * run_pace
        local descend_vstep = (tonumber(C.route3_soar_descend_step) or 0.0) * run_pace
        -- ⛔ fallback uses the UN-vscaled base (2026-08-07, Aurora: "too sluggish for soaring"
        -- -- with the soar steps unset, the fallback inherited the lowered NORMAL scale, so
        -- her normal-flight slider was silently dragging soar down with it)
        if ascend_vstep <= 0.0 then ascend_vstep = base_vstep end
        if descend_vstep <= 0.0 then descend_vstep = base_vstep end
        ascend_vstep = ascend_vstep * svscale
        descend_vstep = descend_vstep * svscale
        retained_vertical_step = normal_vstep
        if run and vertical > 0.0 then retained_vertical_step = ascend_vstep
        elseif run and vertical < 0.0 then retained_vertical_step = descend_vstep end

        local current_vdelta = stale and 0.0 or (tonumber(S.route3_flight_vertical_delta) or 0.0)
        local target_vdelta = scripted and 0.0 or vertical * retained_vertical_step
        local smoothing_vertical = run == true or math.abs(current_vdelta) > normal_vstep * 1.05
        if scripted then
            current_vdelta = 0.0
        elseif smoothing_vertical then
            local increasing = math.abs(target_vdelta) > math.abs(current_vdelta)
            local secs = increasing and math.max(0.05, tonumber(C.route3_soar_accel_secs) or 1.0)
                or math.max(0.05, tonumber(C.route3_soar_decel_secs) or 1.25)
            local vmax = math.max(0.001, normal_vstep, ascend_vstep, descend_vstep)
            local max_change = vmax * sdt / secs
            if current_vdelta < target_vdelta then current_vdelta = math.min(target_vdelta, current_vdelta + max_change)
            elseif current_vdelta > target_vdelta then current_vdelta = math.max(target_vdelta, current_vdelta - max_change) end
            if math.abs(current_vdelta) < 0.001 and math.abs(target_vdelta) < 0.001 then current_vdelta = 0.0 end
        else
            current_vdelta = target_vdelta
        end
        S.route3_flight_vertical_delta = current_vdelta
        S.route3_soar_vertical_status = string.format("%.2f -> %.2f", current_vdelta, target_vdelta)
        vertical = retained_vertical_step > 0.0001 and (current_vdelta / retained_vertical_step) or 0.0
    else
        S.route3_flight_forward_delta = 0.0
        S.route3_flight_vertical_delta = 0.0
        S.route3_soar_speed_clock = nil
        S.route3_soar_coasting = false
        S.route3_soar_speed_status = nil
        S.route3_soar_vertical_status = nil
    end

    local turn_input = C.character_root_turn_enabled and side or 0.0
    local strafe_input = C.character_root_strafe_enabled and side or 0.0
    local has_input = math.abs(turn_input) + math.abs(strafe_input) + math.abs(forward) + math.abs(vertical) > 0.0
    S.last_character_root_forward = forward
    S.last_character_root_side = strafe_input
    S.last_character_root_vertical = vertical
    S.last_character_root_has_input = has_input
    S.last_character_root_turn = math.abs(turn_input) > 0.0
    S.last_character_root_turn_input = turn_input
    S.last_character_root_animation_forward = false
    S.last_character_root_post_turn = false
    S.last_character_root_transform_turn = false
    S.route3_motion_blocked = false

    if S.airborne ~= true and (tonumber(S.route3_ground_jump_windup_until) or 0.0) > os.clock() then
        -- stand still for the jump wind-up: the leap clip starts from standing
        S.last_character_root_move_error = "(jump wind-up)"
        return true
    end

    if route3_takeoff_lock_active() then
        S.route3_takeoff_lock_status = string.format(
            "locked %.2fs",
            math.max(0.0, (tonumber(S.route3_takeoff_lock_until) or 0.0) - os.clock())
        )
        -- rise during the SECOND HALF of the takeoff flap: crouch first, then lift
        local rise = math.max(0.0, tonumber(C.route3_takeoff_rise_step) or 0.0)
        local lock_secs = math.max(0.1, tonumber(C.route3_takeoff_lock_seconds) or 3.0)
        local lock_elapsed = lock_secs - math.max(0.0, (tonumber(S.route3_takeoff_lock_until) or 0.0) - os.clock())
        if lock_elapsed < lock_secs * 0.5 then rise = 0.0 end
        if rise > 0.0 and S.route3_air_pos then
            S.route3_air_pos = make_position(
                tonumber(S.route3_air_pos.x) or 0.0,
                (tonumber(S.route3_air_pos.y) or 0.0) + rise,
                tonumber(S.route3_air_pos.z) or 0.0
            )
        end
        local hold_pos = S.route3_air_pos or transform_pos(go) or gpos
        local hold_rot = S.route3_air_rot or transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
        route3_apply_air_transform(ch, go, hold_pos, hold_rot)
        S.last_character_root_move_call_ok = true
        S.last_character_root_move_moved = false
        S.last_character_root_move_delta = 0.0
        S.last_character_root_move_error = "takeoff locked"
        S.last_character_root_forward = 0.0
        S.last_character_root_side = 0.0
        S.last_character_root_vertical = 0.0
        S.last_character_root_has_input = false
        S.route3_flight_status = "takeoff lock: " .. tostring(S.route3_takeoff_lock_status or "(active)")
        return true
    end
    route3_release_takeoff_lock_if_due(ch, go)

    if S.airborne == true and S.route3_landing_requested == true
        and os.clock() >= (tonumber(S.route3_landing_deadline) or math.huge) then
        return route3_cancel_landing(ch, go, "timeout")
    end

    if S.airborne == true
        and S.route3_landing_requested ~= true
        and type(S.route3_dogfight) ~= "table"   -- dogfight standdown: it owns its own floors
        and C.route3_air_ground_clearance_enabled == true then
        local hold_pos = S.route3_air_pos or transform_pos(go) or gpos
        local ground_hit = route3_ground_hit_under(go, hold_pos)
        local ground_y = tonumber(ground_hit and ground_hit.y)
        local clearance = math.max(0.0, tonumber(C.route3_air_ground_clearance) or 0.9)
        if ground_y and hold_pos and ((tonumber(hold_pos.y) or 0.0) - ground_y) < clearance then
            local rot = S.route3_air_rot or transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
            local lifted = make_position(tonumber(hold_pos.x) or 0.0, ground_y + clearance, tonumber(hold_pos.z) or 0.0)
            S.route3_air_pos = lifted
            S.route3_air_rot = rot
            route3_apply_air_transform(ch, go, lifted, rot)
            if not has_input then
                S.route3_flight_status = string.format("air clearance %.2fm", clearance)
                return true
            end
        end
    end

    -- LANDING owns the descent: route it through the RELIABLE no-input auto-descent path even when the
    -- stick is pushed, so steering can never stall the descent (Aurora). The stick is ignored while
    -- landing (option A) -- pick your spot before R3, or press R3 again to cancel back to flight.
    if (not has_input) or S.route3_landing_requested == true then
        if S.airborne == true then
            -- HOLD the air position even while coasting: without this, a playing
            -- clip's root motion owns the griffin whenever the stick is idle
            local hold_pos = S.route3_air_pos or transform_pos(go) or gpos
            local hold_rot = S.route3_air_rot or transform_rot(go) or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
            if S.route3_landing_requested == true then
                -- landing descends by itself, no stick required
                local d = math.max(0.02, tonumber(C.route3_landing_auto_step) or 0.15)
                -- LONG-REACH below-only ray in RENDER space: never blinded by
                -- being under the surface, never fooled by canopy, never off
                -- by a tile offset
                local rp2 = transform_render_pos(go)
                local hit = route3_cast_ground_below(
                    tonumber(rp2 and rp2.x) or tonumber(hold_pos.x) or 0.0,
                    tonumber(hold_pos.y) or 0.0,
                    tonumber(rp2 and rp2.z) or tonumber(hold_pos.z) or 0.0,
                    60.0, 120.0
                )
                local raw_gy = tonumber(hit and hit.y)
                local gy, cancelled = route3_landing_ground_or_cancel(ch, go, raw_gy, os.clock())
                if cancelled then return true end
                -- Do not descend during a transient ray miss. Holding for the
                -- grace window is safer than dropping several metres on stale Y.
                if raw_gy then
                    hold_pos = make_position(tonumber(hold_pos.x) or 0.0, (tonumber(hold_pos.y) or 0.0) - d, tonumber(hold_pos.z) or 0.0)
                end
                local snap = math.max(0.05, tonumber(C.route3_flight_landing_snap_height) or 0.35)
                S.route3_landing_debug = string.format(
                    "auto hold=%.2f gy=%s h=%s",
                    tonumber(hold_pos.y) or 0.0, tostring(gy),
                    gy and string.format("%.2f", (tonumber(hold_pos.y) or 0.0) - gy) or "?"
                )
                if raw_gy and gy and ((tonumber(hold_pos.y) or 0.0) - gy) <= snap then
                    route3_finish_landing(ch, go, gy, "auto descent")
                    return true
                end
            end
            S.route3_air_pos = hold_pos
            S.route3_air_rot = hold_rot
            local rise_st = S.route3_quick_burst
            local mark_rise_apply = type(rise_st) == "table" and rise_st.phase == "rise"
                and rise_st.seat_first_apply_done ~= true
            if mark_rise_apply then griffin_rise_crash_mark("FIRST SEAT RISE APPLY begin") end
            route3_apply_air_transform(ch, go, hold_pos, hold_rot)
            if mark_rise_apply then
                rise_st.seat_first_apply_done = true
                griffin_rise_crash_mark("FIRST SEAT RISE APPLY completed")
            end
        end
        S.last_character_root_move_call_ok = false
        S.last_character_root_move_moved = false
        S.last_character_root_move_delta = 0.0
        S.last_character_root_move_error = "(route3 no input)"
        S.last_character_root_move_run = false
        S.last_character_root_move_step = 0.0
        S.route3_stuck_since = 0.0
        S.last_route3_edge_guard = "idle"
        return false
    end

    local vertical_step = step
    if S.airborne == true then
        vertical_step = retained_vertical_step or math.max(0.0, tonumber(C.route3_flight_vertical_step) or step)
        local quick_rise = S.route3_quick_burst
        if type(quick_rise) == "table" and quick_rise.phase == "rise"
            and quick_rise.normal_vertical_drive == true then
            vertical = 1.0
            vertical_step = math.max(0.001, tonumber(quick_rise.drive_step) or vertical_step)
        end
        if S.route3_landing_requested == true then
            vertical_step = math.max(0.02, tonumber(C.route3_flight_landing_descent_step) or 0.35)
        end
        -- QUICK rise/dive (A / descend+A) = the FASTER vertical speed, so they read as distinct from the
        -- (now slower) regular ascend/descend. Applies to the simple straight-up/straight-down bursts.
        local qnow = os.clock()
        if (tonumber(S.route3_simple_rise_until) or 0.0) > qnow or (tonumber(S.route3_simple_dive_until) or 0.0) > qnow then
            vertical_step = math.max(vertical_step, tonumber(C.route3_quick_vertical_step) or 0.95)
            -- ⛔ PER-FRAME TAPE (2026-07-26, 5th CTD). Plain A crashes with EVERY experiment
            -- off, so the suspect is this line: ordinary flight ascends at the normal step,
            -- the A press slams it to ~0.95/frame. That is the SAME divergence-from-
            -- FlightControl that killed the node runs, triggered by our own speed instead of
            -- a node's root motion. json.dump_file flushes, so the last frame written IS the
            -- frame it died on -- and the y column shows how far it got first.
            if C.route3_rise_trace_frames ~= false then
                S.route3_simple_frame = (tonumber(S.route3_simple_frame) or 0) + 1
                pcall(function()
                    local p = transform_pos(go)
                    griffin_rise_crash_mark(string.format("SIMPLE-RISE drive f%d step=%.2f y=%.2f",
                        S.route3_simple_frame, vertical_step, tonumber(p and p.y) or -1.0))
                end)
            end
        end
    end
    -- QUICK-RISE/DIVE burst: override the vertical input + speed for the burst window,
    -- EASED (sin curve: gentle start -> peak -> gentle stop) so it reads as a transition,
    -- not a teleport. Movement starts at move_at (after the node anim's wind-up lead).
    local rnow = os.clock()
    local rising = S.airborne == true and (tonumber(S.route3_rise_until) or 0.0) > rnow
        and rnow >= (tonumber(S.route3_rise_move_at) or 0.0)
    S.route3_rise_dbg = (rising == true) and (C.route3_rise_node_force == true)
    -- ⭐ 2026-07-26: the 6th CTD died on "SIMPLE-RISE drive f1" -- the FIRST vertical frame,
    -- at step 0.45 vs the 0.30 she ascends with harmlessly all day. So it is a specific CALL
    -- in this frame, not accumulated divergence. These call-level marks already existed but
    -- were gated behind route3_rise_node_force + the OLD burst path, so they never fired for
    -- the simple rise. Open that gate: one more press and the tape names the exact call.
    if C.route3_rise_trace_frames ~= false
        and ((tonumber(S.route3_simple_rise_until) or 0.0) > rnow
             or (tonumber(S.route3_simple_dive_until) or 0.0) > rnow) then
        S.route3_rise_dbg = true
        S.route3_rise_frame = tonumber(S.route3_simple_frame) or 0
    end
    if rising then
        S.route3_rise_frame = (tonumber(S.route3_rise_frame) or 0) + 1
        if not S.route3_rise_move_marked then S.route3_rise_move_marked = true; pcall(function() griffin_rise_crash_mark("MOVE start dir=" .. tostring(S.route3_rise_dir)) end) end
        local dir = (tonumber(S.route3_rise_dir) or 1.0) < 0.0 and -1.0 or 1.0
        local dur = math.max(0.2, tonumber(C.route3_rise_secs) or 0.8)
        local p = math.min(1.0, math.max(0.0, (os.clock() - (tonumber(S.route3_rise_t0) or os.clock())) / dur))
        local factor = math.max(0.25, math.sin(math.pi * p))
        vertical = dir
        vertical_step = math.max(vertical_step, (tonumber(C.route3_rise_step) or 1.2) * factor)
    end
    S.last_character_root_move_run = run == true or S.route3_soar_coasting == true
    S.last_character_root_move_step = step

    local current_yaw = yaw_from_transform(go) or S.heading_yaw or 0.0
    local turn_step = math.max(0.0, tonumber(C.character_root_turn_step) or 0.035)
    local new_yaw = wrap_angle(current_yaw + turn_input * turn_step)
    local rot = make_quat_yaw(new_yaw)
    -- sprint dive/climb: tilt the nose toward the vertical input, eased per tick
    -- (⛔ do NOT wire the quick-rise into this: burst-pitching reproduced the PARKED bug
    -- verbatim -- griffin flips upside down + rider detaches. S-curve tilt = Phase-2 seat.)
    local pitch_target = 0.0
    if S.airborne == true and run and math.abs(vertical) > 0.05 then
        pitch_target = -vertical * math.max(0.0, tonumber(C.route3_flight_pitch_max) or 26.0)
        if C.route3_flight_pitch_invert == true then pitch_target = -pitch_target end
    end
    local pitch_smooth = math.min(1.0, math.max(0.02, tonumber(C.route3_flight_pitch_smooth) or 0.15))
    local pitch = tonumber(S.route3_air_pitch) or 0.0
    pitch = pitch + (pitch_target - pitch) * pitch_smooth
    S.route3_air_pitch = pitch
    -- NOTE: the tilt itself is applied to the ROOT JOINT in the authority tick;
    -- pitching the object transform is a dead end (character logic either
    -- flips upside down or syncs the rotation back to flat)

    local before = (S.airborne == true and S.route3_air_pos) or transform_pos(go) or gpos
    local ok = false
    local err = nil
    local mode = math.max(0, math.min(1, math.floor(tonumber(C.route3_proxy_drive_mode) or 0)))
    local translation_input = math.abs(forward) + math.abs(strafe_input) + math.abs(vertical)

    -- Rotation by transform is the one part we know the griffin accepts reliably.
    -- If we are also translating, write the final transform once below to reduce camera shake.
    if translation_input <= 0.0 then
        if S.airborne == true then
            S.route3_air_pos = before
            S.route3_air_rot = rot
            ok = route3_apply_air_transform(ch, go, before, rot) or ok
        else
            ok = set_transform(go, before, rot) or ok
        end
    end

    local fwd = { x = math.sin(new_yaw), y = 0.0, z = math.cos(new_yaw) }
    local right = { x = math.cos(new_yaw), y = 0.0, z = -math.sin(new_yaw) }
    local dx = (fwd.x * forward + right.x * strafe_input) * step
    local dy = vertical * vertical_step
    local dz = (fwd.z * forward + right.z * strafe_input) * step
    if S.airborne == true and S.route3_landing_requested == true then
        -- keep descending during a landing even while steering
        dy = math.min(dy, -math.max(0.02, tonumber(C.route3_landing_auto_step) or 0.15))
    end
    local ground_hit = nil
    local ground_y = tonumber(S.route3_landing_ground_y)
    local landing_check = S.airborne == true
        and (S.route3_landing_requested == true or C.route3_auto_land_on_ground_touch == true)
    if landing_check then
        ground_hit = route3_ground_hit_under(go, before)
        local raw_ground_y = tonumber(ground_hit and ground_hit.y)
        if S.route3_landing_requested == true then
            local cancelled = false
            ground_y, cancelled = route3_landing_ground_or_cancel(ch, go, raw_ground_y, os.clock())
            if cancelled then return true end
            if not raw_ground_y then dy = 0.0 end
        elseif raw_ground_y then
            ground_y = raw_ground_y
        end
        local snap_height = math.max(0.05, tonumber(C.route3_flight_landing_snap_height) or 0.35)
        local current_y = tonumber(before.y) or tonumber(gpos.y) or 0.0
        if S.route3_landing_requested == true then
            S.route3_landing_debug = string.format(
                "steer cur=%.2f gy=%s h=%s",
                current_y, tostring(ground_y),
                ground_y and string.format("%.2f", current_y - ground_y) or "?"
            )
        end
        if ground_hit and ground_y and ((current_y - ground_y) <= snap_height or (current_y + dy - ground_y) <= snap_height) then
            route3_finish_landing(ch, go, ground_y, S.route3_landing_requested == true and "auto" or "ground touch")
            return true
        end
        if S.route3_landing_requested == true and ground_y then
            local min_y = ground_y + snap_height
            if current_y + dy < min_y then dy = min_y - current_y end
        end
    end
    if S.airborne == true
        and S.route3_landing_requested ~= true
        and type(S.route3_dogfight) ~= "table"   -- dogfight standdown: it owns its own floors
        and C.route3_air_ground_clearance_enabled == true then
        if not ground_y then
            if S.route3_rise_dbg then pcall(function() griffin_rise_crash_mark("f" .. tostring(S.route3_rise_frame) .. " before ground_hit") end) end
            ground_hit = route3_ground_hit_under(go, before)
            ground_y = tonumber(ground_hit and ground_hit.y)
        end
        if ground_y then
            local clearance = math.max(0.0, tonumber(C.route3_air_ground_clearance) or 0.9)
            local current_y = tonumber(before.y) or tonumber(gpos.y) or 0.0
            local min_y = ground_y + clearance
            if current_y + dy < min_y then dy = min_y - current_y end
        end
    end
    local max_step = math.max(0.0, tonumber(S.airborne and C.route3_flight_max_step or C.route3_transform_max_step) or tonumber(C.native_climb_max_step) or 0.08)
    if S.airborne == true and C.route3_flight_independent_vertical == true then
        local hdx, _, hdz = clamp_drive_delta(dx, 0.0, dz, max_step)
        dx, dz = hdx, hdz
        -- clamp to the EFFECTIVE vertical step (so the soar-dive boost above isn't capped
        -- back down; identical to before when not sprint-diving)
        local max_vertical = math.max(0.0, vertical_step or max_step)
        if max_vertical > 0.0 then
            if dy > max_vertical then dy = max_vertical end
            if dy < -max_vertical then dy = -max_vertical end
        end
    else
        dx, dy, dz = clamp_drive_delta(dx, dy, dz, max_step)
    end

    local move_blocked = false
    if math.abs(forward) + math.abs(strafe_input) > 0.0 and not route3_edge_guard_allows_move(go, dx, dz) then
        move_blocked = true
        dx, dy, dz = 0.0, 0.0, 0.0
        forward, strafe_input, vertical = 0.0, 0.0, 0.0
        S.last_character_root_forward = 0.0
        S.last_character_root_side = 0.0
        S.last_character_root_vertical = 0.0
        S.route3_motion_blocked = true
        S.route3_stuck_since = 0.0
        stop_griffin_animation()
    end

    if math.abs(forward) + math.abs(strafe_input) + math.abs(vertical) > 0.0 then
        if mode == 1 then
            local axis_mode = math.max(0, math.min(3, math.floor(tonumber(C.character_root_move_axis_mode) or 0)))
            local root_x, root_z = strafe_input, forward
            if axis_mode == 1 then
                root_x, root_z = -strafe_input, -forward
            elseif axis_mode == 2 then
                root_x, root_z = forward, -strafe_input
            elseif axis_mode == 3 then
                root_x, root_z = -forward, strafe_input
            end
            local move = make_vec3(root_x * step, vertical * vertical_step, root_z * step)
            if S.route3_rise_dbg then pcall(function() griffin_rise_crash_mark("f" .. tostring(S.route3_rise_frame) .. " before onRootApply") end) end
            local call_ok, call_err = pcall(function()
                ch:call("onRootApply(via.vec3, via.Quaternion)", move, make_quat_identity())
            end)
            if not call_ok then
                call_ok, call_err = pcall(function()
                    ch:call("onRootApply", move, make_quat_identity())
                end)
            end
            if not call_ok then err = call_err end
            ok = call_ok == true or ok
        else
            local pos = make_position(
                (tonumber(before.x) or 0.0) + dx,
                (tonumber(before.y) or 0.0) + dy,
                (tonumber(before.z) or 0.0) + dz
            )
            if S.airborne == true then
                S.route3_air_pos = pos
                S.route3_air_rot = rot
                local rise_st = S.route3_quick_burst
                local mark_normal_rise = type(rise_st) == "table" and rise_st.phase == "rise"
                    and rise_st.normal_vertical_drive == true and rise_st.normal_first_apply_done ~= true
                if mark_normal_rise then griffin_rise_crash_mark("FIRST NORMAL PIPELINE APPLY begin") end
                if S.route3_rise_dbg then pcall(function() griffin_rise_crash_mark("f" .. tostring(S.route3_rise_frame) .. " before air_transform") end) end
                ok = route3_apply_air_transform(ch, go, pos, rot) or ok
                if S.route3_rise_dbg then pcall(function() griffin_rise_crash_mark("f" .. tostring(S.route3_rise_frame) .. " air_transform OK") end) end
                if mark_normal_rise then
                    rise_st.normal_first_apply_done = true
                    griffin_rise_crash_mark("FIRST NORMAL PIPELINE APPLY completed")
                end
            else
                ok = set_transform(go, pos, rot) or ok
            end
        end
    end

    local after = transform_pos(go)
    if after and not sane_position(after) then
        set_transform(go, before, rot)
        after = transform_pos(go) or before
        ok = false
        err = "rejected absurd griffin position"
    end
    if ok then
        S.heading_yaw = new_yaw
        S.drive_pos = (S.airborne == true and S.route3_air_pos) or after or before
        S.drive_rot = rot
    end
    -- ROTATION FIX (2026-07-18, Aurora): restore the 07-01 parked behaviour — rotate the
    -- rider WITH the griffin on native-climb mounts too. `rot` here is make_quat_yaw
    -- (yaw-only, ~line 16113), so it physically CANNOT invert her — the old "end-of-loop
    -- upside-down drill" came from the Wilds-pose/puppet writes (currently disabled), not
    -- from this yaw-only write. The removed `and S.native_climb_mount ~= true` gate assumed
    -- the native climb owns her orientation, but on this mount it does NOT drive it (she
    -- froze facing one way) = the regression that lost her rotation. If the drill ever
    -- returns, gate on the Wilds pose being ACTIVE, never on native_climb_mount.
    if C.route3_rotate_rider_with_griffin == true then
        set_character_rotation_only(get_player(), rot)
    end
    local delta = math.sqrt(math.max(0.0, distance_sq(before, after) or 0.0))
    local movement_input = math.abs(tonumber(S.last_character_root_forward) or 0.0)
        + math.abs(tonumber(S.last_character_root_side) or 0.0)
        + math.abs(tonumber(S.last_character_root_vertical) or 0.0)
    if C.route3_stuck_stop_enabled == true
        and move_blocked ~= true
        and movement_input > 0.2
        and delta < (tonumber(C.route3_stuck_min_delta) or 0.015) then
        local now = os.clock()
        if (tonumber(S.route3_stuck_since) or 0.0) <= 0.0 then
            S.route3_stuck_since = now
        elseif now - (tonumber(S.route3_stuck_since) or now) >= (tonumber(C.route3_stuck_stop_seconds) or 0.6) then
            S.route3_motion_blocked = true
            S.last_route3_edge_guard = "stuck stop"
            stop_griffin_animation()
        end
    else
        S.route3_stuck_since = 0.0
    end
    S.last_character_root_move_call_ok = ok == true
    S.last_character_root_move_moved = delta > 0.002
    S.last_character_root_move_delta = delta
    S.last_character_root_move_error = move_blocked and tostring(S.last_route3_edge_guard)
        or (S.route3_motion_blocked and "route3 stuck stop")
        or (ok and ("(route3 mode " .. tostring(mode) .. ")") or tostring(err or "route3 move failed"))
    S.last_griffin_set_ok = ok == true
    if S.airborne == true then
        local requested_delta = math.sqrt(math.max(0.0, distance_sq(before, S.route3_air_pos) or 0.0))
        S.route3_flight_status = string.format(
            "air land=%s f=%.2f t=%.2f v=%.2f up=%s down=%s moved=%s d=%.3f req=%.3f reap=%s/%s rider=%s mask=0x%X",
            tostring(S.route3_landing_requested == true),
            tonumber(forward) or 0.0,
            tonumber(turn_input) or 0.0,
            tonumber(vertical) or 0.0,
            tostring((tonumber(ascend) or 0.0) > 0.0),
            tostring((tonumber(descend) or 0.0) > 0.0),
            tostring(delta > 0.002),
            tonumber(delta) or 0.0,
            tonumber(requested_delta) or 0.0,
            tostring(S.last_heading_transform_reapply == true),
            tostring(S.route3_air_reapply_status or "(none)"),
            tostring(S.route3_air_rider_status or "(none)"),
            tonumber(S.last_raw_button_mask) or 0)
    end
    return ok == true
end

function route3_ground_jump_tick(now, ch, go)
    if S.airborne == true then
        -- interrupted by a real takeoff mid-jump: restore the root controllers we killed at launch
        if S.route3_ground_jump_active == true then pcall(function() route3_flap_set_root_controllers(true) end) end
        if type(S.base_owner) == "table" and S.base_owner.name == "groundjumpfall" then
            S.base_owner = nil
        end
        S.route3_ground_jump_active = false; return false
    end
    if not (S.route3_proxy_ride_active == true and go) then return false end
    now = now or os.clock()

    local down = false
    pcall(function() down = iris_kb(math.floor(tonumber(C.route3_ground_jump_key) or 32)) end)
    if not down then down = raw_gamepad_button_down(C.route3_ground_jump_buttons) end
    local pressed = down and S.route3_ground_jump_prev ~= true
    S.route3_ground_jump_prev = down

    if S.route3_ground_jump_active ~= true then
        if not pressed then return false end
        local pos = transform_pos(go)
        if not pos then return false end
        local windup = math.max(0.0, tonumber(C.route3_ground_jump_windup) or 0.3)
        S.route3_ground_jump_active = true
        S.route3_ground_jump_windup_until = now + windup
        S.route3_ground_jump_t0 = now + windup
        S.route3_ground_jump_base_y = tonumber(pos.y) or 0.0
        S.route3_ground_jump_mid_done = false
        S.route3_ground_jump_fall_done = false
        clear_motion_queue()
        -- ⭐ the PARABOLA (set_transform below) owns vertical -- kill the clip root controllers so clip
        -- 422's LEAP root-motion can't ALSO lift her (during the un-driven windup especially) = the
        -- "float at the start of a jump" (Aurora). Restored at touchdown below.
        pcall(function() route3_flap_set_root_controllers(false) end)
        -- jump kit: LAUNCH (422) -> WING-FLAP (423) -> [FALL LOOP 416 on a long drop] -> LAND (401).
        -- The wing-flap + fall-loop switches fire in the airborne arc below -- our old jump held 422
        -- the whole way = the "missing half" (Aurora found the middle clips). All species-tunable.
        play_griffin_motion(math.floor(tonumber(C.route3_jump_clip_start) or 422), 0, true)
        -- protect the launch clip through wind-up + arc: a fixed 2.2s expired mid-arc on the
        -- drake (2.0s wind-up) and the ground gait painter walked her through the air
        S.audition_until_clock = now + 2.2 + math.max(0.0, tonumber(C.route3_ground_jump_windup) or 0.3)
        return true
    end

    if now < (tonumber(S.route3_ground_jump_windup_until) or 0.0) then
        return true -- crouching for the leap
    end

    -- ⭐ LANDING SETTLE (2026-08-07, Aurora: "0.5s of no movement once it hits the ground"):
    -- the jump stays "active" (movement stays locked out) while the landing clip plays,
    -- then hands control back.
    if S.route3_ground_jump_settle_until then
        if now < S.route3_ground_jump_settle_until then return true end
        S.route3_ground_jump_settle_until = nil
        S.route3_ground_jump_active = false
        return false
    end

    local v0 = math.max(1.0, tonumber(C.route3_ground_jump_speed) or 8.5)
    local g = math.max(2.0, tonumber(C.route3_ground_jump_gravity) or 13.0)
    local t = math.max(0.0, now - (tonumber(S.route3_ground_jump_t0) or now))
    local h = v0 * t - 0.5 * g * t * t
    -- MIDDLE of the native jump: once the launch clip (422) has played out, switch to the WING-FLAP
    -- clip (423) for the airborne phase -- the bit our old jump skipped by holding 422 the whole way
    -- (Aurora found it). The 416 fall-loop + 401 land follow below.
    if not S.route3_ground_jump_mid_done and (tonumber(C.route3_jump_clip_mid) or -1) >= 0
        and t > (tonumber(C.route3_jump_mid_delay) or 0.3) then
        S.route3_ground_jump_mid_done = true
        play_griffin_motion(math.floor(tonumber(C.route3_jump_clip_mid) or 423), 0, true)
    end
    local pos = transform_pos(go)
    if not pos then
        pcall(function() route3_flap_set_root_controllers(true) end)
        if type(S.base_owner) == "table" and S.base_owner.name == "groundjumpfall" then
            S.base_owner = nil
        end
        S.route3_ground_jump_active = false
        return false
    end
    -- forward push while airborne so the leap actually carries
    local fstep = math.max(0.0, tonumber(C.route3_ground_jump_forward_step) or 0.09)
    local jyaw = yaw_from_transform(go) or S.heading_yaw or 0.0
    local fx, fz = math.sin(jyaw) * fstep, math.cos(jyaw) * fstep
    -- land on the REAL ground below, not the takeoff height: a jump off a
    -- bridge falls all the way down, a jump onto a ledge lands on the ledge
    local base_y = tonumber(S.route3_ground_jump_base_y) or 0.0
    local land_y = base_y
    pcall(function()
        local rp = transform_render_pos(go)
        if rp then
            local hit = route3_cast_ground_below(
                tonumber(rp.x) or 0.0, tonumber(pos.y) or 0.0, tonumber(rp.z) or 0.0,
                5.0, 120.0
            )
            if hit and tonumber(hit.y) then land_y = tonumber(hit.y) end
        end
    end)
    local cur_y = base_y + h
    -- FALL LOOP: past apex and still well above the ground (jumped off a ledge -> long drop) -> loop
    -- the fall clip (416) so she flaps down instead of holding the launch/flap pose all the way.
    if S.route3_ground_jump_mid_done and not S.route3_ground_jump_fall_done
        and (tonumber(C.route3_jump_clip_fall) or -1) >= 0
        and t > (v0 / g) and (cur_y - land_y) > (tonumber(C.route3_jump_fall_height) or 3.0) then
        S.route3_ground_jump_fall_done = true
        S.base_owner = { name = "groundjumpfall", until_clock = now + 0.25 }
        play_griffin_motion(math.floor(tonumber(C.route3_jump_clip_fall) or 416),
            0, true, "groundjumpfall")
    end
    if S.route3_ground_jump_fall_done then
        -- Keep ordinary idle/flight painters off layer 0 for the whole descent.
        -- Do not restart the loop: renewing ownership lets its playhead advance.
        S.base_owner = { name = "groundjumpfall", until_clock = now + 0.25 }
    end
    local drop = math.max(0.0, base_y - land_y)
    local expected_land_t = (v0 + math.sqrt(v0 * v0 + 2.0 * g * drop)) / g
    local hard_timeout = math.min(20.0, math.max(6.0, expected_land_t + 1.5))
    if (cur_y <= land_y + 0.25 and t > 0.2) or t > hard_timeout then
        local landed = make_position((tonumber(pos.x) or 0.0) + fx, land_y, (tonumber(pos.z) or 0.0) + fz)
        set_transform(go, landed, nil)
        if ch then set_character_transform(ch, landed, nil) end
        pcall(function() route3_flap_set_root_controllers(true) end)   -- restore (paired with launch disable)
        if type(S.base_owner) == "table" and S.base_owner.name == "groundjumpfall" then
            S.base_owner = nil
        end
        play_griffin_motion(math.floor(tonumber(C.route3_jump_clip_land) or 401), 0, true)
        S.audition_until_clock = now + 0.8
        -- jump stays active through the settle: movement unlocks when the window ends
        S.route3_ground_jump_settle_until = now + math.max(0.0, tonumber(C.route3_ground_jump_settle_secs) or 0.5)
        return true
    end
    local jumped = make_position(
        (tonumber(pos.x) or 0.0) + fx,
        cur_y,
        (tonumber(pos.z) or 0.0) + fz
    )
    set_transform(go, jumped, nil)
    if ch then set_character_transform(ch, jumped, nil) end
    return true
end

-- ⭐ DISCOVER the clip that Locomotion.VerticalJumpFront drives, so we can play it directly (Aurora's
-- idea) instead of firing the fragile FSM node live. Do it while she stands FREE (not mounted): fire
-- the node once (un-puppeted so the FSM advances into it), then the watch tick below reads the base
-- layer -- the first clip that differs from the standing baseline IS the jump clip. Saved per-species.

function griffin_jump_discover_tick()
    if S.jump_discover_active ~= true then return end
    local gch = reacquire_griffin()
    -- re-fire her jump ACTION each frame (priority-10 requestActionCore = the AI yields; no nav/think
    -- suppression needed). Watch the FSM node + base-layer clip flip to the jump = confirmation it fires.
    pcall(function() request_griffin_action(tostring(C.route3_jump_native_action or "VerticalJumpFront"), 0) end)
    local cb, cc = -1, -1
    local node = "?"
    pcall(function()
        local m = gch and gch:call("get_Motion"); local L = m and m:call("getLayer", 0)
        if L then cb = tonumber(L:call("get_MotionBankID")) or -1; cc = tonumber(L:call("get_MotionID")) or -1 end
    end)
    pcall(function() node = tostring(read_griffin_fsm_node()) end)
    local cur = tostring(cb) .. ":" .. tostring(cc)
    S.jump_discover_seen = cur .. " node=" .. node   -- DIAG: base-layer clip + the FSM node right now
    if (cc >= 0 and cur ~= S.jump_discover_base) or (node ~= "?" and node ~= "" and not tostring(node):find("Wait")) then
        C.route3_jump_native_bank = cb
        C.route3_jump_native_clip = cc
        S.jump_discover_found = cur
        S.jump_discover_active = false
        pcall(function() save_config() end)
        pcall(function() griffin_species_profile_save() end)
        S.jump_discover_status = "action FIRED -> node=" .. node .. " clip=" .. cur .. ". Tick 'Use native jump' to A/B."
        pcall(function() log.info("[GriffinRide] jump action FIRED node=" .. node .. " clip=" .. cur) end)
        return
    end
    if os.clock() >= (tonumber(S.jump_discover_until) or 0.0) then
        S.jump_discover_active = false
        if not S.jump_discover_found then
            S.jump_discover_status = "no change (base " .. tostring(S.jump_discover_base) .. ", saw " .. tostring(S.jump_discover_seen) .. ") -- try action name 'Locomotion.VerticalJumpFront'"
        end
    end
end

local function flight_tick(entry)
    griffin_rise_stage("FRAME: flight_tick begin (" .. tostring(entry) .. ")")
    S.drive_tick_hits = S.drive_tick_hits + 1
    S.last_drive_tick_entry = tostring(entry or "?")
    if not C.enabled then S.last_drive_skip = "disabled"; return end
    if S.world_paused == true then S.last_drive_skip = "paused/photo mode"; return end
    if not S.mounted then S.last_drive_skip = "not mounted"; return end
    if not S.flying then S.last_drive_skip = "not flying"; return end
    if not C.drive_enabled then S.last_drive_skip = "drive disabled"; return end
    -- This is deliberately before the native-climb validity check and every
    -- possible drive backend. A predation lease is not merely a target-hygiene
    -- exception: nav, flight-control, root-move and transform drive must all
    -- stand down while the native griffin stack owns approach/root motion.
    if griffin_predation_window_active() then
        S.last_drive_skip = "native predation owns body"
        return
    end
    S.last_drive_skip = "(running)"
    if C.require_native_climb_for_drive and not update_player_climb_state() then
        if S.native_climb_mount then
            S.mounted = false
            S.native_climb_mount = false
            S.flying = false
            S.airborne = false
            S.stamina_hold_active = false
            set_native_rider_suppressed(false)
            S.last_drive_skip = "native climb lost"
            status("native climb lost; drive stopped")
        elseif os.clock() >= (S.next_ui_status_clock or 0) then
            S.last_drive_skip = "waiting for native climb"
            S.last_status = "drive waiting for native climb"
            S.next_ui_status_clock = os.clock() + 0.5
        end
        return
    end
    local ch, go = reacquire_griffin()
    if not (ch and go) then S.last_drive_skip = "no griffin"; return end

    local now = os.clock()
    S.last_clock = now
    local native_carry_active = griffin_predation_native_carry_active()
    if native_carry_active then pcall(function() griffin_predation_carry_follow_tick(ch, go) end) end

    local route3_transform_drive = S.route3_seat_parented == true or S.route3_proxy_ride_active == true
    if native_carry_active or (tonumber(S.route3_predation_wake_until) or 0.0) > now then
        -- PREDATION WAKE window: leave her AI/hate/TARGETS alive -- IsEnablePredation and the
        -- catch selector live in controllers the per-tick puppet+target-clear never lets grow
        -- (this per-tick hygiene was silently wiping the primed PredationTarget every frame)
    else
        clear_griffin_hate()
        if C.block_party_hate == true then clear_party_hate() end
        clear_griffin_targets()
    end
    if S.native_climb_mount then set_native_rider_suppressed(C.native_climb_suppress_player_control == true) end
    if not S.native_climb_mount then set_rider_hard_lock(true) end

    local gtf = nil
    pcall(function() gtf = go:call("get_Transform") end)
    if not gtf then S.last_drive_skip = "no griffin transform"; return end
    local gpos = nil
    pcall(function() gpos = gtf:call("get_UniversalPosition") end)
    if not gpos then S.last_drive_skip = "no griffin position"; return end
    native_observe_tick(ch, go, gpos, now)
    local x, z, input = read_axis()
    local jump_down = button_on(input, C.takeoff_button)
    -- Use the game's decoded A/jump action for quick rise as well. The previous quick-burst
    -- hotkey polled only the raw HID device; on Aurora's controller its A alias never matched,
    -- even though this decoded action (already used by take-off) was working every frame.
    S.route3_rise_action_down = jump_down == true
    S.jump_prev = jump_down
    S.raw_ascend_down = raw_gamepad_button_down(C.raw_ascend_buttons)
    S.raw_descend_down = raw_gamepad_button_down(C.raw_descend_buttons)
    -- SAFE QUICK RISE: this is deliberately indistinguishable from holding the ordinary
    -- working ascend control. No special clip, FSM owner, absolute position or burst table.
    if (tonumber(S.route3_simple_rise_until) or 0.0) > now then
        S.raw_ascend_down = true
        S.raw_descend_down = false
    end
    -- SAFE QUICK DIVE: mirror of the rise -- straight DOWN, ordinary descend input, no forward swoop.
    if (tonumber(S.route3_simple_dive_until) or 0.0) > now then
        S.raw_descend_down = true
        S.raw_ascend_down = false
    end
    -- QUICK-RISE/DIVE burst: force the vertical input flags so the drive's input gates open
    -- even on a NEUTRAL A press (without this the burst only worked while holding R1/L1).
    -- Gated on move_at: the anim's wind-up lead plays out before the movement starts.
    if (tonumber(S.route3_rise_until) or 0.0) > now and now >= (tonumber(S.route3_rise_move_at) or 0.0) then
        if (tonumber(S.route3_rise_dir) or 1.0) < 0.0 then S.raw_descend_down = true
        else S.raw_ascend_down = true end
    end
    local ascend = (button_on(input, C.ascend_button) or S.raw_ascend_down) and 1.0 or 0.0
    local descend = (button_on(input, C.descend_button) or S.raw_descend_down) and 1.0 or 0.0
    -- Manual vertical input should not wait out a stale FC-only timer once the loop node has
    -- released. route3_rise_fc_lift_end re-seeds our air position before movement resumes.
    if (ascend > 0.0 or descend > 0.0) and griffin_rise_fc_window_active(now)
        and not griffin_node_lockout_active(now) then
        route3_rise_fc_lift_end("manual vertical input after node")
    end

    if not S.heading_yaw then S.heading_yaw = yaw_from_transform(go) or 0.0 end
    if not S.ground_y then S.ground_y = gpos.y end

    local manual_x = (S.manual_right and 1.0 or 0.0) - (S.manual_left and 1.0 or 0.0)
    local manual_z = (S.manual_forward and 1.0 or 0.0) - (S.manual_back and 1.0 or 0.0)
    if manual_x ~= 0.0 then
        x = manual_x
        S.last_axis_source = "manual"
    end
    if manual_z ~= 0.0 then
        z = manual_z
        S.last_axis_source = "manual"
    end
    if S.manual_up then ascend = 1.0; S.last_axis_source = "manual" end
    if S.manual_down then descend = 1.0; S.last_axis_source = "manual" end
    S.last_drive_axis_x = tonumber(x) or 0.0
    S.last_drive_axis_z = tonumber(z) or 0.0

    -- MOUNTED SWOOP: while a dive is active WE own the drive -- write the trajectory
    -- into S.route3_air_pos and zero the stick so the seat drive just HOLDS it (rider
    -- stays attached via the same native-climb path). Costs nothing when not swooping.
    if type(S.route3_quick_burst) == "table" then
        route3_quick_burst_tick(ch, go, now)
        local qst = S.route3_quick_burst
        x, z = 0.0, 0.0
        if type(qst) == "table" and qst.phase == "rise" and qst.normal_vertical_drive == true then
            ascend, descend = 1.0, 0.0
        else
            ascend, descend = 0.0, 0.0
        end
        S.last_axis_source = "quick-burst"
    elseif griffin_divebomb_active() then
        route3_divebomb_tick(ch, go, now)
        x, z, ascend, descend = 0.0, 0.0, 0.0, 0.0
        S.last_axis_source = "divebomb"
    elseif griffin_grab_active() then
        if not (S.route3_grab and S.route3_grab.carry_from_native == true) then
            route3_grab_tick(ch, go, now)   -- native-carry eat is ticked from on_frame instead
        end
        -- the grab DIVE and PICKUP own the drive (dive to the target, then hover for the
        -- snatch clip); while carrying she flies normally
        local gph = S.route3_grab and S.route3_grab.phase
        if gph == "dive" or gph == "pickup" then
            x, z, ascend, descend = 0.0, 0.0, 0.0, 0.0
            S.last_axis_source = "grab"
        end
    elseif griffin_dogfight_active() then
        route3_dogfight_tick(ch, go, now)
        x, z, ascend, descend = 0.0, 0.0, 0.0, 0.0
        S.last_axis_source = "dogfight"
    end
    if griffin_gust_active() or griffin_gatk_active() then
        -- GROUND MOVES lock ALL movement (Aurora: movement must not cancel the anim before its last frame).
        -- x=turn zeroed too so a stick nudge can'''''t sweep-cancel it.
        x, z, ascend, descend = 0.0, 0.0, 0.0, 0.0
        S.last_axis_source = "groundmove"
    end

    -- Her own transform is the heading authority: the drive writes rotation, so reading it back
    -- keeps our idea of "forward" identical to what the player sees, with no integration drift.
    S.heading_yaw = yaw_from_transform(go) or S.heading_yaw or 0.0

    if route3_transform_drive and not griffin_predation_window_active(now) then
        route3_seat_transform_drive_tick(ch, go, gpos, x, z, ascend, descend, input)
        griffin_rise_stage("drive returned")
        route3_ground_follow_tick(go)
        griffin_rise_stage("ground_follow OK")
        route3_proxy_rider_tick(go)
        griffin_rise_stage("proxy_rider OK")
        if S.airborne then
            griffin_rise_stage("airborne block enter")
            -- lock the rider's cling pose for the whole flight (delayed so the
            -- pose has settled — freezing mid-transition contorts the rider)
            if C.route3_freeze_rider_pose == true and S.rider_pose_frozen ~= true
                and S.route3_wilds_rider_pose_active ~= true
                and now >= (tonumber(S.route3_rider_pose_manual_until) or 0.0)
                and now >= (tonumber(S.route3_air_visual_block_until) or 0.0) + math.max(0.0, tonumber(C.route3_freeze_rider_delay) or 0.0)
                and griffin_rider_pose_settled(now) then
                local wilds_started = false
                if C.route3_wilds_rider_pose_enabled == true then
                    wilds_started = route3_wilds_rider_pose_start() == true
                end
                if not wilds_started then
                    local has_capture = (tonumber(C.route3_rider_pose_bank) or -1) >= 0
                        and (tonumber(C.route3_rider_pose_clip) or -1) >= 0
                        and (tonumber(C.route3_rider_pose_frame) or -1) >= 0
                    if has_capture then
                        local ok, why = griffin_apply_captured_rider_pose()
                        S.route3_rider_pose_status = why
                        -- If the live native climb clip differs, leave it playing. Freezing an arbitrary
                        -- frame again would defeat the point of recording a deterministic riding pose.
                        if ok then S.rider_pose_frozen = true end
                    elseif C.griffin_seat_mode ~= true and griffin_set_player_motion_speed(0.0) then
                        S.rider_pose_frozen = true
                        local cur = griffin_player_motion_state()
                        S.route3_rider_pose_status = string.format("legacy freeze b%s:%s f%.1f (capture this or unfreeze and choose another)",
                            tostring(cur.bank), tostring(cur.clip), tonumber(cur.frame) or -1.0)
                    elseif C.griffin_seat_mode == true then
                        -- ⛔⛔ THE CONTORTION GENERATOR (named from the 08-08 log:
                        -- "rider clip never settled in 6s -- freezing anyway"). On this
                        -- creature the rider's cling clip NEVER settles -- the griffin is
                        -- never still, so the cling FSM keeps re-solving and swapping L0
                        -- clips -- and griffin_rider_pose_settled's 6s fallback then
                        -- freezes her at whatever half-transition frame was on screen.
                        -- That frozen half-pose IS the contortion, held for the whole
                        -- flight. Steady seat therefore NEVER blind-freezes: it holds a
                        -- pose only when Aurora has CAPTURED one (deterministic clip+
                        -- frame, re-pinned whenever that clip is live -- the horse saga's
                        -- winning move), otherwise it leaves the game's own coherent
                        -- cling animation running.
                        S.route3_rider_pose_status =
                            "steady seat: blind freeze refused (capture a pose to hold one)"
                    end
                end
            end
            if native_carry_active then
                -- The native constraint is retained independently now.  Do not request a
                -- different FSM action (that is what asks CatchController to abort), but do
                -- repaint the motion layers with the normal ridden flight visuals: after
                -- FlightPathTraceTarget the mounted action stack otherwise leaves the final
                -- dive/success pose latched forever.  Temporarily bypass the configuration's
                -- native-FSM animation preference without changing the saved setting.
                set_griffin_motion_speed(1.0)
                local ox_base = (S.route3_predation_prey_is_ox == true) and math.floor(tonumber(C.route3_carry_ox_base_clip) or -1) or -1
                local captured_grip = S.route3_predation_prey_is_ox == true
                    and C.route3_predation_grip_pose_enabled ~= false
                    and S.route3_predation_grip_sample ~= nil
                if captured_grip then
                    -- Keep AddBringOx: it owns the parent/body half of the authored ox grip.
                    -- The previous v3 test switched it to Default and then replayed only the
                    -- descendant foreleg chain; that produced a visibly different but still
                    -- ungripped pose. Normal ridden flight owns L0/wings, AddBringOx supplies
                    -- its native body context, and Motion replay replaces only the transition
                    -- node's bad foreleg angles. Catch lifetime/release remain untouched.
                    pcall(function()
                        local c253p = get_component(go, "app.Ch253000")
                        if c253p then griffin_predation_apply_carry_motion(c253p) end
                    end)
                    route3_air_flap_tick(now, true)
                    S.route3_air_visual_status = "native ox carry: AddBringOx context + captured Motion talons"
                elseif ox_base >= 0 then
                    -- OX SPLAY FIX (Iris 2026-07-13, GENTLE -- no BringStart/freeze, keeps the clean drop).
                    -- The talons read "arms back to chest" because AddBringOx composites over the takeoff-
                    -- flap's TUCKED legs. Paint a LEGS-DOWN base clip instead + keep AddBringOx on, so the
                    -- grip reaches DOWN to the ox. Re-assert only when the node stomps L0 (guard vs frame-0
                    -- restart). Live-tunable via route3_carry_ox_base_clip (5030 landing / 5190 glide).
                    pcall(function() griffin_predation_apply_carry_motion(get_component(go, "app.Ch253000")) end)
                    if tonumber(route3_flap_layer_clip()) ~= ox_base then
                        pcall(function() play_griffin_motion(ox_base, 0, true) end)
                    end
                    S.route3_air_visual_status = "native ox carry: base clip " .. tostring(ox_base) .. " + AddBringOx"
                elseif (S.route3_predation_native_grip_held == true or C.route3_predation_carry_freeze == true)
                    and S.route3_predation_prey_is_ox == true then
                    -- NATIVE PROCEDURAL OX GRIP: the Bring node grips deterministically but
                    -- its flight movement teleports her (node-anim rider-wall). Re-assert the freeze every
                    -- frame so its movement code can't run -> stable grip held, no teleport. Transform
                    -- drive owns position; static wings is the tradeoff. Do NOT paint L0 (that fought the
                    -- frozen node); the node's own held pose IS the grip.
                    pcall(function() set_think_stop(ch, true) end)
                    pcall(function() set_motion_fsm_puppet(go, true) end)
                    S.route3_carry_frozen = true   -- flag so the GROUND path tears the freeze down on landing
                    S.route3_air_visual_status = S.route3_predation_native_grip_held
                        and "native ox carry: procedural BringStart grip (safe staged release)"
                        or "native ox carry: FROZEN grip (Bring node, no movement)"
                else
                -- OX CARRY POSE (Iris 2026-07-12): _talon_probe proved the splay = AddBringOx
                -- compositing over OUR flap clip 5210 on L0 (FSM is LIVE, not frozen). Modes (ox only):
                --   "native"       = paint NOTHING; let the live Catch node drive its own carry base so
                --                    AddBringOx sits on the pose it was authored for = correct grip.
                --   "default_body" = keep the ridden flap but drop AddBringOx so it can't splay (no grip).
                --   "flap"         = the old behaviour (flap + AddBringOx = the splay).
                local ox_mode = (S.route3_predation_prey_is_ox == true) and tostring(C.route3_carry_ox_pose_mode or "native") or "flap"
                if ox_mode == "native" then
                    S.route3_air_visual_status = "native ox carry: node-driven pose (no L0 override)"
                else
                    if ox_mode == "default_body" then
                        pcall(function()
                            local c253p = get_component(go, "app.Ch253000")
                            if c253p then c253p:call("set_MotinoLayerActionBodyName(System.String)", "Default") end
                        end)
                    end
                    route3_air_flap_tick(now, true)
                    S.route3_air_visual_status = "native catch carry + ridden flight motion"
                end
                end
            else
                route3_native_flight_fsm_tick(now)
                route3_wing_replay_auto_tick(now)
                route3_air_flap_tick(now, false)
            end
        else
            local procedural_grip_grounded = S.route3_predation_native_grip_held == true
                and griffin_predation_native_carry_active()
            if procedural_grip_grounded then
                -- Never wake BringStart merely because the root crossed the ground
                -- threshold. Land-to-eat will call the staged safe release shortly;
                -- an explicit drop does the same. A direct wake here was the slam bug.
                pcall(function() set_think_stop(ch, true) end)
                pcall(function() set_motion_fsm_puppet(go, true) end)
                S.route3_carry_frozen = true
                S.route3_air_visual_status = "grounded native grip: awaiting staged release/eat"
            else
                -- Tear down only an old/manual carry freeze. The procedural grip has
                -- its own staged node exit and must not pass through this wake path.
                if S.route3_carry_frozen == true and not S.route3_predation_eat then
                -- undo ONLY the carry freeze's think-stop; keep MotionFsm2 puppet at the normal mounted
                -- value (set_griffin_puppet(true) uses C.puppet_motion_fsm) -- un-puppeting broke the
                -- ground drive. Also clear any stuck predation window so steering can resume.
                    pcall(function() set_think_stop(ch, false) end)
                    pcall(function() set_motion_fsm_puppet(go, C.puppet_motion_fsm == true) end)
                    S.route3_predation_mode = nil
                    S.route3_predation_native_until = 0.0
                    S.route3_predation_wake_until = 0.0
                    S.route3_predation_probe_until = 0.0
                    S.route3_carry_frozen = nil
                end
                route3_ground_jump_tick(now, ch, go)
                route3_visual_animation_tick(now)
            end
        end
    end

    -- The retired velocity backend used to integrate S.vx/vy/vz here and write the result onto
    -- her transform. route3's seat drive owns position now, so the only part that still earns its
    -- keep is the teardown: clearing drive_pos is what stops reapply_drive_transform re-applying
    -- a stale target on_frame, and a SECOND writer on her via.Transform is the documented AV.
    S.last_griffin_set_ok = false
    S.drive_pos = nil
    S.drive_rot = nil

    if now >= (S.next_ui_status_clock or 0) then
        read_griffin_fsm_node()
        S.last_status = string.format("%s stick=(%.2f %.2f) h=%.1f",
            S.airborne and "airborne" or "mounted-ground",
            x, z, gpos.y - (tonumber(S.ground_y) or gpos.y))
        S.next_ui_status_clock = now + 0.25
    end
    append_observe_snapshot("tick", ch, go, transform_pos(go) or gpos, now)
end

-- ⭐ WILD-FERRY WALL-CHECK LEASE (2026-08-11). The lure CTD is no longer ambiguous:
-- reframework_crash.dmp lands in app.Ch253WallCheck.updateWallCheckFlight, called from
-- Ch253000.update, ten seconds into the FC-off corridor drive. Ch253WallCheck is an inherited
-- character update (not a detachable component), so the safe intervention is this exact method.
-- Skip it only for the one matching wild Griffin while our ferry owns its transform. The gate
-- vanishes with S.oxtame_fly, which restores native wall avoidance without a teardown call/race.
_G.IrisOxTameWallCheckState_v1 = S -- reload-safe: the one hook always consults the newest state table
pcall(function()
    if rawget(_G, "IrisOxTameWallCheckHook_v1") == true then return end
    local td = sdk.find_type_definition("app.Ch253WallCheck")
    local m = td and td:get_method("updateWallCheckFlight")
    if not m then
        log.warn("[OxTame] Ch253WallCheck.updateWallCheckFlight hook NOT found")
        return
    end
    sdk.hook(m,
        function(args)
            local live_state = rawget(_G, "IrisOxTameWallCheckState_v1")
            local D = live_state and live_state.oxtame_fly
            if not (D and D.fc_off == true and D.ferry == true and D.ch) then
                return sdk.PreHookResult.CALL_ORIGINAL
            end
            local this = nil
            pcall(function() this = sdk.to_managed_object(args[2]) end)
            if this and same_obj(this, D.ch) then
                D.wallcheck_skips = (tonumber(D.wallcheck_skips) or 0) + 1
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            return sdk.PreHookResult.CALL_ORIGINAL
        end,
        nil)
    _G.IrisOxTameWallCheckHook_v1 = true
    log.info("[OxTame] scoped Ch253WallCheck ferry hook registered")
end)

-- ⭐ Hide ONLY the main pawn's floating overhead nameplate while she rides the griffin. DD2 draws
-- that name from app.GUIBase.getName(app.CharacterID); hook it and return an empty string for HER CID
-- while S.route3_pawn_name_hidden is set. Proven return-override pattern (RiftSpeakCarrySpike.lua:5481,
-- AffinityBar.lua:1170). Gated TIGHT -- only her CID, only while latched -- so every other name is
-- untouched, and it restores the instant the ride releases.
pcall(function()
    local gm = sdk.find_type_definition("app.GUIBase"):get_method("getName(app.CharacterID)")
    if not gm then return end
    local pending = false
    sdk.hook(gm,
        function(args)
            pending = false
            pcall(function()
                if S.route3_pawn_name_hidden ~= true then return end
                S.route3_pawn_name_calls = (S.route3_pawn_name_calls or 0) + 1   -- DIAG: hook fired while hidden
                if S.route3_pawn_cid64 == nil then return end
                local g2, g1
                pcall(function() g2 = sdk.to_int64(args[2]) end)   -- getName(CharacterID): first real param
                pcall(function() g1 = sdk.to_int64(args[1]) end)   -- fallback slot (this / static ctx)
                S.route3_pawn_name_lastgot = g2   -- DIAG: what each slot yields vs the cached pawn CID
                S.route3_pawn_name_lastgot1 = g1
                if g2 == S.route3_pawn_cid64 or g1 == S.route3_pawn_cid64 then pending = true end
            end)
        end,
        function(retval)
            if pending then
                pending = false
                S.route3_pawn_name_blanked = (S.route3_pawn_name_blanked or 0) + 1   -- DIAG: matched + blanked
                local ok, s = pcall(function() return sdk.to_ptr(sdk.create_managed_string("")) end)
                if ok and s then return s end
            end
            return retval
        end)
    pcall(function() log.info("[GriffinRide] pawn nameplate hide-hook registered") end)
end)

local rel_method = nil
pcall(function()
    rel_method = sdk.find_type_definition("app.BattleRelationshipHolder"):get_method("getRelationshipFromTo(app.Character, app.Character)")
end)

if rel_method then
    sdk.hook(rel_method,
        function(args)
            thread.get_hook_storage().griffinride_iris_args = (
                C.enabled and sdk.to_int64(args[3]) ~= 0 and sdk.to_int64(args[4]) ~= 0
                    and (next(mounts) ~= nil or S.griffin ~= nil or S.route3_proxy ~= nil)
            ) and args or nil
        end,
        function(retval)
            local args = thread.get_hook_storage().griffinride_iris_args
            if not args then return retval end
            local a, b = nil, nil
            pcall(function()
                a = sdk.to_managed_object(args[3])
                b = sdk.to_managed_object(args[4])
            end)
            if not (a and b) then return retval end
            local a_mount = mounts[a] == true or same_obj(a, S.griffin)
            local b_mount = mounts[b] == true or same_obj(b, S.griffin)
            -- ⭐ 08-13 (the hoe vs Clucky; Aurora: "summoned pets never draw swings"):
            -- mounts{} is WRAPPER-keyed and resident bodies registered with the box's
            -- wrappers matched nothing here - friends on paper, prey in practice. The
            -- box publishes live resident CHARACTER addresses; match those too (the
            -- HoldWolf address pattern).
            if not (a_mount or b_mount) then
                local ra = rawget(_G, "IrisResidentChAddrs")
                if ra then
                    pcall(function()
                        if ra[a:get_address()] then a_mount = true end
                        if ra[b:get_address()] then b_mount = true end
                        -- RECEIPT (throttled): does the swing's targeting even ASK this
                        -- hook about residents? A missing line during a homing swing =
                        -- the acquisition lives elsewhere (TargetSelector/hate side).
                        if (a_mount or b_mount)
                            and os.clock() > (tonumber(rawget(_G, "IrisResRelLogAt")) or 0) then
                            _G.IrisResRelLogAt = os.clock() + 2.0
                            log.info("[GriffinRideProbe (IRIS)] rel hook asked about a RESIDENT - answering FRIEND")
                        end
                    end)
                end
            end
            local a_proxy = same_obj(a, S.route3_proxy)
            local b_proxy = same_obj(b, S.route3_proxy)
            if not (a_mount or b_mount or a_proxy or b_proxy) then return retval end
            if a_proxy or b_proxy then
                local other = (a_proxy and b) or a
                if is_player_or_party(other) then
                    S.friend_hits = S.friend_hits + 1
                    return REL_FRIEND
                end
                if S.route3_proxy_target and same_obj(other, S.route3_proxy_target) then
                    return GRIFFIN_IRIS_REL_ENEMY
                end
                return retval
            end
            -- ATTACK-ORDER HOLE: for the companion vs its ordered target,
            -- FORCE hostile both directions. Deferring to the game was a
            -- dead end: monster-vs-monster is not natively hostile, so both
            -- sides politely Waited (cstate never left 0). Forcing ENEMY
            -- gives her tree a legitimate foe and makes the target fight back.
            -- Also force ENEMY on the UNLEASH path: unleash defers the target to
            -- the game (retval), but monster-vs-monster is natively NEUTRAL, so her
            -- hate sat on a "neutral" goblin and her AI had no legit foe to select =
            -- she idled. Making the ordered/unleashed target a REAL enemy (both dirs)
            -- is exactly what a wild griffin has and we'd deleted. (Investigation
            -- 2026-07-05: THE missing piece for native pursuit.)
            if (S.companion_order == "attack" or S.route3_unleashed == true) and S.companion_target
                and (same_obj(a, S.companion_target) or same_obj(b, S.companion_target)) then
                S.route3_attack_rel_hits = (tonumber(S.route3_attack_rel_hits) or 0) + 1
                pcall(function() S.route3_attack_rel_native = sdk.to_int64(retval) end)
                return GRIFFIN_IRIS_REL_ENEMY
            end
            -- The companion's friendly-world override must not rewrite the
            -- selected prey during the scoped native predation lease. Preserve
            -- the engine's original relationship for the clean replay: the wild
            -- ox tape had no hate target, so inventing an enemy relationship
            -- would turn a predation test into a combat test. Enemy forcing is
            -- retained only as an explicit assisted fallback.
            if griffin_predation_window_active() and S.companion_target
                and (same_obj(a, S.companion_target) or same_obj(b, S.companion_target)) then
                if S.route3_predation_force_enemy_active == true then
                    return GRIFFIN_IRIS_REL_ENEMY
                end
                return retval
            end
            local other = a_mount and b or a
            S.relation_hits = S.relation_hits + 1
            -- ⛔⛔ 08-11 (Aurora: "Lyra just took out my wolf xD and is still trying to
            -- kill it"): the party-friend answer used to sit at the BOTTOM of this hook,
            -- gated on C.friendly_to_party / friendly_to_world -- config drift across
            -- eras could leave both false, and then the hook deferred to the NATIVE
            -- answer, where pawn-vs-ch223-monster is ENEMY. Lyra was doing exactly what
            -- the engine told her. The taming arc settled this: relationship
            -- classification is THE lever that holds a pawn -- so for the PLAYER and
            -- PARTY vs a stable companion it is now UNCONDITIONAL, above every
            -- world/attackable carve-out (those already exclude the party anyway).
            if is_player_or_party(other) then
                S.friend_hits = S.friend_hits + 1
                return REL_FRIEND
            end
            -- UNLEASHED: her native monster AI must see real enemies to fight.
            -- Keep ONLY the player + party forced-friendly (the safety shield);
            -- for everyone else defer to the game (native = hostile to enemies)
            -- so she hunts naturally instead of finding the whole world friendly.
            if S.route3_unleashed == true then
                if is_player_or_party(other) then
                    S.friend_hits = S.friend_hits + 1
                    return REL_FRIEND
                end
                return retval
            end
            -- ⭐⭐⭐ 08-09 r89 -- THE ACTUAL REASON NOTHING CAN HURT THE HORSE.
            -- Every other suspect was eliminated by measurement: colliders on,
            -- HitController on, immunity flags 00/00, hate flowing freely
            -- (hateAllowed climbing into the tens of thousands). And still no
            -- damage -- because none of that matters if the engine decides the
            -- attacker and the target are FRIENDS.
            -- This hook answers app.BattleRelationshipHolder.getRelationshipFromTo,
            -- and with friendly_to_world (default true) it returns REL_FRIEND
            -- for the companion against the ENTIRE WORLD. The cyclops can want
            -- to hit the horse all it likes; every connected blow is billed as
            -- friendly fire and refused with no HP change.
            -- ⛔ AND THIS IS WHY THE r84 FIX DID NOT WORK: I exempted mounted
            -- combat in the HATE hook only. Hate says "who do I want to fight";
            -- relationship says "am I allowed to hurt them". Both have to agree,
            -- and I only ever fixed one of them.
            -- An attackable active companion is fair game whether mounted or
            -- not. Player and pawns remain forced-friendly below; only the
            -- companion/world pairing defers to the game's hostile answer.
            if C.route3_companion_can_be_attacked == true
                or C.route3_mounted_combat ~= false then
                local ridden_rel = false
                pcall(function()
                    local api = rawget(_G, "IrisHorseMount")
                    ridden_rel = api and api.is_mounted
                        and api.is_mounted() == true
                end)
                if (C.route3_companion_can_be_attacked == true or ridden_rel)
                    and not is_player_or_party(other) then
                    _G.IrisMountedRelEnemy =
                        (tonumber(rawget(_G, "IrisMountedRelEnemy")) or 0) + 1
                    return retval   -- defer to the game: hostile stays hostile
                end
            end
            if C.friendly_to_world then
                S.friend_hits = S.friend_hits + 1
                return REL_FRIEND
            end
            if C.friendly_to_party and is_player_or_party(other) then
                S.friend_hits = S.friend_hits + 1
                return REL_FRIEND
            end
            return REL_NEUTRAL
        end
    )
end

-- PORT of Better Monster Infighting's TargetType=19 (that mod sits in a data/ subfolder
-- so REFramework never loaded it). On our griffin's TargetController.updateTargetInfo,
-- force TargetType=19 so her AI treats her current target (the goblin, set via
-- _LastDamageHitObject) as a hostile monster to attack -- the targeting switch we never
-- set. args[2] = the TargetInfo (mirrors the mod's access exactly).
do  -- scoped so these locals don't count toward the 200-local main-chunk ceiling
    local tc_upd_method = nil
    pcall(function() tc_upd_method = sdk.find_type_definition("app.TargetController"):get_method("updateTargetInfo") end)
    if tc_upd_method then
        sdk.hook(tc_upd_method,
            function(args)
                if S.griffin == nil and S.route3_proxy == nil then return end
                pcall(function()
                    local trg = sdk.to_managed_object(args[2])
                    if not trg then return end
                    local chara = nil
                    pcall(function() chara = trg:get_field("<Chara>k__BackingField") end)
                    if not chara then return end
                    local match = (S.route3_unleashed == true and S.griffin and same_obj(chara, S.griffin))
                        or (S.route3_proxy and same_obj(chara, S.route3_proxy))
                    if match then
                        trg:set_field("<TargetType>k__BackingField", 19)
                        S.route3_targettype_hits = (tonumber(S.route3_targettype_hits) or 0) + 1
                    end
                end)
            end,
            nil
        )
    end
end

-- PRE-LOAD SAFETY NET: spawner-born bodies crash the scene teardown of a
-- save-load (confirmed with all mod hooks disabled — it's the spawn method,
-- not us). These hooks fire the moment the player CONFIRMS a load, while
-- the world is still valid, and destroy every spawner instance cleanly.
-- Deliberately NOT gated on C.enabled: this is a safety net, not a feature.
pcall(function()
    local function hook_preload(td_name, sig, tag)
        local td = sdk.find_type_definition(td_name)
        local m = td and td:get_method(sig)
        if not m then return end
        sdk.hook(m,
            function(args)
                pcall(function() griffin_preload_cleanup(tag) end)
                return sdk.PreHookResult.CALL_ORIGINAL
            end,
            nil
        )
    end
    hook_preload("app.SaveDataManager", "requestLoad(System.Int32, app.SaveDataManager.SaveLoadRequestArgs, System.UInt32[])", "save load")
    hook_preload("app.SaveDataManager", "requestLoadManual(System.Int32, app.SaveDataManager.SaveLoadRequestArgs)", "manual load")
    hook_preload("app.SaveDataManager", "requestLoadAuto(app.SaveDataManager.SaveLoadRequestArgs)", "auto load")
    hook_preload("app.MainFlowManager", "requestLoadGameData(System.Int32)", "load game data")
    -- RETURN-TO-TITLE path: the scene tears down HERE, before any load method
    -- (Aurora: quit-to-title then reload still crashed → the load hooks fire
    -- too late). Catch the title-return + backstage-demo transition too.
    hook_preload("app.MainFlowManager", "restart()", "restart/title")
    hook_preload("app.MainFlowManager", "loadBackStageDemo()", "backstage demo")
    hook_preload("app.MainFlowManager", "requestLoadSystemData(System.Action, System.Action)", "load system data")
    hook_preload("app.SaveDataManager", "requestLoadSystemData(app.SaveDataManager.SaveLoadRequestArgs)", "load system (sdm)")
end)

-- root motion reaches the character through this single call: skipping it for
-- our airborne griffin kills a clip's self-propulsion at the source, so the
-- mesh (and the climb-attached rider on it) is never dragged off our position
griffin_iris_root_apply_method = nil
pcall(function()
    griffin_iris_root_apply_method = sdk.find_type_definition("app.Character"):get_method("onRootApply(via.vec3, via.Quaternion)")
end)

if griffin_iris_root_apply_method then
    sdk.hook(griffin_iris_root_apply_method,
        function(args)
            if not (C.enabled and S.griffin ~= nil) then return sdk.PreHookResult.CALL_ORIGINAL end
            -- UNLEASHED: never eat her root motion — she flies and swoops on
            -- her own authored movement now
            if S.route3_unleashed == true then return sdk.PreHookResult.CALL_ORIGINAL end
            if griffin_predation_window_active() then return sdk.PreHookResult.CALL_ORIGINAL end
            local flyin = S.route3_whistle_flyin ~= nil or S.route3_companion_moving == true
            if not flyin then
                if S.airborne ~= true then return sdk.PreHookResult.CALL_ORIGINAL end
                if not (S.route3_proxy_ride_active == true or S.route3_seat_parented == true) then return sdk.PreHookResult.CALL_ORIGINAL end
            end
            local this = nil
            pcall(function() this = sdk.to_managed_object(args[2]) end)
            if this and same_obj(this, S.griffin) then
                S.root_apply_blocks = (tonumber(S.root_apply_blocks) or 0) + 1
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            return sdk.PreHookResult.CALL_ORIGINAL
        end,
        nil
    )
end

local hate_add_method = nil
pcall(function()
    hate_add_method = sdk.find_type_definition("app.HateSystem"):get_method(
        "addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)"
    )
end)

local function action_matches_patterns(node, patterns)
    if not node then return false end
    local lo = tostring(node):lower()
    for raw in tostring(patterns or C.block_player_action_patterns or ""):gmatch("[^,%s]+") do
        local pat = raw:lower()
        if pat ~= "" and lo:find(pat, 1, true) then return true end
    end
    return false
end

function route3_proxy_action_is_attack(node)
    return action_matches_patterns(node, C.route3_proxy_attackish_patterns)
end

ROUTE3_WILD_OBSERVE_LOG_PATH = MOD .. "_wild_combat_observe.csv"

function route3_wild_csv(value)
    local s = tostring(value or "")
    return s:gsub("[\r\n]", " "):gsub(",", ";")
end

function route3_wild_vec(v)
    if not v then return "nil" end
    return string.format("(%.1f %.1f %.1f)", tonumber(v.x) or 0.0, tonumber(v.y) or 0.0, tonumber(v.z) or 0.0)
end

function route3_wild_observe_is_candidate(ch)
    if not ch then return false end
    if is_player_or_party(ch) or is_dead(ch) then return false end
    if S.griffin and same_obj(ch, S.griffin) then return false end
    if S.route3_proxy and same_obj(ch, S.route3_proxy) then return false end
    local nm = tostring(go_name(char_go(ch)) or "")
    return name_matches_csv(nm, C.route3_wild_observer_patterns)
end

function route3_wild_observe_write(line)
    if C.route3_wild_observer_log_enabled ~= true then return false end
    local ok, err = pcall(function()
        local f = io.open(ROUTE3_WILD_OBSERVE_LOG_PATH, "a")
        if not f then error("open failed") end
        f:write(line, "\n")
        f:close()
    end)
    if ok then
        S.route3_wild_observe_log_lines = (tonumber(S.route3_wild_observe_log_lines) or 0) + 1
    else
        S.route3_wild_observe_status = "wild observe write failed: " .. tostring(err)
    end
    return ok
end

function route3_wild_observe_find()
    local pgo = char_go(get_player())
    local ppos = pgo and transform_pos(pgo)
    if not ppos then return nil end
    local radius = math.max(10.0, tonumber(C.route3_wild_observer_radius) or 180.0)
    local best, best_go, best_d = nil, nil, radius * radius
    local function consider(ch)
        if not route3_wild_observe_is_candidate(ch) then return end
        local go = char_go(ch)
        local pos = go and transform_pos(go)
        if not pos then return end
        local d = distance_sq(pos, ppos)
        if d and d < best_d then best, best_go, best_d = ch, go, d end
    end
    pcall(function()
        local em = singleton("app.EnemyManager")
        if em then
            for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
                local list = nil
                pcall(function() list = em:call(getter) end)
                local n = 0
                pcall(function() n = list and list:call("get_Count") or 0 end)
                for i = 0, (tonumber(n) or 0) - 1 do pcall(function() consider(list:call("get_Item", i)) end) end
            end
        end
    end)
    if not best then
        pcall(function()
            local sm = sdk.get_native_singleton("via.SceneManager")
            local smt = sdk.find_type_definition("via.SceneManager")
            local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
            local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
            for _, ch in ipairs(system_array_to_table(comps) or {}) do pcall(function() consider(ch) end) end
        end)
    end
    S.route3_wild_observe_ch = best
    S.route3_wild_observe_go = best_go
    S.route3_wild_observe_name = tostring(go_name(best_go) or "(none)")
    return best, best_go, math.sqrt(best_d or 0.0)
end

function route3_wild_observe_action_update(ch, node)
    if C.route3_wild_observer_enabled ~= true then return false end
    if not (S.route3_wild_observe_ch and same_obj(ch, S.route3_wild_observe_ch)) then
        if not route3_wild_observe_is_candidate(ch) then return false end
        S.route3_wild_observe_ch = ch
        S.route3_wild_observe_go = char_go(ch)
        S.route3_wild_observe_name = tostring(go_name(S.route3_wild_observe_go) or "?")
    end
    S.route3_wild_observe_action = tostring(node or "(none)")
    table.insert(S.route3_wild_observe_actions, 1, S.route3_wild_observe_action)
    while #S.route3_wild_observe_actions > 10 do table.remove(S.route3_wild_observe_actions) end
    if route3_proxy_action_is_attack(node) then
        S.route3_wild_observe_attacks = (tonumber(S.route3_wild_observe_attacks) or 0) + 1
    end
    return true
end

function route3_wild_observe_fsm(ch)
    local node = "?"
    pcall(function()
        local go = char_go(ch)
        local fsm = get_component(go, "via.motion.MotionFsm2")
        node = tostring(fsm and fsm:call("getCurrentNodeName", 0) or "?")
    end)
    return node
end

function route3_wild_observe_tick()
    if C.route3_wild_observer_enabled ~= true then return false end
    local now = os.clock()
    if now - (tonumber(S.route3_wild_observe_last_clock) or 0.0) < 0.25 then return true end
    S.route3_wild_observe_last_clock = now
    local ch, go = S.route3_wild_observe_ch, S.route3_wild_observe_go
    if not (ch and go) or is_dead(ch) then
        ch, go = route3_wild_observe_find()
    end
    if not (ch and go) then
        S.route3_wild_observe_status = "wild observe=no griffin"
        return false
    end
    local ppos = transform_pos(char_go(get_player()))
    local pos = transform_pos(go)
    local dist = (ppos and pos and math.sqrt(distance_sq(pos, ppos) or 0.0)) or 0.0
    local _, battle = griffin_battle_group_status(ch)
    local cflag = "?"
    pcall(function()
        local csc = ch:get_field("<CombatStateControl>k__BackingField")
        local flag = csc and csc:get_field("<CombatStatusFlag>k__BackingField")
        if flag then cflag = tostring(flag:get_field("Data")) end
    end)
    local fsm = route3_wild_observe_fsm(ch)
    local hp = "?"
    pcall(function() hp = tostring(ch:call("get_Hp") or "?") end)
    S.route3_wild_observe_status = string.format("wild observe=%s dist=%.1f %s cstate=%s fsm=%s action=%s attacks=%d",
        tostring(go_name(go) or "?"), dist, tostring(battle or "?"), tostring(cflag),
        tostring(fsm), tostring(S.route3_wild_observe_action or "?"),
        tonumber(S.route3_wild_observe_attacks) or 0)
    route3_wild_observe_write(table.concat({
        string.format("%.3f", now),
        route3_wild_csv(go_name(go)),
        route3_wild_csv(route3_wild_vec(pos)),
        string.format("%.1f", dist),
        route3_wild_csv(battle),
        route3_wild_csv(cflag),
        route3_wild_csv(fsm),
        route3_wild_csv(S.route3_wild_observe_action),
        tostring(tonumber(S.route3_wild_observe_attacks) or 0),
        route3_wild_csv(hp),
    }, ","))
    return true
end

local function character_distance_to_griffin(ch, owner_go)
    local _, griffin_go = reacquire_griffin()
    if not griffin_go then return nil end
    local a = transform_pos(owner_go or char_go(ch))
    local b = transform_pos(griffin_go)
    local dsq = distance_sq(a, b)
    return dsq and math.sqrt(math.max(0.0, dsq)) or nil
end

function should_block_npc_griffin_alert(owner_ch, owner_go, node)
    -- ⛔⛔⛔ 08-10 r99 -- THIS IS WHY NOTHING WILL FIGHT YOU. THE WHOLE THING.
    -- The probe cornered it: updateDamageHp fired TWICE in an entire session, so
    -- the cyclops was not producing damage events for ANYONE -- it was not really
    -- attacking at all. Not the horse being shielded; the enemy being disarmed.
    -- This function is hooked onto requestActionCore and SKIPS the request. Its
    -- pattern list is:
    --   combat, battle, alert, enemy, threat, shout, bark, voice, talk, speech,
    --   attack, atk, weapon, slash, shoot, aim, throw, hit, damage, search,
    --   notice, discover, hostile
    -- ...applied to EVERY non-party character within 45 METRES of the companion.
    -- So an enemy near your mount cannot request an ATTACK ("attack", "atk",
    -- "slash", "weapon", "hit"), and cannot even request NOTICING you
    -- ("notice", "discover", "search", "alert") -- which is precisely why
    -- kicking a fresh cyclops produced no aggro whatsoever.
    -- It was written to stop townsfolk panicking at a tamed griffin, and for that
    -- it is right. But your companion is the horse you are SITTING ON, so it has
    -- been muting every enemy in a 45m bubble that follows you around.
    -- ⭐ Riding is a combat posture. While mounted, enemies keep their voices.
    if C.route3_mounted_combat ~= false then
        local ridden_alert = false
        pcall(function()
            local api = rawget(_G, "IrisHorseMount")
            ridden_alert = api and api.is_mounted
                and api.is_mounted() == true
        end)
        if ridden_alert then
            _G.IrisAlertBlockSkipped =
                (tonumber(rawget(_G, "IrisAlertBlockSkipped")) or 0) + 1
            return false
        end
    end
    -- This pacifier exists for guards/townsfolk, not monsters. Blocking every
    -- "attack/notice/hit" request from kind-8 actors creates a moving 45 m
    -- no-combat bubble around an unmounted companion.
    if C.route3_companion_can_be_attacked == true then
        local octx = route3_ally_group_ctx(owner_ch)
        local okind = nil
        pcall(function() okind = tonumber(octx and octx:get_field("CharacterKind")) end)
        if okind == 8 then return false end
    end
    if C.block_npc_griffin_alert_actions ~= true or not S.griffin then return false end
    if not owner_ch or same_obj(owner_ch, get_player()) or same_obj(owner_ch, S.griffin) then return false end
    if is_player_or_party(owner_ch) then return false end
    if not action_matches_patterns(node, C.block_npc_griffin_alert_patterns) then return false end
    local max_dist = tonumber(C.block_npc_griffin_alert_distance) or 45.0
    local dist = character_distance_to_griffin(owner_ch, owner_go)
    if dist and dist <= max_dist then return true end
    return false
end

local action_request_method = nil
pcall(function()
    action_request_method = sdk.find_type_definition("app.ActionManager"):get_method(
        "requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)"
    )
end)

if action_request_method then
    sdk.hook(action_request_method,
        function(args)
            if not C.enabled then return sdk.PreHookResult.CALL_ORIGINAL end

            local am = nil
            pcall(function() am = sdk.to_managed_object(args[2]) end)
            if not am then return sdk.PreHookResult.CALL_ORIGINAL end

            local owner_go = nil
            pcall(function() owner_go = am:call("get_GameObject") end)
            local owner_ch = get_component(owner_go, "app.Character")

            local node = nil
            pcall(function() node = sdk.to_managed_object(args[4]):ToString() end)
            node = tostring(node or "?")

            pcall(function() route3_wild_observe_action_update(owner_ch, node) end)

            if same_obj(owner_ch, get_player()) then
                -- ⭐ OX-TAME RODEO capture (07-20): stamp the player's requested action BEFORE the
                -- S.mounted gate (the wild-griffin rodeo is NOT S.mounted), so IrisTaming can detect
                -- "the player is attacking" -- a sorceror's staff cast reports NO current-action name,
                -- but it DOES request one through here. Class-agnostic, works even mid native-climb.
                _G.IrisPlayerActionNode = node
                _G.IrisPlayerActionAt = os.clock()
                if not S.mounted then return sdk.PreHookResult.CALL_ORIGINAL end
                table.insert(S.player_action_history, 1, node)
                while #S.player_action_history > 8 do table.remove(S.player_action_history) end
                -- ⭐ v15 AIR-SEAT FALL-ACTION KILL (Nick levitate recipe: cancel HighFall at the
                -- request door). The -Y storm on the drake survived every component kill (FSM,
                -- CC, AdjustTerrain, ghost physics, fall-kill belief) because the ACTION system
                -- requests fall/cling actions straight through them -- a live fall action steps
                -- her down 1.5-3.6m per frame (log: pure -Y micro-jumps), and its fall state is
                -- the landing death bill. While the seat owns her, no fall-family action may run.
                -- Gate is S.route3_air_seat_on, which release() drops BEFORE the ground placement
                -- + latch, so the touchdown latch actions pass untouched.
                if S.route3_air_seat_on == true then
                    -- v16: our own neutral-action eviction request must pass untouched
                    if S.route3_self_action == true then return sdk.PreHookResult.CALL_ORIGINAL end
                    local lo2 = node:lower()
                    if lo2:find("fall", 1, true) or lo2:find("land", 1, true)
                        or lo2:find("cling", 1, true) or lo2:find("climb", 1, true) then
                        S.route3_air_fall_veto = (tonumber(S.route3_air_fall_veto) or 0) + 1
                        S.route3_air_fall_veto_last = node
                        S.route3_air_fall_veto_at = os.clock()
                        return sdk.PreHookResult.SKIP_ORIGINAL
                    end
                end
                if S.native_climb_mount then
                    local rider_blocked = false
                    if C.native_climb_block_player_actions then
                        if C.native_climb_block_all_player_actions == true then
                            -- hard rider lock: only the climb/grip family may act
                            rider_blocked = not action_matches_patterns(node, C.native_climb_player_allow_patterns)
                        else
                            rider_blocked = action_matches_patterns(node, C.native_climb_player_block_patterns)
                        end
                    end
                    if rider_blocked then
                        S.blocked_player_actions = S.blocked_player_actions + 1
                        S.last_blocked_action = node
                        local lo = node:lower()
                        if lo:find("jump", 1, true) or lo:find("jmp", 1, true) then
                            S.jump_request = true
                        end
                        return sdk.PreHookResult.SKIP_ORIGINAL
                    end
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if C.block_player_actions and (C.block_all_player_actions or action_matches_patterns(node, C.block_player_action_patterns)) then
                    S.blocked_player_actions = S.blocked_player_actions + 1
                    S.last_blocked_action = node
                    local lo = node:lower()
                    if lo:find("jump", 1, true) or lo:find("jmp", 1, true) then
                        S.jump_request = true
                    end
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
                return sdk.PreHookResult.CALL_ORIGINAL
            end

            if same_obj(owner_ch, S.route3_proxy) then
                S.route3_proxy_action = node
                table.insert(S.route3_proxy_action_history, 1, tostring(node))
                while #S.route3_proxy_action_history > 8 do table.remove(S.route3_proxy_action_history) end
                if route3_proxy_action_is_attack(node) then
                    S.route3_proxy_attack_count = (tonumber(S.route3_proxy_attack_count) or 0) + 1
                    S.route3_proxy_last_attack_at = os.clock()
                end
                return sdk.PreHookResult.CALL_ORIGINAL
            end

            if same_obj(owner_ch, S.griffin) then
                S.last_griffin_action = node
                if griffin_predation_window_active() then
                    S.last_flight_control_allowed_action = "PRED:" .. tostring(node)
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if S.route3_unleashed == true then
                    -- FULL COMBAT: her native AI owns every action — fly,
                    -- swoop, grab. Block NOTHING.
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if S.route3_self_action == true then
                    -- OUR request (swing/driver): always passes
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if S.companion_order == "attack" then
                    -- DRIVER MODE: her own action layer is silenced — its
                    -- OverwriteDefault spam was yanking the forced attack
                    -- node back to Wait. The driver owns the body; never
                    -- wipe the fury here.
                    S.blocked_griffin_actions = (tonumber(S.blocked_griffin_actions) or 0) + 1
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
                if C.log_griffin_actions then
                    local layer, priority = 0, 0
                    pcall(function() priority = sdk.to_int64(args[3]) & 0xffffffff end)
                    pcall(function() layer = sdk.to_int64(args[5]) & 0xffffffff end)
                    table.insert(S.griffin_action_history, 1, string.format("%s p=%s l=%s", node, tostring(priority), tostring(layer)))
                    while #S.griffin_action_history > 8 do table.remove(S.griffin_action_history) end
                end
                -- NATURAL-THROW window (Lyra's find: these blockers -- patterns incl grb/pin/
                -- hold_attack/fall -- were cancelling the CATCH's own actions during every catch
                -- experiment = poisoned trials). While the NT catch/release runs, let her actions
                -- through so the native catch can actually establish.
                if os.clock() < (tonumber(S.nt_allow_actions_until) or 0.0) then
                    S.last_flight_control_allowed_action = "NT:" .. tostring(node)
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                local block_all_griffin_actions = C.block_all_griffin_actions
                if S.native_climb_mount and C.native_climb_allow_non_hostile_griffin_actions then
                    block_all_griffin_actions = false
                end
                if S.native_climb_mount and native_climb_uses_flight_control()
                    and C.flight_control_allow_actions
                    and action_matches_patterns(node, C.flight_control_allow_action_patterns) then
                    S.flight_control_allowed_actions = S.flight_control_allowed_actions + 1
                    S.last_flight_control_allowed_action = node
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if S.native_climb_mount and C.native_climb_nav_pulse_allow_actions and nav_pulse_active(os.clock())
                    and action_matches_patterns(node, C.native_climb_nav_pulse_allow_patterns) then
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                -- native flight animation: the live FSM needs its own fly/hover
                -- transitions to pass, otherwise the griffin freezes mid-pose
                if C.route3_native_flight_anim == true and S.airborne == true
                    and action_matches_patterns(node, C.route3_native_flight_allow_patterns) then
                    S.flight_control_allowed_actions = (S.flight_control_allowed_actions or 0) + 1
                    S.last_flight_control_allowed_action = node
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if C.block_griffin_mounted_actions and (block_all_griffin_actions or action_matches_patterns(node, C.block_griffin_action_patterns)) then
                    S.blocked_griffin_actions = S.blocked_griffin_actions + 1
                    clear_griffin_hate()
                    clear_griffin_targets()
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end

            if S.mounted and C.block_party_griffin_actions == true and is_player_or_party(owner_ch) then
                local dist = character_distance_to_griffin(owner_ch, owner_go)
                if dist and dist <= (tonumber(C.block_npc_griffin_alert_distance) or 45.0)
                    and action_matches_patterns(node, C.block_party_griffin_action_patterns) then
                    S.npc_griffin_alert_blocks = (S.npc_griffin_alert_blocks or 0) + 1
                    S.last_npc_griffin_alert_block = "party " .. tostring(node)
                    clear_character_hate(owner_ch, owner_go)
                    clear_party_hate()
                    clear_griffin_hate()
                    clear_griffin_targets()
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end

            if C.friendly_to_world and S.route3_unleashed ~= true and should_block_npc_griffin_alert(owner_ch, owner_go, node) then
                if S.companion_order == "attack" then
                    -- ordered combat: the TARGET fights completely free;
                    -- bystander NPCs stay becalmed as usual — but WITHOUT
                    -- the side-effect wipe of HER hate/targets (that wipe
                    -- yanked her to idle whenever anything nearby reacted)
                    if S.companion_target_go and owner_go and same_obj(owner_go, S.companion_target_go) then
                        return sdk.PreHookResult.CALL_ORIGINAL
                    end
                    S.npc_griffin_alert_blocks = (S.npc_griffin_alert_blocks or 0) + 1
                    S.last_npc_griffin_alert_block = node
                    clear_character_hate(owner_ch, owner_go)
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
                S.npc_griffin_alert_blocks = (S.npc_griffin_alert_blocks or 0) + 1
                S.last_npc_griffin_alert_block = node
                -- r100: surface it. Aurora is right that enemies clearly DO
                -- attack sometimes, so the honest question is which of their
                -- actions we are eating -- name the node rather than argue.
                _G.IrisAlertBlocks = (tonumber(rawget(_G, "IrisAlertBlocks")) or 0) + 1
                _G.IrisAlertLastNode = tostring(node)
                clear_character_hate(owner_ch, owner_go)
                clear_griffin_hate()
                clear_griffin_targets()
                return sdk.PreHookResult.SKIP_ORIGINAL
            end

            return sdk.PreHookResult.CALL_ORIGINAL
        end,
        nil
    )
end

-- (GLOBAL on purpose: the main chunk sits AT Lua's 200-local cap -- adding any file-scope
-- local now breaks the parse; this one tipped over when the file grew on 2026-07-15)
iris_player_input_update_method = nil
pcall(function()
    iris_player_input_update_method = sdk.find_type_definition("app.PlayerInputProcessor"):get_method("update()")
end)

if iris_player_input_update_method then
    sdk.hook(iris_player_input_update_method,
        function(args)
            -- SCOUT DRONE also starves player input at the source (S.scout_mode): while the
            -- player pilots the bird, NO button reaches the Arisen OR the UI. This is the strict
            -- "unaffected by any button" bar the downstream think-stop can't meet on its own.
            local scout_block = S.scout_mode == true
            if not (scout_block or (C.enabled and S.native_climb_mount and C.native_climb_suppress_player_control and C.native_climb_skip_player_input_update)) then
                return sdk.PreHookResult.CALL_ORIGINAL
            end

            local this = nil
            pcall(function() this = sdk.to_managed_object(args[2]) end)
            local player_processor = get_player_input_processor()
            if player_processor and this and not same_obj(this, player_processor) then
                return sdk.PreHookResult.CALL_ORIGINAL
            end

            S.player_input_skip_hits = S.player_input_skip_hits + 1
            S.last_player_input_skip = player_processor and "player processor" or "all processors"
            return sdk.PreHookResult.SKIP_ORIGINAL
        end,
        nil
    )
end

if hate_add_method then
    sdk.hook(hate_add_method,
        function(args)
            if not (C.enabled and (C.block_party_hate or C.block_npc_griffin_hate)
                and (S.griffin ~= nil or next(mounts) ~= nil or S.route3_proxy ~= nil)) then
                return sdk.PreHookResult.CALL_ORIGINAL
            end
            local hs, target_go = nil, nil
            pcall(function()
                hs = sdk.to_managed_object(args[2])
                target_go = sdk.to_managed_object(args[3])
            end)
            if not (hs and target_go) then return sdk.PreHookResult.CALL_ORIGINAL end
            local target_ch = get_component(target_go, "app.Character")

            if griffin_predation_window_active() then
                local selected = S.companion_target
                local selected_go = S.companion_target_go or (selected and char_go(selected))
                -- Keep the party shield, but permit the exact predator/prey
                -- hate directions while native control owns the body.
                if same_obj(hs, griffin_hate_system())
                    and (same_obj(target_ch, selected) or same_obj(target_go, selected_go)) then
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
                if same_obj(target_ch, S.griffin) or same_obj(target_go, S.griffin_go) then
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
            end

            -- Wild-combat proxy safety: the proxy may run native AI, but it
            -- must never select the player/pawns as prey, and party hate
            -- toward the proxy should be discarded too.
            if S.route3_proxy then
                local proxy_hs = route3_proxy_hate_system()
                if same_obj(hs, proxy_hs) and is_player_or_party(target_ch) then
                    S.route3_proxy_status = "proxy=blocked party target"
                    clear_character_hate(S.route3_proxy, S.route3_proxy_go)
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
                if (same_obj(target_ch, S.route3_proxy) or same_obj(target_go, S.route3_proxy_go))
                    and route3_party_hate_system(hs) then
                    S.route3_proxy_status = "proxy=blocked party hate"
                    pcall(function() hs:call("clearAllHate") end)
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end

            -- ordered/unleashed combat: hate flows naturally in both directions
            if S.companion_order == "attack" or S.route3_unleashed == true then return sdk.PreHookResult.CALL_ORIGINAL end
            -- ⭐⭐⭐ 08-09 r84 -- THIS IS WHY THE CYCLOPS WILL NOT FIGHT YOU.
            -- (Aurora: "the cyclops is swinging RIGHT on me and the horse but no
            -- damage... when I kick a newly spawned cyclops with the horse it
            -- doesn't aggro at all.")
            -- The branch below fires whenever anything tries to hate the active
            -- companion -- INCLUDING the horse you are sitting on -- and its
            -- response is `hs:clearAllHate()`. Not "forget the horse": forget
            -- EVERYTHING. So the moment a cyclops registers the mount, its whole
            -- hate list is wiped and it loses you along with it. Kick it and the
            -- aggro is deleted in the same breath. It swings on momentum and
            -- commits to nothing, and neither of you is ever a target.
            -- ⭐ A mount you are RIDING is a legitimate target -- that is the
            -- entire premise of the downed/revive system we have been building.
            -- The pacify shield still protects a companion you are NOT on.
            if C.route3_companion_can_be_attacked == true
                or C.route3_mounted_combat ~= false then
                local ridden_now = false
                pcall(function()
                    local api = rawget(_G, "IrisHorseMount")
                    ridden_now = api and api.is_mounted
                        and api.is_mounted() == true
                end)
                if C.route3_companion_can_be_attacked == true or ridden_now then
                    -- r86: COUNT the exemption. If the cyclops still cannot
                    -- fight and this counter is 0, the hook is not reaching
                    -- here (stacked stale closures, or hate never routed
                    -- through this method at all) -- which is a completely
                    -- different hunt from "the exemption is wrong".
                    _G.IrisMountedHateAllowed =
                        (tonumber(rawget(_G, "IrisMountedHateAllowed")) or 0) + 1
                    return sdk.PreHookResult.CALL_ORIGINAL
                end
            end
            if same_obj(target_ch, S.griffin) or same_obj(target_go, S.griffin_go) or (target_ch and mounts[target_ch] == true) then
                if C.block_npc_griffin_hate == true then
                    S.npc_griffin_hate_blocks = (S.npc_griffin_hate_blocks or 0) + 1
                    S.last_npc_griffin_hate_block = "incoming hate to griffin"
                    pcall(function() hs:call("clearAllHate") end)
                end
                clear_griffin_hate()
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            if same_obj(hs, griffin_hate_system()) then
                if C.friendly_to_world or is_player_or_party(target_ch) then
                    if C.block_npc_griffin_hate == true then
                        S.npc_griffin_hate_blocks = (S.npc_griffin_hate_blocks or 0) + 1
                        S.last_npc_griffin_hate_block = "griffin hate write"
                    end
                    clear_griffin_hate()
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end
            return sdk.PreHookResult.CALL_ORIGINAL
        end,
        nil
    )
end

re.on_application_entry("UpdateBehavior", function()
    S.world_paused = griffin_world_paused()
    if griffin_world_sentry() ~= true then return end
    if S.spawner then
        pcall(function()
            S.spawner:updateInstanceCounts()
            S.spawner:requestSpawnOutstanding()
            if S.spawner:hasAnyOutstandingPostProc() then S.spawner:processPostProc() end
        end)
    end

    -- Adoption waits for play to resume. spawn_griffin already refuses to REQUEST a body while
    -- paused, but one requested a moment before the menu opened can still finish constructing
    -- during it -- and register_griffin is the heavy part (scale snap, pacify, ally context,
    -- component pokes) on a character the engine has not finished building. Holding the
    -- adoption costs a frame or two and takes that whole window away.
    if S.pending_spawn and not S.world_paused then
        local ch = nil
        pcall(function()
            local inst = S.spawner and S.spawner.instances and S.spawner.instances[1]
            ch = inst and inst.instance and inst.instance:get_Chara()
        end)
        if ch then
            S.pending_spawn = false
            register_griffin(ch)
        end
    end

    if S.critter_spawner then
        pcall(function()
            S.critter_spawner:updateInstanceCounts()
            S.critter_spawner:requestSpawnOutstanding()
            if S.critter_spawner:hasAnyOutstandingPostProc() then S.critter_spawner:processPostProc() end
        end)
    end
    if S.wild_spawner then
        pcall(function()
            S.wild_spawner:updateInstanceCounts()
            S.wild_spawner:requestSpawnOutstanding()
            if S.wild_spawner:hasAnyOutstandingPostProc() then S.wild_spawner:processPostProc() end
        end)
    end
    if S.route3_proxy_spawner then
        pcall(function()
            S.route3_proxy_spawner:updateInstanceCounts()
            S.route3_proxy_spawner:requestSpawnOutstanding()
            if S.route3_proxy_spawner:hasAnyOutstandingPostProc() then S.route3_proxy_spawner:processPostProc() end
        end)
        if S.route3_proxy_pending == true then
            local ch = nil
            pcall(function()
                local inst = S.route3_proxy_spawner.instances and S.route3_proxy_spawner.instances[1]
                ch = inst and inst.instance and inst.instance:get_Chara()
            end)
            if ch then
                S.route3_proxy = ch
                S.route3_proxy_go = char_go(ch)
                S.route3_proxy_pending = false
                S.route3_proxy_status = "proxy=live"
                route3_proxy_force_hate(ch, S.route3_proxy_target)
            end
        end
    end
    if S.pending_critter_spawn then
        local ch = nil
        pcall(function()
            local inst = S.critter_spawner and S.critter_spawner.instances and S.critter_spawner.instances[#S.critter_spawner.instances]
            ch = inst and inst.instance and inst.instance:get_Chara()
        end)
        if ch then register_critter_reference(ch) end
    end
    -- NEVER re-run the pacify/neutralise stack while UNLEASHED: it disables her
    -- AIDecisionMaker/NavigationAI/RetargetController + clears hate/targets every
    -- 0.5s, which would hard-kill a native hunt mid-fight. (Unguarded footgun found
    -- in the 2026-07-05 pursuit investigation.)
    if C.critter_neutralise_each_tick == true and S.griffin and S.critter and S.route3_unleashed ~= true
        and not griffin_predation_window_active() then
        local now = os.clock()
        if now - (tonumber(S.last_critter_neutral_clock) or 0.0) >= (tonumber(C.critter_neutralise_interval) or 0.5) then
            pcall(function() apply_critter_neutrality() end)
        end
    end

    if not C.drive_in_late_update then safe_run("flight_tick/update", function() flight_tick("UpdateBehavior") end) end
    -- ⭐⭐ GROUNDED DOGFIGHT TICK (2026-08-07, tape 18:18: a 3.9s SAMPLE GAP right after the
    -- skid touchdown -- flight_tick bails on `not S.flying`, and route3_finish_landing at the
    -- strike clears exactly that flag, so the grounded skid's own driver froze mid-ride: no
    -- slide, clip ran out into a statue, then the deferred landing recover "woke" her 3.6s
    -- later = Aurora's "stays still for a while, jumps again, then idles". The dogfight ride
    -- must keep ticking on the GROUND: same call, stick already zeroed by the ride state.)
    safe_run("dogfight_ground_tick", function()
        if griffin_dogfight_active() and S.mounted == true and S.flying ~= true then
            local ch2, go2 = reacquire_griffin()
            if ch2 and go2 then route3_dogfight_tick(ch2, go2, os.clock()) end
        end
    end)
    safe_run("griffin_bones_pump", griffin_bones_pump)   -- eat-remains gimmick spawner (inert when idle)
    safe_run("griffin_civilian_hate_shield", griffin_civilian_hate_shield)   -- bystanders never grudge her
    safe_run("adjust_terrain_flight_guard", function()
        -- the skid leaves AdjustTerrain (terrain snap) ON for a grounded end -- the moment she
        -- goes airborne again it must come off, or the snap glues the flyer to the ground
        if S.route3_adj_grounded_on == true and S.airborne == true then
            S.route3_adj_grounded_on = nil
            local ch2 = reacquire_griffin()
            local adj = ch2 and ch2:get_field("<AdjustTerrain>k__BackingField")
            if adj then adj:call("setEnable", false) end
        end
    end)
    safe_run("route3_rider_immunity_guard", route3_rider_immunity_guard)
    safe_run("griffin_probe_fc_tick", griffin_probe_fc_tick)   -- inert unless the FC probe is armed
    safe_run("griffin_probe_verify_tick", griffin_probe_verify_tick) -- deferred node-slot read
    safe_run("route3_rider_cam_distance_tick", route3_rider_cam_distance_tick)
    safe_run("griffin_rider_engage_gate_tick", griffin_rider_engage_gate_tick)
    -- ROUND-51c/d: jack-camera probe SERIES -- one dump per authored tracking shot
    -- across an ox-cart ride. The player-jacked signal now comes from the
    -- InteractButton mod's hooks via _G.InteractButton_player_jacked_at (the jack
    -- system itself moved to autorun/InteractButton.lua).
    safe_run("griffin_jack_cam_probe", function()
        local jacked_at = tonumber(_G.InteractButton_player_jacked_at)
        if jacked_at and jacked_at ~= tonumber(S.route3_jack_cam_seen)
            and os.clock() >= (tonumber(S.route3_jack_cam_cool) or 0.0) then
            S.route3_jack_cam_seen = jacked_at
            S.route3_jack_cam_cool = os.clock() + 45.0
            S.route3_jack_cam_queue = {
                { at = jacked_at + 2.5,  label = "jack_a" },
                { at = jacked_at + 8.0,  label = "jack_b" },
                { at = jacked_at + 15.0, label = "jack_c" },
                { at = jacked_at + 25.0, label = "jack_d" },
            }
        end
        local q = S.route3_jack_cam_queue
        if type(q) ~= "table" or #q == 0 then return end
        local now = os.clock()
        if now >= (tonumber(q[1].at) or 0.0) then
            local entry = table.remove(q, 1)
            pcall(griffin_camera_probe, tostring(entry.label))
        end
    end)
    safe_run("griffin_camrec_tick", griffin_camrec_tick)
    safe_run("griffin_saddle_pump_tick", griffin_saddle_pump_tick)
end)

re.on_application_entry("LateUpdateBehavior", function()
    if S.route3_world_live ~= true then return end
    safe_run("route3_wilds_rider_pose_tick", route3_wilds_rider_pose_tick)
    -- Apply the ox grip to Motion's calculated skeleton after UpdateMotion while
    -- Catch/Caught retain full native ownership. Transform-joint writes are
    -- rebuilt before skinning and do not own the rendered Ch253 pose.
    safe_run("griffin_predation_apply_grip_pose_late", function()
        griffin_predation_apply_grip_pose_late(true, "late")
    end)
    -- glue a grab-carried body to the ANIMATED talon joint AFTER UpdateMotion (kills the
    -- carry displacement/jitter that came from pinning off the griffin ROOT a frame early)
    safe_run("route3_grab_pin_late", route3_grab_pin_late)
    safe_run("griffin_predation_pin_late", griffin_predation_pin_late)
    if C.drive_in_late_update then safe_run("flight_tick/late", function() flight_tick("LateUpdateBehavior") end) end
    safe_run("route3_air_authority_tick", route3_air_authority_tick)
    -- This MUST be after flight_tick and air authority. The previous order locked the rider
    -- to Iris's OLD position and then moved Iris, so the Arisen visibly stayed behind.
    griffin_rise_stage("LATE: authority returned -> rider_pin_late")
    if S.mounted == true then safe_run("route3_rider_pin_late", route3_rider_pin_late) end
    -- Same frame slot, same reason: the pawn's climb Follower also settles after ordinary ticks,
    -- so her seat write has to land here or it is overwritten before anything renders.
    safe_run("griffin_pawn_seat_follow_late", griffin_pawn_seat_follow_late)
    safe_run("griffin_ride_hud_tick", griffin_ride_hud_tick)   -- re-assert prompt labels every frame
    griffin_rise_stage("LATE: rider_pin_late OK -> saddle_follow")
    -- ROUND-56: the jack-mount saddle rides the neck AFTER the flight drive moved her
    safe_run("griffin_saddle_follow_tick", griffin_saddle_follow_tick)
    griffin_rise_stage("LATE: saddle_follow OK -> wing_capture")
    safe_run("route3_wing_capture_tick/late", function() route3_wing_capture_tick_phase(os.clock(), "late") end)
    griffin_rise_stage("LATE: wing_capture OK -> wing_replay")
    safe_run("route3_apply_captured_wing_replay/late", function() route3_apply_captured_wing_replay(os.clock(), "late") end)
    griffin_rise_stage("LATE: wing_replay OK -> wing_snapshot_hold")
    safe_run("route3_apply_wing_snapshot_hold/late", function() route3_apply_wing_snapshot_hold(os.clock()) end)
    griffin_rise_stage("LATE: wing_snapshot_hold OK -> fc_probe")
    safe_run("native_flight_control_probe/late", function()
        if native_flight_control_probe_tick then native_flight_control_probe_tick(os.clock()) end
    end)
    griffin_rise_stage("LATE: hook COMPLETE -- frame survived LateUpdateBehavior")
end)

re.on_application_entry("UpdateMotion", function()
    if S.route3_world_live ~= true then return end
    safe_run("route3_wing_capture_tick", function() route3_wing_capture_tick(os.clock()) end)
    safe_run("route3_apply_captured_wing_replay", function() route3_apply_captured_wing_replay(os.clock(), "motion") end)
    safe_run("route3_apply_wing_joint_pose", route3_apply_wing_joint_pose)
    -- Ch253 may paint AddBringOx at either side of UpdateMotion depending on the
    -- active node. Assert here as well as LateUpdate/on_frame; capture itself is
    -- deliberately disabled at this ambiguous boundary.
    safe_run("griffin_predation_apply_grip_pose_motion", function()
        griffin_predation_apply_grip_pose_late(false, "motion")
    end)
end)

-- Native climb/collision can write the Arisen after LateUpdateBehavior.  Pin the visual GameObject
-- at the final render boundary as well, matching the proven timing used by rs_anim_lab's bone
-- overlay.  Character/controller state is deliberately untouched here.
re.on_application_entry("PrepareRendering", function()
    if S.route3_world_live == true and S.mounted == true then
        safe_run("route3_rider_pin_render", route3_rider_pin_late)
    end
end)

-- ⭐ ROUND-41: THE RESCUER = app.CharacterPosRotContextRollbacker (round-40 placement
-- data: she's returned ~143m BACK ALONG THE FLIGHT PATH at flight altitude -- a
-- position ROLLBACK, not a warp-to-ground). Hook every rollback-shaped method on the
-- class and SKIP it while the ride pose is active; also dump the full method surface
-- of the PosRot apparatus to the log so a miss can be corrected from its real API.
do
    pcall(function()
        for _, cls in ipairs({ "app.CharacterPosRotContextRollbacker",
                               "app.CharacterPosRotContextRecorder",
                               "app.CharacterPosRotAdjuster" }) do
            local td = sdk.find_type_definition(cls)
            if td then
                local names = {}
                for _, m in ipairs(td:get_methods()) do
                    names[#names + 1] = tostring(m:get_name()) .. "/" .. tostring(m:get_num_params())
                end
                log.info("[GriffinRide] " .. cls .. " methods: " .. table.concat(names, ", "))
            end
        end
    end)
    pcall(function()
        local td = sdk.find_type_definition("app.CharacterPosRotContextRollbacker")
        if not td then log.info("[GriffinRide] Rollbacker type NOT FOUND"); return end
        local hooked = {}
        for _, m in ipairs(td:get_methods()) do
            local n = tostring(m:get_name() or "")
            local lo = n:lower()
            if lo:find("rollback", 1, true) or lo:find("restore", 1, true)
                or lo:find("warp", 1, true) or lo:find("request", 1, true) then
                pcall(function()
                    sdk.hook(m, function(args)
                        -- scoped to HER instance (round-45: the unscoped version
                        -- blocked every character's safety net -- 32k calls/ride)
                        -- 07-24: also armed while the IRIS puppet seat rides
                        if S.route3_rider_puppet_on ~= true
                            and iris_puppet_seat_active() ~= true then return end
                        local ok, addr = pcall(function()
                            return sdk.to_managed_object(args[2]):get_address()
                        end)
                        if ok and addr == S.route3_rb_addr then
                            S.route3_rider_rollback_blocked = (tonumber(S.route3_rider_rollback_blocked) or 0) + 1
                            return sdk.PreHookResult.SKIP_ORIGINAL
                        end
                    end, function(retval) return retval end)
                    hooked[#hooked + 1] = n
                end)
            end
        end
        log.info("[GriffinRide] Rollbacker skip-hooks installed on: "
            .. (#hooked > 0 and table.concat(hooked, ", ") or "(none matched)"))
    end)
    -- ROUND-42: the rescue is TWO-headed. Skipping the Rollbacker shrank the jumps
    -- from 197m to ~13m -- the remainder is the RECORDER's own safe-coord restore
    -- (both placements at the IDENTICAL ground point = a stored safe coord;
    -- restoreCoordFromHistory in its method surface). Skip that head too.
    pcall(function()
        local td = sdk.find_type_definition("app.CharacterPosRotContextRecorder")
        if not td then return end
        local hooked = {}
        for _, mn in ipairs({ "restoreCoordFromHistory", "checkAfterReviveFromFallDead",
                              "invalidateAroundStandableOnAir" }) do
            local m = td:get_method(mn)
            if m then
                pcall(function()
                    sdk.hook(m, function(args)
                        -- 07-24: also armed while the IRIS puppet seat rides
                        if S.route3_rider_puppet_on ~= true
                            and iris_puppet_seat_active() ~= true then return end
                        local ok, addr = pcall(function()
                            return sdk.to_managed_object(args[2]):get_address()
                        end)
                        if ok and addr == S.route3_rec_addr then
                            S.route3_rider_rollback_blocked = (tonumber(S.route3_rider_rollback_blocked) or 0) + 1
                            return sdk.PreHookResult.SKIP_ORIGINAL
                        end
                    end, function(retval) return retval end)
                    hooked[#hooked + 1] = mn
                end)
            end
        end
        log.info("[GriffinRide] Recorder skip-hooks installed on: "
            .. (#hooked > 0 and table.concat(hooked, ", ") or "(none matched)"))
    end)
end

-- MOUNT CAMERA hook: post-hook the main camera controller so our chase pose is the
-- final word each frame (the IrisCreatureCam recipe; callback self-gates on mounted)
do
    pcall(function()
        local td = sdk.find_type_definition("app.MainCameraController")
        local m = td and td:get_method("lateUpdate")
        if m then
            sdk.hook(m, function() end, function(retval)
                pcall(griffin_mount_camera_apply)
                return retval
            end)
        end
    end)
end

-- ================== ROUND-47: TRANSFORM-WRITE INTERCEPT (TXI) ==================
-- After 45 rounds every NAMED system is dead-and-verified-dead and something still
-- repositions the posed rider ~150x/ride (>1.5m micro-jumps) between pin passes.
-- The pin already re-writes the seat at LateUpdateBehavior + PrepareRendering, so
-- the rendered body is likely fine -- the damage is MID-FRAME: camera solve,
-- occlusion fade, proximity events and the audio listener all sample the mover's
-- position before our late fix. Cure = the bad write must never LAND: hook the
-- position setters themselves, scoped to HER addresses, and SKIP anything not
-- flagged as ours (S.route3_our_write -- set inside set_transform /
-- set_character_transform and around the pin's direct logical write; rs_anim_lab is
-- unaffected -- it writes JOINT locals, never the transform position).
-- Work-order review rulings baked in: hooks install LAZILY at first puppet engage
-- (sdk.hook is permanent -- no game-wide tax before the first ride);
-- set_UniversalPosition only by default (set_Position = config opt-in, hot);
-- addresses refreshed every pin pass (stale-address block = worse than the storm);
-- EXPECTED OUTCOMES: blocked>0 + storm gone = cured & mover identified by its
-- attempted coordinates; blocked=0 + storm = the mover writes natively (no managed
-- call) -> read the recon dump (SaveCoordOnUnsafeHandler) and hunt its class.
function griffin_txi_install()
    if S.route3_txi_installed == true then return end
    S.route3_txi_installed = true
    local installed = {}
    local function txi_hook(td_name, m_name, tag, vt_name)
        pcall(function()
            -- ROUND-49: walk parent types -- td:get_method does NOT see inherited
            -- methods (app.Character's set_UniversalPosition lives on a base class;
            -- round-48 field: that hook silently never installed)
            local td = sdk.find_type_definition(td_name)
            local m = nil
            while td and not m do
                m = td:get_method(m_name)
                if not m then td = td:get_parent_type() end
            end
            if not m then return end
            sdk.hook(m, function(args)
                if S.route3_txi_live ~= true then return end
                if S.route3_our_write == true then return end
                local ok, addr = pcall(function()
                    return sdk.to_managed_object(args[2]):get_address()
                end)
                if not ok or addr == nil then return end
                if addr ~= S.route3_txi_tf_addr and addr ~= S.route3_txi_ch_addr then return end
                S.route3_txi_blocked = (tonumber(S.route3_txi_blocked) or 0) + 1
                if S.route3_txi_blocked % 25 == 1 then
                    local px, py, pz = nil, nil, nil
                    pcall(function()
                        local v = sdk.to_valuetype(args[3], vt_name or "via.Position")
                        if v then px, py, pz = tonumber(v.x), tonumber(v.y), tonumber(v.z) end
                    end)
                    pcall(function() log.info(string.format(
                        "[GriffinRide] TXI blocked #%d %s -> (%s, %s, %s)",
                        S.route3_txi_blocked, tag,
                        px and string.format("%.1f", px) or "?",
                        py and string.format("%.1f", py) or "?",
                        pz and string.format("%.1f", pz) or "?")) end)
                end
                return sdk.PreHookResult.SKIP_ORIGINAL
            end, function(retval) return retval end)
            installed[#installed + 1] = tag
        end)
    end
    txi_hook("via.Transform", "set_UniversalPosition", "tf.set_UniversalPosition", "via.Position")
    txi_hook("app.Character", "set_UniversalPosition", "ch.set_UniversalPosition", "via.Position")
    -- ROUND-49: set_Position hook now DEFAULT ON -- with her CharacterController
    -- component disabled, the engine's move-apply path plausibly falls back to the
    -- plain transform setter: the one door round-47 left open (perf-ruling). The
    -- checkbox below the TXI one is the kill-switch if frames drop.
    if C.route3_rider_txi_setpos ~= false then
        txi_hook("via.Transform", "set_Position", "tf.set_Position", "via.vec3")
    end
    S.route3_txi_hooks = (#installed > 0) and table.concat(installed, ", ") or "(none matched!)"
    pcall(function() log.info("[GriffinRide] TXI hooks installed: " .. S.route3_txi_hooks) end)
end

function griffin_txi_recon_dump(player)
    -- one-shot per engage: name the rescue EXECUTOR's class (round-43: the actual
    -- mover is a HANDLER registered via setSaveCoordOnUnsafeHandler) + x-ray the
    -- Recorder's landing/ground sub-objects for the FALL-BILL state (the landing
    -- death accumulates somewhere in here -- future per-tick clear kills it at the
    -- source). Log-only; the storm decode reads this if TXI blocks nothing.
    pcall(function()
        local rec = player:get_field("<PosRotRecorder>k__BackingField")
        if not rec then
            pcall(function() log.info("[GriffinRide] recon: no PosRotRecorder field") end)
            return
        end
        local function fmt_val(v)
            if v == nil then return "nil" end
            local okv, s = pcall(function()
                local x, y, z = v.x, v.y, v.z
                if x ~= nil and y ~= nil and z ~= nil then
                    return string.format("(%.1f,%.1f,%.1f)", tonumber(x) or 0, tonumber(y) or 0, tonumber(z) or 0)
                end
                return nil
            end)
            if okv and s then return s end
            return tostring(v)
        end
        local function dump_obj(label, obj, dump_all)
            local td = obj:get_type_definition()
            if not td then return end
            local names = {}
            for _, m in ipairs(td:get_methods()) do
                names[#names + 1] = tostring(m:get_name()) .. "/" .. tostring(m:get_num_params())
            end
            pcall(function() log.info(string.format("[GriffinRide] recon %s type=%s methods: %s",
                label, tostring(td:get_full_name()), table.concat(names, ", "))) end)
            local fl = {}
            for _, f in ipairs(td:get_fields()) do
                local fn = tostring(f:get_name())
                local lo = fn:lower()
                if dump_all == true
                    or lo:find("fall", 1, true) or lo:find("height", 1, true) or lo:find("air", 1, true)
                    or lo:find("ground", 1, true) or lo:find("land", 1, true) or lo:find("safe", 1, true) then
                    local v = nil
                    pcall(function() v = obj:get_field(fn) end)
                    fl[#fl + 1] = fn .. "=" .. fmt_val(v)
                end
            end
            if #fl > 0 then
                pcall(function() log.info("[GriffinRide] recon " .. label .. " fields: "
                    .. table.concat(fl, " | ")) end)
            end
        end
        for _, fname in ipairs({
            "SaveCoordOnUnsafeHandler", "<SaveCoordOnUnsafeHandler>k__BackingField",
            "LandingProcessor", "<LandingProcessor>k__BackingField",
            "GroundDetector", "<GroundDetector>k__BackingField",
            "Jack", "<Jack>k__BackingField",
        }) do
            local obj = nil
            pcall(function() obj = rec:get_field(fname) end)
            if obj ~= nil then
                pcall(dump_obj, fname, obj)
                -- ROUND-48: the round-47 dump surfaced the FALL apparatus living on the
                -- LandingProcessor (FallInfo = the fall BILL; FallingStuckStopper /
                -- FallPreventer = the storm's rescue machinery) -- x-ray their FULL
                -- field sets so the bill's exact fields are on tape.
                if fname == "LandingProcessor" or fname == "<LandingProcessor>k__BackingField" then
                    for _, sub in ipairs({ "FallInfo", "FallingStuckStopper", "FallPreventer" }) do
                        local so = nil
                        pcall(function() so = obj:get_field(sub) end)
                        if so ~= nil then pcall(dump_obj, fname .. "." .. sub, so, true) end
                    end
                end
            end
        end
    end)
end

function griffin_rider_fall_kill_tick(seat)
    -- ⭐ ROUND-48: THE STORM DECODED FROM THE DIRECTION LOGS -- every micro-jump on
    -- every ride was (0, -1.5..-2.5, 0): a pure-vertical FALL STEP at terminal-ish
    -- velocity. The rider is in a perpetual native FALLING state the whole flight
    -- (no ground under a puppet at altitude): the fall step drags her down each
    -- frame, the pin drags her back = the vibration; the stuck-fall machinery fires
    -- its rescues/fades; and at touchdown FallInfo bills the WHOLE flight as one
    -- lethal fall (the landing death -- same apparatus, every symptom).
    -- CURE = make the game believe ground rides just under her feet: feed
    -- LandingProcessor.LastGroundPosition = seat - 0.6m and re-anchor the
    -- FallingStuckStopper to her current position, every pin pass. No native system
    -- is disabled -- this is belief injection, so dismount needs no restore (the
    -- controller re-learns real ground on its first native update).
    -- v17: also runs under the levitate-hold air seat (puppet off, seat on) -- a levitating
    -- rider still needs the ground-belief feed so no rescue/landing bill can wake up.
    if (S.route3_rider_puppet_on ~= true and S.route3_air_seat_on ~= true) or not seat then return end
    local player = get_player()
    if not player then return end
    local rec, lp = nil, nil
    pcall(function() rec = player:get_field("<PosRotRecorder>k__BackingField") end)
    pcall(function() lp = rec and rec:get_field("LandingProcessor") end)
    if not lp then S.route3_rider_fallkill = "no LandingProcessor"; return end
    local fed = false
    pcall(function()
        local g = lp:call("get_LastGroundPosition")
        if g then
            g.x = tonumber(seat.x) or g.x
            g.y = (tonumber(seat.y) or g.y) - 0.6
            g.z = tonumber(seat.z) or g.z
            lp:call("set_LastGroundPosition", g)
            fed = true
        end
    end)
    pcall(function() lp:call("resetFallingStuckStopperToCurrentPosition") end)
    -- ROUND-49: zero the fall BILL directly, per tick (recon named the fields:
    -- app.FallInfoHolder.FallHeight + resetFallHeight/0). Whatever the fall-step
    -- mover turns out to be, the landing can never bill the flight if the meter
    -- reads ~0 every frame.
    local fh = nil
    pcall(function()
        local fi = lp:get_field("FallInfo")
        if fi then
            fh = tonumber(fi:call("get_FallHeight"))
            fi:call("resetFallHeight")
            fi:call("set_FallHeight", 0.0)
        end
    end)
    local stuck = nil
    pcall(function() stuck = lp:call("get_IsFallingStuckStopperActive") end)
    S.route3_rider_fallkill = string.format("ground fed=%s stuckstopper=%s fallheight=%s",
        tostring(fed), tostring(stuck), fh and string.format("%.1f", fh) or "?")
end

-- ============================ MOUNTED SWOOP ATTACK ============================
-- Player-driven dive-strike while flying + mounted. This SIDESTEPS the autonomous
-- combat ceiling entirely: her AI never has to commit to a target -- WE trigger the
-- dive on a button, drive it through the SAME S.route3_air_pos the ride already uses
-- (so native climb keeps the rider on her back), and WE apply the damage to whatever
-- she passes. Fully gated: nothing here runs unless a swoop is active.
function griffin_swoop_active()
    return type(S.route3_swoop) == "table"
end

function griffin_apply_attack_damage(ench, dmg)
    local hc = griffin_target_hit_controller(ench)
    if not hc then S.route3_swoop_last_dmg = "no HitController"; return false end
    dmg = tonumber(dmg) or 250.0
    -- READ hp via the robust multi-getter (enemy hp is usually NOT on get_Hp -- the old
    -- code read 0 there and BAILED before ever dealing damage). Never gate on the read.
    local before = griffin_hp_from_component(hc)
    -- ONE native damage transaction.  The old code called updateDamageHp AND damageProc and then
    -- forced setDamageReaction a third time.  Apart from dealing 2x the configured damage (the
    -- thunder tape showed 300 -> 600), that can leave large enemies held in the first reaction
    -- action until another hit wakes them.  Pipeline is proven; update/direct HP are fallbacks only.
    local ran = false
    pcall(function() if griffin_damage_via_pipeline(hc, dmg) then ran = true end end)
    local after = griffin_hp_from_component(hc)
    if before and after and after >= before then
        pcall(function() if griffin_damage_via_update(hc, dmg) then ran = true end end)
        after = griffin_hp_from_component(hc)
    end
    -- if the real methods didn't move HP, force it down directly on the component we read
    local raw_fallback = false
    if before and after and after >= before then
        local target_hp = math.max(0.0, before - dmg)
        for _, sig in ipairs({
            "setHp(System.Single, System.Boolean, System.Int32)",
            "setHp(System.Single, System.Boolean)",
            "setHp(System.Single)",
            "set_Hp(System.Single)",
            "set_CurrentHitPoint(System.Single)",
        }) do
            pcall(function() hc:call(sig, target_hp, true, 0) end)
        end
        after = griffin_hp_from_component(hc)
        raw_fallback = after and after < before
    end
    -- Native pipeline/update already owns reaction.  Only a raw HP fallback needs a visual nudge.
    if raw_fallback then pcall(function() hc:call("setDamageReaction") end) end
    local dealt = (before and after) and (before - after) or nil
    if dealt and dealt > 0.0 then
        local mx = (hc and griffin_hp_max_from_component(hc)) or math.max(tonumber(before) or 1.0, tonumber(after) or 1.0, 1.0)
        local nowc = os.clock()
        S.route3_hit_hud = {
            name = griffin_display_name(ench),
            before = tonumber(before), after = tonumber(after), max = mx,
            ch = ench, t0 = nowc,
            until_clock = nowc + math.max(0.5, tonumber(C.route3_dogfight_hud_secs) or 2.6),
        }
    end
    S.route3_swoop_last_dmg = string.format("%s  hp %s->%s  dealt=%s  ran=%s",
        tostring(go_name(char_go(ench)) or "?"),
        tostring(before or "?"), tostring(after or "?"), tostring(dealt or "?"), tostring(ran))
    return (dealt ~= nil and dealt > 0.0)
end

function route3_restore_flight_base()
    -- Release the anim suppression AND return the BASE motion layer to her flight glide.
    -- The swoop clip plays on the base layer; if left there it keeps animating her wings
    -- alongside the flap OVERLAY (layer 1) = two wing motions = the doubled wing-beat
    -- ("2 beats per flap"). Restoring the glide clip clears it.
    S.audition_until_clock = 0.0
    -- ⛔⛔ THE BROKEN-SOAR BUG (2026-08-04). This hardcoded bank 0 while the OTHER call site
    -- (route3_cancel_landing) correctly passes C.flap_glide_bank. flap_glide_clip is 501 and
    -- **bank 0 has no clip 501** -- 501 lives in bank 50 (ch53_000_atk_high_altitude_loop).
    -- So every flight-base restore painted a NON-EXISTENT clip, which is the mangled/inverted
    -- body Aurora screenshotted on the sprint-climb. The config key says "bank for the sprint/
    -- soar clip"; honour it here too so the two call sites can never disagree again.
    -- ⚠ The `or 5190` fallback is itself wrong-in-kind (add_pose_F is an ADDITIVE pose, not a
    -- base clip) -- left alone only because flap_glide_clip is always present, so it never fires.
    local glide = math.floor(tonumber(C.flap_glide_clip) or 5190)
    if glide >= 0 then
        pcall(function() play_griffin_motion(glide, tonumber(C.flap_glide_bank) or 0, true) end)
    end
    -- RETURN-PATH HYGIENE (double-flap suspect: it starts only AFTER a grab/divebomb): clear the
    -- L1 overlay and FORGET the flap phase, so the flap system re-establishes its layers from
    -- scratch next tick instead of trusting state that the special action invalidated (a stale
    -- overlay/phase left an extra sound-notifying clip running).
    pcall(function() route3_flap_clear_overlay() end)
    S.route3_flap_phase = nil
    S.route3_soar_dir_clip = nil
end


-- ============================ MOUNTED DIVE BOMB ============================
-- Aurora's replacement for the swoop: a committed vertical plunge. Dive straight down
-- (start 510 -> falling loop 511) until she nears the ground, SLAM (impact+leap 513) with an
-- AoE burst around the point of impact, then recover (515) to flight. GROUND-driven (keeps
-- falling until the floor is under her), so unlike the fixed-arc swoop it always connects.
function griffin_divebomb_active()
    return type(S.route3_divebomb) == "table"
end

function route3_divebomb_can_start()
    if C.route3_divebomb_enabled ~= true then return false end
    if S.mounted ~= true then return false end
    if S.world_paused == true then return false end
    if griffin_divebomb_active() then return false end
    if griffin_swoop_active() or griffin_grab_active() then return false end
    if S.airborne ~= true then return false end   -- it's an aerial plunge; needs height to fall from
    -- REAL height check: S.airborne can read stale-true while sitting on the ground, so also
    -- require she's actually well ABOVE the floor (no ground-level dive bombs).
    local _, go = reacquire_griffin()
    if go then
        local gy = route3_ground_y_robust(go)
        local gp = transform_pos(go)
        if gy and gp and ((tonumber(gp.y) or 0.0) - gy) < (tonumber(C.route3_divebomb_min_launch_height) or 3.0) then
            return false
        end
    end
    local cd = math.max(0.2, tonumber(C.route3_divebomb_cooldown) or 1.6)
    if os.clock() - (tonumber(S.route3_divebomb_cooldown_at) or -999.0) < cd then return false end
    return true
end

function route3_divebomb_start(reason)
    if reason ~= "test" and not route3_divebomb_can_start() then return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    local pos = S.route3_air_pos or transform_pos(go)
    if not pos then return false end
    S.route3_divebomb = {
        t0 = os.clock(),
        last = os.clock(),
        phase = "dive",
        phase_t0 = os.clock(),
        yaw = yaw_from_transform(go) or S.heading_yaw or 0.0,
        entry_y = tonumber(pos.y) or 0.0,
        looped = false,
        hit = {},   -- things already caught in the slam (one hit each)
    }
    -- HOMING: lock onto the nearest hostile so the plunge steers down onto it instead of just
    -- going forward. Re-fetched each frame in the tick (fresh handle); nil = free forward dive.
    if C.route3_divebomb_homing ~= false then
        pcall(function() S.route3_divebomb.target = griffin_find_enemy(tonumber(C.route3_divebomb_home_radius) or 40.0) end)
    end
    S.airborne = true
    -- park the flap/flight-anim systems so the dive clips actually render (same trick as the swoop)
    local bank = math.floor(tonumber(C.route3_divebomb_clip_bank) or 50)
    local sc = math.floor(tonumber(C.route3_divebomb_start_clip) or 510)
    if sc >= 0 then pcall(function() play_griffin_motion(sc, bank, true) end) end
    S.audition_until_clock = os.clock() + 3.0
    local snd = math.floor(tonumber(C.route3_divebomb_dive_sound_id) or 0)
    if snd > 0 then pcall(function() route3_play_wwise_trigger_id(snd, "divebomb") end) end
    S.route3_divebomb_hits = 0
    S.route3_divebomb_status = "dive bomb!"
    status(tostring(C.route3_griffin_name or "Griffin") .. " plunges!")
    return true
end

function route3_divebomb_damage_sweep(go)
    -- ONE AoE burst around her at the point of impact (horizontal reach, like the swoop sweep).
    local st = S.route3_divebomb
    if not (st and go) then return end
    local gpos = transform_pos(go)
    if not gpos then return end
    local r2 = math.max(1.5, tonumber(C.route3_divebomb_radius) or 6.0); r2 = r2 * r2
    local dmg = math.max(1.0, tonumber(C.route3_divebomb_damage) or 2400.0)
    local function consider(ench)
        if not ench then return end
        if mounts[ench] == true or griffin_is_self(ench) or is_player_or_party(ench) or is_dead(ench) then return end
        if st.hit[ench] == true then return end
        local ego = char_go(ench)
        local epos = ego and transform_pos(ego)
        if not epos then return end
        local dxh = (tonumber(epos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
        local dzh = (tonumber(epos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
        if (dxh * dxh + dzh * dzh) > r2 then return end
        st.hit[ench] = true
        if griffin_apply_attack_damage(ench, dmg) then
            S.route3_divebomb_hits = (tonumber(S.route3_divebomb_hits) or 0) + 1
        end
    end
    -- scene sweep (not just EnemyManager's list, which excludes wildlife/NPCs) = she slams anything under her
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            pcall(function() consider(ch) end)
        end
    end)
end

function route3_divebomb_end(reason)
    S.route3_divebomb = nil
    S.route3_divebomb_cooldown_at = os.clock()
    S.audition_until_clock = 0.0
    route3_restore_flight_base()   -- clear the dive clip off the base layer + resume glide (shared)
    S.route3_divebomb_status = "divebomb=" .. tostring(reason or "done")
end

function route3_divebomb_tick(ch, go, now)
    -- Runs from flight_tick BEFORE the seat drive (like the swoop): we write the trajectory
    -- into S.route3_air_pos, flight_tick zeroes the stick so the seat drive just HOLDS it.
    local st = S.route3_divebomb
    if not st then return false end
    if not (ch and go) or S.mounted ~= true then route3_divebomb_end("interrupted"); return false end
    local dt = math.max(0.001, math.min(0.05, now - (tonumber(st.last) or now)))
    st.last = now
    local bank = math.floor(tonumber(C.route3_divebomb_clip_bank) or 50)
    -- keep flap parked + kill the layer-1 overlay so the dive clips don't double the wingbeat
    S.audition_until_clock = now + 0.3
    pcall(function() route3_flap_clear_overlay() end)
    local pos = S.route3_air_pos or transform_pos(go)
    if not pos then return false end
    local yaw = tonumber(st.yaw) or 0.0

    if st.phase == "dive" then
        -- lead-in start clip, then swap to the falling loop
        if (not st.looped) and (now - (tonumber(st.phase_t0) or now)) >= math.max(0.0, tonumber(C.route3_divebomb_start_secs) or 0.3) then
            st.looped = true
            local lc = math.floor(tonumber(C.route3_divebomb_loop_clip) or 511)
            if lc >= 0 then pcall(function() play_griffin_motion(lc, bank, true) end) end
        end
        -- GROUND read, made robust. The tight per-frame cast rejects any contact >1m above the
        -- ray origin, so once she dips below the surface on a fast plunge it returns nil and she
        -- SKIMS through the floor (Aurora: "doesn't recognize when the ground is"). So: try the
        -- tight cast first (avoids treetops while above), fall back to a cast from WAY above her
        -- entry altitude, and PERSIST the last solid read so a single missed frame can't un-clamp her.
        local ground_y = nil
        pcall(function() local gh = route3_ground_hit_under(go); if gh and tonumber(gh.y) then ground_y = tonumber(gh.y) end end)
        if not ground_y then
            pcall(function()
                local rp = transform_render_pos(go)
                local gx = (rp and tonumber(rp.x)) or (tonumber(pos.x) or 0.0)
                local gz = (rp and tonumber(rp.z)) or (tonumber(pos.z) or 0.0)
                local ref_y = math.max(tonumber(pos.y) or 0.0, tonumber(st.entry_y) or 0.0) + 8.0
                local gh = route3_cast_ground_below(gx, ref_y, gz, 5.0, 500.0)
                if gh and tonumber(gh.y) then ground_y = tonumber(gh.y) end
            end)
        end
        if ground_y then st.ground_y = ground_y end
        local floor_y = tonumber(st.ground_y)   -- last-known; survives a missed cast
        local clearance = math.max(0.3, tonumber(C.route3_divebomb_ground_clearance) or 1.2)
        local fwd = math.max(0.0, tonumber(C.route3_divebomb_forward_speed) or 4.0)
        local dvspd = math.max(2.0, tonumber(C.route3_divebomb_dive_speed) or 20.0)
        -- HOMING: steer the horizontal drift toward the locked target's xz (dive down ONTO it);
        -- no target -> free forward dive along her heading.
        local nx, nz
        local tgo = st.target and char_go(st.target)
        local tpos = tgo and (not is_dead(st.target)) and transform_pos(tgo)
        if tpos then
            local dx = (tonumber(tpos.x) or 0.0) - (tonumber(pos.x) or 0.0)
            local dz = (tonumber(tpos.z) or 0.0) - (tonumber(pos.z) or 0.0)
            local hd = math.sqrt(dx * dx + dz * dz)
            local hstep = math.min(hd, fwd * dt)
            if hd > 0.05 then
                nx = (tonumber(pos.x) or 0.0) + (dx / hd) * hstep
                nz = (tonumber(pos.z) or 0.0) + (dz / hd) * hstep
                st.yaw = math.atan(dx, dz)   -- face the target as she dives
            else
                nx, nz = (tonumber(pos.x) or 0.0), (tonumber(pos.z) or 0.0)
            end
        else
            nx = (tonumber(pos.x) or 0.0) + math.sin(yaw) * fwd * dt
            nz = (tonumber(pos.z) or 0.0) + math.cos(yaw) * fwd * dt
        end
        local prev_y = tonumber(pos.y) or (tonumber(st.entry_y) or 0.0)
        local want_y = prev_y - dvspd * dt
        local reached = false
        if floor_y and want_y <= (floor_y + clearance) then
            want_y = floor_y + clearance
            reached = true
        end
        local newpos = make_position(nx, want_y, nz)
        S.route3_air_pos = newpos
        S.route3_air_rot = make_quat_yaw(tonumber(st.yaw) or yaw)
        pcall(function() route3_apply_air_transform(ch, go, newpos, S.route3_air_rot) end)
        -- SLAM: she's reached the ground (or timed out). LAND her -> GROUND MODE so the impact
        -- plays grounded, not floating (Aurora: "switch to ground mode and play the impact anim").
        if reached or (now - (tonumber(st.t0) or now)) > math.max(1.0, tonumber(C.route3_divebomb_max_dive_secs) or 4.0) then
            local land_y = (floor_y or ground_y or want_y) + (tonumber(C.route3_divebomb_land_offset) or 0.0)
            st.land = { x = nx, y = land_y, z = nz }
            local landpos = make_position(nx, land_y, nz)
            S.route3_air_pos = landpos
            pcall(function() route3_apply_air_transform(ch, go, landpos, S.route3_air_rot) end)
            S.airborne = false   -- <-- GROUND MODE
            S.vy = 0.0
            S.ground_y = land_y
            st.phase = "impact"
            st.phase_t0 = now
            local ic = math.floor(tonumber(C.route3_divebomb_impact_clip) or 513)
            if ic >= 0 then pcall(function() play_griffin_motion(ic, bank, false) end) end
            local snd = math.floor(tonumber(C.route3_divebomb_impact_sound_id) or 0)
            if snd > 0 then pcall(function() route3_play_wwise_trigger_id(snd, "divebomb_hit") end) end
            route3_divebomb_damage_sweep(go)   -- the SLAM AoE, once
        end
        S.route3_divebomb_status = string.format("diving  y=%.1f  hits=%s", want_y, tostring(S.route3_divebomb_hits or 0))
        return true

    elseif st.phase == "impact" then
        -- GROUND MODE: pin her on the floor while the impact+leap clip plays. audition keeps the
        -- grounded idle tick from stomping the clip (route3_visual_animation_tick bails on it).
        S.airborne = false
        local lp = (st.land and make_position(st.land.x, st.land.y, st.land.z)) or pos
        pcall(function() route3_apply_air_transform(ch, go, lp, S.route3_air_rot or make_quat_yaw(yaw)) end)
        if (now - (tonumber(st.phase_t0) or now)) >= math.max(0.2, tonumber(C.route3_divebomb_impact_secs) or 0.7) then
            st.phase = "recover"
            st.phase_t0 = now
            S.airborne = true   -- <-- back to FLIGHT MODE for the climb-out
            S.vy = math.max(tonumber(S.vy) or 0.0, tonumber(C.takeoff_boost) or 4.0)
            local ec = math.floor(tonumber(C.route3_divebomb_end_clip) or 515)
            if ec >= 0 then pcall(function() play_griffin_motion(ec, bank, false) end) end
        end
        S.route3_divebomb_status = string.format("SLAM (grounded)  hits=%s", tostring(S.route3_divebomb_hits or 0))
        return true

    elseif st.phase == "recover" then
        -- FLIGHT MODE: climb back up off the ground while the recovery clip plays, then hand
        -- control back to free flight.
        S.airborne = true
        local end_secs = math.max(0.2, tonumber(C.route3_divebomb_end_secs) or 0.8)
        local prog = math.min(1.0, (now - (tonumber(st.phase_t0) or now)) / end_secs)
        local base = (st.land and tonumber(st.land.y)) or (tonumber(pos.y) or 0.0)
        -- Smoothstep removes the old linear rocket launch. Also cap stale configs: Aurora's
        -- live slider had reached 40m, which was the entire cause of the absurd climb-out.
        local recover_h = math.max(0.0, math.min(12.0, tonumber(C.route3_divebomb_recover_altitude) or 6.0))
        local eased = prog * prog * (3.0 - 2.0 * prog)
        local ry = base + recover_h * eased
        local rp = make_position((st.land and st.land.x) or (tonumber(pos.x) or 0.0), ry,
            (st.land and st.land.z) or (tonumber(pos.z) or 0.0))
        S.route3_air_pos = rp
        pcall(function() route3_apply_air_transform(ch, go, rp, S.route3_air_rot or make_quat_yaw(yaw)) end)
        if prog >= 1.0 then route3_divebomb_end("done"); return false end
        S.route3_divebomb_status = "recovering"
        return true
    end
    route3_divebomb_end("badphase")
    return false
end

function route3_divebomb_hotkey_tick()
    if C.route3_divebomb_enabled ~= true or S.mounted ~= true then S.route3_divebomb_btn_prev = false; return end
    local down = false
    local names = tostring(C.route3_divebomb_buttons or ""):gsub("%s+", "")
    if names ~= "" then pcall(function() down = raw_gamepad_button_down(C.route3_divebomb_buttons) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_divebomb_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down == true and S.route3_divebomb_btn_prev ~= true then route3_divebomb_start("button") end
    S.route3_divebomb_btn_prev = down == true
end

-- ⭐⭐⭐ ATTACK LIVE WINDOW (2026-08-06) -- the mount-vs-puppet bridge.
-- open  = release the BODY: think alive + motion FSM un-puppeted, so the fired node's action code
--         runs for real (root motion, attack colliders, the whole Nick look). The BRAIN is never
--         released: AIDecisionMaker/NavigationAI stay mount-disabled throughout.
-- close = re-park with the predation-proven levers (think-stop + re-puppet + rearm suppression +
--         clear hate so no combat state lingers). Watchdogged: a window can never leak open.
--
-- FlightControl is a LEASE here, not part of the mounted steady state.  arm_ride_drive() pins
-- rootmove/transform as the sole body writer; an attack temporarily wakes FC because the native
-- action needs its integrator.  The old close path restored every other lease but left FC awake,
-- so a later LoopTheLoop ran with two position writers and separated body, saddle and camera by
-- hundreds of metres.  Keep all FC teardown in one idempotent normaliser.
function griffin_fc_lease_snapshot(fc)
    if not fc then return nil end
    local out = {}
    pcall(function()
        local td = fc:get_type_definition()
        for _, field in ipairs((td and td:get_fields()) or {}) do
            local name = tostring(field:get_name() or "")
            local low = name:lower()
            -- The dogfight touches target/move/flight integration state.  Capture only scalar and
            -- vec3 value fields from that surface; never retain managed-object references.
            if low:find("target", 1, true) or low:find("move", 1, true)
                or low:find("flight", 1, true) or low:find("fly", 1, true)
                or low:find("speed", 1, true) or low:find("accel", 1, true)
                or low:find("timer", 1, true) or low:find("groundnotfound", 1, true) then
                local value = nil
                pcall(function() value = fc:get_field(name) end)
                if type(value) == "number" or type(value) == "boolean" then
                    out[name] = { kind = type(value), value = value }
                elseif value ~= nil then
                    local x, y, z = nil, nil, nil
                    pcall(function() x, y, z = tonumber(value.x), tonumber(value.y), tonumber(value.z) end)
                    if x and y and z then out[name] = { kind = "vec3", x = x, y = y, z = z } end
                end
            end
        end
    end)
    return out
end

function griffin_fc_lease_restore(fc, snap, live, render)
    if not fc then return end
    for name, saved in pairs(type(snap) == "table" and snap or {}) do
        pcall(function()
            if saved.kind == "vec3" then
                fc:set_field(name, make_vec3(saved.x, saved.y, saved.z))
            elseif saved.kind == "number" or saved.kind == "boolean" then
                fc:set_field(name, saved.value)
            end
        end)
    end

    -- Position memories must be reseeded at the NEW body location, not restored to the point where
    -- the dive began.  Movement outputs are zeroed so a later node cannot inherit dash momentum.
    local here = render or live
    if here then
        local p = make_vec3(tonumber(here.x) or 0.0, tonumber(here.y) or 0.0, tonumber(here.z) or 0.0)
        for _, name in ipairs({ "<TargetPosition>k__BackingField", "AimTargetPosition",
            "PrevMovePos", "MoveOldPos" }) do
            pcall(function() fc:set_field(name, p) end)
        end
        pcall(function() fc:call("setFlightTargetPosition", p) end)
        pcall(function() fc:call("set_TargetPosition", p) end)
    end
    local zero = make_vec3(0.0, 0.0, 0.0)
    for _, name in ipairs({ "FlightMoveVector", "ISMoveVector", "NowISMoveVector",
        "HoverMoveOffset", "FlightMoveOffset", "HoveringAttitudeMoveVec" }) do
        pcall(function() fc:set_field(name, zero) end)
    end
    -- Native nodes can retire to Locomotion.Wait while their private movement clocks remain
    -- active.  The successful loop before the frozen second take-off left ISMoveTimer=180.1476.
    -- These clocks are part of the action lease and must never survive its hand-back.
    for _, name in ipairs({ "ISMoveTimer", "FlightMoveMotionTimer", "HoverMoveMotionTimer",
        "FlightAttitudeAccelDecelTimer", "FlightAttitudeShakeMotionSpeedTimer",
        "FlySpeedTimer", "FlySpeedHeightTimer" }) do
        pcall(function() fc:set_field(name, 0.0) end)
    end
    if live then
        local y = tonumber(live.y) or 0.0
        pcall(function() fc:call("set_AirTargetPosY", y) end)
        pcall(function() fc:set_field("_AirTargetPosY", y) end)
        pcall(function() fc:set_field("OldAirTargetPos", y) end)
    end
end

function griffin_mounted_fc_sanitise(reason, fallback_enabled, lease_snapshot)
    local ch, go = reacquire_griffin()
    if not go then
        S.route3_fc_sanitise_pending = tostring(reason or "body missing")
        return false
    end
    local fc = get_component(go, "app.FlightControl")
    if not fc then
        S.route3_fc_sanitise_pending = tostring(reason or "FlightControl missing")
        return false
    end

    local live = transform_pos(go)
    local render = transform_render_pos(go) or live
    -- Remove the dogfight seeker's last enemy/velocity beliefs before parking the component.
    -- Restore the pre-attack integration scalars, then reseed position memories at live reality.
    pcall(function() griffin_fc_lease_restore(fc, lease_snapshot, live, render) end)
    if live then
        S.route3_air_pos = live                 -- transform drive resumes from reality, never pre-attack cache
        S.route3_air_rot = transform_rot(go) or S.route3_air_rot
    end
    pcall(function()
        local hit = route3_ground_hit_under(go, nil)
        if hit and tonumber(hit.y) then
            fc:call("setGroundHeight(System.Single, System.Single)", tonumber(hit.y), 0.0)
        end
    end)
    pcall(function()
        local tac = ch and ch["<TargetAngleCtrl>k__BackingField"]
        if tac then
            local deg = math.deg(yaw_from_transform(go) or S.heading_yaw or 0.0)
            tac.Front["<AngleDeg>k__BackingField"] = deg
            tac.Move["<AngleDeg>k__BackingField"] = deg
        end
    end)

    -- A mounted rootmove ride owns position itself.  Only the explicitly selected FC backend is
    -- allowed to leave native FlightControl enabled.  Off-mount, preserve the caller's snapshot.
    local wanted = fallback_enabled
    if S.mounted == true then wanted = native_climb_uses_flight_control() == true end
    if type(wanted) ~= "boolean" then wanted = true end
    pcall(function() fc:call("set_Enabled", wanted) end)
    local actual = "?"
    pcall(function() actual = tostring(fc:call("get_Enabled")) end)
    S.vx, S.vy, S.vz = 0.0, 0.0, 0.0
    S.route3_fc_sanitise_pending = nil
    S.route3_fc_lease_snapshot_pending = nil
    S.route3_fc_lease_enabled_pending = nil
    if S.mounted == true then
        S.route3_attack_recover_until = math.max(tonumber(S.route3_attack_recover_until) or 0.0,
            os.clock() + 0.20)
    end
    S.route3_fc_sanitise_status = string.format("%s -> enabled=%s", tostring(reason or "normalise"),
        actual)
    pcall(function()
        local snap_n = 0
        for _ in pairs(type(lease_snapshot) == "table" and lease_snapshot or {}) do snap_n = snap_n + 1 end
        local mv_mag, timers = "?", {}
        pcall(function()
            local mv = fc:get_field("FlightMoveVector")
            if mv then mv_mag = math.sqrt((tonumber(mv.x) or 0.0)^2 + (tonumber(mv.y) or 0.0)^2
                + (tonumber(mv.z) or 0.0)^2) end
        end)
        for _, name in ipairs({ "ISMoveTimer", "FlightMoveMotionTimer", "FlySpeedTimer",
            "FlySpeedHeightTimer", "FlightAttitudeAccelDecelTimer" }) do
            pcall(function() timers[name] = tonumber(fc:get_field(name)) end)
        end
        local rec = {
            when = os.date("%H:%M:%S"), reason = tostring(reason or "normalise"),
            mounted = S.mounted == true, expected_enabled = wanted,
            actual_enabled = actual, fsm_now = tostring(read_griffin_fsm_node() or "?"),
            drive_mode = tostring(C.native_climb_drive_mode or "?"),
            restored_fields = snap_n, flight_move_magnitude = mv_mag, timers = timers,
        }
        S.route3_fc_handoff_history = type(S.route3_fc_handoff_history) == "table"
            and S.route3_fc_handoff_history or {}
        local hist = S.route3_fc_handoff_history
        hist[#hist + 1] = rec
        while #hist > 10 do table.remove(hist, 1) end
        json.dump_file(MOD .. "_fc_handoff.json", { latest = rec, history = hist })
    end)
    return true
end

function griffin_mounted_fc_guard_tick()
    if S.mounted ~= true or native_climb_uses_flight_control() == true then return false end
    -- Never revoke a live node's lease.  The pending flag survives until every attack owner has
    -- stood down, then this guard performs one atomic hand-back before another move can start.
    if S.route3_live_window or griffin_dogfight_active() or griffin_gustair_active()
        or griffin_rise_fc_window_active() or S.route3_node_lock_at ~= nil
        or S.route3_node_exit_until ~= nil then return false end
    local _, go = reacquire_griffin()
    local fc = go and get_component(go, "app.FlightControl")
    if not fc then return false end
    local enabled = false
    pcall(function() enabled = fc:call("get_Enabled") == true end)
    if enabled or S.route3_fc_sanitise_pending ~= nil then
        return griffin_mounted_fc_sanitise(S.route3_fc_sanitise_pending or "mounted ownership guard",
            S.route3_fc_lease_enabled_pending, S.route3_fc_lease_snapshot_pending)
    end
    return false
end

function griffin_attack_live_window_open(leaf, secs)
    if C.route3_dogfight_live_window == false then return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    local fc_was, fc_state = nil, nil
    pcall(function()
        local fc0 = get_component(go, "app.FlightControl")
        if fc0 then
            fc_was = fc0:call("get_Enabled")
            fc_state = griffin_fc_lease_snapshot(fc0)
        end
    end)
    S.route3_live_window = { until_clock = os.clock() + math.max(1.0, tonumber(secs) or 4.0),
        leaf = tostring(leaf or "?"), fc_was_enabled = fc_was, fc_state = fc_state }
    pcall(function() set_motion_fsm_puppet(go, false) end)
    pcall(function() set_think_stop(ch, false) end)
    -- ⛔⛔ DECIDER-OFF REVERTED (v14, 2026-08-07: DecisionEvaluationModuleLateUpdator AV'd
    -- TWICE mid-skid with the decider disabled -- the evaluation pipeline late-updates the
    -- disabled module and null-derefs. The dm-off/FC-off/FlyPatrol triangle was a CIRCLE:
    -- FC-off made patrol actions lethal (19:58) -> dm-off stopped patrols but killed the
    -- evaluator (20:05, 20:30). v14 breaks the circle at its origin: FC STAYS ALIVE through
    -- the skid (every "FC floats her" verdict was measured with the clearance net -- the
    -- real thief -- still active), so patrol actions are harmless again and the decider
    -- stays enabled. Minimum toggles, everything alive.
    -- ⭐⭐⭐ THE THIRD BRAKE (2026-08-06, and the one that actually held her): the mount suppresses
    -- ROOT MOTION at the via.motion component itself -- RootPlayMode=None + root scale disabled,
    -- re-applied at every clip paint ("root motion would fight the transform drive"). That law is
    -- BELOW the FSM and below think: with both of those live she still computed the pounce's
    -- movement every frame and the motion component THREW IT AWAY. Restore Continuance (2, the
    -- living character's mode -- enum dump in _rootplaymode_enum.json) for the window; close()
    -- re-applies the mount law.
    local rm_after = "?"
    pcall(function()
        local m = ch:call("get_Motion")
        if m then
            local ok2 = pcall(function() m:call("set_RootMotion(via.motion.RootPlayMode)", 2) end)
            if not ok2 then pcall(function() m:call("set_RootMotion", 2) end) end
            pcall(function() m:call("set_RootScaleDisabled(System.Boolean)", false) end)
            -- ⭐ READ BACK -- a pcall'd set with no readback is a wish, not a fact
            pcall(function() rm_after = tostring(m:call("get_RootMotion")) end)
        end
    end)
    -- ⭐⭐ THE FOURTH BRAKE: FLIGHT STATE (2026-08-06). Tape proved rm=2 + live FSM + live think
    -- and STILL statue-still -- because we fire Fly.FlightAttack.* from Locomotion.Wait with
    -- FlightControl disengaged. Flight nodes integrate their movement THROUGH FC, and a
    -- disengaged FC classifies a held griffin as grounded/falling, so the node's movement has
    -- no authority to act on (our own flight tick documents exactly this for fly actions).
    -- Engage the documented recipe verbatim.
    pcall(function()
        local fc = get_component(go, "app.FlightControl")
        if fc then
            pcall(function()
                fc:call("onFlyState(app.FlightControl.FlyStateNo)",
                    math.max(0, math.floor(tonumber(C.flight_control_fly_state) or 1)))
            end)
            pcall(function() fc:call("set_FlagGroundNotFound(System.Boolean)", false) end)
            -- ⛔⛔ TARGET-SEEDED GROUND HEIGHT: TRIED 2026-08-07, REVERTED SAME DAY. Seeding
            -- setGroundHeight from a cast under the TARGET (a) did NOT fix the skid float
            -- (Aurora: "still floats") and (b) was the only new variable in a brand-new native
            -- crash class: app.Ch253WallCheck.updateWallCheckFlight AV inside Ch253000.update
            -- (log 18:43). The engine's believed-ground plumbing feeds systems beyond FC -- do
            -- not lie to it about ground that isn't under her. The hover is an ACCEPTED trade.
            local hit = route3_ground_hit_under(go, nil)
            local gy = tonumber(hit and hit.y)
            if gy then
                pcall(function() fc:call("setGroundHeight(System.Single, System.Single)", gy, 0.0) end)
            end
        end
    end)
    -- ⭐ one-time FC SURFACE DUMP: the next lever is PROPULSION (tape 12:01: FC engaged = she
    -- finally MOVED, a ~5m hover-sink -- the integrator lives, but nothing feeds it forward
    -- speed). Dump every FlightControl method/field touching speed/velocity/accel/move so the
    -- lever gets picked by NAME, not by guessing.
    if S.route3_fc_dumped ~= true then
        S.route3_fc_dumped = true
        pcall(function()
            local fc = get_component(go, "app.FlightControl")
            local td = fc and fc:get_type_definition()
            if not td then return end
            local out = { methods = {}, fields = {} }
            for _, m in ipairs(td:get_methods() or {}) do
                local nm = tostring(m:get_name())
                if nm:lower():find("speed") or nm:lower():find("vel") or nm:lower():find("accel")
                    or nm:lower():find("move") or nm:lower():find("dash") or nm:lower():find("target") then
                    out.methods[#out.methods + 1] = nm
                end
            end
            for _, f in ipairs(td:get_fields() or {}) do
                local nm = tostring(f:get_name())
                if nm:lower():find("speed") or nm:lower():find("vel") or nm:lower():find("accel")
                    or nm:lower():find("move") or nm:lower():find("dash") or nm:lower():find("target") then
                    out.fields[#out.fields + 1] = nm .. " : " .. tostring(f:get_type():get_name())
                end
            end
            json.dump_file(MOD .. "_fc_surface.json", out)
        end)
    end
    S.route3_live_window_status = "OPEN (" .. tostring(leaf) .. ") rm=" .. tostring(rm_after) .. " fc=engaged"
    return true
end

function griffin_attack_live_window_close(why)
    local w = S.route3_live_window
    if not w then return end
    S.route3_live_window = nil
    local ch, go = reacquire_griffin()
    if ch and go then
        -- (v14: decider is never disabled any more; stray-flag restore kept for one version
        -- in case a crashed v12/v13 session left it off)
        if S.route3_window_dm_off then
            S.route3_window_dm_off = nil
            pcall(function()
                local dm = ch:get_field("<AIDecisionMaker>k__BackingField")
                if dm then dm:call("set_Enabled", true) end
            end)
        end
        pcall(function() set_think_stop(ch, true) end)
        pcall(function() set_motion_fsm_puppet(go, C.puppet_motion_fsm == true) end)
        pcall(function() apply_griffin_motion_root_mode() end)   -- re-apply the mount's root-motion law
        pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
        pcall(function() clear_griffin_hate() end)
        -- Re-park body/brain immediately, but return FlightControl only after the native node has
        -- actually retired.  Disabling FC under a still-running action can truncate its last beat.
        local fc_reason = "attack close: " .. tostring(why or "?")
        S.route3_fc_sanitise_pending = fc_reason
        S.route3_fc_lease_snapshot_pending = w.fc_state
        S.route3_fc_lease_enabled_pending = w.fc_was_enabled
        if S.mounted ~= true or (S.route3_node_lock_at == nil
            and not griffin_rise_fc_window_active()) then
            pcall(function() griffin_mounted_fc_sanitise(fc_reason, w.fc_was_enabled, w.fc_state) end)
        end
        -- FC was engaged for the window; if she is grounded now, an engaged FC = the documented
        -- float bug. The post-landing recover is the universal normalize net -- arm it.
        if S.airborne ~= true then S.route3_post_landing_recover_at = os.clock() end
    end
    S.route3_live_window_status = "closed (" .. tostring(why or "?") .. ")"
end

function griffin_live_window_watchdog()
    local w = S.route3_live_window
    if not w then return end
    -- a live window may NEVER outlive its ride: no dogfight state, or past its ceiling -> close
    if (not griffin_dogfight_active()) or os.clock() > (tonumber(w.until_clock) or 0.0)
        or S.mounted ~= true then
        griffin_attack_live_window_close("watchdog")
    end
end

-- ============================ AERIAL DOGFIGHT PASS (griffin-vs-griffin) ============================
-- Lock a wild griffin, dive at it in full 3D (tracks its ALTITUDE, unlike the divebomb's ground plunge),
-- rip a beak-rush through it dealing direct HP damage, then climb out STILL AIRBORNE. One pass per press.
function griffin_dogfight_active() return type(S.route3_dogfight) == "table" end

-- Retained rider-attachment trace. FC hand-off is already proven clean; this captures the other
-- side of the relationship so one field run shows whether the logical player stayed rebased with
-- the moved griffin through dogfight and the following node.
function griffin_climb_handoff_snapshot(reason)
    pcall(function()
        local player = get_player()
        local ctrl = get_climb_ctrl(player)
        local _, ggo = reacquire_griffin()
        local pgo = player and char_go(player)
        local pp = pgo and transform_pos(pgo)
        local gp = ggo and transform_pos(ggo)
        local gap = nil
        if pp and gp then
            local dx = (tonumber(pp.x) or 0.0) - (tonumber(gp.x) or 0.0)
            local dy = (tonumber(pp.y) or 0.0) - (tonumber(gp.y) or 0.0)
            local dz = (tonumber(pp.z) or 0.0) - (tonumber(gp.z) or 0.0)
            gap = math.sqrt(dx * dx + dy * dy + dz * dz)
        end
        local function read_call(name)
            local value = nil
            pcall(function() value = ctrl and ctrl:call(name) end)
            return value
        end
        local target, mode = nil, nil
        pcall(function() target = ctrl and ctrl:get_field("TargetRootObject") end)
        pcall(function() mode = ctrl and ctrl:get_field("_Mode") end)
        local target_addr = nil
        pcall(function() target_addr = target and tostring(target:get_address()) end)
        local row = {
            when = os.date("%H:%M:%S"), reason = tostring(reason or "?"),
            gap_m = gap, mounted = S.mounted == true, airborne = S.airborne == true,
            climb_on_character = read_call("get_IsClimbOnCharacter"),
            climbing = read_call("get_IsClimbing"), climb_moving = read_call("get_IsClimbMoving"),
            enabled = read_call("get_Enabled"), active = read_call("get_IsActive"),
            mode = tostring(mode), target_addr = target_addr,
            follower_suppression_config = C.native_climb_suppress_climb_ctrl == true,
            follower_suppressed_runtime = S.native_climb_ctrl_suppressed == true,
        }
        local old = json.load_file(MOD .. "_climb_handoff.json")
        local history = type(old) == "table" and old.history or nil
        if type(history) ~= "table" then history = {} end
        history[#history + 1] = row
        while #history > 12 do table.remove(history, 1) end
        json.dump_file(MOD .. "_climb_handoff.json", { latest = row, history = history })
    end)
end

function griffin_find_aerial_foe(go)
    local gpos = go and transform_pos(go)
    if not gpos then return nil end
    local search = math.max(10.0, tonumber(C.route3_dogfight_search) or 60.0)
    local bands = tostring(C.route3_dogfight_target_bands or "ch253")
    local gch = reacquire_griffin()   -- MY griffin (exclude by instance, NOT by name -- all ch253 share the go-name)
    local best, best_d = nil, search * search
    local nearby = {}   -- diagnostic: everything around us (name + dist), so we can SEE why the foe wasn't picked
    local function consider(ch)
        local cgo = char_go(ch)
        if not cgo then return end
        local nm = go_name(cgo) or ""
        local pos = transform_pos(cgo)
        if not pos then return end
        local dx = (tonumber(pos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
        local dz = (tonumber(pos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
        local d2 = dx * dx + dz * dz
        if d2 < 40000.0 then nearby[#nearby + 1] = { nm = nm, d = math.sqrt(d2) } end   -- log ring: 200m
        if nm == "" then return end
        -- ⭐ CRITTERS lockable (2026-08-08, Aurora: "include critters like deer/etc") --
        -- ⛔ EXCEPT converted horses (the huntable-guard law: rides/tames, never prey)
        local critter = false
        if nm:find("ch299", 1, true) then
            if C.route3_lock_critters == false then return end
            local ishorse = false
            pcall(function()
                local api = rawget(_G, "__iris_wild_horses_api")
                ishorse = api and api.is_horse and api.is_horse(cgo) == true
            end)
            if ishorse then return end
            critter = true
        end
        -- ⭐ ANY ENEMY (2026-08-05, Aurora: "lock onto the nearest enemy" -- the goblin was never
        -- pounced because goblins were not in the band list). Blank bands = target anything with
        -- an ENEMY BRAIN (ch.EnemyCtrl, the same field Puppeteer uses to identify enemies), which
        -- covers every goblin/wolf/saurian without enumerating chassis ids. The legacy flyer list
        -- stays as a fallback so griffins/harpies still lock even if the field read ever fails.
        local matched = critter
        if not matched and (bands == "" or bands == "*") then
            -- ⛔ brain test ALONE locked friendly NPCs (Aurora 2026-08-05) -- villagers evidently
            -- carry the field too. Require BOTH: an enemy brain AND the enemy chassis range
            -- (monsters are ch2xx: goblins ch22x, big game ch25x; NPCs live in ch3xx, player
            -- ch000, pawns ch001 -- none start "ch2").
            if nm:sub(1, 3) == "ch2" then
                pcall(function() matched = (ch.EnemyCtrl ~= nil) end)
            end
            if not matched then
                for band in ("ch253,ch222"):gmatch("[^,%s]+") do
                    if nm:find(band, 1, true) then matched = true; break end
                end
            end
        else
            for band in bands:gmatch("[^,%s]+") do
                if nm:find(band, 1, true) then matched = true; break end
            end
        end
        if not matched then return end
        -- ONLY exclude MY actual griffin (by instance) -- griffin_is_self also name-matches, and every
        -- ch253 is named "ch253000_00", so it would wrongly exclude the wild target too (Aurora).
        if (gch and same_obj(ch, gch)) or (S.griffin and same_obj(ch, S.griffin)) then return end
        if is_player_or_party(ch) or is_dead(ch) or mounts[ch] == true then return end
        if d2 < best_d then best, best_d = ch, d2 end   -- NEAREST matching griffin, any direction
    end
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do pcall(function() consider(ch) end) end
    end)
    pcall(function()
        table.sort(nearby, function(a, b) return a.d < b.d end)
        local s = ""
        for i = 1, math.min(8, #nearby) do s = s .. string.format(" %s(%.0fm)", tostring(nearby[i].nm), nearby[i].d) end
        log.info("[dogfight] find band=" .. bands .. " found=" .. tostring(best ~= nil) .. " nearest:" .. s)
    end)
    return best
end

function route3_forward_blocked(go, yaw, dist)
    -- horizontal ray from the griffin body forward along yaw; any solid contact = blocked.
    -- x/z are identical in render vs universal space, so we cast in RENDER space (same rig as
    -- the ground cast: layer 2). Used only for the no-target straight dash (stop at a wall).
    if not route3_ensure_ray() then return false end
    local rp = transform_render_pos(go) or transform_pos(go)
    if not rp then return false end
    local ox, oy, oz = tonumber(rp.x) or 0.0, tonumber(rp.y) or 0.0, tonumber(rp.z) or 0.0
    local dx, dz = math.sin(yaw or 0.0), math.cos(yaw or 0.0)
    local d = math.max(1.0, tonumber(dist) or 4.0)
    local blocked = false
    pcall(function()
        route3_ray.filter:set_Group(0); route3_ray.filter:set_Layer(2); route3_ray.filter:set_MaskBits(0)
        route3_ray.result:clear()
        route3_ray.query:call("setRay(via.vec3, via.vec3)",
            make_vec3(ox, oy, oz),
            make_vec3(ox + dx * d, oy, oz + dz * d))
        route3_ray.method:call(route3_ray.system, route3_ray.query, route3_ray.result)
        local count = route3_ray.result:get_NumContactPoints() or 0
        if count and count > 0 then blocked = true end
    end)
    return blocked
end


function route3_dogfight_clamp_altitude(go, y)
    -- keep the pass at least route3_dogfight_min_altitude above the ground, so the griffin
    -- never dips close enough to the floor to show a grounded / all-fours pose mid-strike.
    local minalt = math.max(0.0, tonumber(C.route3_dogfight_min_altitude) or 4.0)
    if minalt <= 0.0 then return y end
    local gy = nil
    pcall(function() gy = route3_ground_y_robust(go, y) end)
    if gy and (tonumber(y) or 0.0) < gy + minalt then return gy + minalt end
    return y
end

function route3_dogfight_beak_contact(st, pos, tpos)
    -- Root-to-root proximity killed a Harpy that the visible beak pass completely missed. Use a
    -- swept proxy at the beak instead: the previous and current beak points form a short capsule,
    -- so a fast pass cannot tunnel through a real contact and a wing/body near-miss cannot score.
    if not (st and pos and tpos) then return false end
    local yaw = tonumber(st.yaw) or 0.0
    local fwd = math.max(0.5, tonumber(C.route3_dogfight_beak_forward) or 3.0)
    local cur = {
        x = (tonumber(pos.x) or 0.0) + math.sin(yaw) * fwd,
        y = tonumber(pos.y) or 0.0,
        z = (tonumber(pos.z) or 0.0) + math.cos(yaw) * fwd,
    }
    local prev = st.prev_beak or cur
    st.prev_beak = cur
    local abx, aby, abz = cur.x - prev.x, cur.y - prev.y, cur.z - prev.z
    local apx = (tonumber(tpos.x) or 0.0) - prev.x
    local apy = (tonumber(tpos.y) or 0.0) - prev.y
    local apz = (tonumber(tpos.z) or 0.0) - prev.z
    local den = abx * abx + aby * aby + abz * abz
    local u = den > 0.0001 and ((apx * abx + apy * aby + apz * abz) / den) or 0.0
    u = math.max(0.0, math.min(1.0, u))
    local qx, qy, qz = prev.x + abx * u, prev.y + aby * u, prev.z + abz * u
    local ex = (tonumber(tpos.x) or 0.0) - qx
    local ey = (tonumber(tpos.y) or 0.0) - qy
    local ez = (tonumber(tpos.z) or 0.0) - qz
    local gap = math.sqrt(ex * ex + ey * ey + ez * ez)
    st.contact_gap = gap
    return gap <= math.max(0.5, tonumber(C.route3_dogfight_contact_radius) or 1.45)
end

function route3_dogfight_record_hit(target)
    -- deal the damage AND capture HP before/after (+max) for the on-screen readout, since wild
    -- griffins have no native health bar. Aurora couldn't tell if a hit registered.
    if not target then return end
    local hc = griffin_target_hit_controller(target)
    local before = hc and griffin_hp_from_component(hc)
    local maxhp = hc and griffin_hp_max_from_component(hc)
    local dealt_ok = griffin_apply_attack_damage(target, math.max(1.0, tonumber(C.route3_dogfight_damage) or 2700.0))
    local after = hc and griffin_hp_from_component(hc)
    local mx = tonumber(maxhp)
    if (not mx) or mx <= 0.0 then mx = math.max(tonumber(before) or 1.0, tonumber(after) or 1.0, 1.0) end
    S.route3_dogfight_hud = {
        name = tostring(go_name(char_go(target)) or "griffin"),
        before = tonumber(before), after = tonumber(after), max = mx,
        dealt = (tonumber(before) and tonumber(after)) and (tonumber(before) - tonumber(after)) or nil,
        hit = dealt_ok == true,
        until_clock = os.clock() + math.max(0.5, tonumber(C.route3_dogfight_hud_secs) or 2.6),
    }
    if dealt_ok then S.route3_dogfight_status = "HIT!" end
end

function route3_dogfight_can_start()
    if C.route3_dogfight_enabled ~= true then return false end
    if S.mounted ~= true then return false end
    if S.world_paused == true then return false end
    if griffin_hit_reaction_busy and griffin_hit_reaction_busy() then return false end
    if griffin_dogfight_active() then return false end
    if griffin_divebomb_active() or griffin_grab_active() then return false end
    -- ⛔⛔ NEVER CROSS-FIRE ATTACK NODES (2026-08-05 crash tape: "GALE-DIVE from-node=
    -- SubUniqueAttack.Ch253000WingThunderAttackAir" -- a gale fired INTO the still-running
    -- wing-thunder, jitter + teleporting + CTD a few presses later). One native node at a time:
    -- refuse while the lockout holds ANY node, while the gust is live, or while the exit pump
    -- is still walking her back to neutral.
    if S.route3_gustair then return false end
    if S.route3_node_exit_until then return false end
    if os.clock() < (tonumber(S.route3_attack_recover_until) or 0.0) then return false end
    local locked = false
    pcall(function() locked = griffin_node_lockout_active() == true end)
    if locked then return false end
    if S.airborne ~= true then return false end
    local cd = math.max(0.2, tonumber(C.route3_dogfight_cooldown) or 0.8)
    if os.clock() - (tonumber(S.route3_dogfight_cooldown_at) or -999.0) < cd then return false end
    return true
end

function route3_dogfight_start(reason)
    if reason ~= "test" and not route3_dogfight_can_start() then return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    pcall(function() griffin_climb_handoff_snapshot("dogfight start") end)
    local foe = griffin_find_aerial_foe(go)   -- may be nil: no foe -> straight forward charge (Aurora: go forward by default, lock ONLY if a foe's there)
    -- native travel mode fires from WHEREVER SHE IS, like Nick -- no closing approach first
    local native_drive = tostring(C.route3_dogfight_drive or "native") == "native"
        and tostring(C.route3_dogfight_style or "gale") ~= "classic"
    S.route3_dogfight = { t0 = os.clock(), last = os.clock(),
        phase = (foe and not native_drive) and "close" or "strike", phase_t0 = os.clock(),
        target = foe, no_target = (foe == nil),
        yaw = yaw_from_transform(go) or S.heading_yaw or 0.0, hit = {} }
    S.airborne = true
    -- ⛔⛔ NO CLIP PAINT IN GALE STYLE (2026-08-05, THE tape verdict). _galetape.json proved the
    -- pounce chain rode the FSM perfectly (StartL 2.9s -> AirLoopL, locked throughout) while
    -- Aurora saw no attack animation at all -- because THIS line painted the beak-rush clip onto
    -- the motion layer at the press, and a freshly-forced layer clip owns her visible body over
    -- the node's animation. The loop's fire path paints nothing, which is why the loop SHOWS.
    -- The clip belongs to the CLASSIC style only.
    if tostring(C.route3_dogfight_style or "gale") == "classic" then
        local bank = math.floor(tonumber(C.route3_dogfight_clip_bank) or 50)
        local sc = math.floor(tonumber(C.route3_dogfight_start_clip) or 510)
        if sc >= 0 then pcall(function() play_griffin_motion(sc, bank, true) end) end
    end
    S.audition_until_clock = os.clock() + 3.0
    S.route3_dogfight_status = "engaging!"
    status(tostring(C.route3_griffin_name or "Griffin") .. " dives to strike!")
    return true
end

function route3_dogfight_tick(ch, go, now)
    local st = S.route3_dogfight
    if not st then return false end
    -- ⛔⛔ NEVER route3_dogfight_end() WHILE A NATIVE NODE IS RIDING (2026-08-05 harpy crash).
    -- end() force-paints the flap clip; during galeride/pounceride the attack node is still live,
    -- and painting over a running node is the two-owners AV. The harpy sequence was exactly that:
    -- our 300-damage hit KILLED the foe mid-ride -> "foe down" -> end() -> paint over the live
    -- gale -> CTD. Ride phases unwind QUIETLY (no repaint; the exit pump repaints at the retire).
    local riding = (st.phase == "galeride" or st.phase == "pounceride")
    local function unwind_quiet(why)
        -- dump the pass's flight recorder (see the fire site) -- one file, overwritten per pass
        pcall(function()
            local tp = st.tape or {}
            json.dump_file(MOD .. "_galetape.json", {
                when = os.date("%H:%M:%S"),
                style = tostring(tp.style), fired = tostring(tp.fired),
                target_name = tostring(tp.target_name),
                fsm_at_fire = tostring(tp.fsm_at_fire),
                fsm_samples = tp.fsm_samples or {},
                lockout_ever_engaged = tp.lockout_ever == true,
                had_target = tp.had_target == true,
                hit_landed = tp.hit == true,
                self_moved_m = math.floor((tonumber(tp.self_moved) or 0.0) * 10) / 10,
                fc_seek_writes = tonumber(tp.fc_writes) or 0,
                fc_calls_ok = tp.fc_ok,
                fc_calls_failed = tp.fc_fail,
                fc_was_disabled = tp.fc_was_disabled == true or nil,
                gearbox_thr_peak = tp.thr_peak and (math.floor(tp.thr_peak * 100) / 100) or nil,
                ride_secs = math.floor(((now or os.clock()) - (tonumber(st.phase_t0) or 0.0)) * 100) / 100,
                exit_reason = tostring(why),
                live_window = tostring(S.route3_live_window_status or "(never opened)"),
                build = tp.build,            -- v9+: which code this pass actually ran
                skid_diag = tp.skid_diag,    -- v9+: did each skid lever LAND (the dump's field
                                             -- list silently dropped these on the first v9 pass)
            })
        end)
        S.route3_dogfight = nil
        S.route3_dogfight_cooldown_at = os.clock()
        S.route3_flap_phase = nil
        S.audition_until_clock = 0.0
        -- quiet-landing hygiene: if the grounding never consumed the one-shot (interrupt),
        -- don't let it silence some FUTURE unrelated landing. ⛔ NOT when the deferred
        -- ground-at-retire flag is armed -- that grounding runs AFTER this unwind and is
        -- exactly the landing the flag is FOR.
        if S.route3_landing_quiet == true and S.airborne == true
            and S.route3_pounce_ground_at_retire == nil then
            S.route3_landing_quiet = nil
        end
        -- AdjustTerrain: if the skid enabled the terrain snap, leave it matching her END state
        -- (grounded = keep snapping, that IS the grounded norm; airborne = off, the flyer norm)
        if S.route3_adj_touched == true then
            S.route3_adj_touched = nil
            pcall(function()
                local ch2 = reacquire_griffin()
                local adj = ch2 and ch2:get_field("<AdjustTerrain>k__BackingField")
                if adj then adj:call("setEnable", S.airborne ~= true) end
            end)
            -- sticky marker: the frame loop clears the snap the moment she next goes airborne
            -- (a flyer with terrain-snap on would be glued to the ground)
            S.route3_adj_grounded_on = (S.airborne ~= true) and true or nil
        end
        pcall(function() griffin_attack_live_window_close(why) end)   -- re-park with the ride
        pcall(function() griffin_climb_handoff_snapshot("dogfight exit: " .. tostring(why)) end)
        S.route3_dogfight_status = "dogfight=" .. tostring(why or "done") .. " (quiet)"
    end
    if not (ch and go) or S.mounted ~= true then
        if riding then unwind_quiet("interrupted") else route3_dogfight_end("interrupted") end
        return false
    end
    local maxs = math.max(2.0, tonumber(C.route3_dogfight_max_secs) or 8.0)
    -- the landing beats (drift-turn + flare) must never be decapitated by the global ceiling
    if riding and (tonumber(st.pounce_step) or 0) >= 3 then maxs = maxs + 4.0 end
    if (now - (tonumber(st.t0) or now)) > maxs then
        if riding then unwind_quiet("timeout") else route3_dogfight_end("timeout") end
        return false
    end
    local tgo = st.target and char_go(st.target)
    if st.target and (not tgo or is_dead(st.target)) then
        if riding then
            -- foe died mid-pass: keep flying the attack OUT -- the animation finishes, nothing
            -- repaints, and the pump retires the node as normal. A GALE flies the line out; a
            -- POUNCE keeps homing on the landing anchor (st.tpin) and lands on the corpse.
            st.target = nil; st.no_home = (st.phase ~= "pounceride"); tgo = nil
        else
            route3_dogfight_end("foe down"); return false
        end
    end
    local dt = math.max(0.001, math.min(0.05, now - (tonumber(st.last) or now)))
    st.last = now
    S.audition_until_clock = now + 0.3
    pcall(function() route3_flap_clear_overlay() end)
    local bank = math.floor(tonumber(C.route3_dogfight_clip_bank) or 50)
    -- ⛔⛔ RIDE PHASES READ THE LIVE TRANSFORM (2026-08-06). S.route3_air_pos is the position WE
    -- last wrote -- native mode writes nothing, so it froze at the fire point. Every tape hd, the
    -- FC-seek target maths and Nick's steer angle were computed from a GHOST. (The 12:13 "14m of
    -- movement" was the puma fleeing; our pos never updated once.)
    local pos = (riding and transform_pos(go)) or S.route3_air_pos or transform_pos(go)
    if not pos then route3_dogfight_end("lost"); return false end
    local tpos = tgo and transform_pos(tgo)
    if st.target and not tpos then route3_dogfight_end("lost"); return false end
    local dx, dy, dz, hd, d3 = 0.0, 0.0, 0.0, 1.0e9, 1.0e9
    if tpos then
        dx = (tonumber(tpos.x) or 0.0) - (tonumber(pos.x) or 0.0)
        dy = (tonumber(tpos.y) or 0.0) - (tonumber(pos.y) or 0.0)
        dz = (tonumber(tpos.z) or 0.0) - (tonumber(pos.z) or 0.0)
        hd = math.sqrt(dx * dx + dz * dz)
        d3 = math.sqrt(dx * dx + dy * dy + dz * dz)
    end
    local speed = math.max(2.0, tonumber(C.route3_dogfight_speed) or 16.0)
    local engage = math.max(2.0, tonumber(C.route3_dogfight_engage) or 7.0)

    if st.phase == "close" then
        -- steer toward the foe in FULL 3D (track its altitude), face it
        if hd > 0.05 then st.yaw = math.atan(dx, dz) end
        local nx, ny, nz = tonumber(pos.x) or 0.0, tonumber(pos.y) or 0.0, tonumber(pos.z) or 0.0
        if d3 > 0.05 then
            local step = math.min(d3, speed * dt)
            nx = nx + dx / d3 * step; ny = ny + dy / d3 * step; nz = nz + dz / d3 * step
        end
        ny = route3_dogfight_clamp_altitude(go, ny)   -- never sink to a grounded pose
        local newpos = make_position(nx, ny, nz)
        S.route3_air_pos = newpos
        S.route3_air_rot = make_quat_yaw(tonumber(st.yaw) or 0.0)
        pcall(function() route3_apply_air_transform(ch, go, newpos, S.route3_air_rot) end)
        if d3 <= engage then
            st.phase = "strike"; st.phase_t0 = now; st.hit = {}
            -- beak-rush clip is played on strike ENTRY (st.strike_clip_on) so both entry paths match
        end
        S.route3_dogfight_status = string.format("closing d=%.1f", d3)
        return true

    elseif st.phase == "strike" then
        -- ⭐⭐ GALE STYLE (2026-08-04): hand the strike to the NATIVE Ch253GaleAttack node -- the
        -- move Aurora admired on Puppeteer's flying-X (decoded from Griffin.lua:250, airborne X
        -- branches straight to this one node). Fired through the LoopTheLoop machinery verbatim:
        -- fc-lift FIRST (the transform drive must stand down before the node's first frame -- two
        -- writers = the crash), lockout armed BEFORE the request, then the 4+0 request pair. The
        -- exit pump retires it and the loop camera films it, both for free, because both key off
        -- the lockout. Damage stays OURS (one-shot on the closed foe) -- native hits on a
        -- think-stopped FSM are not something we rely on.
        if tostring(C.route3_dogfight_style or "gale") == "gale" and not st.gale_tried then
            st.gale_tried = true    -- one attempt; on any failure fall through to the classic clip
            -- ⛔ re-check the cross-fire guard HERE too: the close phase takes time, and another
            -- attack node could have gone live between the press and this strike entry
            local blocked = false
            pcall(function() blocked = griffin_node_lockout_active() == true end)
            if blocked or S.route3_gustair or S.route3_node_exit_until then
                S.route3_dogfight = nil
                S.route3_dogfight_cooldown_at = os.clock()
                S.route3_dogfight_status = "blocked: another attack still running"
                return false      -- quiet unwind: no repaint, the OTHER node is still animating
            end
            local node = tostring(C.route3_dogfight_node or "Fly.FlightAttack.Ch253GaleAttack")
            -- ⭐ POUNCE SELECT: a grounded foe gets the TurnDash chain (Nick's LT move); an
            -- airborne foe (or empty sky) keeps the gale. Ground test = target within 3m of its
            -- own ground height.
            local pounce = false
            if C.route3_dogfight_pounce ~= false and not st.target then
                -- ⭐ EMPTY LOCK = the FLOURISH (2026-08-06, Aurora: "maybe just the pounce to the
                -- ground?"). No foe -> pounce onto a synthetic anchor on the ground ahead; the
                -- whole dash/skid/land chain runs at a spot instead of a soul.
                pounce = true
            end
            if C.route3_dogfight_pounce ~= false and st.target then
                -- ⭐ SPECIES test, not a ground raycast (2026-08-06: the raycast missed on a slope
                -- and a grounded saurian got the gale -- tape 12:01). Flyers (harpy/griffin) get
                -- the GALE; everything that lives on legs gets the POUNCE.
                local nm2 = tostring(go_name(tgo) or "")
                pounce = not (nm2:find("ch222", 1, true) or nm2:find("ch253", 1, true))
            end
            if pounce then node = "Fly.FlightAttack.Ch253FlightTurnDashAttackStartL" end
            if griffin_fsm_node_exists(node) then
                local leaf = node:match("([^%.]+)$") or node
                pcall(function()
                    griffin_rise_crash_mark(string.format("%s from-node=%s fire=%s",
                        pounce and "POUNCE" or "GALE-DIVE",
                        tostring(read_griffin_fsm_node() or "?"), leaf))
                end)
                pcall(function() route3_rise_fc_lift_begin(1.0, 3.5, now, leaf) end)   -- cover the full ~200-frame node
                pcall(function() griffin_node_lockout_begin(leaf, now, "gale") end)    -- NOT "rise": no cinematic camera
                -- ⭐⭐⭐ open the LIVE WINDOW before the request: the node's first frame must
                -- already have a live body, or its action code starts parked and never moves her
                pcall(function()
                    griffin_attack_live_window_open(leaf,
                        (pounce and (tonumber(C.route3_dogfight_pounce_max) or 4.2) or 3.4) + 0.5)
                end)
                pcall(function() request_griffin_action(leaf, 4) end)
                pcall(function() request_griffin_action(leaf, 0) end)
                pcall(function() griffin_rise_crash_mark("gale request SURVIVED") end)
                S.base_owner = { name = "rise", until_clock = now + 3.5 }
                -- ⛔ the recalm must OUTLIVE the live window (a 3.5s recalm re-parked the body
                -- mid-pounce, right at the drift-turn). The exit pump pulls it to NOW at the
                -- retire anyway, so a generous ceiling costs nothing.
                S.route3_rise_recalm_at = now + (pounce and 5.2 or 4.0)
                -- ⭐ the no-foe pounce needs its landing spot NOW: a synthetic anchor ~11m ahead
                -- on her heading, at the terrain's ground height (fallback: a little below her)
                if pounce and not st.target then
                    local yaw0 = tonumber(st.yaw) or 0.0
                    local px1 = (tonumber(pos.x) or 0.0) + math.sin(yaw0) * 11.0
                    local pz1 = (tonumber(pos.z) or 0.0) + math.cos(yaw0) * 11.0
                    -- ground height from under HER (space-consistent with the floor code); the
                    -- terrain 11m ahead is close enough, and the per-frame dash floor covers slope
                    local py1 = nil
                    pcall(function() py1 = route3_ground_y_robust(go) end)
                    st.tpin = { px1, py1 or ((tonumber(pos.y) or 0.0) - 4.0), pz1 }
                end
                -- ⛔ NO hit at fire range for EITHER style (2026-08-07, tape 16:54: the gale's
                -- fire-range hit killed the harpy instantly -- the foe-death handler nil'd the
                -- target on the FIRST ride tick and she flew a dead-straight no-homing line, the
                -- "misses a low harpy" report. Same bug the pounce already fixed at tape 21:49.)
                -- The gale's hit now lands at CONTACT (d3 gate in the ride), the pounce's at arrival.
                S.route3_dogfight_status = "GALE! (native node)"
                -- ⛔ DO NOT call route3_dogfight_end here (2026-08-05, Aurora: "the new dogfight
                -- only animates for a second"). That helper force-paints the flap takeoff clip
                -- IMMEDIATELY -- and my first version's claim that "the lockout paint gate blocks
                -- it" was WRONG: the paint gate is deliberately forced OFF (it removed the loop's
                -- exit). So end() stomped the node's animation ~1s in.
                -- ⭐ And DO NOT end the state machine either (Aurora, same night: the dive "all
                -- happens statically in one place" + "the movement stick affects the griffin
                -- during that animation"). Both symptoms have one cause: ending the dogfight
                -- state handed movement back to the stick-driven flight drive. Stay alive in a
                -- ride phase instead: we drive the dive's travel (on the parked FSM the node's
                -- action code moves NOTHING -- measured on the loop, pure joint animation), and
                -- while the dogfight state lives the flight drive yields, so the stick is out.
                st.phase = pounce and "pounceride" or "galeride"; st.phase_t0 = now
                st.gale_until = now + (pounce and math.max(2.0, tonumber(C.route3_dogfight_pounce_max) or 4.2) or 3.4)
                st.pounce_step = pounce and 1 or nil
                -- ⭐ FLIGHT RECORDER (2026-08-05): every pass writes _galetape.json on exit. Too
                -- many rounds of me guessing why "it just flies forward and back" -- this makes
                -- the next report factual: did the node fire, did the FSM ever SHOW it, did the
                -- lockout engage, why did the ride end, did the hit land.
                st.tape = {
                    build = "skid-v18-slide-slider",   -- ⭐ bump per build: proves which code the pass ran
                    style = pounce and "pounce" or "gale",
                    fired = leaf,
                    fsm_at_fire = tostring(read_griffin_fsm_node() or "?"),
                    had_target = st.target ~= nil,
                    target_name = tostring(go_name(tgo) or "?"),   -- why did the puma get the gale?
                    fsm_samples = {},
                    lockout_ever = false,
                    hit = false,
                }
                pcall(function() route3_flap_clear_overlay() end)
                return true
            end
            S.route3_dogfight_status = "gale node NOT FOUND -> classic strike"
        end
        -- play the beak-rush ONCE on strike entry (covers BOTH the homing entry and the
        -- no-target straight charge, which begins directly in this phase)
        if not st.strike_clip_on then
            st.strike_clip_on = true
            local lc = math.floor(tonumber(C.route3_dogfight_clip) or 511)
            if lc >= 0 then pcall(function() play_griffin_motion(lc, bank, true) end) end
        end
        -- charge forward on the locked heading; if a foe, drift toward its altitude; hit once
        local ny = tonumber(pos.y) or 0.0
        if st.target then
            local ymove = math.max(-speed * 0.4 * dt, math.min(speed * 0.4 * dt, dy))
            ny = ny + ymove
        end
        ny = route3_dogfight_clamp_altitude(go, ny)   -- never sink to a grounded pose
        local nx = (tonumber(pos.x) or 0.0) + math.sin(st.yaw) * speed * dt
        local nz = (tonumber(pos.z) or 0.0) + math.cos(st.yaw) * speed * dt
        -- no-target dash: stop before a solid so we never bore through a cliff/building
        if st.no_target == true then
            local stopd = math.max(1.0, tonumber(C.route3_dogfight_forward_stop) or 4.0)
            if route3_forward_blocked(go, st.yaw, stopd + speed * dt) then
                st.phase = "recover"; st.phase_t0 = now
                route3_restore_flight_base()
                S.route3_dogfight_status = "blocked by solid"
                return true
            end
        end
        local newpos = make_position(nx, ny, nz)
        S.route3_air_pos = newpos
        S.route3_air_rot = make_quat_yaw(tonumber(st.yaw) or 0.0)
        pcall(function() route3_apply_air_transform(ch, go, newpos, S.route3_air_rot) end)
        local yband = math.max(1.0, tonumber(C.route3_dogfight_yband) or 6.0)
        if st.target and math.abs(dy) <= yband and not st.hit[st.target]
            and route3_dogfight_beak_contact(st, newpos, tpos) then
            st.hit[st.target] = true
            route3_dogfight_record_hit(st.target)   -- capture HP before/after -> on-screen readout
            local snd = math.floor(tonumber(C.route3_dogfight_hit_sound_id) or 0)
            if snd > 0 then pcall(function() route3_play_wwise_trigger_id(snd, "dogfight_hit") end) end
        end
        if (now - (tonumber(st.phase_t0) or now)) >= math.max(0.2, tonumber(C.route3_dogfight_strike_secs) or 0.9) then
            st.phase = "recover"; st.phase_t0 = now
            route3_restore_flight_base()   -- back to the glide clip, STILL AIRBORNE
            S.route3_dogfight_reseek_clip = math.floor(tonumber(C.flap_takeoff_clip) or 5210)
            S.route3_dogfight_reseek_until = os.clock() + 2.0   -- keep the flap out of its takeoff intro through recover
        end
        return true

    elseif st.phase == "galeride" or st.phase == "pounceride" then
        -- the native node owns the ANIMATION; we own the TRAVEL (see the gale branch note).
        -- Same movement maths as the strike charge, no clip painting anywhere in this phase.
        -- ⭐ FLY-THROUGH, NOT ORBIT (2026-08-05, Aurora: "jittering, spinning, vibrating...
        -- trying to keep animating into the harpy"). Homing all the way to contact means atan
        -- noise at point-blank (the spin) and grinding into the foe's collision (the vibration).
        -- A real dive is COMMITTED: track only while approaching (>6m), then hold the line and
        -- pass through. After the hit lands, never re-home.
        -- ⭐⭐ LANDING ANCHOR (2026-08-06, tape 21:49: our own hit KILLED the goblin at 9m out;
        -- the foe-death handler nil'd the target, the arrival check needed one, so she dashed
        -- 41m past the corpse. The pounce aims at a SPOT, not a soul: pin the foe's position
        -- every frame it lives, keep homing/landing on the pin when it dies mid-dash.)
        local adx, adz, ahd = dx, dz, hd
        local apy = tpos and tonumber(tpos.y) or nil
        if st.phase == "pounceride" then
            -- ⛔ the anchor FREEZES at the strike (2026-08-06, Aurora: "it follows the goblin
            -- without facing it after the first touch down slide"): tracking a live runner
            -- through the skid/landing turns the touchdown into a sideways chase. The landing
            -- spot is DECIDED the moment she slams in.
            if tpos and (tonumber(st.pounce_step) or 1) < 3 then
                st.tpin = { tonumber(tpos.x) or 0.0, tonumber(tpos.y) or 0.0, tonumber(tpos.z) or 0.0 }
            elseif st.tpin then
                adx = st.tpin[1] - (tonumber(pos.x) or 0.0)
                adz = st.tpin[3] - (tonumber(pos.z) or 0.0)
                ahd = math.sqrt(adx * adx + adz * adz)
                apy = st.tpin[2]
            end
        end
        -- ⭐⭐⭐ FC OWNS ALTITUDE -- COMMAND IT, DON'T FIGHT IT (2026-08-07, tape 17:50: dy held
        -- -2.0..-2.8 through the WHOLE drift + flare, even with fce=false, while our x/z brake
        -- visibly worked -- raw y-writes lose to the engine's flight stack every frame. The live
        -- window seeds setGroundHeight ONCE at fire, cast under her ~14m from the foe: the engine
        -- "lands" on that stale believed ground -- Aurora's own words days ago: "it hits the
        -- 'ground' in mid air". Feed the ANCHOR's real ground every tick; from the carve on,
        -- command the air target down to boot height too.)
        -- (per-tick setGroundHeight feed REMOVED 2026-08-07: same believed-ground lie as the
        -- reverted window-open target seed -- never fixed the float, and that plumbing feeds
        -- more than FC (the WallCheck crash). The hover is an accepted trade.)
        local aiming = (st.target ~= nil) or (st.phase == "pounceride" and st.tpin ~= nil)
        if not st.no_home and aiming and ahd < 1.0e8 and ahd > 6.0 then st.yaw = math.atan(adx, adz) end
        -- ⭐ POUNCE CHAIN STEP: StartL (the banking drift-in) hands to AirLoopL on a timer
        -- (~frame 158, Nick's own handoff point). Same fire kit, lockout re-armed on the new leaf.
        local function pounce_fire_step(leaf2, extend_secs)
            pcall(function() griffin_node_lockout_begin(leaf2, now, "gale") end)
            pcall(function() request_griffin_action(leaf2, 4) end)
            pcall(function() request_griffin_action(leaf2, 0) end)
            -- ⛔ every timer that can re-park her mid-move must OUTLIVE the new step
            st.gale_until = now + extend_secs
            S.route3_rise_recalm_at = math.max(tonumber(S.route3_rise_recalm_at) or 0.0, now + extend_secs + 0.5)
            if type(S.route3_live_window) == "table" then
                S.route3_live_window.until_clock = math.max(tonumber(S.route3_live_window.until_clock) or 0.0, now + extend_secs + 0.5)
            end
            st.step_t0 = now
        end
        if st.pounce_step == 1
            and (now - (tonumber(st.phase_t0) or now)) >= math.max(0.5, tonumber(C.route3_dogfight_pounce_windup_secs) or 1.9) then
            st.pounce_step = 2
            pounce_fire_step("Ch253FlightTurnDashAttackAirLoopL",
                math.max(2.0, tonumber(C.route3_dogfight_pounce_max) or 4.2))
        end
        -- ⭐⭐⭐ THE LANDING BEATS (2026-08-06, tape 21:42: she DASHED 7.4m dead onto the goblin --
        -- travel works -- then PINNED 1.2m above it while fmv decayed: the approach maths clamps
        -- at its destination and the chain had no ending. The video's money shot IS the ending:
        -- skim-dash -> planted DRIFT-TURN around the foe -> LANDING FLARE at it. Both nodes exist
        -- (GriffinNodes_FULL): ...DriftTurnL / ...AirToLandL. Arrival now advances the chain.)
        if st.pounce_step == 2 and aiming and not st.no_home
            and ahd <= math.max(1.0, tonumber(C.route3_dogfight_pounce_arrive_m) or 2.5) then
            st.pounce_step = 3
            st.no_home = true   -- committed: the drift carves on the locked line, no more homing
            -- ⭐ THE STRIKE LANDS HERE (2026-08-06): damaging at fire range killed the goblin
            -- 10m before arrival and cost the landing. The pounce's hit belongs to the moment
            -- she slams in over the target -- the drift-turn IS the strike.
            if st.target and not st.hit[st.target] then
                st.hit[st.target] = true
                route3_dogfight_record_hit(st.target)
                if st.tape then st.tape.hit = true end
                if C.route3_dogfight_blowback ~= false then
                    pcall(function() route3_gust_finale_blow(6.0) end)
                end
                local snd = math.floor(tonumber(C.route3_dogfight_hit_sound_id) or 0)
                if snd > 0 then pcall(function() route3_play_wwise_trigger_id(snd, "dogfight_hit") end) end
            end
            -- remember WHERE THE FOE STANDS (the capsule to stay clear of during the skid)
            if st.tpin then st.spin = { st.tpin[1], st.tpin[3] } end
            -- ⭐ v17 MOMENTUM LOCK (Aurora: the skid "goes a little bit of a random direction
            -- -- really it should go straight in the direction it was flying"): freeze the
            -- slide vector to the DASH heading at impact; the carve rotates the BODY on top.
            st.slide_yaw = tonumber(st.yaw) or 0.0
            -- ⭐⭐⭐ THE SKID IS A GROUND MOVE NOW (2026-08-07, tape 17:59: _AirTargetPosY=0.2
            -- confirmed WRITTEN yet agl held 1.7-2.9 through drift AND flare -- the flight stack
            -- ignores even its own commanded air target during a live window. The altitude-law
            -- memory's own words: don't out-write FC; if its beliefs won't move, HAND OFF. So the
            -- strike GROUNDS her on the spot with route3_finish_landing -- the one grounding tool
            -- with a 100% record -- and the drift/flare beats play as parked joint animation
            -- while the gearbox slides her through the dirt. A grounded body obeys our
            -- transforms completely (every ground ride proves it); the float cannot exist here.)
            -- ⛔⛔ GROUNDED-SKID EXPERIMENT REVERTED (2026-08-07, Aurora: "it's not doing the
            -- cool slide/skid animation, you're just turning her... It looked BETTER before
            -- even if it was hovering above the ground"). Landing at the strike killed the
            -- node-driven drift animation -- the painted-clip version reads as a turn, not the
            -- skid. VERDICT: the NODE CHAIN's look wins; the ~2m hover is the lesser evil and
            -- gets attacked at its source instead (the live window's believed-ground seed).
            pounce_fire_step("Ch253FlightTurnDashAttackDriftTurnL",
                math.max(0.5, tonumber(C.route3_dogfight_pounce_drift_secs) or 1.2)
                + math.max(0.5, tonumber(C.route3_dogfight_pounce_land_secs) or 1.6) + 0.5)
            -- ⛔⛔ v14 — MINIMUM TOGGLES, EVERYTHING ALIVE. FC-disable + AdjustTerrain-enable
            -- DROPPED from the skid stack: both were float levers aimed at the wrong thief
            -- (the clearance net, since stood down), and FC-dead is what made her AI's patrol
            -- actions lethal (the 19:58 crash) -- which forced decider-off, which crashed the
            -- decision evaluator (20:05, 20:30). Breaking the circle at its origin: FC STAYS
            -- ALIVE and is COMMANDED low instead. Every v8-v10 "belief writes are ignored"
            -- verdict was contaminated by the net; this is the lever's first clean trial.
            pcall(function()
                local fcd = get_component(go, "app.FlightControl")
                if fcd then
                    local low = ((st.tpin and tonumber(st.tpin[2])) or (tonumber(pos.y) or 0.0) - 2.0) + 0.2
                    pcall(function() fcd:call("set_AirTargetPosY", low) end)
                    pcall(function() fcd:set_field("_AirTargetPosY", low) end)
                end
            end)
            -- ⭐⭐⭐ THE NAMED KILL (v10, tape 19:36 -- KEPT in v14): ROOT MOTION re-poses the
            -- root to the anim's flight altitude every frame (stolen=+0.25..+0.30). Re-apply
            -- the mount's root-motion law for the skid: joints keep playing the drift
            -- animation, the root belongs to our gearbox alone.
            pcall(function() apply_griffin_motion_root_mode() end)
            -- ⭐ SKID DIAGNOSTIC: state snapshot at the drift fire (v14: no levers to verify
            -- beyond rm + fce -- fce should now read TRUE)
            do
                local diag = { fce_after = "?", rm_after = "?" }
                pcall(function()
                    local fcv = get_component(go, "app.FlightControl")
                    if fcv then diag.fce_after = tostring(fcv:call("get_Enabled")) end
                end)
                pcall(function() diag.rm_after = tostring(ch:call("get_Motion"):call("get_RootMotion")) end)
                if st.tape then st.tape.skid_diag = diag end
            end
        end
        if st.pounce_step == 3 then
            -- ⭐ HAND OFF WHEN THE DRIFT ACTUALLY ENDS (2026-08-06, Aurora: skid -> "instantly
            -- into a flying animation with no transition" -> re-land. DriftTurnL self-exits
            -- before the 1.2s timer; the FSM falls back to the Fly tree in the gap and the whole
            -- weird tail follows). Fire the flare the moment the FSM leaves the drift node.
            local dt_done = (now - (tonumber(st.step_t0) or now))
                >= math.max(0.5, tonumber(C.route3_dogfight_pounce_drift_secs) or 1.2)
            local drift_gone = false
            -- (FSM check is AIR-ONLY: the grounded skid's FSM is puppeted -- timer is the law)
            if (not st.grounded_skid) and not dt_done and (now - (tonumber(st.step_t0) or now)) > 0.4 then
                pcall(function()
                    drift_gone = not tostring(read_griffin_fsm_node() or ""):find("DriftTurn", 1, true)
                end)
            end
            if dt_done or drift_gone then
                st.pounce_step = 4
                if C.route3_dogfight_pounce_end_at_skid ~= false then
                    -- ⭐⭐ END AT THE SKID (2026-08-07, Aurora: "I'd be happy if the animation
                    -- ended at the end of the bank/skid... just end after the slide is done").
                    -- v15: the slide's LAST BEAT is a planted pivot to FACE the goblin
                    -- ("turn around to face the goblin"), then a QUIET grounding -- no
                    -- touchdown-slam clip on a body that's already in the dirt.
                    st.face_beat = true
                    st.gale_until = now + 0.35
                    S.route3_landing_quiet = true
                else
                    -- legacy flare + return-to-foe leg (config: set end_at_skid = false)
                    pounce_fire_step("Ch253FlightTurnDashAttackAirToLandL",
                        math.max(0.5, tonumber(C.route3_dogfight_pounce_land_secs) or 1.6) + 1.2)
                end
            end
        end
        -- ⭐ GALE FLY-THROUGH: an airborne pass has no landing -- on arrival just commit the line
        -- and carry the momentum THROUGH the foe (the pin-and-hang was homing to a fixed point).
        -- ⛔ 3D distance, not horizontal (2026-08-06, Aurora: "moves forward but doesn't connect"
        -- -- charging 5m BELOW the harpy read hd<2 and committed early: she passed underneath)
        if st.phase == "galeride" and st.target and not st.no_home and d3 <= 2.5 then
            st.no_home = true
        end
        -- ⭐ HOLD DURING THE WIND-UP (Aurora: "it moves even during the windup animation"): she
        -- hangs in place aiming until the node's rear-up is done, THEN the charge launches. The
        -- stick stays locked out the whole time (the dogfight state owns movement either way).
        -- (the pounce's StartL is itself a moving drift-in, so it charges from frame one)
        local charging = (st.phase == "pounceride")
            or (now - (tonumber(st.phase_t0) or now)) >= math.max(0.0, tonumber(C.route3_dogfight_gale_windup) or 0.9)
        -- ⭐⭐ DIVE PROFILE (2026-08-05, Aurora: "still flying over their head"). The old travel
        -- kept the 4m CRUISE clamp on the whole pass -- a dive that is forbidden to descend can
        -- only ever hover over the target, which is exactly the "forward and back above its head"
        -- she has been describing for three rounds. A dive gets three stages instead:
        --   approach  = full-3D straight line onto a point just above the foe (1m ground floor)
        --   committed = inside 6m the yaw freezes (no atan spin) and the line is held
        --   pull-out  = after the hit, climb away forward; cruise clamp applies again
        -- ⭐ NATIVE MODE (Aurora): write NO transforms -- the node + FlightControl own movement.
        -- ⭐⭐⭐ BUT FEED THE SEEKER (2026-08-06, the fifth lever): FC is a TARGET-SEEKING
        -- controller (surface dump: setFlightTargetPosition / set_TargetPosition /
        -- AimTargetPosition / updateTarget). On a wild griffin the AI feeds it the prey; our AI
        -- is (rightly) off, so nobody ever told FC where the attack was going -- tape 12:13
        -- shows 14m of real but AIMLESS movement. We play the AI's one-line role: foe position
        -- into FC each frame + Nick's verbatim TargetAngleCtrl steer for the body aim.
        if tostring(C.route3_dogfight_drive or "native") == "native"
            and C.route3_dogfight_fc_seek ~= false and st.target and not st.no_home then
            local trp = tgo and transform_render_pos(tgo)
            if trp then
                -- errors were being swallowed by bare pcalls -- tape the FIRST failure of each
                -- write so a rejected call is a fact in the recorder, not a silent no-op
                local function seek_try(tag, fn)
                    local ok, err = pcall(fn)
                    if not st.tape then return end
                    if ok then
                        st.tape.fc_writes = (tonumber(st.tape.fc_writes) or 0) + 1
                        st.tape.fc_ok = st.tape.fc_ok or {}
                        st.tape.fc_ok[tag] = (tonumber(st.tape.fc_ok[tag]) or 0) + 1
                    else
                        st.tape.fc_fail = st.tape.fc_fail or {}
                        if not st.tape.fc_fail[tag] then st.tape.fc_fail[tag] = tostring(err) end
                    end
                end
                local fc = nil
                pcall(function() fc = get_component(go, "app.FlightControl") end)
                if fc then
                    local v = make_vec3(tonumber(trp.x) or 0.0, tonumber(trp.y) or 0.0, tonumber(trp.z) or 0.0)
                    seek_try("setFlightTargetPosition", function() fc:call("setFlightTargetPosition", v) end)
                    seek_try("set_TargetPosition", function() fc:call("set_TargetPosition", v) end)
                    seek_try("set_AirTargetPosY", function() fc:call("set_AirTargetPosY", tonumber(trp.y) or 0.0) end)
                    -- ⭐⭐ THE PUMP (2026-08-06, tape 20:24: fmv ramps to 1.00 yet moved=0.0 --
                    -- FC computes the dash's thrust and nothing INTEGRATES it while mounted).
                    -- Same fallback rung the fc-lift carries for this exact symptom: force the
                    -- component live and call its own integration step ourselves, every frame.
                    if C.route3_dogfight_fc_pump ~= false then
                        seek_try("set_Enabled", function()
                            if fc:call("get_Enabled") ~= true then
                                fc:call("set_Enabled", true)
                                if st.tape then st.tape.fc_was_disabled = true end
                            end
                        end)
                        -- ⛔ Do not manually advance updateAttitude/updatePosition.  The component
                        -- already updates on the engine schedule once enabled; calling its integrator
                        -- again from on_frame accumulates a private dash state that survives disable
                        -- and corrupts the next LoopTheLoop.  We only ask the seeker to calculate the
                        -- throttle signal consumed by the Lua gearbox below.
                        seek_try("updateTarget", function() call_flight_control(fc, "updateTarget()") end)
                        seek_try("updateUniqueMove", function() call_flight_control(fc, "updateUniqueMove()") end)
                        seek_try("updatePeriodMove", function() call_flight_control(fc, "updatePeriodMove()") end)
                    end
                elseif st.tape and not st.tape.fc_err then
                    st.tape.fc_err = "no app.FlightControl component"
                end
                seek_try("TargetAngleCtrl", function()
                    -- Nick's steer() verbatim (Bestiary/MovesetHandler/NodeCore.lua:116)
                    local tac = ch["<TargetAngleCtrl>k__BackingField"]
                    if tac then
                        local deg = math.deg(math.atan(dx, dz))
                        tac.Front["<AngleDeg>k__BackingField"] = deg
                        tac.Move["<AngleDeg>k__BackingField"] = deg
                    end
                end)
            end
        end
        -- ⭐⭐⭐ THE GEARBOX (2026-08-06, tape 21:03: ALL ten FC calls succeed 151x, fce=true the
        -- whole ride, fmv thrusting -- and moved=0.0 EXACT. The engine's applier is walled for a
        -- ridden body; no method call reaches it. But the node BROADCASTS its choreography:
        -- fmv=0.00 through the whole StartL windup, 0.68->0.86 the instant AirLoopL's dash begins.
        -- So the native node keeps the animation, FC keeps computing the THROTTLE, and we apply
        -- the metres -- paced by the node's own thrust signal, so movement and animation cannot
        -- desync. Direction = the committed dive line (st.yaw freezes inside 6m, no_home after
        -- the hit -- all the anti-orbit laws stay). Writer = route3_apply_air_transform, the one
        -- proven to move her mid-ride in the dive era. Native data, Lua gearbox.
        if tostring(C.route3_dogfight_drive or "native") == "native"
            and C.route3_dogfight_native_gearbox ~= false then
            local thr = 0.0
            pcall(function()
                local fc = get_component(go, "app.FlightControl")
                local mv = fc and fc:get_field("FlightMoveVector")
                if mv then thr = math.sqrt((mv.x or 0)^2 + (mv.y or 0)^2 + (mv.z or 0)^2) end
            end)
            if thr > 1.0 then thr = 1.0 end
            -- the drift/landing nodes may idle their thrust vector -- carve and touchdown still
            -- need travel, so those beats carry a minimum throttle of their own
            if st.pounce_step == 3 then thr = math.max(thr, 0.4)
            elseif st.pounce_step == 4 then thr = math.max(thr, 0.5) end
            -- ⭐ CREEP-IN during the windup (2026-08-07, Aurora: "start the dive/movement a
            -- little earlier"): StartL's own fmv is 0.00, so she used to hang dead-still through
            -- the whole rear-up. A slow advance toward the foe makes the windup part of the dive.
            if st.phase == "pounceride" and (tonumber(st.pounce_step) or 0) == 1 then
                thr = math.max(thr, 0.25)
            elseif st.phase == "pounceride" and (tonumber(st.pounce_step) or 0) == 2 then
                -- Deterministic dash fallback: no dependence on a manually-pumped FC integrator.
                thr = math.max(thr, 1.0)
            end
            -- ⭐ GALE CHARGE (tape 02:43: GaleAttack's own fmv is 0.00 for its WHOLE ride -- the
            -- node is a stationary wind-buffet, so a faithful gearbox went nowhere at the harpy).
            -- After the windup, the gale carries its own committed charge speed.
            if st.phase == "galeride" and charging then thr = math.max(thr, 0.85) end
            if st.tape then st.tape.thr_peak = math.max(tonumber(st.tape.thr_peak) or 0.0, thr) end
            if thr > 0.05 then
                local px0, py0, pz0 = tonumber(pos.x) or 0.0, tonumber(pos.y) or 0.0, tonumber(pos.z) or 0.0
                local nx, ny, nz = px0, py0, pz0
                local step = thr * speed * dt
                -- ⭐ THE CARVE (step 3; tape 21:54: the drift held the dash line and ran 6m past
                -- the goblin, so the flare landed 10m from the kill). The video's drift-turn is a
                -- BRAKED bank AROUND the plant point: curve the heading, cut the speed.
                if st.pounce_step == 3 then
                    st.yaw = (tonumber(st.yaw) or 0.0) + (tonumber(C.route3_dogfight_pounce_drift_rate) or -1.9) * dt
                    -- slide length slider (v18, Aurora: "slide a bit further") -- scales the
                    -- momentum slide only; the spin/turn is untouched
                    step = step * 0.45
                        * math.max(0.2, math.min(3.0, tonumber(C.route3_dogfight_skid_slide_scale) or 2.0))
                    -- ⭐ WALL GUARD (v16, Aurora: skidded next to a building and "clipped it a
                    -- little"): probe along the slide each tick -- a solid within body reach
                    -- keeps the TURN but kills the slide, so she carves in place at the wall
                    -- instead of through it (v17: probe the MOMENTUM line, which is what the
                    -- slide actually travels now, not the rotating body yaw)
                    pcall(function()
                        if route3_forward_blocked(go, st.slide_yaw or st.yaw, 1.6 + step) then step = 0.0 end
                    end)
                end
                if aiming and not st.no_home and apy ~= nil then
                    -- 3D line onto a point just above the foe -- or its landing ANCHOR if our
                    -- strike already killed it (the dive's proven approach maths either way).
                    -- The pounce aims LOW (screenshot 08-06: the skid hung ~1.5m up and "looks
                    -- weird" -- the video skims at knee height). ⛔ The gale aims AT the harpy's
                    -- body too (2026-08-07: +1.2m aim over a LOW flyer = she tops out above it
                    -- and sails over -- the "goes over" report; the ground floor below still
                    -- keeps her out of the dirt).
                    local hover = (st.phase == "pounceride") and 0.5 or 0.3
                    local ady = ((tonumber(apy) or py0) + hover) - py0
                    local d3d = math.sqrt(adx * adx + ady * ady + adz * adz)
                    if d3d > 0.05 then
                        step = math.min(d3d, step)
                        nx = px0 + adx / d3d * step
                        ny = py0 + ady / d3d * step
                        nz = pz0 + adz / d3d * step
                    end
                else
                    -- committed / post-hit: hold the line and fly through
                    local myaw = tonumber(st.yaw) or 0.0
                    -- ⭐ v17 MOMENTUM SKID: the slide travels the locked DASH heading and
                    -- decays like friction (to ~35% by the drift's end) while the body spins
                    -- on top -- "straight in the direction it was flying, then spin round"
                    if st.phase == "pounceride" and st.pounce_step == 3 and st.slide_yaw then
                        myaw = tonumber(st.slide_yaw) or myaw
                        local frac = math.min(1.0, (now - (tonumber(st.step_t0) or now))
                            / math.max(0.3, tonumber(C.route3_dogfight_pounce_drift_secs) or 1.2))
                        step = step * (1.0 - 0.65 * frac)
                    end
                    nx = px0 + math.sin(myaw) * step
                    nz = pz0 + math.cos(myaw) * step
                end
                -- ⭐⭐ THE RETURN (2026-08-07, Aurora reversed the 08-06 call after seeing both:
                -- "I don't mind the fly again and the landing after that but I would want the
                -- griffin to face the goblin again and actually go back to the goblin" -- the
                -- in-place flare left her landing wherever the carve pointed, nowhere near the
                -- kill). Step 4 re-aims at the ANCHOR and flies the flare BACK onto it: yaw
                -- faces the goblin the whole leg, the 3D line lands on the spot, ride-end's
                -- finish_landing grounds her there.
                if st.pounce_step == 4 and st.face_beat then
                    -- ⭐ FACE-THE-FOE BEAT (v15): planted at the carve's end, she pivots to
                    -- the goblin (live one if it ran, the pin over a corpse) and the ride
                    -- ends. No translation -- just the turn.
                    local ftx, ftz
                    if st.target and tpos then
                        ftx, ftz = tonumber(tpos.x), tonumber(tpos.z)
                    elseif st.tpin then
                        ftx, ftz = st.tpin[1], st.tpin[3]
                    end
                    if ftx then
                        local want = math.atan(ftx - px0, ftz - pz0)
                        local diff = (want - (tonumber(st.yaw) or 0.0) + math.pi) % (2.0 * math.pi) - math.pi
                        local maxr = 7.0 * dt
                        if diff > maxr then diff = maxr elseif diff < -maxr then diff = -maxr end
                        st.yaw = (tonumber(st.yaw) or 0.0) + diff
                    end
                    nx, nz = px0, pz0   -- planted; the clamp below pins ny to the dirt
                elseif st.pounce_step == 4 then
                    -- ⛔ return target = the LIVE goblin when it SURVIVED the strike (tape
                    -- 18:59: it ran; the frozen pin was an empty patch of dirt 1m away, so the
                    -- arrival check ended the ride one tick into the flare and she "returned"
                    -- to nothing while the goblin stood 6m off). The pin only over a corpse.
                    local rtx, rty, rtz
                    if st.target and tpos then
                        rtx, rty, rtz = tonumber(tpos.x) or px0, tonumber(tpos.y) or py0, tonumber(tpos.z) or pz0
                    elseif st.tpin then
                        rtx, rty, rtz = st.tpin[1], st.tpin[2], st.tpin[3]
                    end
                    if rtx then
                        local rdx = rtx - px0
                        local rdz = rtz - pz0
                        local rhd = math.sqrt(rdx * rdx + rdz * rdz)
                        if rhd > 0.6 then st.yaw = math.atan(rdx, rdz) end
                        local rdy = ((tonumber(rty) or py0) + 0.4) - py0
                        local rd3 = math.sqrt(rdx * rdx + rdy * rdy + rdz * rdz)
                        if rd3 > 0.05 then
                            local rstep = math.min(rd3, step)   -- full-speed home, clamps AT the spot
                            nx = px0 + rdx / rd3 * rstep
                            ny = py0 + rdy / rd3 * rstep
                            nz = pz0 + rdz / rd3 * rstep
                        end
                        -- ARRIVED back at the foe: end the ride NOW -- ride-end grounds her here
                        if rhd <= 1.2 then st.gale_until = now end
                    else
                        -- no anchor (shouldn't happen): the old in-place settle
                        nx = px0 + (nx - px0) * 0.25
                        nz = pz0 + (nz - pz0) * 0.25
                        ny = py0 - 3.5 * dt
                    end
                end
                pcall(function()
                    -- ⭐ GROUNDED SKID: she has genuinely LANDED (finish_landing at the strike) --
                    -- ride the dirt line outright. Physics handles the corpse bump natively now
                    -- that she is a grounded body; no hold-off gate needed down here.
                    if st.grounded_skid then
                        local gsy = tonumber(st.skid_y) or (st.tpin and tonumber(st.tpin[2]))
                        if gsy then ny = gsy + 0.05 end
                        return
                    end
                    local gy = route3_ground_y_robust(go, ny)
                    -- ⛔ near the foe the cast under her hits ITS collision top = an invisible
                    -- pedestal. Through the skid + landing the ANCHOR's ground (where the foe's
                    -- feet were) is the authority, not the cast.
                    local base = gy
                    if st.tpin and ((tonumber(st.pounce_step) or 0) >= 3) then base = st.tpin[2] end
                    if base then
                        -- ⛔ HER CAPSULE CAN'T OCCUPY THE FOE'S (Aurora's diagnosis): inside the
                        -- foe's radius, don't force her into the dirt -- physics just surfs her
                        -- on its collider (the floating skid). Glide OVER it; drop when clear.
                        -- ⛔ 2026-08-07: the 1.6m/1.2m version of this gate WAS the float. The
                        -- carve's turn radius (~1.5m at drift speed) orbits the plant point
                        -- entirely INSIDE a 1.6m circle, so the "glide over the foe" hold-off
                        -- applied to the WHOLE bank -- Aurora watched the exact 1.2m float the
                        -- gate was meant to prevent. The foe is also DEAD by step 3 (the arrival
                        -- strike) -- a ragdolling corpse barely pushes back. Exclusion shrunk to
                        -- the real capsule (0.8m) and the hold-off to a wing-brush 0.5m.
                        local clear = true
                        if st.spin and (tonumber(st.pounce_step) or 0) >= 3 then
                            local cdx, cdz = px0 - st.spin[1], pz0 - st.spin[2]
                            clear = (cdx * cdx + cdz * cdz) > 0.64   -- 0.8m radius
                        end
                        local floor_m = 1.0   -- gale clearance
                        if st.pounce_step == 4 then
                            floor_m = clear and 0.05 or 0.5    -- touchdown (brush over the corpse)
                        elseif st.pounce_step == 3 then
                            if clear then
                                -- PLANTED skid: with FC disabled at the drift fire nothing
                                -- re-asserts altitude any more -- SLEW her down onto the dirt
                                -- (8 m/s, not a single-frame snap) and hold her there
                                local tgt_y = base + 0.15
                                if ny > tgt_y then ny = math.max(tgt_y, py0 - 8.0 * dt) end
                                floor_m = 0.15
                            else
                                floor_m = 0.5  -- directly over the corpse: low brush, no dirt-fight
                            end
                        elseif st.phase == "pounceride" then
                            floor_m = 0.35    -- the dash SKIMS at knee height (the video's look)
                        end
                        if ny < base + floor_m then ny = base + floor_m end
                    end
                end)
                local newpos = make_position(nx, ny, nz)
                S.route3_air_pos = newpos
                S.route3_air_rot = make_quat_yaw(tonumber(st.yaw) or 0.0)
                pcall(function() route3_apply_air_transform(ch, go, newpos, S.route3_air_rot) end)
                -- v9 forensics: remember what we WROTE; next tick's live read exposes the thief
                st.dbg_write_y = ny
            end
        end
        if tostring(C.route3_dogfight_drive or "native") == "dive" then
            local px0, py0, pz0 = tonumber(pos.x) or 0.0, tonumber(pos.y) or 0.0, tonumber(pos.z) or 0.0
            local nx, ny, nz = px0, py0, pz0
            if charging then
                if st.target and not st.no_home and tpos then
                    local ady = ((tonumber(tpos.y) or py0) + 1.2) - py0
                    local d3d = math.sqrt(dx * dx + ady * ady + dz * dz)
                    if d3d > 0.05 then
                        local step = math.min(d3d, speed * dt)
                        nx = px0 + dx / d3d * step
                        ny = py0 + ady / d3d * step
                        nz = pz0 + dz / d3d * step
                    end
                    pcall(function()
                        local gy = route3_ground_y_robust(go, ny)
                        if gy and ny < gy + 1.0 then ny = gy + 1.0 end
                    end)
                else
                    nx = px0 + math.sin(st.yaw) * speed * dt
                    nz = pz0 + math.cos(st.yaw) * speed * dt
                    ny = py0 + (st.no_home and (speed * 0.25 * dt) or 0.0)   -- pull-out climbs away
                    ny = route3_dogfight_clamp_altitude(go, ny)
                end
            end
            local newpos = make_position(nx, ny, nz)
            S.route3_air_pos = newpos
            S.route3_air_rot = make_quat_yaw(tonumber(st.yaw) or 0.0)
            pcall(function() route3_apply_air_transform(ch, go, newpos, S.route3_air_rot) end)
        end
        -- GALE only: the pounce strikes at arrival (step 3), and its no_home must stay false
        -- until then or the landing beats can never fire. ⛔ CONTACT range, not engage range
        -- (2026-08-07): the old hd<=7m gate landed the kill far out -- with the fire-range hit
        -- gone that would just re-create the same early-death/no-homing bug one ring later.
        -- She strikes when she is ON the foe; the commit + fly-through follow in the same beat.
        if st.phase == "galeride" and st.target and not st.hit[st.target]
            and route3_dogfight_beak_contact(st, pos, tpos) then
            st.hit[st.target] = true
            route3_dogfight_record_hit(st.target)
            if st.tape then st.tape.hit = true end
            st.no_home = true   -- the hit is landed: commit the line and fly THROUGH (see above)
            -- ⭐ PHYSICAL IMPACT (Aurora: the foe "doesn't seem to even respond"): synthetic damage
            -- cannot stagger (engine wall, documented) -- but the gust's blowback CAN shove. One
            -- pulse around her at the moment of contact = the foe visibly reels from the pass.
            if C.route3_dogfight_blowback ~= false then
                pcall(function() route3_gust_finale_blow(6.0) end)
            end
            local snd = math.floor(tonumber(C.route3_dogfight_hit_sound_id) or 0)
            if snd > 0 then pcall(function() route3_play_wwise_trigger_id(snd, "dogfight_hit") end) end
        end
        S.base_owner = { name = "rise", until_clock = now + 0.6 }   -- keep painters parked while we ride
        -- ⛔⛔ DO NOT read the motion layer's playhead to detect "animation over" (2026-08-05,
        -- reverted same night). L0 still reports OUR painted glide loop during a node ride, and a
        -- looping clip crosses its endframe every cycle -- so the "end when the clip ends" check
        -- force-retired the gale/pounce within frames of firing. Aurora saw NO attack animation at
        -- all, just the bare travel maths ("the same weird forward and backward thing"). The ride
        -- ends on its own timer; the freeze is handled by forcing the lockout ceiling AT ride end
        -- (below), so the pump retires her immediately instead of holding the final pose.
        local locked = false
        pcall(function() locked = griffin_node_lockout_active() == true end)
        if st.tape then
            if locked then st.tape.lockout_ever = true end
            if now >= (tonumber(st.tape.next_at) or 0.0) then
                st.tape.next_at = now + 0.4
                -- rm = the LIVE RootMotion mode (must read 2/Continuance for the whole ride --
                -- anything else means something re-suppressed it behind the window's back)
                local rm = "?"
                pcall(function() rm = tostring(ch:call("get_Motion"):call("get_RootMotion")) end)
                -- ⭐ SELF-MOVEMENT (2026-08-06): hd alone can't tell "we moved" from "the target
                -- moved" (the 12:13 misread). Track OUR live position delta + FC's own thrust
                -- vector -- moved= is cumulative metres SHE has covered since the fire.
                local sx, sy, sz = tonumber(pos.x) or 0.0, tonumber(pos.y) or 0.0, tonumber(pos.z) or 0.0
                local moved = tonumber(st.tape.self_moved) or 0.0
                if st.tape.last_sp then
                    local mdx, mdy, mdz = sx - st.tape.last_sp[1], sy - st.tape.last_sp[2], sz - st.tape.last_sp[3]
                    moved = moved + math.sqrt(mdx * mdx + mdy * mdy + mdz * mdz)
                end
                st.tape.last_sp = { sx, sy, sz }
                st.tape.self_moved = moved
                local fmv, fce = "?", "?"
                pcall(function()
                    local fc = get_component(go, "app.FlightControl")
                    local mv = fc and fc:get_field("FlightMoveVector")
                    if mv then fmv = string.format("%.2f", math.sqrt((mv.x or 0)^2 + (mv.y or 0)^2 + (mv.z or 0)^2)) end
                    if fc then fce = tostring(fc:call("get_Enabled")) end
                end)
                -- ⭐ Y-FIGHT FORENSICS (2026-08-07): agl = her height over the ANCHOR's ground,
                -- aty = FC's live _AirTargetPosY relative to that same ground. If agl stays high
                -- while aty is low, the engine is ignoring even its own commanded air target.
                local yfx = ""
                if st.tpin and st.phase == "pounceride" then
                    local agl = (tonumber(pos.y) or 0.0) - (tonumber(st.tpin[2]) or 0.0)
                    -- v9: stolen = live y MINUS what we wrote last tick. ~0 = our writes ARE
                    -- the position (the maths/base is wrong instead); ~+big = a restorer
                    -- reverts the write between our ticks (the thief is engine-side).
                    local stolen = ""
                    if st.dbg_write_y then
                        stolen = string.format(" stolen=%+.2f", (tonumber(pos.y) or 0.0) - tonumber(st.dbg_write_y))
                    end
                    -- real ground under her RIGHT NOW vs the anchor's ground (slope truth)
                    local lg = ""
                    pcall(function()
                        local g2 = route3_ground_y_robust(go, tonumber(pos.y))
                        if g2 then lg = string.format(" lgnd=%+.1f", g2 - (tonumber(st.tpin[2]) or 0.0)) end
                    end)
                    yfx = string.format(" agl=%.1f%s%s", agl, stolen, lg)
                end
                st.tape.fsm_samples[#st.tape.fsm_samples + 1] = string.format("%.1fs %s%s tgt[hd=%.1f dy=%.1f] moved=%.1f fmv=%s fce=%s rm=%s%s%s",
                    now - (tonumber(st.phase_t0) or now),
                    tostring(read_griffin_fsm_node() or "?"), locked and " [locked]" or " [UNLOCKED]",
                    hd < 1.0e8 and hd or -1.0, dy, moved, fmv, fce, rm, yfx,
                    st.target and "" or " (no target)")
            end
        end
        -- ⭐ RACE INSURANCE (2026-08-07): DriftTurnL can self-exit and ride out the lockout's
        -- 0.35s tail BETWEEN our ticks -- if that release lands while we are still on step 3,
        -- the old code unwound the whole ride and the landing flare never fired (the pounce
        -- ended in the exit pump's generic flap recovery: the "flies again" tail). A released
        -- lock on step 3 IS the drift ending -- chain the flare, don't unwind.
        if (not locked) and st.phase == "pounceride" and (tonumber(st.pounce_step) or 0) == 3
            and not st.grounded_skid then   -- air path only; the grounded skid runs no lockout
            st.pounce_step = 4
            if C.route3_dogfight_pounce_end_at_skid ~= false then
                -- drift retired early: same face-the-foe beat, then the quiet grounding
                st.face_beat = true
                st.gale_until = now + 0.35
                S.route3_landing_quiet = true
            else
                pounce_fire_step("Ch253FlightTurnDashAttackAirToLandL",
                    math.max(0.5, tonumber(C.route3_dogfight_pounce_land_secs) or 1.6) + 1.2)
                return true
            end
        end
        -- ⛔ the RETURN leg (step 4 with an anchor) must survive the node retiring early:
        -- AirToLandL can end mid-flight-back, and a lock-release end would land her wherever
        -- she happens to be -- "nowhere near the goblin" (Aurora). She flies the leg out on
        -- the Fly-tree pose (accepted) and lands ON the kill via arrival/timer instead.
        local returning = (st.phase == "pounceride" and (tonumber(st.pounce_step) or 0) >= 4
            and st.tpin ~= nil)
        if ((not locked) and not st.grounded_skid and not returning) or now >= (tonumber(st.gale_until) or 0.0) then
            -- ⭐ a pounce that reached its flare ends GROUNDED. ⛔ Two timing worlds (2026-08-06,
            -- the broken loop camera): if the node ALREADY retired ("not locked"), the exit pump
            -- has ALREADY run -- a deferred flag would linger and ground the NEXT node instead
            -- (the loop-the-loop got landed mid-air, 131m camdiag chaos). Node gone = paint-safe
            -- = ground her RIGHT NOW; only a still-live node defers to the pump.
            if st.phase == "pounceride" and (tonumber(st.pounce_step) or 0) >= 4
                and S.airborne == true then   -- the grounded skid already landed at the strike
                if not locked then
                    local gyl = nil
                    pcall(function() gyl = route3_ground_y_robust(go, st.tpin and st.tpin[2]) end)
                    pcall(function() route3_finish_landing(ch, go, gyl or (st.tpin and st.tpin[2]), "pounce touchdown (immediate)") end)
                else
                    S.route3_pounce_ground_at_retire = (st.tpin and st.tpin[2]) or true
                end
            end
            -- force the lockout ceiling NOW so the exit pump walks her to neutral this frame
            -- instead of letting her hold the node's last pose (the midair freeze)
            S.route3_node_lock_at = now - math.max(1.0, tonumber(C.route3_node_lockout_max) or 3.0) - 1.0
            -- node retired (or timer): unwind with NO repaint -- the exit pump repaints flight
            -- at the retire, which is the correct beat. route3_dogfight_end stays banned here.
            unwind_quiet((not locked) and "lockout released (node gone)" or "ride timer")
            return false
        end
        S.route3_dogfight_status = string.format("%s d=%.1f",
            st.phase == "pounceride" and ("POUNCE! step " .. tostring(st.pounce_step)) or "GALE dive!", d3)
        return true

    elseif st.phase == "recover" then
        -- brief glide-out held ABOVE ground (no all-fours), then the pass is done -- press again to repeat
        local ry = route3_dogfight_clamp_altitude(go, tonumber(pos.y) or 0.0)
        local rpos = make_position(tonumber(pos.x) or 0.0, ry, tonumber(pos.z) or 0.0)
        S.route3_air_pos = rpos
        pcall(function() route3_apply_air_transform(ch, go, rpos, S.route3_air_rot or make_quat_yaw(tonumber(st.yaw) or 0.0)) end)
        if (now - (tonumber(st.phase_t0) or now)) >= math.max(0.1, tonumber(C.route3_dogfight_recover_secs) or 0.5) then
            route3_dogfight_end("pass done"); return false
        end
        S.route3_dogfight_status = "recover"
        return true
    end
    route3_dogfight_end("badphase")
    return false
end

function route3_dogfight_end(reason)
    S.route3_dogfight = nil
    S.route3_dogfight_cooldown_at = os.clock()
    S.audition_until_clock = 0.0
    -- go straight to the flap BEAT clip and pre-load it; the reseek tick snaps it to seg_start the instant it
    -- lands, so the takeoff intro (frames 0..seg_start = the all-fours getup) is never played out.
    pcall(function() route3_flap_clear_overlay() end)   -- double-flap hygiene
    S.route3_flap_phase = nil
    local fc = math.floor(tonumber(C.flap_takeoff_clip) or 5210)
    pcall(function() play_griffin_motion(fc, 0, true) end)
    S.route3_dogfight_reseek_clip = fc
    S.route3_dogfight_reseek_until = os.clock() + 1.2
    S.route3_dogfight_status = "dogfight=" .. tostring(reason or "done")
    S.route3_dogfight_diag = ""; S.route3_dogfight_diag_last = nil
    S.route3_dogfight_diag_until = os.clock() + 2.5
end

function route3_dogfight_reseek_tick()
    if os.clock() > (tonumber(S.route3_dogfight_reseek_until) or 0.0) then return end
    local fc = math.floor(tonumber(S.route3_dogfight_reseek_clip) or 0)
    if fc <= 0 then return end
    if route3_flap_layer_clip() == fc then
        local seg = tonumber(C.route3_dogfight_flap_sync) or 125.0   -- Aurora: resume at 125 to sync the beat (not seg_start 100)
        local frame = route3_flap_layer_frame()
        -- keep the playhead at/after the sync frame (skips the takeoff intro AND the seam) EVERY frame
        if frame == nil or (tonumber(frame) or 0) < seg then
            pcall(function() route3_flap_seek(seg) end)
        end
        S.route3_flap_phase = "beat"; S.route3_flap_seeked = true; S.route3_flap_last = os.clock()
    end
end

function route3_dogfight_diag_tick()
    -- ⚡ PERF (2026-08-10, Iris): this readout is WRITE-ONLY. S.route3_dogfight_diag is assigned
    -- here and at 16644 and read NOWHERE -- verified by grep across every .lua and .off in the
    -- tree. It was resolving the griffin motion component, reading two motion layers and
    -- formatting a six-value string EVERY frame, then discarding the string. Behaviour is
    -- unchanged by gating it: nothing downstream consumes the value.
    -- To bring the readout back for a screenshot: C.dogfight_diag = true
    if C.dogfight_diag ~= true then return end
    -- LIVE flap-state readout: read it (screenshot) DURING the all-fours to see what is off.
    local base = route3_flap_layer_clip()
    local frame = route3_flap_layer_frame()
    local ov = nil; pcall(function() ov = route3_flap_overlay_clip() end)
    local spd = nil; pcall(function() local m = get_griffin_motion_component(); if m then spd = m:call("get_PlaySpeed") end end)
    S.route3_dogfight_diag = string.format("base=%s@%s  overlay=%s  phase=%s  air=%s  spd=%s",
        tostring(base), tostring(frame and math.floor(tonumber(frame) or 0) or "?"), tostring(ov),
        tostring(S.route3_flap_phase), tostring(S.airborne), tostring(spd))
end


-- ⭐ TARGET MARKER (2026-08-05, Aurora: "a little marker on what enemy the griffin will home in
-- on before you press the attack button"). Re-runs the finder on a throttle while airborne and
-- paints a lock tag over the would-be foe. The SAME preview target is what the homing lightning
-- drops its ring on -- one lock, two weapons.
-- ⭐ AUTO-FACE (2026-08-07, Aurora: "have things like the peck/ground pound and the ground
-- wing gust auto face/target the locked on enemy"): snap her heading to the marker-locked
-- foe at a ground move's fire. One lock, every weapon.
function route3_face_locked_target()
    local foe = S.route3_dogfight_preview
    if not foe then return false end
    local dead = true
    pcall(function() dead = is_dead(foe) end)
    if dead then return false end
    local fgo = char_go(foe)
    local ch, go = reacquire_griffin()
    local gp = go and transform_pos(go)
    local fp = fgo and transform_pos(fgo)
    if not (gp and fp) then return false end
    local want = math.atan((tonumber(fp.x) or 0.0) - (tonumber(gp.x) or 0.0),
        (tonumber(fp.z) or 0.0) - (tonumber(gp.z) or 0.0))
    -- ⭐ NATURAL TURN (2026-08-07, Aurora: "can the griffin just naturally rotate in the
    -- direction of where the enemy is moving as opposed to suddenly facing them?"): slew
    -- toward the foe at a bodily turn rate instead of snapping. Called per tick, so the
    -- turn is continuous; a runner circling her gets tracked like a slow turret.
    local cur = yaw_from_transform(go) or S.heading_yaw or want
    local nowf = os.clock()
    local dtf = math.min(0.05, math.max(0.001, nowf - (tonumber(S.route3_face_last) or nowf)))
    S.route3_face_last = nowf
    local diff = (want - cur + math.pi) % (2.0 * math.pi) - math.pi
    local maxr = math.max(0.3, tonumber(C.route3_face_turn_rate) or 2.5) * dtf
    if diff > maxr then diff = maxr elseif diff < -maxr then diff = -maxr end
    local yaw = cur + diff
    S.heading_yaw = yaw
    local rot = make_quat_yaw(yaw)
    if ch then
        pcall(function() set_character_rotation_only(ch, rot) end)
    elseif go then
        pcall(function() set_object_rotation_only(go, rot) end)
    end
    return true
end

function route3_dogfight_marker_tick()
    if C.route3_dogfight_marker == false then S.route3_dogfight_preview = nil; S.route3_df_marker = "off"; return end
    -- ⭐ GROUNDED LOCK (2026-08-07, Aurora: "have the nearest enemy lock work when grounded"):
    -- the marker runs on the ground too now -- one lock feeds the pounce, the lightning AND
    -- the ground moves' auto-facing.
    if S.mounted ~= true or griffin_dogfight_active() then
        S.route3_dogfight_preview = nil
        S.route3_df_marker = "idle (not mounted / mid-pass)"
        return
    end
    local nowc = os.clock()
    if nowc >= (tonumber(S.route3_df_preview_at) or 0.0) then
        S.route3_df_preview_at = nowc + 0.7      -- the finder walks every scene character: throttle
        local _, go = reacquire_griffin()
        local foe = nil
        pcall(function() foe = go and griffin_find_aerial_foe(go) end)
        S.route3_dogfight_preview = foe
    end
    local foe = S.route3_dogfight_preview
    local fgo = foe and char_go(foe)
    local dead = true
    pcall(function() dead = is_dead(foe) end)
    if not fgo or dead then S.route3_dogfight_preview = nil; S.route3_df_marker = "no lock (nothing in range)"; return end
    local rp = transform_render_pos(fgo)
    if not rp then S.route3_df_marker = "lock but no position"; return end
    -- draw.world_to_screen wants render space (same space the camera lives in).
    -- ⛔ Vector3f, NOT make_vec3 (2026-08-05): make_vec3 builds a via.vec3 for the raycast rig,
    -- and world_to_screen rejected it -- which is why the marker always fell back to the fixed
    -- line above the HP bar even with the goblin dead-centre on screen.
    local sp = nil
    pcall(function()
        sp = draw.world_to_screen(Vector3f.new(tonumber(rp.x) or 0.0, (tonumber(rp.y) or 0.0) + 2.4, tonumber(rp.z) or 0.0))
    end)
    if not sp then
        -- off-screen or world_to_screen unavailable. The old fixed "LOCK: name" line above the
        -- prompt cluster is RETIRED (2026-08-06, Aurora: on-target marker only) -- status text
        -- in the panel still records the state for diagnosis.
        S.route3_df_marker = (draw and draw.world_to_screen) and ("lock: " .. tostring(go_name(fgo) or "?") .. " (off-screen)")
            or "world_to_screen MISSING in this REF build"
        return
    end
    S.route3_df_marker = "lock: " .. tostring(go_name(fgo) or "?")
    pcall(function() iris_hud_text("[ LOCK ]", (tonumber(sp.x) or 0.0) - 34.0, tonumber(sp.y) or 0.0, 0xFFE05548, 18) end)
end

function route3_dogfight_hotkey_tick()
    if C.route3_dogfight_enabled ~= true or S.mounted ~= true then
        S.route3_dogfight_btn_prev = false
        S.route3_dogfight_queued_until = nil
        return
    end
    local now = os.clock()
    local down = false
    local names = tostring(C.route3_dogfight_buttons or ""):gsub("%s+", "")
    if names ~= "" then pcall(function() down = raw_gamepad_button_down(C.route3_dogfight_buttons) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_dogfight_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down == true and S.route3_dogfight_btn_prev ~= true then
        if griffin_hit_reaction_busy and griffin_hit_reaction_busy() then
            -- Preserve the edge, but reacquire the target only when the reaction
            -- genuinely retires. A stale target captured before a flinch is worse
            -- than dropping the input.
            S.route3_dogfight_queued_until = now + 2.0
            S.route3_dogfight_status = "queued after hit reaction"
        else
            route3_dogfight_start("button")
        end
    end
    S.route3_dogfight_btn_prev = down == true
    if S.route3_dogfight_queued_until then
        if now >= tonumber(S.route3_dogfight_queued_until) then
            S.route3_dogfight_queued_until = nil
            S.route3_dogfight_status = "queued dogfight expired"
        elseif not (griffin_hit_reaction_busy and griffin_hit_reaction_busy())
            and route3_dogfight_can_start() then
            S.route3_dogfight_queued_until = nil
            route3_dogfight_start("after hit reaction")
        end
    end
end

-- ============================ GROUND MOVES (grounded-mounted attacks) ============================
-- Aurora's spec: WING GUST = 50:200 start -> 50:201 loop WHILE HELD -> 50:202 end (the motion
-- itself knocks enemies back); GROUND ATTACK 2 = alternate 50:0 (double talon stomp) / 50:10
-- (beak attack). Template = the dive bomb: play clips w/ audition parked + horizontal AoE damage.
function griffin_gust_active() return type(S.route3_gust) == "table" end
function griffin_gatk_active() return type(S.route3_gatk) == "table" end

-- ⭐ LIGHT impact reaction (2026-08-07, Aurora: the full blowback on a peck is "a massive
-- hit away" -- she wants a flinch, not a flight). Just the synthetic reaction packet at a
-- reduced reaction rate -- no AI blackout, no ragdoll, no scripted arc: the creature plays
-- its own stagger and stays on its feet.
function route3_light_impact_reaction(ench, ggo, gpos)
    local tgo = char_go(ench)
    local ep = tgo and transform_pos(tgo)
    if not (tgo and ep and gpos) then return false end
    local dx = (tonumber(ep.x) or 0.0) - (tonumber(gpos.x) or 0.0)
    local dz = (tonumber(ep.z) or 0.0) - (tonumber(gpos.z) or 0.0)
    local l = math.sqrt(dx * dx + dz * dz); if l < 0.01 then dx, dz, l = 0.0, 1.0, 1.0 end
    dx, dz = dx / l, dz / l
    local hs = character_hate_system(ench, tgo)
    local di = nil
    pcall(function() di = sdk.create_instance("app.HitController.DamageInfo") end)
    if not di then pcall(function() di = sdk.create_instance("app.HitController.DamageInfo", true) end) end
    if not (di and hs) then return false end
    pcall(function() di:set_field("BlowDamage", 1.0) end)
    pcall(function() di:set_field("IsBlowAttack", true) end)
    pcall(function() di:set_field("BlownReactionRate",
        math.max(0.05, math.min(1.0, tonumber(C.route3_gatk_blow_rate) or 0.35))) end)
    pcall(function() di:set_field("AttackVec", make_vec3(dx, 0.0, dz)) end)
    pcall(function() di:set_field("<DamageGameObject>k__BackingField", tgo) end)
    pcall(function() if ggo then
        di:set_field("<AttackGameObject>k__BackingField", ggo)
        di:set_field("<AttackOwnerObject>k__BackingField", ggo)
    end end)
    pcall(function() hs:call("onDamageReaction(app.HitController.DamageInfo)", di) end)
    pcall(function() hs:call("onUnbalance(via.vec3, via.GameObject, via.GameObject)",
        make_vec3(tonumber(ep.x) or 0.0, tonumber(ep.y) or 0.0, tonumber(ep.z) or 0.0), ggo or tgo, tgo) end)
    return true
end

-- Keep the gust's reaction sweep on exactly the same targets as its damage sweep. The old
-- version flung every non-party app.Character even though the damage path correctly filtered
-- civilians and pawns; besides looking artificial, that could create grudges without a hit.
function route3_ground_target_hostile(ench)
    if not ench or mounts[ench] == true or griffin_is_self(ench)
        or is_player_or_party(ench) or is_dead(ench) then return false end
    local ego = char_go(ench)
    local nm = tostring(go_name(ego) or "")
    if nm:find("ch299", 1, true) then
        if C.route3_lock_critters == false then return false end
        local ishorse = false
        pcall(function()
            local api = rawget(_G, "__iris_wild_horses_api")
            ishorse = api and api.is_horse and api.is_horse(ego) == true
        end)
        return not ishorse
    end
    if nm:sub(1, 3) ~= "ch2" then return false end
    -- EnemyManager stores app.ChXXXXXX behaviour components, whereas the scene sweep gives us
    -- app.Character. griffin_is_registered_enemy normalises that mismatch. The stable hostile
    -- group hash is a second source for enemies temporarily absent from the manager (reaction,
    -- spawn and death transitions).
    if griffin_is_registered_enemy(ench) then return true end
    if griffin_group_hash_value(route3_ally_group_ctx(ench)) == 1895570358 then return true end
    local hostile = false
    pcall(function() hostile = ench:get_field("<EnemyCtrl>k__BackingField") ~= nil end)
    return hostile
end

function route3_character_band(ench)
    -- GameObject names normally carry ch25xxxx, but spawned/managed variants do not always begin
    -- with it. Fall back to the concrete app.ChXXXXXX behaviour component/type so the large-body
    -- safety gate cannot be bypassed by a renamed Ogre.
    if not ench then return nil end
    local function from_text(v)
        local s = tostring(v or "")
        return s:match("[cC][hH](%d%d)%d%d%d%d") or s:match("[cC][hH](%d%d)")
    end
    local band = from_text(go_name(char_go(ench)))
    if band then return band end
    pcall(function() band = from_text(ench:get_type_definition():get_full_name()) end)
    if band then return band end
    local go = char_go(ench)
    pcall(function()
        for _, c in ipairs(system_array_to_table(go and go:call("get_Components")) or {}) do
            local b = from_text(c:get_type_definition():get_full_name())
            if b then band = b; return end
        end
    end)
    return band
end

-- Bosses absorb the gust hit through their native damage/reaction rules, never through our
-- forced ragdoll + transform arc. Prefer runtime flags and retain the same 24/25/26
-- large-monster bands already used by the grab safety gate as a fallback.
function route3_gust_target_is_boss(ench)
    if not ench then return false end
    for _, method in ipairs({ "get_IsBoss", "get_IsBossEnemy", "get_IsLargeEnemy" }) do
        local yes = false
        pcall(function() yes = ench:call(method) == true end)
        if yes then return true end
    end
    local band = route3_character_band(ench)
    if band then
        for raw in tostring(C.route3_gust_boss_block_bands or "24,25,26"):gmatch("[^,%s]+") do
            if raw == band then return true end
        end
    end
    return false
end

function route3_gust_blow_start(ench, ggo, gpos, opts)
    -- opts (2026-08-08): per-caller strength overrides -- {dist, up, secs, ragdoll} -- so the
    -- gatk can fire a SMALL stumble through this same proven-VISIBLE machinery (the light
    -- packet-only reaction showed nothing: "the synthetic packet alone never visibly tumbles").
    -- nil opts = the gust finale's config values, behavior unchanged.
    -- WIND BLOWBACK, no shell/VFX (Aurora: the gust anim IS the visual; shells all look like
    -- spells/earthquakes). Two proven pieces: (1) the grab-dangle's synthetic KNOCKDOWN packet
    -- (route3_grab_apply_fall -- HateSystem onReceiveForce/onDamageReaction/onUnbalance makes the
    -- creature play ITS OWN tumble; field-proven on every grab), aimed OUTWARD instead of down;
    -- (2) a short scripted ground-slide away from her (the legacy throw arc's transform drive).
    -- Result: they tumble + skid back, then their AI stands them up. Reads as wind.
    local tgo = char_go(ench)
    local ep = tgo and transform_pos(tgo)
    if not (tgo and ep and gpos) then return false end
    local dx = (tonumber(ep.x) or 0.0) - (tonumber(gpos.x) or 0.0)
    local dz = (tonumber(ep.z) or 0.0) - (tonumber(gpos.z) or 0.0)
    local l = math.sqrt(dx * dx + dz * dz); if l < 0.01 then dx, dz, l = 0.0, 1.0, 1.0 end
    dx, dz = dx / l, dz / l
    -- 1) the tumble: same packet as the grab dangle, outward vector, tiny damage
    local hs = character_hate_system(ench, tgo)
    local di = nil
    pcall(function() di = sdk.create_instance("app.HitController.DamageInfo") end)
    if not di then pcall(function() di = sdk.create_instance("app.HitController.DamageInfo", true) end) end
    if di and hs then
        pcall(function() di:set_field("Damage", 1.0) end)
        pcall(function() di:set_field("FixedDamage", 1.0) end)
        pcall(function() di:set_field("BlowDamage", 50.0) end)  -- strong poise break; HP damage stays tiny
        pcall(function() di:set_field("IsBlowAttack", true) end)
        pcall(function() di:set_field("BlownReactionRate", 1.0) end)
        pcall(function() di:set_field("AttackVec", make_vec3(dx, 0.0, dz)) end)
        pcall(function() di:set_field("<DamageGameObject>k__BackingField", tgo) end)
        pcall(function() if ggo then di:set_field("<AttackGameObject>k__BackingField", ggo); di:set_field("<AttackOwnerObject>k__BackingField", ggo) end end)
        pcall(function() hs:call("set_ForceDamageInfo(app.HitController.DamageInfo)", di) end)
        pcall(function() hs:call("onReceiveForce(app.HitController.DamageInfo)", di) end)
        pcall(function() hs:call("onDamageReaction(app.HitController.DamageInfo)", di) end)
        pcall(function()
            local p = make_vec3(tonumber(ep.x) or 0.0, tonumber(ep.y) or 0.0, tonumber(ep.z) or 0.0)
            hs:call("onUnbalance(via.vec3, via.GameObject, via.GameObject)", p, ggo or tgo, tgo)
        end)
    end
    -- 2) brief AI BLACKOUT (grab-dangle pattern): with its AI live the goblin's locomotion keeps
    -- it standing upright and the tumble never shows = "iceskating". Disabled for the flight,
    -- restored the moment it lands (route3_gust_blown_tick).
    local disabled = {}
    for _, tn in ipairs({ "app.AIDecisionMaker", "app.NavigationAI" }) do
        local c = get_component(tgo, tn)
        if c then pcall(function() c:call("set_Enabled", false); disabled[#disabled + 1] = c end) end
    end
    -- GROUND-GLUE KILL (the grab's hard-won lesson): GroundFixer + CharacterController re-drive
    -- the root to terrain height every frame -- with them live the fling's vertical arc gets
    -- flattened into "just pushed back". Off for the flight, restored on landing.
    pcall(function()
        local comps = tgo:call("get_Components")
        for _, c in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                local tn2 = tostring(c:get_type_definition():get_full_name())
                if tn2:find("GroundFixer", 1, true) or tn2:find("CharacterController", 1, true) then
                    c:call("set_Enabled", false)
                    disabled[#disabled + 1] = c
                end
            end)
        end
    end)
    -- Do not paint one species' bank-10 throw clip over every victim. On animals and several
    -- monsters it is absent or incompatible; on humanoids it can overwrite the native damage fall.
    if C.route3_gust_force_throw_clip == true then
        pcall(function()
            route3_play_motion_on(ench, tonumber(C.route3_grab_thrown_clip) or 500,
                tonumber(C.route3_grab_thrown_bank) or 10)
        end)
    end
    -- 3b) RAGDOLL: force-enable + the native throw's recorded in-flight state (dmg_throw_action,
    -- then dmg_throw_pause ~0.4s later -- taped off a real Arisen throw). The body goes limp
    -- while our arc drives the root -- the exact combo the talon-carry dangle proved works.
    local ragdolled = false
    local want_ragdoll = C.route3_gust_blow_ragdoll ~= false
    if opts and opts.ragdoll ~= nil then want_ragdoll = opts.ragdoll == true end
    if want_ragdoll then
        pcall(function() ench:call("set_IsForceEnableRagdoll", true); ragdolled = true end)
        pcall(function()
            local rt = sdk.find_type_definition("via.dynamics.Ragdoll"):get_runtime_type()
            local rd = tgo:call("getComponent(System.Type)", rt)
            if rd then rd:call("set_RagdollStateName(System.String)", "dmg_throw_action") end
        end)
    end
    -- 4) the FLING: ballistic arc away from her (the legacy throw's integrator) -- up + outward,
    -- gravity pulls them down, they crash and get back up
    local dur = math.max(0.3, (opts and tonumber(opts.secs)) or tonumber(C.route3_gust_blow_secs) or 0.6)
    local dist = math.max(0.0, (opts and tonumber(opts.dist)) or tonumber(C.route3_gust_blow_dist) or 4.0)
    S.route3_gust_blown = S.route3_gust_blown or {}
    S.route3_gust_blown[#S.route3_gust_blown + 1] = {
        ch = ench, go = tgo, t0 = os.clock(), last = os.clock(),
        vx = dx * dist / dur, vz = dz * dist / dur,
        vy = math.max(0.0, (opts and tonumber(opts.up)) or tonumber(C.route3_gust_blow_up) or 4.0),
        disabled = disabled,
        ragdolled = ragdolled,
        rag_pause_at = ragdolled and (os.clock() + 0.4) or nil,   -- recorded action->pause transition
    }
    S.route3_gust_blow_status = string.format("blow: %s flung %.1fm", tostring(go_name(tgo) or "?"), dist)
    return true
end

function route3_gust_blow_restore(b)
    -- landing: release the ragdoll force-flag and give the AI back so it scrambles up
    if b and b.ragdolled then
        pcall(function() b.ch:call("set_IsForceEnableRagdoll", false) end)
    end
    for _, c in ipairs(b and b.disabled or {}) do pcall(function() c:call("set_Enabled", true) end) end
end

function route3_play_motion_on(ch, clip, bank)
    -- paint a clip on an ARBITRARY character's base layer (play_griffin_motion's core, any body)
    if not (ch and clip and tonumber(clip) and tonumber(clip) >= 0) then return false end
    local ok = false
    pcall(function()
        local motion = ch:call("get_Motion")
        local layer = motion and motion:call("getLayer", 0)
        if not layer then return end
        motion:call("set_PlaySpeed", 1.0)
        motion:call("set_PlayState", 0)
        layer:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
            math.floor(tonumber(bank) or 0), math.floor(tonumber(clip)), 0.0, 8.0, 1, 1)
        ok = true
    end)
    return ok
end

function route3_gust_blown_tick()
    -- drive the registered flings: ballistic arc (gravity), land on the ground cast, then
    -- restore the AI. Bails early on death (the corpse ragdolls natively; keep writing and
    -- it fights the ragdoll) and on a hard 2.5s timeout (never orphan a think-stopped goblin).
    local list = S.route3_gust_blown
    if not (list and #list > 0) then return end
    local now = os.clock()
    for i = #list, 1, -1 do
        local b = list[i]
        local done = true
        pcall(function()
            if (now - (tonumber(b.t0) or now)) > 2.5 then return end          -- timeout -> restore
            if not b.go or is_dead(b.ch) then return end                       -- death -> restore
            local cpos = transform_pos(b.go)
            if not cpos then return end
            local dt = math.max(0.001, math.min(0.05, now - (tonumber(b.last) or now)))
            b.last = now
            -- recorded ragdoll transition: dmg_throw_action -> dmg_throw_pause ~0.4s in
            if b.rag_pause_at and now >= b.rag_pause_at then
                b.rag_pause_at = nil
                pcall(function()
                    local rt = sdk.find_type_definition("via.dynamics.Ragdoll"):get_runtime_type()
                    local rd = b.go:call("getComponent(System.Type)", rt)
                    if rd then rd:call("set_RagdollStateName(System.String)", "dmg_throw_pause") end
                end)
            end
            local nx, ny, nz
            if b.landed_at then
                -- Keep the body visibly DOWN. The old path restored ragdoll and AI on the exact
                -- touchdown frame, allowing an instant upright snap that read as no knockdown.
                nx = tonumber(cpos.x) or 0.0
                ny = (tonumber(b.ground_y) or tonumber(cpos.y) or 0.0) + 0.2
                nz = tonumber(cpos.z) or 0.0
                done = (now - tonumber(b.landed_at)) >= math.max(0.1,
                    tonumber(C.route3_gust_blow_down_secs) or 0.85)
            else
                b.vy = (tonumber(b.vy) or 0.0) - 24.0 * dt                     -- gravity
                nx = (tonumber(cpos.x) or 0.0) + (tonumber(b.vx) or 0.0) * dt
                ny = (tonumber(cpos.y) or 0.0) + b.vy * dt
                nz = (tonumber(cpos.z) or 0.0) + (tonumber(b.vz) or 0.0) * dt
            end
            -- CAST CONTRACT: x/z RENDER space, y UNIVERSAL (this was the "they go underground"
            -- bug -- universal x/z probed the wrong column, the ray never found ground)
            local ground_y = nil
            local rp = transform_render_pos(b.go) or cpos
            local gh = route3_cast_ground_below(tonumber(rp.x) or nx, (tonumber(cpos.y) or 0.0) + 1.0,
                tonumber(rp.z) or nz, 3.0, 60.0)
            if gh and tonumber(gh.y) then ground_y = tonumber(gh.y) end
            if not b.landed_at and ground_y and ny <= ground_y + 0.2 and b.vy < 0.0 then
                ny = ground_y + 0.2                                            -- touchdown
                b.ground_y = ground_y
                b.landed_at = now
                done = false                                                   -- begin visible down-hold
            elseif not b.landed_at then
                done = false                                                   -- still flying
            end
            local np = make_position(nx, ny, nz)
            pcall(function() set_transform(b.go, np, nil) end)
            pcall(function() set_character_transform(b.ch, np, nil) end)
        end)
        if done then
            route3_gust_blow_restore(b)
            table.remove(list, i)
        end
    end
end

function route3_gust_finale_blow(radius)
    -- blow back EVERYONE in the radius (same scene-sweep as the damage pulse; blowback runs
    -- BEFORE the damage so nobody's a corpse yet). radius defaults to the ground finale's;
    -- the aerial gust passes its own. Horizontal-only distance = from the air it hits the
    -- ground foes under her.
    local _, go = reacquire_griffin()
    local gpos = go and transform_pos(go)
    if not gpos then return end
    local r2 = math.max(1.0, tonumber(radius) or tonumber(C.route3_gust_end_radius) or 9.0); r2 = r2 * r2
    local n = 0
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ench in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                if not route3_ground_target_hostile(ench) then return end
                local epos = transform_pos(char_go(ench))
                if not epos then return end
                local dx = (tonumber(epos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
                local dz = (tonumber(epos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
                if (dx * dx + dz * dz) > r2 then return end
                -- The damage pulse below still lands, but large/boss bodies keep native poise.
                if route3_gust_target_is_boss(ench) then return end
                if route3_gust_blow_start(ench, go, gpos) then n = n + 1 end
            end)
        end
    end)
    if n > 0 then S.route3_gust_blow_status = string.format("blowback: %d target(s) tumbled+skid", n) end
end

function route3_ground_aoe_damage(radius, dmg, hitset, centre, freshset)
    local hits = 0
    -- One horizontal AoE pulse (same scene-sweep as the dive bomb slam).
    --
    -- Centred on the griffin by default, which is right for the ground gust and the slam because
    -- those land where she is. Pass `centre` for an attack that lands somewhere else -- the
    -- thunder ring strikes a circle of bolts around her, so damaging her own position would put
    -- the hit nowhere near the lightning the player can see.
    local gpos = centre
    if not gpos then
        local _, go = reacquire_griffin()
        gpos = go and transform_pos(go)
    end
    if not gpos then return end
    local r2 = math.max(1.0, tonumber(radius) or 5.0); r2 = r2 * r2
    dmg = math.max(1.0, tonumber(dmg) or 100.0)
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ench in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                if not route3_ground_target_hostile(ench) then return end
                if hitset and hitset[ench] == true then return end
                local epos = transform_pos(char_go(ench))
                if not epos then return end
                local dx = (tonumber(epos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
                local dz = (tonumber(epos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
                if (dx * dx + dz * dz) > r2 then return end
                if griffin_apply_attack_damage(ench, dmg) then
                    if hitset then hitset[ench] = true end
                    if freshset then freshset[ench] = true end
                    hits = hits + 1
                end
            end)
        end
    end)
    return hits
end

function route3_ground_move_blocked()
    -- grounded-mounted only, and never during another special move
    if S.mounted ~= true then return true end
    if S.airborne == true then return true end
    if griffin_grab_active() or griffin_divebomb_active() then return true end
    if griffin_gust_active() or griffin_gatk_active() then return true end
    return false
end

function route3_gust_end(reason)
    S.route3_gust = nil
    S.base_owner = nil   -- release the base layer BEFORE painting the successor
    S.audition_until_clock = 0.0
    -- NEVER paint restore clips on a body we no longer own: on dismount the native FSM is
    -- waking from puppet state and a changeMotion there = the AV (the oldest law)
    if S.mounted == true then route3_flap_after_action() end
    S.route3_gust_status = "gust=" .. tostring(reason or "done")
end

-- ===== PREDATION PROBES (timeboxed project): native catch, cheap tests first =====
-- Mounted/tamed Iris reports the three selector permissions false even with the
-- exact wild target graph present.  The GATE-OPEN probe overrides only these
-- boolean answers, only for her Ch253 component, and only during its lease.  It
-- does not request an action or fabricate a catch transaction.
function griffin_install_predation_bool_gate_hook(method_name, call_key, count_key)
    pcall(function()
        local td = sdk.find_type_definition("app.Ch253000")
        local m = td and td:get_method(method_name)
        if not m then return end
        sdk.hook(m,
            function(args)
                local force = false
                if S.route3_predation_gate_override_active == true
                    and S.route3_predation_mode == "native"
                    and griffin_predation_window_active() then
                    local this = nil
                    pcall(function() this = sdk.to_managed_object(args[2]) end)
                    local _, go = reacquire_griffin()
                    local own = go and get_component(go, "app.Ch253000")
                    force = this and own and same_obj(this, own) or false
                end
                S[call_key] = force
            end,
            function(retval)
                local force = S[call_key] == true
                S[call_key] = false
                if force then
                    S[count_key] = (tonumber(S[count_key]) or 0) + 1
                    return sdk.to_ptr(1)
                end
                return retval
            end)
    end)
end

if not GRIFFIN_IRIS_PREDATION_GATE_HOOKS_INSTALLED then
    griffin_install_predation_bool_gate_hook("checkEnableAttack", "route3_predation_gate_attack_call", "route3_predation_gate_attack_forced")
    griffin_install_predation_bool_gate_hook("IsEnablePredation", "route3_predation_gate_enable_call", "route3_predation_gate_enable_forced")
    griffin_install_predation_bool_gate_hook("checkPredationAngle(via.GameObject)", "route3_predation_gate_angle_call", "route3_predation_gate_angle_forced")
    GRIFFIN_IRIS_PREDATION_GATE_HOOKS_INSTALLED = true
end

-- In the wild catch, Ch253.getAttackTarget returns TargetController's ox-backed
-- AITargetGeneralPoint. Mounted Iris instead returns the Arisen or a positional
-- offset. Search the whole inheritance chain: get_method(name) on Ch253 found a
-- metadata entry which was never the implementation dispatched by the game.
function griffin_install_attack_target_promoters()
    local td = sdk.find_type_definition("app.Ch253000")
    local installed, attempted, calls = 0, 0, {}
    while td do
        local declaring = tostring(td:get_full_name() or "?")
        for _, m in ipairs(td:get_methods() or {}) do
            if tostring(m:get_name() or "") == "getAttackTarget" then
                attempted = attempted + 1
                local hook_id = declaring .. "#" .. tostring(attempted)
                local ok = pcall(function()
                    sdk.hook(m,
                        function(args)
                            local promote = false
                            if S.route3_predation_promote_attack_target_active == true
                                and S.route3_predation_mode == "native"
                                and griffin_predation_window_active() then
                                local this = nil
                                pcall(function() this = sdk.to_managed_object(args[2]) end)
                                local _, go = reacquire_griffin()
                                local own = go and get_component(go, "app.Ch253000")
                                promote = this and own and same_obj(this, own) or false
                            end
                            calls[hook_id] = promote
                        end,
                        function(retval)
                            local promote = calls[hook_id] == true
                            calls[hook_id] = false
                            if not promote then return retval end
                            local replacement = nil
                            pcall(function()
                                local _, go = reacquire_griffin()
                                local own = go and get_component(go, "app.Ch253000")
                                local tc = own and own:call("get_TargetController")
                                replacement = tc and tc:call("get_TargetAIActionTarget")
                            end)
                            if replacement then
                                S.route3_predation_attack_target_promoted = (tonumber(S.route3_predation_attack_target_promoted) or 0) + 1
                                S.route3_predation_promote_last_hook = hook_id
                                return sdk.to_ptr(replacement)
                            end
                            return retval
                        end)
                end)
                if ok then installed = installed + 1 end
            end
        end
        td = td:get_parent_type()
    end
    S.route3_predation_promote_hook_status = string.format("attack-target hooks installed %d/%d", installed, attempted)
end

if not GRIFFIN_IRIS_PREDATION_PROMOTE_HOOKS_INSTALLED then
    pcall(function() griffin_install_attack_target_promoters() end)
    GRIFFIN_IRIS_PREDATION_PROMOTE_HOOKS_INSTALLED = true
end

-- CLAIM ASSIST (Lyra's lead, the endgame): onCatchCheckCharacter is the claim check inside
-- the catch's collision window -- the ONLY stage still failing (dive/hit/contact all work).
-- During our probe window: count its firings (does the window even open on a forced node?)
-- and FORCE-APPROVE the claim. Window-gated: zero effect outside our catch probes.
if not GRIFFIN_IRIS_PREDATION_CLAIM_HOOK_INSTALLED then pcall(function()
    local td = sdk.find_type_definition("app.Ch253000")
    local m = td and (td:get_method("onCatchCheckCharacter(app.HitController.DamageInfo, app.Character)")
        or td:get_method("onCatchCheckCharacter"))
    if m then
        sdk.hook(m,
            function(args)
                if (tonumber(S.route3_predation_probe_until) or 0.0) <= os.clock() then return end
                S.route3_predation_claim_seen = (tonumber(S.route3_predation_claim_seen) or 0) + 1
            end,
            function(retval)
                if (tonumber(S.route3_predation_probe_until) or 0.0) <= os.clock() then return retval end
                pcall(function() S.route3_predation_claim_native = sdk.to_int64(retval) ~= 0 end)
                -- The clean native replay must preserve the genuine claim result.
                -- Legacy forced-node probes keep their existing configurable assist;
                -- an explicitly assisted native replay opts in through the scoped flag.
                local force_claim = C.route3_predation_force_claim ~= false
                if S.route3_predation_mode == "native" then
                    force_claim = S.route3_predation_force_claim_active == true
                end
                if force_claim then
                    S.route3_predation_claim_forced = (tonumber(S.route3_predation_claim_forced) or 0) + 1
                    return sdk.to_ptr(1)   -- YES, you caught it
                end
                return retval
            end)
    end
end); GRIFFIN_IRIS_PREDATION_CLAIM_HOOK_INSTALLED = true end

-- startCatch spy: is the native ATTACH ever even attempted during our window?
if not GRIFFIN_IRIS_PREDATION_STARTCATCH_HOOK_INSTALLED then pcall(function()
    local td = sdk.find_type_definition("app.CatchController")
    local m = td and td:get_method("startCatch(app.Character, app.CatchController.Setting, app.CatchInterpolator)")
    if m then
        sdk.hook(m, function(args)
            local now = os.clock()
            local probe_active = (tonumber(S.route3_predation_probe_until) or 0.0) > now
            local wild_active = (tonumber(S.route3_wild_catch_capture_until) or 0.0) > now
            if probe_active or wild_active then
                if probe_active then
                    S.route3_predation_startcatch_seen = (tonumber(S.route3_predation_startcatch_seen) or 0) + 1
                end
                local cc, prey, setting, interp = nil, nil, nil, nil
                pcall(function() cc = sdk.to_managed_object(args[2]) end)
                pcall(function() prey = sdk.to_managed_object(args[3]) end)
                pcall(function() setting = sdk.to_managed_object(args[4]) end)
                pcall(function() interp = sdk.to_managed_object(args[5]) end)
                if setting then pcall(function() setting = setting:add_ref() end) end
                local ridden_cc = nil
                pcall(function() ridden_cc = S.griffin and S.griffin:call("get_CatchController") end)
                local catcher = griffin_predation_find_catch_owner(cc)
                S.route3_predation_capture_pending = {
                    cc = cc, catcher = catcher, prey = prey, setting = setting, interp = interp,
                    same_ridden = cc and ridden_cc and same_obj(cc, ridden_cc) or false,
                }
                if setting and ((cc and ridden_cc and same_obj(cc, ridden_cc)) or wild_active) then
                    S.route3_predation_captured_setting = setting
                end
                if wild_active then
                    S.route3_wild_catch_capture_seen = (tonumber(S.route3_wild_catch_capture_seen) or 0) + 1
                    S.route3_wild_catch_capture_until = 0.0
                    local setting_type = setting and "present" or "nil"
                    pcall(function() setting_type = tostring(setting:get_type_definition():get_full_name()) end)
                    S.route3_wild_catch_capture_status = string.format(
                        "CAPTURED catcher=%s prey=%s setting=%s",
                        tostring(catcher and griffin_display_name(catcher) or "unknown"),
                        tostring(prey and griffin_display_name(prey) or "unknown"),
                        setting_type)
                end
            end
        end, function(retval) return retval end)
    end
end); GRIFFIN_IRIS_PREDATION_STARTCATCH_HOOK_INSTALLED = true end

-- ===== CAUGHT-MOTION TAPE (Fable design 2026-07-11) ===== read-only spy: capture
-- what the GAME calls to animate a carried victim while keeping it HELD. Inert until
-- armed (S.route3_caughtmotion_tape_until). Arm from the panel, then PLAYER-carry a
-- goblin. Tape -> data/<MOD>_caughtmotion_tape.json. NEW hook = FULL GAME RESTART.
if not GRIFFIN_IRIS_CAUGHTMOTION_TAPE_HOOK_INSTALLED then pcall(function()
    local function cm_tape(ev, detail)
        if (tonumber(S.route3_caughtmotion_tape_until) or 0.0) <= os.clock() then return end
        S.route3_caughtmotion_tape = S.route3_caughtmotion_tape or {}
        local t = S.route3_caughtmotion_tape
        t[#t + 1] = string.format("%.2f %s %s", os.clock(), ev, tostring(detail or ""))
        while #t > 400 do table.remove(t, 1) end
        pcall(function() json.dump_file(MOD .. "_caughtmotion_tape.json", t) end)
    end
    _G.griffin_cm_tape = cm_tape
    local function armed() return (tonumber(S.route3_caughtmotion_tape_until) or 0.0) > os.clock() end
    local function owner_of(this)
        local n = "?"; pcall(function() n = this:call("get_GameObject"):call("get_Name") end); return tostring(n)
    end
    local function hook_cm(tn, sig, fmt)
        local td = sdk.find_type_definition(tn)
        local m = td and td:get_method(sig)
        if not m then return end
        sdk.hook(m, function(args)
            pcall(function()
                if not armed() then return end
                local this = sdk.to_managed_object(args[2])
                local o = owner_of(this)
                local d = o
                if fmt == "full" then
                    d = string.format("%s bank=%s id=%s interpF=%.1f startF=%.1f loop=%s", o,
                        tostring(sdk.to_int64(args[3])), tostring(sdk.to_int64(args[4])),
                        sdk.to_float(args[5]), sdk.to_float(args[6]), tostring(sdk.to_int64(args[7]) ~= 0))
                elseif fmt == "bankid" then
                    d = string.format("%s bank=%s id=%s", o, tostring(sdk.to_int64(args[3])), tostring(sdk.to_int64(args[4])))
                elseif fmt == "go_bankid" then
                    local gn = "?"; pcall(function() gn = sdk.to_managed_object(args[3]):call("get_Name") end)
                    d = string.format("%s from=%s bank=%s id=%s", o, gn, tostring(sdk.to_int64(args[4])), tostring(sdk.to_int64(args[5])))
                end
                cm_tape(tn:gsub("app%.", "") .. "." .. sig:gsub("%(.*", ""), d)
            end)
            return sdk.PreHookResult.CALL_ORIGINAL
        end, function(retval) return retval end)
    end
    hook_cm("app.CatchController", "setCaughtMotion(System.UInt32, System.UInt32, System.Single, System.Single, System.Boolean, via.motion.InterpolationMode, via.motion.InterpolationCurve, System.Boolean)", "full")
    hook_cm("app.CatchController", "reserveCaughtMotionOnMotionEnd(System.UInt32, System.UInt32, System.Single, System.Single, System.Boolean, via.motion.InterpolationMode, via.motion.InterpolationCurve)", "full")
    hook_cm("app.CatchController", "endInterpolation()", nil)
    hook_cm("app.CaughtController", "endInterpolation()", nil)
    hook_cm("app.CaughtController", "reserveMotion(via.GameObject, System.UInt32, System.UInt32, System.Single, System.Single, System.Boolean, via.motion.InterpolationMode, via.motion.InterpolationCurve)", "go_bankid")
    hook_cm("app.CaughtController", "applyReservedMotion()", nil)
    hook_cm("app.CaughtController", "useStruggleMotion()", nil)
end); GRIFFIN_IRIS_CAUGHTMOTION_TAPE_HOOK_INSTALLED = true end

