-- The captured wild Setting creates a genuine native constraint on Iris, but
-- its start action is a one-shot.  A wild griffin's FSM replaces that action
-- with the carry branch; mounted Iris has no valid native transition and the
-- one-shot's normal end/abort callbacks dismantle both controllers roughly one
-- second later.  Retain ONLY our successfully handed-off replay until the
-- explicit RELEASE button opts out.  This does not fabricate or pin the victim:
-- startCatch/CaughtController still create and update the native constraint.
function griffin_install_native_carry_retention_hook(type_name, method_name, side)
    local td = sdk.find_type_definition(type_name)
    local m = td and td:get_method(method_name)
    if not m then return false end
    sdk.hook(m, function(args)
        if S.route3_predation_carry_retention_active ~= true
            or S.route3_predation_replay_stage == "released"
            or S.mounted ~= true then
            return sdk.PreHookResult.CALL_ORIGINAL
        end
        local this = nil
        pcall(function() this = sdk.to_managed_object(args[2]) end)
        local expected = nil
        if side == "catcher" then
            pcall(function()
                local ch = reacquire_griffin()
                expected = ch and ch:call("get_CatchController")
            end)
        else
            pcall(function()
                expected = S.companion_target and S.companion_target:call("get_CaughtController")
            end)
        end
        if not (this and expected and same_obj(this, expected)) then
            return sdk.PreHookResult.CALL_ORIGINAL
        end
        S.route3_predation_retained_ends = (tonumber(S.route3_predation_retained_ends) or 0) + 1
        S.route3_predation_last_retained_end = type_name .. "." .. method_name
        S.route3_predation_status = "native carry retained: blocked " .. S.route3_predation_last_retained_end
        if (tonumber(S.route3_predation_retained_ends) or 0) <= 12 then
            log.info("[GriffinRideProbe] native carry retained; blocked " .. S.route3_predation_last_retained_end)
        end
        return sdk.PreHookResult.SKIP_ORIGINAL
    end, function(retval) return retval end)
    return true
end

if not GRIFFIN_IRIS_NATIVE_CARRY_RETENTION_HOOKS_INSTALLED then pcall(function()
    -- Catcher-side terminal paths observed/available in the dumped API.
    griffin_install_native_carry_retention_hook("app.CatchController", "endFromFsm(via.behaviortree.ActionArg)", "catcher")
    griffin_install_native_carry_retention_hook("app.CatchController", "abort(System.Boolean)", "catcher")
    griffin_install_native_carry_retention_hook("app.CatchController", "onFinish(System.Boolean)", "catcher")
    -- Victim-side terminal notifications are guarded as well: depending on
    -- update order the victim can be the first half to decide the catch ended.
    griffin_install_native_carry_retention_hook("app.CaughtController", "abort(System.Boolean)", "caught")
    griffin_install_native_carry_retention_hook("app.CaughtController", "abortDirect()", "caught")
    griffin_install_native_carry_retention_hook("app.CaughtController", "notifyAbort()", "caught")
    griffin_install_native_carry_retention_hook("app.CaughtController", "notifyEnd()", "caught")
    griffin_install_native_carry_retention_hook("app.CaughtController", "notifyEscape()", "caught")
    griffin_install_native_carry_retention_hook("app.CaughtController", "onFinish()", "caught")
end); GRIFFIN_IRIS_NATIVE_CARRY_RETENTION_HOOKS_INSTALLED = true end

function griffin_predation_lock_wild_target()
    local ch, go = reacquire_griffin()
    local prey = S.companion_target
    local pgo = prey and char_go(prey)
    local ch253 = go and get_component(go, "app.Ch253000")
    if not (ch and go and pgo and ch253) then return false end
    local tc = nil
    pcall(function() tc = ch253:call("get_TargetController") end)
    if not tc then return false end
    local target_type = math.floor(tonumber(C.route3_predation_target_type) or 35)
    local ep = transform_render_pos(pgo) or transform_pos(pgo)
    if not ep then return false end
    local tv = make_vec3(tonumber(ep.x) or 0.0, tonumber(ep.y) or 0.0, tonumber(ep.z) or 0.0)
    pcall(function() ch253:call("set_PredationTarget(via.GameObject)", pgo) end)
    pcall(function() tc:call("setTypeTarget(app.TargetController.TargetTypeEnum, via.GameObject, via.vec3)", target_type, pgo, tv) end)
    pcall(function() tc:call("setTarget(app.TargetController.TargetTypeEnum)", target_type) end)
    -- Do not call updateTargetInfo/onUpdateTargetData/updateCatch here.  This
    -- helper runs every frame; repeatedly evaluating the selector held Iris in
    -- Locomotion.Fall for the entire lease.  The probe performs one genuine
    -- updateCatch at startup, while this loop only preserves its inputs.
    return true
end

function griffin_predation_clear_stale_transaction(ch, prey)
    -- Experiment 11 set IsActive=true by hand before calling startCatch. If the
    -- call bailed, that left a half-open controller which can reject the next
    -- legitimate native transaction. Only abort controllers that report active.
    local rows = {}
    local cc = nil
    pcall(function() cc = ch and ch:call("get_CatchController") end)
    if cc then
        local active = false
        pcall(function() active = cc:call("get_IsActive") == true end)
        if active then
            local ok = pcall(function() cc:call("abort(System.Boolean)", true) end)
            pcall(function() cc:call("set_IsActive(System.Boolean)", false) end)
            rows[#rows + 1] = "catcher-abort=" .. tostring(ok)
        end
    end
    local caught = nil
    pcall(function() caught = prey and prey:call("get_CaughtController") end)
    if caught then
        local active = false
        pcall(function() active = caught:call("get_IsActive") == true end)
        if active then
            local ok = pcall(function() caught:call("abortDirect") end)
            if not ok then pcall(function() caught:call("abort(System.Boolean)", true) end) end
            pcall(function() caught:call("set_IsActive(System.Boolean)", false) end)
            rows[#rows + 1] = "caught-abort=" .. tostring(ok)
        end
    end
    return #rows > 0 and table.concat(rows, ",") or "clean"
end

function griffin_predation_find_catch_owner(controller)
    if not controller then return nil end
    local found = nil
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            if not found then
                pcall(function()
                    local cc = ch and ch:call("get_CatchController")
                    if cc and same_obj(cc, controller) then found = ch end
                end)
            end
        end
    end)
    return found
end

function griffin_predation_live_sample()
    local ch, go = reacquire_griffin()
    local prey = S.companion_target
    local pgo = prey and char_go(prey)
    local out = {
        t = os.clock(),
        fsm = "?",
        action = "?",
        target_type = "?",
        target = "nil",
        predation_target = "nil",
        catch_target_type = "?",
        is_air_catch = "?",
        ox_carry_motion = "?",
        predation_enabled = "?",
        predation_angle = "?",
        catch_start_action = "?",
        catcher_active = "?",
        is_catching_target = "?",
        caught_active = "?",
        caught_by_griffin = "?",
        startcatch_seen = tonumber(S.route3_predation_startcatch_seen) or 0,
        caught_start_seen = tonumber(S.route3_predation_caught_start_seen) or 0,
        gate_attack_forced = tonumber(S.route3_predation_gate_attack_forced) or 0,
        gate_enable_forced = tonumber(S.route3_predation_gate_enable_forced) or 0,
        gate_angle_forced = tonumber(S.route3_predation_gate_angle_forced) or 0,
        attack_target_promoted = tonumber(S.route3_predation_attack_target_promoted) or 0,
        promote_hook = tostring(S.route3_predation_promote_last_hook or "none"),
    }
    if not (ch and go) then return out end
    pcall(function()
        local fsm = get_component(go, "via.motion.MotionFsm2")
        out.fsm = tostring(fsm and fsm:call("getCurrentNodeName", 0) or "?")
    end)
    pcall(function()
        local am = ch:call("get_ActionManager")
        out.action = tostring(am and am:call("getCurrentActionName(System.UInt32)", 0) or "?")
        out.action_hash = tostring(am and am:call("getCurrentActionHash(System.UInt32)", 0) or "?")
    end)
    local ch253 = get_component(go, "app.Ch253000")
    if ch253 then
        pcall(function() out.catch_target_type = tostring(ch253:call("get_CatchTargetType")) end)
        pcall(function() out.is_air_catch = tostring(ch253:call("get_IsAirCatch")) end)
        pcall(function() out.ox_carry_motion = tostring(ch253:call("get_OxCatchSetCarryedMotion")) end)
        pcall(function() out.predation_enabled = tostring(ch253:call("IsEnablePredation")) end)
        pcall(function() out.predation_angle = tostring(pgo and ch253:call("checkPredationAngle(via.GameObject)", pgo)) end)
        pcall(function() out.catch_start_action = tostring(ch253:call("getCatchStartAction")) end)
        pcall(function() out.enable_attack = tostring(ch253:call("checkEnableAttack")) end)
        pcall(function() out.enable_swoop_attack = tostring(ch253:call("checkEnableSwoopAttack")) end)
        pcall(function()
            local at = ch253:call("getAttackTarget")
            local ago, ach = nil, nil
            pcall(function() ago = at and at:call("get_GameObject") end)
            pcall(function() ach = at and at:call("get_Character") end)
            if not ago and ach then pcall(function() ago = char_go(ach) end) end
            out.attack_target = ago and tostring(ago:call("get_Name")) or (at and "SET(no GO)" or "nil")
            out.attack_target_text = at and tostring(at) or "nil"
            pcall(function() out.attack_target_type = at and tostring(at:get_type_definition():get_full_name()) or "nil" end)
        end)
        pcall(function()
            local v = ch253:call("get_PredationTarget")
            out.predation_target = v and tostring(v:call("get_Name")) or "nil"
        end)
        pcall(function()
            local tc = ch253:call("get_TargetController")
            out.target_type = tostring(tc and tc:call("get_TargetType") or "nil")
            local v = tc and tc:call("get_TargetGameObject")
            out.target = v and tostring(v:call("get_Name")) or "nil"
            local tat = tc and tc:call("get_TargetAIActionTarget")
            local tago = tat and tat:call("get_GameObject")
            out.tc_action_target = tago and tostring(tago:call("get_Name")) or (tat and "SET(no GO)" or "nil")
            pcall(function() out.tc_action_target_type = tat and tostring(tat:get_type_definition():get_full_name()) or "nil" end)
        end)
    end
    pcall(function()
        local cc = ch:call("get_CatchController")
        out.catcher_active = tostring(cc and cc:call("get_IsActive") or false)
        out.is_catching_target = tostring(cc and pgo and cc:call("isCatch(via.GameObject)", pgo) or false)
    end)
    pcall(function()
        local caught = prey and prey:call("get_CaughtController")
        out.caught_active = tostring(caught and caught:call("get_IsActive") or false)
        out.caught_by_griffin = tostring(caught and caught:call("isCaughtBy(via.GameObject)", go) or false)
    end)
    pcall(function()
        local gp, pp = transform_pos(go), transform_pos(pgo)
        if gp then out.griffin_pos = { x = tonumber(gp.x), y = tonumber(gp.y), z = tonumber(gp.z) } end
        if pp then out.prey_pos = { x = tonumber(pp.x), y = tonumber(pp.y), z = tonumber(pp.z) } end
        local gr, pr = transform_render_pos(go), transform_render_pos(pgo)
        if gr then out.griffin_render_pos = { x = tonumber(gr.x), y = tonumber(gr.y), z = tonumber(gr.z) } end
        if pr then out.prey_render_pos = { x = tonumber(pr.x), y = tonumber(pr.y), z = tonumber(pr.z) } end
        if gp and pp then out.distance = math.sqrt(math.max(0.0, distance_sq(gp, pp) or 0.0)) end
    end)
    pcall(function()
            local tc = ch253 and ch253:call("get_TargetController")
            local tp = tc and tc:call("get_TargetPosition")
            if tp then out.target_pos = { x = tonumber(tp.x), y = tonumber(tp.y), z = tonumber(tp.z) } end
            out.degree_to_target = tonumber(tc and tc:call("get_DegreeToTarget"))
    end)
    pcall(function()
        local sp = ch253 and ch253:call("get_AirSwoopAttackTargetLandPos")
        if sp then out.swoop_land_pos = { x = tonumber(sp.x), y = tonumber(sp.y), z = tonumber(sp.z) } end
    end)
    return out
end

function griffin_predation_dump_transaction(capture)
    capture = capture or {}
    local setting = capture.setting
    local fields = {}
    if setting then
        pcall(function()
            local td, seen = setting:get_type_definition(), {}
            while td do
                for _, f in ipairs(td:get_fields() or {}) do
                    local name = tostring(f:get_name() or "?")
                    if not seen[name] and not f:is_static() then
                        seen[name] = true
                        local value, ftype = nil, "?"
                        pcall(function() value = f:get_data(setting) end)
                        pcall(function() ftype = tostring(f:get_type():get_full_name()) end)
                        fields[#fields + 1] = { name = name, type = ftype, value = value == nil and "nil" or tostring(value) }
                    end
                end
                td = td:get_parent_type()
            end
        end)
        table.sort(fields, function(a, b) return tostring(a.name) < tostring(b.name) end)
    end
    local out = {
        time = os.date("%Y-%m-%d %H:%M:%S"),
        same_ridden_controller = capture.same_ridden == true,
        catcher = capture.catcher and tostring(griffin_display_name(capture.catcher)) or "nil",
        prey = capture.prey and tostring(griffin_display_name(capture.prey)) or "nil",
        setting_type = setting and tostring(setting:get_type_definition():get_full_name()) or "nil",
        setting_fields = fields,
        state = griffin_predation_live_sample(),
        tape = S.route3_predation_tape or {},
    }
    pcall(function()
        local cgo = capture.catcher and char_go(capture.catcher)
        local fsm = cgo and get_component(cgo, "via.motion.MotionFsm2")
        local c253 = cgo and get_component(cgo, "app.Ch253000")
        out.catcher_state = {
            name = tostring(go_name(cgo) or "nil"),
            fsm = tostring(fsm and fsm:call("getCurrentNodeName", 0) or "?"),
            predation_enabled = tostring(c253 and c253:call("IsEnablePredation") or "?"),
            predation_angle = tostring(c253 and capture.prey and c253:call("checkPredationAngle(via.GameObject)", char_go(capture.prey)) or "?"),
            catch_target_type = tostring(c253 and c253:call("get_CatchTargetType") or "?"),
            is_air_catch = tostring(c253 and c253:call("get_IsAirCatch") or "?"),
            action_hash = tostring(c253 and c253:call("getCatchStartAction") or "?"),
        }
    end)
    pcall(function() json.dump_file(MOD .. "_predation_transaction.json", out) end)
    S.route3_predation_capture_status = string.format("captured native Setting (%d fields, ridden=%s)", #fields, tostring(capture.same_ridden == true))
    return out
end

function griffin_predation_rearm_ride_suppression(ch, go)
    -- ROOT CAUSE of the post-catch ground slide (Fable dx 2026-07-11): the catch's
    -- set_griffin_puppet(false) ran restore_disabled(), RE-ENABLING her
    -- AIDecisionMaker + NavigationAI (suppressed at mount for the ridden invariant)
    -- and un-stopping navigation -- and NOTHING put them back. On the ground with
    -- an idle stick the re-woken brain owns the root -> she skates (air is fine:
    -- the transform drive overwrites her every frame). Re-arm the ridden
    -- suppression at every catch EXIT. Components only -- do NOT set_griffin_puppet
    -- (true)/resetActionAndAI here (could disturb a still-retained constraint).
    -- disable_record is idempotent+symmetric; the next catch's restore_disabled()
    -- re-enables them cleanly.
    if not (S.mounted and ch and go) then return end
    if C.disable_griffin_ai then
        disable_record(get_component(go, "app.AIDecisionMaker"), "app.AIDecisionMaker")
        disable_record(get_component(go, "app.NavigationAI"), "app.NavigationAI")
    end
    stop_navigation(ch, true)
end

function griffin_predation_clear_carry_layers(go)
    -- The carry GRIP is a partial-body clip on a motion layer above L0 -- nothing
    -- native clears it on a ridden body (the Ch253AirCatch_End cancel action can
    -- never play), so the talon stays gripped forever = contortion + slide + rider
    -- detach (Fable dx 2026-07-11). Clear layers 1-4 with the proven empty-motion
    -- recipe route3_flap_clear_overlay uses (0xFFFFFFFF sentinel). L0 left alone
    -- (base painters own it); only touches layers that actually hold a clip.
    local motion = get_component(go, "via.motion.Motion")
    if not motion then return 0 end
    local cleared = 0
    for li = 1, 4 do
        pcall(function()
            local layer = motion:call("getLayer", li)
            local id = layer and tonumber(layer:call("get_MotionID"))
            if id and id < 4294967295 then
                local ok = pcall(function()
                    layer:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                        0, 4294967295, 0.0, 8.0, 1, 1)
                end)
                if not ok then pcall(function() layer:call("clearMotion") end) end
                cleared = cleared + 1
            end
        end)
    end
    return cleared
end

function griffin_predation_end_catcher(ch)
    -- Guarantee the catcher half DIES at exit. Stage must already be "released" so
    -- the retention hooks pass these through. A half-alive CatchController keeps
    -- running per-frame carry maintenance (keep-joint-height / terrain overwrite) =
    -- the ground SLIDE, and it never clears its own grip.
    local cc = nil
    pcall(function() cc = ch and ch:call("get_CatchController") end)
    if not cc then return "no cc" end
    pcall(function() cc:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
    pcall(function() cc:call("set_IsContinue(System.Boolean)", false) end)
    pcall(function() cc:call("abort(System.Boolean)", true) end)
    local still = false
    pcall(function() still = cc:call("get_IsActive") == true end)
    if still then pcall(function() cc:call("set_IsActive(System.Boolean)", false) end) end  -- last resort
    return still and "forced-inactive" or "aborted"
end

function griffin_predation_exit_cleanup(ch, go)
    -- ORDER MATTERS: end catcher -> clear grip layers -> repose. The CALLER
    -- re-freezes the motion-fsm puppet AFTER this (and only on the ground) --
    -- freezing first is what latched the grip pose at the current frame.
    if not (ch and go) then return "no griffin" end
    -- restore the VICTIM's FSM: the struggle driver puppets it to hold the catch;
    -- a dropped victim must get its FSM back or it stays frozen instead of ragdolling.
    pcall(function()
        local v = S.route3_predation_victim
        if v then set_motion_fsm_puppet(char_go(v), false) end
    end)
    local ended = griffin_predation_end_catcher(ch)
    local layers = griffin_predation_clear_carry_layers(go)
    if S.airborne == true then
        -- do NOT changeMotion a flight clip here (native-AV law). Force the existing
        -- ridden-flight tick to full-wake + re-assert FlyForward/Hover next frame.
        S.route3_native_flight_node = nil
        S.route3_native_flight_last_check = 0.0
    else
        S.route3_post_landing_recover_at = os.clock()  -- existing calm-node + L0 idle recover
    end
    return string.format("carry exit: catcher=%s layers=%d", tostring(ended), layers)
end

-- ============ OX-DROP TAPE (Iris 2026-07-13, Aurora's idea) ============
-- Read-only per-frame recorder (NO hooks -> no restart). Arm it while carrying an ox natively, then
-- DROP the ox: it captures exactly what the native release does to the OX -- its action node, whether
-- its motion keeps ticking (scripted anim) or stops (physics ragdoll), the fall trajectory (smooth
-- gravity vs teleport), and ragdoll flags -- so the homebrew drop can reproduce it instead of guessing.
function griffin_ox_drop_tape_tick()
    local untilc = tonumber(S.route3_ox_drop_tape_until) or 0.0
    if untilc <= 0.0 then return end
    local now = os.clock()
    if now > untilc then
        pcall(function() json.dump_file(MOD .. "_ox_drop_tape.json", { time = os.date("%H:%M:%S"), rows = S.route3_ox_drop_tape or {} }) end)
        S.route3_ox_drop_tape_until = 0.0
        S.route3_predation_status = "ox-drop tape: dumped " .. tostring(#(S.route3_ox_drop_tape or {})) .. " rows"
        return
    end
    if now - (tonumber(S.route3_ox_drop_tape_last) or 0.0) < 0.1 then return end   -- ~10 Hz
    S.route3_ox_drop_tape_last = now
    local prey = S.route3_ox_drop_tape_prey or S.route3_predation_carry_prey or S.route3_predation_victim or S.companion_target
    if not prey then
        pcall(function()
            local _, g = reacquire_griffin()
            local c253 = g and get_component(g, "app.Ch253000")
            local tgo = c253 and c253:call("get_PredationTarget")
            if tgo then prey = get_component(tgo, "app.Character") end
        end)
    end
    if prey then S.route3_ox_drop_tape_prey = prey end
    if not prey then
        local rows = S.route3_ox_drop_tape or {}
        rows[#rows + 1] = string.format("%.1fs (no prey ref)", now - (tonumber(S.route3_ox_drop_tape_t0) or now))
        S.route3_ox_drop_tape = rows
        return
    end
    local pgo = char_go(prey)
    local node, clip, py, caught_a, dead, ragf, dmgfall = "?", "?", "?", "?", "?", "?", "?"
    pcall(function() local fsm = get_component(pgo, "via.motion.MotionFsm2"); node = tostring(fsm and fsm:call("getCurrentNodeName", 0)) end)
    pcall(function() local m = prey:call("get_Motion"); local l = m and m:call("getLayer", 0)
        if l then clip = string.format("b%s:%s f%s", tostring(l:call("get_MotionBankID")), tostring(l:call("get_MotionID")), tostring(l:call("get_Frame"))) end end)
    pcall(function() local rp = transform_render_pos(pgo); py = string.format("%.2f", tonumber(rp and rp.y) or 0.0) end)
    pcall(function() local c = prey:call("get_CaughtController"); caught_a = tostring(c and c:call("get_IsActive")) end)
    pcall(function() dead = tostring(is_dead(prey)) end)
    pcall(function() ragf = tostring(prey:call("get_IsForceEnableRagdoll")) end)
    pcall(function() dmgfall = tostring(prey:call("get_IsDamageFall")) end)
    local rows = S.route3_ox_drop_tape or {}
    rows[#rows + 1] = string.format("%.1fs node=%s L0=%s y=%s caught=%s dead=%s forceRag=%s dmgFall=%s",
        now - (tonumber(S.route3_ox_drop_tape_t0) or now), node, clip, py, caught_a, dead, ragf, dmgfall)
    S.route3_ox_drop_tape = rows
end

function griffin_predation_rebase_drive()
    -- Native control may have moved her tens of metres. Adopt that position
    -- before the mount authority resumes or the next on-frame pass snaps her
    -- back to the stale pre-swoop transform.
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    local pos, rot = transform_pos(go), transform_rot(go)
    if not pos then return false end
    S.route3_air_pos, S.drive_pos = pos, pos
    if rot then S.route3_air_rot, S.drive_rot = rot, rot end
    S.heading_yaw = yaw_from_transform(go) or S.heading_yaw
    return true
end

function griffin_predation_build_hybrid_setting()
    -- GRIFFIN-CATCHES-ANY-SPECIES Setting. The victim animation (whether it
    -- struggles or freezes in the talon) is driven by the Caught* action names,
    -- which are SPECIES/family-specific: an ox uses "Caught_Default", a goblin/
    -- small-humanoid uses "Caught_CarryStart" (captured from a player grab). So:
    -- CLONE whatever species Setting was last captured (its Caught* half is
    -- correct for that creature) and GRAFT the griffin's catcher half on top (her
    -- swoop-catch actions + talon joint R_PropA + no-escape, since our retention
    -- owns the lifetime). One capture per animation FAMILY, not per enemy. Falls
    -- back to the ox Setting if nothing has been captured this session.
    local function graft_griffin_catcher(setting)
        -- overwrite the catcher half with the griffin's swoop-catch + talon +
        -- no-escape (retention owns the lease); leave the victim Caught* half.
        local function setn(name, value) pcall(function() setting:set_field(name, value) end) end
        local function sets(name, value) pcall(function() setting:set_field(name, value == nil and nil or sdk.create_managed_string(value)) end) end
        setn("CatchType", 1)
        sets("Name", "")
        setn("CatchStartActionLayer", 0)
        sets("CatchStartAction", "Ch253AirSwoopAttackCatchToBringSuccess")
        sets("CatchCancelAction", "Ch253AirCatch_End")
        sets("CatchEscapeAction", "Ch253AirCatch_Escape")
        sets("ParentJointName", "R_PropA")   -- her talon, not the player's arm
        setn("InterpolationFrame", 8.0)
        setn("InterpolationType", 0)
        setn("IsDisableCaughtIK", true)
        local never = 3.4028234663853e38
        setn("EscapeSec", never); setn("NearlyEscapeSec", never)
        setn("GachaValue", never); setn("ResistSec", never)
        setn("IsNoCheckCaughtStartAndCancelAction", C.route3_predation_nocheck_caught == true)  -- ox uses false = PLAY the caught action
    end
    local base = S.route3_predation_captured_setting
    if base then
        -- LIVE CAPTURE this session: clone every field (victim Caught* half + escape
        -- values come across correct for whatever species was grabbed), then graft.
        local setting = nil
        pcall(function()
            setting = sdk.create_instance("app.CatchController.Setting"):add_ref()
            pcall(function() setting:call(".ctor()") end)
            local td = base:get_type_definition()
            while td do
                for _, f in ipairs(td:get_fields() or {}) do
                    if not f:is_static() then
                        local n = f:get_name()
                        pcall(function() setting:set_field(n, base:get_field(n)) end)
                    end
                end
                td = td:get_parent_type()
            end
            graft_griffin_catcher(setting)
        end)
        if setting then return setting end
    end
    -- NO live capture (e.g. after a reload -- the capture lives in volatile state):
    -- build from the known "carry" small-enemy victim vocabulary (goblin/bandit/
    -- humanoid), captured 2026-07-10 from a player grab. Tunable via config for
    -- other families; blank the whole set to force a fresh in-session capture.
    local setting = nil
    pcall(function()
        setting = sdk.create_instance("app.CatchController.Setting"):add_ref()
        pcall(function() setting:call(".ctor()") end)
        local function sets(name, value) pcall(function() setting:set_field(name, value == nil and nil or sdk.create_managed_string(value)) end) end
        sets("CaughtStartAction", tostring(C.route3_predation_caught_start or "Caught_CarryStart"))
        sets("CaughtResistAction", tostring(C.route3_predation_caught_resist or "Caught_CarryResist"))
        sets("CaughtNearlyEscapeAction", tostring(C.route3_predation_caught_nearly or "Caught_CarryNearlyEscape"))
        sets("CaughtDieAction", tostring(C.route3_predation_caught_die or "Caught_CarryDie"))
        sets("CaughtCancelAction", tostring(C.route3_predation_caught_cancel or "DmgRagdollFall"))
        sets("CaughtCancelActionForDead", tostring(C.route3_predation_caught_cancel or "DmgRagdollFall"))
        graft_griffin_catcher(setting)
    end)
    return setting or griffin_predation_build_wild_ox_setting()
end

function griffin_predation_build_wild_ox_setting()
    -- Captured verbatim from a real wild Griffin -> ox startCatch transaction
    -- at 2026-07-10 20:22:43. Unlike the old blank Setting, this contains the
    -- native catcher and victim action contract used by the success node.
    if S.route3_predation_baked_wild_setting then return S.route3_predation_baked_wild_setting end
    local setting = nil
    pcall(function()
        setting = sdk.create_instance("app.CatchController.Setting"):add_ref()
        pcall(function() setting:call(".ctor()") end)
        local function setn(name, value) pcall(function() setting:set_field(name, value) end) end
        local function sets(name, value)
            if value == nil then setn(name, nil)
            else pcall(function() setting:set_field(name, sdk.create_managed_string(value)) end) end
        end
        setn("CatchType", 1)
        sets("Name", "")
        setn("CatchStartActionLayer", 0)
        sets("CatchStartAction", "Ch253AirSwoopAttackCatchToBringSuccess")
        sets("CatchCancelAction", "Ch253AirCatch_End")
        sets("CatchEscapeAction", "Ch253AirCatch_Escape")
        sets("CatchCaughtDamageAction", nil)
        sets("CatchResistAction", nil)
        sets("CatchRestartAction", nil)
        sets("CaughtStartAction", "Caught_Default")
        sets("CaughtCancelAction", "CatchEndByCh253000")
        sets("CaughtCancelActionForDead", "Caught_ReleaseForDead")
        sets("CaughtDamageAction", "")
        sets("CaughtDieAction", "CatchEndByCh253000Die")
        sets("CaughtEscapeAction", "CatchEndByCh253000")
        sets("CaughtNearlyEscapeAction", nil)
        sets("CaughtResistAction", nil)
        sets("ConstraintChildJointName", nil)
        sets("ParentJointName", "R_PropA")
        setn("InterpolationFrame", 8.0)
        setn("InterpolationType", 0)
        setn("IsDisableCatchCancelActionOnAbort", false)
        setn("IsDisableCaughtIK", true)
        setn("IsForceUseExtraJoint", false)
        setn("IsInterpolatingCaughtEnableLanding", false)
        setn("IsNoCheckCaughtStartAndCancelAction", false)
        local never = 3.4028234663853e38
        setn("EscapeSec", never)
        setn("GachaValue", never)
        setn("NearlyEscapeSec", never)
        setn("ResistSec", never)
    end)
    S.route3_predation_baked_wild_setting = setting
    return setting
end

function griffin_prey_has_caught_machinery(prey)
    -- CRASH GUARD. startCatch REQUIRES the prey to already own a live (even if
    -- inactive) app.CaughtController -- it does not create one; feeding it a prey
    -- whose controller field is null deref'd garbage and CTD'd. The Fable panel
    -- (2026-07-10) found the earlier method-existence fallback here was VACUOUS:
    -- get_CaughtController is a method on EVERY app.Character, so after the
    -- app.Character normalizer fix it passed even null-victim prey -- defeating
    -- the guard's whole purpose. Require the GETTER to return a live object (the
    -- only thing startCatch actually consumes). NOTE: whether a goblin's getter
    -- is null is UNPROVEN -- the old "goblin has no caught half" claim came from
    -- querying the wrong (monster-behavior) ref; re-INSPECT settles it.
    if not prey then return false end
    local chara = griffin_as_character(prey)  -- query app.Character, not the raw monster ref
    local ok = false
    pcall(function() if chara and chara:call("get_CaughtController") ~= nil then ok = true end end)
    if ok then return true end
    -- Theoretical fallback: an actually-attached CaughtController component. Never
    -- observed on any character (the panel says it's a field, not a component),
    -- but harmless to check and cheap insurance if a species ever differs.
    pcall(function() if get_component(char_go(prey), "app.CaughtController") then ok = true end end)
    return ok
end

function griffin_predation_attach_probe(prey_override, setting_override)
    -- Replay only a Setting captured from an actual native startCatch. The old
    -- probe created an almost blank Setting (all catcher/caught action names
    -- nil), manually marked the controller active, then mislabelled isCatch()
    -- as an eligibility test. That was not a valid native transaction.
    -- prey_override: the generic small-target button hands in its own victim.
    -- setting_override: the small path passes a species HYBRID Setting; bare, this
    -- stays the proven ox path (hardcoded ox Setting, never the volatile capture).
    local ch, go = reacquire_griffin()
    if not (ch and go) then S.route3_predation_status = "attach: no griffin"; return false end
    local prey = prey_override or griffin_find_predation_ox(15.0) or S.companion_target or griffin_find_prey_or_enemy(15.0)
    if not prey then S.route3_predation_status = "attach: no prey within 15m"; return false end
    -- Normalize to the app.Character component: EnemyManager prey arrive as the
    -- monster behavior (app.Ch2xx), but startCatch's param type is app.Character.
    -- Passing the wrong ref was almost certainly the force-catch CTD. The ox path
    -- already holds app.Character, so this is a no-op there.
    prey = griffin_as_character(prey) or prey
    -- HARD crash guard: refuse any prey that lacks the caught half. The ox/human/
    -- pawn all pass; monster classes like the goblin (ch220000) are refused here
    -- instead of taking the game down inside native startCatch.
    if not griffin_prey_has_caught_machinery(prey) then
        S.route3_predation_status = string.format(
            "attach REFUSED: %s (%s) has no CaughtController -- not catchable, would CTD",
            tostring(griffin_display_name(prey)), tostring(go_name(char_go(prey)) or "?"))
        return false
    end
    -- ONLY the real ox (ch299003) self-animates its struggle under griffin carry
    -- (the native carry drives it) -- so only it gets ox carry-motion and is
    -- exempt from our struggle driver. Stag/rabbit/deer are ch299 but DON'T self-
    -- animate (verified 2026-07-11: frozen on Caught_Default) -> they need driving
    -- like the goblin. (Vocabulary is still picked per-family in setting_for.)
    pcall(function() griffin_grab_crash_mark("attach: machinery OK prey=" .. tostring(go_name(char_go(prey)) or "?")) end)
    S.route3_predation_prey_is_ox = tostring(go_name(char_go(prey)) or ""):lower():find("ch299003", 1, true) ~= nil
    local cc = nil
    pcall(function() cc = ch:call("get_CatchController") end)
    if not cc then S.route3_predation_status = "attach: no CatchController"; return false end
    -- Explicit selection: an override (species hybrid) if given, else the RELIABLE
    -- hardcoded ox Setting. Deliberately NOT S.route3_predation_captured_setting --
    -- a fresh player-grab capture overwrites it with the wrong (player) catcher
    -- half + wrong joint, which would silently break even the ox path.
    local setting = setting_override or griffin_predation_build_wild_ox_setting()
    if not setting then
        S.route3_predation_status = "attach: failed to build Setting"
        return false
    end
    local pgo = char_go(prey)
    S.companion_target, S.companion_target_go = prey, pgo
    S.route3_predation_victim = prey              -- dedicated ref (attack retargeter reassigns companion_target)
    S.route3_predation_carry_prey = prey          -- STABLE pin ref (2026-07-12): set at catch, cleared ONLY on release. predation_victim AND companion_target both flicker nil mid-carry (attack retargeter etc.), which made the follow-pin bail "no-prey" every frame.
    S.route3_predation_carry_at = os.clock()      -- when the native carry established (eat-on-landing grace)
    S.route3_carry_dbg_frame = 0
    S.route3_struggle_last_try, S.route3_struggle_tries = 0.0, 0
    S.route3_struggle_pushed = false
    S.route3_struggle_interp_ended = false
    S.route3_struggle_used_native = false
    S.route3_struggle_active_since = 0.0
    S.route3_predation_victim_clip = nil
    pcall(function()
        if S.route3_predation_prey_is_ox ~= true then
            S.route3_predation_victim_clip = griffin_predation_resolve_victim_clip(prey)
        end
    end)
    local already_active = false
    pcall(function() already_active = cc:call("get_IsActive") == true end)
    pcall(function()
        local caught_ctrl = prey:call("get_CaughtController")
        already_active = already_active or (caught_ctrl and caught_ctrl:call("get_IsActive") == true)
    end)
    if already_active then
        S.route3_predation_status = "wild replay: catch already active; refusing to abort/restart it"
        return false
    end
    local was_catching, stale = "?", griffin_predation_clear_stale_transaction(ch, prey)
    pcall(function() was_catching = tostring(cc:call("isCatch(via.GameObject)", pgo)) end)
    local now, untilc = os.clock(), os.clock() + 8.0
    S.route3_predation_mode = "native"
    S.route3_predation_assisted = true
    S.route3_predation_force_claim_active = false
    S.route3_predation_hash_fallback_active = false
    S.route3_predation_force_enemy_active = false
    S.route3_predation_probe_until = untilc
    S.route3_predation_wake_until = untilc
    S.route3_predation_native_until = untilc
    S.route3_predation_hash_requested = true
    S.route3_predation_carry_retention_active = false
    S.route3_predation_retained_ends = 0
    S.route3_predation_last_retained_end = nil
    -- A grip sample belongs to one native catch transaction. Never reuse a pose
    -- captured from an earlier griffin/scale/session.
    S.route3_predation_grip_sample = nil
    S.route3_predation_grip_names = nil
    S.route3_predation_grip_motion_map = nil
    S.route3_predation_native_grip_held = false
    S.route3_predation_grip_capture_done = false
    S.route3_predation_grip_capture_failed = false
    S.route3_predation_grip_hits = 0
    S.route3_predation_grip_best_score = nil
    S.route3_predation_grip_best_sample = nil
    S.route3_predation_grip_sample_count = 0
    S.route3_predation_grip_score_trace = {}
    S.route3_predation_grip_anchor_pos = nil
    S.route3_predation_grip_anchor_rot = nil
    S.route3_predation_grip_status = "waiting for BringStart grip sample"
    S.route3_predation_startcatch_seen = 0
    S.route3_predation_caught_start_seen = 0
    S.route3_predation_tape = {}
    S.route3_predation_tape_last = 0.0
    S.route3_predation_tape_dump_last = 0.0
    pcall(function() griffin_grab_crash_mark("attach: puppet OFF + think wake") end)
    pcall(function() set_griffin_puppet(false) end)
    pcall(function() set_think_stop(ch, false) end)
    pcall(function() set_griffin_motion_speed(1.0) end)
    pcall(function() stop_navigation(ch, false) end)
    pcall(function()
        local c253 = get_component(go, "app.Ch253000")
        if c253 then
            griffin_grab_crash_mark("attach: c253 prime")
            c253:call("set_PredationTarget(via.GameObject)", pgo)
            c253:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 3)
            c253:call("set_IsAirCatch(System.Boolean)", true)
            -- Fable 2026-07-11: DON'T hard-prime this false. For non-ox prey the caught HOLD rides
            -- the griffin's ox-carry channel (OxCatchSetCarryedMotion keeps re-driving the victim's
            -- caught motion); priming false before startCatch neutered the hold = goblin fell out of
            -- the talon. Prime it with the same force/species decision apply_carry_motion uses.
            c253:call("set_OxCatchSetCarryedMotion(System.Boolean)", (S.route3_predation_prey_is_ox == true) or (C.route3_predation_force_victim_ox_motion == true))
        end
    end)
    pcall(function() set_think_stop(prey, false) end)
    pcall(function() local m = prey:call("get_Motion"); if m then m:call("set_PlaySpeed", 1.0) end end)
    -- ⭐ RACE FIX (Iris 2026-07-13): ARM the carry-retention hook BEFORE startCatch, not after.
    -- Good vs bad ox carry differed in EXACTLY ONE field: retainedEnds (1 vs 0). The native success
    -- action (Ch253AirSwoopAttackCatchToBringSuccess) can fire its terminal end (endFromFsm/onFinish)
    -- DURING startCatch's synchronous run -- BEFORE the old arming point in the establish block below.
    -- When it fires early, the hook isn't live yet -> the end runs UNBLOCKED -> the success action
    -- cleans up its pose -> talons splay back into the ox (retainedEnds=0). When the native FSM happens
    -- to fire the end a frame later, the old arming caught it (retainedEnds=1, correct grip). Arming
    -- here makes it deterministic. Disarmed again below if the catch never establishes.
    S.route3_predation_carry_retention_active = true
    pcall(function() griffin_grab_crash_mark("attach: before startCatch") end)
    local ok, err = pcall(function()
        cc:call("startCatch(app.Character, app.CatchController.Setting, app.CatchInterpolator)", prey, setting, nil)
    end)
    pcall(function() griffin_grab_crash_mark("attach: startCatch returned ok=" .. tostring(ok)) end)
    local active, caught, active_bool, caught_bool = "?", "?", false, false
    pcall(function() active_bool = cc:call("get_IsActive") == true; active = tostring(active_bool) end)
    pcall(function()
        local c = prey:call("get_CaughtController")
        caught_bool = c and c:call("get_IsActive") == true or false
        caught = tostring(caught_bool)
    end)
    local chained = false
    if ok and active_bool and caught_bool then
        -- Preserve the accepted transaction itself. The native landing node
        -- immediately chooses Ch253Catch_End on a ridden body, while Aurora's
        -- manual Stop-lease test proved the constraint survives direct handoff.
        local caught_ctrl = nil
        pcall(function() caught_ctrl = prey:call("get_CaughtController") end)
        pcall(function() cc:call("set_IsRejectAbortOnDefault(System.Boolean)", true) end)
        pcall(function() cc:call("set_IsContinue(System.Boolean)", true) end)
        pcall(function() caught_ctrl:call("set_IsRejectAbortOnDefault(System.Boolean)", true) end)
        pcall(function() caught_ctrl:call("set_IsContinue(System.Boolean)", true) end)
        -- Escape-disable ONLY for the ox. For non-ox, disabling escape ALSO kills
        -- isCanStruggle (struggle is the visual arm of the escape/resist machinery)
        -- -> the victim can't struggle. EscapeSec=floatmax already stops the timer,
        -- so retention stays safe without these (Fable review 2026-07-11).
        if S.route3_predation_prey_is_ox == true then
            pcall(function() cc:call("requestDisableEscape") end)
            pcall(function() caught_ctrl:call("set_IsDisableEscape(System.Boolean)", true) end)
        end
        pcall(function() griffin_grab_crash_mark("attach: apply_carry_motion") end)
        pcall(function() griffin_predation_apply_carry_motion(get_component(go, "app.Ch253000")) end)
        pcall(function() griffin_grab_crash_mark("attach: apply_carry_motion OK") end)
        -- The real constraint is now live.  Retain it while advancing out of the
        -- one-shot success pose and through the wild carry-to-flight branch.
        S.route3_predation_carry_retention_active = true
        chained = true
        -- CARRY STAGING (2026-07-11): "none" hands straight to the rider (skip ALL wild
        -- staging -- flies clean but non-ox prey never gets pulled to the talon + she freezes
        -- on the ground). "carry"/"full" run Ch253CarryCatchToFlight first (that node attaches
        -- the prey to the talon AND moves her off the frozen catch-success pose); the to-flight
        -- stage then decides whether to also fire the corrupting FlightPathTraceTarget.
        S.route3_predation_replay_stage = (tostring(C.route3_predation_carry_stage) == "none") and "lean-handoff" or "retained-success"
        S.route3_predation_replay_stage_at = os.clock()
    else
        -- Catch never established -> disarm the retention we armed before startCatch (nothing to hold),
        -- so a failed grab can't leave the hook blocking unrelated catch ends.
        S.route3_predation_carry_retention_active = false
    end
    -- ATTACH DIAGNOSTIC (2026-07-11): the goblin "dangles but stays on the GROUND". Capture the
    -- ground truth -- did the catch ESTABLISH (caughtActive) and is the prey POSITIONALLY at the
    -- talon (dist to R_PropA, render space so the tile offset cancels) or left where it stood?
    pcall(function()
        local prp = transform_render_pos(char_go(prey))
        local tw = nil
        local gtf = transform_of(go)
        local joint = gtf and managed_call(gtf, "getJointByName", tostring(C.route3_grab_talon_joint or "R_PropA"))
        if joint then tw = managed_call(joint, "get_Position") or managed_call(joint, "get_WorldPosition") end
        local dist = (prp and tw) and math.sqrt(
            ((tonumber(prp.x) or 0.0) - (tonumber(tw.x) or 0.0))^2 +
            ((tonumber(prp.y) or 0.0) - (tonumber(tw.y) or 0.0))^2 +
            ((tonumber(prp.z) or 0.0) - (tonumber(tw.z) or 0.0))^2) or -1.0
        local pclip = "?"
        pcall(function() local m = prey:call("get_Motion"); local l = m and m:call("getLayer", 0)
            if l then pclip = string.format("bank=%s id=%s", tostring(l:call("get_MotionBankID")), tostring(l:call("get_MotionID"))) end end)
        json.dump_file(MOD .. "_goblin_attach.json", {
            time = os.date("%H:%M:%S"),
            prey = tostring(go_name(char_go(prey)) or "?"),
            startCatch_ok = ok, catcherActive = active_bool, caughtActive = caught_bool,
            directHandoff = chained, talon_dist_m = dist, prey_L0 = pclip,
            carry_stage = tostring(C.route3_predation_carry_stage),
            nocheck = C.route3_predation_nocheck_caught == true,
        })
    end)
    S.route3_predation_status = string.format(
        "wild replay: beforeIsCatching=%s stale=%s call=%s catcherActive=%s caughtActive=%s directHandoff=%s prey=%s",
        was_catching, stale, ok and "OK" or ("FAILED " .. tostring(err):sub(-60)),
        active, caught, tostring(chained), tostring(griffin_display_name(prey)))
    pcall(function() griffin_grab_crash_mark("attach: EXIT ok=" .. tostring(ok)) end)
    return ok
end

function griffin_predation_apply_carry_motion(c253)
    -- The griffin's carry directives. OxCatchSetCarryedMotion FORCES the ox's
    -- carried animation onto the victim + "AddBringOx" is her ox-carry body pose.
    -- Correct for an ox; for a goblin/humanoid the forced ox motion OVERRIDES the
    -- victim's own Caught_CarryStart and FREEZES it (2026-07-11). So apply ox
    -- motion only for actual ox prey (or if force-toggled). Non-ox victims keep
    -- their own struggle; the attachment itself is the joint constraint, unaffected.
    if not c253 then return end
    local use_ox = (S.route3_predation_prey_is_ox == true) or (C.route3_predation_force_victim_ox_motion == true)
    pcall(function() c253:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 3) end)
    pcall(function() c253:call("set_IsAirCatch(System.Boolean)", true) end)
    pcall(function() c253:call("set_OxCatchSetCarryedMotion(System.Boolean)", use_ox) end)
    pcall(function() c253:call("set_MotinoLayerActionBodyName(System.String)", use_ox and "AddBringOx" or "Default") end)
end

function griffin_predation_replay_continue_tick(now)
    local stage = tostring(S.route3_predation_replay_stage or "")
    if stage == "" or stage == "handed-off" or stage == "released" then return end
    now = tonumber(now) or os.clock()
    local ch, go = reacquire_griffin()
    local prey = S.companion_target
    if not (ch and go and prey) then return end
    local caught_active = false
    pcall(function()
        local caught = prey:call("get_CaughtController")
        caught_active = caught and caught:call("get_IsActive") == true or false
    end)
    if not caught_active then
        -- natural drop: only the RELEASE button used to reset these. Reset the ox
        -- carry directives AND re-arm ride suppression here too, else the woken
        -- brain skates her on the next landing (Fable dx 2026-07-11).
        S.route3_predation_replay_stage = "released"
        S.route3_predation_carry_retention_active = false
        S.route3_predation_grip_sample = nil
        S.route3_predation_grip_names = nil
        S.route3_predation_grip_motion_map = nil
        S.route3_predation_native_grip_held = false
        S.route3_predation_grip_capture_done = false
        S.route3_predation_grip_anchor_pos = nil
        S.route3_predation_grip_anchor_rot = nil
        S.route3_predation_grip_status = "released"
        pcall(function()
            local c253d = get_component(go, "app.Ch253000")
            if c253d then
                c253d:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 0)
                c253d:call("set_IsAirCatch(System.Boolean)", false)
                c253d:call("set_OxCatchSetCarryedMotion(System.Boolean)", false)
                c253d:call("set_MotinoLayerActionBodyName(System.String)", "Default")
            end
        end)
        pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
        pcall(function() griffin_predation_exit_cleanup(ch, go) end)
        S.route3_struggle_pushed = false
        S.route3_predation_victim = nil
        return
    end
    local elapsed = now - (tonumber(S.route3_predation_replay_stage_at) or now)
    local c253 = get_component(go, "app.Ch253000")

    if stage == "lean-handoff" then
        -- IMMEDIATE hand-off (LEAN CARRY): adopt the current in-flight transform, restore
        -- ridden flight, release only the PROBE's ownership -- NOT the Catch/Caught
        -- controllers (retention keeps them alive). NO wild FSM node requests, so her flight
        -- FSM is never corrupted = no float/contort/jam. Re-assert the carry directives once
        -- so the attachment pose holds. This is the "flight" stage handoff minus the staging.
        pcall(function() griffin_predation_apply_carry_motion(c253) end)
        griffin_predation_rebase_drive()
        pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
        S.route3_predation_replay_stage = "handed-off"
        S.route3_predation_replay_stage_at = now
        S.route3_predation_native_until = 0.0
        S.route3_predation_wake_until = 0.0
        S.route3_predation_probe_until = 0.0
        S.route3_predation_mode = nil
        S.base_owner = nil
        S.audition_until_clock = 0.0
        S.route3_flap_phase = nil
        S.route3_soar_dir_clip = nil
        S.last_root_motion_state = nil
        S.last_root_motion_key = nil
        S.route3_predation_status = "LEAN CATCH: native carry handed to rider (no wild flight staging)"
        pcall(function() griffin_grab_crash_mark("stage: LEAN handoff") end)
        return
    end

    if stage == "retained-success" and elapsed >= 0.30 then
        -- BringStart's correct grip is PROCEDURAL/node-bound, not a reusable bone
        -- pose (the 20- and 48-joint Motion replays both proved that). Keep the
        -- native node for an ox; release has a scoped pre-exit back through
        -- CarryCatchToFlight before Catch/Caught are ended.
        local native_grip_hold = C.route3_predation_native_grip_hold ~= false
            and S.route3_predation_prey_is_ox == true
        local capture_grip = not native_grip_hold
            and C.route3_predation_grip_pose_enabled ~= false
            and S.route3_predation_prey_is_ox == true
        local action = (native_grip_hold or capture_grip) and tostring(C.route3_predation_grip_capture_action or "Ch253AirSwoopCatchToBringStart")
            or tostring(C.route3_predation_carry_action or "Ch253CarryCatchToFlight")
        local node = (native_grip_hold or capture_grip) and tostring(C.route3_predation_grip_capture_node or "Catch.Ch253AirSwoopCatchToBringStart")
            or tostring(C.route3_predation_carry_node or "Catch.Ch253CarryCatchToFlight")
        if native_grip_hold or capture_grip then
            -- Keep the native motion/AI live, but pin the root to the entry
            -- transform during the short settle/sampling window.
            S.route3_predation_grip_anchor_pos = transform_pos(go)
            S.route3_predation_grip_anchor_rot = transform_rot(go)
        end
        if capture_grip then
            S.route3_predation_grip_best_score = nil
            S.route3_predation_grip_best_sample = nil
            S.route3_predation_grip_sample_count = 0
            S.route3_predation_grip_score_trace = {}
        end
        pcall(function() griffin_grab_crash_mark("stage: FORCE "
            .. (native_grip_hold and "native-grip-hold " or (capture_grip and "grip-capture " or "carry ")) .. action) end)
        pcall(function() griffin_predation_apply_carry_motion(c253) end)
        pcall(function() request_griffin_action(action, 0) end)
        local moved = false
        pcall(function() moved = set_griffin_fsm_node_silent(node, 0) == true end)
        -- FREEZE PATH: a grip-correct but MOVING Bring node needs to be frozen fast (short settle) so it
        -- can't fly her off; the normal to-flight/FlightPathTraceTarget staging just gives it more time
        -- to teleport. Non-freeze keeps the original staging.
        S.route3_predation_replay_stage = native_grip_hold and "native-grip-settle"
            or (capture_grip and "grip-capture")
            or ((C.route3_predation_carry_freeze == true) and "freeze-settle" or "to-flight")
        S.route3_predation_replay_stage_at = now
        S.route3_predation_status = native_grip_hold
            and (moved and "native ox grip: BringStart settling" or "native ox grip: BringStart requested")
            or (capture_grip
            and (moved and "native carry: sampling BringStart talons" or "native carry: BringStart sample requested")
            or (moved and "native carry: carry node forced" or "native carry: carry node request sent"))
        pcall(function() griffin_grab_crash_mark("stage: node forced OK moved=" .. tostring(moved)) end)
        return
    end

    if stage == "grip-capture" then
        local settle = math.max(0.02, tonumber(C.route3_predation_grip_capture_settle) or 0.15)
        local window = math.max(0.10, tonumber(C.route3_predation_grip_capture_window) or 0.70)
        -- LateUpdate performs the snapshot after UpdateMotion. The timeout keeps a
        -- missing joint/callback from trapping the native hunt in BringStart.
        if S.route3_predation_grip_capture_done == true or elapsed >= settle + window + 0.50 then
            if S.route3_predation_grip_capture_done ~= true then
                S.route3_predation_grip_capture_failed = true
                S.route3_predation_status = "native carry: grip capture timed out; continuing safely"
            end
            pcall(function() griffin_predation_apply_carry_motion(c253) end)
            -- Always leave the sampling node through the proven transition. The
            -- old live A/B setting may still be saved as BringStart from earlier
            -- experiments; honouring it here would recreate the post-drop hunt.
            pcall(function() request_griffin_action("Ch253CarryCatchToFlight", 0) end)
            local moved = false
            pcall(function() moved = set_griffin_fsm_node_silent("Catch.Ch253CarryCatchToFlight", 0) == true end)
            S.route3_predation_replay_stage = "to-flight"
            S.route3_predation_replay_stage_at = now
            S.route3_predation_grip_anchor_pos = nil
            S.route3_predation_grip_anchor_rot = nil
            pcall(function() griffin_grab_crash_mark("stage: grip captured -> carry transition moved=" .. tostring(moved)) end)
        end
        return
    end

    if stage == "native-grip-settle" then
        -- BringStart owns root motion as well as the procedural grip. Suppress only
        -- that root drift while the live node settles.
        local anchor_pos, anchor_rot = S.route3_predation_grip_anchor_pos, S.route3_predation_grip_anchor_rot
        if anchor_pos then
            pcall(function() set_transform(go, anchor_pos, anchor_rot) end)
            pcall(function() set_character_transform(ch, anchor_pos, anchor_rot) end)
        end
    end

    if (stage == "freeze-settle" or stage == "native-grip-settle")
        and elapsed >= (tonumber(C.route3_predation_carry_freeze_settle) or 0.15) then
        -- Let the Bring node establish its grip pose (ran live for the settle window), now FREEZE it so
        -- its flight movement code can't run -> stable grip held, no teleport. Then hand to the rider.
        pcall(function() set_think_stop(ch, true) end)
        pcall(function() set_motion_fsm_puppet(go, true) end)
        S.route3_carry_frozen = true   -- tracked so the ground path tears the freeze down on landing
        S.route3_predation_native_grip_held = stage == "native-grip-settle"
        S.route3_predation_grip_anchor_pos = nil
        S.route3_predation_grip_anchor_rot = nil
        griffin_predation_rebase_drive()
        pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
        S.route3_predation_replay_stage = "handed-off"
        S.route3_predation_replay_stage_at = now
        S.route3_predation_native_until = 0.0
        S.route3_predation_wake_until = 0.0
        S.route3_predation_probe_until = 0.0
        S.route3_predation_mode = nil
        S.base_owner = nil
        S.audition_until_clock = 0.0
        S.route3_flap_phase = nil
        S.route3_soar_dir_clip = nil
        S.last_root_motion_state = nil
        S.last_root_motion_key = nil
        S.route3_predation_status = S.route3_predation_native_grip_held
            and "native ox carry: procedural BringStart grip held"
            or "native ox carry: FROZEN grip handed to rider"
        S.route3_predation_grip_status = S.route3_predation_native_grip_held
            and "holding native procedural BringStart grip (staged release armed)"
            or S.route3_predation_grip_status
        pcall(function() griffin_grab_crash_mark("stage: FROZEN handoff native="
            .. tostring(S.route3_predation_native_grip_held)) end)
        return
    end

    if stage == "landing-loop" and elapsed >= 0.40 then
        pcall(function() griffin_predation_apply_carry_motion(c253) end)
        pcall(function() request_griffin_action(tostring(C.route3_predation_carry_action or "Ch253CarryCatchToFlight"), 0) end)
        local moved = false
        pcall(function() moved = set_griffin_fsm_node_silent(tostring(C.route3_predation_carry_node or "Catch.Ch253CarryCatchToFlight"), 0) == true end)
        S.route3_predation_replay_stage = moved and "to-flight" or "landing-loop"
        S.route3_predation_replay_stage_at = now
        return
    end

    if stage == "to-flight" and elapsed >= 0.85 then
        pcall(function() griffin_grab_crash_mark("stage: to-flight -> flight step") end)
        pcall(function() griffin_predation_apply_carry_motion(c253) end)
        if tostring(C.route3_predation_carry_stage or "carry") ~= "full" then
            -- LEAN (default "carry"): CarryCatchToFlight already engaged the carry + moved her
            -- off the success pose; SKIP the wild FlightPathTraceTarget path-trace node (the
            -- actual flight-FSM corruptor). Jump straight to the rider handoff (flight stage).
            S.route3_predation_replay_stage = "flight"
            S.route3_predation_replay_stage_at = now - 10.0   -- force the flight-stage handoff to fire immediately (its elapsed>=0.35 check)
            return
        end
        pcall(function() request_griffin_action("FlightPathTraceTarget", 0) end)
        local moved = false
        pcall(function() moved = set_griffin_fsm_node_silent("Fly.Flight.FlightPathTraceTarget", 0) == true end)
        S.route3_predation_replay_stage = moved and "flight" or "to-flight"
        S.route3_predation_replay_stage_at = now
        return
    end

    if stage == "flight" and elapsed >= 0.35 then
        pcall(function() griffin_grab_crash_mark("stage: rider HANDOFF") end)
        -- Aurora proved the native constraint survives Stop native lease. Adopt
        -- the current transform, restore ridden flight, and release only the
        -- probe's ownership—not the Catch/Caught controllers.
        griffin_predation_rebase_drive()
        pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
        S.route3_predation_replay_stage = "handed-off"
        S.route3_predation_replay_stage_at = now
        S.route3_predation_native_until = 0.0
        S.route3_predation_wake_until = 0.0
        S.route3_predation_probe_until = 0.0
        S.route3_predation_mode = nil
        S.base_owner = nil
        S.audition_until_clock = 0.0
        -- Force the flight visual system to paint a fresh base/wing state instead
        -- of trusting the phase cached before the catch dive began.
        S.route3_flap_phase = nil
        S.route3_soar_dir_clip = nil
        S.last_root_motion_state = nil
        S.last_root_motion_key = nil
        -- Keep the captured FlightPathTraceTarget motion on the base layer.  The
        -- next ridden-flight tick replaces its stale terminal pose with flight
        -- motion while the retained native constraint continues independently.
        S.route3_predation_status = "WILD CATCH ATTACHED -> native carry flight handed to rider"
    end
end

function griffin_predation_leave_native_grip_before_release(ch, go)
    if S.route3_predation_native_grip_held ~= true then return true end
    if not (ch and go) then return false end

    -- Critical ordering: leave the procedural hunt node while the ox is STILL a
    -- valid native Caught target. The earlier capture experiment proved this exact
    -- BringStart -> CarryCatchToFlight transition is safe while Catch/Caught remain
    -- intact. Only the caller may end those controllers afterwards. Waking and
    -- releasing directly from BringStart is what advanced the hunt into slam/circle.
    pcall(function() set_motion_fsm_puppet(go, false) end)
    pcall(function() set_think_stop(ch, false) end)
    pcall(function()
        griffin_predation_apply_carry_motion(get_component(go, "app.Ch253000"))
    end)
    pcall(function() request_griffin_action("Ch253CarryCatchToFlight", 0) end)
    local moved = false
    pcall(function()
        moved = set_griffin_fsm_node_silent("Catch.Ch253CarryCatchToFlight", 0) == true
    end)
    if not moved then
        local node = tostring(read_griffin_fsm_node() or "")
        moved = node:find("CarryCatchToFlight", 1, true) ~= nil
    end
    if not moved then
        -- Do not risk the known wake-and-slam failure. Restore the held state and
        -- let the next release press retry rather than dropping from BringStart.
        pcall(function() set_think_stop(ch, true) end)
        pcall(function() set_motion_fsm_puppet(go, true) end)
        S.route3_predation_grip_status = "release blocked: could not leave BringStart safely"
        pcall(function() griffin_grab_crash_mark("release: native grip pre-exit FAILED; re-frozen") end)
        return false
    end
    S.route3_predation_native_grip_held = false
    S.route3_carry_frozen = nil
    S.route3_predation_grip_sample = nil
    S.route3_predation_grip_status = "native grip exited through CarryCatchToFlight; releasing"
    pcall(function() griffin_grab_crash_mark("release: native grip pre-exit moved=" .. tostring(moved)) end)
    return moved
end

function griffin_predation_release_native_catch()
    local ch, go = reacquire_griffin()
    local prey = S.route3_predation_carry_prey or S.companion_target or S.route3_predation_victim
    local cc, caught = nil, nil
    pcall(function() cc = ch and ch:call("get_CatchController") end)
    pcall(function() caught = prey and prey:call("get_CaughtController") end)
    -- Never release straight out of the frozen procedural BringStart node. Move
    -- to the already-proven carry transition first, with Catch/Caught still live.
    if S.route3_predation_native_grip_held == true then
        local ok, safe = pcall(function() return griffin_predation_leave_native_grip_before_release(ch, go) end)
        if not ok or safe ~= true then return false end
    end
    -- Opt out before calling the terminal methods, otherwise the scoped
    -- retention hooks would correctly treat this as another automatic cleanup.
    S.route3_predation_replay_stage = "released"
    S.route3_predation_carry_retention_active = false
    -- Stop the LateUpdate foreleg writer before the native cancel/release actions
    -- evaluate. The next UpdateMotion restores ordinary flight joints naturally.
    S.route3_predation_grip_sample = nil
    S.route3_predation_grip_names = nil
    S.route3_predation_grip_motion_map = nil
    S.route3_predation_native_grip_held = false
    S.route3_predation_grip_capture_done = false
    S.route3_predation_grip_apply_hits = 0
    S.route3_predation_grip_anchor_pos = nil
    S.route3_predation_grip_anchor_rot = nil
    S.route3_predation_grip_motion_hits = 0
    S.route3_predation_grip_late_hits = 0
    S.route3_predation_grip_frame_hits = 0
    S.route3_predation_grip_status = "released"
    pcall(function() cc:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
    pcall(function() cc:call("set_IsContinue(System.Boolean)", false) end)
    pcall(function() cc:call("abort(System.Boolean)", true) end)
    pcall(function() caught:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
    pcall(function() caught:call("set_IsContinue(System.Boolean)", false) end)
    pcall(function() caught:call("set_IsDisableEscape(System.Boolean)", false) end)
    pcall(function() caught:call("abortDirect") end)
    pcall(function()
        local c253 = go and get_component(go, "app.Ch253000")
        if c253 then
            c253:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 0)
            c253:call("set_IsAirCatch(System.Boolean)", false)
            c253:call("set_OxCatchSetCarryedMotion(System.Boolean)", false)
            c253:call("set_MotinoLayerActionBodyName(System.String)", "Default")
        end
    end)
    pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
    pcall(function() griffin_predation_exit_cleanup(ch, go) end)
    -- re-freeze the puppet ONLY on the ground and AFTER cleanup; freezing first
    -- latched the grip pose at the current frame (Fable dx 2026-07-11).
    pcall(function() if go and S.airborne ~= true then set_motion_fsm_puppet(go, C.puppet_motion_fsm == true) end end)
    S.route3_predation_victim = nil
    S.route3_predation_carry_prey = nil
    S.route3_struggle_tries = 0
    S.route3_struggle_pushed = false
    S.route3_predation_status = "native catch released"
    return true
end

function route3_predation_probe_tick()
    -- during the probe window: park OUR painters (the native catch owns the anim) + live FSM
    -- readout; at expiry hand flight back
    local untilc = tonumber(S.route3_predation_probe_until) or 0.0
    if S.route3_predation_capture_pending then
        local capture = S.route3_predation_capture_pending
        S.route3_predation_capture_pending = nil
        pcall(function() griffin_predation_dump_transaction(capture) end)
    end
    if untilc <= 0.0 then return end
    local now = os.clock()

    if now < untilc then
        S.audition_until_clock = now + 0.3
        S.base_owner = { name = "predation", until_clock = now + 1.0 }
        pcall(function() read_griffin_fsm_node() end)
        S.route3_predation_fsm = "fsm=" .. tostring(S.last_fsm_node or "?")

        if S.route3_predation_mode == "native" then
            pcall(function() griffin_predation_replay_continue_tick(now) end)
            if S.route3_predation_mode ~= "native" then return end
            if S.route3_predation_target_lock_active == true then
                pcall(function() griffin_predation_lock_wild_target() end)
            end
            local sample = nil
            if now - (tonumber(S.route3_predation_tape_last) or 0.0) >= 0.125 then
                S.route3_predation_tape_last = now
                sample = griffin_predation_live_sample()
                local tape = S.route3_predation_tape or {}
                tape[#tape + 1] = { t = now, event = "sample", state = sample }
                while #tape > 320 do table.remove(tape, 1) end
                S.route3_predation_tape = tape

                -- Once either controller is genuinely active, keep the native
                -- lease alive for as long as the carry exists. It expires two
                -- seconds after release instead of interrupting a successful grip.
                if sample.catcher_active == "true" or sample.caught_active == "true" then
                    local extended = now + 2.0
                    S.route3_predation_probe_until = math.max(tonumber(S.route3_predation_probe_until) or 0.0, extended)
                    S.route3_predation_wake_until = math.max(tonumber(S.route3_predation_wake_until) or 0.0, extended)
                    S.route3_predation_native_until = math.max(tonumber(S.route3_predation_native_until) or 0.0, extended)
                    untilc = tonumber(S.route3_predation_probe_until) or untilc
                end
            end

            -- Give updateCatch/AI half a second to request its own action. Only
            -- then use the hash it exposed, and only if no catch/swoop action
            -- has appeared. This stays on ActionManager's real entry path and
            -- never forces MotionFsm2 directly.
            if S.route3_predation_hash_fallback_active == true
                and S.route3_predation_hash_requested ~= true
                and now >= (tonumber(S.route3_predation_hash_request_at) or math.huge) then
                S.route3_predation_hash_requested = true
                local current = tostring(S.last_fsm_node or ""):lower()
                if current:find("catch", 1, true) or current:find("swoop", 1, true) then
                    S.route3_predation_hash_result = "native action already entered"
                else
                    local hash = math.floor(tonumber(S.route3_predation_native_hash) or 0)
                    if hash <= 0 then
                        pcall(function()
                            local ch, go = reacquire_griffin()
                            local ch253 = go and get_component(go, "app.Ch253000")
                            hash = math.floor(tonumber(ch253 and ch253:call("getCatchStartAction")) or 0)
                            S.route3_predation_native_hash = hash
                        end)
                    end
                    if hash > 0 then
                        local ch = reacquire_griffin()
                        local ok, err = pcall(function()
                            local am = ch and ch:call("get_ActionManager")
                            am:call("requestActionByHash(System.UInt32, System.UInt32, System.Boolean)", hash, 0, false)
                            pcall(function() am:call("updateAction(System.UInt32)", 0) end)
                        end)
                        S.route3_predation_hash_result = ok and ("requested " .. tostring(hash)) or ("FAILED " .. tostring(err))
                        S.route3_predation_tape[#S.route3_predation_tape + 1] = {
                            t = now, event = "hash-fallback", hash = hash, ok = ok,
                            error = ok and "" or tostring(err), state = griffin_predation_live_sample(),
                        }
                    else
                        S.route3_predation_hash_result = "no native hash exposed"
                    end
                end
            end

            if now - (tonumber(S.route3_predation_tape_dump_last) or 0.0) >= 1.0 then
                S.route3_predation_tape_dump_last = now
                pcall(function()
                    json.dump_file(MOD .. "_predation_tape.json", {
                        time = os.date("%Y-%m-%d %H:%M:%S"), mode = "native",
                        status = S.route3_predation_status, hash_result = S.route3_predation_hash_result,
                        samples = S.route3_predation_tape or {},
                    })
                end)
            end
        end

        -- AUTO-CHAIN: contact happened (claim check fired) -> force the ToBring SUCCESS node,
        -- whose action code performs the actual attach (the native sequence we're mimicking)
        -- Never contaminate the clean native-control trial with this legacy forced path.
        if S.route3_predation_mode ~= "native"
            and (tonumber(S.route3_predation_claim_seen) or 0) > 0 and S.route3_predation_bring_fired ~= true then
            S.route3_predation_bring_fired = true
            local bnode = tostring(C.route3_predation_success_node or ""):gsub("%s+", "")
            if bnode ~= "" and griffin_fsm_node_exists(bnode) then
                local bleaf = bnode:match("([^%.]+)$") or bnode
                pcall(function() request_griffin_action(bleaf, 4) end)
                pcall(function() request_griffin_action(bleaf, 0) end)
                pcall(function() set_griffin_fsm_node_silent(bnode, 0) end)
                S.route3_predation_status = "claim! -> chained " .. bnode
            end
        end
    else
        local was_native = S.route3_predation_mode == "native"
        if was_native then
            local final = griffin_predation_live_sample()
            S.route3_predation_tape = S.route3_predation_tape or {}
            S.route3_predation_tape[#S.route3_predation_tape + 1] = { t = now, event = "lease-expired", state = final }
            pcall(function()
                json.dump_file(MOD .. "_predation_tape.json", {
                    time = os.date("%Y-%m-%d %H:%M:%S"), mode = "native", final = final,
                    status = S.route3_predation_status, hash_result = S.route3_predation_hash_result,
                    samples = S.route3_predation_tape,
                })
            end)
            griffin_predation_rebase_drive()
            S.route3_predation_native_until = 0.0
            S.route3_predation_wake_until = 0.0
            S.route3_predation_status = string.format(
                "NATIVE ended | startCatch=%d caughtStart=%d claim=%d | tape dumped",
                tonumber(S.route3_predation_startcatch_seen) or 0,
                tonumber(S.route3_predation_caught_start_seen) or 0,
                tonumber(S.route3_predation_claim_seen) or 0)
        end
        S.route3_predation_probe_until = 0.0
        S.route3_predation_mode = nil
        S.route3_predation_target_lock_active = false
        S.route3_predation_action_feed_active = false
        S.route3_predation_gate_override_active = false
        S.route3_predation_promote_attack_target_active = false
        S.base_owner = nil
        S.audition_until_clock = 0.0
        if S.mounted == true and S.airborne == true then
            pcall(function() route3_restore_flight_base() end)
        end
    end
end

-- ===== AERIAL WING GUST: hover blast -- the gale anim + the same blowback/damage, from the air =====
function griffin_gustair_active() return type(S.route3_gustair) == "table" end

-- Re-assert the calm-lock after ANY attack/action fired via requestActionCore (WingThunder gust,
-- rise/dive nodes). Those WAKE her combat state and nothing clears it -> she FLOATS above ground on
-- landing/dismount (Aurora). Fire ONCE at action end. route3_ally_join_party = the proven combat-state
-- killer (CharacterKind=2 + unregistBossGauge + clear hate); harmless if she's already calm.
function griffin_recalm_after_attack()
    pcall(function() clear_griffin_hate() end)
    pcall(function() clear_griffin_targets() end)
    pcall(function() route3_ally_join_party() end)
end

function route3_gustair_end(reason)
    S.route3_gustair = nil
    S.audition_until_clock = 0.0
    -- ⛔ keep the painter lease while the node still runs (2026-08-05, lightning double-flap):
    -- dropping base_owner here freed the flap module to re-establish OVER the live node for the
    -- tail of the animation -- the out-of-time beat. While the lockout holds, the lease stays;
    -- the exit pump's classic recovery replaces it at the retire.
    local still = false
    pcall(function()
        still = griffin_node_lockout_active() == true and tostring(S.route3_node_lock_src or "") == "gust"
    end)
    if still then
        S.base_owner = { name = "gustair", until_clock = os.clock() + 2.5 }   -- safety-capped lease
    else
        S.base_owner = nil
    end
    -- ⭐ 2026-08-05 (Aurora: "not sure the lightning did the full animation"): this end fires on a
    -- hard 2.5s timer, and its repaint+recalm cut the node's animation dead right there. Now that
    -- the gust arms the NODE LOCKOUT, defer to it: while the lockout still holds the attack node,
    -- the animation is NOT done -- the exit pump repaints flight and re-calms at the actual
    -- retire, which is the correct beat. Only clean up here if the lockout has already let go.
    local locked = false
    pcall(function()
        locked = griffin_node_lockout_active() == true
            and tostring(S.route3_node_lock_src or "") == "gust"
    end)
    if not locked then
        -- return the base layer to the flight glide (the swoop/dogfight's proven restore) --
        -- but NEVER when she's no longer ours (dismount mid-attack = native FSM waking = AV)
        if S.mounted == true and S.airborne == true then
            pcall(function() route3_restore_flight_base() end)
        end
        pcall(griffin_recalm_after_attack)   -- WingThunder woke her combat state -> re-calm or she floats
    end
    S.route3_gust_status = "air gust=" .. tostring(reason or "done")
end

function route3_gustair_tick()
    -- ONE press = ONE native gale: fire her real FSM attack node (the wake-code's proven
    -- trigger trio -- "she plays her real gale attack animation, we only decide WHEN"),
    -- add our blowback+damage at the impact moment, then hand flight back.
    if C.route3_gustair_enabled == false then return end
    local st = S.route3_gustair
    local now = os.clock()
    if st and (S.mounted ~= true or S.airborne ~= true) then route3_gustair_end("grounded"); return end
    local down = false
    local names = tostring(C.route3_gustair_buttons or ""):gsub("%s+", "")
    if names ~= "" then pcall(function() down = raw_gamepad_button_down(names) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_gust_key) or 0)   -- same key as the ground gust: H grounded = gust, H airborne = air gale
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down and S.route3_gustair_btn ~= true and not st and S.mounted == true and S.airborne == true then
        -- never during another special
        local cross = false   -- ⛔ same one-node-at-a-time law as the dogfight (05-08 crash tape)
        pcall(function() cross = griffin_node_lockout_active() == true end)
        if not (griffin_grab_active() or griffin_divebomb_active()
            or griffin_gust_active() or griffin_gatk_active()
            or griffin_dogfight_active() or cross or S.route3_node_exit_until
            or S.route3_live_window or now < (tonumber(S.route3_attack_recover_until) or 0.0)) then
            local node = tostring(C.route3_gustair_node or "Fly.HoverAttack"):gsub("%s+", "")
            -- TYPO GUARD: refuse unknown node names (native crash otherwise)
            if node == "" or not griffin_fsm_node_exists(node) then
                S.route3_gust_status = "air gust node NOT FOUND: " .. node
                S.route3_gustair_btn = down
                return
            end
            local leaf = node:match("([^%.]+)$") or node
            -- ⭐ SAME KIT AS THE GALE DIVE (2026-08-05, Aurora: the lightning "only does a second
            -- of animation"). The gust fired its node BARE -- no fc-lift, no lockout, no recalm
            -- delay -- so the calm-lock / painters could cut the attack short. Arm the proven
            -- LoopTheLoop machinery first, exactly like route3_rise_start_clip and the gale do;
            -- the exit pump then retires the node and repaints flight at the correct beat.
            pcall(function() route3_rise_fc_lift_begin(1.0, 3.0, now, leaf) end)
            pcall(function() griffin_node_lockout_begin(leaf, now, "gust") end)   -- NOT "rise": no cinematic camera
            S.route3_rise_recalm_at = now + 3.0   -- hold the calm-lock off until the attack is done
            pcall(function() request_griffin_action(leaf, 4) end)
            pcall(function() request_griffin_action(leaf, 0) end)
            -- ⛔ setCurrentNode STOMP is OFF by default: it sets a RAW FSM node the AI reverts -> bind
            -- pose / T-pose (Aurora's gale result). requestActionCore (priority 10, above) is the path
            -- the AI honors AND runs the action's onStart (loads the clip). Only flip use_setnode on if
            -- a node refuses to enter without the nudge.
            if C.route3_gustair_use_setnode == true then
                pcall(function() set_griffin_fsm_node_silent(node, 0) end)
            end
            st = {
                t0 = now,
                blow_at = now + math.max(0.05, tonumber(C.route3_gustair_impact) or 1.2),
                end_at = now + math.max(0.5, tonumber(C.route3_gustair_secs) or 2.5),
            }
            S.route3_gustair = st
            -- park OUR painters (flap/idle) so they can't stomp the native gale anim;
            -- no clip painting and no re-assert here -- the FSM owns the animation
            S.base_owner = { name = "gustair", until_clock = now + 1.0 }
            S.audition_until_clock = now + 0.5
            status(tostring(C.route3_griffin_name or "Griffin") .. " unleashes a gale!")
        end
    end
    S.route3_gustair_btn = down
    if not st then return end
    S.audition_until_clock = now + 0.3
    S.base_owner = { name = "gustair", until_clock = now + 1.0 }
    -- live FSM readout so a failed node-take is visible in the panel
    pcall(function() read_griffin_fsm_node() end)
    S.route3_gust_status = "air gale  fsm=" .. tostring(S.last_fsm_node or "?")
    if st.blow_at and now >= st.blow_at then
        st.blow_at = nil
        -- The wind half of this move is vestigial: the aerial gale became the thunder ring, and
        -- its damage now lands at the bolts (griffin_fire_thunder_strikes). What remains here is
        -- the ground gust's own blast, kept only for anyone who wants both -- so it stays silent
        -- at zero instead of firing a token pulse. route3_ground_aoe_damage clamps radius and
        -- damage up to 1, so calling it unguarded meant "0 damage" was really 1 damage in a 1m
        -- disc around HER, several metres inside the ring the player is aiming with.
        local r = tonumber(C.route3_gustair_radius) or 0.0
        local wind_dmg = tonumber(C.route3_gustair_damage) or 0.0
        if r > 0.0 then
            if C.route3_gust_blow_enabled ~= false then route3_gust_finale_blow(r) end
            if wind_dmg > 0.0 then route3_ground_aoe_damage(r, wind_dmg, {}) end
        end
        pcall(function() griffin_fire_thunder_efx() end)      -- optional wing crackle efx (if a path is set)
        pcall(function() griffin_fire_thunder_strikes() end)  -- the real thunder-strike shell ring (if enabled)
    end
    if now >= (tonumber(st.end_at) or 0.0) then route3_gustair_end("done") end
end

-- ⭐ THUNDER/LIGHTNING VFX (2026-07-19): firing the wing-thunder node via requestActionCore plays the
-- MOTION but not the attack's efx, so we spawn the lightning ourselves -- the PROVEN sand-engine route
-- (EffectResource -> holder -> own GO + EffectPlayer + AutoStart, reaped by a timer; mirrors
-- IrisTaming.lua fx9 @4533). Path is set via the panel AFTER capturing it with IrisTaming's EFX TAPE
-- while firing the attack (the exact ch53/000 thunder path isn't in any dump -- must be captured).
function griffin_spawn_efx(path, wx, wy, wz, scale, life)
    path = tostring(path or "")
    if path == "" then return false end
    local ok = false
    pcall(function()
        local res = sdk.create_resource("via.effect.EffectResource", path)
        if not res then return end
        res = res:add_ref()
        local hold = res:create_holder("via.effect.EffectResourceHolder"):add_ref()
        local ego = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "IrisThunderFx")
        if not ego then return end
        ego = ego:add_ref()
        local etf = ego:call("get_Transform")
        etf:call("set_Position", Vector3f.new(tonumber(wx) or 0.0, tonumber(wy) or 0.0, tonumber(wz) or 0.0))
        local s = tonumber(scale) or 1.0
        if s ~= 1.0 then pcall(function() etf:call("set_LocalScale", Vector3f.new(s, s, s)) end) end
        local ep = ego:call("createComponent(System.Type)", sdk.typeof("via.effect.EffectPlayer"))
        ep:call("set_Resource", hold)
        ep:call("set_AutoStart", true)
        S.griffin_efx_live = S.griffin_efx_live or {}
        S.griffin_efx_live[#S.griffin_efx_live + 1] = { go = ego, held = { res, hold }, until_t = os.clock() + (tonumber(life) or 1.8) }
        ok = true
    end)
    return ok
end

function griffin_efx_reaper_tick()
    -- also the shared post-action RE-CALM timer (rise/dive nodes schedule it; runs even after dismount)
    local rc = tonumber(S.route3_rise_recalm_at) or 0.0
    if rc > 0.0 and os.clock() >= rc then
        S.route3_rise_recalm_at = 0.0
        pcall(griffin_recalm_after_attack)
    end
    -- FLOAT DIAG (post-L2 float debug): sample her FSM node + height-above-ground so we can pinpoint
    -- exactly what she's stuck in when she floats. Throttled; shown in the Wing gust panel.
    if os.clock() >= (tonumber(S.route3_float_diag_at) or 0.0) then
        S.route3_float_diag_at = os.clock() + 0.3
        pcall(function()
            local _, ggo = reacquire_griffin()
            if not ggo then S.route3_float_diag = "(no griffin)"; return end
            if S.airborne == true then S.route3_float_diag = "(airborne)"; return end
            local rp = transform_render_pos(ggo) or transform_pos(ggo)
            local h = "?"
            if rp then
                local hit = route3_cast_ground_below(tonumber(rp.x) or 0.0, tonumber(rp.y) or 0.0, tonumber(rp.z) or 0.0, 5.0, 120.0)
                if hit and tonumber(hit.y) then h = string.format("%.2f", (tonumber(rp.y) or 0.0) - tonumber(hit.y)) end
            end
            pcall(function() read_griffin_fsm_node() end)
            local node = tostring(S.last_fsm_node or "")
            -- ⭐ UN-STICK: the WingThunder (and gale/flight) ATTACK node does NOT self-exit when fired via
            -- requestActionCore -> she stays in it = floats ~0.8m even dismounted (Aurora FLOAT DIAG). While
            -- NOT in an active gust window, force her into the neutral GROUNDED node (Locomotion.Wait) so
            -- she drops to the ground. Fires each 0.3s until she's out (then the check stops matching).
            -- GENERAL: grounded but stuck in ANY air node (Fly.*) or attack node = stuck (covers the
            -- WingThunder gust AND any rise/dive node like Fly.Hovering.HoverUpward). A grounded griffin
            -- belongs in Locomotion.* -- a Fly./Attack node while grounded is always a stuck-node float.
            if not (griffin_gustair_active() or griffin_gatk_active() or griffin_grab_active())
                and (node:find("^Fly%.") or node:find("Attack", 1, true) or node:find("SubUnique", 1, true)) then
                local nfull = tostring(C.native_climb_calm_fsm_node or "Locomotion.Wait")
                local nleaf = nfull:match("([^%.]+)$") or "Wait"
                pcall(function() request_griffin_action(nleaf, 4) end)
                pcall(function() request_griffin_action(nleaf, 0) end)
                pcall(function() set_griffin_fsm_node_silent(nfull, 0) end)  -- exiting to a grounded idle is safe to force
                S.route3_float_unstick = "un-stick -> " .. nleaf
            end
            local think = "?"
            pcall(function() local ch = reacquire_griffin(); think = tostring(ch and (ch:call("get_IsThinkStop") or ch:call("get_ThinkStop"))) end)
            S.route3_float_diag = string.format("fsm=%s  height=%s  think=%s  %s",
                tostring(S.last_fsm_node or "?"), h, think, tostring(S.route3_float_unstick or ""))
        end)
    end
    local live = S.griffin_efx_live
    if type(live) ~= "table" or #live == 0 then return end
    local now = os.clock()
    for i = #live, 1, -1 do
        local e = live[i]
        if e and now >= (tonumber(e.until_t) or 0.0) then
            pcall(function() if e.go then e.go:call("destroy", e.go) end end)
            table.remove(live, i)
        end
    end
end

-- fire the thunder efx at the griffin's VISIBLE (render) position, or optional comma-list of wing joints
function griffin_fire_thunder_efx()
    if C.route3_thunder_efx_enabled ~= true then return end
    local path = tostring(C.route3_thunder_efx or "")
    if path == "" then S.route3_thunder_efx_status = "no efx path set"; return end
    local _, ggo = reacquire_griffin()
    if not ggo then return end
    local scale = tonumber(C.route3_thunder_efx_scale) or 1.0
    local life = tonumber(C.route3_thunder_efx_life) or 1.8
    local joints = tostring(C.route3_thunder_efx_joints or "")
    local fired = 0
    if joints ~= "" then
        local gtf = ggo:call("get_Transform")
        for jn in joints:gmatch("[^,%s]+") do
            pcall(function()
                local j = gtf and gtf:call("getJointByName", jn)
                local wp = j and j:call("get_Position")
                if wp and griffin_spawn_efx(path, wp.x, wp.y, wp.z, scale, life) then fired = fired + 1 end
            end)
        end
    end
    if fired == 0 then
        local gp = transform_render_pos(ggo) or transform_pos(ggo)
        if gp and griffin_spawn_efx(path, gp.x, gp.y, gp.z, scale, life) then fired = 1 end
    end
    S.route3_thunder_efx_status = string.format("fired %d emitter(s) @ %.1f", fired, os.clock())
end

-- ⭐⭐ THUNDER STRIKES (2026-07-19): the wing-thunder SPECIAL = ground telegraph circles -> lightning
-- bolts (Aurora). Those are SHELLS (app.ShellManager), NOT the wing efx -- requestActionCore plays only
-- the motion. We cast the griffin's OWN levin (lightning) shells in a ring ourselves, the base-game way
-- (proven by the Bestiary mod's Griffin moveset -- reimplemented inline, NOT a dependency). Each shell
-- carries its own telegraph (omentime) + bolt + hit. ch253000levinspell shellID 3 = ground-spot bolt.
function griffin_cast_shell(path, shellID, wx, wy, wz, owner)
    local ok = false
    pcall(function()
        local SM = sdk.get_managed_singleton("app.ShellManager")
        if not SM then return end
        if not S.route3_shell_method then
            S.route3_shell_method = sdk.find_type_definition("app.ShellManager"):get_method(
                "requestCreateShell(via.GameObject, via.vec3, via.Quaternion, app.ShellRequest.ShellCreateInfo, app.ShellParamData, app.ShellRequest.EventCreateShellSuccess, app.ShellRequest.EventBeforeShellInstantiate)")
        end
        local method = S.route3_shell_method
        if not method then return end
        S.route3_shell_udata = S.route3_shell_udata or {}
        local udata = S.route3_shell_udata[path]
        if not udata then
            udata = sdk.create_userdata("app.ShellParamData", tostring(path))
            if udata then udata = udata:add_ref(); S.route3_shell_udata[path] = udata end
        end
        if not udata then return end
        local hash = nil
        pcall(function() hash = udata.ShellParams._items[math.floor(shellID)]._ShellParamIdHash end)
        if hash == nil then return end
        local info = sdk.create_instance("app.ShellRequest.ShellCreateInfo"):add_ref()
        info.ShellParamIdHash = hash
        method:call(SM, owner, make_vec3(wx, wy, wz), make_quat_yaw(0.0), info, udata, nil, nil)
        ok = true
    end)
    return ok
end

function griffin_fire_thunder_strikes()
    if C.route3_thunder_shell_enabled ~= true then return end
    local path = tostring(C.route3_thunder_shell_path or "")
    if path == "" then S.route3_thunder_shell_status = "no shell path"; return end
    local _, ggo = reacquire_griffin()
    if not ggo then return end
    local shellID = math.floor(tonumber(C.route3_thunder_shell_id) or 3)
    local count = math.max(1, math.floor(tonumber(C.route3_thunder_shell_count) or 8))
    local radius = tonumber(C.route3_thunder_shell_radius) or 4.0
    local gp = transform_render_pos(ggo) or transform_pos(ggo)
    if not gp then return end
    local cx, cy, cz = tonumber(gp.x) or 0.0, tonumber(gp.y) or 0.0, tonumber(gp.z) or 0.0
    -- ⭐ HOMING (2026-08-05, Aurora): if the target marker has an enemy locked, drop the ring ON
    -- THEM instead of under the griffin. Same preview lock the dogfight marker paints -- one
    -- lock, two weapons. 60m sanity ceiling so a stale lock can't fire across the map.
    if C.route3_thunder_home ~= false then
        pcall(function()
            local foe = S.route3_dogfight_preview
            local fgo = foe and char_go(foe)
            if fgo and not is_dead(foe) then
                local fp = transform_render_pos(fgo) or transform_pos(fgo)
                if fp then
                    local hdx, hdz = (tonumber(fp.x) or cx) - cx, (tonumber(fp.z) or cz) - cz
                    if (hdx * hdx + hdz * hdz) <= 3600.0 then
                        cx, cy, cz = tonumber(fp.x) or cx, tonumber(fp.y) or cy, tonumber(fp.z) or cz
                        S.route3_thunder_shell_status = "homing on " .. tostring(go_name(fgo) or "?")
                    end
                end
            end
        end)
    end
    pcall(function() local hit = route3_cast_ground_below(cx, cy, cz, 5.0, 120.0); if hit and tonumber(hit.y) then cy = tonumber(hit.y) end end)
    local yaw = yaw_from_transform(ggo) or S.heading_yaw or 0.0
    local fx, fz, rx, rz = math.sin(yaw), math.cos(yaw), math.cos(yaw), -math.sin(yaw)
    -- Damage lands AT THE BOLTS, not around her. The aerial gale became this thunder ring, but its
    -- damage was still the ground gust's -- a disc centred on the griffin, several metres inside
    -- the lightning the player is actually aiming with. One shared hitset across the ring so an
    -- enemy standing between two bolts is hit once, not once per bolt.
    local strike_dmg = tonumber(C.route3_thunder_strike_damage) or 0.0
    local strike_r = math.max(0.5, tonumber(C.route3_thunder_strike_radius) or 3.0)
    local hitset = strike_dmg > 0.0 and {} or nil
    local fired = 0
    local hit_n = 0
    if hitset then S.route3_swoop_last_dmg = nil end   -- so the black box can't show a STALE verdict
    -- ⛔⛔ SPACE REBASE (2026-08-07, black box 22:11: HIT=0, "helper never ran", centre x=-11 --
    -- RENDER coords. The ring is placed in RENDER space (right for spawning bolts) but
    -- route3_ground_aoe_damage compares against UNIVERSAL enemy positions -- the two differ by
    -- the streaming-cell offset, so the sweep has measured a distance between two different
    -- coordinate systems since the ring shipped. Same trap as the underground loop camera.
    -- Rebase via the griffin, readable in both spaces -- the offset cancels exactly.)
    local uox, uoy, uoz = 0.0, 0.0, 0.0
    pcall(function()
        local uni, ren = transform_pos(ggo), transform_render_pos(ggo)
        if uni and ren then
            uox = (tonumber(uni.x) or 0.0) - (tonumber(ren.x) or 0.0)
            uoy = (tonumber(uni.y) or 0.0) - (tonumber(ren.y) or 0.0)
            uoz = (tonumber(uni.z) or 0.0) - (tonumber(ren.z) or 0.0)
        end
    end)
    -- (2026-08-07 EVENING REVERT, Aurora: "return it to our blank slate" -- the blowback and
    -- pending-strike experiments are GONE; this is the plain immediate-damage shape the black
    -- box PROVED working at 22:32: hp 3500->3200, HIT=2.)
    for i = 0, count - 1 do
        local a = (2.0 * math.pi / count) * i
        local fo, ro = radius * math.cos(a), radius * math.sin(a)
        local bx, bz = cx + fx * fo + rx * ro, cz + fz * fo + rz * ro
        if griffin_cast_shell(path, shellID, bx, cy, bz, ggo) then fired = fired + 1 end
        if hitset then
            hit_n = hit_n + (route3_ground_aoe_damage(strike_r, strike_dmg, hitset,
                make_position(bx + uox, cy + uoy, bz + uoz)) or 0)
        end
    end
    -- A ring leaves the middle untouched. One extra bolt at the centre closes that hole without
    -- spoiling the ring read that makes the move aimable.
    if C.route3_thunder_shell_centre == true then
        if griffin_cast_shell(path, shellID, cx, cy, cz, ggo) then fired = fired + 1 end
        if hitset then hit_n = hit_n + (route3_ground_aoe_damage(strike_r, strike_dmg, hitset,
            make_position(cx + uox, cy + uoy, cz + uoz)) or 0) end
    end
    -- shell 1 is TARGETED (bolts seek foes away from the ring geometry): one sweep over the
    -- whole ring AREA with the shared hitset catches what the bolts actually struck
    if hitset then
        hit_n = hit_n + (route3_ground_aoe_damage(radius + strike_r, strike_dmg, hitset,
            make_position(cx + uox, cy + uoy, cz + uoz)) or 0)
    end
    -- hit count in the status = the truth-teller: "hit=0" means geometry missed (code RAN);
    -- no status update at all means the cast never fired
    S.route3_thunder_shell_status = string.format("cast %d strikes r=%.1f%s @ %.1f",
        fired, radius, strike_dmg > 0.0 and string.format(" dmg=%.0f/%.1fm HIT=%d", strike_dmg, strike_r, hit_n) or " (shell damage only)",
        os.clock())
    -- ⭐ THUNDER BLACK BOX (2026-08-07, "no damage despite cleanly hitting through lockon"):
    -- one file per cast so the failing link is READABLE -- did the damage config load, did the
    -- homing find the lock, how many foes the sweep touched, and what the damage helper said
    -- about the last one it tried.
    pcall(function()
        json.dump_file(MOD .. "_thunder_diag.json", {
            when = os.date("%H:%M:%S"),
            fired = fired,
            strike_dmg = strike_dmg,
            strike_r = strike_r,
            ring_radius = radius,
            hit_n = hit_n,
            homing_status = tostring(S.route3_thunder_shell_status),
            centre = { x = cx, y = cy, z = cz },
            centre_universal = { x = cx + uox, y = cy + uoy, z = cz + uoz },
            space_offset = { x = uox, y = uoy, z = uoz },
            had_marker_lock = S.route3_dogfight_preview ~= nil,
            last_damage_attempt = tostring(S.route3_swoop_last_dmg or "(helper never ran)"),
        })
    end)
end

-- ===== AIR PRESS: airborne downward wing-slam (SECOND aerial attack) =====
-- The dead "air wing gust" fired an EMPTY FSM node (Fly.HoverAttack has no leaf = no-op). This is the
-- salvage: same blowback+damage, but driven by CLIP REPLAY of the proven-resident bank-50 air-press
-- clips (600 start -> 601 loop -> 602 end) so there's a real animation. Stays airborne (no force-land),
-- so it reads as the opposite of the dive bomb: a stationary radial downdraft slam.
function route3_airpress_tick()
    if C.route3_airpress_enabled == false then return end
    local st = S.route3_airpress
    local now = os.clock()
    if st and (S.mounted ~= true or S.airborne ~= true) then route3_airpress_end("grounded"); return end
    local down = false
    local names = tostring(C.route3_airpress_buttons or ""):gsub("%s+", "")
    if names ~= "" then pcall(function() down = raw_gamepad_button_down(names) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_airpress_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down and S.route3_airpress_btn ~= true and not st and S.mounted == true and S.airborne == true then
        -- never during another special
        if not (griffin_grab_active() or griffin_divebomb_active()
            or griffin_gust_active() or griffin_gatk_active() or griffin_gustair_active()) then
            -- CLAIM base-layer ownership FIRST, then paint AS that owner -- else our own owner gate
            -- (play_griffin_motion) blocks the loop/end clips = "prep plays then nothing" (Aurora).
            S.base_owner = { name = "airpress", until_clock = now + 1.0 }
            S.audition_until_clock = now + 0.5
            local bank = math.floor(tonumber(C.route3_airpress_clip_bank) or 50)
            local sc = math.floor(tonumber(C.route3_airpress_start_clip) or 600)
            if sc >= 0 then pcall(function() play_griffin_motion(sc, bank, true, "airpress") end) end
            local esecs = math.max(0.3, tonumber(C.route3_airpress_end_secs) or 1.3)
            st = {
                t0 = now,
                loop_at = now + math.max(0.0, tonumber(C.route3_airpress_start_secs) or 0.35),
                impact_at = now + math.max(0.05, tonumber(C.route3_airpress_impact) or 0.55),
                endclip_at = now + esecs,
                done_at = now + esecs + 0.4,
                looped = false, blown = false, ended = false,
            }
            S.route3_airpress = st
            status(tostring(C.route3_griffin_name or "Griffin") .. " slams the air!")
        end
    end
    S.route3_airpress_btn = down
    if not st then return end
    S.audition_until_clock = now + 0.3
    S.base_owner = { name = "airpress", until_clock = now + 1.0 }
    pcall(function() route3_flap_clear_overlay() end)   -- kill the flap overlay so the clip doesn't double
    local bank = math.floor(tonumber(C.route3_airpress_clip_bank) or 50)
    if (not st.looped) and now >= (tonumber(st.loop_at) or math.huge) then
        st.looped = true
        local lc = math.floor(tonumber(C.route3_airpress_loop_clip) or 601)
        if lc >= 0 then pcall(function() play_griffin_motion(lc, bank, true, "airpress") end) end
    end
    if (not st.blown) and now >= (tonumber(st.impact_at) or math.huge) then
        st.blown = true
        local r = math.max(1.0, tonumber(C.route3_airpress_radius) or 8.0)
        if C.route3_airpress_blow_enabled ~= false then pcall(function() route3_gust_finale_blow(r) end) end
        pcall(function() route3_ground_aoe_damage(r, tonumber(C.route3_airpress_damage) or 300.0, {}) end)
        S.route3_airpress_status = "air press IMPACT!"
    end
    if (not st.ended) and now >= (tonumber(st.endclip_at) or math.huge) then
        st.ended = true
        local ec = math.floor(tonumber(C.route3_airpress_end_clip) or 602)
        if ec >= 0 then pcall(function() play_griffin_motion(ec, bank, true, "airpress") end) end
    end
    if now >= (tonumber(st.done_at) or 0.0) then route3_airpress_end("done") end
end

-- ===== QUICK-RISE: burst altitude gain on A/cross (or Space) while flying =====
function griffin_grab_crash_mark(s)
    -- GRAB CRASH MONITOR (ox-grab CTD 2026-07-12): json.dump_file flushes, so a hard
    -- native CTD leaves the last step reached in data/..._grab_crash.json ("last" field).
    S.route3_grab_trace = S.route3_grab_trace or {}
    S.route3_grab_trace[#S.route3_grab_trace + 1] = string.format("%.2f %s", os.clock(), tostring(s))
    while #S.route3_grab_trace > 60 do table.remove(S.route3_grab_trace, 1) end
    pcall(function() json.dump_file(MOD .. "_grab_crash.json", { last = tostring(s), time = os.date("%H:%M:%S"), trace = S.route3_grab_trace }) end)
end

-- =====================================================================================
-- JOINT-SPACE PROBE -- is the "rider can never follow" wall actually a wrong-space bug?
-- Samples every frame into MEMORY; writes at most once a second (the per-frame-file
-- mistake cost Aurora a 3fps rise, not repeating it). Read-only: no writes to the game.
-- =====================================================================================
function griffin_jointprobe_resolve(go)
    -- Find a root-ish joint ONCE and remember which name answered, so the readout can say
    -- so. A wrong joint name would read as "no divergence" and falsely re-confirm the wall.
    if S.jointprobe_name and S.jointprobe_name ~= "" then return S.jointprobe_name end
    local tf = nil
    pcall(function() tf = go:call("get_Transform") end)
    if not tf then return nil end
    local candidates = {}
    local pick = tostring(C.route3_jointprobe_joint or "")
    if pick ~= "" then candidates[#candidates + 1] = pick end
    candidates[#candidates + 1] = tostring(C.route3_pitch_joint or "root")
    for _, n in ipairs({ "root", "Root", "COG", "cog", "hip", "Hip", "waist", "Spine_0", "spine_0" }) do
        candidates[#candidates + 1] = n
    end
    for _, n in ipairs(candidates) do
        local j = nil
        pcall(function() j = tf:call("getJointByName", n) end)
        if j then
            S.jointprobe_name = n
            return n
        end
    end
    S.jointprobe_name = nil
    S.jointprobe_status = "no root-ish joint found (tried " .. #candidates .. " names)"
    return nil
end

function griffin_jointprobe_tick()
    if C.route3_jointprobe_enabled ~= true then return false end
    local _, go = reacquire_griffin()
    if not go then S.jointprobe_status = "(no griffin)"; return false end
    local opos = transform_pos(go)
    if not opos then return false end
    local jname = griffin_jointprobe_resolve(go)
    if not jname then return false end

    -- ⛔⛔ TWO RUNS OF GARBAGE (2026-07-26): get_Position alone gave (-512,-128,1024) then
    -- (-640,-128,1152) -- every component a multiple of 128, i.e. some cell/partition value,
    -- NOT a joint. A tonumber() check happily accepted it. So:
    --   1. use managed_call + the SAME ladder the rest of this file uses for joint world pos
    --      (get_Position -> get_WorldPosition -> get_UniversalPosition, per :21041/:24669),
    --   2. demand PLAUSIBILITY -- a root joint sits within a few metres of the object
    --      transform, so anything beyond 50m is a bad getter, not a finding,
    --   3. record WHICH getter answered and what every candidate returned.
    local ox = tonumber(opos.x) or 0.0
    local oy = tonumber(opos.y) or 0.0
    local oz = tonumber(opos.z) or 0.0
    local jpos, jvia = nil, nil
    S.jointprobe_tried = {}
    pcall(function()
        local tf = go:call("get_Transform")
        local j = tf and tf:call("getJointByName", jname)
        if not j then return end
        for _, m in ipairs({ "get_Position", "get_WorldPosition", "get_UniversalPosition",
                             "get_LocalPosition", "get_BaseLocalPosition" }) do
            local v = managed_call(j, m)
            local vx, vy, vz = v and tonumber(v.x), v and tonumber(v.y), v and tonumber(v.z)
            if vx and vy and vz then
                -- ⛔ NO absolute-distance gate. SOLVED 2026-07-26: the joint is reported in
                -- LOCAL SCENE space while transform_pos(go) is UNIVERSAL, so the two differ by
                -- a CONSTANT streaming-cell origin -- measured at (-640,-128,+1152). Two runs
                -- proved it: object Y rose +29.84, joint Y rose +29.90, offset unchanged.
                -- get_WorldMatrix[3] returns the identical value, so get_Position is correct.
                -- Comparing absolutes across two spaces can only ever yield that constant;
                -- the REAL signal is whether the OFFSET moves (see below).
                S.jointprobe_tried[#S.jointprobe_tried + 1] =
                    string.format("%s -> (%.1f %.1f %.1f)", m, vx, vy, vz)
                if not jpos then jpos, jvia = v, m end
            else
                S.jointprobe_tried[#S.jointprobe_tried + 1] = m .. " -> (no value)"
            end
        end
        -- MATRIX ROUTE. get_Position came back in a model/local space (3.4,-116.2,15.6 while
        -- the body sat at 643,11.8,-1136), and there is no get_WorldPosition on a joint. The
        -- world transform of a posed joint lives in its matrix; row 3 is the translation.
        if not jpos then
            for _, mm in ipairs({ "get_WorldMatrix", "getWorldMatrix", "get_Matrix" }) do
                local M = managed_call(j, mm)
                if M then
                    local t = nil
                    pcall(function() t = M[3] end)
                    local tx, ty, tz = t and tonumber(t.x), t and tonumber(t.y), t and tonumber(t.z)
                    if tx and ty and tz then
                        local d = math.sqrt((tx - ox) ^ 2 + (ty - oy) ^ 2 + (tz - oz) ^ 2)
                        S.jointprobe_tried[#S.jointprobe_tried + 1] = string.format(
                            "%s[3] -> (%.1f %.1f %.1f) d=%.1f %s", mm, tx, ty, tz, d,
                            d <= 50.0 and "PLAUSIBLE" or "implausible-REJECTED")
                        if d <= 50.0 and not jpos then jpos, jvia = t, mm .. "[3]" end
                    else
                        S.jointprobe_tried[#S.jointprobe_tried + 1] = mm .. " -> (matrix, no readable row 3)"
                    end
                else
                    S.jointprobe_tried[#S.jointprobe_tried + 1] = mm .. " -> (no value)"
                end
            end
        end
        -- Last resort: tell me what this object ACTUALLY exposes instead of me guessing a 4th time.
        if not jpos and not S.jointprobe_methods then
            S.jointprobe_methods = method_names_matching(j,
                { "pos", "matrix", "world", "universal", "trans", "global" }, 60)
        end
    end)
    if not jpos then
        S.jointprobe_status = "joint '" .. jname .. "': NO getter returned a plausible position. "
            .. table.concat(S.jointprobe_tried, " | ")
        pcall(function() json.dump_file(MOD .. "_jointprobe.json", {
            note = "FAILED: no plausible joint world-position getter. object transform shown for scale.",
            joint = jname,
            object_transform = string.format("(%.2f %.2f %.2f)", ox, oy, oz),
            candidates_tried = S.jointprobe_tried,
            joint_methods_available = S.jointprobe_methods or { "(not enumerated)" },
        }) end)
        return false
    end

    -- THE ACTUAL MEASUREMENT. offset = joint - object. Both spaces are rigid, so while the two
    -- move together this offset is CONSTANT. Baseline it on the first sample and report how far
    -- it DRIFTS: drift ~0 = the joint never moves independently of the object transform, so the
    -- rider (pinned to the object) already follows everything -> the "rider can't follow" wall
    -- is real. drift of metres during a stay-behind clip = the animation displaces her in joint
    -- space only, the rider is pinned to a transform that never moved, and it is FIXABLE.
    local offx = (tonumber(jpos.x) or 0.0) - (tonumber(opos.x) or 0.0)
    local offy = (tonumber(jpos.y) or 0.0) - (tonumber(opos.y) or 0.0)
    local offz = (tonumber(jpos.z) or 0.0) - (tonumber(opos.z) or 0.0)
    if not S.jointprobe_baseoff then
        S.jointprobe_baseoff = { x = offx, y = offy, z = offz }
    end
    local b = S.jointprobe_baseoff
    local dx = offx - b.x
    local dy = offy - b.y
    local dz = offz - b.z
    local dist = math.sqrt(dx * dx + dy * dy + dz * dz)

    -- ⭐⭐ THE SEAT JOINT is the one that matters. ROOT is rigid to the object transform by
    -- construction (drift 0.000 over 1973 samples), and upY never left 1.0 -- so the loop is
    -- NOT in the object transform at all. It is a pose animation in the joints BELOW root,
    -- while route3_air_authority_tick pins the transform to our own straight flight path.
    -- The rider, pinned to that transform, therefore flies straight while she rotates around
    -- him. If Spine_2 swings metres during the loop, THAT is the channel to pin the rider to
    -- -- and the file already has the machinery (route3_rider_joint_anchor_enabled, currently
    -- false). Measured relative to ROOT so the local/universal space offset cancels out.
    pcall(function()
        local tf = go:call("get_Transform")
        local sname = tostring(C.route3_seat_joint or "Spine_2")
        local sj = tf and tf:call("getJointByName", sname)
        local sp = sj and managed_call(sj, "get_Position")
        if sp and tonumber(sp.x) then
            local rx = (tonumber(jpos.x) or 0.0)
            local ry = (tonumber(jpos.y) or 0.0)
            local rz = (tonumber(jpos.z) or 0.0)
            local ex = (tonumber(sp.x) or 0.0) - rx
            local ey = (tonumber(sp.y) or 0.0) - ry
            local ez = (tonumber(sp.z) or 0.0) - rz
            if not S.jointprobe_seatbase then
                S.jointprobe_seatbase = { x = ex, y = ey, z = ez }
            end
            local sb = S.jointprobe_seatbase
            local sd = math.sqrt((ex - sb.x) ^ 2 + (ey - sb.y) ^ 2 + (ez - sb.z) ^ 2)
            S.jointprobe_seat_now = string.format("%s vs root: offset (%.2f %.2f %.2f) SWING=%.3fm",
                sname, ex, ey, ez, sd)
            if sd > (tonumber(S.jointprobe_seat_max) or -1.0) then
                S.jointprobe_seat_max = sd
                S.jointprobe_seat_max_at = S.jointprobe_seat_now .. "  node=" .. tostring(node or "?")
            end
        else
            S.jointprobe_seat_now = "seat joint '" .. sname .. "' not found"
        end
    end)

    -- ⭐ DOES HER OBJECT TRANSFORM ACTUALLY ROTATE? DRIFT=0 proved the transform FOLLOWS the
    -- loop in position, so the rider can be placed correctly -- but the live pin builds the
    -- seat from a FLATTENED yaw-only frame with `up` hardcoded to world +Y, which would leave
    -- the rider hanging at the level-flight seat while she rotates around him (exactly what
    -- Aurora sees: "they stay put and do their own backflip, then reattach at the end").
    -- The fix depends on where the rotation lives:
    --   upDot reaches -1  -> the OBJECT transform really inverts -> seat from her real axes.
    --   upDot stays  ~+1  -> rotation is joint-only; her axes never tilt and using them would
    --                        change nothing -- the seat must come from the JOINT frame instead.
    pcall(function()
        local tf = go:call("get_Transform")
        local ay = tf and tf:call("get_AxisY")
        local uy = ay and tonumber(ay.y)
        if uy then
            S.jointprobe_updot = uy
            if uy < (tonumber(S.jointprobe_updot_min) or 2.0) then
                S.jointprobe_updot_min = uy
            end
        end
    end)

    -- context: WHAT is playing when it diverges is the whole point
    local node, bank, clip = "?", -1, -1
    pcall(function() node = tostring(read_griffin_fsm_node() or "?") end)
    pcall(function()
        local m = go:call("getComponent(System.Type)", sdk.typeof("via.motion.Motion"))
        local l = m and m:call("getLayer", 0)
        if l then
            clip = tonumber(l:call("get_MotionID")) or -1
            pcall(function() bank = tonumber(l:call("get_BankID")) or -1 end)
        end
    end)

    local now = os.clock()
    S.jointprobe_live = string.format("DRIFT=%.3fm (dx%.2f dy%.2f dz%.2f) via=%s joint='%s' L0=%s:%s node=%s",
        dist, dx, dy, dz, tostring(jvia), jname, tostring(bank), tostring(clip), node)
    -- ⛔ skip TRANSITION frames: an empty L0 (0xFFFFFFFF sentinel) or a blank node means the
    -- body is mid-swap and both readings are meaningless. That is what the first two runs
    -- captured as their "peak" -- L0=-1:4294967295 with node="".
    if clip == 4294967295 or node == "" or node == "?" then return true end
    -- keep the WORST sample and what was playing at the time
    if dist > (tonumber(S.jointprobe_max) or -1.0) then
        S.jointprobe_max = dist
        S.jointprobe_max_at = S.jointprobe_live
    end
    S.jointprobe_samples = (tonumber(S.jointprobe_samples) or 0) + 1

    if now - (tonumber(S.jointprobe_last_write) or 0.0) >= 1.0 then
        S.jointprobe_last_write = now
        pcall(function()
            json.dump_file(MOD .. "_jointprobe.json", {
                note = "DRIFT of (rootJoint - objectTransform). The two live in DIFFERENT spaces (joint=local scene, object=universal) so their raw difference is a constant streaming-cell offset; only its DRIFT is meaningful. ~0 = joint never moves independently, rider wall is real. Metres = joint-space displacement the rider is blind to, and FIXABLE.",
                joint = jname,
                -- ⛔ WHO OWNS THE RIDER? The seat-joint fix lives in route3_rider_pin_late,
                -- which returns immediately when the puppet seat is active; the puppet seat's
                -- own seat_pin_apply returns for a pose_only griffin costume. If nothing owns
                -- her, the NATIVE CLIMB does and no lua write reaches her -- which is exactly
                -- "hovers where the motion starts". This decides where the fix has to go.
                rider_owner = (function()
                    local ps_on = false
                    pcall(function() ps_on = iris_puppet_seat_active() == true end)
                    if ps_on then return "IrisPuppetSeat -- route3_rider_pin_late RETURNS, seat-joint fix NEVER RUNS" end
                    if S.route3_rider_puppet_on == true then return "route3_rider_puppet WELD -- we own her, fix belongs in the weld" end
                    if S.native_climb_mount == true then return "NATIVE CLIMB -- no lua write reaches her" end
                    return "route3_rider_pin_late -- the seat-joint fix SHOULD be live"
                end)(),
                rider_follow_flag = tostring(C.route3_rider_follow_seat_joint),
                rider_pin_status = tostring(S.route3_rider_seat_follow or "(never reached my branch)"),
                read_via = tostring(jvia),
                candidates_tried = S.jointprobe_tried,
                samples = S.jointprobe_samples,
                live = S.jointprobe_live,
                max_drift_m = S.jointprobe_max,
                SEAT_JOINT_SWING_m = S.jointprobe_seat_max,
                seat_joint_peak_sample = S.jointprobe_seat_max_at,
                seat_verdict = (tonumber(S.jointprobe_seat_max) or 0.0) > 0.5
                    and "SEAT JOINT MOVES -> pin the rider to it (route3_rider_joint_anchor_enabled) and he rides the loop"
                    or "seat joint rigid too -> the loop is not in the skeleton either; look at mesh/shader or the camera",
                body_upY_now = S.jointprobe_updot,
                body_upY_MIN = S.jointprobe_updot_min,
                rotation_verdict = (tonumber(S.jointprobe_updot_min) or 1.0) < 0.0
                    and "OBJECT TRANSFORM INVERTS -> build the seat from her real axes"
                    or "object transform never tilts -> rotation is JOINT-only, seat must come from the joint frame",
                space_offset_baseline = S.jointprobe_baseoff and string.format("(%.1f %.1f %.1f)", S.jointprobe_baseoff.x, S.jointprobe_baseoff.y, S.jointprobe_baseoff.z) or "?",
                max_sample = S.jointprobe_max_at,
            })
        end)
    end
    return true
end

function griffin_rise_stage(name)
    -- STAGE TAPE (2026-07-26). The 7th CTD reached "f1 air_transform OK" and then died with
    -- frame 2 never arriving -- so the killer is a LATER STAGE of the same frame, past every
    -- call the drive itself instruments. Only writes during an active simple rise/dive, so it
    -- costs nothing the rest of the time.
    if C.route3_rise_trace_frames == false then return end
    local n = os.clock()
    if (tonumber(S.route3_simple_rise_until) or 0.0) <= n
        and (tonumber(S.route3_simple_dive_until) or 0.0) <= n then return end
    pcall(function() griffin_rise_crash_mark("STAGE " .. tostring(name)) end)
end

function griffin_rise_crash_mark(s)
    -- CRASH MONITOR (Aurora 2026-07-12): dump the last quick-rise/dive step each mark. json.dump_file
    -- writes+closes (flushes), so a hard native CTD leaves the step it died on in the file. After a
    -- crash, read data/GriffinRideProbe (IRIS)_rise_crash.json -> the "last" field = the crash step.
    S.route3_rise_trace = S.route3_rise_trace or {}
    S.route3_rise_trace[#S.route3_rise_trace + 1] = string.format("%.2f %s", os.clock(), tostring(s))
    -- 40 was fine when only the drive marked; the safe_run bisect emits ~25 a frame and
    -- would roll the PRESS off the top before the crash line lands. 200 keeps the whole shot.
    while #S.route3_rise_trace > 200 do table.remove(S.route3_rise_trace, 1) end
    pcall(function() json.dump_file(MOD .. "_rise_crash.json", { last = tostring(s), time = os.date("%H:%M:%S"), trace = S.route3_rise_trace }) end)
end

-- =====================================================================================
-- DOWNED/REVIVE -- SLICE 0 PROBE (2026-07-21). Two UNKNOWNS that reshape the build and
-- that no amount of planning resolves, because both are "does this hard-AV?" questions:
--   (1) does disabling app.FlightControl crash -- and if not, what then owns position?
--   (2) does a Damage-tree down node fire safely on a FRIENDLY body?
-- ⛔ LAWS OBSERVED HERE: nothing runs on its own (buttons only); the FC disable ALWAYS
-- auto-restores (a lease left off = an unflyable griffin); the tape is written BEFORE
-- each dangerous call, because json.dump_file flushes and an uncatchable native AV still
-- leaves the step it died on in data/GriffinRideProbe (IRIS)_downed_probe.json ("last").
-- =====================================================================================


function griffin_probe_flight_control()
    local _, go = reacquire_griffin()
    if not go then return nil, nil end
    return get_component(go, "app.FlightControl"), go
end

function griffin_probe_height_above_ground(go)
    -- how far the body actually is off the floor -- a FROZE verdict is meaningless on a
    -- griffin that was already standing on the ground.
    if not go then return nil end
    local up = transform_pos(go)
    local rp = transform_render_pos(go) or up
    if not (up and rp) then return nil end
    local hit = route3_cast_ground_below(rp.x, up.y, rp.z, 3.0, 200.0)
    if not (hit and tonumber(hit.y)) then return nil end
    return (tonumber(up.y) or 0.0) - tonumber(hit.y)
end

function griffin_probe_fc_restore(reason)
    -- the ONE canonical unwind -- idempotent, safe to call from anywhere (window end,
    -- body lost, script reset). Defaults to RE-ENABLING when the original state was
    -- unreadable: an over-eager restore is harmless, a missed one grounds the griffin.
    -- ALSO restores our own transform drive, which the probe suspends (see _fc_start).
    local st = S.downed_probe_fc
    S.downed_probe_fc = nil
    local fc = griffin_probe_flight_control()
    if fc then pcall(function() fc:call("set_Enabled", (st and st.was) ~= false) end) end
    if st and st.drive_saved then
        C.drive_griffin_transform = st.drive_a
        C.native_climb_drive_griffin_transform = st.drive_b
    end
    griffin_downed_probe_mark("FC RESTORE (" .. tostring(reason or "?") .. ")")
end

function griffin_probe_fc_start()
    -- UNKNOWN 1. Disable FC, then sample altitude for a window and classify what happened.
    -- ⛔ ROUND 2 (Aurora's first run read FROZE +0.00m while MOUNTED): our own transform
    -- drive writes the griffin's position every frame, so with the drive live the probe was
    -- measuring OUR pin, not FlightControl. The window now SUSPENDS our drive as well --
    -- that is the honest question anyway ("if we stop driving and FC is off, what happens?").
    if S.downed_probe_fc then status("FC probe already running"); return end
    local fc, go = griffin_probe_flight_control()
    if not fc then status("FC probe: no app.FlightControl on this body"); return end
    local agl = griffin_probe_height_above_ground(go)
    if agl and agl < 3.0 then
        status(string.format("FC probe REFUSED: only %.1fm above ground -- get airborne first", agl))
        return
    end
    local up = transform_pos(go)
    local y0 = up and tonumber(up.y)
    local was = nil
    pcall(function() was = fc:call("get_Enabled") end)
    -- suspend OUR drive for the window (restored by _fc_restore on every exit path)
    local st = { t0 = os.clock(), y0 = y0, agl0 = agl, was = was, samples = {}, next_at = 0.0,
        drive_saved = true, drive_a = C.drive_griffin_transform,
        drive_b = C.native_climb_drive_griffin_transform,
        until_t = os.clock() + (tonumber(C.route3_downed_probe_secs) or 6.0) }
    C.drive_griffin_transform = false
    C.native_climb_drive_griffin_transform = false
    griffin_downed_probe_mark(string.format("FC DISABLE about to fire (enabled=%s y=%.2f agl=%s drive suspended)",
        tostring(was), tonumber(y0) or -1.0, tostring(agl and string.format("%.1f", agl) or "?")))
    local ok = pcall(function() fc:call("set_Enabled", false) end)
    griffin_downed_probe_mark("FC DISABLE returned ok=" .. tostring(ok))
    S.downed_probe_fc = st
    status(string.format("FC probe armed at %.1fm AGL -- our drive suspended, auto-restores",
        tonumber(agl) or -1.0))
end

function griffin_probe_fc_tick()
    local st = S.downed_probe_fc
    if not st then return end
    local now = os.clock()
    local _, go = reacquire_griffin()
    if not go then griffin_probe_fc_restore("body lost"); return end
    if now >= (tonumber(st.next_at) or 0.0) then
        st.next_at = now + 0.25
        local up = transform_pos(go)
        local y = up and tonumber(up.y)
        if y then
            st.samples[#st.samples + 1] = string.format("%.2fs y=%.2f d=%+.2f",
                now - st.t0, y, y - (tonumber(st.y0) or y))
            while #st.samples > 40 do table.remove(st.samples, 1) end
            st.last_y = y
        end
    end
    if now < (tonumber(st.until_t) or 0.0) then return end
    local y0, y1 = tonumber(st.y0), tonumber(st.last_y)
    local elapsed = math.max(0.01, now - (tonumber(st.t0) or now))
    local verdict = "UNREADABLE (no altitude samples)"
    if y0 and y1 then
        local d = y1 - y0
        if d < -0.5 then verdict = string.format("FELL %.2fm (%.1f m/s) -- gravity/physics took over", -d, -d / elapsed)
        elseif d > 0.5 then verdict = string.format("ROSE %.2fm -- something ELSE still lifts it", d)
        else verdict = string.format("FROZE (%+.2fm) -- nothing owns position; we must drive the fall", d) end
    end
    S.downed_probe_verdict = verdict
    pcall(function() json.dump_file(MOD .. "_downed_probe_fc.json",
        { verdict = verdict, y0 = st.y0, y1 = st.last_y, was_enabled = st.was,
          secs = elapsed, time = os.date("%H:%M:%S"), samples = st.samples }) end)
    griffin_downed_probe_mark("FC VERDICT " .. verdict)
    griffin_probe_fc_restore("window ended")
    status("FC probe: " .. verdict)
end

function griffin_probe_node_readout()
    -- the VERIFY half: what action slot 0 actually holds right now
    local slot = "?"
    pcall(function()
        local am = griffin_action_manager()
        local lst = am and am:get_field("CurrentActionList")
        local a0 = lst and lst:call("get_Item", 0)
        slot = a0 and tostring(a0:call("ToString()")) or "nil"
    end)
    return slot
end

function griffin_probe_request_action(node, layer, prio)
    -- like request_griffin_action but with an EXPLICIT priority. The shipped helper
    -- hardcodes Priority=10; Nick's Bestiary NodeCore uses 0. Round 1 returned
    -- slot0=Invalid at 10, so the probe now walks both.
    local am = griffin_action_manager()
    if not am then return false end
    S.route3_self_action = true
    local ok = pcall(function()
        am:call("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)",
            tonumber(prio) or 0, tostring(node or ""), tonumber(layer) or 0)
    end)
    S.route3_self_action = false
    return ok
end

function griffin_probe_down_node()
    -- UNKNOWN 3. ⛔ THIS IS THE CALL THAT MAY HARD-AV. Blocklist honoured first (the
    -- Fly.Hovering family is proven-lethal cold), tape written BEFORE each request so a
    -- CTD still names the exact form that killed us.
    -- ROUND 2: walk a LADDER of call forms and stop at the first that changes slot 0 --
    -- one press now tests dotted-vs-leaf and priority 10-vs-0 instead of guessing one.
    local node = tostring(C.route3_downed_probe_node or "")
    if node == "" then status("down-node probe: no node set"); return end
    for band in tostring(C.route3_rise_node_blocklist or ""):gmatch("[^,%s]+") do
        if node:find(band, 1, true) then
            status("down-node probe REFUSED: '" .. band .. "' is blocklisted (known native AV)")
            return
        end
    end
    -- ⛔ ROUND-3 FIX (Aurora's rabbit test): the slot CANNOT be read in the same frame as the
    -- request -- Nick's NodeCore says so outright ("Node names can take a frame or two to
    -- update"). Round 2 read it immediately, saw Invalid after every form, reported
    -- "NO FORM TOOK", and fired all four -- while the node had in fact taken (slot0 read
    -- DmgDownLoop a moment later and the rabbit visibly went down). So: fire ONE form per
    -- press and verify on a DEFERRED tick. Press again to step to the next form.
    local leaf = tostring(node:match("([^%.]+)$") or node)
    local forms = {
        { name = node, prio = 0,  tag = "dotted@0" },
        { name = leaf, prio = 0,  tag = "leaf@0" },
        { name = node, prio = 10, tag = "dotted@10" },
        { name = leaf, prio = 10, tag = "leaf@10" },
    }
    local idx = (tonumber(S.downed_probe_form_idx) or 0) % #forms + 1
    S.downed_probe_form_idx = idx
    local f = forms[idx]
    local before = griffin_probe_node_readout()
    griffin_downed_probe_mark(string.format("DOWN NODE fire %s name=%s slot-before=%s",
        f.tag, f.name, tostring(before)))
    local ok = griffin_probe_request_action(f.name, 0, f.prio)
    griffin_downed_probe_mark("DOWN NODE request returned ok=" .. tostring(ok))
    S.downed_probe_node_at = os.clock()
    S.downed_probe_node_name = node
    S.downed_probe_pending = { tag = f.tag, before = before, ok = ok,
        check_at = os.clock() + (tonumber(C.route3_downed_probe_verify_delay) or 0.5) }
    S.downed_probe_node_hit = f.tag .. ": verifying..."
    status("down-node probe fired " .. f.tag .. " (verifying in a moment)")
end

function griffin_probe_verify_tick()
    -- the DEFERRED half of the node probe -- reads the action slot a beat after the request,
    -- because the slot is not populated in the firing frame.
    local p = S.downed_probe_pending
    if not p then return end
    if os.clock() < (tonumber(p.check_at) or 0.0) then return end
    S.downed_probe_pending = nil
    local after = griffin_probe_node_readout()
    local took = p.ok and tostring(after) ~= tostring(p.before)
        and not tostring(after):find("Invalid", 1, true)
    S.downed_probe_node_hit = string.format("%s -> slot0=%s  %s", tostring(p.tag),
        tostring(after), took and "*** TOOK ***" or "(no change -- press again for next form)")
    griffin_downed_probe_mark("DOWN NODE verify: " .. S.downed_probe_node_hit)
    status("down-node probe: " .. S.downed_probe_node_hit)
end

-- =====================================================================================
-- DOWNED / REVIVE -- SLICE 1: the ground state machine (2026-07-21).
-- A tamed companion reaching the floor HP does NOT die: it goes DOWN, you get a window to
-- revive it by hand, and if you don't it is carried back to the stable to heal slowly.
--
-- ⛔ THE GOVERNING RISK, per the work-order review: a downed companion holds FOUR leases at
-- once (damage immunity, AI off, nav off, HP pinned). A script reset, your death, an area
-- change or a CTD all bypass a tidy exit -- and a leaked lease is an IMMORTAL BRAIN-DEAD PET
-- that no longer has any state telling us to unwind it. So: ONE canonical release
-- (griffin_downed_release) called from every exit, plus a boot sweep for the paths that
-- never reach an exit at all.
--
-- ⛔ SECOND LAW: we HOLD state, we never SET it. Native getup/revive logic silently
-- re-enables the components we disable (the grab system learned this the same way), so the
-- leases are re-asserted every frame while down.
--
-- SLICE 1 IS GROUND-ONLY. The air/fall branch is slice 2 (probe answers: FlightControl can
-- be disabled safely and the body then FREEZES, so the fall must be hand-driven and capped
-- at route3_swoop_vertical_speed or the rider's climb grip releases).
-- =====================================================================================



















function griffin_mount_crash_mark(s)
    -- RT-MOUNT CRASH MONITOR (Aurora 2026-07-20): the auto-mount+pose path crashed once with nothing
    -- in the REF log (native AV pattern). json.dump_file flushes, so a hard CTD leaves the last step
    -- reached in data/GriffinRideProbe (IRIS)_mount_crash.json -> the "last" field = the crash step.
    S.route3_mount_trace = S.route3_mount_trace or {}
    S.route3_mount_trace[#S.route3_mount_trace + 1] = string.format("%.2f %s", os.clock(), tostring(s))
    while #S.route3_mount_trace > 40 do table.remove(S.route3_mount_trace, 1) end
    pcall(function() json.dump_file(MOD .. "_mount_crash.json", { last = tostring(s), time = os.date("%H:%M:%S"), trace = S.route3_mount_trace }) end)
end

function route3_quick_burst_active()
    return type(S.route3_quick_burst) == "table"
end

function route3_quick_burst_node_matches(current, wanted)
    current, wanted = tostring(current or ""), tostring(wanted or "")
    if current == "" or wanted == "" then return false end
    local leaf = wanted:match("[^%.]+$") or wanted
    return current == wanted or current == leaf or current:find(leaf, 1, true) ~= nil
end


function route3_quick_burst_travel_node_safe(st, current)
    current = tostring(current or "")
    if current == "" or current == "(unknown)" then return false end
    if route3_quick_burst_node_matches(current, st and st.node) then return false end
    local lower = current:lower()
    -- These are precisely the native owners that must never overlap our transform travel.
    return lower:find("catch", 1, true) == nil
        and lower:find("attack", 1, true) == nil
        and lower:find("bring", 1, true) == nil
end


function route3_quick_burst_end(reason)
    local st = S.route3_quick_burst
    if not st then return end
    local now = os.clock()
    S.route3_quick_burst = nil
    S.route3_rise_until = 0.0
    S.route3_rise_move_at = 0.0
    S.route3_rise_hold_until = 0.0
    S.route3_rise_node_used = nil
    S.route3_rise_dbg = false
    if S.base_owner and S.base_owner.name == "rise" then S.base_owner = nil end
    S.audition_until_clock = 0.0
    if S.mounted == true and S.airborne == true then
        local ch, go = reacquire_griffin()
        if ch and go then
            -- Quick bursts no longer change the action FSM. Never try to force an action/node
            -- during exit or dismount; restore only the ordinary resident flight base.
            S.route3_native_flight_node = nil
            S.route3_native_flight_last_check = 0.0
            pcall(function() route3_restore_flight_base() end)
        end
    end
    S.route3_rise_cd_at = math.max(tonumber(S.route3_rise_cd_at) or 0.0,
        now + math.max(0.0, tonumber(C.route3_rise_cooldown) or 0.4))
    S.route3_rise_status = (st.dir < 0 and "quick dive: " or "quick rise: ") .. tostring(reason or "done")
    S.route3_rise_status_until = now + 2.0
    griffin_rise_crash_mark("END " .. tostring(reason or "done"))
end


function route3_quick_burst_begin_handoff(st, now)
    -- Compatibility for a hot-reloaded pre-fix burst. Do not touch its native FSM again;
    -- convert it to the direct controller and continue from the current held transform.
    st.safe_direct = true
    st.node = ""
    route3_quick_burst_begin_travel(st, now)
end

function route3_quick_burst_begin_travel(st, now)
    st.phase = st.dir < 0.0 and "drop" or "rise"
    st.phase_t0 = now
    st.last = now
    local _, go = reacquire_griffin()
    local pos = (go and (S.route3_air_pos or transform_pos(go))) or st.hold_pos
    local y = tonumber(pos and pos.y)
    if not y then route3_quick_burst_end("travel start position lost"); return false end
    local max_speed = math.max(6.0, math.min(16.0, tonumber(C.route3_quick_vertical_max_speed) or 14.0))
    if st.dir < 0.0 then
        local depth = math.max(2.0, math.min(120.0, tonumber(C.route3_quick_dive_depth) or 14.0))
        local clearance = math.max(0.3, tonumber(C.route3_dive_ground_clearance) or 1.2)
        local gy = route3_ground_y_robust(go, y) or tonumber(st.ground_y)
        if not gy then route3_quick_burst_end("floor lost before drop"); return false end
        st.ground_y = gy
        -- ⛔ TOO LOW = NO DESCEND LOOP (2026-08-07, Aurora: "should not allow descend
        -- loop-the-loop when near the ground, a good 70m or so"): the gate is her OWN depth
        -- setting -- there must be room for the whole configured dive, or the loop animation
        -- plays while the drop truncates against the floor. Self-scales with the slider.
        if (y - gy) < depth + clearance then
            route3_quick_burst_end(string.format("too low for the descend loop (%.0fm up, need %.0fm)",
                y - gy, depth + clearance))
            return false
        end
        st.travel_start_y = y
        st.travel_target_y = math.max(gy + clearance, y - depth)
        st.travel_distance = math.max(0.0, y - st.travel_target_y)
        -- smoothstep's peak velocity is 1.5 * distance / duration. Extend a short
        -- user duration instead of allowing a dangerous single-frame/world relocation.
        st.travel_duration = math.max(0.3, tonumber(C.route3_dive_drop_secs) or 1.5,
            (1.5 * st.travel_distance) / max_speed)
        local clip = math.floor(tonumber(C.route3_dive_drop_clip) or 551)
        if C.route3_dive_motion_enabled == true and clip >= 0 then
            play_griffin_motion(clip, math.floor(tonumber(C.route3_dive_motion_bank) or 50), true, "rise")
        end
        S.route3_rise_status = "quick dive: dropping"
    else
        local height = math.max(2.0, math.min(120.0, tonumber(C.route3_quick_rise_height) or 14.0))
        st.normal_vertical_drive = true
        st.drive_step = 0.001
        st.travel_start_y = y
        st.travel_target_y = y + height
        st.travel_distance = height
        st.travel_duration = math.max(0.3, tonumber(C.route3_rise_secs) or 1.75,
            (1.5 * height) / max_speed)
        S.route3_rise_status = "quick rise: climbing"
    end
    griffin_rise_crash_mark(string.format("DIRECT TRAVEL start %.1fm / %.2fs",
        tonumber(st.travel_distance) or 0.0, tonumber(st.travel_duration) or 0.0))
    return true
end

function route3_quick_burst_apply(ch, go, st, pos)
    local rot = make_quat_yaw(tonumber(st.yaw) or S.heading_yaw or 0.0)
    S.route3_air_pos = pos
    S.route3_air_rot = rot
    local ok = route3_apply_air_transform(ch, go, pos, rot)
    if ok then
        st.hold_pos, st.hold_rot = pos, rot
        S.heading_yaw = tonumber(st.yaw) or S.heading_yaw
    end
    return ok == true
end


function route3_quick_burst_tick(ch, go, now)
    local st = S.route3_quick_burst
    if not st then return false end
    if not (ch and go) or S.mounted ~= true or S.airborne ~= true then
        route3_quick_burst_end("interrupted")
        return false
    end
    now = now or os.clock()
    S.base_owner = { name = "rise", until_clock = now + 1.0 }
    S.audition_until_clock = now + 0.3
    -- The rise owns an authored additive UP pose on L1. Clearing it here would reduce the
    -- climb back to the forward-looking base clip. Dive and all other phases still clear L1.
    if not (st.dir > 0.0 and st.rise_overlay_active == true
        and (st.phase == "direct_windup" or st.phase == "rise")) then
        pcall(function() route3_flap_clear_overlay() end)
    end

    if st.phase == "windup" then
        -- A pre-fix state survived a hot reload. It may still own a native Attack/Catch action;
        -- cancel without requesting another action and let normal flight recovery take over.
        route3_quick_burst_end("retired native wind-up cancelled")
        return false
    end

    if st.phase == "direct_windup" then
        -- Reapply the same transform during the authored brace/wingbeat. There is no native
        -- ActionManager owner to cancel and therefore no unsafe hand-off phase.
        route3_quick_burst_apply(ch, go, st, st.hold_pos)
        local left = math.max(0.0, (tonumber(st.phase_until) or now) - now)
        S.route3_rise_status = st.dir < 0.0 and string.format("quick dive: brace %.1fs", left)
            or string.format("quick rise: wing-up %.1fs", left)
        if now >= (tonumber(st.phase_until) or now) then route3_quick_burst_begin_travel(st, now) end
        return true
    end

    if st.phase == "handoff" then
        route3_quick_burst_begin_handoff(st, now)
        return true
    end

    local dt = math.max(0.001, math.min(0.05, now - (tonumber(st.last) or now)))
    st.last = now
    local pos = S.route3_air_pos or transform_pos(go) or st.hold_pos
    if not pos then route3_quick_burst_end("position lost"); return false end
    if st.safe_direct ~= true and now - (tonumber(st.last_node_check) or 0.0) >= 0.05 then
        st.last_node_check = now
        local current = read_griffin_fsm_node()
        if not route3_quick_burst_travel_node_safe(st, current) then
            griffin_rise_crash_mark("TRAVEL abort unsafe-node=" .. tostring(current))
            route3_quick_burst_end("native action reclaimed body; movement cancelled")
            return false
        end
    end

    if st.phase == "rise" then
        local dur = math.max(0.3, tonumber(st.travel_duration) or tonumber(C.route3_rise_secs) or 1.75)
        local frac = math.min(1.0, math.max(0.0, (now - (tonumber(st.phase_t0) or now)) / dur))
        local eased = frac * frac * (3.0 - 2.0 * frac)
        local live_pos = transform_pos(go) or pos
        local live_y = tonumber(live_pos and live_pos.y) or tonumber(pos.y) or 0.0
        local start_y = tonumber(st.travel_start_y) or live_y
        local target_y = tonumber(st.travel_target_y) or start_y
        local desired_y = start_y + (target_y - start_y) * eased
        local max_step = math.max(0.05, math.min(0.5, tonumber(C.route3_quick_vertical_max_step) or 0.35))
        local dy = math.max(0.001, math.max(-max_step, math.min(max_step, desired_y - live_y)))
        -- Do not construct or publish an absolute position here. Even staging an upward
        -- S.route3_air_pos crashed before the seat writer could enter. Feed only a scalar
        -- vertical step into the ordinary, proven manual-ascent pipeline below.
        st.normal_vertical_drive = true
        st.drive_step = dy
        if st.first_apply_marked ~= true then
            st.first_apply_marked = true
            griffin_rise_crash_mark(string.format("FIRST NORMAL RISE DRIVE armed step=%.4f", dy))
        end
        local remaining = math.max(0.0, target_y - (live_y + dy))
        S.route3_rise_status = string.format("quick rise: %.1fm", remaining)
        if remaining <= 0.05 then route3_quick_burst_end("done") end
        return true
    end

    if st.phase == "drop" then
        local dur = math.max(0.3, tonumber(st.travel_duration) or tonumber(C.route3_dive_drop_secs) or 1.5)
        local frac = math.min(1.0, math.max(0.0, (now - (tonumber(st.phase_t0) or now)) / dur))
        local forward_speed = math.max(0.0, tonumber(C.route3_dive_swoop_speed) or 16.0)
        local forward_blend = math.max(0.0, math.min(1.0, (frac - 0.65) / 0.35))
        local yaw = tonumber(st.yaw) or 0.0
        local dx = math.sin(yaw) * forward_speed * forward_blend * dt
        local dz = math.cos(yaw) * forward_speed * forward_blend * dt
        if forward_blend > 0.0 and route3_forward_blocked(go, yaw, 3.0 + forward_speed * dt) then dx, dz = 0.0, 0.0 end
        local gy = route3_ground_y_robust(go, tonumber(st.hold_pos and st.hold_pos.y)) or tonumber(st.ground_y)
        if not gy then route3_quick_burst_end("floor lost; movement cancelled"); return false end
        st.ground_y = gy
        local clearance = math.max(0.3, tonumber(C.route3_dive_ground_clearance) or 1.2)
        local min_y = gy + clearance
        local eased = frac * frac * (3.0 - 2.0 * frac)
        local start_y = tonumber(st.travel_start_y) or tonumber(pos.y) or min_y
        local target_y = math.max(min_y, tonumber(st.travel_target_y) or min_y)
        local desired_y = start_y + (target_y - start_y) * eased
        local max_step = math.max(0.05, math.min(0.5, tonumber(C.route3_quick_vertical_max_step) or 0.35))
        local dy = math.max(-max_step, math.min(max_step, desired_y - (tonumber(pos.y) or desired_y)))
        local ny = math.max(min_y, (tonumber(pos.y) or min_y) + dy)
        local newpos = make_position((tonumber(pos.x) or 0.0) + dx, ny, (tonumber(pos.z) or 0.0) + dz)
        if not route3_quick_burst_apply(ch, go, st, newpos) then route3_quick_burst_end("transform write failed"); return false end
        local remaining = math.max(0.0, ny - target_y)
        S.route3_rise_status = string.format("quick dive: %.1fm", remaining)
        if (frac >= 1.0 and remaining <= 0.05) or ny <= min_y + 0.02 then
            st.phase = "swoop"
            st.phase_t0 = now
            st.last = now
            local clip = math.floor(tonumber(C.route3_dive_swoop_clip) or 501)
            local bank = math.floor(tonumber(C.route3_dive_swoop_bank) or 50)
            if C.route3_dive_motion_enabled == true and clip >= 0 then
                play_griffin_motion(clip, bank, true, "rise")
            end
            S.route3_rise_status = "quick dive: forward swoop"
        end
        return true
    end

    if st.phase == "swoop" then
        local dur = math.max(0.1, tonumber(C.route3_dive_swoop_secs) or 0.75)
        local frac = math.min(1.0, math.max(0.0, (now - (tonumber(st.phase_t0) or now)) / dur))
        local speed = math.max(1.0, tonumber(C.route3_dive_swoop_speed) or 16.0)
        local yaw = tonumber(st.yaw) or 0.0
        if route3_forward_blocked(go, yaw, 3.0 + speed * dt) then
            route3_quick_burst_end("forward path blocked")
            return false
        end
        local gy = route3_ground_y_robust(go, tonumber(pos.y)) or tonumber(st.ground_y)
        if not gy then route3_quick_burst_end("floor lost; movement cancelled"); return false end
        st.ground_y = gy
        local min_y = gy + math.max(0.3, tonumber(C.route3_dive_ground_clearance) or 1.2)
        local newpos = make_position(
            (tonumber(pos.x) or 0.0) + math.sin(yaw) * speed * dt,
            math.max(min_y, tonumber(pos.y) or min_y),
            (tonumber(pos.z) or 0.0) + math.cos(yaw) * speed * dt)
        if not route3_quick_burst_apply(ch, go, st, newpos) then route3_quick_burst_end("transform write failed"); return false end
        S.route3_rise_status = string.format("quick dive: swoop %.1fs", math.max(0.0, dur - (now - st.phase_t0)))
        if frac >= 1.0 then route3_quick_burst_end("done") end
        return true
    end

    route3_quick_burst_end("unknown phase")
    return false
end

-- Start painting a climb/dive CLIP for the quick rise/descend (dir>0 = climb, dir<0 = dive). Play-motion,
-- NOT an FSM node (the nodes crashed). Parked with base_owner so the flap can't stomp it; the transform
-- drive still owns the actual up/down movement. route3_rise_tick re-asserts + restores flight at the end.
-- ⭐⭐ THE NODE LOCKOUT PREDICATE (2026-08-04). Single source of truth for "a native node is
-- currently driving her body, so nothing else may touch it".
--
-- Why this exists: firing a node only held `base_owner` for 0.6s, but a real node (LoopTheLoop
-- is ~4s) keeps owning her root motion long after that lapses. Aurora then held B mid-loop, the
-- soar painter repainted L0 over a node-driven body, and the engine AV'd -- the same two-owners
-- signature as clip 5010. The screenshot of the mangled soar pose is the survivable version of
-- the same collision.
--
-- The window closes on EVIDENCE, not a guess: it stays open while the node we fired is still the
-- current FSM node, so it tracks the node's real length instead of a hardcoded duration. Three
-- independent ways out, because a lock that can wedge is worse than the bug:
--   1. her FSM has left the node (the normal exit)
--   2. route3_node_lockout_max seconds have passed regardless (the ceiling)
--   3. the flag is off, or she is not airborne/mounted any more
-- ⭐⭐ NODE EXIT PUMP (2026-08-04). A force-fired node has no exit of its own, and one request is
-- not enough -- taped proof that a single requestAction bounced straight off a running LoopTheLoop:
--     exit_requested=Ch253SoaringFlight, fsm before AND after = Fly.Flight.Ch253LoopTheLoopFlight
--
-- Two things the one-shot got wrong:
--   1. ⛔ `IsRejectRequestOnDefault` / `IsRejectAbortOnDefault` -- a running action refuses both new
--      requests and being aborted until these are cleared. Documented, and I ignored it.
--   2. It only tried once. The same tape shows the exit DID land on a later press, so it is a race
--      against the node's own accept window, not an impossibility.
-- So: clear both flags, re-request every frame until the FSM genuinely leaves, then RESTORE the
-- flags (never leave her accepting every default request) and stop.
function griffin_node_exit_pump(now)
    local until_t = tonumber(S.route3_node_exit_until)
    if not until_t then return end
    -- ⛔ GROUNDED = CANCEL (2026-08-07): the exit node is a FLIGHT neutral (SoaringFlight);
    -- pumping it into a grounded body shoves her FSM into a flight state on the dirt (the
    -- post-pounce loop corruption). Restore the reject flag and stand down -- the
    -- post-landing recover owns the grounded neutral.
    if S.mounted == true and S.airborne ~= true then
        S.route3_node_exit_until = nil
        pcall(function()
            local am = griffin_action_manager()
            if am then am:call("set_IsRejectRequestOnDefault", true) end
        end)
        S.route3_node_exit_status = "(cancelled: grounded)"
        return
    end
    now = tonumber(now) or os.clock()
    local leaf = tostring(C.route3_node_exit_node or ""):match("([^%.]+)$") or ""
    local live = "?"
    pcall(function() live = tostring(read_griffin_fsm_node() or "?") end)
    local from = tostring(S.route3_node_exit_from or "")
    -- ⛔ SUCCESS = SHE IS IN THE EXIT NODE, not merely "no longer in the fired node" (2026-08-05).
    -- The old escaped-test declared victory the instant she left the attack node -- including
    -- leaving it INTO SoaringFlight, i.e. her woken brain flying off (Aurora's screenshot: "just
    -- started flying up using the soaring flight animation", twice). Escaping into a rebellion is
    -- not an exit. The pump now keeps requesting the neutral until the FSM actually SHOWS it (or
    -- the 1.5s window times out -- a pump that can wedge is worse than the bug).
    local reached = (leaf ~= "" and live:find(leaf, 1, true) ~= nil)
    local escaped = (from == "" or not live:find(from, 1, true))
    if reached or now > until_t or leaf == "" then
        S.route3_node_exit_until = nil
        pcall(function()   -- ⛔ ALWAYS restore: never leave her accepting every default request
            local am = griffin_action_manager()
            if am then am:call("set_IsRejectRequestOnDefault", true) end
        end)
        -- ⭐ REPAINT FLIGHT AFTER THE RETIRE (Aurora: "it does a small ground idle when it ends").
        -- Locomotion.Wait is the correct SAFE neutral -- it is where our drive parks her -- but it
        -- is a GROUND state, so its idle pose shows for a beat. The FSM state and the visible clip
        -- are separate concerns: keep the safe state, repaint the flight clip over the top.
        if reached or escaped then
            -- ⭐ drop OUR base-owner lease first: restore_flight_base paints with NO owner, so our
            -- own still-running "rise"/"gustair" lease bounced our own repaint -- which is the
            -- "ends in an on-the-ground idle" Aurora saw on the gale. The lease's job (protecting
            -- the node from painters) ended with the node.
            S.base_owner = nil
            -- ⭐⭐ CLASSIC FLIGHT RECOVERY, not restore_flight_base (2026-08-05, Aurora: "the fly
            -- is now double flapping... seems to put the flap loop out of time"). The glide
            -- repaint left the flap system to re-establish against a playhead it did not choose
            -- -- the old out-of-time double-flap. The classic dogfight solved this years of tape
            -- ago: paint the flap BEAT clip and arm the reseek, which pins the playhead at the
            -- sync frame (route3_dogfight_flap_sync) so the beat can never be out of phase.
            if S.route3_pounce_ground_at_retire ~= nil and S.mounted == true then
                -- ⭐⭐ POUNCE ENDS GROUNDED (2026-08-06, Aurora: "it probably needs to land at
                -- that point so it's grounded" -- the flare finished and the Fly tree took her
                -- straight back to hovering). The node is parked NOW, so the full landing flow
                -- is safe to run: it grounds the whole mount state (S.airborne=false), plays
                -- the touchdown clip and calm-nets the seam. She ends STANDING at the kill.
                local gy_hint = tonumber(S.route3_pounce_ground_at_retire)
                S.route3_pounce_ground_at_retire = nil
                local ch3, go3 = reacquire_griffin()
                local gy = nil
                pcall(function() gy = route3_ground_y_robust(go3, gy_hint) end)
                gy = gy or gy_hint
                pcall(function() route3_finish_landing(ch3, go3, gy, "pounce touchdown") end)
            elseif S.mounted == true and S.airborne == true then
                pcall(function() route3_flap_clear_overlay() end)
                S.route3_flap_phase = nil
                local fc2 = math.floor(tonumber(C.flap_takeoff_clip) or 5210)
                pcall(function() play_griffin_motion(fc2, 0, true) end)
                S.route3_dogfight_reseek_clip = fc2
                S.route3_dogfight_reseek_until = os.clock() + 1.2
            elseif S.mounted == true then
                -- mounted + GROUNDED (the skid pounce ends standing, 2026-08-07): the landing
                -- calm-net owns the pose -- painting the flight base here would pop her into a
                -- glide on the dirt
            else
                pcall(function() route3_restore_flight_base() end)
            end
            -- ⭐ RE-CALM THE MOMENT THE NODE RETIRES (2026-08-05, Aurora: after the new attacks
            -- "the griffin started going nuts and then did soaring flight as if it was trying to
            -- regain control"). The attack fire delays the calm-lock (needed, or the calm cuts the
            -- animation short) -- but the delay OUTLIVES the node, and in that gap her woken
            -- combat brain gets real frames and runs off into SoaringFlight. The node is done the
            -- instant we retire it, so the calm-lock's reason to wait is done too: pull it to NOW.
            local nowc = os.clock()
            local at = tonumber(S.route3_rise_recalm_at)
            if at and at > nowc then S.route3_rise_recalm_at = nowc end
        end
        S.route3_node_exit_status = string.format("%s after %d tries (now %s)",
            reached and "RETIRED" or (escaped and "escaped-but-not-parked" or "gave up"),
            tonumber(S.route3_node_exit_tries) or 0, live)
        S.route3_fc_sanitise_pending = "node exit: " .. tostring(S.route3_node_exit_status)
        pcall(function()
            griffin_climb_handoff_snapshot("node exit: " .. tostring(from) .. " -> " .. tostring(live))
        end)
        pcall(function()
            json.dump_file(MOD .. "_nodeexit.json", {
                when = os.date("%H:%M:%S"),
                result = reached and "RETIRED OK (parked in exit node)"
                    or (escaped and "TIMED OUT escaped elsewhere (rebellion?)" or "TIMED OUT -- still stuck"),
                from_node = from, exit_requested = leaf,
                fsm_now = live, tries = tonumber(S.route3_node_exit_tries) or 0,
            })
        end)
        return
    end
    S.route3_node_exit_tries = (tonumber(S.route3_node_exit_tries) or 0) + 1
    pcall(function()
        local am = griffin_action_manager()
        if am then
            am:call("set_IsRejectRequestOnDefault", false)   -- accept our request
            -- ⛔ NO IsRejectAbortOnDefault here: that field lives on the CharacterController
            -- (Puppeteer sets it on the pawn's ctrl), NOT on app.ActionManager. Setting it here
            -- threw "Attempted to set invalid REManagedObject field" every frame of the pump.
        end
    end)
    pcall(function() request_griffin_action(leaf, 0) end)
    S.route3_node_exit_status = "retiring " .. from .. " -> " .. leaf
        .. " (try " .. tostring(S.route3_node_exit_tries) .. ", now " .. live .. ")"
end

function griffin_node_lockout_begin(leaf, now, src, keep_cam)
    if C.route3_node_lockout == false then return end
    -- ⛔ a NEW node fire invalidates any pending pounce-landing order: a stale flag here landed
    -- the loop-the-loop mid-air (2026-08-06) -- the deferred grounding belongs to ONE retire only
    S.route3_pounce_ground_at_retire = nil
    S.route3_node_lock_at = tonumber(now) or os.clock()
    S.route3_node_lock_leaf = tostring(leaf or "")
    -- ⭐ WHO fired this lockout (2026-08-05). The gale dive and the wing-thunder now ride the same
    -- lockout machinery, and the loop camera keyed on "lockout active" alone -- so every attack
    -- hijacked the cinematic camera (Aurora: "which I don't want"). Tag the source; the camera
    -- films ONLY "rise" (quick ascend/descend = the loop). Omitted src defaults to "rise" so the
    -- rise path needs no change.
    S.route3_node_lock_src = tostring(src or "rise")
    S.route3_node_lock_seen = false   -- set once her FSM actually shows the node (it takes a frame or two)
    -- ⭐ Re-arm the camera HERE, on the node FIRE -- not on the lock going idle. Aurora: "the camera
    -- worked once but then it wouldn't work again". Its timer was only cleared when the lock fully
    -- released, so a second loop fired while the first 8s lock was still held saw a stale timer,
    -- decided the shot was already over, and never filmed. Firing a node always starts a new shot.
    -- keep_cam: a HOLD re-fire of the same node mid-window must NOT restart the shot (Aurora:
    -- "it does the camera thing twice") -- same press, same shot.
    if keep_cam ~= true then
        S.route3_loopcam_t0 = nil
        S.route3_loopcam_yaw = nil
        S.route3_loopcam_anchor = nil
        S.route3_loopcam_travel_max = 0.0   -- fresh shot = fresh peak-travel reading
    end
end

function griffin_node_lockout_active(now)
    if C.route3_node_lockout == false then return false end
    local t0 = tonumber(S.route3_node_lock_at)
    if not t0 then return false end
    now = tonumber(now) or os.clock()
    local maxs = math.max(0.2, tonumber(C.route3_node_lockout_max) or 8.0)
    if now - t0 > maxs then                       -- CEILING: never wedge
        S.route3_node_lock_at = nil
        S.route3_node_lock_status = "released (ceiling)"
        S.route3_node_lock_restore = true         -- ⛔ was missing: the ceiling exit left the base
        return false                              -- layer un-restored, so she held the node's pose
    end
    local leaf = tostring(S.route3_node_lock_leaf or "")
    -- Read the FSM LIVE rather than trusting S.last_fsm_node -- that cache is only refreshed by
    -- whoever happened to call read_griffin_fsm_node last, and a stale name here would either
    -- hold the lock to its ceiling or drop it early. Throttled, because the paint gate can ask
    -- several times in one frame and this does a component lookup.
    if now - (tonumber(S.route3_node_lock_read_at) or -1.0) > 0.05 then
        S.route3_node_lock_read_at = now
        pcall(function() read_griffin_fsm_node() end)
    end
    local live = tostring(S.last_fsm_node or "")
    if leaf ~= "" and live ~= "" and live:find(leaf, 1, true) then
        S.route3_node_lock_seen = true            -- confirmed: the node really is running
        S.route3_node_lock_last = now
        S.route3_node_lock_status = "LOCKED on " .. leaf
        return true
    end
    -- Node not (yet) visible. Before it has EVER been seen, hold the lock anyway -- the request
    -- needs a frame or two to take, and that entry gap is precisely when a stray paint is fatal.
    if S.route3_node_lock_seen ~= true then
        S.route3_node_lock_status = "LOCKED (node entering)"
        return true
    end
    -- It was running and now it isn't -> ride out the tail, then release.
    local tail = math.max(0.0, tonumber(C.route3_node_lockout_tail) or 0.35)
    if now - (tonumber(S.route3_node_lock_last) or t0) <= tail then
        S.route3_node_lock_status = "LOCKED (tail)"
        return true
    end
    S.route3_node_lock_at = nil
    S.route3_node_lock_status = "released (node ended)"
    -- Hand the base layer back ONE tick later, not here: this predicate is called from inside
    -- play_griffin_motion, so painting from it would re-enter the painter. The rise tick consumes
    -- the flag. Without it, a restore that happened to be attempted DURING the lock is simply lost
    -- and she can hold the node's last pose.
    S.route3_node_lock_restore = true
    return false
end

function route3_rise_start_clip(dir, dur, now)
    local descending = (tonumber(dir) or 1.0) < 0.0
    -- ⭐ v10 nodeless flight: the cinematic used to arm on NODE FIRE (lockout). With no node,
    -- arm it on the rise press itself -- the shot covers the movement window. Node species
    -- (griffin) also pass here; their lockout arm makes this redundant but harmless.
    S.route3_loopcam_clip_until = (tonumber(now) or os.clock()) + math.max(0.5, tonumber(dur) or 1.0) + 0.8
    -- NODE takes priority if the picker set one: fire it the SAFE way (requestActionCore priority 10
    -- ONLY -- NO setCurrentNode, which the AI reverts to a T-pose). The node owns the animation; the
    -- movement burst still drives the actual up/down. ⛔ PreSwoop/LoopTheLoop break the camera -- avoid.
    local node = descending and tostring(C.route3_rise_node_down or "") or tostring(C.route3_rise_node_up or "")
    node = node:gsub("%s+", "")
    if node ~= "" and C.route3_rise_use_node ~= false then
        -- ⛔ CRASH/CAMERA BLOCKLIST: some FSM nodes HARD-CRASH (native AV -- uncatchable by pcall) or
        -- break the camera when fired cold via requestActionCore (crash tape: Fly.Hovering.HoverBackward
        -- AV'd; PreSwoop/LoopTheLoop break the cam). REFUSE to fire a blocklisted node -> fall through to
        -- the clip path (safer than crashing the game).
        -- GATES REMOVED 2026-07-26 (Aurora's call, and the evidence backs it): the blocklist
        -- refusal and the Fly-tree requirement both existed on the theory that cross-tree /
        -- "lethal" node fires caused the CTDs. They did not -- clip 5010 did, and it is fixed.
        -- Whatever you pick in the NODE PICKER now fires. The only check left is
        -- griffin_fsm_node_exists, which stays because an unknown NAME is a native AV, not a
        -- refusal we can reason about. Blocklisted names are still flagged ⛔ in the picker.
        if not griffin_fsm_node_exists(node) then
            -- ⭐ record the FAILURE case too -- "node not found" silently falls through to a plain
            -- clip, which looks exactly like "it isn't using LoopTheLoop" from the saddle.
            pcall(function()
                json.dump_file(MOD .. "_ridediag.json", {
                    when = os.date("%H:%M:%S"),
                    RESULT = "NODE NOT FOUND -- fell through to clip only",
                    node_wanted = tostring(node),
                    dir = (tonumber(dir) or 1.0) < 0.0 and "DESCEND" or "ASCEND",
                    fsm_now = tostring(read_griffin_fsm_node() or "?"),
                    use_node = tostring(C.route3_rise_use_node),
                })
            end)
            S.route3_rise_status = "rise node NOT FOUND: " .. node    -- fall through to clip
            -- (cross-tree gate removed with the blocklist gate -- see above)
        else
            local leaf = node:match("([^%.]+)$") or node
            -- TAPE THE PRECONDITIONS BEFORE THE DANGEROUS CALL (the file's own crash-tape law).
            -- The 2026-07-26 LoopTheLoop CTD was inconclusive on ONE point: whether the
            -- ActionInterface disable had actually applied or had hit the REFUSED path -- that
            -- verdict lived in S and died with the process. It goes on disk now, alongside the
            -- FSM node we are jumping FROM, which the tape says is what actually matters.
            pcall(function()
                griffin_rise_crash_mark(string.format("ACTINT[%s] from-node=%s fire=%s%s",
                    tostring(S.griffin_action_interface_status or "(never applied)"),
                    tostring(read_griffin_fsm_node() or "?"),
                    leaf,
                    C.route3_rise_node_with_clip == true and " +clip" or ""))
            end)
            -- ⭐ OPEN THE FC-LIFT WINDOW *BEFORE* THE REQUEST. The standdown must already be
            -- in force on the very first frame the node exists -- if the transform drive gets
            -- even one tick alongside it we are back to two writers, which is the crash.
            pcall(function() route3_rise_fc_lift_begin(dir, dur, now, leaf) end)
            -- ⭐ ARM THE LOCKOUT BEFORE THE REQUEST, for the same reason fc-lift arms first: the
            -- very first frame the node exists must already be protected. Opening it after the
            -- request leaves exactly the one-tick gap that two-owner crashes live in.
            pcall(function() griffin_node_lockout_begin(leaf, now) end)
            S.route3_rise_hold_fires = 0   -- fresh hold budget per press (rise-node hold)
            S.route3_loopcam_dir = descending and -1.0 or 1.0   -- the PAN camera sweeps this way
            -- ⭐ RIDE DIAG: Aurora cannot find the panel readouts, so the answers go to DISK.
            -- data/GriffinRideProbe (IRIS)_ridediag.json -- one record per node fire.
            pcall(function()
                S.route3_ride_diag = {
                    when = os.date("%H:%M:%S"),
                    configured_up = tostring(C.route3_rise_node_up or ""),
                    configured_down = tostring(C.route3_rise_node_down or ""),
                    dir = (tonumber(dir) or 1.0) < 0.0 and "DESCEND" or "ASCEND",
                    node_requested = leaf,
                    node_exists = true,          -- we are inside the exists() branch
                    use_node = tostring(C.route3_rise_use_node),
                    with_clip = tostring(C.route3_rise_node_with_clip),
                    fsm_before = tostring(read_griffin_fsm_node() or "?"),
                }
                json.dump_file(MOD .. "_ridediag.json", S.route3_ride_diag)
            end)
            pcall(function() request_griffin_action(leaf, 4) end)
            pcall(function() request_griffin_action(leaf, 0) end)
            pcall(function() griffin_rise_crash_mark("node request SURVIVED (did not AV on the call itself)") end)
            -- ⭐ protect the node's ANIMATION for the whole rise window (2026-08-11): the old
            -- 0.3/0.6s leases let the flap repaint stomp L0 ~1s in -- which HIDES a node's
            -- animation (tape law) even while the FSM stays in the node. On short bursts this
            -- is why "the animation doesn't last". The exit pump still retires at window end.
            S.base_owner = { name = "rise", until_clock = now + math.max(0.6, tonumber(dur) or 0.6) }
            S.audition_until_clock = now + math.max(0.3, tonumber(dur) or 0.3)
            -- the node WAKES her combat state (same as the WingThunder gust) -> re-calm when its window
            -- ends, or she floats above ground on landing/dismount (checked in griffin_efx_reaper_tick).
            S.route3_rise_recalm_at = now + math.max(0.5, tonumber(dur) or 1.0) + 0.6
            S.route3_rise_status = (descending and "dive node: " or "rise node: ") .. leaf
                .. (S.route3_rise_bypassed == node and " [BYPASSED]" or "")
            if C.route3_rise_node_with_clip ~= true then
                S.route3_rise_clip_until = 0.0   -- node owns the anim -> no clip paint (normal path)
                return
            end
            -- CONTENTION TEST: do NOT zero the clip and do NOT return -- fall through to the clip
            -- painter so the descend clip runs UNDERNEATH the node. Two owners on one motion
            -- stack, on purpose. base_owner/audition are re-set identically below; harmless.
            S.route3_rise_status = S.route3_rise_status .. " + clip"
        end
    end
    if C.route3_rise_clip_enabled == false then S.route3_rise_clip_until = 0.0; return end
    local loop_clip = descending and math.floor(tonumber(C.route3_rise_descend_clip) or 551)
        or math.floor(tonumber(C.route3_rise_ascend_clip) or 702)
    if loop_clip < 0 then S.route3_rise_clip_until = 0.0; return end   -- -1 loop = no clip (natural flap climb)
    local start_clip = descending and math.floor(tonumber(C.route3_rise_descend_start_clip) or 550)
        or math.floor(tonumber(C.route3_rise_ascend_start_clip) or 700)
    S.route3_rise_clip = loop_clip
    S.route3_rise_clip_bank = math.floor(tonumber(C.route3_rise_clip_bank) or 50)
    S.route3_rise_clip_until = now + math.max(0.2, tonumber(dur) or 1.0)
    S.route3_rise_clip_looped = false
    S.route3_rise_clip_loop_at = now + math.max(0.0, tonumber(C.route3_rise_clip_start_secs) or 0.3)
    S.route3_rise_clip_replay_at = math.huge   -- don't loop-replay until we've switched to the loop clip
    S.base_owner = { name = "rise", until_clock = now + 0.6 }
    S.audition_until_clock = now + 0.3
    -- play the START clip first (establishes the pose); the painter swaps to the LOOP after the delay
    -- BRACKET THE CLIP PAINT so one press separates the two remaining suspects: if the tape
    -- ends on "about to play" the changeMotion killed us; if it reaches "clip played OK" and
    -- then dies on a SIMPLE-RISE drive frame, the vertical step did.
    S.route3_simple_frame = 0
    pcall(function() griffin_rise_crash_mark(string.format("about to play rise clip b%s:%s",
        tostring(S.route3_rise_clip_bank), tostring(start_clip >= 0 and start_clip or loop_clip))) end)
    if start_clip >= 0 then
        pcall(function() play_griffin_motion(start_clip, S.route3_rise_clip_bank, true, "rise") end)
    else
        pcall(function() play_griffin_motion(loop_clip, S.route3_rise_clip_bank, true, "rise") end)
        S.route3_rise_clip_looped = true; S.route3_rise_clip_replay_at = now + 0.7
    end
    pcall(function() griffin_rise_crash_mark("rise clip played OK") end)
end

function route3_rise_tick()
    if C.route3_rise_enabled == false then return end
    local now = os.clock()
    if S.mounted ~= true or S.airborne ~= true then
        S.route3_rise_btn = false
        S.route3_simple_rise_until = 0.0
        S.route3_simple_dive_until = 0.0
        S.route3_rise_clip_until = 0.0
        if type(S.base_owner) == "table" and S.base_owner.name == "rise" then S.base_owner = nil end
        if route3_quick_burst_active() then route3_quick_burst_end("dismounted") end
        return
    end
    local down = S.route3_rise_action_down == true
    local names = tostring(C.route3_rise_buttons or ""):gsub("%s+", "")
    if not down and names ~= "" then pcall(function() down = raw_gamepad_button_down(names) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_rise_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down and S.route3_rise_btn ~= true then
        local cd_ok = now >= (tonumber(S.route3_rise_cd_at) or 0.0)
        -- not during specials that own the pose, never while the takeoff lock holds,
        -- and NEVER during a landing sequence (two systems fighting the flight state)
        local busy = griffin_grab_active() or griffin_divebomb_active()
            or griffin_gustair_active() or (tonumber(S.route3_takeoff_lock_until) or 0.0) > now
            or S.route3_landing_requested == true or griffin_dogfight_active()
            or S.route3_live_window ~= nil or S.route3_node_exit_until ~= nil
            or now < (tonumber(S.route3_attack_recover_until) or 0.0)
        if not busy then
            pcall(function() busy = griffin_node_lockout_active(now) == true end)
        end
        -- ⛔ DESCEND-LOOP ALTITUDE GATE v3 (2026-08-07). v2's mid-branch return left a HALF-
        -- ARMED rise state (Aurora's "weird ground idle pose" on double press) and used the
        -- depth slider (71m!) as the bar -- which her cruising height never clears ("stopped
        -- forever"; the timed dive path actually covers ~25m, the depth slider is a fiction
        -- there). Clean pre-check BEFORE any state arms, with its own honest tunable bar.
        local dive_refused = false
        if cd_ok and not busy and S.raw_descend_down == true then
            pcall(function()
                local _, go2 = reacquire_griffin()
                local p2 = go2 and transform_pos(go2)
                local gy2 = p2 and route3_ground_y_robust(go2, tonumber(p2.y))
                if p2 and gy2 then
                    local need = math.max(2.0, tonumber(C.route3_descend_loop_min_agl) or 25.0)
                    local agl = (tonumber(p2.y) or 0.0) - gy2
                    if agl < need then
                        dive_refused = true
                        S.route3_rise_cd_at = now + 0.3
                        S.route3_rise_status = string.format("descend loop refused: %.0fm up, need %.0fm", agl, need)
                        S.route3_rise_status_until = now + 2.5
                    end
                end
            end)
        end
        if cd_ok and not busy and not route3_quick_burst_active() and not dive_refused then
            -- DIRECTION at press: holding the descend button = quick DIVE, otherwise quick RISE
            S.route3_rise_dir = (S.raw_descend_down == true) and -1.0 or 1.0
            S.route3_rise_move_marked = nil
            S.route3_rise_frame = 0
            griffin_rise_crash_mark("PRESS dir=" .. tostring(S.route3_rise_dir))
            -- Old configs still contain the two native audition nodes. They are read only for the
            -- crash tape now: both actions proved non-cancellable and are never requested here.
            local node = S.route3_rise_dir < 0 and tostring(C.route3_rise_node_down or "")
                or tostring(C.route3_rise_node_up or "")
            node = node:gsub("%s+", "")
            griffin_rise_crash_mark("retired-node=" .. (node ~= "" and node or "(none)"))
            if S.route3_rise_dir > 0 then
                -- The special rise controller is RETIRED. It CTD'd after a successful first
                -- frame through three different ownership schemes. Treat A as a timed hold of
                -- the already-proven ordinary ascend input and touch nothing else.
                local dur = math.max(0.2, tonumber(C.route3_rise_secs) or 1.75)
                S.route3_simple_rise_until = now + dur
                S.route3_rise_cd_at = S.route3_simple_rise_until
                    + math.max(0.0, tonumber(C.route3_rise_cooldown) or 0.4)
                S.route3_rise_status = string.format("safe rise: ordinary ascend %.2fs", dur)
                S.route3_rise_status_until = S.route3_rise_cd_at
                route3_rise_start_clip(1.0, dur, now)   -- climbing wing-beat clip over the rise window
                griffin_rise_crash_mark("SAFE RISE ordinary-input + climb clip")
            elseif C.route3_rise_safe_choreo ~= false then
                -- Quick DESCEND = STRAIGHT DOWN, mirroring the rise (Aurora: her downward node only makes
                -- sense as a strict drop). Timed hold of the ordinary DESCEND input, no forward swoop.
                local dur = math.max(0.2, tonumber(C.route3_rise_secs) or 1.75)
                S.route3_simple_dive_until = now + dur
                S.route3_rise_cd_at = S.route3_simple_dive_until + math.max(0.0, tonumber(C.route3_rise_cooldown) or 0.4)
                S.route3_rise_status = string.format("safe dive: ordinary descend %.2fs", dur)
                S.route3_rise_status_until = S.route3_rise_cd_at
                route3_rise_start_clip(-1.0, dur, now)   -- dive clip + fires the picked dive NODE straight down
            else
                -- Explicit compatibility fallback: the older movement-only burst. The retired
                -- node values and route3_rise_node_force flag remain ignored.
                local dur = math.max(0.2, tonumber(C.route3_rise_secs) or 1.0)
                S.route3_rise_move_at = now
                S.route3_rise_t0 = now
                S.route3_rise_until = now + dur
                S.route3_rise_hold_until = S.route3_rise_until
                S.route3_rise_cd_at = S.route3_rise_until + math.max(0.0, tonumber(C.route3_rise_cooldown) or 0.4)
                S.route3_rise_status = S.route3_rise_dir < 0 and "dive (movement only)" or "rise (movement only)"
                route3_rise_start_clip(S.route3_rise_dir, dur, now)   -- climb/dive clip over the burst
                if S.route3_rise_dir > 0 then pcall(function() route3_flap_after_action() end) end
            end
        end
    end
    -- PAINT the climb/dive clip over the burst window (parked so the flap can't stomp it): START clip
    -- first, swap to the LOOP after route3_rise_clip_start_secs, re-play the loop on a throttle so a
    -- finished loop re-arms without frame-0 freezing; hand the base layer back to flight at the end.
    if C.route3_rise_clip_enabled ~= false and S.airborne == true
        and (tonumber(S.route3_rise_clip_until) or 0.0) > now then
        S.base_owner = { name = "rise", until_clock = now + 0.6 }
        S.audition_until_clock = now + 0.3
        local rbank = math.floor(tonumber(S.route3_rise_clip_bank) or 50)
        local rclip = math.floor(tonumber(S.route3_rise_clip) or -1)
        if S.route3_rise_clip_looped ~= true and now >= (tonumber(S.route3_rise_clip_loop_at) or math.huge) then
            S.route3_rise_clip_looped = true
            S.route3_rise_clip_replay_at = now + 0.25
            pcall(function() play_griffin_motion(rclip, rbank, true, "rise") end)
        elseif S.route3_rise_clip_looped == true and now >= (tonumber(S.route3_rise_clip_replay_at) or math.huge) then
            -- ⭐ v11 FRAME-AWARE REPLAY (2026-08-12): the old fixed 0.7s replay restarted the
            -- clip from frame 0 every 0.7s -- fine for the griffin's short bank-50 bursts,
            -- but it CHOPS the drake's long com_flight_loop ("repeats a lot, goes into a
            -- t-pose sometimes" on video). Same recipe as the predation L0 driver: repaint
            -- ONLY when the layer lost our clip or the clip genuinely reached its end.
            S.route3_rise_clip_replay_at = now + 0.25   -- read cadence, not restart cadence
            local lost, wrap = false, false
            pcall(function()
                local ch = reacquire_griffin()
                local m = ch and ch:call("get_Motion")
                local l = m and m:call("getLayer", 0)
                if not l then return end
                local mid = tonumber(l:call("get_MotionID")) or -1
                local endf = tonumber(l:call("get_EndFrame")) or 0.0
                local fr = tonumber(l:call("get_Frame")) or 0.0
                lost = (mid ~= rclip)
                wrap = (not lost) and endf > 0.0 and fr >= endf - 8.0
                -- re-loop by SEEK, never changeMotion (flap's own law: "no clip restarts").
                -- Every changeMotion on the ridden body is a knock/attach-jolt suspect.
                if wrap then l:call("set_Frame", 0.0) end
            end)
            if lost then pcall(function() play_griffin_motion(rclip, rbank, true, "rise") end) end
        end
    elseif (tonumber(S.route3_rise_clip_until) or 0.0) > 0.0 and now >= (tonumber(S.route3_rise_clip_until) or 0.0) then
        S.route3_rise_clip_until = 0.0
        if type(S.base_owner) == "table" and S.base_owner.name == "rise" then S.base_owner = nil end
        pcall(function() route3_restore_flight_base() end)
    end
    -- ⭐ WINDOW-END RETIRE (2026-08-11, per-species): with the full-window paint protection the
    -- travel node no longer gets stomped -- so nothing ends it, and it keeps natively flying her
    -- past the burst until the 8s lockout ceiling = a SECOND un-commanded ascend (Aurora: "it
    -- does one ascend, camera back to normal, then again"). Release the lock the moment the
    -- burst window closes; the restore-consume below then arms the normal exit pump.
    -- ⛔ Per-species OFF by default: the griffin's LoopTheLoop MUST outlive its 1.75s window
    -- (the loop takes ~4s) -- only species with sustained travel nodes (drake) turn this on.
    if C.route3_rise_retire_at_window == true and S.route3_node_lock_at ~= nil
        and tostring(S.route3_node_lock_src or "") == "rise" then
        local w = math.max(tonumber(S.route3_simple_rise_until) or 0.0,
            tonumber(S.route3_simple_dive_until) or 0.0)
        if w > 0.0 and now >= w then
            S.route3_node_lock_at = nil
            S.route3_node_lock_status = "released (rise window ended)"
            S.route3_node_lock_restore = true
        end
    end
    -- ⭐ Consume the lockout's release flag: give the base layer back exactly once, a tick after
    -- the node ended, so she can't hold the node's final pose if a restore was swallowed by the lock.
    if S.route3_node_lock_restore == true then
        S.route3_node_lock_restore = nil
        if type(S.base_owner) == "table" and S.base_owner.name == "rise" then S.base_owner = nil end
        -- ⛔⛔ GROUNDED RETIRE (2026-08-07, Aurora's repro: pounce → take off → loop → "camera
        -- goes crazy and griffin doesn't respond"): this restore path is an AIR tool. On the
        -- pounce's GROUNDED end it painted the flight glide onto her standing body AND armed
        -- the exit pump below -- which then spent 1.5s shoving her FSM into SoaringFlight,
        -- OUTLIVING the 0.8s post-landing recover that had just parked her properly. She was
        -- left standing in the dirt with her FSM in a flight node, and the next takeoff+loop
        -- inherited the lie. Grounded = the post-landing recover owns the neutral; do NOTHING.
        local grounded_retire = (S.mounted == true and S.airborne ~= true)
        if grounded_retire then
            S.route3_node_exit_status = "(grounded retire: recover owns the neutral)"
        else
        -- ⭐ RISE-NODE HOLD (2026-08-11, drake round 5): TRAVEL nodes (FlightPathTraceTarget /
        -- FlightTarget) self-exit almost immediately when fired with no target to trace -- fc
        -- tape: fired at 18:52:23, retired to Wait the same second = "doesn't last long enough".
        -- While the rise/dive burst window is still open, RE-FIRE the node instead of retiring:
        -- the burst owns the movement window, the node owns the look. No flight-base repaint on
        -- this path (a fresh forced clip HIDES a node's animation -- the Puppeteer tape law).
        -- Throttle-capped so an instantly-rejecting node cannot machine-gun requests.
        local hold_until = math.max(tonumber(S.route3_simple_rise_until) or 0.0,
            tonumber(S.route3_simple_dive_until) or 0.0)
        local hold_node = tostring(S.route3_node_lock_leaf or "")
        if C.route3_rise_hold_node ~= false and tostring(S.route3_node_lock_src or "") == "rise"
            and C.route3_rise_retire_at_window == true   -- ⛔ per-species: griffin's LoopTheLoop
            -- FSM flickers mid-loop and an ungated hold RE-FIRED it = double loops (08-11 field)
            and hold_node ~= "" and hold_until > now and S.airborne == true
            and (tonumber(S.route3_rise_hold_fires) or 0) < 12 then
            S.route3_rise_hold_fires = (tonumber(S.route3_rise_hold_fires) or 0) + 1
            pcall(function() request_griffin_action(hold_node, 4) end)
            pcall(function() request_griffin_action(hold_node, 0) end)
            pcall(function() griffin_node_lockout_begin(hold_node, now, "rise", true) end)
            -- refresh the paint protection to the window edge so the flap repaint can't stomp
            -- the re-fired node either
            S.base_owner = { name = "rise", until_clock = math.max(hold_until, now + 0.6) }
            S.audition_until_clock = math.max(hold_until, now + 0.3)
            S.route3_node_exit_status = string.format("hold re-fire #%d: %s",
                tonumber(S.route3_rise_hold_fires) or 0, hold_node)
        else
        pcall(function() route3_restore_flight_base() end)
        -- ⭐⭐⭐ RETIRE THE NODE (2026-08-04). THE root cause of the "permanent" rider displacement,
        -- found by Aurora's before/after probe rather than by me guessing:
        --     fsm before = SubUniqueAttack.Ch253000WingThunderAttackAir   (stuck from an earlier move)
        --     fsm after  = Fly.Flight.Ch253LoopTheLoopFlight              (STILL IN THE LOOP NODE)
        -- Nothing ever handed her back to a neutral flight state, so she sat in a residual loop
        -- pose forever. The probe's discriminator nailed it: SPINE-from-ROOT and RIDER-from-BODY
        -- both shifted by the SAME (+0.01 -0.43 +0.00), i.e. the shared input -- the seat joint --
        -- moved. Both riders were following her correctly; SHE was the thing left in the wrong pose.
        --
        -- It also explains "LoopTheLoop isn't the default": firing LoopTheLoop while she is ALREADY
        -- in LoopTheLoop is a no-op, so the second press did visibly nothing and looked unset.
        --
        -- ⛔ requestAction, NEVER setCurrentNode -- setCurrentNode onto an air node is a documented
        -- T-pose. Exit node is configurable because the right neutral differs per creature.
        -- ⭐ ARM THE RETRY PUMP rather than firing once. Tape from the one-shot version:
        --     exit_requested Ch253SoaringFlight | before AND after = Ch253LoopTheLoopFlight
        -- i.e. the request landed and changed NOTHING. A running node refuses to be interrupted
        -- until the reject flags are cleared, and even then it only takes on some frames (the same
        -- tape shows fsm_before = SoaringFlight on a later press, so it DOES work sometimes).
        -- That is a race, not a wall -- so retry until the FSM actually moves.
        local from_leaf = tostring(S.route3_node_lock_leaf or "")
        local live_now = "?"
        pcall(function() live_now = tostring(read_griffin_fsm_node() or "?") end)
        local loop_self_retired = tostring(S.route3_node_lock_src or "") == "rise"
            and from_leaf:find("LoopTheLoop", 1, true) ~= nil
            and live_now ~= "?" and not live_now:find(from_leaf, 1, true)
        if loop_self_retired then
            -- ⭐ NORMAL LOOP EXIT: the lockout only reaches this branch AFTER observing the node
            -- leave naturally. Forcing Locomotion.Wait anyway put a flying Griffin into a ground
            -- skeleton state, moving Spine_2 for BOTH riders and leaving them under/in her belly.
            -- The visible flight repaint above is sufficient; the emergency pump is reserved for
            -- the ceiling case where the FSM is genuinely still stuck in LoopTheLoop.
            S.route3_node_exit_until = nil
            S.route3_node_exit_from = nil
            S.route3_node_exit_tries = 0
            S.base_owner = nil
            if S.mounted == true and S.airborne == true then
                pcall(function() route3_flap_clear_overlay() end)
                S.route3_flap_phase = nil
                local fc2 = math.floor(tonumber(C.flap_takeoff_clip) or 5210)
                pcall(function() play_griffin_motion(fc2, 0, true) end)
                S.route3_dogfight_reseek_clip = fc2
                S.route3_dogfight_reseek_until = os.clock() + 1.2
            end
            local at = tonumber(S.route3_rise_recalm_at)
            if at and at > now then S.route3_rise_recalm_at = now end
            S.route3_node_exit_status = "loop self-retired -> " .. live_now
        elseif C.route3_node_exit_enabled ~= false and tostring(C.route3_node_exit_node or "") ~= "" then
            S.route3_node_exit_until = now + math.max(0.2, tonumber(C.route3_node_exit_secs) or 1.5)
            S.route3_node_exit_from = from_leaf
            S.route3_node_exit_tries = 0
        end
        end   -- (rise-node hold else-branch)
        end   -- (grounded_retire else-branch)
    end
    pcall(function() griffin_node_exit_pump(now) end)   -- retry the retire until the FSM leaves
    S.route3_rise_btn = down
    if not route3_quick_burst_active()
        and (tonumber(S.route3_rise_hold_until or S.route3_rise_until) or 0.0) <= now
        and S.route3_rise_status and now >= (tonumber(S.route3_rise_status_until) or 0.0) then
        S.route3_rise_status = nil
    end
end

function route3_gust_motion_sample(st, bank)
    local frame, ending, clip = nil, nil, nil
    pcall(function()
        local ch = reacquire_griffin()
        local motion = ch and ch:call("get_Motion")
        local layer = motion and motion:call("getLayer", 0)
        if layer and tonumber(layer:call("get_MotionBankID")) == bank then
            clip = tonumber(layer:call("get_MotionID"))
            if clip == tonumber(st.cur_clip) then
                frame = tonumber(layer:call("get_Frame"))
                ending = tonumber(layer:call("get_EndFrame"))
            end
        end
    end)
    return frame, ending, clip
end

function route3_gust_flap_damage(st, bank)
    if not st or st.phase == "ending" then return end
    local frame, ending, clip = route3_gust_motion_sample(st, bank)
    if not (frame and clip == tonumber(st.cur_clip)) then return end
    -- A looping clip's playhead wraps. That wrap—not a wall-clock timer—re-arms exactly one hit
    -- for the next visible wing cycle. Start/clip changes naturally reset the same latch.
    if st.flap_clip ~= clip or (st.flap_last_frame and frame < st.flap_last_frame - 1.0) then
        st.flap_clip = clip
        st.flap_hit_done = nil
    end
    st.flap_last_frame = frame
    local frac = st.phase == "start"
        and (tonumber(C.route3_gust_start_hit_fraction) or 0.72)
        or (tonumber(C.route3_gust_loop_hit_fraction) or 0.58)
    frac = math.max(0.05, math.min(frac, 0.95))
    local threshold = (ending and ending > 1.0) and ending * frac
        or (st.phase == "start" and 11.0 or 18.0)
    if st.flap_hit_done ~= true and frame >= threshold then
        st.flap_hit_done = true
        st.hit = {}
        route3_ground_aoe_damage(C.route3_gust_radius, C.route3_gust_damage, st.hit)
        S.route3_gust_status = string.format("gust %s wing-beat f%.0f/%.0f",
            tostring(st.phase), frame, tonumber(ending) or -1.0)
    end
end

function route3_gust_tick()
    if C.route3_gust_enabled ~= true then return end
    local down = false
    local names = tostring(C.route3_gust_buttons or ""):gsub("%s+", "")
    if names == "" then names = "west,square" end   -- contextual: X = gust when grounded, dive bomb when airborne
    pcall(function() down = raw_gamepad_button_down(names) end)
    if not down then
        local vk = math.floor(tonumber(C.route3_gust_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    local st = S.route3_gust
    local now = os.clock()
    local bank = math.floor(tonumber(C.route3_gust_bank) or 50)
    if st and S.mounted ~= true then route3_gust_end("dismount"); return end
    if down and not st then
        if route3_ground_move_blocked() then return end
        pcall(route3_face_locked_target)   -- the gust blasts TOWARD the locked foe
        S.route3_gust = { phase = "start", t0 = now, hit = {},
            cur_clip = math.floor(tonumber(C.route3_gust_start_clip) or 200) }
        S.base_owner = { name = "gust", until_clock = now + 1.0 }
        pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_gust_start_clip) or 200), bank, false, "gust") end)
        S.audition_until_clock = now + 0.6
        status(tostring(C.route3_griffin_name or "Griffin") .. " whips up a gust!")
        S.route3_gust_status = "gust starting"
        return
    end
    if not st then return end
    S.audition_until_clock = now + 0.3   -- keep the flap/idle systems parked while the gust owns the wings
    S.base_owner = { name = "gust", until_clock = now + 1.0 }   -- refresh base-layer ownership
    -- ⭐ TRACK THE RUNNER (2026-08-07, Aurora: "have the ground attack lock on follow the
    -- target as it moves -- only in terms of direction"): re-face the locked foe every tick
    -- while the gust plays; direction only, never movement.
    pcall(route3_face_locked_target)
    -- NATIVE-STOMP RECOVERY: the gate blocks OUR painters, but the native FSM doesn't go
    -- through play_griffin_motion -- if the base layer shows a foreign clip, re-assert the
    -- gust phase clip (the FACE-reassert pattern)
    if st.cur_clip then
        local live = route3_flap_layer_clip()
        if live and live ~= st.cur_clip then
            pcall(function() play_griffin_motion(st.cur_clip, bank, st.phase == "loop", "gust") end)
        end
    end
    -- Damage belongs to the visible down-beat, not to elapsed seconds. Sample before changing
    -- phases so the final beat of clip 200 cannot be lost to the 200 -> 201 transition.
    route3_gust_flap_damage(st, bank)
    if st.phase == "start" and (now - st.t0) >= math.max(0.1, tonumber(C.route3_gust_start_secs) or 0.5) then
        st.phase = "loop"
        st.cur_clip = math.floor(tonumber(C.route3_gust_loop_clip) or 201)
        st.flap_clip = nil; st.flap_last_frame = nil; st.flap_hit_done = nil
        pcall(function() play_griffin_motion(st.cur_clip, bank, true, "gust") end)
        S.route3_gust_status = "gusting (wing-synchronised)"
    end
    if (not down) and st.phase ~= "ending" then
        st.phase = "ending"
        local end_impact = math.max(0.1, tonumber(C.route3_gust_end_impact) or 1.2)
        -- Knockdown must precede the damage packet. A legacy saved value of 2.75s put the
        -- fling long after the 1.2s damage, so dead/transitioned enemies never fell over.
        local blow_at = math.max(0.1, math.min(tonumber(C.route3_gust_blow_at) or 1.15,
            math.max(0.1, end_impact - 0.05)))
        -- the END anim (202) carries the GRAND-FINALE blast late in the clip -- hold the phase
        -- (and the movement lock) long enough for the WHOLE clip, never cutting the finale
        local end_secs = math.max(math.max(0.1, tonumber(C.route3_gust_end_secs) or 2.0),
            end_impact + 0.6, blow_at + 0.6)
        st.end_t0 = now
        st.end_frame = end_secs * 30.0
        -- Fallback only. Once layer zero exposes the authored EndFrame below, the finale keys from
        -- that playhead instead and damage + knockback land as ONE event on the last large flap.
        st.finale_fallback_frame = math.max(end_impact, blow_at) * 30.0
        st.finale_frame = math.max(1.0,
            tonumber(C.route3_gust_finale_frame) or st.finale_fallback_frame)
        st.cur_clip = math.floor(tonumber(C.route3_gust_end_clip) or 202)
        st.flap_clip = nil; st.flap_last_frame = nil; st.flap_hit_done = nil
        pcall(function() play_griffin_motion(st.cur_clip, bank, false, "gust") end)
        S.route3_gust_status = "gust finale"
    end
    if st.phase == "ending" then
        -- Read the authored clip rather than racing it with wall time. The 30fps fallback keeps
        -- the move bounded if a native transition briefly hides layer zero.
        local frame, authored_end = route3_gust_motion_sample(st, bank)
        frame = frame or math.max(0.0, (now - (tonumber(st.end_t0) or now)) * 30.0)
        st.frame = frame
        if authored_end and authored_end > 1.0 then
            st.end_frame = math.max(tonumber(st.end_frame) or 0.0, authored_end)
        end
        -- This is the REAL layer-zero playhead, not elapsed time or a percentage of the clip.
        -- Aurora placed the final heavy down-beat at roughly 3s, i.e. frame 90 at game motion rate.
        -- Keeping it as an explicit authored frame makes later one-frame tuning honest and stable.
        local finale_frame = tonumber(st.finale_frame) or tonumber(st.finale_fallback_frame) or 90.0
        if st.finale_done ~= true and frame >= finale_frame then
            st.finale_done = true
            -- One authored finale transaction: the large flap hurts and launches together.
            if C.route3_gust_blow_enabled ~= false then route3_gust_finale_blow() end
            st.hit = {}
            route3_ground_aoe_damage(tonumber(C.route3_gust_end_radius) or ((tonumber(C.route3_gust_radius) or 7.0) + 2.0),
                tonumber(C.route3_gust_end_damage) or 300.0, st.hit)
            S.route3_gust_status = string.format("gust FINALE wing-beat f%.0f/%.0f",
                frame, tonumber(authored_end) or -1.0)
        end
        if frame >= (tonumber(st.end_frame) or 60.0) then route3_gust_end("done") end
    end
end

function route3_gatk_start_attack(now, chained)
    local charge = C.route3_charge_enabled ~= false
        and S.airborne ~= true
        and S.last_character_root_move_run == true
        and (tonumber(S.last_character_root_forward) or 0.0) > 0.25
    if charge then
        local start_secs = math.max(0.05, tonumber(C.route3_charge_start_secs) or 0.22)
        local rush_secs = math.max(start_secs + 0.2, tonumber(C.route3_charge_secs) or 1.35)
        S.route3_gatk = {
            t0 = now, last = now, hit = {}, hit_total = 0,
            name = "charge", charge = true, charge_phase = "start",
            loop_at = now + start_secs, charge_until = now + rush_secs,
        }
        pcall(route3_face_locked_target)
        pcall(function()
            play_griffin_motion(math.floor(tonumber(C.route3_charge_start_clip) or 306),
                math.floor(tonumber(C.route3_charge_start_bank) or 0), false)
        end)
        S.audition_until_clock = now + rush_secs + math.max(0.2, tonumber(C.route3_charge_end_secs) or 0.65)
        S.route3_gatk_status = "charge (LandDash contact attack)"
        return S.route3_gatk
    end
    S.route3_gatk_alt = not (S.route3_gatk_alt == true)
    local stomp = S.route3_gatk_alt == true
    local clip = stomp and math.floor(tonumber(C.route3_gatk_stomp_clip) or 0)
        or math.floor(tonumber(C.route3_gatk_beak_clip) or 10)
    -- Back to the original deterministic move: damage is a single Griffin-centred radius pulse
    -- after the hand-tuned number of seconds. Reading a recycled motion playhead could begin at
    -- frame 60+ and score on button-down; animated joint volumes could also miss valid targets.
    -- Neither is acceptable for a basic attack.
    local impact_secs = stomp and (tonumber(C.route3_gatk_stomp_impact) or 1.5)
        or (tonumber(C.route3_gatk_beak_impact) or 2.0)
    impact_secs = math.max(0.1, impact_secs)
    local hold_secs = math.max(tonumber(C.route3_gatk_secs) or 1.2, impact_secs + 0.35)
    S.route3_gatk = {
        t0 = now, clip = clip, hit = {}, hit_total = 0,
        name = stomp and "stomp" or "peck", stomp = stomp,
        damage = stomp and (tonumber(C.route3_gatk_damage) or 1500.0)
            or (tonumber(C.route3_gatk_peck_damage) or 1200.0),
        impact_at = now + impact_secs,
        end_at = now + hold_secs,
    }
    pcall(route3_face_locked_target)
    pcall(function()
        play_griffin_motion(clip,
            math.floor(tonumber(C.route3_gust_bank) or 50), false)
    end)
    S.audition_until_clock = now + 0.5
    S.route3_gatk_status = S.route3_gatk.name .. " (original timed attack)"
    return S.route3_gatk
end

function route3_gatk_charge_tick(st, now)
    if not (st and st.charge == true) then return false end
    local _, go = reacquire_griffin()
    if not go then S.route3_gatk = nil; return false end
    local elapsed = now - (tonumber(st.t0) or now)
    if st.charge_phase == "start" and now >= (tonumber(st.loop_at) or now) then
        st.charge_phase = "rush"
        pcall(function()
            play_griffin_motion(math.floor(tonumber(C.route3_charge_loop_clip) or 553),
                math.floor(tonumber(C.route3_charge_loop_bank) or 50), true)
        end)
    end
    local moving = S.last_character_root_move_run == true
        and (tonumber(S.last_character_root_forward) or 0.0) > 0.15
        and S.last_character_root_move_moved == true
    if st.charge_phase ~= "ending" and elapsed > 0.3 and not moving then
        st.charge_until = now -- releasing the sprint ends the attack rather than sliding damage statically
    end
    -- The dash-start is the visible wind-up/lunge. It must not score a hit before the authored
    -- charge loop has actually begun, otherwise the old button-down phantom hit returns.
    if st.charge_phase == "rush" and moving then
        local gp = transform_pos(go)
        if gp then
            local yaw = yaw_from_transform(go) or S.heading_yaw or 0.0
            local beak = nil
            pcall(function() beak = griffin_predation_joint_world_position(go, gp, "Jaw_0") end)
            if not beak then
                local fwd = math.max(0.5, tonumber(C.route3_charge_beak_forward) or 3.5)
                beak = make_position(
                    (tonumber(gp.x) or 0.0) + math.sin(yaw) * fwd,
                    tonumber(gp.y) or 0.0,
                    (tonumber(gp.z) or 0.0) + math.cos(yaw) * fwd)
            end
            local fresh = {}
            local hit_ct = route3_ground_aoe_damage(
                tonumber(C.route3_charge_radius) or 2.25,
                tonumber(C.route3_charge_damage) or 2100.0,
                st.hit, beak, fresh) or 0
            route3_gatk_contact_effects(st, fresh, hit_ct, now)
        end
    end
    if st.charge_phase ~= "ending" and now >= (tonumber(st.charge_until) or now) then
        st.charge_phase = "ending"
        st.end_at = now + math.max(0.2, tonumber(C.route3_charge_end_secs) or 0.65)
        pcall(function()
            play_griffin_motion(math.floor(tonumber(C.route3_charge_end_clip) or 554),
                math.floor(tonumber(C.route3_charge_end_bank) or 50), false)
        end)
    elseif st.charge_phase == "ending" and now >= (tonumber(st.end_at) or now) then
        S.route3_gatk = nil
        S.route3_gatk_cd_at = tonumber(st.t0) or now
        S.audition_until_clock = 0.0
        route3_flap_after_action()
        S.route3_gatk_status = string.format("charge done (contacts=%d)", tonumber(st.hit_total) or 0)
        return false
    end
    return true
end

function route3_gatk_contact_effects(st, fresh, hit_ct, now)
    if hit_ct <= 0 then return end
    st.hit_total = (tonumber(st.hit_total) or 0) + hit_ct
    local snd_ok = "-"
    if st.sound_done ~= true then
        st.sound_done = true
        local snd = math.floor(tonumber(C.route3_gatk_hit_sound_id) or 0)
        if snd > 0 then
            local sok = false
            pcall(function()
                local foe_go = nil
                for ench in pairs(fresh or {}) do foe_go = char_go(ench); break end
                sok = route3_wwise_trigger_nick(snd,
                    char_go(get_player()) or foe_go)
            end)
            snd_ok = tostring(sok)
        end
    end
    if C.route3_gatk_blowback ~= false then
        pcall(function()
            local _, ggo = reacquire_griffin()
            local gp = ggo and transform_pos(ggo)
            if not gp then return end
            for ench in pairs(fresh or {}) do
                pcall(function() route3_gust_blow_start(ench, ggo, gp, {
                    dist = math.max(0.2,
                        tonumber(C.route3_gatk_blow_dist) or 1.2),
                    up = math.max(0.0,
                        tonumber(C.route3_gatk_blow_up) or 1.8),
                    secs = 0.4, ragdoll = false,
                }) end)
            end
        end)
    end
    S.route3_gatk_status = string.format(
        "%s TIMED CONTACT t=%.2fs total=%d snd_ok=%s",
        tostring(st.name), math.max(0.0, now - (tonumber(st.t0) or now)),
        tonumber(st.hit_total) or 0, snd_ok)
end

function route3_gatk_tick()
    if C.route3_gatk_enabled ~= true then return end
    local down = false
    local names = tostring(C.route3_gatk_buttons or ""):gsub("%s+", "")
    if names == "" then names = "north,triangle" end
    pcall(function() down = raw_gamepad_button_down(names) end)
    if not down then
        local vk = math.floor(tonumber(C.route3_gatk_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end

    local now = os.clock()
    local pressed = down and S.route3_gatk_btn ~= true
    local st = S.route3_gatk
    if pressed and not st then
        local cd = math.max(0.2, tonumber(C.route3_gatk_cooldown) or 1.2)
        if not route3_ground_move_blocked()
            and (now - (tonumber(S.route3_gatk_cd_at) or -999.0)) >= cd then
            st = route3_gatk_start_attack(now, false)
        end
    end
    S.route3_gatk_btn = down == true
    st = S.route3_gatk
    if not st then return end
    if S.mounted ~= true then
        S.route3_gatk = nil
        S.audition_until_clock = 0.0
        route3_flap_after_action()
        return
    end

    S.audition_until_clock = now + 0.3
    pcall(route3_face_locked_target)
    if st.charge == true then
        route3_gatk_charge_tick(st, now)
        return
    end
    if st.impact_done ~= true and now >= (tonumber(st.impact_at) or math.huge) then
        st.impact_done = true
        local fresh = {}
        -- Keep the reliable hand-tuned impact time, but put its volume where the attack visibly
        -- lands. The old 5m root-centred disc could hurt something beside/behind a missed peck.
        local centre, radius = nil, nil
        local _, ggo = reacquire_griffin()
        local gp = ggo and transform_pos(ggo)
        if gp then
            local yaw = yaw_from_transform(ggo) or S.heading_yaw or 0.0
            local forward = st.stomp and (tonumber(C.route3_gatk_stomp_forward) or 1.8)
                or (tonumber(C.route3_gatk_peck_forward) or 3.2)
            centre = make_position(
                (tonumber(gp.x) or 0.0) + math.sin(yaw) * forward,
                tonumber(gp.y) or 0.0,
                (tonumber(gp.z) or 0.0) + math.cos(yaw) * forward)
            radius = st.stomp and (tonumber(C.route3_gatk_stomp_radius) or 3.0)
                or (tonumber(C.route3_gatk_peck_radius) or 2.4)
            -- Preserve the reliable hand-tuned impact TIME, but sample the limb that is visibly
            -- striking at that instant. Root-forward guesses miss whenever the authored attack bends
            -- the neck or plants the talons somewhere other than the locomotion heading.
            if st.stomp then
                local lp, rp = nil, nil
                pcall(function()
                    lp = griffin_predation_joint_world_position(ggo, gp, "L_PropA")
                    rp = griffin_predation_joint_world_position(ggo, gp, "R_PropA")
                end)
                if lp and rp then
                    centre = make_position((lp.x + rp.x) * 0.5, (lp.y + rp.y) * 0.5,
                        (lp.z + rp.z) * 0.5)
                end
            else
                local jaw = nil
                pcall(function() jaw = griffin_predation_joint_world_position(ggo, gp, "Jaw_0") end)
                if jaw then centre = make_position(jaw.x, jaw.y, jaw.z) end
            end
        end
        local hit_ct = route3_ground_aoe_damage(radius or C.route3_gatk_radius,
            st.damage or C.route3_gatk_damage, st.hit, centre, fresh) or 0
        route3_gatk_contact_effects(st, fresh, hit_ct, now)
    end

    if now >= (tonumber(st.end_at) or math.huge) then
        S.route3_gatk = nil
        -- Cooldown is measured from attack START, not the end of its recovery;
        -- a completed animation is therefore immediately responsive.
        S.route3_gatk_cd_at = tonumber(st.t0) or now
        S.audition_until_clock = 0.0
        route3_flap_after_action()
        S.route3_gatk_status = string.format("%s timed attack done (contacts=%d)",
            tostring(st.name), tonumber(st.hit_total) or 0)
    end
end

-- ============================ [Y] GRAB / CARRY / EAT ============================
-- Snatch a non-boss creature in her talons while flying, carry it (parented under her
-- talons so it follows automatically), then DROP it (fall damage) or LAND to EAT it.
-- Harpy-style. Player-driven, same as the swoop -- no autonomous AI needed.
function griffin_grab_active()
    return type(S.route3_grab) == "table"
end

function griffin_is_registered_enemy(ch)
    -- true if ch is in the EnemyManager enemy list (goblins, bandits, hostile humans).
    -- Friendly NPCs / townsfolk are NEVER in this list -> the clean way to exclude them.
    if not ch then return false end
    local found = false
    pcall(function()
        local em = singleton("app.EnemyManager")
        if not em then return end
        for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
            local list = nil
            pcall(function() list = em:call(getter) end)
            local n = 0
            pcall(function() n = list and list:call("get_Count") or 0 end)
            if (tonumber(n) or 0) > 0 then
                for i = 0, n - 1 do
                    local e = nil
                    pcall(function() e = list:call("get_Item", i) end)
                    if e then
                        local ec = griffin_as_character(e)
                        if same_obj(e, ch) or same_obj(ec, ch) then found = true; return end
                        local ego, cgo = char_go(e), char_go(ch)
                        if ego and cgo then
                            local ea, ca = nil, nil
                            pcall(function() ea = ego:get_address() end)
                            pcall(function() ca = cgo:get_address() end)
                            if ea and ca and ea == ca then found = true; return end
                        end
                    end
                end
                return   -- first non-empty list is the authoritative one
            end
        end
    end)
    return found
end


function route3_grab_is_grabbable(ch, allow_dead)
    if not ch then return false end
    if mounts[ch] == true or griffin_is_self(ch) or is_player_or_party(ch) then return false end
    -- exclude ANY player-faction body: pawns AND tamed companions all sit on the party
    -- group (2385506540); enemies (monster group) and wildlife (neutral) never do. Without
    -- this the Y grab could lock onto a friendly companion (Lyra) standing near a corpse
    -- instead of the corpse -- and the active-protection table only covers the current body.
    if griffin_group_hash_value(route3_ally_group_ctx(ch)) == 2385506540 then return false end
    -- corpses allowed only when the caller opts in (the mounted Y grab does; the EAT
    -- command does not -- it hunts live prey).
    if allow_dead ~= true and is_dead(ch) then return false end
    if S.route3_grab and S.route3_grab.carried == ch then return false end
    -- Runtime truth outranks the ID fallback. This also protects large creatures whose spawned
    -- GameObject has been renamed and whose exact species band is not yet in the config list.
    if route3_gust_target_is_boss(ch) then return false end
    -- too big to grab? block the boss/large-monster chXX bands (dragons/cyclops/ogres/
    -- griffins/minotaurs/garm = ch24x/ch25x/ch26x).
    local band = route3_character_band(ch)
    if band then
        for raw in tostring(C.route3_grab_block_bands or "24,25,26"):gmatch("[^,%s]+") do
            if raw == band then return false end
        end
    end
    -- NEVER grab friendly NPCs / townsfolk (Aurora: it ate Francisca on the road). Exclude
    -- HUMANS that aren't registered enemies -- i.e. citizens. Enemy humans (bandits, in the
    -- EnemyManager list) + all monsters/wildlife (non-human) stay fair game. Gating ONLY
    -- humans on the enemy list means a quirky/empty list can never wrongly block a monster.
    local is_human = false
    pcall(function() is_human = ch:get_field("<Human>k__BackingField") ~= nil end)
    if is_human and not griffin_is_registered_enemy(ch) then
        -- EnemyManager may evict a bandit as soon as it dies. Preserve the same
        -- safety rule by accepting an opted-in human corpse only when its stable
        -- group hash is the known hostile/wild-monster group; civilian corpses
        -- remain protected even after death.
        local corpse_hostile = false
        if allow_dead == true and is_dead(ch) then
            corpse_hostile = griffin_group_hash_value(route3_ally_group_ctx(ch)) == 1895570358
        end
        if not corpse_hostile then return false end
    end
    return true
end

function route3_grab_find_target(go)
    local gpos = go and transform_pos(go)
    if not gpos then return nil end
    local yaw = yaw_from_transform(go) or S.heading_yaw or 0.0
    local fx, fz = math.sin(yaw), math.cos(yaw)
    local search = math.max(6.0, tonumber(C.route3_grab_search) or 45.0)
    local best, best_d = nil, search * search
    local function consider(ch)
        -- default: LIVE prey only. An already-dead corpse ragdolls and can't be held in the talon
        -- (nothing un-kills it), so don't snatch one unless the corpse-grab option is on.
        if not route3_grab_is_grabbable(ch, C.route3_grab_allow_corpses == true) then return end
        local pos = transform_pos(char_go(ch))
        if not pos then return end
        local dx = (tonumber(pos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
        local dz = (tonumber(pos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
        local d2 = dx * dx + dz * dz
        if d2 > best_d then return end
        if (dx * fx + dz * fz) < -2.0 then return end   -- must be roughly AHEAD of her
        best, best_d = ch, d2
    end
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do pcall(function() consider(ch) end) end
    end)
    return best
end

function griffin_saddle_frame(gtf)
    -- Orthonormal saddle basis from griffin JOINT POSITIONS (render space):
    --   fwd  = Spine_1 -> Spine_3 along the back (pitch),
    --   right = left-side joint -> right-side joint if a known L/R pair resolves (roll),
    --           else up x fwd (no roll). Columns of M: x=right, y=up, z=fwd
    -- (matches the character convention: fwd=(sin yaw,0,cos yaw), right=cross(up,fwd)).
    -- Returns M (3x3), origin (anchor handled by caller), mode string; or nil.
    local ja = managed_call(gtf, "getJointByName", tostring(C.route3_saddle_fwd_a or "Spine_1"))
    local jb = managed_call(gtf, "getJointByName", tostring(C.route3_saddle_fwd_b or "Spine_3"))
    local pa = ja and managed_call(ja, "get_Position") or nil
    local pb = jb and managed_call(jb, "get_Position") or nil
    if not (pa and pb) then return nil end
    local fx = (tonumber(pb.x) or 0.0) - (tonumber(pa.x) or 0.0)
    local fy = (tonumber(pb.y) or 0.0) - (tonumber(pa.y) or 0.0)
    local fz = (tonumber(pb.z) or 0.0) - (tonumber(pa.z) or 0.0)
    local fl = math.sqrt(fx * fx + fy * fy + fz * fz)
    if fl < 0.05 then return nil end
    fx, fy, fz = fx / fl, fy / fl, fz / fl
    local rx, ry, rz, mode = nil, nil, nil, "no-roll"
    for _, pair in ipairs({ { "L_Leg_Upper", "R_Leg_Upper", "legs" },
                            { "L_Arm_Upper", "R_Arm_Upper", "wings" } }) do
        local jl = managed_call(gtf, "getJointByName", pair[1])
        local jr = managed_call(gtf, "getJointByName", pair[2])
        local pl = jl and managed_call(jl, "get_Position") or nil
        local pr = jr and managed_call(jr, "get_Position") or nil
        if pl and pr then
            local dx = (tonumber(pr.x) or 0.0) - (tonumber(pl.x) or 0.0)
            local dy = (tonumber(pr.y) or 0.0) - (tonumber(pl.y) or 0.0)
            local dz = (tonumber(pr.z) or 0.0) - (tonumber(pl.z) or 0.0)
            local dl = math.sqrt(dx * dx + dy * dy + dz * dz)
            if dl > 0.05 then
                rx, ry, rz, mode = dx / dl, dy / dl, dz / dl, pair[3]
                break
            end
        end
    end
    local ux, uy, uz
    if rx then
        -- up = fwd x right; guard against a swapped/odd pair leaving the frame upside down
        ux = fy * rz - fz * ry
        uy = fz * rx - fx * rz
        uz = fx * ry - fy * rx
        if uy < 0.0 then
            rx, ry, rz = -rx, -ry, -rz
            ux, uy, uz = -ux, -uy, -uz
        end
    else
        -- no lateral pair: right = up x fwd (flat), degenerate when the spine goes vertical
        rx = 1.0 * fz - 0.0 * fy   -- cross((0,1,0), f)
        ry = 0.0
        rz = 0.0 * fy - 1.0 * fx
        local rl = math.sqrt(rx * rx + rz * rz)
        if rl < 0.05 then return nil end
        rx, rz = rx / rl, rz / rl
        ux = fy * rz - fz * ry
        uy = fz * rx - fx * rz
        uz = fx * ry - fy * rx
    end
    local ul = math.sqrt(ux * ux + uy * uy + uz * uz)
    if ul < 0.05 then return nil end
    ux, uy, uz = ux / ul, uy / ul, uz / ul
    -- re-orthonormalize right = up x fwd
    rx = uy * fz - uz * fy
    ry = uz * fx - ux * fz
    rz = ux * fy - uy * fx
    local M = { { rx, ux, fx }, { ry, uy, fy }, { rz, uz, fz } }
    return M, mode
end

function griffin_q_to_euler_zxy(q)
    -- engine convention R = Ry@Rx@Rz (verified: paired local_rot/local_euler in skeleton dumps)
    local x = tonumber(q.x) or 0.0
    local y = tonumber(q.y) or 0.0
    local z = tonumber(q.z) or 0.0
    local w = tonumber(q.w) or 1.0
    local m12 = 2.0 * (x * y + z * w)          -- m[2][1]
    local m22 = 1.0 - 2.0 * (x * x + z * z)    -- m[2][2]
    local m23 = 2.0 * (y * z - x * w)          -- m[2][3]
    local m13 = 2.0 * (x * z + y * w)          -- m[1][3]
    local m33 = 1.0 - 2.0 * (x * x + y * y)    -- m[3][3]
    local m11 = 1.0 - 2.0 * (y * y + z * z)    -- m[1][1]
    local m31 = 2.0 * (x * z - y * w)          -- m[3][1]
    local ex = math.asin(math.max(-1.0, math.min(1.0, -m23)))
    local ey, ez
    if math.abs(math.cos(ex)) > 1e-5 then
        ey = math.atan(m13, m33)
        ez = math.atan(m12, m22)
    else
        ey = math.atan(-m31, m11)
        ez = 0.0
    end
    return ex, ey, ez
end

function griffin_pause_player_motion_layers(paused)
    -- STUDIO pause recipe: set_Speed + set_PlaySpeed + EVERY layer's speed. Top-level
    -- PlaySpeed alone left additive layers + newly-swapped clips running.
    local player = get_player()
    local motion = nil
    pcall(function() motion = player and player:call("get_Motion") end)
    if not motion then
        local pgo = char_go(player)
        motion = pgo and get_component(pgo, "via.motion.Motion") or nil
    end
    if not motion then return false end
    local sp = (paused == true) and 0.0 or 1.0
    pcall(function() motion:call("set_Speed", sp) end)
    pcall(function() motion:call("set_PlaySpeed", sp) end)
    for i = 0, 15 do
        pcall(function() motion:call("getLayer", i):call("set_Speed", sp) end)
    end
    return true
end

function griffin_rider_steady_sweep(pgo, on)
    -- studio steady port for the rider: kill the ground/IK re-solvers that fight the
    -- weld (GroundFixer = THE historic 6-session bug). Keeps Chain (hair/cloth alive is
    -- good on a rider) and RetargetRig (killing it EATS joint writes -- studio law).
    if on == true then
        S.route3_rider_steady_disabled = {}
        pcall(function()
            local comps = pgo:call("get_Components")
            for _, c in ipairs(system_array_to_table(comps) or {}) do
                local td = c and c:get_type_definition()
                local nm = td and td:get_full_name() or ""
                if nm == "via.motion.JointConstraints" or nm == "via.motion.IkLeg2"
                    or nm == "app.SlopeBodyCorrection2Leg"
                    or nm:find("GroundFixer", 1, true)
                    or nm:find("AdjustTerrain", 1, true)
                    -- AdjustPress = the engine's push-out-of-overlapping-bodies solver. The
                    -- rider sits INSIDE the griffin's silhouette every frame; its endless
                    -- failed push-outs are the prime suspect for the collision fighting +
                    -- the stuck-player rescue (fade-to-black teleport). Restored on
                    -- puppet-off with the rest of the sweep.
                    or nm == "app.AdjustPress" then
                    pcall(function() c:call("set_Enabled", false) end)
                    S.route3_rider_steady_disabled[#S.route3_rider_steady_disabled + 1] = c
                end
            end
        end)
    else
        for _, c in ipairs(S.route3_rider_steady_disabled or {}) do
            pcall(function() c:call("set_Enabled", true) end)
        end
        S.route3_rider_steady_disabled = nil
    end
    return true
end

function griffin_rider_ghost_children(pgo, on)
    -- Weapons/props are CHILD GameObjects with their OWN colliders + hit volumes --
    -- the staff on her back pokes the griffin every frame and none of the character
    -- sweeps ever touched it (round-24: hit SFX + camera shake survived the
    -- HitController kill). Walk the child transform tree once at puppet engage and
    -- ghost every collider/hit component; restore the exact set on puppet-off.
    if on == true then
        -- top-up friendly: keep the existing restore list so periodic re-sweeps
        -- (round-38) only append NEWLY-caught components
        S.route3_rider_ghost_kids = S.route3_rider_ghost_kids or {}
        local tf = pgo and pgo:call("get_Transform")
        if not tf then return end
        local function walk(node, depth)
            if depth > 6 then return end
            local child = nil
            pcall(function() child = node:call("get_Child") end)
            while child do
                pcall(function()
                    local go = child:call("get_GameObject")
                    if go then
                        for _, cn in ipairs({ "via.physics.Colliders",
                                              "via.physics.RequestSetCollider",
                                              "app.HitController" }) do
                            local c = get_component(go, cn)
                            if c then
                                local en = nil
                                pcall(function() en = c:call("get_Enabled") end)
                                if en ~= false then
                                    pcall(function() c:call("set_Enabled", false) end)
                                    S.route3_rider_ghost_kids[#S.route3_rider_ghost_kids + 1] = c
                                    S.route3_rider_ghost_new = (tonumber(S.route3_rider_ghost_new) or 0) + 1
                                end
                            end
                        end
                    end
                end)
                walk(child, depth + 1)
                local nxt = nil
                pcall(function() nxt = child:call("get_Next") end)
                child = nxt
            end
        end
        walk(tf, 0)
        if (tonumber(S.route3_rider_ghost_new) or 0) > 0 then
            pcall(function() log.info(string.format(
                "[GriffinRide] ghosted %d child collider/hit components (total tracked %d)",
                tonumber(S.route3_rider_ghost_new) or 0, #(S.route3_rider_ghost_kids or {}))) end)
        end
    else
        for _, c in ipairs(S.route3_rider_ghost_kids or {}) do
            pcall(function() c:call("set_Enabled", true) end)
        end
        S.route3_rider_ghost_kids = nil
    end
end

function route3_rider_puppet(on)
    -- PUPPET RIDE (2026-07-15, Aurora-approved mount rework): the native climb ATTACH
    -- re-solves the rider's transform downstream of every lua write -- across rounds
    -- 0-8 she always rendered at the CLIMB's solution (the grab point, in whatever
    -- cling orientation the state fancied), never at ours; the fine sliders "did
    -- nothing" because our writes were never the visual authority. So while the ride
    -- pose is active we leave the climb entirely (goblin-carry model, field-proven on
    -- a flying griffin): abort climb + think-stop + controller off + FSM off +
    -- ground/IK steady kill; motion layers stay ALIVE with L0 pinned to the neutral
    -- clip per tick (griffin_rider_neutral_motion_tick -- the taming idiom; a dead
    -- layer stack latches whatever orientation the last action froze in). The weld
    -- owns position, visual and logical. Rotation is JOINT-driven (root yaw), never
    -- the transform (round-20 law).
    local player = get_player()
    local pgo = char_go(player)
    if not (player and pgo) then return false end
    if on == true and S.route3_rider_puppet_on ~= true then
        set_think_stop(player, true)
        local abort_ok = nil
        pcall(function() abort_ok = route3_abort_native_climb(player) end)
        S.route3_rider_puppet_abort = tostring(abort_ok)
        set_character_controller_enabled(player, false)
        griffin_set_player_fsm_enabled(false)
        pcall(function()
            local human = player:call("get_Human")
            local hfsm = human and human.Fsm
            if hfsm then hfsm:set_Enabled(false); S.route3_rider_humanfsm_off = true end
        end)
        griffin_pause_player_motion_layers(false)   -- layers ALIVE; the neutral pin owns them
        griffin_rider_steady_sweep(pgo, true)
        if C.route3_rider_ghost_physics ~= false then
            pcall(griffin_rider_ghost_children, pgo, true)
        end
        S.route3_rider_yaw0 = nil   -- yaw-follow baseline re-measured once the pose is live
        S.route3_rider_yaw_delta = nil
        S.route3_rider_yaw_acc = nil
        S.route3_rider_body0 = nil
        S.route3_rider_hip_rest = nil   -- re-captured once the neutral clip is confirmed live
        S.route3_rider_ghost_rekills = 0   -- fresh per-ride escape telemetry
        S.route3_rider_ghost_note = nil
        S.route3_rider_ghost_next = 0.0
        S.route3_rec_dump_n = 0            -- fresh Recorder x-ray each ride
        S.route3_rider_microjumps = 0
        -- cache HER rollback/recorder instance addresses for the scoped skip-hooks
        pcall(function() S.route3_rb_addr = player:get_field("PosRotContextRollbacker"):get_address() end)
        pcall(function() S.route3_rec_addr = player:get_field("<PosRotRecorder>k__BackingField"):get_address() end)
        -- ROUND-47: arm the transform-write intercept (lazy hook install on first
        -- engage; addresses re-refreshed every pin pass against reload/revive churn)
        S.route3_txi_blocked = 0
        S.route3_our_write = false
        pcall(function() S.route3_txi_ch_addr = player:get_address() end)
        pcall(function() S.route3_txi_tf_addr = pgo:call("get_Transform"):get_address() end)
        if C.route3_rider_txi_enabled ~= false then
            pcall(griffin_txi_install)
            S.route3_txi_live = (S.route3_txi_tf_addr ~= nil or S.route3_txi_ch_addr ~= nil)
        else
            S.route3_txi_live = false
        end
        pcall(griffin_txi_recon_dump, player)
        S.route3_rider_puppet_on = true
        return true
    elseif on ~= true and S.route3_rider_puppet_on == true then
        -- ROUND-47: disarm the intercept FIRST -- every restore below writes her
        -- position; with TXI still live those writes would be silently skipped and
        -- she'd strand at the saddle point (work-order review blocker #2)
        S.route3_txi_live = false
        S.route3_our_write = false
        pcall(griffin_rider_ghost_children, pgo, false)
        griffin_rider_steady_sweep(pgo, false)
        griffin_pause_player_motion_layers(false)
        griffin_set_player_fsm_enabled(true)
        if S.route3_rider_humanfsm_off == true then
            pcall(function()
                local human = player:call("get_Human")
                local hfsm = human and human.Fsm
                if hfsm then hfsm:set_Enabled(true) end
            end)
            S.route3_rider_humanfsm_off = false
        end
        set_character_controller_enabled(player, true)
        set_think_stop(player, false)
        pcall(function()
            local pgo2 = char_go(player)
            for _, cn in ipairs({ "via.dynamics.Ragdoll", "app.CharacterRagdoll",
                                  "via.physics.RequestSetCollider", "via.physics.Colliders",
                                  "app.HitController", "via.physics.CharacterController",
                                  "via.motion.JointConstraints", "via.motion.IkLeg2" }) do
                local c = get_component(pgo2, cn)
                if c then pcall(function() c:call("set_Enabled", true) end) end
            end
        end)
        S.route3_rider_yaw0 = nil
        S.route3_rider_yaw_delta = nil
        -- fall-immunity grace: the dismount drop + first ground contact after the
        -- controller returns must not bill the flight as fall damage
        S.route3_rider_immunity_grace = os.clock() + 2.5
        S.route3_rider_puppet_on = false
        return true
    end
    return false
end

function griffin_rider_neutral_motion_tick()
    -- THE THIRD LEG of the proven taming player-clip trio (think-stop + FSM off +
    -- changeMotion L0 re-asserted). The ACTION system calls changeMotion directly --
    -- it kept swapping the L0 clip (fall/cling actions: no ground under a mid-air,
    -- controller-off rider) straight through both disabled FSMs and paused layers.
    -- Re-assert a neutral L0 clip and pin frame 0 EVERY tick; the last writer wins,
    -- and per-tick re-assertion makes that us (field-proven by the taming hand pose).
    local player = get_player()
    local motion = nil
    pcall(function() motion = player and player:call("get_Motion") end)
    if not motion then
        local pgo = char_go(player)
        motion = pgo and get_component(pgo, "via.motion.Motion") or nil
    end
    if not motion then return end
    -- ⭐ v14b (Aurora: "keep the grabbed-onto-the-monster position"): the LOOK and the SYSTEM
    -- are separable. The climb system stays dead in drake flight, but its POSE is just a clip
    -- the player owns: b20:100 mount-wait -- the braced two-hand grip, July-verified "upright/
    -- GOOD" (its b20:0 sibling is the spread-eagle; never pin that one). Pinned playing, so
    -- she breathes and grips instead of standing.
    local tb, tc = 0, 0
    if S.route3_air_seat_on == true
        and tostring(C.route3_air_seat_pose_mode or "cling") == "cling" then
        tb, tc = 20, 100
    end
    pcall(function()
        local layer = motion:call("getLayer", 0)
        if not layer then return end
        local bank = tonumber(layer:call("get_MotionBankID")) or -1
        local clip = tonumber(layer:call("get_MotionID")) or -1
        if bank ~= tb or clip ~= tc then
            layer:call(
                "changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                tb, tc, 0.0, 8.0, 1, 1)
        elseif type(S.route3_rider_hip_rest) ~= "table" then
            -- neutral clip confirmed live: capture Hip's seated local ONCE as the
            -- yaw-follow rest (capturing on an unconfirmed clip would bake a climb
            -- pose in; base local differs from her live stance -- round-20: live Hip
            -- rest = (-0.06,-0.27,1.57), base = (0,0,1.57))
            pcall(function()
                local pgo2 = char_go(player)
                local tf2 = pgo2 and pgo2:call("get_Transform")
                local hip = tf2 and tf2:call("getJointByName", "Hip")
                local le = hip and hip:call("get_LocalEulerAngle")
                if le then
                    S.route3_rider_hip_rest = {
                        x = tonumber(le.x) or 0, y = tonumber(le.y) or 0, z = tonumber(le.z) or 0,
                    }
                end
            end)
        end
        layer:call("set_Frame", 0.0)
        -- parked (round-14): alive layers let the fall actions visibly duel the pin
        -- (teleport/spazz loop); frozen speed + per-tick frame pin = the taming idiom.
        layer:call("set_Speed", 0.0)
    end)
    -- ⭐⭐ ROUND-17: THE RAGDOLL (goblin-carry law, finally applied to the RIDER).
    -- Fall/cling actions trigger ragdoll BLENDING: a physics sim drawn OVER the
    -- animation pose at render time. Explains everything: joint cache upright while
    -- the screen shows a dangling body; oscillation (sim vs our writes); "settles
    -- upside down" (ragdoll at rest); survives every FSM/action/transform kill
    -- (physics is independent). The carry pin re-asserts un-ragdoll EVERY frame as
    -- law -- do the same for the rider.
    pcall(function() player:call("EnableRagdoll(System.Boolean)", false) end)
    pcall(function()
        local pgo = char_go(player)
        for _, cn in ipairs({ "via.dynamics.Ragdoll", "app.CharacterRagdoll" }) do
            local c = get_component(pgo, cn)
            if c then pcall(function() c:call("set_Enabled", false) end) end
        end
    end)
    -- ROUND-16 cure (kept as insurance): via.motion.ActorMotion's FixedRootOffsetRotation
    -- is the motion system's own whole-body rotation offset, set by climb/fall actions
    -- downstream of the transform. Nothing native clears it while the puppet has every
    -- native system dead -- hold it at identity while posed.
    pcall(function()
        local pgo = char_go(player)
        local am = pgo and get_component(pgo, "via.motion.ActorMotion")
        if am then am:call("set_FixedRootOffsetRotation", make_quat_identity()) end
    end)
    -- ═══ ROUND-20 RE-GRAB KILLER ═══ Pose-off test proved the flip is NATIVE and the
    -- photo showed WHERE: slung under the belly = a CLIMB CLING. She sits INSIDE the
    -- griffin's climb volume every frame; DD2 auto-clings to a touched monster ->
    -- the game RE-GRABS her continuously (the collision/teleport spazz = the re-grab
    -- duel). Counter = the ox-carry law: colliders OFF while carried + re-abort any
    -- climb EVERY tick so a re-grab dies within a frame.
    pcall(function()
        local pgo = char_go(player)
        -- app.HitController: the hit/hurt-volume system (separate from physics
        -- colliders) -- the griffin's body rubbing her hurt volumes every frame is
        -- the prime suspect for the constant impact SFX while seated inside its
        -- silhouette. Side effect while posed: she cannot be hit (acceptable on a
        -- mount). Restored on puppet-off.
        -- via.motion.JointConstraints joined the per-tick list round-38: on storm
        -- mounts something native re-enables it CONTINUOUSLY (verifier log: one
        -- "GHOST ESCAPE re-killed" per second, all flight) -- the 1s verifier loses
        -- that tug-of-war; per-tick last-writer-wins makes the last writer us.
        -- via.motion.IkLeg2 promoted round-40: the ground-probing leg IK re-awakens
        -- right before each storm ride's first rescue -- the likely "player has no
        -- ground, call rescue" reporter
        for _, cn in ipairs({ "via.physics.RequestSetCollider", "via.physics.Colliders",
                              "app.HitController", "via.motion.JointConstraints",
                              "via.motion.IkLeg2" }) do
            local c = get_component(pgo, cn)
            if c then pcall(function() c:call("set_Enabled", false) end) end
        end
        -- ROUND-25: setCharacterControllerEnable is only the app-level BEHAVIOR flag;
        -- the via.physics.CharacterController COMPONENT keeps its capsule live in the
        -- physics scene -- the thing the press/squeeze system grinds against inside
        -- the griffin (hit SFX, camera shake, and the crush-rescue fade-to-black).
        -- Kill the component itself while posed; restored on puppet-off.
        if C.route3_rider_ghost_physics ~= false then
            local cc = get_component(pgo, "via.physics.CharacterController")
            if cc then pcall(function() cc:call("set_Enabled", false) end) end
        end
    end)
    -- ⛔ ROUND-39: THE LOST ROUND-8 LAW RESTORED -- the kill trio (think-stop +
    -- MotionFsm2 + Human.Fsm) was applied ONCE at puppet engage; round 8 said
    -- re-assert PER TICK and that got lost across the rebuild. On storm mounts
    -- something revives her FSMs mid-ride -> the action system runs underneath the
    -- pose (hit reactions = the noises, pose fight = the vibration, constraint
    -- re-enables = the JointConstraints fingerprint, action camera fx = fades).
    -- Logged when caught alive so the next storm names its own mechanism.
    pcall(function() set_think_stop(player, true) end)
    pcall(function()
        local pgo2 = char_go(player)
        local mfsm = pgo2 and get_component(pgo2, "via.motion.MotionFsm2")
        if mfsm and mfsm:call("get_Enabled") == true then
            mfsm:call("set_Enabled", false)
            pcall(function() log.info("[GriffinRide] STORM: MotionFsm2 was RE-ENABLED mid-ride -- killed") end)
        end
    end)
    pcall(function()
        local human = player:call("get_Human")
        local hfsm = human and human.Fsm
        if hfsm and hfsm:get_Enabled() == true then
            hfsm:set_Enabled(false)
            S.route3_rider_humanfsm_off = true
            pcall(function() log.info("[GriffinRide] STORM: Human.Fsm was RE-ENABLED mid-ride -- killed") end)
        end
    end)
    -- ROUND-38 GHOST VERIFIER: the one-time sweeps can be ESCAPED -- native systems
    -- re-enable components mid-ride, and whether one slips through is a per-mount
    -- coin flip (Aurora: "sometimes it works perfectly, sometimes the knocking/fade
    -- is back"). Every ~1s: re-disable any tracked component that flipped back on,
    -- LOGGING each by name (the escape list IS the diagnosis), plus a top-up
    -- re-sweep of the child tree for components that appeared after engage.
    if C.route3_rider_ghost_physics ~= false then
        pcall(function()
            local now = os.clock()
            if now < (tonumber(S.route3_rider_ghost_next) or 0.0) then return end
            S.route3_rider_ghost_next = now + 1.0
            local rekills = 0
            for _, list in ipairs({ S.route3_rider_steady_disabled, S.route3_rider_ghost_kids }) do
                for _, c in ipairs(list or {}) do
                    local en = nil
                    pcall(function() en = c:call("get_Enabled") end)
                    if en == true then
                        pcall(function() c:call("set_Enabled", false) end)
                        rekills = rekills + 1
                        pcall(function() log.info("[GriffinRide] GHOST ESCAPE re-killed: "
                            .. tostring(c:get_type_definition():get_full_name())) end)
                    end
                end
            end
            S.route3_rider_ghost_new = 0
            local pgo2 = char_go(player)
            if pgo2 then pcall(griffin_rider_ghost_children, pgo2, true) end
            local newly = tonumber(S.route3_rider_ghost_new) or 0
            if rekills > 0 or newly > 0 then
                S.route3_rider_ghost_rekills = (tonumber(S.route3_rider_ghost_rekills) or 0) + rekills + newly
                S.route3_rider_ghost_note = string.format(
                    "%d native re-enable(s)/late arrivals squashed this ride (log has names)",
                    S.route3_rider_ghost_rekills)
            end
        end)
    end
    -- ⭐ ROUND-40: THE STORM = THE STUCK-PLAYER RESCUE, finally on tape -- the
    -- VISUAL GO warps 70-200m mid-flight (to the LAST GROUND POSITION: the jump
    -- grows with flight distance), the pin yanks her back, repeat = vibration +
    -- a fade per rescue. Tell: IkLeg2 (ground-probing IK) re-awakens right before
    -- the first rescue of each storm ride. Counter: pin her last-ground-position
    -- to the CURRENT SEAT every tick, so a rescue warps her to where she already
    -- is -- displacement zero, fight over.
    -- ROUND-42/43: mark her coord safe AND feed the Recorder's safe-coord store the
    -- SEAT every tick (poison the well: whatever executor restores "to safety",
    -- safety = where she already is). One-shot log reports which feed call works.
    pcall(function()
        local rec = player:get_field("<PosRotRecorder>k__BackingField")
        if not rec then return end
        pcall(function() rec:call("set_IsSafeCoord", true) end)
        local sp = S.route3_rider_seat_last
        if type(sp) == "table" then
            local pos = make_position(sp.x, sp.y, sp.z)
            local rot = nil
            pcall(function() rot = transform_of(char_go(player)):call("get_Rotation") end)
            if rot then
                local okA = pcall(function() rec:call("recordPosRotExternal", pos, rot) end)
                local okB = false
                if not okA then okB = pcall(function() rec:call("recordPosRot", pos, rot) end) end
                if S.route3_rec_feed_logged ~= true then
                    S.route3_rec_feed_logged = true
                    pcall(function() log.info(string.format(
                        "[GriffinRide] safe-coord feed: recordPosRotExternal=%s recordPosRot=%s",
                        tostring(okA), tostring(okB))) end)
                end
            end
        end
        -- ROUND-44 (x-ray findings): clear the STALE after-fall-dead latch (true since
        -- her wakestone death, hours old -- a latched "keep restoring this character"
        -- state), poison its stored revive position with the seat, and reset the
        -- actively-growing farthest-safe history (37 entries) via the class's OWN
        -- resetHistory (never hand-drain -- empty-data warps).
        pcall(function() rec:set_field("IsAfterReviveFromFallDead", false) end)
        pcall(function()
            local sp2 = S.route3_rider_seat_last
            if type(sp2) == "table" then
                rec:set_field("PosAfterReviveFromFallDead", Vector3f.new(sp2.x, sp2.y, sp2.z))
            end
        end)
        if (tonumber(S.route3_rec_dump_n) or 0) % 60 == 30 then
            pcall(function() rec:call("resetHistory") end)
        end
        -- ROUND-43 X-RAY: one-shot field dump ~3s into the ride -- after a rescue,
        -- the field holding the placement coords identifies the storage to overwrite
        S.route3_rec_dump_n = (tonumber(S.route3_rec_dump_n) or 0) + 1
        if S.route3_rec_dump_n == 400 then
            local out = {}
            local td = rec:get_type_definition()
            for _, f in ipairs(td:get_fields()) do
                local n = tostring(f:get_name())
                local ok, v = pcall(function() return rec:get_field(n) end)
                local s = ok and tostring(v) or "?"
                pcall(function()
                    if v and v.x ~= nil then
                        s = string.format("(%.1f,%.1f,%.1f)", tonumber(v.x) or 0, tonumber(v.y) or 0, tonumber(v.z) or 0)
                    end
                end)
                out[#out + 1] = n .. "=" .. s
            end
            pcall(function() log.info("[GriffinRide] Recorder fields: " .. table.concat(out, " | ")) end)
        end
    end)
    -- ⛔ ROUND-45: 339 micro-jumps/ride through EVERY hook = the profile of exactly
    -- one enemy in this saga -- the NATIVE CLIMB ATTACH (round 9: "re-solves the
    -- rider's transform downstream of all lua writes"). On coin-flip mounts it
    -- survives the engage race; abort alone doesn't kill a running attach. Hard
    -- suppression of the climb CONTROLLER itself, per tick.
    pcall(function()
        local ctrl = get_climb_ctrl(player)
        if ctrl then
            call_bool_methods(ctrl, false, {
                "set_Enabled", "setEnable", "set_Enable", "set_IsEnable", "set_IsActive",
            })
        end
    end)
    pcall(function() route3_abort_native_climb(player) end)
    -- ROUND-33 FALL-DEATH FIX: the game cannot track "airborne" on a rider whose
    -- controller/FSM are dead and whose logical body rides above the seat -- at
    -- touchdown it settled the WHOLE FLIGHT's altitude as one lethal fall (log
    -- 12:20:14: "landed" -> "rider died" 107ms apart). Ride = damage-immune
    -- (the grab-carry immunity trio), released via a grace window after dismount
    -- so the landing itself can't bill her either.
    -- ⛔⛔ 08-09 r79 -- THIS IS WHY NOTHING CAN HURT YOU ON A HORSE.
    -- (Aurora, repeatedly: "the ogre doesn't target me or my horse... I'm not
    -- getting hit or seeing any hit reactions", and it survived enabling the
    -- rider's HitController, which is what sent me hunting.)
    -- route3_grab_set_immunity sets set_IsDamageZero / set_IsIgnoreDamageHit /
    -- set_DamageCollisionOff -- BLANKET immunity to everything, for the whole
    -- ride. HitController on or off is irrelevant against IsDamageZero.
    -- It was added for a real bug (round 33): a rider whose controller and FSM
    -- are dead cannot be tracked as airborne, so the engine settled an entire
    -- flight's altitude as one lethal fall at touchdown.
    -- ⭐ But that specific problem now has a TARGETED fix -- the r66 fall shield
    -- scales damage types 14/15 (fall) while mounted, in calcDamageReaction --
    -- so the blanket is no longer the only thing standing between the rider and
    -- a bogus fall death. Default OFF so mounted combat actually exists.
    -- ⚠ IF YOU START DYING ON LANDING FROM LONG RIDES, this is the switch:
    -- route3_ride_damage_immune = true restores the old blanket exactly.
    if C.route3_ride_damage_immune == true then
        pcall(function() route3_grab_set_immunity(player, true) end)
    end
end

function griffin_camera_probe(label)
    -- CAMERA SITUATION PROBE (round-36): the game's own MONSTER-CLIMB camera (the
    -- usable one from the pre-puppet mount) is selected by some state the camera
    -- system reads. Dump every camera-ish component's state/situation/mode getter
    -- VALUES so two dumps (standing vs climbing) diff to the exact field to force.
    local out = { label = tostring(label or ""), clock = os.clock(), sources = {} }
    -- ROUND-51d: record the SHOT GEOMETRY too (Aurora: the oxcart cam does authored
    -- tracking shots -- where the camera physically sits per shot is half the prize)
    pcall(function()
        local cam = sdk.get_primary_camera()
        local cgo = cam and cam:call("get_GameObject")
        local tf = cgo and cgo:call("get_Transform")
        local p = tf and tf:call("get_Position")
        local r = tf and tf:call("get_Rotation")
        if p then out.camera_pos = { x = p.x, y = p.y, z = p.z } end
        if r then out.camera_rot = { x = r.x, y = r.y, z = r.z, w = r.w } end
        pcall(function() out.camera_fov = cam:call("get_FOV") end)
        local pgo = char_go(get_player())
        local pp = pgo and transform_pos(pgo)
        if pp then out.player_pos = { x = pp.x, y = pp.y, z = pp.z } end
    end)
    local function harvest(obj, tag)
        local rec = { tag = tag, values = {}, methods = {} }
        pcall(function()
            local td = obj:get_type_definition()
            rec.type = td:get_full_name()
            local t = td
            while t do
                pcall(function()
                    for _, m in ipairs(t:get_methods()) do
                        local n = m:get_name() or ""
                        local lo = n:lower()
                        if lo:find("state") or lo:find("situation") or lo:find("mode")
                            or lo:find("climb") or lo:find("dist") or lo:find("zoom")
                            or lo:find("ride") or lo:find("mount") or lo:find("type") then
                            local np = 0
                            pcall(function() np = m:get_num_params() end)
                            if np == 0 and n:sub(1, 4) == "get_" then
                                local okv, v = pcall(function() return obj:call(n) end)
                                if okv then rec.values[n] = tostring(v) end
                            elseif lo:find("set_", 1, true) == 1 or n:sub(1, 4) == "set_" then
                                rec.methods[#rec.methods + 1] = n .. "/" .. tostring(np)
                            end
                        end
                    end
                end)
                t = t:get_parent_type()
            end
        end)
        out.sources[#out.sources + 1] = rec
    end
    -- the camera GameObject's components -- ALL of them (round-51c: the round-37
    -- harvest was thin because of the name filter; the oxcart/jack camera's
    -- controller may not carry "camera" in its type name)
    pcall(function()
        local cam = sdk.get_primary_camera()
        local cgo = cam and cam:call("get_GameObject")
        for _, c in ipairs(system_array_to_table(cgo:call("get_Components")) or {}) do
            local nm = ""
            pcall(function() nm = c:get_type_definition():get_full_name() end)
            harvest(c, "camGO:" .. nm)
        end
    end)
    -- camera-ish components on the PLAYER
    pcall(function()
        local pgo = char_go(get_player())
        for _, c in ipairs(system_array_to_table(pgo:call("get_Components")) or {}) do
            local nm = ""
            pcall(function() nm = c:get_type_definition():get_full_name() end)
            if nm:lower():find("camera") then harvest(c, "playerGO:" .. nm) end
        end
    end)
    -- likely camera singletons + one level of their OBJECT FIELDS (the active
    -- situation/controller objects live behind fields, whatever their type names)
    for _, sn in ipairs({ "app.CameraManager", "app.MainCameraController",
                          "app.PlayerCameraController", "app.CameraSituationManager" }) do
        pcall(function()
            local s = sdk.get_managed_singleton(sn)
            if not s then return end
            harvest(s, "singleton:" .. sn)
            local td = s:get_type_definition()
            for _, f in ipairs(td:get_fields()) do
                pcall(function()
                    local v = s:get_field(f:get_name())
                    if type(v) == "userdata" and v.get_type_definition then
                        local vt = tostring(v:get_type_definition():get_full_name() or ""):lower()
                        if vt:find("camera") or vt:find("situation") or vt:find("controller") then
                            harvest(v, "singleton:" .. sn .. "." .. tostring(f:get_name()))
                        end
                    end
                end)
            end
        end)
    end
    local fname = MOD .. "_camera_probe_" .. tostring(label or "x") .. ".json"
    json.dump_file(fname, out)
    S.route3_campr_status = string.format("dumped %d camera sources -> %s", #out.sources, fname)
    pcall(function() log.info("[GriffinRide] camera probe: " .. S.route3_campr_status) end)
end

function griffin_camrec_tick()
    -- 🎥 ROUND-51e (Aurora): CONTINUOUS camera recorder -- tick the panel box, ride
    -- the oxcart as long as you like, untick to save. Geometry track = cam
    -- pos/rot/FOV + player pos at 3 Hz (the full tracking-shot choreography);
    -- CUT detection = camera jumping >3m between samples -> full state harvest per
    -- distinct shot (griffin_camera_probe "rec_cut_N", capped at 12).
    if S.route3_camrec_on ~= true then return end
    local now = os.clock()
    if now < (tonumber(S.route3_camrec_next) or 0.0) then return end
    S.route3_camrec_next = now + 0.33
    local rec = S.route3_camrec
    if type(rec) ~= "table" then
        rec = { started = now, samples = {}, cuts = 0 }
        S.route3_camrec = rec
    end
    if #rec.samples >= 2400 then
        S.route3_camrec_status = "recorder FULL (~13min) -- untick to save"
        return
    end
    pcall(function()
        local cam = sdk.get_primary_camera()
        local cgo = cam and cam:call("get_GameObject")
        local tf = cgo and cgo:call("get_Transform")
        local p = tf and tf:call("get_Position")
        if not p then return end
        local r = nil
        pcall(function() r = tf:call("get_Rotation") end)
        local fov = nil
        pcall(function() fov = cam:call("get_FOV") end)
        local pgo = char_go(get_player())
        local pp = pgo and transform_pos(pgo)
        local s = {
            t = now - rec.started,
            cam = { x = p.x, y = p.y, z = p.z },
            rot = r and { x = r.x, y = r.y, z = r.z, w = r.w } or nil,
            fov = fov,
            player = pp and { x = pp.x, y = pp.y, z = pp.z } or nil,
        }
        local last = rec.samples[#rec.samples]
        rec.samples[#rec.samples + 1] = s
        if last and last.cam then
            local dx = s.cam.x - last.cam.x
            local dy = s.cam.y - last.cam.y
            local dz = s.cam.z - last.cam.z
            if (dx * dx + dy * dy + dz * dz) > 9.0 and (tonumber(rec.cuts) or 0) < 12 then
                rec.cuts = (tonumber(rec.cuts) or 0) + 1
                s.cut = rec.cuts
                pcall(griffin_camera_probe, "rec_cut_" .. rec.cuts)
            end
        end
        S.route3_camrec_status = string.format("recording: %d samples, %d cut(s), %.0fs",
            #rec.samples, tonumber(rec.cuts) or 0, now - rec.started)
    end)
end

function griffin_mount_camera_apply()
    if iris_puppet_seat_active() then return end -- 07-24: the puppet seat brings its own chase cam
    -- MOUNT CAMERA (round-33): a custom chase camera that OWNS the view while
    -- mounted, applied in the MainCameraController.lateUpdate post-hook (the
    -- IrisCreatureCam recipe). Kills the native camera's collision fight with the
    -- griffin's bulk in one stroke: the vibration, the occlusion fade-to-black,
    -- and the muffled audio (the listener rides the camera) were all the native
    -- solver losing against a giant feathered hitbox. Camera-only; render space;
    -- looks along -Z (engine camera convention, zfwd = -1 in IrisCreatureCam).
    if C.route3_mountcam_enabled == false then S.route3_mountcam_state = nil; return end
    -- gate on MOUNTED only (not puppet): the camera owns the view regardless of how the rider is posed.
    -- Requiring puppet meant it never fired on the native-climb mount (the live default ride).
    if not (S.mounted == true) then
        S.route3_mountcam_state = nil
        S.route3_mountcam_fpyaw = nil
        return
    end
    local _, ggo = reacquire_griffin()
    local gtf = ggo and transform_of(ggo)
    local gp = gtf and gtf:call("get_Position")
    if not gp then return end
    local yaw = yaw_from_transform(ggo) or 0.0
    local a = math.max(0.02, math.min(1.0, tonumber(C.route3_mountcam_smooth) or 0.12))
    local camx, camy, camz, dx, dy, dz
    if C.route3_mountcam_first == true then
        -- FIRST PERSON: camera pinned to her Head_0 joint (her body renders as a
        -- full model, so arms/legs/griffin-neck are all genuinely visible). Yaw is
        -- SMOOTHED griffin heading, not head rotation -- head bob stays out of the
        -- view axis. Position is raw (glued to the skull, else it reads detached).
        local player = get_player()
        local pgo = char_go(player)
        local ptf = pgo and pgo:call("get_Transform")
        local hd = ptf and ptf:call("getJointByName", "Head_0")
        local hp = hd and hd:call("get_Position")
        if not hp then return end
        local fy = S.route3_mountcam_fpyaw
        if type(fy) ~= "number" then fy = yaw end
        local dyaw = math.atan(math.sin(yaw - fy), math.cos(yaw - fy))
        fy = fy + dyaw * math.max(a, 0.2)
        S.route3_mountcam_fpyaw = fy
        -- RIGHT-STICK FREE-LOOK: the mod owns the camera so the native RS look is dead -- read the raw
        -- right stick ourselves and offset the view yaw/pitch by it. Accumulates + clamps; yaw gently
        -- recenters to forward when the stick is idle so you can always find the griffin's heading again.
        local lyaw = tonumber(S.route3_mountcam_lookyaw) or 0.0
        local lpit = tonumber(S.route3_mountcam_lookpit) or 0.0
        local nowc = os.clock()
        local ldt = 0.016
        local llt = tonumber(S.route3_mountcam_look_last)
        if llt then ldt = math.max(0.001, math.min(0.05, nowc - llt)) end
        S.route3_mountcam_look_last = nowc
        local rx, rz = 0.0, 0.0
        pcall(function() rx, rz = scout_read_axis_R() end)
        local sens = math.rad(tonumber(C.route3_mountcam_look_sens) or 130.0)
        local invy = (C.route3_mountcam_look_invert_y == true) and -1.0 or 1.0
        if math.abs(rx) > 0.12 or math.abs(rz) > 0.12 then
            lyaw = lyaw + rx * sens * ldt
            lpit = lpit + rz * sens * ldt * invy
        else
            lyaw = lyaw - lyaw * math.min(1.0, ldt * 2.0)   -- idle: ease yaw back to forward (pitch holds)
        end
        local ymax = math.rad(tonumber(C.route3_mountcam_look_yaw_max) or 150.0)
        local pmax = math.rad(tonumber(C.route3_mountcam_look_pitch_max) or 70.0)
        if lyaw > ymax then lyaw = ymax elseif lyaw < -ymax then lyaw = -ymax end
        if lpit > pmax then lpit = pmax elseif lpit < -pmax then lpit = -pmax end
        S.route3_mountcam_lookyaw = lyaw
        S.route3_mountcam_lookpit = lpit
        local vyaw = fy + lyaw
        local ffx, ffz = math.sin(vyaw), math.cos(vyaw)
        local fwdo = tonumber(C.route3_mountcam_fp_fwd) or 0.22
        local upo = tonumber(C.route3_mountcam_fp_up) or 0.08
        camx = (tonumber(hp.x) or 0) + ffx * fwdo
        camy = (tonumber(hp.y) or 0) + upo
        camz = (tonumber(hp.z) or 0) + ffz * fwdo
        local pit = math.rad(tonumber(C.route3_mountcam_fp_pitch_deg) or 0.0) + lpit
        dx = ffx * math.cos(pit)
        dy = math.sin(pit)
        dz = ffz * math.cos(pit)
        S.route3_mountcam_state = nil
    else
        -- CHASE: smoothed follow behind/above the griffin
        local fx, fz = math.sin(yaw), math.cos(yaw)
        local rgx, rgz = math.cos(yaw), -math.sin(yaw)
        local dist = tonumber(C.route3_mountcam_dist) or 9.0
        local h = tonumber(C.route3_mountcam_height) or 3.5
        local side = tonumber(C.route3_mountcam_side) or 0.0
        local lookup = tonumber(C.route3_mountcam_look_up) or 2.0
        local tx = (tonumber(gp.x) or 0) - fx * dist + rgx * side
        local ty = (tonumber(gp.y) or 0) + h
        local tz = (tonumber(gp.z) or 0) - fz * dist + rgz * side
        local st = S.route3_mountcam_state
        if type(st) ~= "table" then st = { x = tx, y = ty, z = tz } end
        st.x = st.x + (tx - st.x) * a
        st.y = st.y + (ty - st.y) * a
        st.z = st.z + (tz - st.z) * a
        S.route3_mountcam_state = st
        camx, camy, camz = st.x, st.y, st.z
        dx = (tonumber(gp.x) or 0) - camx
        dy = ((tonumber(gp.y) or 0) + lookup) - camy
        dz = (tonumber(gp.z) or 0) - camz
    end
    local l = math.sqrt(dx * dx + dy * dy + dz * dz)
    if l < 1e-6 then return end
    -- camera forward column = -look direction (engine camera looks along -Z)
    local cfx, cfy, cfz = -dx / l, -dy / l, -dz / l
    -- basis: right = up x f, up = f x right, then ROLL 180 about the view axis
    -- (negate right AND up together -- field 07-16: the un-rolled basis rendered
    -- the world upside down; negating the pair keeps the rotation proper)
    local rx2, ry2, rz2 = -cfz, 0.0, cfx
    local rl = math.sqrt(rx2 * rx2 + ry2 * ry2 + rz2 * rz2)
    if rl < 1e-6 then return end
    rx2, ry2, rz2 = rx2 / rl, ry2 / rl, rz2 / rl
    local ux = cfy * rz2 - cfz * ry2
    local uy = cfz * rx2 - cfx * rz2
    local uz = cfx * ry2 - cfy * rx2
    local q = griffin_m3_to_quat({ { rx2, ux, cfx }, { ry2, uy, cfy }, { rz2, uz, cfz } })
    pcall(function()
        local cam = sdk.get_primary_camera()
        local xf = cam and cam:call("get_GameObject"):call("get_Transform")
        if not xf then return end
        local p = xf:call("get_Position")
        p.x = camx; p.y = camy; p.z = camz
        xf:call("set_Position", p)
        local qq = xf:call("get_Rotation")
        qq.x = q.x; qq.y = q.y; qq.z = q.z; qq.w = q.w
        xf:call("set_Rotation", qq)
    end)
end

-- CYCLE the mount camera with one assignable hotkey (Aurora: switch modes without the dev panel):
-- DEFAULT (stock game cam) -> CHASE (angled 3/4 follow) -> FIRST PERSON -> back to DEFAULT.
function route3_camcycle_tick()
    if S.mounted ~= true then S.route3_camcycle_btn = false; return end   -- only while riding
    local down = false
    local names = tostring(C.route3_camcycle_buttons or ""):gsub("%s+", "")
    if names ~= "" then pcall(function() down = raw_gamepad_button_down(names) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_camcycle_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down and S.route3_camcycle_btn ~= true then
        local mode
        if C.route3_mountcam_enabled ~= true then mode = 1          -- default -> chase
        elseif C.route3_mountcam_first ~= true then mode = 2        -- chase -> first person
        else mode = 0 end                                          -- first person -> default
        if mode == 0 then
            C.route3_mountcam_enabled = false
            status("Camera: Default (game)")
        elseif mode == 1 then
            C.route3_mountcam_enabled = true; C.route3_mountcam_first = false
            status("Camera: Chase (3/4)")
        else
            C.route3_mountcam_enabled = true; C.route3_mountcam_first = true
            S.route3_mountcam_lookyaw = 0.0; S.route3_mountcam_lookpit = 0.0
            status("Camera: First Person")
        end
        pcall(save_config)
    end
    S.route3_camcycle_btn = down
end

-- Friendly name for a Windows VK (for the "press a key to bind" UI). Letters/digits/F-keys computed.
function iris_vk_name(vk)
    vk = math.floor(tonumber(vk) or 0)
    if vk == 0 then return "none" end
    if vk >= 0x41 and vk <= 0x5A then return string.char(vk) end        -- A-Z
    if vk >= 0x30 and vk <= 0x39 then return string.char(vk) end        -- 0-9
    if vk >= 0x70 and vk <= 0x7B then return "F" .. (vk - 0x6F) end     -- F1-F12
    local names = {
        [0x20] = "Space", [0x1B] = "Esc", [0x0D] = "Enter", [0x09] = "Tab", [0x08] = "Backspace",
        [0x25] = "Left", [0x26] = "Up", [0x27] = "Right", [0x28] = "Down",
        [0x2D] = "Insert", [0x2E] = "Delete", [0x24] = "Home", [0x23] = "End", [0x21] = "PgUp", [0x22] = "PgDn",
        [0xC0] = "`", [0xDB] = "[", [0xDD] = "]", [0xDC] = "\\", [0xBA] = ";", [0xDE] = "'",
        [0xBF] = "/", [0xBC] = ",", [0xBE] = ".", [0xBD] = "-", [0xBB] = "=",
    }
    return names[vk] or string.format("VK 0x%02X", vk)
end

-- Generic keyboard-bind CAPTURE (RiftSpeak-style): set S.kbcap_target = "<config key name>", then this tick
-- grabs the next key pressed and writes it there (ESC cancels). Reusable for any hotkey in the panel.
function griffin_kbcapture_tick()
    local target = S.kbcap_target
    if not target then return end
    -- ⛔ iris_kb_raw, NOT iris_kb: this runs from the config panel, i.e. ONLY while the
    -- REFramework overlay is open -- which is exactly what the input gate blocks. Reading
    -- through the gate here would mean the capture never sees a key. While a capture is
    -- armed we ALSO flag the gate so the key you are binding can't fire its old action.
    _G.IrisKeyCaptureActive = true
    if iris_kb_raw(0x1B) then
        S.kbcap_target = nil; S.kbcap_msg = "capture cancelled"; _G.IrisKeyCaptureActive = false; return
    end
    for vk = 0x08, 0xFE do
        -- skip mouse buttons + pure modifiers (Shift/Ctrl/Alt L+R) so a stray modifier can't grab the bind
        local skip = (vk <= 0x06) or vk == 0x10 or vk == 0x11 or vk == 0x12 or (vk >= 0xA0 and vk <= 0xA5)
        if not skip then
            local down = false
            pcall(function() down = iris_kb_raw(vk) end)
            if down then
                C[target] = vk
                S.kbcap_msg = iris_vk_name(vk) .. " bound"
                S.kbcap_target = nil
                pcall(save_config)
                return
            end
        end
    end
end

-- ===== OXCART CINEMATIC CAMERA PROBE (2026-07-19) =====
-- BetterOxcartsRedux skips switchCamera when controlType == 11 to DISABLE the oxcart cam -> 11 = the
-- oxcart sweeping camera. These tools: (a) DUMP the ControlType enum so we confirm 11 + see every mode
-- (any native FP/flight?); (b) TRY switching the live camera to it mid-flight to see if it frames the
-- griffin (cinematic sweep) or misframes to the absent oxcart. Reversible.
function griffin_rider_refuse_death(tag)
    -- ROUND-35: the landing kill SURVIVED the immunity trio -- DD2's lethal-fall
    -- kill is its own death STATE, not damage (the taming keep-alive's
    -- reviveFromFallDead is the dedicated antidote). A rider death while mounted
    -- or inside the dismount grace is ALWAYS our fall-bill artifact: refuse it --
    -- revive + refill HP instead of accepting it.
    -- ⛔ ORDER MATTERS (round-46): write_hp THEN reviveFromFallDead -- a character
    -- at 0 HP cannot be revived. ROUND-47 post-mortem of the 16:52 tape (alive=false
    -- 20x/s WITH the round-46 order): (a) we disable app.HitController per tick
    -- while posed and then tried to write HP through it -- re-enable it FIRST;
    -- (b) is_dead() returns true on hp<=0 ALONE, so a failed HP write reads as
    -- "revive failed" even if the revive worked -- readback hp and get_IsDead
    -- SEPARATELY (the round-18 standing law this function violated).
    local player = get_player()
    if not (player and is_dead(player)) then return false end
    local hp_before, hp_after = nil, nil
    pcall(function()
        local pgo = char_go(player)
        local hc = pgo and get_component(pgo, "app.HitController")
        if not hc then return end
        pcall(function() hc:call("set_Enabled", true) end)
        local function read_cur()
            for _, m in ipairs({ "get_Hp", "get_CurrentHitPoint" }) do
                local ok, v = pcall(function() return hc:call(m) end)
                if ok and tonumber(v) then return tonumber(v) end
            end
            return nil
        end
        hp_before = read_cur()
        local max = nil
        for _, m in ipairs({ "get_MaxHitPoint", "get_MaxHp", "get_HpMax" }) do
            local ok, v = pcall(function() return hc:call(m) end)
            if ok and tonumber(v) then max = tonumber(v); break end
        end
        if not max then return end
        for _, sig in ipairs({
            "setHp(System.Single, System.Boolean, System.Int32)",
            "setHp(System.Single, System.Boolean)",
            "setHp(System.Single)",
            "set_Hp(System.Single)",
        }) do
            pcall(function() hc:call(sig, max, true, 0) end)
        end
        hp_after = read_cur()
    end)
    pcall(function() player:call("reviveFromFallDead(System.Boolean)", false) end)
    local isdead_flag = nil
    pcall(function() isdead_flag = player:call("get_IsDead") end)
    local ok_now = not is_dead(player)
    -- the dismount-grace guard calls this 20x/s while dead -- throttle the LOG, not
    -- the attempt (the 16:52 tape was thousands of identical lines)
    local now = os.clock()
    if ok_now or now >= (tonumber(S.route3_revive_log_at) or 0.0) then
        S.route3_revive_log_at = now + 0.5
        pcall(function() log.info(string.format(
            "[GriffinRide] RIDE REVIVE (%s): hp %s -> %s, get_IsDead=%s, alive=%s",
            tostring(tag), tostring(hp_before), tostring(hp_after),
            tostring(isdead_flag), tostring(ok_now))) end)
    end
    if not ok_now and S.route3_revive_dump_done ~= true then
        -- one-shot: surface every revive/death-shaped method on the player so the
        -- next fix comes from the REAL API, not a third guess (player death flow
        -- may differ from the creature flow this recipe came from)
        S.route3_revive_dump_done = true
        pcall(function()
            local names = {}
            local td = player:get_type_definition()
            while td do
                for _, m in ipairs(td:get_methods()) do
                    local n = tostring(m:get_name() or "")
                    local lo = n:lower()
                    if lo:find("revive", 1, true) or lo:find("death", 1, true)
                        or lo:find("dead", 1, true) or lo:find("wake", 1, true) then
                        names[#names + 1] = n .. "/" .. tostring(m:get_num_params())
                    end
                end
                td = td:get_parent_type()
            end
            log.info("[GriffinRide] revive-shaped player methods: "
                .. (#names > 0 and table.concat(names, ", ") or "(none)"))
        end)
    end
    return ok_now
end

function route3_rider_cam_distance_tick()
    -- ROUND-37 CAMERA FIX (probe-driven): the native camera treats the mounted rider
    -- as a STANDING player -- LookAtDistance 5.4m mounted vs 9.95m in the (usable)
    -- monster-climb camera. app.CameraManager.set_DistanceOffset is the writable
    -- global distance knob (probe found it at 0.0): push the NATIVE camera back to
    -- climb range while mounted -- native collision, native orbit stick, native
    -- everything, just further out. Restored on dismount and script reset.
    local want = (S.mounted == true and C.route3_cam_distance_enabled ~= false)
    local mgr = nil
    pcall(function() mgr = sdk.get_managed_singleton("app.CameraManager") end)
    if not mgr then return end
    if want then
        pcall(function() mgr:call("set_DistanceOffset", tonumber(C.route3_cam_distance_offset) or 5.0) end)
        S.route3_cam_dist_set = true
    elseif S.route3_cam_dist_set == true then
        pcall(function() mgr:call("set_DistanceOffset", 0.0) end)
        S.route3_cam_dist_set = false
    end
end

function route3_rider_immunity_guard()
    -- post-dismount grace: keep fall-immunity briefly, then restore mortality
    local until_t = tonumber(S.route3_rider_immunity_grace) or 0.0
    if until_t <= 0.0 then return end
    local player = get_player()
    if not player then S.route3_rider_immunity_grace = 0.0; return end
    if os.clock() < until_t then
        pcall(function() route3_grab_set_immunity(player, true) end)
        pcall(function() griffin_rider_refuse_death("dismount grace") end)
    else
        pcall(function() route3_grab_set_immunity(player, false) end)
        S.route3_rider_immunity_grace = 0.0
    end
end

function griffin_m3_zxy(x, y, z)
    -- Rz(z) @ Rx(x) @ Ry(y) -- the CANDIDATE engine euler-SETTER order with Y
    -- innermost (the getter is verified Ry@Rx@Rz against the skeleton dump, but this
    -- engine's rotation setters have form for asymmetry: set_LocalRotation
    -- bind-composes). The runtime probe below decides which one the setter really is.
    local cy, sy = math.cos(y or 0.0), math.sin(y or 0.0)
    local cx, sx = math.cos(x or 0.0), math.sin(x or 0.0)
    local cz, sz = math.cos(z or 0.0), math.sin(z or 0.0)
    local Ry = { { cy, 0, sy }, { 0, 1, 0 }, { -sy, 0, cy } }
    local Rx = { { 1, 0, 0 }, { 0, cx, -sx }, { 0, sx, cx } }
    local Rz = { { cz, -sz, 0 }, { sz, cz, 0 }, { 0, 0, 1 } }
    return griffin_m3_mul(Rz, griffin_m3_mul(Rx, Ry))
end

function griffin_m3_to_euler_zxyouter(m)
    -- decompose R = Rz(z) @ Rx(x) @ Ry(y): m32 = sin(x); m31 = -cos(x)sin(y),
    -- m33 = cos(x)cos(y); m12 = -sin(z)cos(x), m22 = cos(z)cos(x)
    local ex = math.asin(math.max(-1.0, math.min(1.0, m[3][2])))
    local ey, ez
    if math.abs(math.cos(ex)) > 1e-5 then
        ey = math.atan(-m[3][1], m[3][3])
        ez = math.atan(-m[1][2], m[2][2])
    else
        ey = math.atan(m[1][3], m[1][1])
        ez = 0.0
    end
    return ex, ey, ez
end

function griffin_rider_log_saddle_joint_menu(gtf, wanted)
    -- ONCE per unknown saddle-joint name: enumerate the rig and surface every joint
    -- with neck/head/spine in its name -- the griffin rig uses NON-STANDARD names
    -- (R_PropA talons, L_FrontLeg_Upper...), so a guessed name fails silently into
    -- the flat fallback seat otherwise (the round-22 "Neck_1 did nothing" bug).
    S.route3_rider_joint_menu_done = S.route3_rider_joint_menu_done or {}
    if S.route3_rider_joint_menu_done[wanted] then return end
    S.route3_rider_joint_menu_done[wanted] = true
    local names = {}
    pcall(function()
        for _, j in ipairs(system_array_to_table(gtf:call("get_Joints")) or {}) do
            local n = ""
            pcall(function() n = tostring(j and j:call("get_Name") or "") end)
            local lo = n:lower()
            if n ~= "" and (lo:find("neck", 1, true) or lo:find("head", 1, true)
                or lo:find("spine", 1, true)) then
                names[#names + 1] = n
            end
        end
    end)
    S.route3_rider_joint_menu = (#names > 0)
        and ("this rig has: " .. table.concat(names, ", "))
        or "could not list this rig's joints"
    pcall(function() log.info("[GriffinRide] saddle joint '" .. tostring(wanted)
        .. "' not found; " .. S.route3_rider_joint_menu) end)
end

function griffin_rider_limbfit_apply()
    if iris_puppet_seat_active() then return end -- 07-24: puppet seat owns the limbs
    -- LIVE LIMB FIT: additive local-euler tweaks on top of the Wilds pose, applied
    -- in a LAZY-REGISTERED PrepareRendering pass so it runs AFTER rs_anim_lab's
    -- pose write (registration order: autorun-load hooks fire "G" before "r";
    -- runtime registrations append after both -- the round-1 write-order note).
    -- Slider units are degrees; L side gets (x,y,z), R side mirrors (x,-y,-z).
    if S.route3_wilds_rider_pose_active ~= true then return end
    local player = get_player()
    local pgo = char_go(player)
    local tf = pgo and pgo:call("get_Transform")
    if not tf then return end
    -- ⛔ ROUND-31 LAW: live limb sliders are FINE-TOUCH ONLY (a few degrees). Big
    -- rotations through set_LocalEulerAngle hit euler-branch badlands (field: Thigh
    -- Z 46deg mirrored fine, Thigh X 127deg exploded asymmetric) and NO runtime
    -- mirror math survives that. The POSE ITSELF is authored by the offline solver
    -- (rs_tools/rs_synth_ride_fit.py -- position-space, per-side, FK-verified),
    -- exactly like the original straddle. Same identical add on both sides: the
    -- rig's frames are pre-mirrored (clip evidence: symmetric straddle has
    -- byte-identical L/R knee locals).
    local function mirror_pair(lname, rname, dx, dy, dz)
        if dx == 0.0 and dy == 0.0 and dz == 0.0 then return end
        for _, nm in ipairs({ lname, rname }) do
            pcall(function()
                local j = tf:call("getJointByName", nm)
                local le = j and j:call("get_LocalEulerAngle")
                if not le then return end
                j:call("set_LocalEulerAngle", Vector3f.new(
                    (tonumber(le.x) or 0) + dx,
                    (tonumber(le.y) or 0) + dy,
                    (tonumber(le.z) or 0) + dz))
            end)
        end
    end
    local function rad3(kx, ky, kz)
        return math.rad(tonumber(C[kx]) or 0.0), math.rad(tonumber(C[ky]) or 0.0),
            math.rad(tonumber(C[kz]) or 0.0)
    end
    local tx, ty, tz = rad3("route3_limb_thigh_x", "route3_limb_thigh_y", "route3_limb_thigh_z")
    local kx, ky, kz = rad3("route3_limb_knee_x", "route3_limb_knee_y", "route3_limb_knee_z")
    local nx, ny, nz = rad3("route3_limb_ankle_x", "route3_limb_ankle_y", "route3_limb_ankle_z")
    local ax, ay, az = rad3("route3_limb_arm_x", "route3_limb_arm_y", "route3_limb_arm_z")
    local ex, ey, ez = rad3("route3_limb_elbow_x", "route3_limb_elbow_y", "route3_limb_elbow_z")
    mirror_pair("L_Leg_Upper", "R_Leg_Upper", tx, ty, tz)
    mirror_pair("L_Leg_Lower", "R_Leg_Lower", kx, ky, kz)
    -- ankles: the cleanup resets them to base pre-lab, so these tweaks are the only
    -- thing shaping the feet -- lets her lay the feet flat along the neck sides
    mirror_pair("L_Leg_Ankle", "R_Leg_Ankle", nx, ny, nz)
    mirror_pair("L_Arm_Upper", "R_Arm_Upper", ax, ay, az)
    mirror_pair("L_Arm_Lower", "R_Arm_Lower", ex, ey, ez)
end

function griffin_rider_hand_magnet_apply()
    if iris_puppet_seat_active() then return end -- 07-24: puppet seat owns the hands
    -- HAND MAGNET (round-32, Aurora's ask): each hand is pulled onto a grip point
    -- riding the griffin's scruff joint, every frame, via 2-bone arm IK solved in
    -- POSITION space (the offline solver's exact technique, live): world targets ->
    -- law-of-cosines elbow -> minimal-twist locals against the LIVE clavicle world
    -- rotation (player joint rotations are trustworthy -- the hug_dev law) ->
    -- SEEDED euler extraction (continuity with last frame; init from the clip pose)
    -- so the write never jumps branches. Runs post-lab, after limbfit; owns the
    -- arm chain while enabled.
    if C.route3_hand_magnet == false then return end
    if S.route3_wilds_rider_pose_active ~= true then return end
    local player = get_player()
    local pgo = char_go(player)
    local ptf = pgo and pgo:call("get_Transform")
    local _, ggo = reacquire_griffin()
    local gtf = ggo and transform_of(ggo)
    if not (ptf and gtf) then return end
    local nj = managed_call(gtf, "getJointByName", tostring(C.route3_hand_grip_joint or "Neck_0"))
    local np = nj and managed_call(nj, "get_Position")
    if not np then return end
    local gyaw = yaw_from_transform(ggo) or 0.0
    local fwx, fwz = math.sin(gyaw), math.cos(gyaw)
    local rgx, rgz = math.cos(gyaw), -math.sin(gyaw)
    local GW = tonumber(C.route3_hand_grip_width) or 0.25
    local GH = tonumber(C.route3_hand_grip_up) or 0.05
    local GF = tonumber(C.route3_hand_grip_fwd) or 0.15
    -- self-contained math (file-scope locals live far above -- LUA TRAP)
    local function v(x, y, z) return { x = x, y = y, z = z } end
    local function vsub(a, b) return v(a.x - b.x, a.y - b.y, a.z - b.z) end
    local function vadd(a, b) return v(a.x + b.x, a.y + b.y, a.z + b.z) end
    local function vscale(a, s) return v(a.x * s, a.y * s, a.z * s) end
    local function vlen(a) return math.sqrt(a.x * a.x + a.y * a.y + a.z * a.z) end
    local function vnorm(a)
        local l = vlen(a)
        if l < 1e-9 then return v(0, 0, 1) end
        return vscale(a, 1.0 / l)
    end
    local function vcross(a, b)
        return v(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x)
    end
    local function vdot(a, b) return a.x * b.x + a.y * b.y + a.z * b.z end
    local function quat_m3(q)
        local x = tonumber(q.x) or 0.0
        local y = tonumber(q.y) or 0.0
        local z = tonumber(q.z) or 0.0
        local w = tonumber(q.w) or 1.0
        return { { 1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w) },
                 { 2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w) },
                 { 2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y) } }
    end
    local function axis_m3(a, ang)
        local c, s, C1 = math.cos(ang), math.sin(ang), 1.0 - math.cos(ang)
        local x, y, z = a.x, a.y, a.z
        return { { c + x * x * C1, x * y * C1 - z * s, x * z * C1 + y * s },
                 { y * x * C1 + z * s, c + y * y * C1, y * z * C1 - x * s },
                 { z * x * C1 - y * s, z * y * C1 + x * s, c + z * z * C1 } }
    end
    local function rot_between(a, b)
        a, b = vnorm(a), vnorm(b)
        local ax = vcross(a, b)
        local s = vlen(ax)
        local c = math.max(-1.0, math.min(1.0, vdot(a, b)))
        if s < 1e-9 then
            if c > 0 then return { { 1, 0, 0 }, { 0, 1, 0 }, { 0, 0, 1 } } end
            local p = vnorm(vcross(a, math.abs(a.y) < 0.9 and v(0, 1, 0) or v(1, 0, 0)))
            return axis_m3(p, math.pi)
        end
        return axis_m3(vnorm(ax), math.atan(s, c))
    end
    local function m3_euler_seeded(m, seed)
        -- engine R = Ry@Rx@Rz; pick the branch candidate closest to the seed
        local exb = math.asin(math.max(-1.0, math.min(1.0, -m[2][3])))
        local best, bd = nil, 1e9
        for _, exc in ipairs({ exb, math.pi - exb }) do
            local eyc, ezc
            if math.abs(math.cos(exc)) > 1e-6 then
                eyc = math.atan(m[1][3], m[3][3])
                ezc = math.atan(m[2][1], m[2][2])
            else
                eyc = math.atan(-m[3][1], m[1][1])
                ezc = 0.0
            end
            local t = { exc, eyc, ezc }
            for i = 1, 3 do
                while t[i] - seed[i] > math.pi do t[i] = t[i] - 2.0 * math.pi end
                while t[i] - seed[i] < -math.pi do t[i] = t[i] + 2.0 * math.pi end
            end
            local d = math.abs(t[1] - seed[1]) + math.abs(t[2] - seed[2]) + math.abs(t[3] - seed[3])
            if d < bd then bd, best = d, t end
        end
        return best[1], best[2], best[3]
    end
    S.route3_hand_seed = S.route3_hand_seed or {}
    for _, sd in ipairs({ { side = "L", sx = 1.0 }, { side = "R", sx = -1.0 } }) do
        pcall(function()
            local side, sx = sd.side, sd.sx
            local uj = ptf:call("getJointByName", side .. "_Arm_Upper")
            local lj = ptf:call("getJointByName", side .. "_Arm_Lower")
            local hj = ptf:call("getJointByName", side .. "_Arm_Hand")
            local cj = ptf:call("getJointByName", side .. "_Arm_Clavicle")
            if not (uj and lj and hj and cj) then return end
            local Sp = uj:call("get_Position")
            local Ep = lj:call("get_Position")
            local Hp = hj:call("get_Position")
            local cq = cj:call("get_Rotation")
            if not (Sp and Ep and Hp and cq) then return end
            local SP = v(tonumber(Sp.x) or 0, tonumber(Sp.y) or 0, tonumber(Sp.z) or 0)
            local l1 = vlen(vsub(v(tonumber(Ep.x) or 0, tonumber(Ep.y) or 0, tonumber(Ep.z) or 0), SP))
            local l2 = vlen(vsub(v(tonumber(Hp.x) or 0, tonumber(Hp.y) or 0, tonumber(Hp.z) or 0),
                v(tonumber(Ep.x) or 0, tonumber(Ep.y) or 0, tonumber(Ep.z) or 0)))
            if l1 < 0.05 or l2 < 0.05 then return end
            -- grip point (render space, like every joint position)
            local T = v((tonumber(np.x) or 0) + rgx * (sx * GW) + fwx * GF,
                        (tonumber(np.y) or 0) + GH,
                        (tonumber(np.z) or 0) + rgz * (sx * GW) + fwz * GF)
            local D = vsub(T, SP)
            local d = math.max(math.abs(l1 - l2) + 0.01, math.min(l1 + l2 - 0.01, vlen(D)))
            local t0 = vnorm(D)
            local cosA = math.max(-1.0, math.min(1.0, (l1 * l1 + d * d - l2 * l2) / (2.0 * l1 * d)))
            -- elbow pole: outward + down, so elbows bow away from her body
            local pole = vnorm(v(rgx * sx, -0.6, rgz * sx))
            local axis = vcross(t0, pole)
            if vlen(axis) < 1e-6 then axis = v(0, 1, 0) end
            local updir = vnorm(griffin_m3_mulv(axis_m3(vnorm(axis), math.acos(cosA)), t0))
            local elbow = vadd(SP, vscale(updir, l1))
            local foredir = vnorm(vsub(T, elbow))
            -- minimal-twist locals against the LIVE clavicle world (python technique)
            local Wc = quat_m3(cq)
            local Xax = v(sx, 0, 0)   -- bone axes: +X on L, -X on R (mirrored-rig law)
            local ubase = uj:call("get_BaseLocalRotation")
            local lbase = lj:call("get_BaseLocalRotation")
            if not (ubase and lbase) then return end
            local Ru_rest = quat_m3(ubase)
            local Ru = griffin_m3_mul(rot_between(griffin_m3_mulv(Ru_rest, Xax),
                griffin_m3_tmulv(Wc, updir)), Ru_rest)
            local Wup = griffin_m3_mul(Wc, Ru)
            local Rl_rest = quat_m3(lbase)
            local Rl = griffin_m3_mul(rot_between(griffin_m3_mulv(Rl_rest, Xax),
                griffin_m3_tmulv(Wup, foredir)), Rl_rest)
            local ks = S.route3_hand_seed[side]
            if not ks then
                local cu = uj:call("get_LocalEulerAngle")
                local cl = lj:call("get_LocalEulerAngle")
                ks = {
                    u = { tonumber(cu and cu.x) or 0, tonumber(cu and cu.y) or 0, tonumber(cu and cu.z) or 0 },
                    l = { tonumber(cl and cl.x) or 0, tonumber(cl and cl.y) or 0, tonumber(cl and cl.z) or 0 },
                }
            end
            local ux, uy, uz = m3_euler_seeded(Ru, ks.u)
            local lx, ly, lz = m3_euler_seeded(Rl, ks.l)
            ks.u = { ux, uy, uz }
            ks.l = { lx, ly, lz }
            S.route3_hand_seed[side] = ks
            uj:call("set_LocalEulerAngle", Vector3f.new(ux, uy, uz))
            lj:call("set_LocalEulerAngle", Vector3f.new(lx, ly, lz))
        end)
    end
end

function route3_rider_pose_cleanup(pgo, yaw_delta)
    -- The clip does not write ankles/feet/toes, so clean the visible climb grip after
    -- native motion evaluates. Root clean-up is legacy puppet-only; the safe overlay
    -- deliberately preserves native root orientation and position.
    local tf = pgo and pgo:call("get_Transform")
    if not tf then return end
    -- SAFE/native-overlay calls pass yaw_delta=nil. In that mode native climb MUST
    -- retain its evaluated root position/rotation so it can turn with the Griffin.
    -- The old unconditional root reset contradicted "native owns orientation" and
    -- plausibly pinned the visible rider to her original heading. Puppet/legacy calls
    -- still get the old root clean-up because they explicitly pass a yaw value.
    local cleanup_names = { "L_Leg_Ankle", "R_Leg_Ankle",
        "L_Leg_Foot", "R_Leg_Foot", "L_Leg_Toes", "R_Leg_Toes" }
    if yaw_delta ~= nil then table.insert(cleanup_names, 1, "root") end
    for _, nm in ipairs(cleanup_names) do
        pcall(function()
            local j = tf:call("getJointByName", nm)
            if not j then return end
            local bq = j:call("get_BaseLocalRotation")
            if bq then
                local ex, ey, ez = griffin_q_to_euler_zxy(bq)
                j:call("set_LocalEulerAngle", Vector3f.new(ex, ey, ez))
            end
            if nm == "root" and S.route3_rider_puppet_on == true then
                -- Root POSITION reset is PUPPET-only (the pin owns her position there). In the
                -- SAFE upright lock, keep the native climb's root position so she rides with the
                -- griffin -- resetting root position to base every frame fights fast turns and
                -- stretches her body toward the neck. The lock only needs the ROTATION reset above.
                local bp = j:call("get_BaseLocalPosition")
                if bp then j:call("set_LocalPosition", Vector3f.new(bp.x, bp.y, bp.z)) end
            end
        end)
    end
    -- YAW-FOLLOW via HIP (round-22 channel: the studio's proven player-orientation
    -- joint). ABSOLUTE write from the captured seated rest -- idempotent across the
    -- two per-frame pin passes, cannot compound.
    --
    -- ROUND-23: the euler SETTER's composition order is probed AT RUNTIME. Round-22
    -- field: turning pitched her by the turn amount -- the signature of the yaw delta
    -- landing on Hip's LOCAL Y (horizontal, thanks to the rest's ~90deg roll), which
    -- happens if set_LocalEulerAngle composes Y INNERMOST (Rz@Rx@Ry) while the getter
    -- is verified Ry@Rx@Rz against the skeleton dump. Probe: write a known test
    -- euler, read get_LocalRotation back, match against both candidates.
    local dy = tonumber(yaw_delta) or 0.0
    local rest = S.route3_rider_hip_rest
    -- nil means "clean the unkeyed pose joints, but leave Hip orientation alone".
    -- The safe visual mount uses ActorMotion's visual-root offset below; feeding it
    -- through this local-euler path pitched the rider and could invert her outright.
    if yaw_delta ~= nil and type(rest) == "table" then
        pcall(function()
            local j = tf:call("getJointByName", "Hip")
            if not j then return end
            if S.route3_rider_euler_conv == nil then
                local ty = rest.y + 0.5
                j:call("set_LocalEulerAngle", Vector3f.new(rest.x, ty, rest.z))
                local q = nil
                pcall(function() q = j:call("get_LocalRotation") end)
                local conv = "?"
                local da, db = -1, -1
                if q then
                    local function qdot(p)
                        return math.abs((tonumber(q.x) or 0) * p.x + (tonumber(q.y) or 0) * p.y
                            + (tonumber(q.z) or 0) * p.z + (tonumber(q.w) or 1) * p.w)
                    end
                    da = qdot(griffin_m3_to_quat(griffin_m3_ypr(ty, rest.x, rest.z)))
                    db = qdot(griffin_m3_to_quat(griffin_m3_zxy(rest.x, ty, rest.z)))
                    if da > 0.999 and da >= db then conv = "yxz"
                    elseif db > 0.999 then conv = "zxy" end
                end
                S.route3_rider_euler_conv = conv
                pcall(function() log.info(string.format(
                    "[GriffinRide] Hip euler-setter probe: conv=%s (yxz dot=%.4f, zxy dot=%.4f)",
                    conv, da, db)) end)
            end
            if dy ~= 0.0 and S.route3_rider_euler_conv == "zxy" then
                -- true parent-frame yaw, re-encoded for a Y-innermost setter
                local M = griffin_m3_mul(griffin_m3_ypr(dy, 0.0, 0.0),
                    griffin_m3_zxy(rest.x, rest.y, rest.z))
                local ex, ey, ez = griffin_m3_to_euler_zxyouter(M)
                j:call("set_LocalEulerAngle", Vector3f.new(ex, ey, ez))
            elseif dy ~= 0.0 then
                -- symmetric setter (or probe undecided): Ry@Rx@Rz means a parent-frame
                -- yaw is EXACTLY an euler-Y add
                j:call("set_LocalEulerAngle", Vector3f.new(rest.x, rest.y + dy, rest.z))
            else
                -- dy == 0: re-assert rest (also cleans the probe's test write)
                j:call("set_LocalEulerAngle", Vector3f.new(rest.x, rest.y, rest.z))
            end
        end)
    end
end


function griffin_rider_safe_motion_yaw_restore()
    local base = S.route3_rider_safe_motion_base
    if type(base) == "table" then
        local pgo = char_go(get_player())
        local am = pgo and get_component(pgo, "via.motion.ActorMotion")
        if am then pcall(function()
            am:call("set_FixedRootOffsetRotation",
                griffin_make_quat_raw(base.x, base.y, base.z, base.w))
        end) end
    end
    S.route3_rider_safe_motion_base = nil
    S.route3_rider_safe_motion_last = nil
    S.route3_rider_safe_hip_motion_index = nil
    S.route3_rider_hip_world_setter = nil
    S.route3_rider_hip_world_readback = nil
end

-- Place the player on the griffin's BACK before the climb latches. TWO modes:
-- DEFAULT (route3_rt_mount_use_fixed_offset=false) = rebase to the LIVE Spine_2 BACK BONE
--   (universal + (jointRender - griffinRender)). It drifts ~30cm with the idle anim BUT it's ALWAYS on
--   the actual back surface, so the grab always lands on the back = seated, never under/beside. The pose
--   is relative + hand-IK so it tolerates the drift (proven: clean seated mounts, e.g. shot 47).
-- FIXED offset (route3_rt_mount_use_fixed_offset=true) = griffin ROOT + a constant yaw-rotated offset.
--   ⛔ 2026-07-20 REGRESSION: this DEAD-RECKONS the back; when the griffin tilts/shifts out of rest pose
--   the point is in mid-air BESIDE her -> the player falls during the latch delay and the climb grabs her
--   low (flank/belly) = the "under the beast" mounts (shots 46, 51). Kept only as an A/B option, OFF.
-- `up` = small drop-in margin added to height so the grab catches as she settles onto the surface.
function griffin_place_player_on_back(ptf, ggo, up)
    if not (ptf and ggo) then return false end
    local gtf = transform_of(ggo)
    if not gtf then return false end
    local dy = tonumber(up) or 0.3
    if C.route3_rt_mount_use_fixed_offset == true then
        local gup = transform_pos(ggo)
        if not gup then return false end
        local gyaw = yaw_from_transform(ggo) or 0.0
        local fwd = { x = math.sin(gyaw), z = math.cos(gyaw) }
        local right = { x = math.cos(gyaw), z = -math.sin(gyaw) }
        local lx = tonumber(C.route3_rt_mount_local_x) or 0.0
        local ly = tonumber(C.route3_rt_mount_local_y) or 1.35
        local lz = tonumber(C.route3_rt_mount_local_z) or -0.55
        local moved = false
        pcall(function() ptf:call("set_UniversalPosition", make_position(
            (tonumber(gup.x) or 0.0) + right.x * lx + fwd.x * lz,
            (tonumber(gup.y) or 0.0) + ly + dy,
            (tonumber(gup.z) or 0.0) + right.z * lx + fwd.z * lz)); moved = true end)
        return moved
    end
    -- DEFAULT: live Spine_2 back bone (always on the real back surface)
    local gup = transform_pos(ggo)
    local grp = transform_render_pos(ggo) or gup
    local joint = managed_call(gtf, "getJointByName", tostring(C.route3_rt_mount_joint or "Spine_2"))
    local jp = joint and managed_call(joint, "get_Position")
    if not (gup and grp and jp) then return false end
    local moved = false
    pcall(function() ptf:call("set_UniversalPosition", make_position(
        (tonumber(gup.x) or 0.0) + (tonumber(jp.x) or 0.0) - (tonumber(grp.x) or 0.0),
        (tonumber(gup.y) or 0.0) + (tonumber(jp.y) or 0.0) - (tonumber(grp.y) or 0.0) + dy,
        (tonumber(gup.z) or 0.0) + (tonumber(jp.z) or 0.0) - (tonumber(grp.z) or 0.0))); moved = true end)
    return moved
end

-- Fire the PROVEN native climb-latch (the pawn-probe recipe that actually flips
-- get_IsClimbOnCharacter). Order matters and the CTRL variant carries the target GameObject --
-- the v1 zero-arg climber:startClimb() never latched, which is why RT-from-standing just plopped
-- her on the back. Do NOT think-stop the player -- the climb FSM must RUN to consume the latch.
function griffin_fire_player_climb_latch(player, ggo)
    if not (player and ggo) then return "no player/griffin" end
    local ctrl = get_climb_ctrl(player)
    local tags = {}
    local function step(tag, fn) local ok = pcall(fn); tags[#tags + 1] = tag .. (ok and "" or "!") end
    if ctrl then step("ctrl.start(go)", function() ctrl:call("startClimb(via.GameObject, System.Boolean)", ggo, false) end) end
    step("tgt", function() player:call("set_RequestClimbTarget", ggo) end)
    step("byreq", function() player:call("set_IsSetClimbActionByRequest", true) end)
    step("start", function() player:call("startClimb(System.Boolean)", false) end)
    return table.concat(tags, " ")
end

function griffin_smart_mount()
    -- MOUNT-FROM-STANDING v3 (Aurora): the v1/v2 teleport-to-Neck_1 + zero-arg startClimb was wrong
    -- on BOTH counts -- Neck_1 sits high on the neck so the character controller ejected her ("sends
    -- me flying"), and climber:startClimb() with no args never latched the climb ("plops on the back,
    -- not climbing"). The pawn-climb probe proved the real latch: place her FLUSH on the BACK (Spine_2,
    -- universal rebase), fire startClimb(via.GameObject, System.Boolean) WITH the griffin GO, do NOT
    -- think-stop (the climb FSM must RUN to consume it), then WATCH a short window --
    -- get_IsClimbOnCharacter flips a few frames later and griffin_rt_mount_watch_tick adopts the ride.
    local player = get_player()
    local pgo = char_go(player)
    local ptf = pgo and transform_of(pgo)
    local gch, ggo = reacquire_griffin()
    if not (player and ptf and ggo and gch) then S.route3_smart_mount_status = "smart mount: need player + active griffin"; return false end
    -- ⛔ TOO SMALL TO RIDE (2026-08-08, Aurora: "baby griffins can't be ridden until they're
    -- a large enough size"): a hatchling below the rideable fraction of its full-grown scale
    -- refuses the mount. Reads the LIVE growth curve, so one day she simply becomes big
    -- enough and the same grip press just works.
    local too_small = false
    pcall(function()
        local rec = griffin_stable_live_rec()
        local h = rec and rec.hatch
        if not h then return end
        local baby = tonumber(h.baby_scale) or 0.12
        local full = tonumber(h.full) or (tonumber(C.spawn_scale) or 0.45)
        local t = 0.0
        local igh = iris_bridge_igh()
        if igh and tonumber(h.igh0) then
            t = math.max(0.0, math.min(1.0,
                (igh - tonumber(h.igh0)) / math.max(0.1, (tonumber(h.growth_days) or 10.0) * 24.0)))
        end
        local cur = baby + (full - baby) * t
        local need = full * math.max(0.1, math.min(1.0, tonumber(C.route3_ride_min_grown) or 0.75))
        if cur < need then
            too_small = true
            S.route3_smart_mount_status = string.format(
                "%s is too small to ride yet (%.0f%% grown, rideable at %.0f%%)",
                tostring(rec.name or "the hatchling"),
                (cur - baby) / math.max(0.01, full - baby) * 100.0,
                (need - baby) / math.max(0.01, full - baby) * 100.0)
            status(S.route3_smart_mount_status)
            -- on-screen card via IrisTaming's banner (the panel status alone was invisible)
            pcall(function()
                local T = rawget(_G, "IrisTaming")
                if T and T.prompt then
                    T.prompt("TOO SMALL TO RIDE", S.route3_smart_mount_status, 3.5, 0xFF80D0FF)
                end
            end)
        end
    end)
    if too_small then return false end
    -- ⛔ PET TIER (2026-08-08, Aurora: "R on the wolf tries to mount it -- teleports up and
    -- falls over; R should PICK IT UP until it's mount-sized"): a wolf/cat (ch223) is a PET
    -- until the Wyrmfeeding rite grows it. Refuse the mount unless it's wyrm-grown toward the
    -- mount line (C.wyrm_mount_scale). Reads the LIVE record, so the day the rite completes the
    -- same grip just works -- and until then R falls through to the carry/pickup path.
    local pet_tier = false
    pcall(function()
        local sp = tostring(go_name(ggo) or "")
        if sp:find("ch223", 1, true) then
            -- ⛔ 08-11 (Aurora: "everytime tries to mount the panther"): this gate read the
            -- ACTIVE record's wyrm growth no matter WHICH body was under the hand -- with a
            -- grown wolf on the roster, every other ch223 (the panther) inherited its mount
            -- permission. A ch223 may mount ONLY when it IS the active companion's own body
            -- AND that record is grown. Anything else ch223-shaped is pet tier, full stop.
            local rec = griffin_stable_live_rec()
            local is_active_body = false
            pcall(function()
                local _, ago = reacquire_griffin()
                is_active_body = (ago ~= nil) and (ggo ~= nil) and ago:get_address() == ggo:get_address()
            end)
            local grown = is_active_body and rec and rec.wyrm and (tonumber(rec.wyrm.to) or 1.0) >= ((tonumber(C.wyrm_mount_scale) or 1.85) - 0.05)
            pcall(function() log.info(string.format("[GriffinRideProbe (IRIS)] pet-tier gate: body=%s active_body=%s wyrm_to=%s grown=%s",
                sp, tostring(is_active_body), tostring(rec and rec.wyrm and rec.wyrm.to or "none"), tostring(grown == true))) end)
            if not grown then
                pet_tier = true
                S.route3_smart_mount_status =
                    tostring((rec and rec.name) or "This one")
                    .. " is a companion -- feed it the Wyrm's Rite at a camp to grow a mount"
                pcall(function()
                    local T = rawget(_G, "IrisTaming")
                    if T and T.prompt then
                        T.prompt("NOT A MOUNT YET", S.route3_smart_mount_status, 3.5, 0xFF80D0FF)
                    end
                end)
            end
        end
    end)
    if pet_tier then return false end
    -- ⭐ SEAT MODE v2 (08-08 round 3): the puppet/weld seat is DEAD on the griffin — the
    -- rider-anchor wall (her spine joints whip metres through ordinary idles; the weld
    -- calibrated against a rearing spine = prone rider, and the pin fought her live body
    -- = the field vibration). v2 = the PAWN TREATMENT: the classic climb entry below,
    -- the native Follower owns her (the only system that has ever tracked this creature),
    -- and the seat enforcer holds the climb MOTION at zero. Mount-side contribution here
    -- is only the side gate — everything else is the proven classic path.
    if C.griffin_seat_mode == true and griffin_seat_side_blocked(ptf, ggo) then
        S.route3_smart_mount_status = "mount refused -- walk to her SIDE first"
        status(S.route3_smart_mount_status)
        return false
    end
    -- crash-tape context: record the griffin's node + airborne flags at mount START so a CTD tape shows
    -- whether she was grounded (universal rebase valid) or in a flight/hover state (rebase suspect).
    pcall(function()
        read_griffin_fsm_node()
        griffin_mount_crash_mark(string.format("SMART MOUNT begin gnode=%s pAir=%s mounted=%s nclimb=%s",
            tostring(S.last_fsm_node or "?"), tostring(S.airborne), tostring(S.mounted), tostring(S.native_climb_mount)))
    end)
    local placed = griffin_place_player_on_back(ptf, ggo, tonumber(C.route3_smart_mount_up) or 0.3)
    if not placed then S.route3_smart_mount_status = "smart mount: back joint not found (bad rig?)"; return false end
    pcall(function() griffin_mount_crash_mark("placed on back (Spine_2)") end)
    local grab = "off"
    if C.route3_smart_mount_autograb ~= false then
        grab = griffin_fire_player_climb_latch(player, ggo)
    end
    pcall(function() griffin_mount_crash_mark("latch fired [" .. tostring(grab) .. "]") end)
    -- arm the watch: it polls for the latch and re-fires ONLY as a throttled, transition-guarded
    -- fallback (see the CRASH LAW in griffin_rt_mount_watch_tick). Stamp the fire time for the throttle.
    S.route3_rt_mount_last_fire = os.clock()
    S.route3_rt_mount_watch_until = os.clock() + (tonumber(C.route3_rt_mount_watch_secs) or 1.5)
    S.route3_smart_mount_status = string.format("smart mount: on back, latch [%s] -- watching...", grab)
    return true
end

-- ⭐⭐ EPONA-TEMPLATE SEAT (2026-08-08, work-order build) ------------------------------------
-- The horse mount saga closed with a template that made Epona's seat identical every mount:
-- no native climb, FallLoop deterministic park, seat pin writes last, an enforcer that re-parks
-- anything native that wakes, and the PosRotRecorder fed the seat as "safe" so the stuck-player
-- rescue has nothing older to return her to. This block is that template on the griffin,
-- riding the probe's EXISTING puppet apparatus (route3_rider_puppet = think-stop/CC-off/FSM-off/
-- TXI/rescue-skip-hooks; the rigid weld pin + auto-locked saddle offsets own position+facing).
-- The climb-entry mount stays untouched behind C.griffin_seat_mode=false.

function griffin_seat_feed_recorder(x, y, z, reset_history)
    -- IrisHorseRodeo feed_player_safe_position, ported (r42): keep DD2's safe-coordinate
    -- recorder AT THE SEAT so the rescue warps her nowhere. At altitude this records the
    -- saddle itself as safe ground -- the fade counter the July puppet never had.
    pcall(function()
        local player = get_player()
        local recorder = player and player:get_field("<PosRotRecorder>k__BackingField")
        local pgo = player and char_go(player)
        local tf = pgo and transform_of(pgo)
        if not (recorder and tf) then return end
        if reset_history then pcall(function() recorder:call("resetHistory") end) end
        local pos = make_position(x, y, z)
        local rot = tf:call("get_Rotation")
        pcall(function() recorder:call("set_IsSafeCoord", true) end)
        local wrote = pcall(function() recorder:call("recordPosRotExternal", pos, rot) end)
        if not wrote then pcall(function() recorder:call("recordPosRot", pos, rot) end) end
        pcall(function()
            recorder:set_field("PosAfterReviveFromFallDead", Vector3f.new(x, y, z))
            recorder:set_field("IsAfterReviveFromFallDead", false)
        end)
        pcall(function()
            local landing = recorder:get_field("LandingProcessor")
            if not landing then return end
            local ground = landing:call("get_LastGroundPosition")
            if ground then
                ground.x, ground.y, ground.z = x, y - 0.1, z
                landing:call("set_LastGroundPosition", ground)
            end
            landing:call("resetFallingStuckStopperToCurrentPosition")
            local fall = landing:get_field("FallInfo")
            if fall then
                fall:call("resetFallHeight")
                fall:call("set_FallHeight", 0.0)
            end
        end)
    end)
end

function griffin_seat_side_blocked(ptf, ggo)
    -- r47 SIDE-ONLY gate: nose/tail presses never produced a clean boarding on the horse;
    -- on the griffin they'd also start the enter inside the wing/tail volume.
    local blocked = false
    pcall(function()
        local gtf = transform_of(ggo)
        local gp = gtf:call("get_Position")
        local az = gtf:call("get_AxisZ")
        local pp = ptf:call("get_Position")
        local dx, dz = pp.x - gp.x, pp.z - gp.z
        local fore = dx * az.x + dz * az.z
        local sidem = math.sqrt(math.max(0.0, dx * dx + dz * dz - fore * fore))
        blocked = math.abs(fore) > sidem + (tonumber(C.griffin_seat_side_slack) or 0.6)
    end)
    return blocked
end
function griffin_seat_enforcer_tick()
    -- post-dismount landing re-assert (the CC snap-back law: the restored controller's
    -- cached position beats a single write -- re-write through a short window)
    local land = S.griffin_seat_land
    if type(land) == "table" then
        if os.clock() > (tonumber(land.until_t) or 0.0) then
            S.griffin_seat_land = nil
        else
            pcall(function()
                local pgo = char_go(get_player())
                transform_of(pgo):call("set_UniversalPosition",
                    make_position(land.x, land.y, land.z))
            end)
        end
    end
    local seated = (S.mounted == true and S.native_climb_mount == true)
    -- stamp the moment she becomes seated, so the freeze can wait for the climb to
    -- finish settling her (field round 11: freezing on the mount frame locks the
    -- half-boarded PRONE pose -- screenshot: flat across the back, legs out)
    if seated then
        if not S.griffin_seat_mount_at then S.griffin_seat_mount_at = os.clock() end
        -- ⛔ SAME TRAP AS THE FREEZE (round 12): the PrepareRendering pass that runs
        -- griffin_rider_seat_hold_tick is registered ONLY inside route3_wilds_rider_pose_start,
        -- so with no pose the seat hold could never run no matter what its checkbox said.
        -- Register it here too. LAZY (at first mount), never at load: registrations fire in
        -- order and this file loads before rs_anim_lab ("G" < "r"), so a load-time bone pass
        -- would be overpainted. Guarded by the same flag so it can never double-register.
        if S.route3_limbfit_registered ~= true then
            S.route3_limbfit_registered = true
            re.on_application_entry("PrepareRendering", function()
                safe_run("griffin_rider_safe_visual", griffin_rider_safe_visual_tick)
                safe_run("griffin_rider_seat_hold", griffin_rider_seat_hold_tick)
                safe_run("griffin_rider_limbfit", griffin_rider_limbfit_apply)
                safe_run("griffin_rider_hand_magnet", griffin_rider_hand_magnet_apply)
            end)
        end
    else
        S.griffin_seat_mount_at = nil
    end
    -- ⛔ ROUND-10 WIRING BUG (mine): the FREEZE and the readout used to live BELOW the
    -- seat-mode gate, so with steady seat OFF (Aurora's correct state after round 7)
    -- ticking "FREEZE" ran nothing at all and the field result was meaningless. They are
    -- INDEPENDENT experiments -- the freeze needs only a mounted rider -- so they run on
    -- `seated` alone. Only the stillness discipline below belongs to seat mode.
    if seated then
        pcall(function()
            local st = griffin_player_motion_state()
            S.griffin_seat_clip = string.format("b%s:%s f%.0f/%s",
                tostring(st.bank), tostring(st.clip),
                tonumber(st.frame) or -1, tostring(st.ending))
        end)
        if (tonumber(C.route3_rider_pose_bank) or -1) >= 0 then
            pcall(griffin_apply_captured_rider_pose)
        end
    end
    -- ⭐⭐ THE FREEZE (Aurora's ask). Per-frame: the ACTION system rewrites PlaySpeed on
    -- its own transitions, and at 10Hz we lose that race (the round-6 lesson).
    -- Restores live in dismount_griffin / stop_ride_only / on_script_reset.
    local settle_left = 0.0
    if seated and S.griffin_seat_mount_at then
        settle_left = math.max(0.0, (tonumber(C.griffin_seat_freeze_delay) or 2.5)
            - (os.clock() - S.griffin_seat_mount_at))
    end
    S.griffin_seat_settle_left = settle_left
    if C.griffin_seat_freeze_fsm == true and seated and settle_left <= 0.0 then
        griffin_set_player_fsm_enabled(false)
        griffin_set_player_motion_speed(0.0)
        S.griffin_seat_frozen = true
    elseif S.griffin_seat_frozen == true then
        griffin_set_player_fsm_enabled(true)
        griffin_set_player_motion_speed(1.0)
        S.griffin_seat_frozen = false
    end
    -- v2 (08-08 round 3, the PAWN TREATMENT): she rides the NATIVE CLIMB; the enforcer's
    -- whole job is STILLNESS + not falling off. No puppet, no FallLoop, no pose, no
    -- rescue feed -- the climb-alive ride never faded and the Follower owns her body.
    if not (C.griffin_seat_mode == true and seated) then return end
    local now = os.clock()
    if now < (tonumber(S.griffin_seat_next_enforce) or 0.0) then return end
    S.griffin_seat_next_enforce = now + 0.1
    local player = get_player()
    if not player then return end
    -- 1) PAWN STILLNESS TRIO (griffin_pawn_ride_tick PHASE 3 -- weeks-proven on this
    -- exact creature): the Follower keeps her glued + world-valid; zeroed climb motion
    -- means she CANNOT crawl the torso or the head. Re-asserted, never one-shot.
    pcall(function()
        local ctrl = get_climb_ctrl(player)
        if not ctrl then return end
        pcall(function() ctrl:call("set_IsClimbMoving", false) end)
        pcall(function() ctrl:call("set_ClimbMotionSpeed", 0.0) end)
        pcall(function() ctrl:call("set_ClimbMoveAngleDeg", 0.0) end)
        -- 1b) abort-reject (pawn PHASE 3 parity): an abort-proof climber gives the cling
        -- state machine less to re-solve. ⚠ think_stop on the PLAYER was ALSO here and is
        -- REMOVED (round 7): the player is the real climber and her climb FSM has to keep
        -- running -- the mount path's own comment says so in as many words ("do NOT
        -- think-stop -- the climb FSM must RUN"). Brain-stopping her mid-ride is a
        -- candidate for the round-7 contortion, and it is not what the pawn recipe does
        -- to a body that owns its own climb.
        pcall(function() ctrl:set_field("<IsRejectAbortOnDefault>k__BackingField", true) end)
        S.griffin_seat_stills = (tonumber(S.griffin_seat_stills) or 0) + 1
    end)
    -- ⛔⛔ REMOVED 2026-08-08 (field round 7, Aurora: "more contortion and spazzing/
    -- teleporting around now with the steady seat on -- it was better before"). Two
    -- writes lived here and BOTH re-created failures this file already has laws about:
    --
    -- (a) A per-frame FACING pin (set_character_rotation_only toward the griffin's yaw)
    --     while the NATIVE CLIMB is alive. [[griffin-wilds-ride-pose]] settled this in
    --     July and marked it WALLED, "do not re-litigate": the climb re-solves her
    --     orientation every frame, so a second rotation author = THE STORM (detach/
    --     float/spin). The version that IS safe writes from the drive apply, which owns
    --     her transform in that moment -- the channel is not the point, the ownership is.
    --     I mistook one for the other. The drive keeps its write; the enforcer has none.
    --
    -- (b) A RE-LATCH watchdog firing startClimb whenever IsClimbOnCharacter read false.
    --     That flag reads false transiently during node windows and mid-transition, so a
    --     0.4s-throttled re-latch fires INTO a live climb and the engine re-solves her
    --     attach point = the teleporting. The pawn's watchdog is safe because a pawn that
    --     genuinely drops is a lost passenger; the PLAYER is the real climber and the
    --     same flag means something different for her. Touchdown drop-offs go back to
    --     being handled by the mount path, not by a per-tick re-grab.
    --
    -- What remains is only the pawn stillness trio above -- the one piece with a
    -- weeks-proven field record on this exact creature.
end

function griffin_rider_mount_still_tick()
    -- Do not revive the failed transform-weld experiment: native ClimbCtrl is the
    -- sole attachment/rotation owner. We only renew its proven "do not crawl"
    -- controls and the already-settled motion freeze after combat code has had a
    -- chance to rewrite them. This keeps the rider visually quiet without a
    -- second transform author causing detach/spin/teleport storms.
    if C.route3_rider_stillness_enabled == false then return end
    local seated = S.mounted == true and S.native_climb_mount == true
    local special = S.airborne == true
        or type(S.route3_gatk) == "table"
        or type(S.route3_gust) == "table"
        or type(S.route3_gustair) == "table"
        or type(S.route3_dogfight) == "table"
        or type(S.route3_divebomb) == "table"
        or type(S.route3_quick_burst) == "table"
        or S.route3_node_lock_at ~= nil
        or S.route3_node_exit_until ~= nil
    if not (seated and special) then
        if S.route3_rider_stillness_owned == true and S.airborne ~= true then
            griffin_set_player_motion_speed(1.0)
            S.rider_pose_frozen = false
            S.route3_rider_stillness_owned = nil
        end
        return
    end

    local player = get_player()
    if not player then return end
    pcall(function()
        local ctrl = get_climb_ctrl(player)
        if not ctrl then return end
        pcall(function() ctrl:call("set_IsClimbMoving", false) end)
        pcall(function() ctrl:call("set_ClimbMotionSpeed", 0.0) end)
        pcall(function() ctrl:call("set_ClimbMoveAngleDeg", 0.0) end)
        pcall(function() ctrl:set_field("<IsRejectAbortOnDefault>k__BackingField", true) end)
    end)

    if C.route3_freeze_rider_pose == true then
        if S.rider_pose_frozen == true then
            -- Action transitions can restore PlaySpeed later in the same frame;
            -- renew the lease rather than trusting the original one-shot write.
            if griffin_set_player_motion_speed(0.0) then
                S.route3_rider_stillness_owned = true
            end
        elseif griffin_rider_pose_settled(os.clock())
            and griffin_set_player_motion_speed(0.0) then
            S.rider_pose_frozen = true
            S.route3_rider_stillness_owned = true
            S.route3_rider_pose_status = "mounted stillness: settled native climb pose held"
        end
    end
end

-- CLIMB-FROM-STANDING (Aurora): native climb normally needs airborne contact (jump + RT), so from
-- standing RT alone does nothing. Detect RT (r2) pressed on foot NEAR the tame griffin and run
-- griffin_smart_mount, which places her flush on the BACK and fires the PROVEN pawn-climb latch =
-- "just press RT to mount", no jump. The watch tick below re-fires until the climb latches, then adopts.
function griffin_rt_mount_tick()
    if C.route3_rt_mount_enabled ~= true then return end
    if S.mounted == true or S.player_climb_on_character == true or S.native_climb_mount == true
        or S.airborne == true then
        S.route3_rt_mount_prev = false; return
    end
    local down = false
    pcall(function() down = raw_gamepad_button_down(tostring(C.route3_rt_mount_buttons or "r2")) end)
    local pressed = down and (S.route3_rt_mount_prev ~= true)
    S.route3_rt_mount_prev = down
    if not pressed then return end
    local _, ggo = reacquire_griffin()
    if not ggo or C.route3_mountable == false then return end
    local pgo = char_go(get_player())
    local pp = pgo and transform_pos(pgo)
    local gp = transform_pos(ggo)
    if not (pp and gp) then return end
    local dx, dz = (tonumber(pp.x) or 0.0) - (tonumber(gp.x) or 0.0), (tonumber(pp.z) or 0.0) - (tonumber(gp.z) or 0.0)
    if math.sqrt(dx * dx + dz * dz) > (tonumber(C.route3_rt_mount_range) or 4.5) then return end
    local horse_mount = route3_active_horse_mount(ggo)
    -- ⛔⛔ MOUNTABLE SPECIES ONLY (08-08 -- Aurora called this four rounds before I found it:
    -- "unless this is a mount creature, don't mount ... the only creatures that should allow
    -- this are horses, and wolf/cat if they have had the wyrmlife crystal rite").
    --
    -- THE BUG: this tick fires on RT -- the SAME button as IrisTaming's pet grab -- within 4m
    -- of whatever body is registered as the active companion, and griffin_smart_mount then
    -- "places her flush on the BACK". The only gate was C.route3_mountable, a global on/off
    -- with no species check. A tamed RABBIT registers here exactly like a griffin (the log
    -- says it outright: "registered griffin ch299200_A_00"), so every grab press also mounted
    -- her onto the rabbit -- the player snapping to rabbit+0.29 that the altitude trace kept
    -- showing, with no Climb action and indifferent to collision, which is why eight rounds of
    -- fixes inside IrisTaming (collision ghosting, every climb entry point, the native catch
    -- skip) all changed nothing. The launch was never in that file.
    --
    -- Horses keep their own path (IrisHorseRodeo consumes this RT edge below). Everything else
    -- must be a griffin, or grown to the mount line by the rite.
    -- ⛔ TEMPORARILY DISABLED 08-09 to isolate a reproducible crash when mounting a HORSE.
    -- Aurora confirms horse mounting worked earlier today and broke during tonight's work, so
    -- something of mine caused it. Everything else I added to this path is already cleared or
    -- disarmed; this gate is the last one standing, so it goes off too rather than stay a
    -- maybe. ⚠ COST: the rabbit RT-mount launch comes back while this is off -- re-enable the
    -- moment the horse is proven either way.
    -- ⭐ 08-09 r67 -- YOU CANNOT RIDE A BODY THAT IS DOWN. (Aurora: "I press RT
    -- on the downed horse, it tried to mount the downed horse xD".) A downed
    -- companion is HP-pinned, AI-off, animation-claimed and being re-asserted
    -- every frame -- mounting it puts the seat writer and the downed re-assert
    -- on the same body, which is the exact collision that ends in the
    -- actinter move crash. _G.IrisDownedAddrs is the cross-file registry the
    -- downed system already maintains for precisely this kind of question.
    -- ⛔ Ahead of the species gate on purpose: it applies to horses too, and
    -- horses take the horse_mount path that skips everything below.
    do
        local daddr = nil
        pcall(function() daddr = ggo and ggo:get_address() end)
        if daddr and type(_G.IrisDownedAddrs) == "table"
            and _G.IrisDownedAddrs[daddr] then
            S.route3_smart_mount_status = "mount refused: it is DOWN -- revive it first"
            return
        end
    end
    if C.route3_mount_species_gate == true and not horse_mount then
        local mnm = tostring(go_name(ggo) or "")
        local grown = false
        pcall(function()
            -- 08-11: same body-identity rule as the pet-tier gate -- growth only licenses
            -- the ACTIVE companion's own body, never every ch223 in reach.
            local rec = griffin_stable_live_rec()
            local _, ago = reacquire_griffin()
            local same = (ago ~= nil) and (ggo ~= nil) and ago:get_address() == ggo:get_address()
            grown = same and rec and rec.wyrm and (tonumber(rec.wyrm.to) or 1.0) >= ((tonumber(C.wyrm_mount_scale) or 1.85) - 0.05)
            -- ⛔ 08-13 (Shadow launched skyward, no vault): wyrm-grown WOLVES + GREAT CATS
            -- ride the RODEO saddle now (the horse architecture, IrisHorseRodeo wyrm
            -- mount). This climb-mount's teleport+latch on their unclimbable backs was
            -- the pet-launch class reborn - the griffin path stands down for those bands.
            if grown and (mnm:find("ch260", 1, true) or mnm:find("ch223", 1, true)) then
                grown = false
            end
        end)
        if not (mnm:find("ch253", 1, true) or mnm:find("ch257", 1, true) or grown) then
            S.route3_smart_mount_status = "mount refused: " .. mnm .. " is not a mount species"
            if os.clock() - (tonumber(S.route3_mount_refuse_log_at) or 0.0) > 1.0 then
                S.route3_mount_refuse_log_at = os.clock()
                pcall(function() log.info("[GriffinRideProbe (IRIS)] RT mount REFUSED: " .. mnm .. " is not a mount species (not ch253, not wyrm-grown)") end)
            end
            return
        end
    end
    if horse_mount then
        -- (breadcrumb removed 08-09: it did disk I/O on the RT press, i.e. inside the exact
        -- path that crashes, and told us nothing the log did not.)
        -- Do not mount here. IrisHorseRodeo runs later in the frame and
        -- consumes this very RT edge with its seat/vault path. We only
        -- prepare ownership and suppress the invalid smart-mount latch.
        local ok, why = false, nil
        pcall(function()
            ok, why = horse_mount.prepare(ggo, true)
        end)
        S.route3_smart_mount_status = ok
            and "horse mount handed to IrisHorseRodeo"
            or ("horse mount handoff failed: " .. tostring(why))
        return
    end
    pcall(griffin_smart_mount)
end

-- RT-MOUNT WATCH (Aurora): the climb FSM takes a few frames to CONSUME the latch, so smart_mount
-- can't read it back the same frame (v1's bug -- it reported "not-yet" and gave up). Re-fire the
-- placement + latch each frame over a short window; the frame get_IsClimbOnCharacter flips, hand off
-- to route3_start_auto_ride (the same adopt path the natural jump+RT mount uses -> pose + lock + seat).
function griffin_rt_mount_watch_tick()
    local _, active_go = reacquire_griffin()
    if route3_active_horse_mount(active_go) then
        -- Clear any stale griffin smart-mount retry loop left by an older
        -- build. Re-teleporting every 0.4s is the standing/falling bug.
        S.route3_rt_mount_watch_until = 0.0
        return
    end
    local until_t = tonumber(S.route3_rt_mount_watch_until) or 0.0
    if until_t <= os.clock() then return end
    -- already riding? done.
    if S.mounted == true or S.native_climb_mount == true then S.route3_rt_mount_watch_until = 0.0; return end
    update_player_climb_state()
    if S.player_climb_on_character == true then
        S.route3_rt_mount_watch_until = 0.0
        pcall(function() griffin_mount_crash_mark("LATCHED (IsClimbOnCharacter=true)") end)
        if C.route3_rt_mount_auto_ride ~= false then
            -- AUTO-MOUNT (default): straight to the seated ride -- same adopt path as natural jump+RT.
            pcall(function() griffin_mount_crash_mark("before route3_start_auto_ride") end)
            pcall(function() route3_start_auto_ride("rt-mount") end)
            pcall(function() griffin_mount_crash_mark("after route3_start_auto_ride (adopt+pose armed)") end)
            S.route3_smart_mount_status = "smart mount: LATCHED -> adopting ride"
        else
            -- CLIMB-ONLY: leave her in the native clinging state; adopt/ride separately (hotkey).
            S.route3_smart_mount_status = "smart mount: LATCHED (climb-only) -- adopt to ride"
        end
        return
    end
    -- not latched yet.
    -- ⛔ CRASH LAW (2026-07-20 tape): the OLD watch re-fired set_UniversalPosition + startClimb EVERY
    -- frame. Attempts 1-2 latched in ~1 frame so the re-fire never ran; attempt 3 missed by a frame,
    -- the re-fire slammed a SECOND startClimb + universal-yank into the climb transition already in
    -- flight, and it CTD'd (native AV -- the same "forcing universal every frame fights the native
    -- climb" law that retired warp-to-back). FIX: never re-fire into an in-progress transition, and
    -- throttle. If a climb is transitioning (get_IsClimbing), WAIT. Only re-fire once the transition
    -- has genuinely NOT taken (>= refire_gap since the last fire AND not climbing).
    local player = get_player()
    local pgo = char_go(player)
    local ptf = pgo and transform_of(pgo)
    local _, ggo = reacquire_griffin()
    if not (player and ptf and ggo) then return end
    local ctrl = get_climb_ctrl(player)
    local climbing = false
    pcall(function() climbing = ctrl and ctrl:call("get_IsClimbing") == true end)
    if climbing then return end   -- transition in flight -> WAIT for it, never fire into it
    local last_fire = tonumber(S.route3_rt_mount_last_fire) or 0.0
    if os.clock() - last_fire < (tonumber(C.route3_rt_mount_refire_gap) or 0.4) then return end
    -- genuine miss: the first fire didn't start a climb -> re-place + re-fire ONCE, throttled
    S.route3_rt_mount_last_fire = os.clock()
    pcall(function() griffin_mount_crash_mark("re-fire latch (throttled, not climbing)") end)
    pcall(function() griffin_place_player_on_back(ptf, ggo, tonumber(C.route3_smart_mount_up) or 0.3) end)
    pcall(function() griffin_fire_player_climb_latch(player, ggo) end)
end

-- SEAT READOUT (Aurora 2026-07-20): the question that decides if the Wilds pose is viable = "does the
-- native climb park her ROOT in the SAME griffin-relative spot every mount?" The placement sliders
-- can't tell us (the climb re-solves position post-grab). So MEASURE it: her render root minus the
-- griffin render root, projected into the griffin's own frame (Right / Up / Fwd). Mount a few times --
-- if R/U/F repeat within a few cm, the seat is consistent and the pose can sit on it; if they wander,
-- the native climb itself is the variance and no placement change will fix it.
function griffin_seat_readout_tick()
    if not (S.mounted == true or S.native_climb_mount == true) then S.route3_seat_readout = nil; return end
    local pgo = char_go(get_player())
    local _, ggo = reacquire_griffin()
    if not (pgo and ggo) then return end
    local pr = transform_render_pos(pgo)
    local gr = transform_render_pos(ggo)
    if not (pr and gr) then return end
    local gyaw = yaw_from_transform(ggo) or 0.0
    local fwd = { x = math.sin(gyaw), z = math.cos(gyaw) }
    local right = { x = math.cos(gyaw), z = -math.sin(gyaw) }
    local dx = (tonumber(pr.x) or 0.0) - (tonumber(gr.x) or 0.0)
    local dy = (tonumber(pr.y) or 0.0) - (tonumber(gr.y) or 0.0)
    local dz = (tonumber(pr.z) or 0.0) - (tonumber(gr.z) or 0.0)
    -- ROOT TILT (Aurora 2026-07-20: the pose is ALWAYS on, so bad mounts = same pose on a badly-ORIENTED
    -- root, not a failed pose). Measure how far her root's up-vector deviates from world-up (pitch+roll
    -- lean, in degrees). If GOOD mounts read ~0deg and BAD (spread-cling) mounts read 20deg+, orientation
    -- is the culprit and route3_rider_lock_upright is the fix. up.y of the root quat = 1 - 2(x^2 + z^2).
    local tilt = -1.0
    pcall(function()
        local rootj = managed_call(transform_of(pgo), "getJointByName", "root")
        local q = rootj and managed_call(rootj, "get_Rotation")
        if q then
            local qx, qz = tonumber(q.x) or 0.0, tonumber(q.z) or 0.0
            local upy = 1.0 - 2.0 * (qx * qx + qz * qz)
            if upy > 1.0 then upy = 1.0 elseif upy < -1.0 then upy = -1.0 end
            tilt = math.deg(math.acos(upy))
        end
    end)
    local ms = griffin_player_motion_state()
    S.route3_seat_readout = string.format("seat rel griffin: R=%+.2f U=%+.2f F=%+.2f | tilt=%.0fdeg | L0 b%s:%s",
        dx * right.x + dz * right.z, dy, dx * fwd.x + dz * fwd.z, tilt,
        tostring(ms.bank), tostring(ms.clip))
end

function griffin_warp_rider_to_back()
    -- Relocate the rider onto the top of the griffin's back near the seat anchor so a
    -- side/leg grab is normalised before the seat + upright lock place her. Uses
    -- set_UniversalPosition -- the channel that actually renders the player's world
    -- position (via.Transform set_Position does NOT render for the player, per the saga).
    local pgo = char_go(get_player())
    local ptf = pgo and transform_of(pgo)
    if not ptf then S.route3_warp_dbg = "warp: no player transform"; return false end
    local _, ggo = reacquire_griffin()
    local gtf = ggo and transform_of(ggo)
    if not gtf then S.route3_warp_dbg = "warp: no griffin"; return false end
    -- Aim at the ACTUAL seat, pose-proof: measure the Hip->seat gap in RENDER space (both are
    -- joints, same space) and shift her UNIVERSAL position by that vector. A relative vector is
    -- identical in render and universal space (they differ only by a global translation), so no
    -- conversion is needed. The seat target is the SAME point the visual seat aims the Hip at,
    -- so warp + seat agree. A mount that is already good has a ~zero gap and is left untouched.
    local anchor = managed_call(gtf, "getJointByName", tostring(C.route3_rider_visual_anchor_joint or "Neck_1"))
    local ap = anchor and managed_call(anchor, "get_Position")
    local hip = managed_call(ptf, "getJointByName", "Hip")
    local hp = hip and managed_call(hip, "get_Position")
    local her = nil
    pcall(function() her = ptf:call("get_UniversalPosition") end)
    if not (ap and hp and her) then S.route3_warp_dbg = "warp: missing anchor/hip/univ"; return false end
    local gyaw = yaw_from_transform(ggo) or 0.0
    local fwd = { x = math.sin(gyaw), z = math.cos(gyaw) }
    local right = { x = math.cos(gyaw), z = -math.sin(gyaw) }
    local ox = tonumber(C.route3_rider_visual_offset_x) or 0.0
    local oy = tonumber(C.route3_rider_visual_offset_y) or 0.0
    local oz = tonumber(C.route3_rider_visual_offset_z) or 0.0
    local sx = (tonumber(ap.x) or 0.0) + right.x * ox + fwd.x * oz
    local sy = (tonumber(ap.y) or 0.0) + oy
    local sz = (tonumber(ap.z) or 0.0) + right.z * ox + fwd.z * oz
    local dx = sx - (tonumber(hp.x) or 0.0)
    local dy = sy - (tonumber(hp.y) or 0.0)
    local dz = sz - (tonumber(hp.z) or 0.0)
    local gapmag = math.sqrt(dx * dx + dy * dy + dz * dz)
    if gapmag < 0.25 then
        -- Already at the seat -- leave a good mount completely untouched (the whole point is to
        -- rescue a FAR grab, not nudge one that's already right).
        S.route3_warp_fires = (tonumber(S.route3_warp_fires) or 0) + 1
        S.route3_warp_dbg = string.format("warp#%d gap %.2f m -- at seat, no move", S.route3_warp_fires, gapmag)
        return true
    end
    local target = make_position((tonumber(her.x) or 0.0) + dx, (tonumber(her.y) or 0.0) + dy, (tonumber(her.z) or 0.0) + dz)
    local ok = false
    pcall(function() ptf:call("set_UniversalPosition", target); ok = true end)
    S.route3_warp_fires = (tonumber(S.route3_warp_fires) or 0) + 1
    S.route3_warp_dbg = string.format("warp#%d ok=%s Hip->seat gap=(%.2f,%.2f,%.2f)",
        S.route3_warp_fires, tostring(ok), dx, dy, dz)
    return ok
end

function griffin_rider_safe_visual_tick()
    if iris_puppet_seat_active() then return end -- 07-24: puppet seat owns placement
    -- Safe mount placement/orientation. Position uses Hip local POSITION only; heading
    -- uses ActorMotion's visual root offset. The player GameObject, app.Character,
    -- controller and native climb constraint remain completely untouched.
    if S.route3_wilds_rider_pose_active ~= true or S.route3_rider_puppet_on == true then return end
    local pgo = char_go(get_player())
    local ptf = pgo and transform_of(pgo)
    local _, ggo = reacquire_griffin()
    local gtf = ggo and transform_of(ggo)
    if not (ptf and gtf) then return end
    local hip = managed_call(ptf, "getJointByName", "Hip")
    if not hip then return end

    -- WARP-TO-BACK settle window (Aurora 2026-07-18): the engage gate can delay the pose
    -- past a fixed post-mount window, so START the window HERE -- the first tick the pose is
    -- actually live -- not at adopt. For that window, pull her onto the back near the seat
    -- so a side/leg grab normalises before the seat below places her.
    if S.route3_warp_pending == true then
        S.route3_warp_pending = false
        S.route3_mount_warp_until = os.clock() + (tonumber(C.route3_mount_warp_secs) or 1.2)
        S.route3_warp_fires = 0
    end
    if (tonumber(S.route3_mount_warp_until) or 0.0) > os.clock() then
        pcall(griffin_warp_rider_to_back)
    end

    -- Hot-reload migration: restore/forget both failed heading channels immediately.
    if S.route3_rider_safe_yaw_version ~= 6 then
        pcall(griffin_rider_safe_motion_yaw_restore)
        S.route3_rider_safe_yaw_version = 6
        C.route3_rider_visual_yaw_enabled = false
        pcall(save_config)
        S.route3_rider_hip_rest = nil
        S.route3_rider_safe_hip_world0 = nil
        S.route3_rider_safe_motion_base = nil
        S.route3_rider_safe_motion_last = nil
        S.route3_rider_safe_gyaw0 = nil
        S.route3_rider_safe_pyaw0 = nil
        S.route3_rider_euler_conv = nil
    end

    -- LOCK UPRIGHT (Aurora 2026-07-18): the native climb re-solves the rider's ROOT joint
    -- every frame, and that re-solve slowly tips her into a lean/drift even from a perfect
    -- mount. When locked, pass 0.0 so route3_rider_pose_cleanup adds "root" to its reset
    -- list = the root is held LEVEL each frame -> no drift. This is safe now that
    -- route3_rotate_rider_with_griffin (transform yaw) drives her facing: level root +
    -- transform yaw = upright AND turning with the griffin. (The old "root reset pins her
    -- heading" caveat only held while that yaw write was gated off -- it no longer is.)
    -- The Hip-yaw block inside cleanup self-skips in safe mode (no hip_rest captured).
    route3_rider_pose_cleanup(pgo, C.route3_rider_lock_upright == true and 0.0 or nil)
    C.route3_rider_visual_yaw_enabled = false
    local yaw_ok = false

    if C.route3_rider_visual_seat_enabled ~= true then
        S.route3_rider_visual_status = "native climb position + native root orientation (forced yaw parked)"
        return
    end
    local anchor_name = tostring(C.route3_rider_visual_anchor_joint or "Neck_1")
    local anchor = managed_call(gtf, "getJointByName", anchor_name)
    local ap = anchor and managed_call(anchor, "get_Position")
    local hp = managed_call(hip, "get_Position")
    local lp = managed_call(hip, "get_LocalPosition")
    if not (ap and hp and lp) then
        S.route3_rider_visual_status = "visual seat unavailable: missing " .. anchor_name
        return
    end
    local gyaw = yaw_from_transform(ggo) or 0.0
    local fwd = { x = math.sin(gyaw), z = math.cos(gyaw) }
    local right = { x = math.cos(gyaw), z = -math.sin(gyaw) }
    local ox = tonumber(C.route3_rider_visual_offset_x) or 0.0
    local oy = tonumber(C.route3_rider_visual_offset_y) or 0.0
    local oz = tonumber(C.route3_rider_visual_offset_z) or 0.0
    local target = {
        x = (tonumber(ap.x) or 0.0) + right.x * ox + fwd.x * oz,
        y = (tonumber(ap.y) or 0.0) + oy,
        z = (tonumber(ap.z) or 0.0) + right.z * ox + fwd.z * oz,
    }
    local delta = {
        x = target.x - (tonumber(hp.x) or 0.0),
        y = target.y - (tonumber(hp.y) or 0.0),
        z = target.z - (tonumber(hp.z) or 0.0),
    }
    -- CLAMP the per-frame seat correction. A sharp griffin turn whips the neck anchor
    -- through world space faster than the native climb drags her body along, so for one
    -- frame `target` is far ahead of her real Hip and the full correction lunges her toward
    -- the neck (visible stretch). Cap it: normal seating (a few cm) is untouched; a
    -- turn-spike becomes a barely-visible one-frame lag that catches up next frame.
    do
        local dmag = math.sqrt(delta.x * delta.x + delta.y * delta.y + delta.z * delta.z)
        local dmax = tonumber(C.route3_rider_seat_max_step) or 0.6
        if dmag > dmax and dmag > 1e-6 then
            local sfac = dmax / dmag
            delta.x, delta.y, delta.z = delta.x * sfac, delta.y * sfac, delta.z * sfac
        end
    end
    -- Hip is parented to the root joint. Player-joint world rotations are a proven
    -- channel; rotate the world correction back into that parent's local frame.
    local root = managed_call(ptf, "getJointByName", "root")
    local rq = root and managed_call(root, "get_Rotation")
    if not rq then rq = managed_call(ptf, "get_Rotation") end
    local local_delta = delta
    if rq then
        local inv = {
            x = -(tonumber(rq.x) or 0.0), y = -(tonumber(rq.y) or 0.0),
            z = -(tonumber(rq.z) or 0.0), w = tonumber(rq.w) or 1.0,
        }
        local_delta = griffin_q_rotate_vec(inv, delta)
    end
    managed_call(hip, "set_LocalPosition", Vector3f.new(
        (tonumber(lp.x) or 0.0) + local_delta.x,
        (tonumber(lp.y) or 0.0) + local_delta.y,
        (tonumber(lp.z) or 0.0) + local_delta.z))
    S.route3_rider_visual_status = string.format("%s %+0.2f/%+0.2f/%+0.2f; %s",
        anchor_name, ox, oy, oz, yaw_ok and string.format("yaw err %+.1f deg",
            tonumber(S.route3_rider_visual_yaw_error_deg) or 0.0) or "yaw unavailable")
end

-- ROOT-ANCHORED SEAT HOLD (Aurora 2026-07-20, "one last attempt at MH Wilds pose"). The native climb
-- grabs her ROOT at a varying spot every mount (neck/back/mid) = the last unsolved problem now that
-- "Full" bones fixed the tilt. This holds her BODY at a FIXED griffin-relative seat by nudging the Hip
-- LOCAL position toward a target each frame -- the SAME proven channel as the canned visual seat, with
-- ONE change: the anchor is the griffin ROOT (moves SMOOTHLY with the body) instead of Neck_1 (which
-- WHIPS through world space on turns = the drift that killed the old seat). The Hip is pose-owned (Full),
-- NOT climb-owned, so this doesn't fight the native climb's root ownership. Runs at PrepareRendering
-- AFTER the pose applies the hip; keeps the pose's hip ROTATION (upright), overrides only POSITION.
function griffin_rider_seat_hold_tick()
    if iris_puppet_seat_active() then return end -- 07-24: puppet seat owns the hip
    -- AIR SEAT bypasses the (epona-closure forced-false) C gate: with the climb dead and the
    -- pin owning the transform, the hip anchor + root-joint facing are exactly what the
    -- flight seat needs, on the storm-free joint channel this function already uses.
    if C.route3_seat_hold_enabled ~= true and S.route3_air_seat_on ~= true then return end
    if not (S.mounted == true or S.native_climb_mount == true) then return end
    -- Needs SOMETHING to own the hip, or the live animation rewrites it every frame and
    -- the correction never sticks. The Wilds pose was the only owner in July -- but the
    -- FREEZE (MotionFsm2 off + PlaySpeed 0) is a strictly better one: with playback
    -- stopped nothing rewrites the hip local at all, so the correction holds and the
    -- next frame's delta is ~0. This is the round-12 pairing: freeze locks the BONES,
    -- the seat hold anchors that rigid body to the griffin's ROOT (smooth) instead of
    -- letting the climb solver drag it with the animated back ("when the griffin moves
    -- she keeps moving around"). ⛔ Hip-LOCAL writes only -- the transform belongs to
    -- the native climb and writing it is the storm.
    if not (S.route3_wilds_rider_pose_active == true
        or S.griffin_seat_frozen == true
        or S.route3_air_seat_on == true) then return end
    local pgo = char_go(get_player())
    local ptf = pgo and transform_of(pgo)
    local _, ggo = reacquire_griffin()
    if not (ptf and ggo) then return end
    local hip = managed_call(ptf, "getJointByName", "Hip")
    if not hip then return end
    local hp = managed_call(hip, "get_Position")
    local lp = managed_call(hip, "get_LocalPosition")
    local groot = transform_render_pos(ggo)
    if not (hp and lp and groot) then return end
    local gyaw = yaw_from_transform(ggo) or 0.0
    local fwd = { x = math.sin(gyaw), z = math.cos(gyaw) }
    local right = { x = math.cos(gyaw), z = -math.sin(gyaw) }
    local ox = tonumber(C.route3_seat_hold_x) or 0.0
    local oy = tonumber(C.route3_seat_hold_y) or 1.35
    local oz = tonumber(C.route3_seat_hold_z) or -0.4
    local target = {
        x = (tonumber(groot.x) or 0.0) + right.x * ox + fwd.x * oz,
        y = (tonumber(groot.y) or 0.0) + oy,
        z = (tonumber(groot.z) or 0.0) + right.z * ox + fwd.z * oz,
    }
    local delta = {
        x = target.x - (tonumber(hp.x) or 0.0),
        y = target.y - (tonumber(hp.y) or 0.0),
        z = target.z - (tonumber(hp.z) or 0.0),
    }
    local dmag = math.sqrt(delta.x * delta.x + delta.y * delta.y + delta.z * delta.z)
    local dmax = tonumber(C.route3_seat_hold_max_step) or 3.0
    if dmag > dmax and dmag > 1e-6 then
        local s = dmax / dmag
        delta.x, delta.y, delta.z = delta.x * s, delta.y * s, delta.z * s
    end
    -- Hip is parented to the root joint -> rotate the world correction into that parent's local frame
    local root = managed_call(ptf, "getJointByName", "root")
    local rq = (root and managed_call(root, "get_Rotation")) or managed_call(ptf, "get_Rotation")
    local ldelta = delta
    if rq then
        local inv = { x = -(tonumber(rq.x) or 0.0), y = -(tonumber(rq.y) or 0.0), z = -(tonumber(rq.z) or 0.0), w = tonumber(rq.w) or 1.0 }
        ldelta = griffin_q_rotate_vec(inv, delta)
    end
    pcall(function()
        managed_call(hip, "set_LocalPosition", Vector3f.new(
            (tonumber(lp.x) or 0.0) + ldelta.x,
            (tonumber(lp.y) or 0.0) + ldelta.y,
            (tonumber(lp.z) or 0.0) + ldelta.z))
    end)
    -- FACING via the JOINT channel (Fable lead 2026-07-20). ⛔ The OLD facing pin wrote the TRANSFORM
    -- rotation (set_character_rotation_only) -- the channel the FSM/action system OWNS and re-asserts =
    -- "THE STORM" (she detaches/floats/spins). This instead writes the ROOT JOINT's LOCAL rotation at
    -- PrepareRendering -- the SAME storm-free channel the Hip position pin, hand magnet and pose cleanup
    -- all use with zero storm. Set root LOCAL = inverse(transform world rot) x yaw(gyaw), so root WORLD =
    -- upright + facing the griffin, regardless of the (frozen) transform yaw. No transform write -> no FSM
    -- fight -> (hypothesis) no storm. QUAT compose, NOT euler -- the root has no ~90deg roll like the Hip
    -- (round-22 euler-axis trap). This OVERWRITES pose_cleanup's lock-upright root reset (runs after it).
    if C.route3_seat_hold_face_griffin ~= false then
        pcall(function()
            local rootj = managed_call(ptf, "getJointByName", "root")
            local q_t = ptf:call("get_Rotation")               -- transform WORLD rot (root's parent)
            local base = rootj and rootj:call("get_BaseLocalRotation")  -- root's REST local rot (upright)
            if rootj and q_t and base then
                local tx, tyq, tz, tw = tonumber(q_t.x) or 0.0, tonumber(q_t.y) or 0.0, tonumber(q_t.z) or 0.0, tonumber(q_t.w) or 1.0
                local bx, byq, bz, bw = tonumber(base.x) or 0.0, tonumber(base.y) or 0.0, tonumber(base.z) or 0.0, tonumber(base.w) or 1.0
                -- ⛔ v1 set root world = pure yaw(gyaw) and threw base away -> UPSIDE DOWN (the authored
                -- root rest is NOT identity). FIX: preserve base, apply ONLY the world-up yaw delta.
                -- base_world = transform x base_local = her UPRIGHT rest orientation, facing rest_yaw
                local wx, wy, wz, ww = griffin_q_mul(tx, tyq, tz, tw, bx, byq, bz, bw)
                local fwd = griffin_q_rotate_vec({ x = wx, y = wy, z = wz, w = ww }, { x = 0.0, y = 0.0, z = 1.0 })
                local rest_yaw = math.atan(tonumber(fwd.x) or 0.0, tonumber(fwd.z) or 0.0)
                local delta = gyaw - rest_yaw
                local ds, dc = math.sin(delta * 0.5), math.cos(delta * 0.5)   -- world-up yaw(delta)
                -- desired_world = yaw(delta) x base_world (upright preserved, now facing the griffin)
                local ex, ey, ez, ew = griffin_q_mul(0.0, ds, 0.0, dc, wx, wy, wz, ww)
                -- root_local = conj(transform) x desired_world  (world = parent x local)
                local rx, ryq, rz, rw = griffin_q_mul(-tx, -tyq, -tz, tw, ex, ey, ez, ew)
                rootj:call("set_LocalRotation", griffin_make_quat_raw(rx, ryq, rz, rw))
            end
        end)
    end
    S.route3_seat_hold_status = string.format("seat hold (root-anchored) %+.2f/%+.2f/%+.2f dmag=%.2f face=%s(joint)", ox, oy, oz, dmag, tostring(C.route3_seat_hold_face_griffin ~= false))
end

-- SURGICAL COLLISION KILL for the seat-hold ride (Aurora 2026-07-20: "isn't disabling collision what
-- rs_hug did?"). "The storm" (67: she detaches + floats off when we force position/facing) is very
-- likely her LIVE physics capsule colliding with the griffin body and being EJECTED -- the grab system
-- hit the SAME "collision/teleport spazz" and its notes say setCharacterControllerEnable isn't enough,
-- you must disable the actual collider COMPONENTS. set_rider_hard_lock does that, but line ~17220 SKIPS
-- it on native-climb mounts (which is OUR ride), so her CharacterController + GroundFixer stay live.
-- This kills JUST those components (via the proven disable_rider_record) -- NOT the think-stop/FSM-disable
-- the full hard-lock also does (those would break the climb). Restores them the moment she dismounts.
function griffin_seat_collision_tick()
    if iris_puppet_seat_active() then return end -- 07-24: puppet seat runs its own suppression
    -- PER-TICK STORM SUPPRESSOR (Aurora 2026-07-20). v1 was WRONG twice: too-narrow list + ONE-SHOT.
    -- The grab code's notes name the real storm fingerprint: native RE-ENABLES via.motion.JointConstraints
    -- + via.motion.IkLeg2 EVERY frame (IkLeg2 = the "no ground -> call rescue" reporter), plus the
    -- collider/hit components grind inside the griffin. Counter = disable them PER TICK (last-writer-wins).
    -- ⛔ Deliberately does NOT touch MotionFsm2 / Human.Fsm / think-stop -- those are the full puppet
    -- lockdown that BREAKS the native climb + flight. So this tests the collider+constraint+IK layer ONLY;
    -- if the storm survives it, the culprit is the FSM layer = the true wall we can't kill without flight.
    local mounted = (S.mounted == true or S.native_climb_mount == true)
    local want = (C.route3_seat_hold_kill_collision == true) and mounted
    S.route3_seat_disabled = S.route3_seat_disabled or {}
    local csv = tostring(C.route3_seat_storm_components
        or "via.physics.RequestSetCollider,via.physics.Colliders,via.physics.CharacterController,CharacterController,app.HitController,GroundFixer,JointConstraints,IkLeg2")
    if want then
        local pgo = char_go(get_player())
        local n = 0
        pcall(function()
            local comps = pgo and pgo:call("get_Components")
            for _, c in ipairs(system_array_to_table(comps)) do
                local td = c and c:get_type_definition()
                local full = td and td:get_full_name() or ""
                local short = full:match("([^%.]+)$") or full
                if name_matches_csv(full, csv) or name_matches_csv(short, csv) then
                    if S.route3_seat_disabled[c] == nil then
                        local was = true
                        pcall(function() local v = c:call("get_Enabled"); if type(v) == "boolean" then was = v end end)
                        S.route3_seat_disabled[c] = { was = was, label = short }
                    end
                    pcall(function() c:call("set_Enabled", false) end)   -- PER TICK -- native re-enables it
                    n = n + 1
                end
            end
        end)
        S.route3_seat_collision_status = string.format("storm-suppress: %d comps/tick", n)
    elseif next(S.route3_seat_disabled) ~= nil then
        for c, rec in pairs(S.route3_seat_disabled) do
            if rec and rec.was ~= false then pcall(function() c:call("set_Enabled", true) end) end
            S.route3_seat_disabled[c] = nil
        end
        S.route3_seat_collision_status = "storm-suppress: restored"
    end
end


-- ==================== ROUND-56: THE JACK-MOUNT (native saddle) ====================
-- The riding-position endgame, assembled from the round 51-55 discoveries: spawn a
-- SEAT gimmick (default: ox-cart bench gm80_042_00, the motjack/ActStart family --
-- the ONLY family where ActStart exists; stool = fallback checkbox), neuter its collision,
-- WELD it to the griffin's Neck_1 saddle point per frame (a prop's transform is
-- freely writable -- no R20 player-quat law here), then jack the player onto it via
-- app.AdjustJack (field-proven: jack->true on town gimmicks). A jacked passenger is
-- a SANCTIONED state: fixed in place, posed by the seat's own MotionJackFsm2, and
-- exempt from the fall/rescue machinery that made the puppet unwinnable (R48-50).
-- v1 = dev buttons; wire into the ride flow once field-proven.

function griffin_saddle_states(fsm)
    -- compact port of the InteractButton v2 state reader (EMV BehaviorTree chain:
    -- get_Layer() core handles -> get_tree_object -> get_nodes -> get_full_name).
    -- The state SET decides which entry we jack -- "ActStart" only exists on the
    -- motjack family (oxcart bench); chairs use SitDown/SitLoop; blanket defaults
    -- were the round-56 "she sits NEAR the stool" bug.
    local names, set = {}, {}
    if not fsm then return names, set end
    local handles = {}
    pcall(function() handles = system_array_to_table(fsm:call("get_Layer()")) or {} end)
    if #handles == 0 then
        pcall(function()
            local t = fsm:get_trees()
            if type(t) == "table" then handles = t end
        end)
    end
    pcall(function()
        for _, ch in ipairs(handles) do
            local tree = nil
            pcall(function() tree = ch.get_tree_object and ch:get_tree_object() end)
            if tree then
                local nodes = nil
                pcall(function() nodes = tree:get_nodes() end)
                for _, node in ipairs(nodes or {}) do
                    local fn = nil
                    pcall(function() fn = node:get_full_name() end)
                    if fn and fn ~= "" and not tostring(fn):find("%.") then
                        local k = tostring(fn):lower()
                        if not set[k] then
                            set[k] = tostring(fn)
                            names[#names + 1] = tostring(fn)
                        end
                    end
                end
            end
        end
    end)
    return names, set
end

function griffin_saddle_resolve_entry(set)
    -- priority: explicit config -> motjack seat (ActStart, the PROVEN passenger
    -- state from the ox-cart tape) -> chair sit -> generic starts -> first state
    local override = tostring(C.route3_saddle_state or "")
    if override ~= "" then
        local hit = set[override:lower()]
        if hit then return hit, "config" end
    end
    for _, cand in ipairs({ "ActStart", "SitDown", "SitLoop", "StartAction", "Start" }) do
        local hit = set[cand:lower()]
        if hit then return hit, "auto" end
    end
    for k, real in pairs(set) do
        if k ~= "root" and not k:find("end") and k ~= "finish" then
            return real, "first-nonterminal"
        end
    end
    return nil, "none"
end

function griffin_saddle_neuter(go)
    -- kill every collider/physics piece on the seat tree (a solid prop embedded in
    -- the griffin would feed the press/rescue systems); KEEP via.motion.* -- the
    -- MotionJackFsm2 is the whole point. Mesh visibility is a separate checkbox.
    local killed = 0
    local function sweep(g, depth)
        if not g or depth > 4 then return end
        pcall(function()
            for _, c in ipairs(system_array_to_table(g:call("get_Components")) or {}) do
                local tn = ""
                pcall(function() tn = tostring(c:get_type_definition():get_full_name()) end)
                if tn:find("via.physics", 1, true) or tn:find("Collider", 1, true)
                    or tn:find("app.HitController", 1, true) or tn:find("AdjustPress", 1, true) then
                    pcall(function() c:call("set_Enabled", false) end)
                    killed = killed + 1
                end
            end
        end)
        pcall(function()
            local tf = g:call("get_Transform")
            local child = tf and tf:call("get_Child")
            while child do
                sweep(child:call("get_GameObject"), depth + 1)
                child = child:call("get_Next")
            end
        end)
    end
    sweep(go, 0)
    return killed
end

function griffin_saddle_set_visible(go, visible)
    local function sweep(g, depth)
        if not g or depth > 4 then return end
        pcall(function()
            local mesh = g:call("getComponent(System.Type)", sdk.typeof("via.render.Mesh"))
            if mesh then mesh:call("set_Enabled", visible == true) end
        end)
        pcall(function()
            local tf = g:call("get_Transform")
            local child = tf and tf:call("get_Child")
            while child do
                sweep(child:call("get_GameObject"), depth + 1)
                child = child:call("get_Next")
            end
        end)
    end
    sweep(go, 0)
end

function griffin_saddle_find_fsm(go)
    -- ROUND-58: collect EVERY jack FSM in the spawned tree and pick the best SEAT.
    -- The R57 first-hit search grabbed the PARENT cart's own FSM (driver states:
    -- FreeGetOff etc.) and never reached the passenger seat children -- the town
    -- bench worked because Aurora scanned the seat child directly. Scoring:
    -- ActStart in the state set +10 (the proven passenger entry), GO name contains
    -- "seat" +5, is a child not the root +2. ALL candidates logged with their
    -- states -- if the spawned cart has no seat children at all, the log says so.
    local candidates = {}
    local function sweep(g, depth)
        if not g or depth > 6 then return end
        pcall(function()
            local f = g:call("getComponent(System.Type)", sdk.typeof("via.motion.MotionJackFsm2"))
            if f then
                local names, set = griffin_saddle_states(f)
                local nm = tostring(go_name(g) or "?")
                local score = 0
                if set["actstart"] then score = score + 10 end
                if nm:lower():find("seat", 1, true) then score = score + 5 end
                if depth > 0 then score = score + 2 end
                candidates[#candidates + 1] = {
                    fsm = f, go = g, names = names, set = set, score = score, name = nm,
                }
            end
        end)
        pcall(function()
            local tf = g:call("get_Transform")
            local child = tf and tf:call("get_Child")
            while child do
                sweep(child:call("get_GameObject"), depth + 1)
                child = child:call("get_Next")
            end
        end)
    end
    sweep(go, 0)
    for _, c in ipairs(candidates) do
        pcall(function() log.info(string.format("[GriffinRide] saddle FSM candidate: %s (score %d) states: %s",
            c.name, c.score, #c.names > 0 and table.concat(c.names, ", ") or "(none)")) end)
    end
    local best = nil
    for _, c in ipairs(candidates) do
        if best == nil or c.score > best.score then best = c end
    end
    return best, #candidates
end

function griffin_saddle_pump_tick()
    -- finish an in-flight saddle spawn (prefab readiness is async)
    local sp = S.route3_saddle_spawn
    if type(sp) ~= "table" then return end
    if os.clock() - (tonumber(sp.at) or 0.0) > 10.0 then
        S.route3_saddle_spawn = nil
        S.route3_saddle_status = "saddle spawn TIMED OUT"
        return
    end
    pcall(function()
        if not sp.prefab:call("get_Ready") then return end
        if not sp.spawned then
            local gm = sdk.get_managed_singleton("app.GenerateManager")
            local m = gm and sdk.find_type_definition("app.GenerateManager"):get_method(
                "requestCreateInstance(app.PrefabController, app.GenerateInfo.GenerateInfoContainer, System.Int32, app.InstanceInfo, System.Action`2<app.PrefabInstantiateResults,app.DummyArg>, System.Action`2<app.PrefabInstantiateResults,app.DummyArg>)")
            if not m then S.route3_saddle_spawn = nil; S.route3_saddle_status = "GenerateManager method missing"; return end
            m:call(gm, sp.pc, sp.gi, 0, sp.ii, nil, nil)
            sp.spawned = true
        end
        local go = sp.ii["<Instance>k__BackingField"]
        if go then
            pcall(function() go:add_ref() end)
            S.route3_saddle_go = go
            S.route3_saddle_spawn = nil
            local killed = 0
            -- ROUND-59: neuter is now optional -- the town seats (jack -> true) have
            -- LIVE colliders; if the jack validates against something we disabled,
            -- the neuter itself is the nil-thrower. Untick to test.
            if C.route3_saddle_neuter ~= false then
                pcall(function() killed = griffin_saddle_neuter(go) end)
            end
            if C.route3_saddle_hide == true then
                pcall(griffin_saddle_set_visible, go, false)
            end
            local hit, n_cand = griffin_saddle_find_fsm(go)
            S.route3_saddle_fsm = hit and hit.fsm or nil
            S.route3_saddle_fsm_go = hit and hit.go or nil
            if hit then
                pcall(function() hit.fsm:add_ref(); hit.go:add_ref() end)
            end
            -- ROUND-57/58: resolve the entry from the CHOSEN seat's real state set
            -- (the R56 bug: jacking a state the FSM doesn't have = ground-sit beside
            -- the seat; the R57 bug: first-found FSM = the parent cart's driver FSM)
            local entry, how = nil, "none"
            if hit then
                S.route3_saddle_set = hit.set
                entry, how = griffin_saddle_resolve_entry(hit.set)
            end
            S.route3_saddle_entry = entry
            S.route3_saddle_status = string.format(
                "SADDLE SPAWNED (%s): %d collider(s) neutered, %d jack FSM(s), best %s, entry %s (%s)",
                tostring(go_name(go) or "?"), killed, tonumber(n_cand) or 0,
                hit and (tostring(hit.name) .. " score " .. tostring(hit.score)) or "MISSING",
                tostring(entry or "NONE"), tostring(how))
            pcall(function() log.info("[GriffinRide] " .. tostring(S.route3_saddle_status)) end)
        end
    end)
end

function griffin_saddle_follow_tick()
    -- per-frame WELD: park the saddle at the Neck_1 seat point (render joint pos
    -- rebased to universal via the root delta -- the goblin-carry law), oriented to
    -- the griffin's flat yaw + the seat-shaping yaw config. Runs in
    -- LateUpdateBehavior after the flight drive so the seat rides this frame's pose.
    local go = S.route3_saddle_go
    if go == nil then return end
    local valid = false
    pcall(function() valid = go:call("get_Valid") ~= false end)
    if not valid then S.route3_saddle_go = nil; S.route3_saddle_fsm = nil; return end
    local _, ggo = reacquire_griffin()
    local gtf = ggo and transform_of(ggo)
    if not gtf then return end
    local anchor = tostring(C.route3_rider_anchor_joint or C.route3_seat_joint or "Neck_1")
    local joint = managed_call(gtf, "getJointByName", anchor)
    local jp = joint and managed_call(joint, "get_Position")
    if not jp then S.route3_saddle_status = "saddle: joint '" .. anchor .. "' not found"; return end
    local gup, grp = nil, nil
    pcall(function() gup = gtf:call("get_UniversalPosition") end)
    pcall(function() grp = gtf:call("get_Position") end)
    if not (gup and grp) then return end
    local yaw = yaw_from_transform(ggo) or 0.0
    local fwd = { x = math.sin(yaw), z = math.cos(yaw) }
    local right = { x = math.cos(yaw), z = -math.sin(yaw) }
    local fine_x = tonumber(C.route3_rider_lock_offset_x) or 0.0
    local fine_y = tonumber(C.route3_rider_lock_offset_y) or 0.0
    local fine_z = tonumber(C.route3_rider_lock_offset_z) or 0.0
    local drop = tonumber(C.route3_saddle_drop) or 0.45
    local pos = make_position(
        jp.x + (gup.x - grp.x) + right.x * fine_x + fwd.x * fine_z,
        jp.y + (gup.y - grp.y) + fine_y - drop,
        jp.z + (gup.z - grp.z) + right.z * fine_x + fwd.z * fine_z)
    -- child-offset compensation (round-57): the jack seat may be a CHILD of the
    -- welded GO (the oxcart bench carries per-seat children metres from the cart
    -- origin) -- shift the parent so the SEAT CHILD lands on the seat point.
    -- Uses the current measured offset, so it converges within a frame or two.
    local fgo = S.route3_saddle_fsm_go
    if fgo ~= nil and fgo ~= go then
        pcall(function()
            local cpos = transform_pos(fgo)
            local ppos2 = transform_pos(go)
            if cpos and ppos2 then
                pos = make_position(
                    pos.x - (cpos.x - ppos2.x),
                    pos.y - (cpos.y - ppos2.y),
                    pos.z - (cpos.z - ppos2.z))
            end
        end)
    end
    local rot = make_quat_yaw(yaw + math.rad(tonumber(C.route3_rider_lock_yaw_deg) or 0.0))
    pcall(function() set_transform(go, pos, rot) end)
end

function griffin_saddle_jack(on)
    local player = get_player()
    local pgo = char_go(player)
    local aj = pgo and get_component(pgo, "app.AdjustJack")
    if not aj then S.route3_saddle_status = "no AdjustJack on player"; return end
    if on ~= true then
        pcall(function() aj:call("rejectSelf") end)
        S.route3_saddle_status = "saddle released"
        return
    end
    local seat_go = S.route3_saddle_fsm_go or S.route3_saddle_go
    local seat_fsm = S.route3_saddle_fsm
    if not (seat_go and seat_fsm) then
        S.route3_saddle_status = "no saddle (spawn it first; jack FSM must be FOUND)"
        return
    end
    local function make_req(tn)
        local inst, how = nil, "ctor"
        pcall(function() inst = sdk.create_instance(tn) end)
        if inst == nil then
            how = "manual-alloc"
            pcall(function() inst = sdk.create_instance(tn, true) end)
        end
        if inst ~= nil then pcall(function() inst:add_ref() end) else how = "FAILED" end
        return inst, how
    end
    local jr, jr_how = make_req("app.AdjustJack.JackRequest")
    local pmr, pmr_how = make_req("app.AdjustJack.PlayMotionRequest")
    if not (jr and pmr) then S.route3_saddle_status = "could not create jack requests"; return end
    -- ROUND-59 forensics: the identical call succeeded on the TOWN seat_03 but
    -- returns nil (= swallowed exception) on OUR spawned one -- surface everything
    local can = nil
    pcall(function() can = aj:call("canJack(app.AdjustJack.Priority)", 4) end)
    pcall(function() log.info(string.format(
        "[GriffinRide] saddle jack pre-flight: jr=%s pmr=%s canJack(4)=%s seat_valid=%s",
        jr_how, pmr_how, tostring(can),
        tostring(seat_go:call("get_Valid")))) end)
    local entry = S.route3_saddle_entry
    if type(S.route3_saddle_set) == "table" then
        -- re-resolve live so the override field works without respawning
        local e2 = griffin_saddle_resolve_entry(S.route3_saddle_set)
        if e2 then entry = e2 end
    end
    if not entry or entry == "" then
        S.route3_saddle_status = "no resolved entry state (see saddle FSM states in the log)"
        return
    end
    pcall(function() jr:set_field("<Owner>k__BackingField", seat_go) end)
    pcall(function() jr:set_field("<Priority>k__BackingField", 4) end)
    pcall(function() pmr:set_field("<Owner>k__BackingField", seat_go) end)
    pcall(function() pmr:set_field("<StateName>k__BackingField", tostring(entry)) end)
    pcall(function() pmr:set_field("<IsFullNameState>k__BackingField", false) end)
    pcall(function() pmr:set_field("<motionJackFsm>k__BackingField", seat_fsm) end)
    pcall(function() pmr:set_field("<LayerNo>k__BackingField", 0) end)
    pcall(function() pmr:set_field("<StartFrame>k__BackingField", 0.0) end)
    pcall(function() pmr:set_field("<InterpolationFrame>k__BackingField", 30.0) end)
    pcall(function() pmr:set_field("<InterpolationMode>k__BackingField", 1) end)
    pcall(function() pmr:set_field("<InterpolationCurve>k__BackingField", 3) end)
    local ok = nil
    local okc, callerr = pcall(function()
        ok = aj:call("requestJackAndPlayMotion(app.AdjustJack.JackRequest, app.AdjustJack.PlayMotionRequest)", jr, pmr)
    end)
    if ok ~= true then
        -- ⛔ ROUND-60: a THROWN jack leaves the PLAYER HALF-JACKED -- doJack stops
        -- her action systems before the exception unwinds, and nothing restarts
        -- them (Aurora's field report: can't interact or attack until a full game
        -- reload). Restore her on EVERY failed jack, unconditionally.
        pcall(function() aj:call("rejectSelf") end)
        pcall(function() aj:call("restartOwnerProcess", true) end)
        pcall(function() aj:call("enableOwnerFSM") end)
    end
    S.route3_saddle_status = string.format("saddle jack -> %s (seat %s, state %s)%s",
        tostring(ok), tostring(go_name(seat_go) or "?"), tostring(entry),
        (not okc) and (" CALL ERROR: " .. tostring(callerr) .. " (player auto-restored)") or "")
    pcall(function() log.info("[GriffinRide] " .. tostring(S.route3_saddle_status)) end)
end

function griffin_saddle_despawn()
    pcall(function() griffin_saddle_jack(false) end)
    local go = S.route3_saddle_go
    local borrowed = S.route3_saddle_borrowed
    S.route3_saddle_go = nil
    S.route3_saddle_fsm = nil
    S.route3_saddle_fsm_go = nil
    S.route3_saddle_spawn = nil
    S.route3_saddle_borrowed = nil
    if go and borrowed then
        -- return the town's furniture where we found it
        if type(borrowed) == "table" then
            pcall(function()
                local pos = make_position(borrowed.x, borrowed.y, borrowed.z)
                local tf = go:call("get_Transform")
                local rq = tf:call("get_Rotation")
                rq.x = borrowed.qx; rq.y = borrowed.qy; rq.z = borrowed.qz; rq.w = borrowed.qw
                set_transform(go, pos, rq)
            end)
        end
        S.route3_saddle_status = "borrowed bench returned home"
        return
    end
    if go then pcall(function() go:call("destroy(via.GameObject)", go) end) end
    S.route3_saddle_status = "saddle removed"
end

function griffin_seat_joint_universal(go, gpos)
    -- ⭐⭐ THE RIDER-FOLLOWS-THE-ANIMATION FIX (2026-07-26, measured not guessed).
    -- Probe results: root joint drift 0.000m over 1973 samples, body upY never left 1.0 --
    -- so the object transform NEVER tilts and NEVER leaves our own flight path. The loop is a
    -- pose animation in the joints below root. Spine_2 swings 4.725m against root through it
    -- (peak offset (-0.14 -3.05 -0.06) = her inverted at the top). Pinning the rider to the
    -- object transform therefore CANNOT ever follow the animation -- that is the whole bug.
    --
    -- Joint positions read in LOCAL/RENDER space; the object transform is UNIVERSAL, and the
    -- two differ by a constant streaming-cell offset (measured (-640,-128,+1152)). Rebase via
    -- ROOT, which the probe proved is rigid to the object transform, so the tile offset
    -- cancels exactly -- the same "rebase render->universal via the actor root" law the
    -- goblin-carry talon pin already uses.
    local tf = transform_of(go)
    if not (tf and gpos) then return nil end
    local rj = managed_call(tf, "getJointByName", "root")
    local sj = managed_call(tf, "getJointByName", tostring(C.route3_seat_joint or "Spine_2"))
    local rp = rj and managed_call(rj, "get_Position")
    local sp = sj and managed_call(sj, "get_Position")
    if not (rp and sp and tonumber(rp.x) and tonumber(sp.x)) then return nil end
    local bx = (tonumber(gpos.x) or 0.0) - (tonumber(rp.x) or 0.0)
    local by = (tonumber(gpos.y) or 0.0) - (tonumber(rp.y) or 0.0)
    local bz = (tonumber(gpos.z) or 0.0) - (tonumber(rp.z) or 0.0)
    return make_position(
        (tonumber(sp.x) or 0.0) + bx + (tonumber(C.route3_rider_seat_fine_x) or 0.0),
        (tonumber(sp.y) or 0.0) + by + (tonumber(C.route3_rider_seat_fine_y) or 0.0),
        (tonumber(sp.z) or 0.0) + bz + (tonumber(C.route3_rider_seat_fine_z) or 0.0))
end

-- ⭐ Shared window gate for BOTH seat-joint follows (Arisen + pawn). See route3_rider_seat_always.
-- Reuses the node lockout so "the rider follows the animation" and "nothing else may touch her"
-- are the same window by construction -- they cannot drift apart and disagree.
function griffin_rider_seat_window_active(now)
    if C.route3_rider_seat_always == true then return true end
    now = tonumber(now) or os.clock()
    local locked = false
    pcall(function() locked = griffin_node_lockout_active(now) == true end)
    if locked then S.route3_rider_seat_win_at = now; return true end
    -- brief tail so releasing back to the flat seat is a settle, not a snap
    local tail = math.max(0.0, tonumber(C.route3_rider_seat_window_tail) or 0.25)
    local last = tonumber(S.route3_rider_seat_win_at)
    return last ~= nil and (now - last) <= tail
end

-- ⭐⭐ LOOP CAMERA (2026-08-04, Aurora: "it always has the griffin right at the top or bottom of
-- the screen... I'd like to either follow the griffin and keep it in the centre, or a cinematic
-- camera like the oxcart"). The ordinary ride camera is welded behind the rider, so when the node
-- throws her 6m through a loop she leaves the frame entirely.
--
-- Two things make the loop actually READ, and both are deliberate:
--   1. The filming yaw is FROZEN at the moment the node fires. If the camera orbited her live
--      heading it would rotate WITH her through the loop and the loop would look like nothing at
--      all -- you only see a loop from a fixed vantage. This is why it films side-on.
--   2. The aim point blends between a held ANCHOR (the loop's centre) and her live position.
--      blend 1.0 = pure follow, she stays dead-centre. Lower = she arcs through frame = cinematic.
--
-- Camera-only: this never writes the griffin or the rider. Same rig IrisCreatureCam proved --
-- post-hook app.MainCameraController.lateUpdate so our pose survives the controller each frame.
-- ⭐⭐ SEAT BASELINE PROBE (2026-08-04). The riders are PERMANENTLY displaced after a loop, and I
-- have guessed the cause wrong twice, so this measures instead.
--
-- Both seats are derived points, and they do NOT share a baseline -- which is the whole value of
-- this probe. The rider seat rebases via the ROOT joint (griffin_seat_joint_universal), the pawn
-- seat rebases via the RENDER position (griffin_pawn_seat_point). So:
--   * both shift by the SAME amount   -> the shared input moved: the seat JOINT itself, i.e. the
--                                        node left a residual pose and the skeleton never reset
--   * only the rider shifts           -> the ROOT joint drifted from the object transform
--   * only the pawn shifts            -> universal-vs-render (the streaming-cell rebase) moved
--   * nothing shifts but they LOOK wrong -> it is not the seat maths at all; it is the climb/attach
-- That is a genuine four-way discriminator, which is exactly what guessing could not give us.
-- ⭐⭐ RIDE HUD -- rename the on-screen action prompts to the griffin's actual abilities.
-- Technique learned by READING Puppeteer/PuppetHandler.lua:178 (handle_enemy_ui). We implement our
-- own; Nick's files are never touched. The game's action-guide panel is the GameObject "ui010201";
-- each prompt is a via.gui text object reached with via.gui.Control.getObject(path), and the label
-- is just set_Message(string). Guarded on get_DrawSelf so we never poke a hidden panel.
--
-- ⚠ These are the CONTROL-STICK-side panel names, not Xbox letters: R1/R2 = RB/RT, L1/L2 = LB/LT.
function griffin_ride_hud_paths()
    return {
        Y  = "PNL_top/PNL_L02/PNL_txt/mtx_00",
        L1 = "PNL_top/PNL_L01/PNL_txt/mtx_00",
        L2 = "PNL_top/PNL_L00/PNL_txt/mtx_00",
        X  = "PNL_top/PNL_L03/PNL_txt/mtx_00",
        A  = "PNL_top/PNL_R03/PNL_txt/mtx_00",
        B  = "PNL_top/PNL_R02/PNL_txt/mtx_00",
        R1 = "PNL_top/PNL_R01/PNL_txt/mtx_00",
        R2 = "PNL_top/PNL_R00/PNL_txt/mtx_00",
    }
end

function griffin_ride_hud_tick()
    if C.route3_ride_hud ~= true then S.route3_ride_hud_status = "off"; return end
    if S.mounted ~= true then S.route3_ride_hud_status = "not mounted"; return end
    -- ⭐ GROUND vs FLIGHT (Aurora): the same buttons mean different things with her feet down, so
    -- pick the set first. A blank ground label falls through to the flight label rather than
    -- blanking the prompt -- an empty prompt is worse than a slightly wrong one.
    local airborne = (S.airborne == true)
    -- ⛔ FIXED 2026-08-04 (Aurora): a blank GROUND label used to fall through to the FLIGHT label,
    -- so R2/L2 showed flight names with her feet down. That also contradicted the panel's own hint
    -- ("Blank = leave the game's label"). Blank now means exactly that: we do not write that slot
    -- at all and the game's own prompt stands.
    local function pick(b)
        if airborne then return C["route3_hud_" .. b] end
        return C["route3_hudg_" .. b]
    end
    local labels = {}
    for _, b in ipairs({ "Y", "X", "A", "B", "L1", "L2", "R1", "R2" }) do labels[b] = pick(b) end
    -- Ground attack is contextual: while actually sprinting forwards the same Y/Attack press
    -- starts the LandDash charge. Change the visible label before the carrying override below.
    local charge_ready = not airborne and C.route3_charge_enabled ~= false
        and S.last_character_root_move_run == true
        and (tonumber(S.last_character_root_forward) or 0.0) > 0.25
    if charge_ready then labels.Y = tostring(C.route3_hudg_Y_charge or "Charge") end
    -- ⭐ STATE OVERRIDE: once something is in her talons, the button that grabbed it now DROPS it.
    -- A prompt still reading "Grab" is actively lying about what the button does.
    local carrying = false
    pcall(function()
        carrying = (type(S.route3_grab) == "table" and S.route3_grab.carried ~= nil)
            or (S.route3_predation_carry_active == true)
    end)
    if carrying then
        if tostring(C.route3_hud_Y_carrying or "") ~= "" then labels.Y = C.route3_hud_Y_carrying end
        if tostring(C.route3_hud_X_carrying or "") ~= "" then labels.X = C.route3_hud_X_carrying end
    end
    S.route3_ride_hud_set = (airborne and "flight" or "ground")
        .. (charge_ready and "+charge" or "") .. (carrying and "+carrying" or "")
    local wrote, why = 0, "?"
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        if not scene then why = "no scene"; return end
        local ui = scene:call("findGameObject(System.String)", "ui010201")
        if not ui then why = "no ui010201 (panel not in this scene)"; S.route3_hud_panel_drawn = false; return end
        if ui:get_DrawSelf() ~= true then
            why = "panel hidden right now"
            -- ⭐ Doubles as a PAUSE / MENU signal for the loop camera: the action-prompt panel is
            -- hidden whenever we are not in normal gameplay. Cheaper and more reliable than
            -- inventing a pause check, and the tape already proved it flips (22:47:57).
            S.route3_hud_panel_drawn = false
            return
        end
        S.route3_hud_panel_drawn = true
        local base = get_component(ui, "app.GUIBase")
        local root = base and base.Root
        if not root then why = "no GUIBase root"; return end
        local getobj = sdk.find_type_definition("via.gui.Control"):get_method("getObject(System.String)")
        if not getobj then why = "no getObject method"; return end
        -- ⭐⭐ THE "B ONLY SHOWS WITH LB HELD" ANSWER (2026-08-04, from _huddiag.json):
        --     B / L2 / R1  playstate = "DISABLE_HIDETXT"     <- literally "disabled, hide text"
        --     A / X / Y / R2 playstate = "DEFAULT"
        -- The panel was VISIBLE the whole time -- set_Visible was never the lever. The game marks
        -- the slot disabled for the current context and that suppresses our label.
        -- ⭐ Rather than guess the enum's numeric value, HARVEST a known-good PlayState off a panel
        -- that is currently DEFAULT and copy it onto the disabled ones. Self-correcting, and it
        -- cannot break if the enum ever changes.
        -- ⛔⛔⛔ THE set_PlayState UN-DISABLE IS DEAD -- TWO CTDs, DO NOT REBUILD IT (2026-08-05).
        -- The plan was: harvest a healthy panel's PlayState, copy it onto a DISABLE_HIDETXT slot so
        -- our label shows (the "B only appears with LB held" complaint). The harvest and the copy
        -- both WORKED (tape: B/L2/R1 DISABLE_HIDETXT -> forced ok -> DEFAULT)... and the game died
        -- within the same second, BOTH times it ever ran: once at mount (ground set, panel caught
        -- mid-"DECIDE"), and once ~5s later after the settle-gate moved it to the flight set --
        -- the last dump caught the frame BEFORE the settle expired, then death. Same lever, two
        -- different moments, no other new code running: writing PlayStates into the prompt GUI's
        -- state machine is lethal, full stop. READING states stays (that diag is how we know any
        -- of this). The B slot joining the set only while LB is held is game behaviour we accept.
        S.route3_hud_goodstate = "(un-disable REMOVED -- 2 CTDs)"
        for btn, path in pairs(griffin_ride_hud_paths()) do
            local txt = tostring(labels[btn] or "")
            if txt ~= "" then
                local o = getobj:call(root, path)
                -- ⛔ re-assert EVERY frame: the game rewrites these labels itself whenever the
                -- prompt set changes, so a one-shot write is visibly overwritten a moment later.
                if o then pcall(function() o:call("set_Message", txt); wrote = wrote + 1 end) end
                -- ⭐ FORCE THE SLOT VISIBLE (Aurora: "soar/sprint on B isn't showing unless L1 is
                -- held"). Setting the text is not enough -- the game also decides which prompt
                -- PANELS are shown for the current context, and B only joins the set while L1 is
                -- held. Un-hide the owning panel so a label we have written is actually readable.
                if C.route3_ride_hud_force_show ~= false then
                    local panel_path = path:gsub("/PNL_txt/mtx_00$", "")
                    local pnl = getobj:call(root, panel_path)
                    -- ⭐ MEASURE, don't guess. Two blind attempts at un-hiding B have failed, so
                    -- record what actually happens: does the panel object even resolve, what is
                    -- its Visible state, and does our write stick? Written to disk per button.
                    local rec = { path = panel_path, resolved = (pnl ~= nil) }
                    if pnl then
                        pcall(function() pnl:call("set_Visible", true) end)
                        -- READ-ONLY from here on -- see the ⛔⛔⛔ law above: set_PlayState = CTD ×2
                        pcall(function() rec.playstate = tostring(pnl:call("get_PlayState")) end)
                    end
                    S.route3_hud_diag = S.route3_hud_diag or {}
                    S.route3_hud_diag[btn] = rec
                end
            end
        end
        why = "ok"
    end)
    S.route3_ride_hud_status = string.format("%s (%d labels, %s set)", why, wrote,
        tostring(S.route3_ride_hud_set or "?"))
    -- ⭐⭐ FAKE B: draw our own prompt line for the slot the cling context withholds (config note
    -- has the full story). Gated on the REAL slot being suppressed -- when LB reveals the game's
    -- own B prompt (playstate flips to DEFAULT), ours disappears the same frame.
    S.route3_hud_fakeb = nil
    S.route3_hud_faker3 = nil
    if S.route3_hud_panel_drawn == true then
        local w, h = 1920.0, 1080.0
        pcall(function()
            local ds = imgui.get_display_size()
            if ds then w = tonumber(ds.x) or w; h = tonumber(ds.y) or h end
        end)
        local sc = h / 1080.0
        local bx = w - (tonumber(C.route3_hud_fakeb_dx) or 245.0) * sc
        local by = h - (tonumber(C.route3_hud_fakeb_dy) or 63.0) * sc
        -- ⭐ in the GAME's face (Alegreya via IrisFont's per-call override) at her chosen size;
        -- glyph-to-label gap scales with the size so growing the font can't overlap the words
        local fpx = math.max(12.0, tonumber(C.route3_hud_fake_px) or 21.0)
        local fface = tostring(C.route3_hud_fake_face or "Alegreya.ttf")
        local gap = fpx * 1.3 * sc
        local function fake_text(s2, x2, y2, c2, px2)
            local F = _G.IrisFont
            local p2 = px2 or fpx
            if not (F and F.text and F.text(s2, x2, y2, c2, p2, nil, fface)) then
                iris_hud_text(s2, x2, y2, c2, p2)
            end
        end
        -- ⭐ PRESS HIGHLIGHT (Aurora 2026-08-08: "the native UI lights up when you hold a
        -- button -- can we do this for our fake buttons?"). The vanilla prompts brighten
        -- their glyph + word while the button is held; ours were painted at one fixed
        -- colour, so a held button looked identical to an idle one. Read the SAME raw pad
        -- mask the ride controls already use (S.last_raw_button_mask, refreshed every
        -- frame by the input layer) and swap in a lit colour pair.
        -- ⛔ Mask only -- no isButtonOn: these prompts are drawn while the ride owns input,
        -- and the game's own button state is suppressed there (that suppression is WHY we
        -- draw fake prompts in the first place).
        local function pad_held(names)
            local down = false
            pcall(function() down = raw_gamepad_button_down(names) == true end)
            return down
        end
        -- lit = near-white. IDLE is the important half (Aurora 2026-08-08: "make the fake
        -- words look like the same semi-grayed words the normal ones use" -- ours were
        -- painted at full cream, so beside the game's dimmed prompts they read as
        -- permanently lit and the press highlight had nothing to contrast against).
        -- One shared idle grey for every fake WORD; glyphs keep their identity colour.
        local LIT_LABEL = tonumber(C.route3_hud_lit_label) or 0xFFFFFFFF
        local LIT_GLYPH = tonumber(C.route3_hud_lit_glyph) or 0xFFFFFFFF
        local DIM_LABEL = tonumber(C.route3_hud_idle_label) or 0xFF9C9C9C
        local function lit_pair(names, glyph_idle, label_idle)
            if pad_held(names) then return LIT_GLYPH, LIT_LABEL end
            return glyph_idle, (label_idle or DIM_LABEL)
        end
        if C.route3_hud_fake_b ~= false then
            local txt = tostring(labels.B or "")
            local brec = S.route3_hud_diag and S.route3_hud_diag.B
            local suppressed = brec and tostring(brec.playstate or ""):find("DISABLE", 1, true) ~= nil
            if txt ~= "" and suppressed then
                S.route3_hud_fakeb = txt
                -- right-column convention: glyph first, then the label (matches "B Dash" in vanilla)
                local gc, lc = lit_pair("B,Circle", 0xFFE0574F, nil)  -- Xbox-B red glyph; word = shared idle grey
                fake_text("B", bx, by, gc)
                fake_text(txt, bx + gap, by, lc)
            end
        end
        -- ⭐ R3 has no native slot in this panel AT ALL, so there is nothing to dedupe against --
        -- it draws whenever the cluster does. Carry label falls through when blank (see config).
        if C.route3_hud_faker3 ~= false then
            local txt3 = ""
            if carrying then txt3 = tostring(C.route3_hud_r3_carry or "") end
            if txt3 == "" then
                txt3 = airborne and tostring(C.route3_hud_r3_flight or "")
                    or tostring(C.route3_hud_r3_ground or "")
            end
            if txt3 ~= "" then
                S.route3_hud_faker3 = txt3
                local x3 = w - (tonumber(C.route3_hud_faker3_dx) or 245.0) * sc
                local y3 = by - (tonumber(C.route3_hud_faker3_dy) or 27.0) * sc
                local gc3, lc3 = lit_pair("R3", 0xFFC9C9C9, nil)  -- stick-press grey glyph
                fake_text("R3", x3 - 6.0 * sc, y3, gc3)
                fake_text(txt3, x3 + gap + 10.0 * sc, y3, lc3)  -- R3 glyph is wider than one letter
            end
        end
        -- ⭐ L3 line (2026-08-07, Aurora): same treatment as R3 -- ground-only "Dismount"
        -- (flight label blank by default, so it simply vanishes in the air)
        if C.route3_hud_fakel3 ~= false then
            local txtl = airborne and tostring(C.route3_hud_l3_flight or "")
                or tostring(C.route3_hud_l3_ground or "")
            if txtl ~= "" then
                local xl = w - (tonumber(C.route3_hud_fakel3_dx) or 245.0) * sc
                local yl = by - (tonumber(C.route3_hud_fakel3_dy) or 54.0) * sc
                local gcl, lcl = lit_pair("L3", 0xFFC9C9C9, nil)
                fake_text("L3", xl - 6.0 * sc, yl, gcl)
                fake_text(txtl, xl + gap + 10.0 * sc, yl, lcl)
            end
        end
        -- ⭐ LT + RB: draw our own bright GLYPH + WORD pair (Aurora: the game's dimmed glyphs
        -- "aren't actually lit up so you can't really see them"). Shoulder rows use the smaller
        -- shoulder font size. Sliders position the GLYPH; the word hangs off the correct column
        -- side (left column = word then glyph, right column = glyph then word), width-estimated
        -- at ~0.52px/char -- close enough for placement, and the sliders absorb the rest.
        local spx = math.max(10.0, tonumber(C.route3_hud_fake_px_shoulder) or 18.0)
        local function fake_word(btn, glyph, side, enk, dxk, dyk, defdx, defdy, pad_names)
            if C[enk] == false then return nil end
            local txtw = tostring(labels[btn] or "")
            local rec2 = S.route3_hud_diag and S.route3_hud_diag[btn]
            local hiddenw = rec2 and tostring(rec2.playstate or ""):find("DISABLE", 1, true) ~= nil
            if txtw == "" or not hiddenw then return nil end
            local xw = w - (tonumber(C[dxk]) or defdx) * sc
            local yw = h - (tonumber(C[dyk]) or defdy) * sc
            local gcw, lcw = lit_pair(pad_names, 0xFFDADADA, nil)
            fake_text(glyph, xw, yw, gcw, spx)
            if side == "left" then
                fake_text(txtw, xw - (#txtw * spx * 0.52 + 8.0) * sc, yw, lcw, spx)
            else
                fake_text(txtw, xw + (#glyph * spx * 0.62 + 8.0) * sc, yw, lcw, spx)
            end
            return txtw
        end
        S.route3_hud_fakelt_on = fake_word("L2", "LT", "left",
            "route3_hud_fakelt", "route3_hud_fakelt_dx", "route3_hud_fakelt_dy", 650.0, 158.0, "L2")
        S.route3_hud_fakerb_on = fake_word("R1", "RB", "right",
            "route3_hud_fakerb", "route3_hud_fakerb_dx", "route3_hud_fakerb_dy", 385.0, 125.0, "R1")
    end
    -- one dump a second while mounted -- enough to read, cheap enough not to cost frames
    -- (⚠ the per-frame-write trap already cost us a 3fps session; never dump every frame)
    if S.route3_hud_diag and os.clock() >= (tonumber(S.route3_hud_diag_at) or 0.0) then
        S.route3_hud_diag_at = os.clock() + 1.0
        pcall(function()
            json.dump_file(MOD .. "_huddiag.json", {
                when = os.date("%H:%M:%S"),
                status = S.route3_ride_hud_status,
                set = tostring(S.route3_ride_hud_set or "?"),
                harvested_good_playstate = tostring(S.route3_hud_goodstate or "(never ran)"),
                buttons = S.route3_hud_diag,
            })
        end)
    end
end

function griffin_seat_diag_capture()
    local out = { t = os.clock() }
    local _, go = reacquire_griffin()
    if not go then out.err = "no griffin"; return out end
    local function v3(p)
        if not p then return nil end
        return { x = tonumber(p.x) or 0.0, y = tonumber(p.y) or 0.0, z = tonumber(p.z) or 0.0 }
    end
    out.uni = v3(transform_pos(go))
    out.ren = v3(transform_render_pos(go))
    pcall(function()
        local tf = transform_of(go)
        local rj = tf and managed_call(tf, "getJointByName", "root")
        local sj = tf and managed_call(tf, "getJointByName", tostring(C.route3_seat_joint or "Spine_2"))
        out.root = v3(rj and managed_call(rj, "get_Position"))
        out.spine = v3(sj and managed_call(sj, "get_Position"))
    end)
    pcall(function() out.rider = v3(griffin_seat_joint_universal(go, transform_pos(go))) end)
    pcall(function() out.pawnseat = v3(griffin_pawn_seat_point(go)) end)
    pcall(function() out.fsm = tostring(read_griffin_fsm_node() or "?") end)
    pcall(function()
        local m = get_griffin_motion_component()
        local ly = m and m:call("getLayer", 0)
        if ly then
            out.bank = tonumber(ly:call("get_MotionBankID"))
            out.clip = tonumber(ly:call("get_MotionID"))
            out.frame = tonumber(ly:call("get_Frame"))
        end
    end)
    return out
end

function griffin_seat_diag_line(name, a, b)
    -- report the DELTA between two captures; absolute values across mixed spaces mean nothing
    local pa, pb = a and a[name], b and b[name]
    if not (pa and pb) then return name .. ": (n/a)" end
    local dx, dy, dz = pb.x - pa.x, pb.y - pa.y, pb.z - pa.z
    local d = math.sqrt(dx * dx + dy * dy + dz * dz)
    return string.format("%-9s moved %5.2fm  (%+.2f %+.2f %+.2f)", name, d, dx, dy, dz)
end

-- ⭐⭐ THE MISSING HALF OF NICK'S CAMERA TRICK (2026-08-04). Puppeteer's camera visibly tracks his
-- node moves, and it is NOT because his write site is better -- it is because he SWITCHES the main
-- camera controller to another control type first (PuppetSetup.lua:144, switchCamera(2,nil,nil,nil))
-- so the game's follow-camera stops re-posing the transform every frame. We copied his write and
-- skipped his switch, which is why five rounds of tuning (space, target, ease, snap, floor) all
-- "worked" in the tape yet never changed the picture: the follow controller kept winning the frame.
function griffin_loopcam_cam_switch(ct)
    local ok = false
    S.route3_loopcam_switching = true    -- so our own call is not recorded as "the game's choice"
    pcall(function()
        local cm = sdk.get_managed_singleton("app.CameraManager")
        local ctrl = cm and cm._MainCameraControllers and cm._MainCameraControllers[0]
        if ctrl then
            -- Nick's exact 4-arg form first; the July probe's 3-arg form as fallback
            local ok4 = pcall(function() ctrl:switchCamera(ct, nil, nil, nil) end)
            if not ok4 then
                ctrl:call("switchCamera(app.CameraDefine.ControlType, app.CameraSwitchInterpParam, app.PostEffectSetting)", ct, nil, nil)
            end
            ok = true
        end
    end)
    S.route3_loopcam_switching = false
    S.route3_loopcam_cam_ct = ok and ct or nil
    return ok
end

do
    -- passively record the control type the GAME last switched to, so the restore puts back what
    -- was actually running instead of assuming 0 (BetterOxcartsRedux hooks this same 3-arg overload
    -- to catch the oxcart's switch, so the game demonstrably routes through it)
    pcall(function()
        local td = sdk.find_type_definition("app.MainCameraController")
        local m = td and td:get_method("switchCamera(app.CameraDefine.ControlType, app.CameraSwitchInterpParam, app.PostEffectSetting)")
        if m then
            sdk.hook(m, function(args)
                if S.route3_loopcam_switching ~= true then
                    pcall(function() S.route3_loopcam_game_ct = tonumber(sdk.to_int64(args[3])) end)
                end
                -- ⛔ NO DISK WRITES IN THIS HOOK (2026-08-05, hygiene). A json-per-call dump lived
                -- here briefly; removed on principle (the per-frame-write trap). Verified NOT the
                -- 1fps cause: the dump file never appeared on disk, i.e. this hook has never fired
                -- once -- the game does not route through this 3-arg overload at all (which is
                -- also why cam_type_restore always reads "none recorded"; restore-to-0 is doing
                -- the work and evidently lands).
            end, function(retval) return retval end)
        end
    end)
end

function griffin_loopcam_active()
    if C.route3_loopcam ~= true then return false end
    if S.mounted ~= true then return false end
    -- ⛔ NEVER hold the camera outside normal gameplay (Aurora: "pause menu breaks with this camera
    -- stuff"). The action-prompt panel is hidden in menus/pause, which makes it a free and
    -- reliable gameplay signal. ⚠ Known trap in this codebase: the frame loop KEEPS RUNNING while
    -- paused, so anything that writes per-frame must opt OUT of the pause, not assume it stops.
    if S.route3_hud_panel_drawn == false then return false end
    local locked = false
    pcall(function() locked = griffin_node_lockout_active() == true end)
    -- v10: a clip-only rise has no lockout -- the press-armed window keeps the shot alive
    if not locked and os.clock() < (tonumber(S.route3_loopcam_clip_until) or 0.0) then
        locked = true
    end
    if not locked then
        local w = math.max(tonumber(S.route3_simple_rise_until) or 0.0,
            tonumber(S.route3_simple_dive_until) or 0.0)
        -- ⭐ HAND-BACK TAIL (2026-08-12, tape-proven): at lock release the native camera's FIRST
        -- authority frame snaps to ~5.7m (cling mode) before relaxing to the normal 8m -- the
        -- "weird close-up". Keep filming ~1.5s past the window so the native cam resumes only
        -- after its flight mode has settled. Per-species (retire_at_window species only).
        if C.route3_rise_retire_at_window == true and S.route3_loopcam_t0 ~= nil
            and w > 0.0 and os.clock() < w + 2.5 then
            return true
        end
        -- ⭐ hold-refire grace (2026-08-11): a one-frame lock gap between a travel node bailing
        -- and the rise-hold re-firing it cleared t0 here, so the re-fire started a SECOND shot
        -- (Aurora: "the camera thing twice"). Keep the shot timer alive while the rise window
        -- is still open; clear it only once the window has genuinely closed.
        if w <= os.clock() then S.route3_loopcam_t0 = nil end
        return false
    end
    -- ⭐ film ONLY the loop (lockout source "rise"); the gale/thunder attacks share the lockout
    -- machinery but must NOT hijack the camera (Aurora, 2026-08-05)
    if tostring(S.route3_node_lock_src or "rise") ~= "rise" then return false end
    -- ⭐ THE CAMERA GETS ITS OWN, SHORTER CAP (Aurora: "it took a long time to return to normal").
    -- The lockout can legitimately run to its 8s ceiling -- that is the right length for PROTECTING
    -- her body, and far too long to hold someone's camera hostage. A loop is over in a couple of
    -- seconds; film that and give control straight back. Two independent windows on purpose.
    local now = os.clock()
    if S.route3_loopcam_t0 == nil then S.route3_loopcam_t0 = now end
    local cap = math.max(0.5, tonumber(C.route3_loopcam_max) or 3.5)
    -- ⭐ 2026-08-11 (drake): while a held travel node keeps her FSM genuinely in Fly.*, the
    -- NATIVE cling-flight camera owns the view (Aurora identified it: "the camera they use
    -- when you're holding onto a griffin while it's flying" -- an ugly close-up). Species
    -- that retire at window end hold the cinematic across the WHOLE window instead, so the
    -- native close-up never shows; the retire lands ~0.6s after the window and the standard
    -- camera returns with the Wait state.
    if C.route3_rise_retire_at_window == true then
        local w = math.max(tonumber(S.route3_simple_rise_until) or 0.0,
            tonumber(S.route3_simple_dive_until) or 0.0)
        -- +1.6 covers the retire pump too, so the native cam only ever resumes in its FAR
        -- mode (measured: ~5.6m while FSM in Fly.*, 8m+ once parked back in Wait)
        if w > now then cap = math.max(cap, (w - S.route3_loopcam_t0) + 1.6) end
    end
    -- v10 nodeless: the press-armed clip shot sets its own length
    local cu = tonumber(S.route3_loopcam_clip_until) or 0.0
    if cu > now then cap = math.max(cap, cu - S.route3_loopcam_t0) end
    if now - S.route3_loopcam_t0 > cap then
        S.route3_loopcam_status = "released (shot over, lock still held)"
        return false
    end
    return true
end

-- ⭐⭐⭐ THE CLOSE-UP VETO (2026-08-12, THE camera fix -- snapshot-diff proven). The ride's
-- normal view is app.ClimbingCameraController (ControlType 6). At node fire the native climb
-- state transiently reads false (the documented node-window flicker), and the game calls
-- switchCamera(1 = Usually ...) = the ON-FOOT camera glued to a rider on a huge drake = "the
-- weird close-up". Veto exactly that: Usually-downgrades while MOUNTED during a node window.
-- Menus/cutscenes/talk (types 12/15/...) and genuine dismounts outside windows pass through.
-- Hook installed ONCE via versioned guard; logic dispatched through _G so a reload updates
-- behaviour (the hook-pins-old-closures law).
_G.iris_camswitch_veto_fn = function(args)
    local ok, ret = pcall(function()
        local ct = tonumber(sdk.to_int64(args[3])) or -1
        S.route3_camswitch_last = string.format("%s ct=%d", os.date("%H:%M:%S"), ct)
        -- ⛔⛔ v21 THE STUCK CAMERA, NAMED: THIS VETO WAS EATING OUR OWN HAND-BACK. The cinematic
        -- returns the view by calling griffin_loopcam_cam_switch(game_ct) -- the FOUR-arg overload,
        -- i.e. straight into this hook -- and when the recorded type is 1 (Usually) we vetoed our
        -- own restore, so the shot never gave the camera back. The `node_lock_at ~= nil` arm has no
        -- time limit, which is why it stranded rather than recovered. Our own switches are now
        -- always allowed (the flag the passive recorder already sets), and the veto stands down
        -- entirely under the air seat, where Usually IS the ride camera rather than the close-up.
        -- The cinematic itself is untouched -- Aurora wants the shot, she wants it to hand back.
        if ct == 1 and S.mounted == true and S.route3_air_seat_on ~= true
            and S.route3_loopcam_switching ~= true then
            local w = math.max(tonumber(S.route3_simple_rise_until) or 0.0,
                tonumber(S.route3_simple_dive_until) or 0.0)
            if S.route3_node_lock_at ~= nil or os.clock() < w + 1.5 then
                S.route3_camswitch_veto_count = (tonumber(S.route3_camswitch_veto_count) or 0) + 1
                S.route3_camswitch_last = S.route3_camswitch_last .. " VETOED"
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end
        return nil
    end)
    if ok then return ret end
end
if _G.IRIS_CAMSWITCH_VETO_HOOKED == nil then
    _G.IRIS_CAMSWITCH_VETO_HOOKED = true
    pcall(function()
        local td = sdk.find_type_definition("app.MainCameraController")
        local m = td and td:get_method(
            "switchCamera(app.CameraDefine.ControlType, app.CameraSwitchInterpParam, app.PostEffectSetting, app.CameraDefine.ToPlayerCameraOption)")
        if m then
            sdk.hook(m, function(args)
