    scout_caw = function(sound_id)
        -- X = DIVE-STEAL (Aurora's pivot; the caw/taunt is dead -- enemies never validate the
        -- puppeted crow as a target, so distract was engine-walled). Press: a screech (near-range
        -- audible), then the drone tick AUTO-PILOTS the bird onto the nearest enemy below, strikes
        -- 1 HP through the proven swoop pipeline, flags the steal for IrisTaming's pouch roll, and
        -- leaves the MARK on the victim. The search runs around the BIRD (griffin_find_enemy
        -- measures from the player -- the wrong circle for a scout).
        local gch, go = reacquire_griffin()
        if not (gch and go) then return 0 end
        if S.scout_dive then return 1 end   -- already mid-dive: let it finish
        local sid = math.floor(tonumber(sound_id) or 0)
        if sid > 0 then
            pcall(function()
                local wc = route3_wwise_container()
                if wc then wc:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)", sid, go, go) end
            end)
        end
        local bpos = transform_pos(go)
        if not bpos then return 0 end
        local radius = tonumber(C.scout_caw_range) or 25.0
        local best, best_d = nil, radius * radius
        pcall(function()
            local em = singleton("app.EnemyManager")
            if not em then return end
            for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
                local list = nil
                pcall(function() list = em:call(getter) end)
                local n0 = 0
                pcall(function() n0 = list and list:call("get_Count") or 0 end)
                if (tonumber(n0) or 0) > 0 then
                    for i = 0, n0 - 1 do
                        pcall(function()
                            local ch2 = list:call("get_Item", i)
                            if ch2 and not griffin_is_self(ch2) and not is_player_or_party(ch2) and not is_dead(ch2) then
                                local go2 = char_go(ch2)
                                local p2 = go2 and transform_pos(go2)
                                local d = p2 and distance_sq(p2, bpos)
                                if d and d < best_d then best, best_d = ch2, d end
                            end
                        end)
                    end
                    return
                end
            end
        end)
        if best then
            local pn = "?"
            pcall(function() pn = go_name(char_go(best)) end)
            S.scout_dive = { prey = best, t0 = os.clock(), phase = "dive" }
            pcall(function() log.info(string.format("[GriffinScout] DIVE on %s (%.1fm from the bird)", tostring(pn), math.sqrt(best_d))) end)
            return 1
        end
        pcall(function() log.info(string.format("[GriffinScout] dive: no enemy within %.0fm of the bird", radius)) end)
        return 0
    end,
    scout_pickpocket = function()
        -- X on the SURFACE (the rat -- the thief, not the mugger): dart to the mark's feet,
        -- rear up, rummage, LIFT something -- no damage, no aggro. 1 = darting, 0 = no mark.
        local gch, go = reacquire_griffin()
        if not (gch and go) then return 0 end
        if S.scout_pick then return 1 end
        local bpos = transform_pos(go)
        if not bpos then return 0 end
        local radius = tonumber(C.scout_caw_range) or 25.0
        local best, best_d = nil, radius * radius
        pcall(function()
            local em = singleton("app.EnemyManager")
            if not em then return end
            for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
                local list = nil
                pcall(function() list = em:call(getter) end)
                local n0 = 0
                pcall(function() n0 = list and list:call("get_Count") or 0 end)
                if (tonumber(n0) or 0) > 0 then
                    for i = 0, n0 - 1 do
                        pcall(function()
                            local ch2 = list:call("get_Item", i)
                            if ch2 and not griffin_is_self(ch2) and not is_player_or_party(ch2) and not is_dead(ch2) then
                                local go2 = char_go(ch2)
                                local p2 = go2 and transform_pos(go2)
                                local d = p2 and distance_sq(p2, bpos)
                                if d and d < best_d then best, best_d = ch2, d end
                            end
                        end)
                    end
                    return
                end
            end
        end)
        if best then
            S.scout_pick = { prey = best, t0 = os.clock(), phase = "dart" }
            pcall(function() log.info(string.format("[GriffinScout] PICKPOCKET darts at %s (%.1fm)", tostring(go_name(char_go(best))), math.sqrt(best_d))) end)
            return 1
        end
        pcall(function() log.info(string.format("[GriffinScout] pickpocket: no mark within %.0fm", radius)) end)
        return 0
    end,
    scout_dive_result = function()
        -- IrisTaming polls this each frame: true exactly once per landed strike (it rolls the
        -- steal into the pouch and writes the prompt)
        if S.scout_dive_hit then S.scout_dive_hit = nil; return true end
        return false
    end,
    scout_ambush = function()
        -- X while BURROWED (the rabbit -- Aurora's option B): auto-pilot the dust trail UNDER
        -- the nearest prey and ERUPT beneath it. Returns 1 = stalking, 0 = no prey in range,
        -- -1 = not burrowed (the ambush needs the earth).
        local gch, go = reacquire_griffin()
        if not (gch and go) then return 0 end
        if S.scout_ambush then return 1 end
        if not S.scout_burrowed then return -1 end
        local bpos = transform_pos(go)
        if not bpos then return 0 end
        local radius = tonumber(C.scout_caw_range) or 25.0
        local best, best_d = nil, radius * radius
        -- sweep 1: registered enemies (goblins, saurians...)
        pcall(function()
            local em = singleton("app.EnemyManager")
            if not em then return end
            for _, getter in ipairs({ "get_EnemyList", "getAllEnemies", "get_ActiveEnemyList", "get_EnemyCharacterList" }) do
                local list = nil
                pcall(function() list = em:call(getter) end)
                local n0 = 0
                pcall(function() n0 = list and list:call("get_Count") or 0 end)
                if (tonumber(n0) or 0) > 0 then
                    for i = 0, n0 - 1 do
                        pcall(function()
                            local ch2 = list:call("get_Item", i)
                            if ch2 and not griffin_is_self(ch2) and not is_player_or_party(ch2) and not is_dead(ch2) then
                                local go2 = char_go(ch2)
                                local p2 = go2 and transform_pos(go2)
                                local d = p2 and distance_sq(p2, bpos)
                                if d and d < best_d then best, best_d = ch2, d end
                            end
                        end)
                    end
                    return
                end
            end
        end)
        -- sweep 2: WILDLIFE are invisible to EnemyManager (the throw-R&D law) -- scene sweep
        -- of app.Character, ch2* bodies only (enemies + critters; never NPCs/party)
        pcall(function()
            local sm0 = sdk.get_native_singleton("via.SceneManager")
            local smt0 = sdk.find_type_definition("via.SceneManager")
            local scene0 = sm0 and sdk.call_native_func(sm0, smt0, "get_CurrentScene")
            local comps0 = scene0 and scene0:call("findComponents(System.Type)", sdk.typeof("app.Character"))
            local n0 = 0
            pcall(function() n0 = comps0:call("get_Length") or 0 end)
            if n0 == 0 then pcall(function() n0 = comps0:get_size() or 0 end) end
            local IT0 = _G.IrisTaming
            for i = 0, (tonumber(n0) or 0) - 1 do
                pcall(function()
                    local ch2 = comps0:call("get_Item", i) or comps0[i]
                    local go2 = ch2 and ch2:call("get_GameObject")
                    if not go2 then return end
                    if not tostring(go_name(go2) or ""):match("^ch2") then return end
                    if griffin_is_self(ch2) or is_player_or_party(ch2) or is_dead(ch2) then return end
                    -- never ambush our own tames
                    local pet0 = false
                    pcall(function() if IT0 and IT0.has_pet then pet0 = IT0.has_pet(ch2:get_address()) == true end end)
                    if pet0 then return end
                    local p2 = transform_pos(go2)
                    local d = p2 and distance_sq(p2, bpos)
                    if d and d < best_d then best, best_d = ch2, d end
                end)
            end
        end)
        if best then
            S.scout_ambush = { prey = best, t0 = os.clock() }
            pcall(function() log.info(string.format("[GriffinScout] AMBUSH stalks %s (%.1fm)", tostring(go_name(char_go(best))), math.sqrt(best_d))) end)
            return 1
        end
        pcall(function() log.info(string.format("[GriffinScout] ambush: no prey within %.0fm of the rabbit", radius)) end)
        return 0
    end,
    scout_status = function()
        return { drive = S.scout_drive ~= nil, flyback = S.scout_flyback ~= nil, suppressed = S.scout_mode == true,
            stamina = tonumber(S.scout_sprint_sta) or 1.0, sprint_lock = S.scout_sprint_lock == true, sprinting = S.scout_sprinting == true,
            burrowed = S.scout_burrowed == true,   -- the taming side draws the MOUND TRAIL off this
            hopping = (S.scout_hop ~= nil) or (S.scout_dismount ~= nil) }   -- ...and plays the HOP sound off this
    end,
    rename_companion = function(id2, nm2)
        local st = S.route3_stable
        if not (st and st.companions) then return false end
        for _, r in ipairs(st.companions) do
            if r.id == id2 then
                r.name = tostring(nm2)
                if st.active == id2 then C.route3_griffin_name = r.name end
                pcall(function() griffin_tamed_save() end)
                return true
            end
        end
        return false
    end,
}

function route3_grab_frozen_drop(st, carried, cgo, dmg, fall_h)
    -- RAGDOLL DROP (Fable step 5, 2026-07-11): the old frozen pose looked stiff on release. Swap
    -- to the PROVEN blowback recipe -- force-enable ragdoll + the native throw's recorded
    -- dmg_throw_action state so the body goes LIMP -- while the transform integrator drives the
    -- fall straight down. The integrator owns the ROOT (so the ragdoll can't eject it near her
    -- collision; it only limps the limbs). Clear the carry-anim puppet + restore fall-death first.
    st.native_launched = true   -- THIS is the launch: pin_late bails, no more transform writes
    pcall(function() set_motion_fsm_puppet(cgo, false) end)
    pcall(function() carried:call("set_IsDamageFall(System.Boolean)", true) end)
    st.carry_anim_active = false
    if C.route3_grab_ragdoll_drop ~= false then
        pcall(function() set_think_stop(carried, false) end)   -- limp, not rigid
        pcall(function() carried:call("set_IsForceEnableRagdoll", true) end)
        if st.corpse == true or is_dead(carried) then
            -- Corpse carry explicitly parked these components. Re-enable them
            -- now that pin_late has bailed, before selecting the fall state.
            pcall(function()
                for _, cn in ipairs({ "via.dynamics.Ragdoll", "app.CharacterRagdoll" }) do
                    local c = get_component(cgo, cn)
                    if c then c:call("set_Enabled", true) end
                end
            end)
            pcall(function() carried:call("EnableRagdoll(System.Boolean)", true) end)
            pcall(function() carried:call("startRagdoll") end)
        end
        pcall(function()
            local rt = sdk.find_type_definition("via.dynamics.Ragdoll"):get_runtime_type()
            local rd = cgo:call("getComponent(System.Type)", rt)
            if rd then rd:call("set_RagdollStateName(System.String)", "dmg_throw_action") end
        end)
        st.throw_state_at = os.clock() + 0.4   -- dmg_throw_action -> dmg_throw_pause (the throw tick fires it)
        st.ragdoll_drop = true
    else
        pcall(function() set_think_stop(carried, true) end)
        pcall(function() local m = carried:call("get_Motion"); if m then m:call("set_PlaySpeed", 0.0) end end)
        pcall(function() carried:call("EnableRagdoll(System.Boolean)", false) end)
    end
    -- ⚠ CONTROLLER STAYS OFF MID-AIR: waking the physics capsule while the body is still clipped
    -- into the griffin's talons = DEPENETRATION ejection (the "random direction at ridiculous
    -- speed" fling -- the last suspect standing). The fall is integrated by transform (the dive
    -- bomb's proven driver); the controller wakes at the FLOOR, where nothing overlaps.
    pcall(function() set_character_controller_enabled(carried, false) end)
    pcall(function() stop_navigation(carried, false) end)
    st.drop_integrate = true
    st.drop_vy = 0.0
    st.drop_alive = st.corpse ~= true and not is_dead(carried) -- never revive/immunise an existing corpse
    st.drop_dmg = dmg       -- landing applies the height damage
    st.phase = "throw"
    st.throw_t0 = os.clock(); st.last = os.clock()
    S.route3_grab_ragdiag = string.format("frozen-drop h=%s dmg=%.0f", tostring(fall_h and string.format("%.1f", fall_h) or "?"), tonumber(dmg) or 0)
    S.route3_grab_status = "dropping " .. tostring(S.route3_grab_ragdiag)
    route3_grab_nt_trace("frozen drop engaged")   -- (dump happens at landing -- one tape, whole story)
end

function route3_grab_nt_dump_api()
    -- one-shot reflection dump of the catch/caught APIs (static type info, no live instance
    -- needed) -> data/..._catchctrl_methods.json. The natural-release call lives in here.
    if S.nt_api_dumped then return end
    S.nt_api_dumped = true
    local out = {}
    for _, tn in ipairs({ "app.CatchController", "app.CaughtController" }) do
        local rows = {}
        pcall(function()
            local td = sdk.find_type_definition(tn)
            for _, m in ipairs(td:get_methods() or {}) do
                local nm = tostring(m:get_name() or "")
                local ps = {}
                pcall(function() for _, pt in ipairs(m:get_param_types() or {}) do ps[#ps + 1] = tostring(pt:get_full_name() or "?") end end)
                rows[#rows + 1] = nm .. "(" .. table.concat(ps, ", ") .. ")"
            end
        end)
        table.sort(rows)
        out[tn] = rows
    end
    pcall(function() json.dump_file(MOD .. "_catchctrl_methods.json", out) end)
end


function route3_grab_nt_state(carried, cgo)
    -- live caught + ragdoll-state readout (the same fields the observer records)
    local caught = nil
    pcall(function()
        local cc = carried:call("get_CaughtController")
        if cc then caught = cc:call("get_IsCaught"); if caught == nil then caught = cc:call("get_IsActive") end end
    end)
    local rstate = nil
    pcall(function()
        local rt = sdk.find_type_definition("via.dynamics.Ragdoll"):get_runtime_type()
        local rd = cgo:call("getComponent(System.Type)", rt)
        if rd then rstate = tostring(rd:call("get_RagdollStateName")) end
    end)
    return caught, rstate
end

function route3_grab_throw(reason)
    -- THROW the prey (Aurora, RiftSpeak-Arisen style): ragdoll + hurl forward+up in an arc,
    -- then impact damage on landing = the "flung, tumbles, fell over" effect.
    local st = S.route3_grab
    local carried = st and st.carried
    if not (st and carried) then route3_grab_end(reason or "thrown"); return true end
    local gch, go = reacquire_griffin()
    -- use the stable FLIGHT heading, not the raw transform yaw: the flap/flight animation wobbles
    -- the transform's rotation each frame, so reading it at launch threw her a different way each time.
    local yaw = S.heading_yaw or (go and yaw_from_transform(go)) or 0.0
    local cgo = char_go(carried)

    -- ===== HEIGHT-HONEST DROP (default): real physics via the one ragdoll that always works =====
    -- Root cause of every failure: any path that needs the goblin's live systems mid-air trips its
    -- own FALL-DEATH check (the old "dies if held too long" killer) or the gated ragdoll. So use
    -- what is PROVEN: the DEATH ragdoll always engages (the eat flops bodies with it; corpses
    -- tumble with real physics). Compute the height damage AT RELEASE:
    --   LETHAL height  -> scream, the fall's own damage kills it at release, death ragdoll takes
    --                     over = a real tumbling physics fall. (From that height it died either way.)
    --   SURVIVABLE     -> release FROZEN (no live brain = no fall-death), gravity drops it, kept
    --                     alive through the fall, lands, takes the height damage, gets back up.
    if C.route3_grab_native_throw ~= false and cgo then
        -- native_launched moved into route3_grab_frozen_drop (the real launch); the nt path must
        -- NOT set it here, or pin_late's ntcatch-hold (during the catch window) becomes dead code.
        st.phase = "throw"
        st.throw_t0 = os.clock(); st.last = os.clock()
        local p0 = transform_pos(cgo)
        st.peak_y = p0 and tonumber(p0.y) or nil
        local gy = route3_ground_y_robust(cgo, st.peak_y)
        st.drop_gy = gy
        local fall_h = (st.peak_y and gy) and math.max(0.0, st.peak_y - gy) or nil
        -- height damage, computed up front (same curve the landing uses): decides the path
        local g = tonumber(C.route3_fall_damage_gravity) or 24.0
        local impact_vy = fall_h and math.sqrt(2.0 * g * math.max(0.0, fall_h)) or nil
        local dmg = route3_fall_damage_for(carried, impact_vy)
        local hp = nil
        pcall(function() local hc = griffin_target_hit_controller(carried); if hc then hp = griffin_hp_from_component(hc) end end)
        st.land_hp0 = hp
        route3_grab_detach_from_talon(carried)                    -- safety no-op unless parented
        if C.route3_grab_nt_experiment ~= true then
            -- PRIMARY: the frozen drop. The fair-trial tape (2026-07-07 12:08) is definitive:
            -- startCatch ok=true then 64 samples of caught=false/DisableStates with ALL blockers
            -- down -- a monster catcher cannot drive CatchController. Predation is the next path.
            route3_grab_frozen_drop(st, carried, cgo, dmg, fall_h)
            local dclip = math.floor(tonumber(C.route3_grab_drop_clip) or -1)
            if dclip >= 0 then
                pcall(function() play_griffin_motion(dclip, math.floor(tonumber(C.route3_grab_clip_bank) or 20), false) end)
                S.audition_until_clock = os.clock() + 0.6
            end
            status(tostring(C.route3_griffin_name or "Griffin") .. " drops its prey!")
            return true
        end
        -- ===== NATURAL THROW v2 -- FAIR TRIAL (kept behind route3_grab_nt_experiment for research;
        -- ===== the 12:08 tape says the catch never establishes on a monster catcher): make the =====
        -- ===== throw by entering a REAL caught state, then releasing it naturally.        =====
        -- The recording defines "established": caught=true + ragdoll state "pin_00_carry". We
        -- verify LIVE against that before releasing; any stage failing degrades to the stable
        -- frozen drop (never a lob). Observer can record our throw to diff vs the natural one.
        route3_grab_nt_dump_api()   -- one-shot: the release API -> _catchctrl_methods.json
        S.nt_allow_actions_until = os.clock() + 2.0   -- blockers stand down for the catch window
        S.nt_trace = {}
        route3_grab_nt_trace("NT start: blockers down, restoring body")
        -- restore the body to FULL native first (the game catches a normal goblin, so hand it
        -- one) -- except GroundFixer, which mid-air snaps to terrain; the caught state will own
        -- position, so GF returns only once the catch is verified.
        -- HYBRID: clear the carry-anim FSM puppet (a puppeted victim can't play the native
        -- CaughtCancelAction) + normalize to app.Character (startCatch needs it; a monster ref CTDs).
        pcall(function() set_motion_fsm_puppet(cgo, false) end)
        st.carry_anim_active = false
        carried = griffin_as_character(carried) or carried
        st.carried = carried
        route3_grab_set_immunity(carried, false)
        pcall(function() set_think_stop(carried, false) end)
        pcall(function() local m = carried:call("get_Motion"); if m then m:call("set_PlaySpeed", 1.0) end end)
        pcall(function() local h = carried:call("get_Human"); if h then local f = h.Fsm or h:get_field("Fsm"); if f then f:call("set_Enabled", true) end end end)
        pcall(function() carried:call("set_IsDamageFall(System.Boolean)", true) end)
        st.nt_dmg = dmg; st.nt_fall_h = fall_h
        if is_dead(carried) or not griffin_prey_has_caught_machinery(carried) then
            route3_grab_nt_trace("-> frozen drop (dead / no caught machinery)")
            route3_grab_frozen_drop(st, carried, cgo, dmg, fall_h)
        else
            -- proven predation establish: the captured Setting + Ch253 directives, same-frame check.
            local cc = nil
            pcall(function() cc = gch and gch:call("get_CatchController") end)
            local setting = cc and griffin_predation_release_setting_for(carried)
            pcall(function() griffin_predation_clear_stale_transaction(gch, carried) end)
            pcall(function()
                local c253 = get_component(go, "app.Ch253000")
                if c253 then
                    c253:call("set_PredationTarget(via.GameObject)", cgo)
                    c253:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 3)
                    c253:call("set_IsAirCatch(System.Boolean)", true)
                end
            end)
            local nt_ok, nt_ret = false, nil
            if cc and setting then
                for _, fn in ipairs({
                    function() nt_ret = cc:call("startCatch(app.Character, app.CatchController.Setting, app.CatchInterpolator)", carried, setting, nil) end,
                    function() nt_ret = cc:call("startCatch(app.Character, app.CatchController.Setting)", carried, setting) end,
                }) do if pcall(fn) then nt_ok = true; break end end
            end
            local cactive, caughtactive = false, false
            pcall(function() cactive = cc:call("get_IsActive") == true end)
            pcall(function() local cgt = carried:call("get_CaughtController"); caughtactive = cgt and cgt:call("get_IsActive") == true or false end)
            route3_grab_nt_trace(string.format("startCatch ok=%s ret=%s cActive=%s caughtActive=%s", tostring(nt_ok), tostring(nt_ret), tostring(cactive), tostring(caughtactive)))
            if nt_ok and cactive and caughtactive then
                -- established SAME FRAME (the proven catch is synchronous): flip physics native + release
                st.nt_established = true
                route3_grab_restore_ground_components()
                pcall(function() set_character_controller_enabled(carried, true) end)
                pcall(function() carried:call("EnableRagdoll(System.Boolean)", true) end)
                st.phase = "ntrelease"
                st.nt_rel_at = os.clock() + math.max(0.1, tonumber(C.route3_grab_nt_hold_secs) or 0.2)
                st.nt_rel_try = 0
                S.route3_grab_ragdiag = "nt: caught, releasing..."
            elseif nt_ok then
                st.phase = "ntcatch"   -- backstop poll (rare: async establish)
                st.nt_t0 = os.clock()
                S.route3_grab_ragdiag = "nt: catching..."
            else
                route3_grab_nt_trace("-> frozen drop (startCatch failed)")
                route3_grab_frozen_drop(st, carried, cgo, dmg, fall_h)
            end
        end
        local clip = math.floor(tonumber(C.route3_grab_drop_clip) or -1)
        if clip >= 0 then
            pcall(function() play_griffin_motion(clip, math.floor(tonumber(C.route3_grab_clip_bank) or 20), false) end)
            S.audition_until_clock = os.clock() + 0.6
        end
        status(tostring(C.route3_griffin_name or "Griffin") .. " drops its prey!")
        S.route3_grab_status = "dropping " .. tostring(S.route3_grab_ragdiag)
        return true
    end

    -- ===== LEGACY hand-rolled arc (route3_grab_native_throw = false) =====
    local speed = math.max(0.0, tonumber(C.route3_grab_throw_speed) or 16.0)
    st.vx = math.sin(yaw) * speed
    st.vz = math.cos(yaw) * speed
    st.vy = tonumber(C.route3_grab_throw_up) or 6.0
    st.phase = "throw"
    st.throw_t0 = os.clock()
    st.last = os.clock()
    st.peak_y = nil   -- highest Y reached during the arc -> the effective fall height for damage
    route3_grab_detach_from_talon(carried)   -- unparent from the talon so the arc can drive it freely
    -- let-go clip on the griffin
    local clip = math.floor(tonumber(C.route3_grab_drop_clip) or -1)
    if clip >= 0 then
        pcall(function() play_griffin_motion(clip, math.floor(tonumber(C.route3_grab_clip_bank) or 20), false) end)
        S.audition_until_clock = os.clock() + 0.6
    end
    status(tostring(C.route3_griffin_name or "Griffin") .. " hurls its prey!")
    S.route3_grab_status = "throwing"
    return true
end

function route3_grab_finish_throw(carried, fall_h, impact_vy, native, land_hp0, drop_dmg)
    -- fall_h / impact_vy MUST be params: S.route3_grab is cleared on the first line, so they can't
    -- be read off state afterward.
    local corpse = carried and (((S.route3_grab and S.route3_grab.corpse == true) or is_dead(carried)) == true)
    route3_grab_nt_trace(string.format("LANDED fall_h=%s", tostring(fall_h)))
    route3_grab_nt_trace_dump("landed")
    S.route3_grab = nil
    S.audition_until_clock = 0.0
    route3_flap_after_action()   -- double-flap hygiene on EVERY exit (throws never ran it = the regression)
    if native == true and carried then
        -- NATIVE fall landed. FULLY un-freeze first: the carry left think/PlaySpeed/AI in mixed
        -- states -- without this it locks in a rigid pose ("statue") instead of settling as a
        -- normal body/corpse. Then settle fall damage (HP-delta guard: if the game's own fall
        -- damage already applied on landing, don't double it) and restore everything else.
        route3_grab_unfreeze(carried)   -- clears immunity + think/PlaySpeed/AI back on
        local dealt = 0.0
        if drop_dmg ~= nil then
            -- survivable drop: apply the height damage computed at release
            dealt = tonumber(drop_dmg) or 0.0
            if dealt > 0.0 then pcall(function() griffin_apply_attack_damage(carried, dealt) end) end
            S.route3_swoop_last_dmg = string.format("landed: fall dmg %.0f", dealt)
        else
            local hc = griffin_target_hit_controller(carried)
            local now_hp = hc and griffin_hp_from_component(hc)
            if land_hp0 and now_hp and now_hp < land_hp0 then
                dealt = land_hp0 - now_hp
                S.route3_swoop_last_dmg = string.format("NATIVE impact %s->%s", tostring(land_hp0), tostring(now_hp))
            elseif fall_h then
                pcall(function() dealt = route3_apply_fall_damage(carried, fall_h, impact_vy) or 0.0 end)
            end
        end
        if (tonumber(dealt) or 0.0) > 0.0 then pcall(function() carried:call("setDamageReaction") end) end
        route3_grab_restore_ground_components()
        if not corpse then
            pcall(function() set_character_controller_enabled(carried, true) end)
            pcall(function() stop_navigation(carried, false) end)
            local ai = get_component(char_go(carried), "app.AIDecisionMaker"); if ai then pcall(function() ai:call("set_Enabled", true) end) end
        end
        S.route3_grab_status = string.format("dropped(native) fall_h=%s dmg: %s",
            tostring(fall_h and string.format("%.1f", fall_h) or "?"), tostring(S.route3_swoop_last_dmg or dealt or "?"))
        return
    end
    if carried then
        route3_grab_set_immunity(carried, false)   -- EXPLICIT immunity clear FIRST: the carry made it un-killable, which rejected the impact damage
        route3_grab_unfreeze(carried)   -- undo the freeze/AI-disable so it dies/reacts
        route3_grab_restore_ground_components()   -- GroundFixer/CharacterController back on (landed)
        if not corpse then
            pcall(function() set_character_controller_enabled(carried, true) end)  -- live-body collision back on
            pcall(function() stop_navigation(carried, false) end)
        end
        -- GAME-ACCURATE fall damage FIRST, while the body is still NON-ragdolled (native
        -- onDamageFromFall works better before ragdoll); native onDamageFromFall(height), mimic fallback.
        local dealt = 0.0
        pcall(function() dealt = route3_apply_fall_damage(carried, fall_h, impact_vy) or 0.0 end)
        -- NOW ragdoll so it flops "fallen over" on impact (this is the tumble reaction)
        pcall(function() carried:call("EnableRagdoll(System.Boolean)", true) end)
        pcall(function() carried:call("startRagdoll") end)
        if (tonumber(dealt) or 0.0) > 0.0 then
            pcall(function() carried:call("setDamageReaction") end)   -- only react if it actually took damage (safe drop = no hurt)
        end
        S.route3_grab_status = string.format("thrown fall_h=%s dmg: %s",
            tostring(fall_h and string.format("%.1f", fall_h) or "?"), tostring(S.route3_swoop_last_dmg or dealt or "?"))
        return
    end
    S.route3_grab_status = "thrown"
end

function route3_grab_end(reason)
    local st = S.route3_grab
    griffin_predation_restore_meal_collision(st)
    if st and st.phase == "eat" then
        pcall(function() local _, ggo = reacquire_griffin(); if ggo then set_motion_fsm_puppet(ggo, false) end end)
        S.route3_post_landing_recover_at = os.clock()
    end
    S.route3_grab = nil
    if S.base_owner and S.base_owner.name == "eat" then S.base_owner = nil end
    S.audition_until_clock = 0.0
    route3_flap_after_action()   -- double-flap hygiene on EVERY exit
    S.route3_grab_status = "grab=" .. tostring(reason or "done")
end

function griffin_predation_carry_pose_watchdog()
    -- DISABLED 2026-07-12: native_carry_active returns FALSE for a carried OX (held via pin + Catch
    -- node, no active CaughtController), so this misfired during the ox carry and CLOSED the predation
    -- window every 0.25s -> that killed the wing-system stand-down (route3_apply_captured_wing_replay
    -- @4335) = the BROKEN FLAT WINGS. Off until the ox-carry break is properly diagnosed.
    if C.route3_catch_watchdog_enabled ~= true then return end
    if S.mounted ~= true then return end
    if S.route3_predation_eat or S.route3_predation_eat_pending or S.route3_grab then return end
    if griffin_predation_native_carry_active() then S.route3_catch_wd = nil; return end   -- legit carry: leave Catch alone
    local ch, go = reacquire_griffin()
    if not (ch and go) then return end
    local node = tostring(read_griffin_fsm_node() or "")
    if not (node:find("Catch") or node:find("Carry")) then S.route3_catch_wd = nil; return end   -- already clear
    local now = os.clock()
    if (now - (tonumber(S.route3_catch_wd_at) or 0.0)) < 0.25 then return end   -- throttle
    S.route3_catch_wd_at = now
    S.route3_catch_wd = (tonumber(S.route3_catch_wd) or 0) + 1
    -- UNPARK the native flight tick: close the predation window + force a re-assert next frame
    S.route3_predation_mode = nil
    S.route3_predation_wake_until = 0.0
    S.route3_predation_probe_until = 0.0
    S.route3_predation_native_until = 0.0
    S.route3_native_flight_node = nil
    S.route3_native_flight_last_check = 0.0
    if S.airborne ~= true then
        -- GROUNDED: engage FlightControl (makes the flight transition legal), hop Catch->Fly, then let
        -- the landing recover take Fly->calm + normalize.
        pcall(function() set_motion_fsm_puppet(go, false) end)
        pcall(function() set_think_stop(ch, false) end)
        pcall(function() set_griffin_motion_speed(1.0) end)
        local fc = get_component(go, "app.FlightControl")
        if fc then
            pcall(function() fc:call("onFlyState(app.FlightControl.FlyStateNo)", math.max(0, math.floor(tonumber(C.flight_control_fly_state) or 1))) end)
            pcall(function() fc:call("set_FlagGroundNotFound(System.Boolean)", false) end)
            local hit = route3_ground_hit_under(go, nil)
            local gy = tonumber(hit and hit.y)
            if gy then pcall(function() fc:call("setGroundHeight(System.Single, System.Single)", gy, 0.0) end) end
        end
        pcall(function() set_griffin_fsm_node_silent(tostring(C.route3_native_flight_fly_node or "Fly.Flying.FlyForward"), tonumber(C.route3_air_visual_native_fsm_tree) or 0) end)
        S.route3_post_landing_recover_at = now   -- next: Fly -> calm node + normalize
    end
    pcall(function() json.dump_file(MOD .. "_catch_wd.json", {
        time = os.date("%H:%M:%S"), attempts = S.route3_catch_wd, node_before = node,
        airborne = S.airborne == true, node_after = tostring(read_griffin_fsm_node() or "") }) end)
end

function griffin_predation_is_big_meal(prey)
    local nm = tostring(go_name(char_go(prey)) or ""):lower()
    for pat in tostring(C.route3_grab_big_prefixes or "ch299003"):gmatch("[^,%s]+") do
        if nm:find(pat:lower(), 1, true) then return true end
    end
    return false
end

function griffin_predation_joint_world_position(go, gpos, joint_name)
    local tf = transform_of(go)
    local joint = tf and managed_call(tf, "getJointByName", tostring(joint_name or ""))
    local jp = joint and (managed_call(joint, "get_Position")
        or managed_call(joint, "get_WorldPosition") or managed_call(joint, "get_UniversalPosition"))
    local grp = transform_render_pos(go)
    gpos = gpos or transform_pos(go)
    if not (jp and grp and gpos and sane_position(jp)) then return nil end
    -- Joint is render-space, root target is universal-space. Rebase the local
    -- render delta onto the universal root so world-tile offsets cancel.
    return {
        x = (tonumber(gpos.x) or 0.0) + (tonumber(jp.x) or 0.0) - (tonumber(grp.x) or 0.0),
        y = (tonumber(gpos.y) or 0.0) + (tonumber(jp.y) or 0.0) - (tonumber(grp.y) or 0.0),
        z = (tonumber(gpos.z) or 0.0) + (tonumber(jp.z) or 0.0) - (tonumber(grp.z) or 0.0),
    }
end

function griffin_predation_meal_talon_anchor(go, gpos, yaw, eat)
    if C.route3_predation_eat_big_talon_anchor == false or not (go and gpos and eat) then return nil end
    if eat.meal_anchor and eat.meal_anchor.mode == "talons" then return eat.meal_anchor end
    local left_name = tostring(C.route3_predation_eat_big_left_joint or "L_PropA")
    local right_name = tostring(C.route3_predation_eat_big_right_joint or "R_PropA")
    local lp = griffin_predation_joint_world_position(go, gpos, left_name)
    local rp = griffin_predation_joint_world_position(go, gpos, right_name)
    if not (lp and rp) then return nil end
    -- Sample once, before the start clip moves the feet. The ox must remain
    -- stationary while 5300 lifts and then plants both talons onto its body.
    local forward = tonumber(C.route3_predation_eat_big_talon_forward) or 0.0
    local side = tonumber(C.route3_predation_eat_big_talon_side) or 0.0
    local anchor = {
        x = (lp.x + rp.x) * 0.5 + math.sin(yaw) * forward + math.cos(yaw) * side,
        z = (lp.z + rp.z) * 0.5 + math.cos(yaw) * forward - math.sin(yaw) * side,
        mode = "talons", joint = left_name .. "+" .. right_name,
        forward = forward, side = side,
    }
    eat.meal_anchor = anchor
    return anchor
end

function griffin_predation_meal_mouth_anchor(go, gpos, yaw, eat)
    if C.route3_predation_eat_mouth_anchor == false or not (go and gpos and eat) then return nil end
    -- The first native-eat tick runs just before 5300 is painted. Follow the live
    -- jaw briefly while that clip settles, then lock the meal in world space so
    -- it does not bob back and forth with every bite.
    local settle = 0.45
    local elapsed = os.clock() - (tonumber(eat.eat_t0 or eat.t0) or os.clock())
    if eat.meal_anchor and eat.meal_anchor.mode == "mouth" and elapsed >= settle then return eat.meal_anchor end
    local tf = transform_of(go)
    local joint_name = tostring(C.route3_predation_eat_anchor_joint or "Jaw_0")
    local joint = tf and managed_call(tf, "getJointByName", joint_name)
    local jp = joint and (managed_call(joint, "get_Position")
        or managed_call(joint, "get_WorldPosition") or managed_call(joint, "get_UniversalPosition"))
    local grp = transform_render_pos(go)
    if not (jp and grp and sane_position(jp)) then return nil end

    -- Joint positions are render-space; root transform positions are universal.
    -- Re-base the joint's render-space delta onto the universal root, exactly as
    -- the proven talon pin does, so world-tile offsets cannot fling the carcass.
    local forward = tonumber(C.route3_predation_eat_anchor_forward) or 0.35
    local side = tonumber(C.route3_predation_eat_anchor_side) or 0.0
    local anchor = {
        x = (tonumber(gpos.x) or 0.0) + (tonumber(jp.x) or 0.0) - (tonumber(grp.x) or 0.0)
            + math.sin(yaw) * forward + math.cos(yaw) * side,
        z = (tonumber(gpos.z) or 0.0) + (tonumber(jp.z) or 0.0) - (tonumber(grp.z) or 0.0)
            + math.cos(yaw) * forward - math.sin(yaw) * side,
        mode = "mouth", joint = joint_name,
        forward = forward,
        side = side,
    }
    eat.meal_anchor = anchor
    return anchor
end

function griffin_predation_meal_anchor(go, gpos, yaw, eat)
    if eat and eat.big == true then
        local talons = griffin_predation_meal_talon_anchor(go, gpos, yaw, eat)
        if talons then return talons end
    end
    return griffin_predation_meal_mouth_anchor(go, gpos, yaw, eat)
end

function griffin_predation_disable_meal_collision(prey, cgo, big, eat)
    if not (prey and cgo and eat) then return 0 end
    eat.meal_collision_disabled = eat.meal_collision_disabled or {}
    pcall(function() set_character_controller_enabled(prey, false) end)
    local types = { "via.physics.CharacterController" }
    if big == true then
        -- Fresh ox component dump (2026-07-13) proved the missing collision was
        -- SkinningMeshColliderSet/Holder plus the live death ragdoll. Disable
        -- every owner/updater, not merely the root Colliders wrapper, otherwise
        -- the two large bodies depenetrate and skate across the terrain.
        types = {
            "via.physics.CharacterController", "via.physics.Colliders", "via.physics.RequestSetCollider",
            "via.physics.SkinningMeshColliderSet", "app.SkinningMeshColliderHolder",
            "app.SkinningMeshColliderUpdater", "app.AdjustPress", "app.AdjustTerrain",
            "app.CharacterRagdoll", "via.dynamics.Ragdoll",
        }
    end
    for _, type_name in ipairs(types) do
        local comp = get_component(cgo, type_name)
        if comp then
            local rec = eat.meal_collision_disabled[comp]
            if not rec then
                local was = true
                pcall(function()
                    local v = comp:call("get_Enabled")
                    if type(v) == "boolean" then was = v end
                end)
                rec = { obj = comp, was = was, type_name = type_name }
                eat.meal_collision_disabled[comp] = rec
            end
            pcall(function() comp:call("set_Enabled", false) end) -- reassert: an updater may revive it
        end
    end
    local hits = 0
    for _ in pairs(eat.meal_collision_disabled) do hits = hits + 1 end
    return hits
end

function griffin_predation_restore_meal_collision(eat)
    if not (eat and eat.meal_collision_disabled) then return end
    for comp, rec in pairs(eat.meal_collision_disabled) do
        if rec and rec.was ~= false then pcall(function() comp:call("set_Enabled", true) end) end
        eat.meal_collision_disabled[comp] = nil
    end
end

-- Has the player walked away from the meal?
--
-- The eat is meant to hold "until the player moves", and both checks asked read_axis() -- i.e.
-- "is the stick deflected?". That is not the same question. read_axis honours
-- C.input_axis_source, which is "raw" here, so it reports the raw gamepad stick and nothing else;
-- move on the other input and the meal never notices. It also cannot see a player being carried,
-- shoved or warped.
--
-- Distance from where the meal started answers it for every input method at once. The stick check
-- stays as well, because it reacts on the first frame you push rather than after a metre.
function griffin_predation_eat_player_moved(eat, dist)
    if not eat then return false end
    local pgo = char_go(get_player())
    local pp = pgo and transform_pos(pgo)
    if not pp then return false end
    if not eat.anchor then
        eat.anchor = { x = tonumber(pp.x) or 0.0, z = tonumber(pp.z) or 0.0 }
        return false
    end
    local dx = (tonumber(pp.x) or 0.0) - eat.anchor.x
    local dz = (tonumber(pp.z) or 0.0) - eat.anchor.z
    dist = math.max(0.2, tonumber(dist) or 1.5)
    return (dx * dx + dz * dz) > (dist * dist)
end

function griffin_predation_carry_eat_tick()
    -- EAT-ON-LANDING for the NATIVE carry. Mirrors the WORKING eat-nearest command (griffin_eat_tick):
    -- set_griffin_puppet(true) keeps think ALIVE so the clip ADVANCES, ground-pin her with a LOCKED
    -- facing, reposition the prey, and play clips PLAINLY (no base_owner gate, no hard think-stop --
    -- those froze the claws-on). Land while carrying -> release into a real ragdoll -> claws-on
    -- (get_eat_start) -> eat LOOP held continuously until the player moves.
    if C.route3_predation_eat_enabled == false then return end
    local eat = S.route3_predation_eat
    if not eat then
        if S.route3_grab then return end   -- a homebrew grab owns the griffin; don't double-drive
        -- PENDING EAT (armed by the in-air release at landing intent): wait for touchdown, let the
        -- landing recover settle her into the neutral calm node, then start the eat there.
        local pend = S.route3_predation_eat_pending
        if pend then
            if S.mounted ~= true or (os.clock() - (tonumber(pend.t0) or 0.0)) > 25.0 then
                S.route3_predation_eat_pending = nil
            elseif S.airborne ~= true then
                if not pend.landed_at then pend.landed_at = os.clock(); return end
                -- wait until the landing recover has actually RUN (it clears recover_at to 0 once it
                -- forces the neutral calm node + puppet); route3_finish_landing schedules it ~0.8s out.
                -- 1.5s fallback so a missed recover can't strand the pending eat.
                if (tonumber(S.route3_post_landing_recover_at) or 0.0) > 0.0 and (os.clock() - pend.landed_at) < 1.5 then return end
                S.route3_predation_eat_pending = nil
                local prey = pend.prey
                if prey and char_go(prey) then
                    local _, _go0 = reacquire_griffin()
                    local lyaw = (_go0 and yaw_from_transform(_go0)) or S.heading_yaw or 0.0
                    local _big = false
                    pcall(function()
                        local _nm = tostring(go_name(char_go(prey)) or ""):lower()
                        for pat in tostring(C.route3_grab_big_prefixes or "ch299003"):gmatch("[^,%s]+") do
                            if _nm:find(pat:lower(), 1, true) then _big = true end
                        end
                    end)
                    S.base_owner = nil
                    S.route3_predation_eat = { prey = prey, t0 = os.clock(), phase = "start",
                        locked_yaw = lyaw, big = _big, diag = {}, from_air = true }
                    status(tostring(C.route3_griffin_name or "Griffin") .. " pins its catch to feed")
                    S.route3_predation_status = "eating"
                else
                    -- prey despawned during the descent (ragdoll corpse cleaned up) -- don't fail silent
                    S.route3_predation_status = "eat aborted: prey lost before touchdown"
                    status("Prey lost before the meal")
                end
                return
            end
            return
        end
        if not griffin_predation_native_carry_active() then return end
        if S.mounted ~= true or S.airborne == true then return end
        local carry_at = tonumber(S.route3_predation_carry_at) or 0.0
        if carry_at <= 0.0 or (os.clock() - carry_at) < (tonumber(C.route3_predation_eat_grace) or 1.5) then return end
        local prey = S.route3_predation_carry_prey or S.route3_predation_victim or S.companion_target
        if not prey then return end
        local now = os.clock()
        local _, _go0 = reacquire_griffin()
        local lyaw = (_go0 and yaw_from_transform(_go0)) or S.heading_yaw or 0.0
        local _big = false
        pcall(function()
            local _nm = tostring(go_name(char_go(prey)) or ""):lower()
            for pat in tostring(C.route3_grab_big_prefixes or "ch299003"):gmatch("[^,%s]+") do
                if _nm:find(pat:lower(), 1, true) then _big = true end
            end
        end)
        -- GRACE (Fable xhigh): let the native catch's own end/cancel actions PLAY on the ridden body,
        -- else the griffin action blocker cuts them and the grip clip on layers 1-4 stays painted
        -- over L0 = the mask that hid the eat clips. Same mechanism the NT-throw release uses.
        S.nt_allow_actions_until = now + 1.5
        pcall(function() griffin_predation_release_native_catch() end)
        pcall(function() griffin_predation_rebase_drive() end)   -- adopt the landed transform (no stale snap)
        S.route3_predation_mode = nil
        S.route3_predation_wake_until = 0.0
        S.route3_predation_probe_until = 0.0
        S.route3_predation_native_until = 0.0
        S.route3_predation_replay_stage = "handed-off"
        S.route3_post_landing_recover_at = 0.0
        S.base_owner = nil
        pcall(function()
            local c253r = _go0 and get_component(_go0, "app.Ch253000")
            if c253r then
                c253r:call("set_OxCatchSetCarryedMotion(System.Boolean)", false)
                c253r:call("set_MotinoLayerActionBodyName(System.String)", "Default")
                c253r:call("set_PredationTarget(via.GameObject)", nil)   -- else she auto-faces/circles the prey after
            end
        end)
        -- kill + ragdoll the prey so it flops flat for the meal (ported from route3_grab_eat)
        pcall(function() griffin_apply_attack_damage(prey, 99999.0) end)
        pcall(function() prey:call("EnableRagdoll(System.Boolean)", true) end)
        pcall(function() prey:call("startRagdoll") end)
        -- LIVE eat state -> the block below (set_griffin_puppet think-alive + ground pin + clip chain)
        -- becomes the driver. It was ORPHANED since v8 (trigger set S.route3_grab). Fable xhigh caught it.
        S.route3_predation_eat = { prey = prey, t0 = now, phase = "start", locked_yaw = lyaw, big = _big, diag = {} }
        status(tostring(C.route3_griffin_name or "Griffin") .. " pins its catch to feed")
        S.route3_predation_status = "eating"
        return
    end
    -- EAT IN PROGRESS
    local prey = eat.prey
    local cgo = prey and char_go(prey)
    local ch, go = reacquire_griffin()
    if not (prey and cgo and go) then
        griffin_predation_restore_meal_collision(eat)
        S.route3_predation_eat = nil
        pcall(function() set_griffin_puppet(false) end)
        return
    end
    local now = os.clock()
    S.base_owner = { name = "eat", until_clock = now + 1.0 }   -- hold the layer against the ride painters
    S.audition_until_clock = now + 0.3
    local eat_abort = S.airborne == true
    if not eat_abort and (now - (tonumber(eat.t0) or now)) > 0.75 then
        local amx, amz = 0.0, 0.0
        pcall(function() amx, amz = read_axis() end)
        if (math.abs(tonumber(amx) or 0.0) > 0.3) or (math.abs(tonumber(amz) or 0.0) > 0.3) then eat_abort = true end
        -- the stick is only one way to move; walking away counts whatever moved you
        if not eat_abort and griffin_predation_eat_player_moved(eat, C.route3_predation_eat_move_dist) then
            eat_abort = true
        end
    end
    if eat_abort then
        -- ABORT (takeoff or movement, any phase): end the meal instantly, hand everything back
        griffin_predation_restore_meal_collision(eat)
        S.route3_predation_eat = nil
        S.base_owner = nil
        S.audition_until_clock = 0.0
        pcall(function() set_griffin_puppet(false) end)
        pcall(function() griffin_predation_rearm_ride_suppression(ch, go) end)
        S.route3_post_landing_recover_at = os.clock()   -- normalize L0/speed/think/AI via the existing recover tick
        S.route3_flap_phase = nil
        S.route3_native_flight_node = nil
        S.route3_native_flight_last_check = 0.0
        S.route3_predation_status = "eat aborted (moved/took off)"
        return
    end
    -- think ALIVE + AI off + nav stopped + puppet-FREEZE the FSM (Fable HIGH). For the from_air eat
    -- she is now in the neutral calm node (Catch was left in the air), and freezing a neutral node
    -- is exactly the state the WORKING unmounted eat plays 5300/5310 in. == set_griffin_puppet(true).
    pcall(function() set_think_stop(ch, false) end)
    pcall(function() stop_navigation(ch, true) end)
    if C.disable_griffin_ai then
        pcall(function() disable_record(get_component(go, "app.AIDecisionMaker"), "app.AIDecisionMaker") end)
        pcall(function() disable_record(get_component(go, "app.NavigationAI"), "app.NavigationAI") end)
    end
    -- ==== KILL THE CARRY OVERLAY (Iris 2026-07-13) -- the actual "eat is invisible" fix. ====
    -- _eat_diag PROVED forcing her out of Catch is futile: 12 forced setCurrentNode calls and the node
    -- never budges (the Ch253 re-drives it). But the thing HIDING the eat was never the node -- it was
    -- the AddBringOx action body (OxCatchSetCarryedMotion + MotinoLayerActionBodyName) painting the carry
    -- grip over L0. Clearing that overlay reveals the L0 eat clip EVEN while she stays in the Catch node
    -- (Aurora confirmed the eat is visible now). So: no node-forcing, no return-loop (that only delayed +
    -- jittered the 5300 clip). Just clear the overlay -- every frame, cheap, so it can't creep back mid-
    -- meal. from_air only; the grounded fallback keeps its own hop.
    if eat.from_air == true then
        if not eat.carry_overlay_killed then
            local cc_live = false
            pcall(function() local cc = ch:call("get_CatchController"); cc_live = cc and cc:call("get_IsActive") == true end)
            if cc_live then pcall(function() griffin_predation_end_catcher(ch) end) end
            eat.carry_overlay_killed = true
        end
        pcall(function()
            local c253x = get_component(go, "app.Ch253000")
            if c253x then
                c253x:call("set_OxCatchSetCarryedMotion(System.Boolean)", false)
                c253x:call("set_MotinoLayerActionBodyName(System.String)", "Default")
                c253x:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 0)
                c253x:call("set_IsAirCatch(System.Boolean)", false)
            end
        end)
    end
    -- FREEZE only for the from_air eat (she is now in the NEUTRAL calm node -> freezing holds it while L0
    -- plays, the working-eat pattern; hardcoded true so a flipped puppet_motion_fsm debug flag can't
    -- silently break it). GROUNDED FALLBACK stays UN-frozen so its hop can try to leave Catch --
    -- freezing before the hop is the documented "latches the grip pose" anti-pattern (exit_cleanup note).
    pcall(function() set_motion_fsm_puppet(go, eat.from_air == true) end)
    pcall(function() griffin_predation_clear_carry_layers(go) end)
    -- HARD-kill the catcher if it's still active -- a live CatchController keeps re-driving the
    -- carry FSM node every frame (would revert any setCurrentNode).
    local catcher_active = false
    pcall(function() local cc = ch:call("get_CatchController"); catcher_active = cc and cc:call("get_IsActive") == true end)
    if catcher_active then pcall(function() griffin_predation_end_catcher(ch) end) end
    local cur_node = tostring(read_griffin_fsm_node())
    if eat.from_air ~= true then
        -- GROUNDED FALLBACK ONLY (rare: landed carrying without going through the in-air release).
        -- Try to leave the Catch node via the action system. NEVER do this for a from_air eat: she is
        -- already neutral, and a grounded FlyForward request could be accepted and fling her airborne.
        local step = "settled"
        if cur_node:find("Catch") or cur_node:find("Carry") then
            pcall(function() ch:call("resetActionAndAI") end)
            pcall(function() request_griffin_action(tostring(C.route3_predation_eat_exit_flight or "Fly.Flying.FlyForward"), 0) end)
            step = "hop1-flight"
        elseif cur_node:find("Fly") or cur_node:find("Hover") or cur_node:find("Takeoff") then
            pcall(function() request_griffin_action(tostring(C.route3_predation_eat_exit_action or "CombatStateNormal"), 0) end)
            pcall(function() set_griffin_fsm_node_silent(tostring(C.native_climb_calm_fsm_node or "Locomotion.Wait"), tonumber(C.native_climb_calm_fsm_tree) or 0) end)
            step = "hop2-neutral"
        end
        eat.node_dbg = string.format("cur=%s step=%s cc=%s (grounded-fallback)", cur_node, step, tostring(catcher_active))
    else
        eat.node_dbg = string.format("cur=%s from_air overlay-killed=%s cc=%s", cur_node, tostring(eat.carry_overlay_killed == true), tostring(catcher_active))
    end
    local yaw = tonumber(eat.locked_yaw) or yaw_from_transform(go) or S.heading_yaw or 0.0
    -- PIN her grounded + FIXED facing (holds her on the meal; think alive so the clip advances)
    -- ⭐ PIN LOCKED ONCE (2026-08-08, Aurora: "the griffin will slide (ice skate) while
    -- eating and that'll get it out of position or end the animation early" -- the pin
    -- re-read her LIVE position every tick, so any physics nudge (the corpse's shell, slope
    -- creep) re-anchored the pin at the nudged spot: a one-way ratchet. It also dragged the
    -- rider, tripping the eat's player-moved cancel = the early end. Capture the spot at
    -- eat start; re-assert THAT, immovably, every tick.)
    do
        local gpos = transform_pos(go)
        if gpos then
            if not eat.pin then
                local gy = tonumber(gpos.y) or 0.0
                pcall(function()
                    local rp = transform_render_pos(go)
                    local gh = route3_cast_ground_below(tonumber(rp and rp.x) or (tonumber(gpos.x) or 0.0), (tonumber(gpos.y) or 0.0) + 5.0, tonumber(rp and rp.z) or (tonumber(gpos.z) or 0.0), 3.0, 60.0)
                    if gh and tonumber(gh.y) then gy = tonumber(gh.y) end
                end)
                eat.pin = { x = tonumber(gpos.x) or 0.0, y = gy, z = tonumber(gpos.z) or 0.0 }
            end
            local gp2 = make_position(eat.pin.x, eat.pin.y, eat.pin.z)
            local gr2 = make_quat_yaw(yaw)
            pcall(function() set_transform(go, gp2, gr2) end)
            pcall(function() set_character_transform(ch, gp2, gr2) end)
        end
    end
    -- Lay the prey in front of her beak. Big prey used to be excluded entirely
    -- because its physics shell shoved her sideways; disable that shell first,
    -- then use the existing big-distance/Y controls to place the ox deliberately.
    if C.route3_predation_eat_position ~= false then
        local gpos = transform_pos(go)
        if gpos then
            local dist = math.max(0.5, tonumber(C.route3_grab_eat_distance) or 2.6)
            if eat.big == true then dist = dist + math.max(0.0, tonumber(C.route3_grab_eat_big_dist) or 2.0) end
            local side = tonumber(C.route3_grab_eat_side) or 0.0
            local anchor = griffin_predation_meal_anchor(go, gpos, yaw, eat)
            local ex = anchor and tonumber(anchor.x)
                or ((tonumber(gpos.x) or 0.0) + math.sin(yaw) * dist + math.cos(yaw) * side)
            local ez = anchor and tonumber(anchor.z)
                or ((tonumber(gpos.z) or 0.0) + math.cos(yaw) * dist - math.sin(yaw) * side)
            local ey = tonumber(gpos.y) or 0.0
            pcall(function()
                -- Cast below the DESTINATION, not the prey's old drop point. X/Z
                -- must be render-space; derive them from the griffin render root
                -- so world-tile offsets cancel correctly.
                local grp = transform_render_pos(go)
                local rex = grp and ((tonumber(grp.x) or 0.0) + ex - (tonumber(gpos.x) or 0.0)) or ex
                local rez = grp and ((tonumber(grp.z) or 0.0) + ez - (tonumber(gpos.z) or 0.0)) or ez
                local gh = route3_cast_ground_below(rex, (tonumber(gpos.y) or 0.0) + 5.0, rez, 3.0, 60.0)
                if gh and tonumber(gh.y) then ey = tonumber(gh.y) end
            end)
            local yraise = eat.big == true and (tonumber(C.route3_grab_eat_big_yraise) or 0.9) or 0.1
            local epos = make_position(ex, ey + yraise, ez)
            local erot = nil
            if eat.big == true and C.route3_predation_eat_big_crosswise ~= false then
                erot = make_quat_yaw(yaw + (tonumber(C.route3_predation_eat_big_yaw_deg) or 90.0) * math.pi / 180.0)
            elseif eat.big == true and C.route3_predation_eat_big_align == true then
                erot = make_quat_yaw(yaw + math.pi)
            elseif eat.big ~= true and C.route3_predation_eat_meal_rotate == true then
                -- ⭐ small-meal ROTATE (2026-08-08, Aurora: "might need a rotate option too"):
                -- forces the corpse's lie-angle relative to HER heading (180 = facing her,
                -- 90 = crosswise). OFF = the natural ragdoll flop, as before.
                erot = make_quat_yaw(yaw + (tonumber(C.route3_predation_eat_meal_yaw_deg) or 180.0) * math.pi / 180.0)
            end
            local collision_hits = griffin_predation_disable_meal_collision(prey, cgo, eat.big == true, eat)
            pcall(function() set_transform(cgo, epos, erot) end)
            pcall(function() set_character_transform(prey, epos, erot) end)
            eat.prey_position_status = anchor
                and string.format("%s=%s fwd=%.2f side=%.2f y=%.1f big=%s collision=%d",
                    tostring(anchor.mode), tostring(anchor.joint), tonumber(anchor.forward) or 0.0, tonumber(anchor.side) or 0.0,
                    yraise, tostring(eat.big == true), collision_hits)
                or string.format("root-dist=%.1f side=%.2f y=%.1f big=%s collision=%d",
                    dist, side, yraise, tostring(eat.big == true), collision_hits)
        end
    end
    -- CLIP CHAIN: claws-on START -> after start_secs -> eat LOOP. Played plainly (force) once per
    -- phase like the eat-nearest command -- the clip is left to run/loop on its own.
    local bank = math.floor(tonumber(C.route3_grab_clip_bank) or 20)
    local want = (eat.phase == "start") and math.floor(tonumber(C.route3_predation_eat_start_clip) or 5300)
        or math.floor(tonumber(C.route3_grab_eat_clip) or 5310)
    pcall(function()
        local playing = tonumber(route3_flap_layer_clip())
        if want >= 0 and playing ~= want and now - (tonumber(eat.reassert_at) or 0.0) > 0.25 then
            eat.reassert_at = now
            eat.pushes = (tonumber(eat.pushes) or 0) + 1
            play_griffin_motion(want, bank, true, "eat")
        end
        if now - (tonumber(eat.diag_at) or 0.0) > 0.5 then
            eat.diag_at = now
            local fr, endf, spd, pst = -1, -1, -1, "?"
            pcall(function()
                local m = ch:call("get_Motion")
                local l = m and m:call("getLayer", 0)
                if l then
                    fr = tonumber(l:call("get_Frame")) or -1
                    endf = tonumber(l:call("get_EndFrame")) or -1
                end
                if m then
                    spd = tonumber(m:call("get_PlaySpeed")) or -1
                    pst = tostring(m:call("get_PlayState"))
                end
            end)
            local lyr = ""
            pcall(function()
                local m = ch:call("get_Motion")
                for li = 0, 4 do pcall(function()
                    local layer = m:call("getLayer", li)
                    local id = layer and tonumber(layer:call("get_MotionID"))
                    if id and id < 4294967295 then
                        local w, f = -1, -1
                        pcall(function() w = tonumber(layer:call("get_Weight")) or -1 end)
                        pcall(function() f = tonumber(layer:call("get_Frame")) or -1 end)
                        lyr = lyr .. string.format(" L%d=%d(w%.2f f%.0f)", li, id, w, f)
                    end
                end) end
            end)
            eat.diag = eat.diag or {}
            eat.diag[#eat.diag + 1] = string.format(
                "%.1fs %s want=%d playing=%s fr=%.0f/%.0f spd=%.2f state=%s fsm=%s pushes=%d blocked=%s layers:%s NODE[%s]",
                now - (tonumber(eat.t0) or now), tostring(eat.phase), want, tostring(playing),
                fr, endf, spd, pst, tostring(read_griffin_fsm_node()),
                tonumber(eat.pushes) or 0, tostring(S.base_owner_blocked or ""), lyr, tostring(eat.node_dbg or ""))
            json.dump_file(MOD .. "_eat_diag.json", { time = os.date("%H:%M:%S"),
                big = eat.big == true, rows = eat.diag,
                -- which placement path ran: "mouth=Jaw_0 fwd=..." (anchor, the good one) or
                -- "root-dist=..." (fallback) -- the 2026-08-08 "too far" bug was fallback
                -- distances scrambled to 10/10 in the saved config
                placement = tostring(eat.prey_position_status or "(never placed)") })
        end
    end)
    if eat.phase == "start" then
        -- Play the FULL claws-on start clip (5300). Aurora: it must run its whole ~5s, not get cut at
        -- ~1.5s by a wall-clock timer. Transition to the eat LOOP only when 5300 actually reaches its end
        -- frame; a generous wall-clock safety (start_secs, min 6s) covers a bad frame read so it can't hang.
        local sfr, sendf = -1, -1
        pcall(function()
            local m = ch:call("get_Motion")
            local l = m and m:call("getLayer", 0)
            if l then sfr = tonumber(l:call("get_Frame")) or -1; sendf = tonumber(l:call("get_EndFrame")) or -1 end
        end)
        local clip_done = (sendf > 1 and sfr >= 0 and sfr >= sendf - 6)
        local safety = (now - (tonumber(eat.t0) or now)) >= math.max(8.0, tonumber(C.route3_predation_eat_start_secs) or 8.0)
        if clip_done or safety then
            eat.phase = "loop"; eat.loop_at = now
            pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_grab_eat_clip) or 5310), bank, true, "eat") end)
        end
    end
    -- END on movement (Aurora: "played continuously until you moved") or a safety timeout
    local ended = false
    if eat.phase == "loop" and (now - (tonumber(eat.loop_at) or now)) > 0.5 then
        local mx, mz = 0.0, 0.0
        pcall(function() mx, mz = read_axis() end)
        if (math.abs(tonumber(mx) or 0.0) > 0.3) or (math.abs(tonumber(mz) or 0.0) > 0.3) then ended = true end
        if not ended and griffin_predation_eat_player_moved(eat, C.route3_predation_eat_move_dist) then
            ended = true
        end
    end
    if (now - (tonumber(eat.t0) or now)) > (tonumber(C.route3_predation_eat_max_secs) or 60.0) then ended = true end
    if ended then
        pcall(function() griffin_apply_attack_damage(prey, 99999.0) end)   -- devoured
        griffin_predation_restore_meal_collision(eat)
        S.route3_predation_eat = nil
        S.base_owner = nil
        S.audition_until_clock = 0.0
        pcall(function() set_griffin_puppet(false) end)   -- hand her back to normal flight/control
        pcall(function() local _c, _g = reacquire_griffin(); griffin_predation_rearm_ride_suppression(_c, _g) end)
        S.route3_post_landing_recover_at = os.clock()   -- normalize L0/speed/think/AI via the existing recover tick
        S.route3_flap_phase = nil
        S.route3_native_flight_node = nil
        S.route3_native_flight_last_check = 0.0
        pcall(function()
            local _g2 = select(2, reacquire_griffin())
            local c253e = _g2 and get_component(_g2, "app.Ch253000")
            if c253e then
                c253e:call("set_OxCatchSetCarryedMotion(System.Boolean)", false)
                c253e:call("set_MotinoLayerActionBodyName(System.String)", "Default")
                c253e:call("set_PredationTarget(via.GameObject)", nil)   -- else she auto-faces/circles the prey after
            end
        end)
        pcall(function() route3_flap_after_action() end)
        S.route3_predation_status = "meal finished"
        status(tostring(C.route3_griffin_name or "Griffin") .. " finishes its meal")
    end
end
-- ⭐⭐ BONES REMAINS (2026-08-08, Aurora's design: "maybe we just leave generic bones?" --
-- gimmick gm51_581, a generic picked-clean bone pile, spawned where the meal lay as the
-- corpse vanishes. One pile fits every species; nobody autopsies the femurs. Minimal port
-- of IrisFurnish's PROVEN gimmick-spawn state machine (prefab -> ready ->
-- requestCreateInstance -> poll). ⛔ UNIVERSAL coords (the gimmick-spawn law).
function griffin_bones_spawn_queue(ux, uy, uz, yaw)
    local gid
    pcall(function()
        local fld = sdk.find_type_definition("app.GimmickID"):get_field("Gm51_581")
        if fld then gid = fld:get_data() end
    end)
    if not gid then S.route3_bones_status = "no GimmickID for gm51_581"; return false end
    S.route3_bones_jobs = S.route3_bones_jobs or {}
    table.insert(S.route3_bones_jobs, { gid = gid, x = ux, y = uy, z = uz, yaw = yaw or 0.0, stage = "prefab", f = 0 })
    return true
end

function griffin_bones_pump()
    local jobs = S.route3_bones_jobs
    if not jobs or #jobs == 0 then return end
    for i = #jobs, 1, -1 do
        local q = jobs[i]
        local drop = false
        if q.stage == "prefab" then
            local ok = pcall(function()
                local prefab = sdk.create_instance("via.Prefab"):add_ref()
                prefab:set_Path("AppSystem/gimmick/prefab/gm51_581.pfb")
                pcall(function() prefab:set_Standby(true) end)
                local ctrl = sdk.create_instance("app.PrefabController"):add_ref()
                ctrl._Item = prefab
                pcall(function() ctrl:get_Item():set_Standby(true) end)
                local inst = sdk.create_instance("app.InstanceInfo"):add_ref()
                local container
                pcall(function() container = inst:get_Container() end)
                if not container then container = sdk.create_instance("app.GenerateInfo.GenerateInfoContainer"):add_ref() end
                local pos = ValueType.new(sdk.find_type_definition("via.Position"))
                pos.x, pos.y, pos.z = q.x, q.y, q.z
                local cat = 5
                pcall(function()
                    local f2 = sdk.find_type_definition("app.GeneratorCategory"):get_field("Gimmick")
                    if f2 then cat = f2:get_data() end
                end)
                pcall(function() container._CommonInfo._Category = cat end)
                pcall(function() container._CommonInfo._ObjectID._SelectedGimmickID = q.gid end)
                pcall(function() container._CommonInfo._InitialPosition = pos end)
                pcall(function() container._CommonInfo._ContextPosition = pos end)
                pcall(function() container._CommonInfo:setContextPosition(pos) end)
                pcall(function()
                    local half = (q.yaw or 0.0) / 2.0
                    local rqt = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                    rqt.x, rqt.y, rqt.z, rqt.w = 0.0, math.sin(half), 0.0, math.cos(half)
                    container._CommonInfo:setInitialAngle(rqt)
                end)
                q.prefab, q.ctrl, q.inst, q.container = prefab, ctrl, inst, container
            end)
            if ok and q.prefab then q.stage = "wait"; q.f = 0 else drop = true end
        elseif q.stage == "wait" then
            q.f = q.f + 1
            local ready = false
            pcall(function() ready = q.prefab:get_Ready() == true end)
            if ready then
                S.route3_bones_seq = (tonumber(S.route3_bones_seq) or 0) + 1
                local okr = pcall(function()
                    local gen = sdk.get_managed_singleton("app.GenerateManager")
                    gen:call("requestCreateInstance(app.PrefabController, app.GenerateInfo.GenerateInfoContainer, System.Int32, app.InstanceInfo, System.Action`2<app.PrefabInstantiateResults,app.DummyArg>, System.Action`2<app.PrefabInstantiateResults,app.DummyArg>)",
                        q.ctrl, q.container, 743500 + S.route3_bones_seq, q.inst, nil, nil)
                end)
                if okr then q.stage = "poll"; q.f = 0 else drop = true end
            elseif q.f > 900 then drop = true end
        elseif q.stage == "poll" then
            q.f = q.f + 1
            local bgo
            pcall(function() bgo = q.inst:get_Instance() end)
            if not bgo then pcall(function() bgo = q.inst["<Instance>k__BackingField"] end) end
            if bgo then
                S.route3_bones_status = "bones left at the kill"
                drop = true
            elseif q.f > 900 then
                S.route3_bones_status = "bones spawn timed out"
                drop = true
            end
        else
            drop = true
        end
        if drop then table.remove(jobs, i) end
    end
end

function route3_grab_eat()
    local st = S.route3_grab
    local carried = st and st.carried
    if not (st and carried) then return false end
    if st.phase == "eat" then return true end   -- already feeding
    st.phase = "eat"
    st.eat_t0 = os.clock()
    st.eat_phase = "start"
    st.eat_loop_due = nil
    st.eat_reassert_at = 0.0
    st.meal_anchor = nil
    st.last = os.clock()
    route3_grab_detach_from_talon(carried)   -- unparent so the eat can lay it on the ground
    route3_grab_unfreeze(carried)   -- undo the dangle freeze so the death/ragdoll animates
    -- (2026-08-07: an eat-start warp briefly lived here and was REMOVED same day -- the eat
    -- tick below already runs a full per-tick meal-placement system (distance/side/ground
    -- cast/lie-angle/joint anchors); a second writer at start just fought it. The placement
    -- problem Aurora sees is diagnosed via the eat_diag black box instead.)
    -- KILL it so the engine's death ragdoll flops it FLAT on the ground (matches the
    -- unmounted eat -- a live ragdoll stayed upright), then ragdoll to back it up.
    pcall(function() griffin_apply_attack_damage(carried, 99999.0) end)
    pcall(function() carried:call("EnableRagdoll(System.Boolean)", true) end)
    pcall(function() carried:call("startRagdoll") end)
    -- eat animation on the griffin -- flap parked so it shows, same as the snatch.
    -- claws-on (talons-on-body) FIRST, then the eat loop after eat_start_secs
    local clip = math.floor(tonumber(C.route3_grab_eat_clip) or -1)
    local sclip = math.floor(tonumber(C.route3_predation_eat_start_clip) or -1)
    if sclip >= 0 then
        S.base_owner = { name = "eat", until_clock = os.clock() + 1.0 }
        pcall(function() play_griffin_motion(sclip, math.floor(tonumber(C.route3_grab_clip_bank) or 20), true, "eat") end)
        st.anim = true
        S.audition_until_clock = os.clock() + 3.0
    elseif clip >= 0 then
        st.eat_phase = "loop"
        st.eat_loop_at = os.clock()
        S.base_owner = { name = "eat", until_clock = os.clock() + 1.0 }
        pcall(function() play_griffin_motion(clip, math.floor(tonumber(C.route3_grab_clip_bank) or 20), true, "eat") end)
        st.anim = true
        S.audition_until_clock = os.clock() + 3.0
    else
        st.eat_phase = "loop"
        st.eat_loop_at = os.clock()
    end
    status(tostring(C.route3_griffin_name or "Griffin") .. " sets down its catch to feed")
    S.route3_grab_status = "eating"
    return true
end

function route3_grab_tick(ch, go, now)
    local st = S.route3_grab
    if not st then return false end
    if not (ch and go) or S.mounted ~= true then route3_grab_drop("interrupted"); return false end
    -- (corpse-carry allowed: do NOT auto-drop a carried body just because it's dead --
    -- a prey that dies mid-carry simply becomes a carried corpse)
    -- while the grab anim plays, kill the layer-1 flap overlay so its baked wing SFX
    -- doesn't double up with the grab clip's (the swoop/grab double-flap-sound bug)
    if st.anim == true then pcall(function() route3_flap_clear_overlay() end) end
    if st.phase == "pickup" or st.phase == "carry" then
        pcall(function() route3_grab_drive_carry_anim(st) end)
    end
    if st.phase == "dive" then
        local dur = math.max(0.3, tonumber(st.dur) or tonumber(C.route3_grab_duration) or 1.4)
        if now - (tonumber(st.t0) or now) > dur then route3_grab_end("missed"); return false end
        local target = st.target
        local tgo = target and char_go(target)
        local tpos = tgo and transform_pos(tgo)
        local gpos = transform_pos(go)
        if not (target and tpos and gpos) then route3_grab_end("target lost"); return false end   -- dead OK (corpse grab)
        local dt = math.max(0.001, math.min(0.05, now - (tonumber(st.last) or now)))
        st.last = now
        S.airborne = true   -- stay in FLIGHT mode through the snatch so she never LANDS (a landing
                            -- flips S.flying/airborne, flight_tick bails, and the carry freezes with
                            -- the prey stuck on the ground = "connected but on the ground").
        local dx = (tonumber(tpos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
        local dz = (tonumber(tpos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
        local hdist = math.sqrt(dx * dx + dz * dz)   -- HORIZONTAL distance: she snatches from ABOVE
        -- HOLD a hover altitude over the ground instead of diving down to the prey's Y. Diving to
        -- the floor was landing her; staying up lets route3_grab_pin_late yank the prey UP to the
        -- talon (which is the whole point of a talon carry). Ease toward ground + snatch clearance.
        local clr = math.max(1.0, tonumber(C.route3_grab_snatch_clearance) or 3.0)
        local ground_y = route3_ground_y_robust(go, st.entry_y or (tonumber(gpos.y) or 0.0))
        if ground_y then st.ground_y = ground_y else ground_y = tonumber(st.ground_y) end   -- persist
        local cur_y = tonumber(gpos.y) or 0.0
        local want_y = cur_y
        if ground_y then
            local hover_y = ground_y + clr
            want_y = cur_y + (hover_y - cur_y) * math.min(1.0, 4.0 * dt)   -- descend/climb to hover
        end
        -- only snatch once she's BOTH horizontally over the prey AND descended to snatch height
        -- (else diving straight down from way up would catch at altitude = a huge yank-up).
        local low_enough = (not ground_y) or (cur_y <= ground_y + clr + 3.0)
        if hdist <= math.max(2.0, tonumber(C.route3_grab_range) or 6.0) and low_enough then
            if st.native_catch == true then pcall(function() griffin_grab_crash_mark("SNATCH reached -> route3_grab_catch") end) end
            route3_grab_catch(ch, go, target)
            return true
        end
        local speed = math.max(1.0, tonumber(C.route3_grab_forward_speed) or 12.0)
        local scale = math.min(1.0, (speed * dt) / math.max(0.001, hdist))
        local np = make_position(
            (tonumber(gpos.x) or 0.0) + dx * scale,
            want_y,
            (tonumber(gpos.z) or 0.0) + dz * scale)
        S.route3_air_pos = np
        S.route3_air_rot = make_quat_yaw(math.atan(dx, dz))
        pcall(function() route3_apply_air_transform(ch, go, np, S.route3_air_rot) end)
        S.route3_grab_status = string.format("closing to snatch h=%.1fm y=%.1f", hdist, want_y)
        if st.native_catch == true then
            st.dbg_frame = (tonumber(st.dbg_frame) or 0) + 1
            pcall(function() griffin_grab_crash_mark(string.format("dive f%d h=%.1f", st.dbg_frame, hdist)) end)
        end
        return true
    elseif st.phase == "pickup" then
        -- SNATCH: HOVER in place (flight_tick zeros the stick this phase) + park the flap
        -- AND wing systems (full swoop technique) so the pickup clip actually renders, then
        -- hand off to free-flight carry.
        S.audition_until_clock = now + 0.3
        -- LIFT OFF: raise the hover target toward carry altitude so a low/ground snatch actually
        -- picks the prey UP off the ground (talon = where it hangs). One-shot until st.lifted.
        route3_grab_climb_liftoff(st, go)
        local hp = S.route3_air_pos or transform_pos(go)
        if hp then
            pcall(function() route3_apply_air_transform(ch, go, hp, S.route3_air_rot or make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)) end)
        end
        -- (carried-body pin moved to route3_grab_pin_late / LateUpdateBehavior -- it reads
        -- the ANIMATED talon joint AFTER UpdateMotion, which is what kills the displacement)
        -- diagnostic: is the snatch clip actually the one playing on her base layer, or is
        -- something still overriding it? (want X:Y vs playing 0:Z)
        pcall(function() S.route3_grab_status = string.format("snatch want %s:%s  playing 0:%s",
            tostring(math.floor(tonumber(C.route3_grab_clip_bank) or 50)),
            tostring(math.floor(tonumber(C.route3_grab_pickup_clip) or -1)),
            tostring(route3_flap_layer_clip() or "?")) end)
        -- one-shot probe a few frames in (let the clip settle) -> read off disk
        if not st.probed and (now - (tonumber(st.t0) or now)) > 0.2 then
            st.probed = true
            pcall(function()
                local mid0, mid1 = nil, nil
                pcall(function() mid0 = route3_flap_layer_clip() end)
                pcall(function() mid1 = route3_flap_overlay_clip() end)
                json.dump_file(MOD .. "_grab_probe.json", {
                    time = os.date("%H:%M:%S"),
                    want_bank = math.floor(tonumber(C.route3_grab_clip_bank) or 50),
                    want_pickup_clip = math.floor(tonumber(C.route3_grab_pickup_clip) or -1),
                    playing_base_layer0 = mid0,
                    playing_overlay_layer1 = mid1,
                    fsm_node = (function() pcall(function() read_griffin_fsm_node() end) return S.last_fsm_node end)(),
                    audition_active = (tonumber(S.audition_until_clock) or 0) > now,
                    mounted = S.mounted, flying = S.flying, airborne = S.airborne,
                    grab_anim_flag = st.anim, grab_phase = st.phase,
                    ragdoll_call_ok = S.route3_grab_ragdoll_ok,
                    prey_name = tostring(go_name(char_go(st.carried)) or "?"),
                    prey_fall_ragdoll_methods = (function()
                        local m = {}
                        pcall(function() m = method_names_matching(st.carried, { "fall", "ragdoll", "gravity", "blow", "knock", "down", "airborne", "float", "collapse" }, 80) end)
                        return m
                    end)(),
                })
            end)
        end
        -- don't hand off to free-flight until BOTH the snatch clip has had its beat AND she's
        -- lifted the prey clear of the ground (st.lifted). Hard 3.5s cap so a failed climb (no
        -- ground read, blocked, etc.) can't wedge us in pickup forever.
        if ((now >= (tonumber(st.pickup_until) or 0.0)) and st.lifted)
            or ((now - (tonumber(st.grabbed_at) or now)) > 3.5) then
            st.phase = "carry"; st.carry_started = false
        end
        return true
    elseif st.phase == "carry" then
        -- honor a throw queued during the dive/snatch (pressing Y mid-pickup used to be ignored)
        if st.queued_throw == true then
            st.queued_throw = nil
            route3_grab_throw("queued")
            return true
        end
        -- ANIM FLOW: the snatch clip plays first (flap PARKED via audition so it shows);
        -- after pickup_until, switch to the carry/hold clip looped so she doesn't freeze on
        -- the snatch's last frame. start -> hold. (Land-to-eat and drop handle the END.)
        if st.anim then
            if (not st.carry_started) and now >= (tonumber(st.pickup_until) or 0.0) then
                st.carry_started = true
                local cclip = math.floor(tonumber(C.route3_grab_carry_clip) or -1)
                if cclip >= 0 then
                    pcall(function() play_griffin_motion(cclip, math.floor(tonumber(C.route3_grab_clip_bank) or 50), true) end)
                else
                    -- no hold clip -> resume her normal flap so she doesn't freeze on the
                    -- snatch's last frame while carrying
                    st.anim = false
                    route3_restore_flight_base()
                end
            end
            if st.anim then S.audition_until_clock = now + 0.3 end
        end
        -- (carried-body pin is now route3_grab_pin_late in LateUpdateBehavior -- reads the
        -- ANIMATED talon joint after UpdateMotion so it stays glued with no displacement)
        -- land while carrying -> eat. GRACE: never auto-eat in the first moment after a snatch,
        -- or a snatch that caught her briefly low would flip straight to eating (= "goblin ends
        -- up on the ground, never picked up"). Only a DELIBERATE later landing feeds.
        if C.route3_grab_eat_enabled == true and S.airborne ~= true
            and (now - (tonumber(st.grabbed_at) or now)) > (tonumber(C.route3_grab_eat_grace) or 1.5) then
            route3_grab_eat()
        end
        return true
    elseif st.phase == "eat" then
        -- lay the prey (ragdolled = limp/flat) on the GROUND in front of her beak while the
        -- eat clip plays, then devour it.
        if st.anim then
            S.audition_until_clock = now + 0.3
            S.base_owner = { name = "eat", until_clock = now + 1.0 }
            -- The corpse route does not have native predation's eat driver. Give
            -- it the same ownership: live think for clip advance, frozen neutral
            -- FSM, cleared partial-body layers, and a guarded L0 reassert.
            pcall(function() set_think_stop(ch, false) end)
            pcall(function() stop_navigation(ch, true) end)
            pcall(function() set_motion_fsm_puppet(go, true) end)
            pcall(function() griffin_predation_clear_carry_layers(go) end)
            local bank = math.floor(tonumber(C.route3_grab_clip_bank) or 20)
            local start_clip = math.floor(tonumber(C.route3_predation_eat_start_clip) or 5300)
            local loop_clip = math.floor(tonumber(C.route3_grab_eat_clip) or 5310)
            local want = st.eat_phase == "start" and start_clip or loop_clip
            local playing = tonumber(route3_flap_layer_clip())
            if want >= 0 and playing ~= want and now - (tonumber(st.eat_reassert_at) or 0.0) > 0.25 then
                st.eat_reassert_at = now
                pcall(function() play_griffin_motion(want, bank, true, "eat") end)
            end
            if st.eat_phase == "start" then
                local fr, endf = -1, -1
                pcall(function()
                    local m = ch:call("get_Motion")
                    local l = m and m:call("getLayer", 0)
                    if l then fr = tonumber(l:call("get_Frame")) or -1; endf = tonumber(l:call("get_EndFrame")) or -1 end
                end)
                local clip_done = endf > 1 and fr >= 0 and fr >= endf - 6
                local safety = now - (tonumber(st.eat_t0) or now) >= math.max(8.0, tonumber(C.route3_predation_eat_start_secs) or 8.0)
                if clip_done or safety then
                    st.eat_phase = "loop"
                    st.eat_loop_at = now
                    pcall(function() play_griffin_motion(loop_clip, bank, true, "eat") end)
                end
            end
            if now - (tonumber(st.eat_diag_at) or 0.0) > 0.5 then
                st.eat_diag_at = now
                pcall(function()
                    local fr, endf = -1, -1
                    local m = ch:call("get_Motion")
                    local l = m and m:call("getLayer", 0)
                    if l then fr = tonumber(l:call("get_Frame")) or -1; endf = tonumber(l:call("get_EndFrame")) or -1 end
                    json.dump_file(MOD .. "_homebrew_eat_diag.json", {
                        time = os.date("%H:%M:%S"), corpse = st.corpse == true,
                        phase = tostring(st.eat_phase), want = want, playing = tonumber(route3_flap_layer_clip()),
                        frame = fr, end_frame = endf, position = tostring(st.prey_position_status or "?") })
                end)
            end
        end
        local carried = st.carried
        local cgo = carried and char_go(carried)
        local gpos = transform_pos(go)
        if cgo and gpos then
            local yaw = yaw_from_transform(go) or S.heading_yaw or 0.0
            local big = griffin_predation_is_big_meal(carried)
            st.big = big
            local dist = math.max(0.5, tonumber(C.route3_grab_eat_distance) or 2.6)
            if big then
                dist = dist + math.max(0.0, tonumber(C.route3_grab_eat_big_dist) or 2.0)
            else
                -- ⭐ SMALL meals sit CLOSER (2026-08-08, Aurora: deer = right, chopper = "way
                -- too far away" -- the base distance suits a bulky body whose centre is far
                -- from its edge; a small corpse at the same root distance ends up beyond the
                -- beak). Dedicated distance for the small class.
                dist = math.max(0.5, tonumber(C.route3_grab_eat_small_dist) or 1.5)
            end
            local side = tonumber(C.route3_grab_eat_side) or 0.0   -- +right/-left, centre the prey
            local anchor = griffin_predation_meal_anchor(go, gpos, yaw, st)
            local ex = anchor and tonumber(anchor.x)
                or ((tonumber(gpos.x) or 0.0) + math.sin(yaw) * dist + math.cos(yaw) * side)
            local ez = anchor and tonumber(anchor.z)
                or ((tonumber(gpos.z) or 0.0) + math.cos(yaw) * dist - math.sin(yaw) * side)
            local ey = tonumber(gpos.y) or 0.0
            pcall(function()
                local grp = transform_render_pos(go)
                local rex = grp and ((tonumber(grp.x) or 0.0) + ex - (tonumber(gpos.x) or 0.0)) or ex
                local rez = grp and ((tonumber(grp.z) or 0.0) + ez - (tonumber(gpos.z) or 0.0)) or ez
                local gh = route3_cast_ground_below(rex, (tonumber(gpos.y) or 0.0) + 5.0, rez, 3.0, 60.0)
                if gh and tonumber(gh.y) then ey = tonumber(gh.y) end
            end)
            local epos = make_position(ex, ey + (big and (tonumber(C.route3_grab_eat_big_yraise) or 0.9) or 0.1), ez)
            -- ROTATION: default (angle 0) = nil = natural ragdoll flop; non-zero forces a set
            -- lie-angle (yaw toward her beak + pitch), same control as the unmounted eat.
            local pdeg = tonumber(C.route3_grab_eat_pitch_deg) or 0.0
            local erot = nil
            local body_yaw = yaw + math.pi
            if big and C.route3_predation_eat_big_crosswise ~= false then
                body_yaw = yaw + (tonumber(C.route3_predation_eat_big_yaw_deg) or 90.0) * math.pi / 180.0
                erot = make_quat_yaw(body_yaw)
            end
            if pdeg ~= 0.0 then erot = griffin_make_quat_yaw_pitch(body_yaw, pdeg * math.pi / 180.0) end
            griffin_predation_disable_meal_collision(carried, cgo, big, st)
            pcall(function() set_transform(cgo, epos, erot) end)
            pcall(function() set_character_transform(carried, epos, erot) end)
            st.prey_position_status = anchor
                and string.format("%s=%s fwd=%.2f side=%.2f", tostring(anchor.mode), tostring(anchor.joint),
                    tonumber(anchor.forward) or 0.0, tonumber(anchor.side) or 0.0)
                or string.format("root-dist=%.1f side=%.2f", dist, side)
        end
        if st.carry_from_native == true and now - (tonumber(st.eat_diag_at) or 0.0) > 0.5 then
            st.eat_diag_at = now
            local amx, amz = 0.0, 0.0
            pcall(function() amx, amz = read_axis() end)
            pcall(function()
                -- v2 (2026-08-07): + PLACEMENT forensics -- where the placement system thinks
                -- the meal is vs where it actually lies (Aurora: goblin AND bandit both ended
                -- up wrong; read this file after an eat to see which link lies)
                local mgo2 = st.carried and char_go(st.carried)
                local mp2 = mgo2 and transform_pos(mgo2)
                local gp4 = transform_pos(go)
                local rel = "?"
                if mp2 and gp4 then
                    local rdx2 = (tonumber(mp2.x) or 0) - (tonumber(gp4.x) or 0)
                    local rdz2 = (tonumber(mp2.z) or 0) - (tonumber(gp4.z) or 0)
                    local ry2 = (tonumber(mp2.y) or 0) - (tonumber(gp4.y) or 0)
                    local yw2 = yaw_from_transform(go) or 0.0
                    -- express the meal's offset in HER frame: +fwd = ahead of the beak
                    local fwd = rdx2 * math.sin(yw2) + rdz2 * math.cos(yw2)
                    local side = rdx2 * math.cos(yw2) - rdz2 * math.sin(yw2)
                    rel = string.format("fwd=%.2f side=%.2f dy=%.2f", fwd, side, ry2)
                end
                json.dump_file(MOD .. "_eat_diag.json", { time = os.date("%H:%M:%S"),
                    elapsed = now - (tonumber(st.eat_t0) or now), phase = "eat",
                    playing = tonumber(route3_flap_layer_clip()), loop_due = st.eat_loop_due ~= nil,
                    airborne = S.airborne == true, flying = S.flying == true,
                    meal_rel_to_beak = rel,
                    placement_status = tostring(st.prey_position_status or "(placement never ran)"),
                    carry_from_native = st.carry_from_native == true,
                    axis = string.format("%.2f,%.2f", tonumber(amx) or 0.0, tonumber(amz) or 0.0) })
            end)
        end
        local eat_done = false
        if st.carry_from_native == true then
            if S.airborne == true then eat_done = true end
            if not eat_done and now - (tonumber(st.eat_t0) or now) > 1.0 then
                local emx, emz = 0.0, 0.0
                pcall(function() emx, emz = read_axis() end)
                if (math.abs(tonumber(emx) or 0.0) > 0.3) or (math.abs(tonumber(emz) or 0.0) > 0.3) then eat_done = true end
            end
            if now - (tonumber(st.eat_t0) or now) > 20.0 then eat_done = true end
        else
            eat_done = st.eat_phase == "loop"
                and now - (tonumber(st.eat_loop_at) or now) > math.max(0.5, tonumber(C.route3_grab_eat_duration) or 3.0)
        end
        if eat_done then
            pcall(function() griffin_apply_attack_damage(carried, 99999.0) end)   -- devoured
            griffin_predation_restore_meal_collision(st)
            route3_grab_restore_ground_components()   -- undo the carry's component disables before it's gone
            pcall(function() set_motion_fsm_puppet(go, false) end)
            -- ⭐ CORPSE VANISH (2026-08-07, Aurora: the finished meal "looking unscathed" ruins
            -- it -- make the remains disappear). ⛔ NEVER destroy() a native body (the ogre-
            -- crash law: dangling target-list refs) -- WARP it far below the world instead,
            -- the farming eviction pattern.
            if C.route3_eat_corpse_vanish ~= false then
                pcall(function()
                    local meal = S.route3_grab and S.route3_grab.carried
                    local mgo = meal and char_go(meal)
                    local mp0 = mgo and transform_pos(mgo)
                    if mp0 then
                        -- ⭐ leave the BONES where the meal lay (queued BEFORE the warp; the
                        -- pile inherits her heading so it reads as the meal's remains)
                        if C.route3_eat_leave_bones ~= false then
                            local byaw = yaw_from_transform(go) or S.heading_yaw or 0.0
                            pcall(function() griffin_bones_spawn_queue(
                                tonumber(mp0.x) or 0.0, tonumber(mp0.y) or 0.0, tonumber(mp0.z) or 0.0, byaw) end)
                        end
                        local away = make_position((tonumber(mp0.x) or 0.0) + 400.0,
                            (tonumber(mp0.y) or 0.0) - 120.0, (tonumber(mp0.z) or 0.0) + 400.0)
                        pcall(function() mgo:call("get_Transform"):call("set_UniversalPosition", away) end)
                        pcall(function() meal:call("set_UniversalPosition", away) end)
                    end
                end)
            end
            S.route3_grab = nil
            S.base_owner = nil
            S.audition_until_clock = 0.0
            S.route3_post_landing_recover_at = os.clock()
            route3_flap_after_action()   -- double-flap hygiene on EVERY exit
            S.route3_grab_status = "devoured"
            status(tostring(C.route3_griffin_name or "Griffin") .. " devours its catch")
        end
        return true
    elseif st.phase == "ntcatch" then
        -- NATURAL THROW: wait for the REAL catch to establish, verified against the recording
        -- (caught=true + ragdoll "pin_00_carry"). Timeout degrades to the frozen drop.
        local carried = st.carried
        local cgo = carried and char_go(carried)
        if not cgo then route3_grab_end("lost"); return false end
        S.nt_allow_actions_until = now + 1.0   -- keep the blockers standing down
        local caught, rstate = route3_grab_nt_state(carried, cgo)
        S.route3_grab_ragdiag = string.format("nt catch=%s state=%s", tostring(caught), tostring(rstate or "?"))
        S.route3_grab_status = "natural throw: " .. S.route3_grab_ragdiag
        route3_grab_nt_trace("ntcatch " .. S.route3_grab_ragdiag)
        local elapsed = now - (tonumber(st.nt_t0) or now)
        if caught == true then
            -- established: the catch owns position NOW -- flip physics native (the pin's ntcatch
            -- hold returns the instant caught went true, so no write/physics overlap)
            st.nt_established = true
            route3_grab_restore_ground_components()
            pcall(function() set_character_controller_enabled(carried, true) end)
            pcall(function() carried:call("EnableRagdoll(System.Boolean)", true) end)
            st.phase = "ntrelease"
            st.nt_rel_at = now + math.max(0.1, tonumber(C.route3_grab_nt_hold_secs) or 0.2)
            st.nt_rel_try = 0
        elseif elapsed > 0.8 then
            route3_grab_nt_trace("-> frozen drop (catch never established)")
            route3_grab_frozen_drop(st, carried, cgo, st.nt_dmg, st.nt_fall_h)
        end
        return true
    elseif st.phase == "ntrelease" then
        -- NATURAL RELEASE: reserve the thrown reaction, then end the catch the native way --
        -- try the release APIs in order until the caught flag actually drops.
        local carried = st.carried
        local cgo = carried and char_go(carried)
        if not cgo then route3_grab_end("lost"); return false end
        local cc = nil
        pcall(function() cc = ch and ch:call("get_CatchController") end)
        S.nt_allow_actions_until = now + 1.0   -- keep the blockers standing down through the release
        local caught, rstate = route3_grab_nt_state(carried, cgo)
        S.route3_grab_ragdiag = string.format("nt release try=%d caught=%s state=%s", tonumber(st.nt_rel_try) or 0, tostring(caught), tostring(rstate or "?"))
        route3_grab_nt_trace("ntrelease " .. S.route3_grab_ragdiag)
        S.route3_grab_status = "natural throw: " .. S.route3_grab_ragdiag
        if caught == false or caught == nil then
            route3_grab_nt_trace("RELEASED after try=" .. tostring(st.nt_rel_try or 0) .. " -> monitoring fall")
            -- RELEASED: the game owns it now (thrown/fall states) -- just monitor the landing
            st.native_launched = true
            st.phase = "throw"
            st.throw_t0 = now; st.last = now
            st.drop_alive = false
            st.drop_dmg = st.nt_dmg   -- landing fallback damage (HP-delta guarded)
            return true
        end
        if now >= (tonumber(st.nt_rel_at) or 0.0) and cc then
            st.nt_rel_at = now + 0.3   -- next attempt window
            st.nt_rel_try = (tonumber(st.nt_rel_try) or 0) + 1
            route3_grab_nt_trace("firing release try=" .. tostring(st.nt_rel_try))
            local try = st.nt_rel_try
            if try == 1 then
                -- THE PROVEN release (griffin_predation_release_native_catch): abort BOTH halves.
                -- The Setting's CaughtCancelAction (DmgRagdollFall / CatchEndByCh253000) then plays
                -- NATIVELY = "lets go, naturally falls". NO reserveCaughtReleaseAction (it would
                -- override the cancel action with a player-throw pose).
                local cgt = nil
                pcall(function() cgt = carried:call("get_CaughtController") end)
                pcall(function() cc:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
                pcall(function() cc:call("set_IsContinue(System.Boolean)", false) end)
                pcall(function() cc:call("abort(System.Boolean)", true) end)
                pcall(function() cgt:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
                pcall(function() cgt:call("set_IsContinue(System.Boolean)", false) end)
                pcall(function() cgt:call("abortDirect") end)
                pcall(function()
                    local c253 = go and get_component(go, "app.Ch253000")
                    if c253 then
                        c253:call("set_CatchTargetType(app.Ch253000.CatchTargetEnum)", 0)
                        c253:call("set_IsAirCatch(System.Boolean)", false)
                    end
                end)
            elseif try == 2 then
                -- fallback: the literal fall request
                pcall(function() cc:call("requestFallCaughtChara") end)
                pcall(function() local cgt = carried:call("get_CaughtController"); if cgt then cgt:call("requestFallCaughtChara") end end)
            elseif try == 3 then
                pcall(function() cc:call("set_IsDisableEscape(System.Boolean)", false) end)
                pcall(function() cc:call("requestCatchCancelActionOnAbort") end)
            elseif try >= 4 then
                route3_grab_frozen_drop(st, carried, cgo, st.nt_dmg, st.nt_fall_h)
            end
        end
        return true
    elseif st.phase == "throw" then
        local carried = st.carried
        local cgo = carried and char_go(carried)
        local cpos = cgo and transform_pos(cgo)
        if not cpos then
            route3_grab_finish_throw(carried, nil, nil, st.native_launched == true, st.land_hp0)
            return false   -- body vanished
        end

        -- NATIVE FREE-FALL: MONITOR ONLY -- the game's own fall action owns the body; never write
        -- its transform. Track the apex + watch for landing. get_IsGround is an unverified getter,
        -- so ALSO accept ground-proximity (fresh y-space-correct cast) as the landing signal; the
        -- time cap only finishes if the body is actually NEAR the floor (restoring GroundFixer
        -- mid-air = the snap-to-terrain bug), with a long hard-abort so nothing is orphaned.
        if st.native_launched == true then
            local cy = tonumber(cpos.y) or 0.0
            if not st.peak_y or cy > st.peak_y then st.peak_y = cy end
            local elapsed = now - (tonumber(st.throw_t0) or now)
            if st.drop_integrate == true then
                -- TRANSFORM-DRIVEN FALL (no native physics mid-air = nothing can warp or eject):
                -- v += g*dt straight down, written every tick; the floor check below lands it.
                local dt = math.max(0.001, math.min(0.05, now - (tonumber(st.last) or now)))
                st.last = now
                local g = tonumber(C.route3_fall_damage_gravity) or 24.0
                st.drop_vy = (tonumber(st.drop_vy) or 0.0) + g * dt
                local ny = cy - st.drop_vy * dt
                local np = make_position(tonumber(cpos.x) or 0.0, ny, tonumber(cpos.z) or 0.0)
                pcall(function() set_transform(cgo, np, nil) end)
                pcall(function() set_character_transform(carried, np, nil) end)
                cy = ny
            end
            if st.drop_alive == true then
                -- survivable drop: keep it alive + immune THROUGH the fall (its fall-death check
                -- must never win mid-air); the landing applies the real height damage.
                route3_grab_set_immunity(carried, true)
                if tonumber(st.land_hp0) then route3_grab_keep_alive(carried, tonumber(st.land_hp0)) end
            end
            if st.throw_state_at and now >= st.throw_state_at then
                -- recorded transition: dmg_throw_action -> dmg_throw_pause ~0.4s after release
                st.throw_state_at = nil
                pcall(function()
                    local rt = sdk.find_type_definition("via.dynamics.Ragdoll"):get_runtime_type()
                    local rd = cgo:call("getComponent(System.Type)", rt)
                    if rd then rd:call("set_RagdollStateName(System.String)", "dmg_throw_pause") end
                end)
            end
            local grounded = false
            pcall(function() grounded = carried:call("get_IsGround") == true end)
            local ground_y = nil
            pcall(function()
                local rp = transform_render_pos(cgo) or cpos
                local gh = route3_cast_ground_below(tonumber(rp.x) or 0.0, cy + 30.0, tonumber(rp.z) or 0.0, 2.0, 400.0)
                if gh and tonumber(gh.y) then ground_y = tonumber(gh.y) end
            end)
            if ground_y then st.drop_gy = ground_y else ground_y = tonumber(st.drop_gy) end
            local near_floor = ground_y and (cy <= ground_y + 1.0)
            -- LANDING = position-verified ONLY. get_IsGround reads STALE-TRUE right after release
            -- (the tape showed a 15.5m "fall" landing in 0.36s -> finish restored GroundFixer/nav
            -- mid-air -> the body WARPED to the floor = "it just appears on the ground").
            -- Also require the physics-minimum fall time for the measured height.
            local min_fall = 0.3
            if st.peak_y and ground_y then
                local h = math.max(0.0, st.peak_y - ground_y)
                local g = tonumber(C.route3_fall_damage_gravity) or 24.0
                min_fall = math.max(0.3, 0.7 * math.sqrt(2.0 * h / math.max(1.0, g)))
            end
            local landed = (elapsed > min_fall) and near_floor == true
            if st.drop_integrate == true and ground_y and cy <= ground_y + 0.4 then landed = elapsed > 0.15 end
            if elapsed > 8.0 then landed = true end                             -- hard abort: never orphan
            if landed and st.drop_integrate == true and ground_y then
                -- place it ON the floor before finish restores its systems (safe: nothing overlaps here)
                local lp = make_position(tonumber(cpos.x) or 0.0, ground_y + 0.2, tonumber(cpos.z) or 0.0)
                pcall(function() set_transform(cgo, lp, nil) end)
                pcall(function() set_character_transform(carried, lp, nil) end)
            end
            if landed then
                local fall_h = st.peak_y and math.max(0.0, st.peak_y - (ground_y or cy)) or nil
                route3_grab_finish_throw(carried, fall_h, nil, true, st.land_hp0, st.drop_alive == true and st.drop_dmg or nil)
                return false
            end
            S.route3_grab_status = string.format("falling apex=%.1f y=%.1f gnd=%s %s",
                st.peak_y or cy, cy, tostring(ground_y and math.floor(ground_y) or "?"), tostring(S.route3_grab_ragdiag or ""))
            return true
        end

        -- ===== LEGACY hand-rolled arc (route3_grab_native_throw = false) =====
        local dt = math.max(0.001, math.min(0.05, now - (tonumber(st.last) or now)))
        st.last = now
        st.vy = (tonumber(st.vy) or 0.0) - 24.0 * dt   -- gravity
        local nx = (tonumber(cpos.x) or 0.0) + (tonumber(st.vx) or 0.0) * dt
        local ny = (tonumber(cpos.y) or 0.0) + (tonumber(st.vy) or 0.0) * dt
        if not st.peak_y or ny > st.peak_y then st.peak_y = ny end   -- track the apex
        local nz = (tonumber(cpos.z) or 0.0) + (tonumber(st.vz) or 0.0) * dt
        local ground_y = nil
        pcall(function()
            local rp = transform_render_pos(cgo) or cpos
            local gh = route3_cast_ground_below(tonumber(rp.x) or 0.0, (tonumber(cpos.y) or 0.0) + 30.0, tonumber(rp.z) or 0.0, 2.0, 400.0)
            if gh and tonumber(gh.y) then ground_y = tonumber(gh.y) end
        end)
        local landed = false
        if ground_y and ny <= ground_y + 0.3 and (tonumber(st.vy) or 0.0) < 0.0 then ny = ground_y + 0.3; landed = true end
        if now - (tonumber(st.throw_t0) or now) > 4.0 then landed = true end
        local np = make_position(nx, ny, nz)
        pcall(function() set_transform(cgo, np, nil) end)
        pcall(function() set_character_transform(carried, np, nil) end)
        S.route3_grab_status = string.format("thrown  vy=%.1f", tonumber(st.vy) or 0.0)
        if landed then
            local fall_h = st.peak_y and math.max(0.0, (tonumber(st.peak_y) or 0.0) - (ground_y or ny)) or nil
            local impact_vy = math.abs(tonumber(st.vy) or 0.0)   -- v^2/2g == apex-land (same integrator)
            route3_grab_finish_throw(carried, fall_h, impact_vy)
            return false
        end
        return true
    end
    return false
end

function route3_grab_hotkey_tick()
    if C.route3_grab_enabled ~= true or S.mounted ~= true then S.route3_grab_btn_prev = false; return end
    local down = false
    local names = tostring(C.route3_grab_buttons or ""):gsub("%s+", "")
    if names ~= "" then pcall(function() down = raw_gamepad_button_down(C.route3_grab_buttons) end) end
    if not down then
        local vk = math.floor(tonumber(C.route3_grab_key) or 0)
        if vk > 0 then pcall(function() down = iris_kb(vk) end) end
    end
    if down == true and S.route3_grab_btn_prev ~= true then
        if C.route3_grab_native == true then
            -- NATIVE catch on the grab button (over the homebrew grab): press to
            -- catch nearest catchable, press again to release. Grounded + not
            -- carrying = leave the press for the stomp/peck tick (don't intercept).
            if griffin_grab_active() and S.route3_grab.phase == "carry" then
                route3_grab_throw("button")
            elseif griffin_grab_active() and (S.route3_grab.phase == "pickup" or S.route3_grab.phase == "dive") then
                S.route3_grab.queued_throw = true
                S.route3_grab_status = "throw queued"
            elseif griffin_predation_native_carry_active() then
                griffin_predation_release_native_catch()
            elseif S.airborne == true then
                griffin_predation_grab_approach_start()
            end
        elseif griffin_grab_active() and S.route3_grab.phase == "carry" then
            route3_grab_throw("button")
        elseif griffin_grab_active() and (S.route3_grab.phase == "pickup" or S.route3_grab.phase == "dive") then
            -- QUEUE a press made mid-snatch (Lyra: ignoring it made the button feel broken):
            -- the carry tick fires the throw the instant the carry establishes
            S.route3_grab.queued_throw = true
            S.route3_grab_status = "throw queued"
        elseif not griffin_grab_active() then
            route3_grab_start("button")
        end
    end
    S.route3_grab_btn_prev = down == true
end

function route3_grab_start(reason)
    if C.route3_grab_enabled ~= true then return false end
    if S.mounted ~= true then status("mount + take off to grab"); return false end
    if S.airborne ~= true then status("take off first to grab"); return false end   -- grounded Y = stomp/peck, not a grab
    if griffin_grab_active() then return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then return false end
    local target = route3_grab_find_target(go)
    if not target then status("nothing grabbable ahead"); return false end
    local gp = transform_pos(go)
    S.route3_grab = {
        phase = "dive", t0 = os.clock(), last = os.clock(),
        target = target, yaw = yaw_from_transform(go) or S.heading_yaw or 0.0,
        entry_y = gp and tonumber(gp.y) or 0.0,   -- ref for the robust ground cast
    }
    S.route3_grab_status = "diving to grab"
    status(tostring(C.route3_griffin_name or "Griffin") .. " dives to snatch!")
    return true
end

-- ============================================================================
-- "EAT THAT" COMMAND (Aurora): unmounted order -> she flies to a grabbable enemy,
-- POUNCES on it (ground grab), and FEEDS. Same target constraints as the mounted
-- grab (route3_grab_is_grabbable: non-boss, up to oxen). Clip chain (bank 20):
--   4010 grb_hold_attack_ground_start (pounce) -> 4012 grb_hold_attack_ground_hit
--   -> 5300 get_eat_start (claws onto body) -> 5310 get_eat_loop -> 5320 get_eat_end.
-- Prey repositioned ragdolled in front of her beak exactly like the mounted eat.
-- ============================================================================
-- Should the meal be cut short? Returns a reason, or nil to keep feeding.
--
-- Feeding deliberately owns her -- orders suspend while she eats -- but "owns her" was reading as
-- "ignores you": route3_eat_loop_dur is 16 seconds, so ordering her to follow mid-meal did
-- nothing visible and looked like the animation had got stuck (Aurora: "moving when eating
-- doesn't end the eating animation"). Whether it appeared to work depended entirely on how far
-- into the loop she was.
--
-- griffin_eat_start clears companion_order, so any order sitting here was issued DURING the meal
-- and is the player explicitly asking for her back. That outranks lunch.
function griffin_eat_interrupt_reason()
    local ordered = S.companion_order
    if ordered == "follow" or ordered == "come" or ordered == "stay" or ordered == "attack" then
        return "ordered to " .. tostring(ordered)
    end
    -- She should also not stay behind chewing while the player walks off. The leash is generous:
    -- it is there to stop her being abandoned, not to police where you stand.
    local leash = tonumber(C.route3_eat_leash) or 0.0
    if leash > 0.0 then
        local _, go = reacquire_griffin()
        local pgo = char_go(get_player())
        local gp = go and transform_pos(go)
        local pp = pgo and transform_pos(pgo)
        if gp and pp then
            local dx = (tonumber(pp.x) or 0.0) - (tonumber(gp.x) or 0.0)
            local dz = (tonumber(pp.z) or 0.0) - (tonumber(gp.z) or 0.0)
            if (dx * dx + dz * dz) > leash * leash then return "player walked away" end
        end
    end
    return nil
end

function griffin_eat_active()
    return type(S.route3_eat) == "table"
end

function griffin_eat_find_target(go)
    -- nearest grabbable to the griffin (NO facing constraint -- it's a command, she
    -- may not be looking at it), same filter as the mounted grab.
    local gpos = go and transform_pos(go)
    if not gpos then return nil end
    local radius = math.max(6.0, tonumber(C.route3_eat_search_radius) or 45.0)
    local best, best_d = nil, radius * radius
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        for _, ch in ipairs(system_array_to_table(comps) or {}) do
            pcall(function()
                if route3_grab_is_grabbable(ch) then
                    local pos = transform_pos(char_go(ch))
                    if pos then
                        local dx = (tonumber(pos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
                        local dz = (tonumber(pos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
                        local d2 = dx * dx + dz * dz
                        if d2 < best_d then best, best_d = ch, d2 end
                    end
                end
            end)
        end
    end)
    return best
end

function griffin_eat_pin_griffin_ground(ch, go, tgo)
    -- hold her grounded, facing the prey, during the pounce/feed so root motion or
    -- physics can't drift her off the meal.
    pcall(function() set_griffin_puppet(true) end)
    local gpos = transform_pos(go)
    if not gpos then return end
    -- FIXED facing (locked at arrival). Do NOT re-face the moving/ragdolling prey every
    -- frame or she spins -- hold one direction for the whole pounce+feed.
    local st = S.route3_eat
    local yaw = (st and tonumber(st.locked_yaw)) or yaw_from_transform(go) or S.heading_yaw or 0.0
    local gy = tonumber(gpos.y) or 0.0
    pcall(function()
        local gh = route3_ground_hit_under(go)
        if gh and tonumber(gh.y) then gy = tonumber(gh.y) end
    end)
    local pos = make_position(tonumber(gpos.x) or 0.0, gy, tonumber(gpos.z) or 0.0)
    local rot = make_quat_yaw(yaw)
    pcall(function() set_transform(go, pos, rot) end)
    pcall(function() set_character_transform(ch, pos, rot) end)
end

function griffin_make_quat_yaw_pitch(yaw, pitch)
    -- yaw about Y (heading) composed with a pitch about X. pitch=0 == make_quat_yaw;
    -- pitch=pi/2 tips a standing body flat (horizontal). q = q_yaw * q_pitch.
    local hy, hp = (tonumber(yaw) or 0.0) * 0.5, (tonumber(pitch) or 0.0) * 0.5
    local cy, sy = math.cos(hy), math.sin(hy)
    local cp, sp = math.cos(hp), math.sin(hp)
    local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
    q.w = cy * cp
    q.x = cy * sp
    q.y = sy * cp
    q.z = -sy * sp
    return q
end

function griffin_eat_reposition_prey(ch, go, target)
    -- lay the ragdolled prey lying FLAT in front of her beak, ground-clamped (render-space
    -- cast). The per-frame root pin overrides the ragdoll, so we must pin a HORIZONTAL
    -- rotation (yaw + ~90deg pitch) or it stands upright between her talons.
    local cgo = target and char_go(target)
    local gpos = transform_pos(go)
    if not (cgo and gpos) then return end
    local st = S.route3_eat
    local yaw = (st and tonumber(st.locked_yaw)) or yaw_from_transform(go) or S.heading_yaw or 0.0
    local dist = math.max(0.5, tonumber(C.route3_eat_distance) or 2.6)
    local side = tonumber(C.route3_eat_side) or 0.0   -- +right / -left, to centre the prey
    -- forward = (sin,cos) along yaw; right = (cos,-sin) perpendicular
    local ex = (tonumber(gpos.x) or 0.0) + math.sin(yaw) * dist + math.cos(yaw) * side
    local ez = (tonumber(gpos.z) or 0.0) + math.cos(yaw) * dist - math.sin(yaw) * side
    local ey = tonumber(gpos.y) or 0.0
    pcall(function()
        local rp = transform_render_pos(cgo)
        local gh = route3_cast_ground_below(tonumber(rp and rp.x) or ex, (tonumber(gpos.y) or 0.0) + 5.0, tonumber(rp and rp.z) or ez, 3.0, 60.0)
        if gh and tonumber(gh.y) then ey = tonumber(gh.y) end
    end)
    local epos = make_position(ex, ey + 0.1, ez)
    -- ROTATION: default (angle 0) = pin POSITION ONLY and let the DEAD body's own ragdoll
    -- flop it flat -- the upright look before was our yaw-pin FIGHTING the natural drape.
    -- A non-zero angle forces a controlled lie-flat rotation instead (experimental: the
    -- pivot is at the feet, so it swings rather than lays -- usually leave it at 0).
    local pdeg = tonumber(C.route3_eat_prey_pitch_deg) or 0.0
    local erot = nil
    if pdeg ~= 0.0 then erot = griffin_make_quat_yaw_pitch(yaw + math.pi, pdeg * math.pi / 180.0) end
    pcall(function() set_transform(cgo, epos, erot) end)
    pcall(function() set_character_transform(target, epos, erot) end)
    pcall(function() set_character_controller_enabled(target, false) end)
end

function griffin_eat_end(reason)
    local st = S.route3_eat
    S.route3_eat = nil
    S.audition_until_clock = 0.0
    S.airborne = false
    S.flying = false
    -- prey survived (interrupted, not devoured): un-ragdoll + un-freeze it so it acts again
    if st and st.target and reason ~= "devoured" then
        pcall(function() st.target:call("EnableRagdoll(System.Boolean)", false) end)
        pcall(function() set_character_controller_enabled(st.target, true) end)
        pcall(function() st.target:call("set_IsThinkStop", false) end)
        pcall(function() stop_navigation(st.target, false) end)
        pcall(function() st.target:call("setDamageReaction") end)
    end
    -- GRIFFIN recovery: ONLY when WE still own her body. On a "mounted" exit the ride
    -- system just placed her into a native climb-mount action -- calling
    -- stop_griffin_animation() (forces an FSM node) + set_griffin_puppet(false)
    -- (=resetActionAndAI) on a body mid native-action is the documented CRASH class.
    -- Let the ride own her; only clear our state.
    if reason ~= "mounted" then
        local gch, go = reacquire_griffin()
        -- snap her to the ground first so a fly-phase abort doesn't drop her from the air
        if go then
            pcall(function()
                local gp = transform_pos(go)
                local gh = route3_ground_hit_under(go)
                if gp and gh and tonumber(gh.y) then
                    local rot = make_quat_yaw(yaw_from_transform(go) or S.heading_yaw or 0.0)
                    local pos = make_position(tonumber(gp.x) or 0.0, tonumber(gh.y), tonumber(gp.z) or 0.0)
                    set_transform(go, pos, rot)
                    if gch then set_character_transform(gch, pos, rot) end
                end
            end)
        end
        pcall(function() stop_griffin_animation() end)
        pcall(function() set_griffin_puppet(false) end)
        S.companion_order = "stay"
    end
    S.route3_eat_status = "eat=" .. tostring(reason or "done")
    return true
end

function griffin_eat_start(reason)
    if griffin_eat_active() then return false end   -- already feeding: don't orphan the current prey
    if S.mounted == true then status("dismount before sending her to feed"); return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then status("no companion to send"); return false end
    local target = griffin_eat_find_target(go)
    if not target then status("nothing she can eat nearby"); return false end
    if S.route3_unleashed == true then pcall(function() griffin_recall() end) end
    S.companion_order = nil
    S.route3_companion_moving = false
    S.route3_whistle_flyin = nil
    S.drive_pos = nil; S.drive_rot = nil
    S.route3_air_pos = nil; S.route3_air_rot = nil
    S.route3_eat = {
        phase = "fly", target = target, target_go = char_go(target),
        t0 = os.clock(), last = os.clock(), flap_at = 0.0,
    }
    pacify_griffin(nil)
    stop_navigation(ch, true)
    set_griffin_motion_speed(1.0)
    pcall(function() play_griffin_motion(math.floor(tonumber(C.flap_takeoff_clip) or 5210), 0, true) end)
    S.route3_eat_status = "moving to feed"
    status(tostring(C.route3_griffin_name or "Companion") .. " moves in to feed...")
    return true
end

function griffin_eat_tick()
    local st = S.route3_eat
    if not st then return false end
    if S.world_paused == true then return true end
    if S.mounted == true then griffin_eat_end("mounted"); return false end
    local ch, go = reacquire_griffin()
    if not (ch and go) then griffin_eat_end("no griffin"); return false end
    local target = st.target
    local tgo = st.target_go or (target and char_go(target))
    local now = os.clock()
    -- once she's COMMITTED (pouncing/feeding) a dead/despawned target is FINE -- we KILL it
    -- on the pounce-hit, and a vanished corpse just means the feed clips play out on their
    -- own. Only bail on a lost/dead target during the FLY phase (before she's on it).
    local committed = st.phase ~= "fly"
    if not (target and tgo) or not transform_pos(tgo) then
        if not committed then griffin_eat_end("target lost"); return false end
    elseif is_dead(target) and not committed then
        griffin_eat_end("target lost"); return false
    end
    local bank = math.floor(tonumber(C.route3_eat_clip_bank) or 20)

    if st.phase == "fly" then
        if now - (tonumber(st.t0) or now) > (tonumber(C.route3_eat_timeout) or 25.0) then
            griffin_eat_end("could not reach"); return false
        end
        pcall(function() set_griffin_puppet(true) end)
        S.airborne = false; S.flying = false
        local gpos = transform_pos(go)
        local tpos = transform_pos(tgo)
        if not (gpos and tpos) then return true end
        local dxh = (tonumber(tpos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
        local dzh = (tonumber(tpos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
        local hdist = math.sqrt(dxh * dxh + dzh * dzh)
        local ghit = route3_ground_hit_under(tgo)
        local tground = (ghit and tonumber(ghit.y)) or (tonumber(tpos.y) or 0.0)
        local engage = tonumber(C.route3_eat_engage_range) or 2.5
        if hdist <= engage then
            -- ARRIVED: LOCK the facing now (held for the whole pounce+feed so she never
            -- spins), settle onto the ground, freeze the prey, begin the pounce
            st.locked_yaw = math.atan(dxh, dzh)
            local face = make_quat_yaw(st.locked_yaw)
            local landed = make_position(tonumber(gpos.x) or 0.0, tground, tonumber(gpos.z) or 0.0)
            pcall(function() set_transform(go, landed, face) end)
            pcall(function() set_character_transform(ch, landed, face) end)
            pcall(function() target:call("set_IsThinkStop", true) end)
            pcall(function() stop_navigation(target, true) end)
            st.phase = "pounce"; st.phase_t0 = now; st.hit_played = false
            pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_eat_pounce_clip) or 4010), bank, false) end)
            S.audition_until_clock = now + 2.0
            S.route3_eat_status = "POUNCE"
            return true
        end
        -- inline eased flight drive (mirrors the unleash approach -- NOT route3_aerial_move_to,
        -- which sets airborne=true and re-pins an unmounted body)
        local clearance = tonumber(C.route3_eat_cruise_clear) or 5.0
        local ease = math.min(1.0, hdist / 15.0)
        local dest_y = tground + clearance * ease
        local step = route3_aerial_frame_step(st, tonumber(C.route3_eat_approach_speed) or 16.0, 1.0)
        local dx = (tonumber(tpos.x) or 0.0) - (tonumber(gpos.x) or 0.0)
        local dy = dest_y - (tonumber(gpos.y) or 0.0)
        local dz = (tonumber(tpos.z) or 0.0) - (tonumber(gpos.z) or 0.0)
        local d3 = math.sqrt(dx * dx + dy * dy + dz * dz)
        if d3 > 0.001 then
            local sc = math.min(step, d3) / d3
            local face = make_quat_yaw(math.atan(dxh, dzh))
            local npos = make_position((tonumber(gpos.x) or 0.0) + dx * sc,
                (tonumber(gpos.y) or 0.0) + dy * sc, (tonumber(gpos.z) or 0.0) + dz * sc)
            pcall(function() set_transform(go, npos, face) end)
            pcall(function() set_character_transform(ch, npos, face) end)
        end
        if (tonumber(st.flap_at) or 0.0) + 3.5 < now then
            st.flap_at = now
            pcall(function() play_griffin_motion(math.floor(tonumber(C.flap_takeoff_clip) or 5210), 0, true) end)
        end
        S.route3_eat_status = string.format("flying to feed %.0fm", hdist)
        return true

    elseif st.phase == "pounce" then
        -- 4010 pounce -> 4012 hit (KNOCKS IT DOWN). Hold her grounded, facing locked.
        S.audition_until_clock = now + 0.3
        griffin_eat_pin_griffin_ground(ch, go, tgo)
        local p_dur = math.max(0.2, tonumber(C.route3_eat_pounce_dur) or 0.37)
        local h_dur = math.max(0.2, tonumber(C.route3_eat_hit_dur) or 0.3)
        if (not st.hit_played) and now - (tonumber(st.phase_t0) or now) >= p_dur then
            st.hit_played = true
            pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_eat_pounce_hit_clip) or 4012), bank, false) end)
            S.audition_until_clock = now + 1.0
            -- KILL it on the hit (Aurora: "dead if easier"). A DEAD body flops flat via the
            -- engine's own death ragdoll (lie-down solved) and it's dead before the beak
            -- goes in. Capsule-off + explicit ragdoll back it up so it can't stay upright.
            pcall(function() griffin_apply_attack_damage(target, 99999.0) end)
            pcall(function() set_character_controller_enabled(target, false) end)
            pcall(function() target:call("EnableRagdoll(System.Boolean)", true) end)
            pcall(function() target:call("startRagdoll") end)
            st.ragdolled = true
        end
        if st.hit_played then
            griffin_eat_reposition_prey(ch, go, target)   -- lay it lying in front from the hit on
        else
            pcall(function() target:call("set_IsThinkStop", true) end)
        end
        if now - (tonumber(st.phase_t0) or now) >= p_dur + h_dur then
            st.phase = "eat_start"; st.phase_t0 = now
            pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_eat_start_clip) or 5300), bank, false) end)
            S.audition_until_clock = now + 1.5
            S.route3_eat_status = "FEEDING"
        end
        return true

    elseif st.phase == "eat_start" or st.phase == "eat_loop" then
        S.audition_until_clock = now + 0.3
        griffin_eat_pin_griffin_ground(ch, go, tgo)
        griffin_eat_reposition_prey(ch, go, target)
        if st.phase == "eat_start" and now - (tonumber(st.phase_t0) or now) >= math.max(0.2, tonumber(C.route3_eat_start_dur) or 3.8) then
            st.phase = "eat_loop"; st.phase_t0 = now
            pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_eat_loop_clip) or 5310), bank, true) end)
        end
        if st.phase == "eat_loop" and now - (tonumber(st.phase_t0) or now) >= math.max(0.5, tonumber(C.route3_eat_loop_dur) or 16.0) then
            st.phase = "eat_end"; st.phase_t0 = now
            pcall(function() play_griffin_motion(math.floor(tonumber(C.route3_eat_end_clip) or 5320), bank, false) end)
        end
        return true

    elseif st.phase == "eat_end" then
        S.audition_until_clock = now + 0.3
        griffin_eat_pin_griffin_ground(ch, go, tgo)
        griffin_eat_reposition_prey(ch, go, target)
        if now - (tonumber(st.phase_t0) or now) >= math.max(0.3, tonumber(C.route3_eat_end_dur) or 0.4) then
            pcall(function() griffin_apply_attack_damage(target, 99999.0) end)   -- devoured
            status(tostring(C.route3_griffin_name or "Griffin") .. " devours its prey")
            griffin_eat_end("devoured")
            return false
        end
        return true
    end
    return true
end

-- ============ CREATURE RECOLOR (ported from the Bestiary/APEX fx.change_color) ============
-- per-material BaseColor tint on a live via.render.Mesh. color = {r,g,b,a} tints ALL
-- materials (overall), or a table {matname={r,g,b,a}} tints named ones. proven recipe.
function iris_recolor(go, color)
    if not (go and color) then return 0 end
    local mesh = nil
    pcall(function() mesh = go:call("getComponent(System.Type)", sdk.typeof("via.render.Mesh")) end)
    if not mesh then return 0 end
    if S.iris_basecolor_hash == nil then
        pcall(function()
            local m = sdk.find_type_definition("via.murmur_hash"):get_method("calc32(System.String)")
            S.iris_basecolor_hash = m:call(nil, "BaseColor")
        end)
    end
    local hash = S.iris_basecolor_hash
    if not hash then return 0 end
    local hits = 0
    local n = 0
    pcall(function() n = mesh:call("get_MaterialNum") or 0 end)
    for mi = 0, (tonumber(n) or 0) - 1 do
        local matname = ""
        pcall(function() matname = tostring(mesh:call("getMaterialName", mi) or "") end)
        local rgba = nil
        if color[1] then rgba = color
        elseif color[matname] then rgba = color[matname] end
        if rgba and rgba ~= "disabled" then
            local vi = -1
            pcall(function() vi = mesh:call("getMaterialVariableIndex", mi, hash) end)
            local vn = 0
            pcall(function() vn = mesh:call("getMaterialVariableNum", mi) or 0 end)
            if vi and vi >= 0 and vi < (tonumber(vn) or 0) then
                pcall(function()
                    mesh:call("setMaterialFloat4", mi, vi, Vector4f.new(rgba[1], rgba[2], rgba[3], rgba[4] or 1.0))
                    hits = hits + 1
                end)
            end
        end
    end
    return hits
end

function iris_active_go()
    -- the live active stable-companion GameObject (always a tamed creature)
    local go = S.griffin_go
    if go and go.call then return go end
    if S.griffin and S.griffin.call then
        local g = nil
        pcall(function() g = S.griffin:call("get_GameObject") end)
        if g and g.call then return g end
    end
    return nil
end

function iris_apply_active_color(color)
    local go = iris_active_go()
    if not go then S.iris_color_status = "no active companion -- summon one first"; return end
    local hits = iris_recolor(go, color)
    local st = S.route3_stable
    if st and st.active then
        for _, comp in ipairs(st.companions or {}) do
            if comp.id == st.active then comp.color = { color[1], color[2], color[3], color[4] or 1.0 } end
        end
        pcall(function() griffin_stable_write() end)
        pcall(function() griffin_tamed_save() end)
    end
    S.iris_color_status = string.format("recoloured %d materials (saved)", hits)
end


function iris_recolor_tick()
    -- re-apply the active companion's saved colour on a low cadence so it survives
    -- summon/respawn (materials reset when the mesh reloads)
    local now = os.clock()
    if now < (tonumber(S.iris_recolor_next) or 0.0) then return end
    S.iris_recolor_next = now + 1.5
    local st = S.route3_stable
    if not (st and st.active) then return end
    local color = nil
    for _, comp in ipairs(st.companions or {}) do
        if comp.id == st.active then color = comp.color end
    end
    if not color then return end
    local go = iris_active_go()
    if go then iris_recolor(go, color) end
end

-- friendly display name for the HP panel + anywhere (ch253000_00 -> "Griffin", NPCs keep raw for now)
function griffin_display_name(ch)
    if not ch then return "Target" end
    local raw = tostring(go_name(char_go(ch)) or "")
    if iris_type_name then local nm = iris_type_name(raw); if nm and nm ~= "" then return nm end end
    local base = raw:match("^(ch%d+)")
    return base or (raw ~= "" and raw or "Target")
end

-- ===== D2D HP PANEL (top-centre target HP bar; imgui fallback if d2d absent). ARGB. Globals only. =====
function griffin_hud_argb(a, r, g, b)
    return ((a & 0xFF) << 24) | ((r & 0xFF) << 16) | ((g & 0xFF) << 8) | (b & 0xFF)
end
function route3_hud_prepare()
    if S.route3_hud_d2d_ok ~= true then return end
    local st = S.route3_d2d or {}; S.route3_d2d = st
    local now = os.clock()
    local sw = 1920.0
    pcall(function() local ds = imgui.get_display_size(); if ds and tonumber(ds.x) then sw = tonumber(ds.x) end end)
    st.sw = sw
    local hud = S.route3_hit_hud
    st.bar = st.bar or {}
    -- retired by default (2026-08-06, Aurora: "I don't really like it anymore") -- flip
    -- route3_dogfight_hit_hud true to bring the top-centre target bar back
    if C.route3_dogfight_hit_hud == true and type(hud) == "table" and now <= (tonumber(hud.until_clock) or 0.0) then
        local mx = math.max(1.0, tonumber(hud.max) or 1.0)
        local after = math.max(0.0, math.min(mx, tonumber(hud.after) or mx))
        local before = math.max(after, math.min(mx, tonumber(hud.before) or after))
        local ease = math.min(1.0, (now - (tonumber(hud.t0) or now)) / 0.35)
        st.bar.visible = true
        st.bar.frac = after / mx
        st.bar.chipFrac = (before / mx) + ((after / mx) - (before / mx)) * ease
        st.bar.name = tostring(hud.name or "Target")
        st.bar.hptext = string.format("%d / %d", math.floor(after), math.floor(mx))
    else
        st.bar.visible = false
    end
end
function griffin_hud_d2d_draw()
    local st = S.route3_d2d; if not st then return end
    local b = st.bar
    if b and b.visible and S.griffin_hud_font then
        local bw, bh = 340.0, 20.0
        local bx = (tonumber(st.sw) or 1920.0) * 0.5 - bw * 0.5
        local by = 92.0
        local d = S.griffin_hud_d2d
        d.fill_rect(bx - 3.0, by - 3.0, bw + 6.0, bh + 6.0, griffin_hud_argb(190, 8, 8, 10))
        d.fill_rect(bx, by, bw, bh, griffin_hud_argb(225, 42, 12, 12))
        d.fill_rect(bx, by, bw * (b.chipFrac or b.frac), bh, griffin_hud_argb(150, 235, 120, 90))
        d.fill_rect(bx, by, bw * (b.frac or 0.0), bh, griffin_hud_argb(255, 225, 45, 45))
        d.text(S.griffin_hud_font, tostring(b.name), bx + 2.0, by - 24.0, griffin_hud_argb(255, 255, 255, 255))
        d.text(S.griffin_hud_font, tostring(b.hptext), bx + bw - 96.0, by - 24.0, griffin_hud_argb(255, 235, 235, 235))
    end
end
function iris_hud_text(s, x, y, col, base)
    -- ⭐ ONE ON-SCREEN FACE (07-21): player-facing strings route through the shared d2d text
    -- layer (IrisFont.lua). ⛔ draw.text takes NO font argument -- it can only ever be the
    -- imgui default bitmap face -- so it stays purely as the no-d2d fallback. GLOBAL on
    -- purpose: this file's call sites sit thousands of lines ABOVE here, and a local would
    -- resolve to a nil global there (the local-function law).
    local F = _G.IrisFont
    if F and F.text and F.text(s, x, y, col, base or 19) then return end
    pcall(draw.text, s, x, y, col)
end

function griffin_hud_fonts()
    -- re-resolved every d2d pass so the shared face/size picker is LIVE (fonts baked once in
    -- the init callback below would ignore the slider until a script reload)
    local F = _G.IrisFont
    if not (F and F.d2d) then return end
    local f = F.d2d(20)
    if f then S.griffin_hud_font = f; S.griffin_hud_font_rodeo = f end
end

function griffin_hud_init_d2d()
    if not _G.d2d then return false end
    S.griffin_hud_d2d = _G.d2d
    S.griffin_hud_d2d.register(function()
        -- FALLBACK faces only -- griffin_hud_fonts overwrites both with the shared IrisFont
        -- serif each pass. Constantia was the old rodeo face: a good match for the game's UI
        -- serif but a MICROSOFT SYSTEM font, so ⛔ not redistributable in a Nexus release.
        S.griffin_hud_font = S.griffin_hud_d2d.Font.new("Tahoma", 20)
        pcall(function() S.griffin_hud_font_rodeo = S.griffin_hud_d2d.Font.new("Constantia", 20) end)
    end, function() pcall(griffin_hud_fonts); pcall(griffin_hud_d2d_draw); pcall(iris_rodeo_bars_d2d_draw); pcall(iris_progress_bar_d2d_draw); pcall(iris_scout_bar_d2d_draw); pcall(iris_mount_hp_d2d_draw) end)
    _G.IrisHudD2DOk = true   -- cross-file signal: the styled d2d gauges own the bars (fallback rects stand down)
    S.route3_hud_d2d_ok = true
    pcall(function() log.info("[hud] d2d HP panel active") end)
    return true
end
pcall(griffin_hud_init_d2d)

-- ⭐ HUD EASING (07-24, Aurora: "sometimes it jumps from 50% to 95%... I want it going up 1% at a
-- time, like a loading bar"). It was never a rendering delay -- the NUMBERS genuinely step: the duel
-- integrates grip on the ox-tame's 0.7s scene tick, so a 0.45/s recovery arrives as one ~0.3 jump.
-- Moving the duel to a per-frame tick would re-tune its whole balance, so instead the BAR eases
-- toward the true value at a fixed rate: always honest, never teleports, and readable mid-ride.
-- Shared by both renderers (d2d + the draw.* fallback) so they can never disagree.
function iris_rodeo_hud_ease(gf, bf)
    local now = os.clock()
    local dt = math.max(0.0, math.min(0.25, now - (tonumber(S.rodeo_shown_t) or now)))
    S.rodeo_shown_t = now
    local rate = 0.9 * dt                     -- ~1.1s for a full sweep; a 30% step reads as ~0.35s
    local function ease(shown, target)
        if shown == nil then return target end -- first frame of a duel: adopt, don't crawl up from 0
        local diff = target - shown
        if math.abs(diff) <= rate then return target end
        return shown + ((diff > 0.0) and rate or -rate)
    end
    S.rodeo_grip_shown = ease(tonumber(S.rodeo_grip_shown), gf)
    S.rodeo_brk_shown = ease(tonumber(S.rodeo_brk_shown), bf)
    return S.rodeo_grip_shown, S.rodeo_brk_shown
end

function iris_companion_hp_tick()
    -- ⭐ r83 (Aurora: "would be good to have this up for all tamed creatures
    -- while they are summoned, instead of while mounted"). Moved out of the
    -- rodeo's ride tick and into the companion frame loop, so it follows the
    -- SOUL rather than the saddle -- wolf, griffin, critter, mounted or not.
    -- ⛔ ONE writer for _G.IrisMountHUD. The rodeo's feed is gone; two modules
    -- writing one value is the exact pattern that caused the scale vibration.
    if C.mount_hp_bar == false then return end
    local ch = nil
    pcall(function() ch = reacquire_griffin() end)
    if not ch then return end
    local go = char_go(ch)
    if not go then return end
    local addr = nil
    pcall(function() addr = go:get_address() end)
    -- ⭐ read the HP store that ACTUALLY MOVES. r83 proved app.HitController on
    -- the body reports full health while the creature is downed; the receiver
    -- captured in the damage hook is the one taking the hits. Prefer it, and
    -- fall back to the old reader only until the first hit lands.
    local hc = addr and (S.hp_source or {})[addr] or nil
    local hp = nil
    if hc then pcall(function() hp = tonumber(hc:call("get_Hp")) end) end
    if not hp then hp = tonumber(griffin_read_target_hp(ch)) end
    local hpmax = nil
    pcall(function()
        hpmax = tonumber(griffin_hp_max_from_component(
            hc or griffin_target_hit_controller(ch)))
    end)
    if not (hp and hpmax and hpmax > 0) then return end
    local nm = "Companion"
    pcall(function()
        local r = griffin_stable_live_rec()
        if type(r) == "table" and r.name then nm = tostring(r.name) end
    end)
    -- Persistent, tiny damage receipt. The framework log is commonly empty
    -- after a relaunch/CTD; this survives and tells us whether a future report
    -- is a hit-routing, HP-write or merely bar-resolution problem.
    pcall(function()
        local hits = tonumber(rawget(_G, "IrisClampHits")) or 0
        local key = table.concat({ tostring(addr), string.format("%.3f", hp),
            string.format("%.3f", hpmax), tostring(hits) }, ":")
        local now = os.clock()
        if key ~= S.companion_damage_diag_key
            and now >= (tonumber(S.companion_damage_diag_at) or 0.0) then
            S.companion_damage_diag_key = key
            S.companion_damage_diag_at = now + 0.2
            local hca = nil
            pcall(function() hca = hc and hc:get_address() end)
            json.dump_file(MOD .. "_companion_damage_diag.json", {
                time = os.date("%H:%M:%S"), name = nm,
                species = tostring(go_name(go) or "?"),
                hp = hp, hp_max = hpmax, fraction = hp / hpmax,
                clamp_hits = hits,
                clamp = tostring(rawget(_G, "IrisClampDbg") or "none"),
                fallback_hits = tonumber(rawget(_G, "IrisFallbackDamageHits")) or 0,
                fallback_last = tostring(rawget(_G, "IrisFallbackDamageLast") or "none"),
                -- 08-12 IV receipts: the bloodline's actual fingerprints on the pipeline
                iv_atk_hits = tonumber(rawget(_G, "IrisIVAtkHits")) or 0,
                iv_last_atk = tostring(rawget(_G, "IrisIVLastAtk") or "none"),
                iv_def_hits = tonumber(rawget(_G, "IrisIVDefHits")) or 0,
                iv_last_def = tostring(rawget(_G, "IrisIVLastDef") or "none"),
                body_address = tostring(addr), hp_source_address = tostring(hca),
            })
        end
    end)
    -- 08-12 UNICORN DISPLAY HP: the native max-HP write is walled (the
    -- engine computes max from an unreachable authority), but the wild-horses
    -- damage hook already makes a unicorn EFFECTIVELY base_hp (incoming
    -- damage x native/base). The bar scales its numbers by that same factor:
    -- identical fraction, denominator = the true effective pool. To the
    -- player this IS 1000 HP.
    pcall(function()
        local api = rawget(_G, "__iris_wild_horses_api")
        -- 08-12 (Aurora: "a flash of 1000/1000 before it changes, every
        -- summon"): the registry's gene-scaled base_hp lands a second AFTER
        -- the variant stamp, so the api briefly answered the plain species
        -- pool. The STABLE RECORD knows the gene from frame one and uses the
        -- SAME curve -- ask it FIRST; the api is the fallback.
        local want = nil
        local r0 = griffin_stable_live_rec()
        if type(r0) == "table" and r0.kind == "horse" then
            local pool0 = (r0.variant == "unicorn")
                and ((api and api.unicorn_base_hp and api.unicorn_base_hp())
                    or 1000) or 250
            local g0 = r0.iv and tonumber(r0.iv.hp)
            local want0 = math.floor(
                pool0 * (g0 and (1.0 + g0 / 30.0 * 0.5) or 1.0) + 0.5)
            if want0 > 250.5 then want = want0 end
        end
        if not want then
            want = api and api.display_max_hp and api.display_max_hp(go)
        end
        if want and want > hpmax then
            local k = want / hpmax
            hp, hpmax = hp * k, want
        end
    end)
    _G.IrisMountHUD = {
        active = true, t = os.clock(),
        frac = math.max(0.0, math.min(1.0, hp / hpmax)),
        label = nm, hp = hp, hp_max = hpmax,
    }
end
local function iris_pet_hp_integer(v)
    -- Exact, readable health values without letting floating-point tails leak
    -- into the HUD: 101265.003 becomes 101,265.
    local n = math.floor(math.max(0.0, tonumber(v) or 0.0) + 0.5)
    local s = tostring(n)
    repeat
        local next_s, changed = s:gsub("^(%d+)(%d%d%d)", "%1,%2")
        s = next_s
        if changed == 0 then break end
    until false
    return s
end
function iris_mount_hp_d2d_draw()
    -- ⭐⭐ MOUNT HEALTH (08-09, Aurora: "is there any way to show the horse's
    -- health bar somewhere while riding? might be useful info"). Now that a
    -- mount can actually be hurt and downed, riding without knowing its HP is
    -- flying blind -- the first warning you get is the body collapsing.
    -- Same iris_hud_bar the house gauge and rodeo bars use, so it is the native
    -- look for free. Top-left: DD2 owns bottom-centre (player HP/stamina) and
    -- top-right (map), and this must never sit on top of either.
    -- Fed by _G.IrisMountHUD = {active, t, frac, label} from the rodeo.
    local d = S.griffin_hud_d2d
    if not d then return end
    local hud = _G.IrisMountHUD
    local now = os.clock()
    local live = type(hud) == "table" and hud.active == true
        and (now - (tonumber(hud.t) or 0.0)) <= 1.0
    local fd = S.mount_hp_fade or { a = 0.0, t = now }
    S.mount_hp_fade = fd
    local dtf = math.max(0.0, math.min(0.1, now - (tonumber(fd.t) or now)))
    fd.t = now
    fd.a = math.max(0.0, math.min(1.0, (tonumber(fd.a) or 0.0)
        + (live and (dtf / 0.25) or -(dtf / 0.35))))
    if live then S.mount_hp_last = hud else hud = S.mount_hp_last end
    if fd.a <= 0.02 or type(hud) ~= "table" then return end
    -- ⛔ r83: no gauges over the pause menu / map / photo mode (Aurora: "it needs
    -- to disappear when the game is paused"). Same oracle the progress bar uses.
    local paused = false
    pcall(function()
        local pm = sdk.get_managed_singleton("app.PauseManager")
        if pm and pm:call("isPausedAny") == true then paused = true end
    end)
    if not paused then
        pcall(function()
            local gm = sdk.get_managed_singleton("app.GuiManager")
            if gm and (gm:call("isPausedGUI") == true
                or gm:call("get_IsDispPhotoModeAll") == true
                or gm:call("get_IsDispPhotoMode") == true) then
                paused = true
            end
        end)
    end
    if paused then return end
    local sw, sh = 1920.0, 1080.0
    pcall(function()
        local ds = imgui.get_display_size()
        if ds then sw = tonumber(ds.x) or sw; sh = tonumber(ds.y) or sh end
    end)
    local scale = sh / 1080.0
    -- ⭐ r83 PLACEMENT (Aurora's marked screenshot): sit it directly ABOVE the
    -- Arisen's own health/stamina pair, matching their width and centring, so it
    -- reads as part of the same stack rather than a mod overlay.
    -- r84 placement, tunable (Aurora: "slightly different size/thickness than
    -- the arisen's, also it currently blocks the arisen's health bar").
    -- Raised clear of the player's pair and thinned to match their weight.
    -- All four are config keys so this can be dialled without another round
    -- trip: mount_hp_w / mount_hp_h / mount_hp_y (up from the bottom) /
    -- mount_hp_x (offset from centre, 0 = centred).
    local bw = (tonumber(C.mount_hp_w) or 552.0) * scale
    local bh = (tonumber(C.mount_hp_h) or 9.0) * scale
    local bx = sw * 0.5 - bw * 0.5 + (tonumber(C.mount_hp_x) or 0.0) * scale
    local by = sh - ((tonumber(C.mount_hp_y) or 112.0) * scale)
    local f = math.max(0.0, math.min(1.0, tonumber(hud.frac) or 0.0))
    local font = S.griffin_hud_font_rodeo or S.griffin_hud_font
    -- ⭐ TRAFFIC-LIGHT (Aurora's split, with the thresholds nudged): under 25%
    -- red, under 60% amber, otherwise green. Deliberately NOT the native crimson
    -- -- a creature's health is a different thing from the Arisen's, and the
    -- colour is doing the work of telling you at a glance.
    local fr, fg, fb, hr, hg, hb
    if f < 0.25 then
        fr, fg, fb, hr, hg, hb = 190, 48, 36, 255, 140, 110       -- red
    elseif f < 0.60 then
        fr, fg, fb, hr, hg, hb = 214, 168, 74, 255, 236, 180      -- DD2 amber
    else
        fr, fg, fb, hr, hg, hb = 92, 158, 68, 190, 245, 170       -- green
    end
    local label = tostring(hud.label or "Companion")
    local hp = tonumber(hud.hp)
    local hpmax = tonumber(hud.hp_max)
    if hp and hpmax and hpmax > 0.0 then
        label = string.format("%s  %s / %s", label,
            iris_pet_hp_integer(hp), iris_pet_hp_integer(hpmax))
    end
    -- Keep the thin gauge visually clean.  iris_hud_bar's house style puts text in the gauge
    -- band, which is fine for 20px progress bars but obscures this 9px companion bar.  Draw the
    -- gauge unlabelled, then place both readings on the baseline immediately above it.
    iris_hud_bar(d, font, bx, by, bw, bh, fd.a, f,
        nil, false, fr, fg, fb, hr, hg, hb)
    if font then
        local A = fd.a
        local function tc(a, r, g, b)
            return griffin_hud_argb(math.floor(a * A + 0.5), r, g, b)
        end
        local ty = by - 21.0 * scale
        local pt = string.format("%d%%", math.floor(f * 100.0 + 0.5))
        local px = bx + bw - 55.0 * scale
        d.text(font, label, bx + 1.0, ty + 1.0, tc(200, 10, 8, 6))
        d.text(font, label, bx, ty, tc(255, 226, 214, 186))
        d.text(font, pt, px + 1.0, ty + 1.0, tc(200, 10, 8, 6))
        d.text(font, pt, px, ty, tc(255, 226, 214, 186))
    end
end
function iris_rodeo_bars_d2d_draw()
    -- ⭐⭐ NATIVE-STYLED rodeo bars (07-21, Aurora: "mimic the game's UI style" -- the Boss Healthbar
    -- Overhaul lesson: the native look = a real serif font + the game's palette + fades, not imgui
    -- rects). d2d gives all three. Smoky backing, antique-gold border, DD2's stamina amber for GRIP
    -- (ember-red when low, like the real stamina bar), crimson for BREAK, top-edge sheen, quarter
    -- ticks, parchment serif labels with a drop shadow, fade in/out envelope.
    local d = S.griffin_hud_d2d
    if not d then return end
    local now = os.clock()
    local hud = _G.IrisRodeoHUD
    local live = type(hud) == "table" and hud.active == true and (now - (tonumber(hud.t) or 0.0)) <= 1.0
    -- fade envelope: 0.25s in, 0.35s out (the last feed keeps drawing through the fade-out)
    local fd = S.rodeo_hud_fade or { a = 0.0, t = now }
    S.rodeo_hud_fade = fd
    local dtf = math.max(0.0, math.min(0.1, now - (tonumber(fd.t) or now)))
    fd.t = now
    fd.a = math.max(0.0, math.min(1.0, (tonumber(fd.a) or 0.0) + (live and (dtf / 0.25) or -(dtf / 0.35))))
    if live then S.rodeo_hud_last = hud else hud = S.rodeo_hud_last end
    if fd.a <= 0.02 or type(hud) ~= "table" then
        -- duel over: forget the eased readings so the next one adopts its opening values instantly
        S.rodeo_grip_shown = nil; S.rodeo_brk_shown = nil
        return
    end
    local A = fd.a
    local function c(a, r, g, b) return griffin_hud_argb(math.floor(a * A + 0.5), r, g, b) end
    local sw = 1920.0
    pcall(function() local ds = imgui.get_display_size(); if ds and tonumber(ds.x) then sw = tonumber(ds.x) end end)
    local bw, bh = 430.0, 20.0
    local bx = sw * 0.5 - bw * 0.5
    local font = S.griffin_hud_font_rodeo or S.griffin_hud_font
    local gf, bf = iris_rodeo_hud_ease(
        math.max(0.0, math.min(1.0, tonumber(hud.grip) or 0.0)),
        math.max(0.0, math.min(1.0, tonumber(hud.brk) or 0.0)))
    if gf < 0.30 then iris_hud_bar(d, font, bx, 56.0, bw, bh, A, gf, "Grip", true, 196, 64, 34, 255, 150, 110)      -- ember: you're losing her
    else iris_hud_bar(d, font, bx, 56.0, bw, bh, A, gf, "Grip", true, 214, 168, 74, 255, 236, 180) end              -- DD2 stamina amber
    if hud.striking == true then iris_hud_bar(d, font, bx, 92.0, bw, bh, A, bf, "Break", true, 214, 60, 40, 255, 150, 120)   -- blood-bright while you land it
    else iris_hud_bar(d, font, bx, 92.0, bw, bh, A, bf, "Break", true, 158, 32, 28, 235, 110, 90) end                        -- native HP crimson
end
function iris_hud_bar(d, font, bx, y, bw, bh, A, frac, label, pct, fr, fg, fb, hr, hg, hb)
    -- ⭐ THE house gauge (07-21): border (antique gold, 1px) -> smoky backing -> leather trough ->
    -- fill + top sheen -> quarter ticks -> parchment serif label (+ optional right-aligned percent).
    -- A = fade alpha 0..1. Shared by the rodeo bars and the universal progress bar.
    local function c(a, r, g, b) return griffin_hud_argb(math.floor(a * A + 0.5), r, g, b) end
    d.fill_rect(bx - 1.0, y - 1.0, bw + 2.0, bh + 2.0, c(150, 158, 130, 78))
    d.fill_rect(bx, y, bw, bh, c(215, 16, 13, 10))
    d.fill_rect(bx + 1.0, y + 1.0, bw - 2.0, bh - 2.0, c(235, 34, 28, 22))
    local fq = math.max(0.0, math.min(1.0, tonumber(frac) or 0.0))
    local fw = (bw - 2.0) * fq
    if fw > 0.5 then
        d.fill_rect(bx + 1.0, y + 1.0, fw, bh - 2.0, c(255, fr, fg, fb))
        d.fill_rect(bx + 1.0, y + 1.0, fw, (bh - 2.0) * 0.42, c(70, hr, hg, hb))   -- top sheen
    end
    for i = 1, 3 do   -- quarter ticks, faint
        d.fill_rect(bx + (bw * 0.25) * i, y + 2.0, 1.0, bh - 4.0, c(70, 0, 0, 0))
    end
    if font then
        if label and label ~= "" then
            d.text(font, label, bx + 9.0, y - 2.0, c(200, 10, 8, 6))               -- drop shadow
            d.text(font, label, bx + 8.0, y - 3.0, c(255, 226, 214, 186))          -- parchment
        end
        if pct then
            local pt = string.format("%d%%", math.floor(fq * 100.0 + 0.5))
            d.text(font, pt, bx + bw - 55.0, y - 2.0, c(200, 10, 8, 6))
            d.text(font, pt, bx + bw - 56.0, y - 3.0, c(255, 226, 214, 186))
        end
    end
end
function iris_progress_bar_d2d_draw()
    -- ⭐⭐ THE UNIVERSAL PROGRESS BAR (07-21, Aurora: "use a bar like this for all the progress
    -- stuff -- any time a % is climbing"): one native-styled amber gauge, lower-center (near where
    -- the game parks its interaction gauges), fed by _G.IrisProgressHUD = {active, t, frac, label}
    -- from ANY rite -- the palm, the pact, the bond, the patience. Same fade envelope as the rodeo.
    local d = S.griffin_hud_d2d
    if not d then return end
    -- no gauges over the pause menu / photo mode (Aurora 07-23) - flags per the pause probe
    local paused = false
    pcall(function()
        local pm = sdk.get_managed_singleton("app.PauseManager")
        if pm and pm:call("isPausedAny") == true then paused = true end
    end)
    if not paused then pcall(function()
        local gm = sdk.get_managed_singleton("app.GuiManager")
        if gm and (gm:call("get_IsDispPhotoModeAll") == true or gm:call("get_IsDispPhotoMode") == true) then paused = true end
    end) end
    if paused then return end
    local now = os.clock()
    local hud = _G.IrisProgressHUD
    local live = type(hud) == "table" and hud.active == true and (now - (tonumber(hud.t) or 0.0)) <= 1.0
    local fd = S.prog_hud_fade or { a = 0.0, t = now }
    S.prog_hud_fade = fd
    local dtf = math.max(0.0, math.min(0.1, now - (tonumber(fd.t) or now)))
    fd.t = now
    fd.a = math.max(0.0, math.min(1.0, (tonumber(fd.a) or 0.0) + (live and (dtf / 0.25) or -(dtf / 0.35))))
    if live then S.prog_hud_last = hud else hud = S.prog_hud_last end
    if fd.a <= 0.02 or type(hud) ~= "table" then return end
    local sw, sh = 1920.0, 1080.0
    pcall(function() local ds = imgui.get_display_size(); if ds then sw = tonumber(ds.x) or sw; sh = tonumber(ds.y) or sh end end)
    local bw, bh = 400.0, 20.0
    if type(hud.bars) == "table" and #hud.bars > 0 then
        -- ⭐ MULTI-BAR mode (07-23, Aurora's construction site: Stone + Timber): feed
        -- hud.bars = { {frac,label}, ... } and they stack upward from the single-bar spot,
        -- same amber, same fades. Single-bar callers keep working untouched.
        for i, b in ipairs(hud.bars) do
            iris_hud_bar(d, S.griffin_hud_font_rodeo or S.griffin_hud_font,
                sw * 0.5 - bw * 0.5, sh * 0.66 + (i - 1) * (bh + 16.0), bw, bh, fd.a,
                tonumber(b.frac) or 0.0, tostring(b.label or ""), true,
                214, 168, 74, 255, 236, 180)
        end
    else
        iris_hud_bar(d, S.griffin_hud_font_rodeo or S.griffin_hud_font,
            sw * 0.5 - bw * 0.5, sh * 0.66, bw, bh, fd.a,
            tonumber(hud.frac) or 0.0, tostring(hud.label or ""), true,
            214, 168, 74, 255, 236, 180)   -- the bond amber
    end
end
