    if hud.lock == true then
        iris_hud_bar(d, nil, sw * 0.5 - bw * 0.5, 92.0, bw, bh, fd.a, sf, nil, false, 196, 64, 34, 255, 150, 110)    -- spent: ember
    elseif hud.sprinting == true then
        iris_hud_bar(d, nil, sw * 0.5 - bw * 0.5, 92.0, bw, bh, fd.a, sf, nil, false, 235, 190, 90, 255, 244, 200)   -- sprinting: bright
    else
        iris_hud_bar(d, nil, sw * 0.5 - bw * 0.5, 92.0, bw, bh, fd.a, sf, nil, false, 214, 168, 74, 255, 236, 180)   -- amber
    end
end
function iris_rodeo_bars_draw()
    -- ⭐ on-screen GRIP + BREAK bars for the ox-tame RODEO (Aurora 07-20: real bars, not "==="). Fed by
    -- _G.IrisRodeoHUD (written each rodeo tick in IrisTaming; cross-file since the two files hold
    -- separate S). Auto-hides when the feed goes stale (duel ended). Built-in draw.* -- ARGB colors.
    -- FALLBACK ONLY (07-21): when d2d is up, the native-styled iris_rodeo_bars_d2d_draw owns the bars.
    if S.route3_hud_d2d_ok == true then return end
    local hud = _G.IrisRodeoHUD
    if not (type(hud) == "table" and hud.active == true) then return end
    if (os.clock() - (tonumber(hud.t) or 0.0)) > 1.0 then _G.IrisRodeoHUD = nil; return end
    if not draw then return end
    pcall(function()
        local sw = 1920.0
        pcall(function() local ds = imgui.get_display_size(); if ds and tonumber(ds.x) then sw = tonumber(ds.x) end end)
        local bw, bh = 360.0, 20.0
        local bx = sw * 0.5 - bw * 0.5
        local gy = 64.0
        -- GRIP (top): green -> amber -> red as it drains
        local gf, bf = iris_rodeo_hud_ease(
            math.max(0.0, math.min(1.0, tonumber(hud.grip) or 0.0)),
            math.max(0.0, math.min(1.0, tonumber(hud.brk) or 0.0)))
        local gcol = (gf < 0.30) and 0xFFE0402A or ((gf < 0.60) and 0xFFE0B020 or 0xFF3CC05A)
        draw.filled_rect(bx - 3.0, gy - 3.0, bw + 6.0, bh + 6.0, 0xC0000000)
        draw.filled_rect(bx, gy, bw, bh, 0xFF23232A)
        draw.filled_rect(bx, gy, bw * gf, bh, gcol)
        draw.text(string.format("GRIP  %d%%", math.floor(gf * 100.0 + 0.5)), bx + 6.0, gy + 2.0, 0xFFFFFFFF)
        -- BREAK (below): fills as she breaks; brightens while you're landing it
        local byy = gy + bh + 10.0
        local bcol = (hud.striking == true) and 0xFF66D0FF or 0xFF3E82D8
        draw.filled_rect(bx - 3.0, byy - 3.0, bw + 6.0, bh + 6.0, 0xC0000000)
        draw.filled_rect(bx, byy, bw, bh, 0xFF23232A)
        draw.filled_rect(bx, byy, bw * bf, bh, bcol)
        draw.text(string.format("BREAK  %d%%%s", math.floor(bf * 100.0 + 0.5), (hud.striking == true) and "  <<<" or ""), bx + 6.0, byy + 2.0, 0xFFFFFFFF)
        -- (the old "act:<name>" DIAG line lived here -- retired 07-21 for release; the action name
        -- still reaches the REF-menu status line via S.status for pattern debugging)
    end)
end

function iris_dive_observer_tick()
    -- ⭐ DIVE OBSERVER (07-20, Aurora's idea): watch a NATURAL wild-griffin dive to reverse-engineer the
    -- state that triggers it. Reads the nearest wild ch253's FSM node(s) + altitude + distance + descent
    -- rate + AI enemy-target-list, every ~0.3s, LOGGED ([DIVEOBS]) + drawn on-screen. Provoke a dive
    -- (stand in the open so a wild griffin swoops at you, or watch one hunt) and read the node SEQUENCE.
    -- ⭐ RE-ARMED 07-25 (Aurora: "can we not trace the nodes for exactly how it does the get up into
    -- flying toward the field -- and the exact same node structure for the positioning into dive?").
    -- Exactly right, and this is the tool for it: it samples her live FSM nodes across trees 0-3 plus
    -- altitude / distance / targets, and flushes to reframework/data/IrisDiveObs.json.
    -- ⛔ OPT-IN, not opt-out (Aurora 2026-07-25: "disable the obs display"). It used to run unless
    -- something explicitly set the flag false, so forgetting to disarm it left a research readout
    -- on a player's screen. Set _G.IrisDiveObs = true to re-arm it for a tracing session.
    if _G.IrisDiveObs ~= true then return end
    local now = os.clock()
    if now - (tonumber(S.dive_obs_at) or 0.0) >= 0.30 then
        S.dive_obs_at = now
        pcall(function()
            local pgo = char_go(get_player()); local pu = pgo and transform_pos(pgo)
            if not pu then return end
            local comp_addr = nil
            pcall(function() local g0 = S.griffin; local gg = g0 and char_go(g0); comp_addr = gg and gg:get_address() end)
            local best, bestd, bestgo = nil, 1e18, nil
            local sm = sdk.get_native_singleton("via.SceneManager")
            local smt = sdk.find_type_definition("via.SceneManager")
            local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
            local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
            for _, ch in ipairs(system_array_to_table(comps) or {}) do
                pcall(function()
                    local go = ch and ch:call("get_GameObject"); if not go then return end
                    if not tostring(go_name(go) or ""):find("ch253", 1, true) then return end
                    if comp_addr and go:get_address() == comp_addr then return end
                    local u = transform_pos(go); local d = u and distance_sq(u, pu)
                    if d and d < bestd then bestd = d; best = ch; bestgo = go end
                end)
            end
            if not bestgo then S.dive_obs = "DIVEOBS: no wild griffin near"; return end
            local gu = transform_pos(bestgo)
            local d3 = math.sqrt(bestd)
            local horiz = math.sqrt((gu.x - pu.x) * (gu.x - pu.x) + (gu.z - pu.z) * (gu.z - pu.z))
            -- height ABOVE THE PLAYER (the ground-cast read 0; this is reliable + is the dive geometry we want)
            local alt = (tonumber(gu.y) or 0.0) - (tonumber(pu.y) or 0.0)
            local vy = 0.0
            if S.dive_obs_py then vy = (gu.y - S.dive_obs_py) / 0.30 end
            S.dive_obs_py = gu.y
            local nodes = {}
            pcall(function()
                local fsm = get_component(bestgo, "via.motion.MotionFsm2")
                if fsm then for t = 0, 3 do local v = fsm:call("getCurrentNodeName", t); if v and tostring(v) ~= "" then nodes[#nodes + 1] = t .. ":" .. tostring(v) end end end
            end)
            -- WHO is she targeting? (Aurora: "show a target too -- player or something, might be an enum")
            local el, etgt = -1, "-"
            pcall(function()
                local bb = get_component(bestgo, "app.AIBlackBoardController")
                if not bb then return end
                local lst = bb:call("get_EnemyActionTargetList")
                el = (lst and tonumber(lst:call("get_Count"))) or -1
                if lst and el > 0 then
                    local at = lst:call("get_Item", 0)
                    local ago = nil
                    pcall(function() ago = at:call("get_GameObject") end)
                    if not ago then pcall(function() ago = at:get_field("_GameObject") end) end
                    if ago then
                        etgt = (pgo and ago:get_address() == pgo:get_address()) and "PLAYER" or tostring(go_name(ago) or "?")
                    else
                        etgt = "at?"
                    end
                end
            end)
            local prey = "-"
            pcall(function()
                local c253 = get_component(bestgo, "app.Ch253000")
                if not c253 then return end
                local pt = nil
                pcall(function() pt = c253:call("get_PredationTarget") end)
                if not pt then pcall(function() pt = c253:get_field("PredationTarget") end) end
                if pt then
                    local ptgo = nil
                    pcall(function() ptgo = pt:call("get_GameObject") end)
                    prey = (pgo and ptgo and ptgo:get_address() == pgo:get_address()) and "PLAYER" or tostring((ptgo and go_name(ptgo)) or go_name(pt) or "?")
                end
            end)
            local line = string.format("DIVEOBS d3=%.0f horiz=%.0f alt=%.0f vy=%.1f enemy(%d)=%s prey=%s | %s", d3, horiz, alt, vy, el, etgt, prey, table.concat(nodes, " "))
            S.dive_obs = line
            log.info("[" .. line .. "]")
            -- ⭐ AUTO-SAVE to JSON (Aurora: no need to watch the panel) -- a rolling buffer of samples,
            -- flushed to reframework/data/IrisDiveObs.json every ~3s while a griffin is near. Only grows
            -- when one's around (we only reach here with a bestgo), so it's the dive window, not idle spam.
            S.dive_obs_buf = S.dive_obs_buf or {}
            S.dive_obs_buf[#S.dive_obs_buf + 1] = {
                t = math.floor(now * 100) / 100, d3 = math.floor(d3), horiz = math.floor(horiz),
                alt = math.floor(alt), vy = math.floor(vy * 10) / 10, enemy_n = el, enemy = etgt,
                prey = prey, nodes = table.concat(nodes, " "),
            }
            while #S.dive_obs_buf > 600 do table.remove(S.dive_obs_buf, 1) end
            if now - (tonumber(S.dive_obs_save_at) or 0.0) > 3.0 then
                S.dive_obs_save_at = now
                pcall(function() json.dump_file("IrisDiveObs.json", { samples = S.dive_obs_buf }) end)
            end
        end)
    end
    if draw and S.dive_obs then
        pcall(function()
            draw.filled_rect(18, 38, 1000, 22, 0xC0000000)
            draw.text(tostring(S.dive_obs), 24, 42, 0xFF80FF80)
        end)
    end
end

-- ============================================================
-- FEATURE MODULES
--
-- Publish the shared helpers, then load the modules. Both happen HERE, after every definition in
-- this file and before any hook is registered: a module binds its dependencies at load time, so
-- exporting piecemeal next to each definition would silently hand a module a nil for anything
-- defined later. One export block means that cannot happen.
--
-- Only file-LOCAL helpers need publishing. The other ~500 top-level functions are already
-- globals -- a chunk cannot hold more than 200 locals -- so modules reach those directly.
-- ⚠ Includes the forward-declared ones (`local f` ... `f = function()`), which look like globals
-- but are not: reacquire_griffin is the one that caught this out.
-- ============================================================
ctx.char_go = char_go
ctx.delete_griffin = delete_griffin
ctx.get_player = get_player
ctx.is_dead = is_dead
ctx.transform_pos = transform_pos
ctx.clear_griffin_hate = clear_griffin_hate
ctx.clear_griffin_targets = clear_griffin_targets
ctx.go_name = go_name
ctx.make_vec3 = make_vec3
ctx.register_griffin = register_griffin
ctx.set_character_transform = set_character_transform
ctx.set_think_stop = set_think_stop
ctx.set_transform = set_transform
ctx.singleton = singleton
ctx.spawn_griffin = spawn_griffin
ctx.stop_navigation = stop_navigation
ctx.yaw_from_transform = yaw_from_transform
ctx.distance_sq = distance_sq
ctx.griffin_action_manager = griffin_action_manager
ctx.make_position = make_position
ctx.make_quat_yaw = make_quat_yaw
ctx.pacify_griffin = pacify_griffin
ctx.read_griffin_fsm_node = read_griffin_fsm_node
ctx.restore_disabled = restore_disabled
ctx.set_griffin_puppet = set_griffin_puppet
ctx.set_motion_fsm_puppet = set_motion_fsm_puppet
ctx.stop_griffin_animation = stop_griffin_animation
ctx.transform_rot = transform_rot
ctx.wrap_angle = wrap_angle
-- ⚠ Not just functions. MOD, DEFAULT and mounts are file-local VARIABLES, and a module that
-- uses one without binding it gets a nil global -- which fails silently inside the pcalls this
-- code is full of. The stable came up empty exactly that way: MOD was nil, so
-- `MOD .. "_stable.json"` threw inside a pcall and the loader decided there was no roster.
ctx.MOD = MOD
ctx.DEFAULT = DEFAULT
ctx.mounts = mounts
ctx.status = status
ctx.get_component = get_component
ctx.table_count = table_count
ctx.motion_tag = motion_tag
ctx.get_griffin_motion_component = get_griffin_motion_component
ctx.play_griffin_motion = play_griffin_motion
ctx.set_griffin_motion_speed = set_griffin_motion_speed
ctx.reacquire_griffin = reacquire_griffin
ctx.system_array_to_table = system_array_to_table

require("IrisGriffin.flap")
require("IrisGriffin.orders")
require("IrisGriffin.stable")
require("IrisGriffin.downed")

re.on_frame(function()
    -- the WHOLE per-frame suite (orders, whistle, climb state, ally writes,
    -- ride safety) ran unguarded through title-screen teardown and loads —
    -- that was the reload crash. Nothing below runs unless the world is live.
    if griffin_world_sentry() ~= true then return end
    griffin_rise_stage("FRAME: on_frame begin (next frame reached)")
