    griffin_rise_stage("FRAME: on_frame COMPLETE -- all lua survived this frame")
end)


-- friendly type name for the stable (species code -> readable)
function iris_type_name(sp)
    local s = tostring(sp or "")
    if s:find("ch253", 1, true) then return "Griffin" end
    if s:find("ch257", 1, true) then return "Drake" end
    if s:find("ch223001", 1, true) then
        -- with the IRIS cat pak the "dog" prefab variants ARE the cats
        -- (2026-08-06, Mia the "Dog" was a panther): _01 = Panther, _00 = Puma
        if s:match("_01$") then return "Panther" end
        return "Puma"
    end
    if s:find("ch223", 1, true) then return "Wolf" end
    if s:find("ch299410", 1, true) then return "Crow" end
    if s:find("ch299430", 1, true) then return "Bird" end
    if s:find("ch299400", 1, true) then return "Bat" end
    if s:find("ch299440", 1, true) then return "Bat" end
    if s:find("ch299420", 1, true) then return "Seabird" end
    if s:find("ch299210", 1, true) then return "Rat" end
    if s:find("ch299200", 1, true) then return "Rabbit" end
    if s:find("ch299221", 1, true) then return "Chicken" end
    if s:find("ch299003", 1, true) then return "Ox" end
    if s:find("ch299011", 1, true) then return "Doe" end
    if s:find("ch299020", 1, true) then return "Goat" end
    if s:find("ch220", 1, true) then return "Goblin" end
    if s:find("ch221", 1, true) then return "Saurian" end
    local band = s:match("ch%d+")   -- unknown species: the band code, never the raw body name
    if band then return band end
    return s ~= "" and s or "Creature"
end

-- ============================================================
-- KEY BINDING -- click, then press the key you want.
--
-- Bindings are stored as Windows VK codes because that is what reframework:is_key_down takes,
-- but nobody should have to know that 0x47 is G. The picker sweeps the VK range for whatever
-- is held and stores it, so the number stays an implementation detail.
--
-- The sweep only runs on frames where the player is actually rebinding, so its cost never
-- reaches normal play. Globals rather than locals: this chunk is on Lua's 200-local ceiling.
-- ============================================================
iris_key_names = {
    [0x08] = "Backspace", [0x09] = "Tab",     [0x0D] = "Enter",  [0x10] = "Shift",
    [0x11] = "Ctrl",      [0x12] = "Alt",     [0x14] = "CapsLk", [0x1B] = "Esc",
    [0x20] = "Space",     [0x21] = "PageUp",  [0x22] = "PageDn", [0x23] = "End",
    [0x24] = "Home",      [0x25] = "Left",    [0x26] = "Up",     [0x27] = "Right",
    [0x28] = "Down",      [0x2D] = "Insert",  [0x2E] = "Delete", [0xBC] = ",",
    [0xBE] = ".",         [0xBF] = "/",       [0xBA] = ";",      [0xDE] = "'",
    [0xDB] = "[",         [0xDD] = "]",       [0xDC] = "\\",     [0xBD] = "-",
    [0xBB] = "=",         [0xC0] = "`",
}
for vk = 0x30, 0x39 do iris_key_names[vk] = string.char(vk) end            -- 0-9
for vk = 0x41, 0x5A do iris_key_names[vk] = string.char(vk) end            -- A-Z
for vk = 0x70, 0x87 do iris_key_names[vk] = "F" .. (vk - 0x6F) end         -- F1-F24
for vk = 0x60, 0x69 do iris_key_names[vk] = "Num" .. (vk - 0x60) end       -- numpad 0-9

function iris_key_label(vk)
    vk = math.floor(tonumber(vk) or 0)
    if vk <= 0 then return "(unbound)" end
    return iris_key_names[vk] or string.format("key 0x%02X", vk)
end

-- Returns a VK code once something is pressed, "cancel" for Esc, or nil while still waiting.
function iris_key_capture_poll()
    -- reads RAW on purpose: the picker only ever runs with the overlay open, which is
    -- what the input gate blocks. Re-assert the capture flag so the key being picked
    -- can't also fire its old action (the gate clears it every frame).
    _G.IrisKeyCaptureActive = true
    if reframework:is_key_down(0x1B) then return "cancel" end
    for vk = 0x08, 0xFE do
        -- 0x01-0x07 are mouse buttons: skipped, or the click that armed the picker would bind
        local down = false
        pcall(function() down = reframework:is_key_down(vk) == true end)
        if down then return vk end
    end
    return nil
end

-- One rebindable row. get/set are functions so this works for our own C.* keys and for the
-- keys owned by IrisTaming and IrisCustomize, which are reached through their bridges.
function iris_key_bind_row(label, get, set, id)
    local cur = 0
    pcall(function() cur = get() end)
    if S.iris_key_capture == id then
        imgui.text(label .. ":  press any key...")
        imgui.same_line()
        if imgui.button("cancel##kbx" .. id) then S.iris_key_capture = nil end
        local got = iris_key_capture_poll()
        if got == "cancel" then
            S.iris_key_capture = nil
        elseif got then
            pcall(function() set(got) end)
            S.iris_key_capture = nil
        end
        return
    end
    if imgui.button(label .. ":  " .. iris_key_label(cur) .. "##kb" .. id) then
        S.iris_key_capture = id
    end
    imgui.same_line()
    if imgui.button("x##kbc" .. id) then pcall(function() set(0) end) end
end

re.on_draw_ui(function()
    -- ============================================================
    -- CLEAN PLAYER PANEL -- the public face: status, the buttons
    -- that matter, orders, the stable. All tuning/probes/dumps
    -- live under "I.R.I.S. dev" (collapsed) below.
    -- ============================================================
    if imgui.tree_node("I.R.I.S.") then
        local chg2
        imgui.text(string.format("%s   ride=%s  flight=%s  air=%s",
            S.griffin and tostring(C.route3_griffin_name or "Companion") or "(no companion - press G to whistle)",
            yn(S.route3_proxy_ride_active), yn(S.airborne), tostring(S.route3_flight_status or "(none)")))
        imgui.separator()

        -- 🐉 DRAKE TESTING (2026-08-12, temporary — dies with the rest of the dev UI).
        -- Everything the close-cam/knocking bisect needs, in one box. Both checkboxes are
        -- the SAME variables as the ones buried in the loop-camera tree, just surfaced.
        if imgui.tree_node("🐉 DRAKE TESTING (camera/knocking bisect)##c_drktest") then
            imgui.text_colored("AIR SEAT: in flight you are not a climber -- the cling mode can't engage.", 0xFF80D0FF)
            local dkas
            dkas, C.route3_air_seat = imgui.checkbox(
                "AIR SEAT (the drake flight fix)##c_drk_airseat", C.route3_air_seat == true)
            if dkas then save_config() end
            local dklv
            dklv, C.route3_air_seat_levitate = imgui.checkbox(
                "LEVITATE HOLD (untick = old puppet mode)##c_drk_levitate",
                C.route3_air_seat_levitate ~= false)
            if dklv then save_config() end
            local dkq
            dkq, C.route3_air_seat_quiet = imgui.checkbox(
                "mute levitate's hum + glow in flight##c_drk_quiet",
                C.route3_air_seat_quiet ~= false)
            if dkq then save_config() end
            imgui.text("   " .. tostring(S.route3_air_quiet_note or "(nothing muted yet)"))
            imgui.text(string.format("seat: %s | relatch: %s | pose: %s",
                tostring(S.route3_air_seat_status or (S.route3_air_seat_on == true and "ON" or "off")),
                tostring(S.route3_air_relatch_status or "-"),
                S.route3_air_seat_pose == true and "riding" or "(none - rs_anim_lab off?)"))
            imgui.text_colored("state: " .. tostring(S.route3_air_lev_state or "-")
                .. " | action: " .. tostring(_G.IrisPlayerActionNode or "-"), 0xFF80FFD0)
            imgui.text("anchor: " .. tostring(S.route3_rider_lock_status or "-"))
            imgui.text("rig: " .. tostring(S.route3_air_joint_note or "(no dump yet)"))
            local dks1, dks2
            -- ⛔ v21: the floor was 0.0, so if the seat point sat ABOVE the back this slider
            -- could not reach the fix at all -- "tune it with the sliders" was never possible.
            -- The drake's "root" joint is NOT at ground level like the griffin's, so the same
            -- +2.3 that seats a griffin puts her metres over a drake.
            dks1, C.route3_seat_offset_y = imgui.drag_float(
                "seat height on her back (can go negative)##c_drk_seaty",
                tonumber(C.route3_seat_offset_y) or 2.3, 0.05, -12.0, 12.0)
            if dks1 then save_config() end
            dks2, C.route3_seat_offset_z = imgui.drag_float(
                "seat forward/back (+ = toward the head)##c_drk_seatz",
                tonumber(C.route3_seat_offset_z) or 1.6, 0.05, -8.0, 8.0)
            if dks2 then save_config() end
            local dkcd
            dkcd, C.route3_drake_cam_dist = imgui.drag_float(
                "camera distance (native camera, stick works)##c_drk_camdist",
                tonumber(C.route3_drake_cam_dist) or 15.0, 0.25, 4.0, 80.0)
            if dkcd then save_config() end
            imgui.text("   cam fields: " .. tostring(S.route3_camfield_note or "(not mounted yet)"))
            local dkpm
            local cling_on = tostring(C.route3_air_seat_pose_mode or "cling") == "cling"
            dkpm, cling_on = imgui.checkbox(
                "grab-on pose in flight (untick = Wilds riding pose)##c_drk_posemode", cling_on)
            if dkpm then
                C.route3_air_seat_pose_mode = cling_on and "cling" or "wilds"
                save_config()
            end
            local dk1, dk2
            dk1, C.route3_loopcam = imgui.checkbox(
                "cinematic camera on ascend/descend##c_drk_loopcam", C.route3_loopcam ~= false)
            if dk1 then save_config() end
            dk2, C.route3_rise_clip_enabled = imgui.checkbox(
                "flight animation (clip paint) on ascend/descend##c_drk_riseclip",
                C.route3_rise_clip_enabled ~= false)
            if dk2 then save_config() end
            if imgui.button("APPLY species profile now##c_drk_apply") then
                pcall(function()
                    local dgo = select(2, reacquire_griffin())
                    local raw = dgo and (tostring(go_name(dgo) or ""):match("^[^@]+") or "") or ""
                    local skey = raw:match("ch%d+_%a_%d+") or raw:match("ch%d+_%d+")
                    griffin_species_profile_apply(skey or griffin_species_key())
                    save_config()
                    status("profile: " .. tostring(S.route3_profile_status))
                end)
            end
            imgui.same_line()
            imgui.text(tostring(S.route3_rise_status or "(no rise yet)"))
            imgui.tree_pop()
        end
        imgui.separator()

        if imgui.button("Spawn / replace##c_spawn") then spawn_griffin() end
        imgui.same_line()
        if imgui.button("Adopt / ride##c_adopt") then route3_start_auto_ride("button") end
        imgui.same_line()
        if imgui.button("Dismount##c_dismount") then dismount_griffin() end
        imgui.same_line()
        if imgui.button("Calm##c_calm") then pacify_griffin("manual calm"); stop_griffin_animation() end
        imgui.same_line()
        if imgui.button("Dismiss##c_dismiss") then griffin_dismiss() end
        imgui.same_line()
        -- "Release", not "Delete": this is the one that takes her OUT of the stable for good
        -- (delete_griffin ends with griffin_stable_remove_active). Dismiss keeps the soul and
        -- whistles her back; this does not. It asks first, by name, for that reason.
        if S.iris_release_confirm then
            imgui.text_colored("Release " .. tostring(C.route3_griffin_name or "this one") .. " for good?", 0xFFFFC080)
            imgui.same_line()
            if imgui.button("Yes, release##c_release_yes") then
                S.iris_release_confirm = nil
                delete_griffin()
            end
            imgui.same_line()
            if imgui.button("Cancel##c_release_no") then S.iris_release_confirm = nil end
        elseif imgui.button("Release##c_release") then
            S.iris_release_confirm = true
        end
        -- IV readout (v1): the active companion's rolled genes. SIZE is rolled but not yet
        -- applied to the body (deliberate -- scale composes with wyrm growth; own pass later).
        pcall(function()
            local rec9 = griffin_stable_active()
            local iv9 = rec9 and rec9.iv
            if iv9 then
                imgui.text(string.format("IVs of %s (selected):  HP %d | ATK %d | DEF %d | SPD %d | SIZE %d | LUCK %d",
                    tostring(rec9.name or "?"),
                    tonumber(iv9.hp) or 0, tonumber(iv9.atk) or 0, tonumber(iv9.def) or 0,
                    tonumber(iv9.spd) or 0, tonumber(iv9.size) or 0, tonumber(iv9.luck) or 0))
            end
        end)

        imgui.separator()
        imgui.text("Orders: " .. tostring(S.companion_order or "stay"))
        imgui.same_line()
        if imgui.button("Follow##c_follow") then
            if S.route3_unleashed == true then griffin_recall() end
            S.companion_order = "follow"; status(tostring(C.route3_griffin_name or "Companion") .. " follows you")
        end
        imgui.same_line()
        if imgui.button("Stay##c_stay") then
            if S.route3_unleashed == true then griffin_recall()
            elseif S.companion_order == "attack" then griffin_order_disengage("ordered")
            else S.companion_order = "stay"; S.route3_companion_moving = false; stop_griffin_animation(); status(tostring(C.route3_griffin_name or "Companion") .. " stays") end
        end
        imgui.same_line()
        if imgui.button("Come##c_come") then
            if S.route3_unleashed == true then griffin_recall() end
            S.companion_order = "come"; status(tostring(C.route3_griffin_name or "Companion") .. " is coming")
        end
        imgui.same_line()
        if imgui.button("Attack##c_attack") then
            if S.route3_unleashed == true then griffin_recall() end
            griffin_order_attack()
        end
        imgui.same_line()
        if imgui.button("Eat##c_eat") then griffin_eat_start("button") end

        imgui.separator()
        local cst = S.route3_stable
        if cst and cst.companions and #cst.companions > 0 then
            imgui.text("STABLE")
            for ci, comp in ipairs(cst.companions) do
                if S.iris_rename_target == comp.id then
                    imgui.text("Name " .. tostring(comp.name or "?") .. ":")
                    chg2, S.iris_rename_buf = imgui.input_text("##c_rename_input", tostring(S.iris_rename_buf or comp.name or ""))
                    imgui.same_line()
                    if imgui.button("Seal##c_rename_ok") then
                        local nm = tostring(S.iris_rename_buf or "")
                        if nm ~= "" then
                            comp.name = nm
                            if comp.id == cst.active then C.route3_griffin_name = nm end
                            pcall(function() griffin_stable_write() end)
                            pcall(function() griffin_tamed_save() end)
                            pcall(function() save_config() end)
                            S.iris_rename_confirm = nm .. " it is."
                            S.iris_rename_confirm_at = os.clock() + 4.0
                            status("renamed to " .. nm)
                        end
                        S.iris_rename_target = nil
                    end
                    imgui.same_line()
                    if imgui.button("Cancel##c_rename_cancel") then S.iris_rename_target = nil end
                else
                    local active = comp.id == cst.active
                    local gsym = (comp.gender == "female" and " \u{2640}") or (comp.gender == "male" and " \u{2642}") or ""
                    -- the record's KIND stamp outranks the species band (08-06:
                    -- Chad the horse read "(Doe)" -- both are ch299011).
                    -- 08-12: the VARIANT outranks the kind (Epona read "(Horse)")
                    local kind_nm = (comp.variant == "unicorn" and "Unicorn")
                        or (comp.kind == "horse" and "Horse")
                        or iris_type_name(comp.species)
                    local label = string.format("%s%s%s  (%s)##c_stable_%d",
                        active and "> " or "    ",
                        tostring(comp.name or "?"), gsym, kind_nm, ci)
                    if imgui.button(label) and not active then
                        if S.mounted == true then
                            status("dismount before switching companions")
                        else
                            griffin_tamed_save()
                            S.griffin = nil; S.griffin_go = nil
                            cst.active = comp.id
                            griffin_stable_set_shim(comp)
                            S.route3_tamed_restore_at = os.clock() + 1.0
                            S.route3_tamed_restore_tries = 0
                            griffin_stable_write()
                            status("active companion: " .. tostring(comp.name) .. " - whistle (G) to call")
                        end
                    end
                    imgui.same_line()
                    if imgui.button("Rename##c_ren_" .. tostring(ci)) then
                        if _G.IrisTaming and _G.IrisTaming.open_rename then
                            pcall(function() _G.IrisTaming.open_rename(comp.id, comp.name) end)
                        else
                            S.iris_rename_target = comp.id; S.iris_rename_buf = comp.name or ""
                        end
                    end
                end
            end
            if S.iris_rename_confirm and os.clock() < (tonumber(S.iris_rename_confirm_at) or 0.0) then
                imgui.text_colored(tostring(S.iris_rename_confirm), 0xFF80FFB0)
            end
        else
            imgui.text("(stable empty -- tame a creature to begin)")
        end

        -- customize (colour) -- active companion only, which is always a tamed creature
