                chg2, cc[1] = imgui.drag_float("R##c_col_r", cc[1], 0.02, 0.0, 2.0)
                chg2, cc[2] = imgui.drag_float("G##c_col_g", cc[2], 0.02, 0.0, 2.0)
                chg2, cc[3] = imgui.drag_float("B##c_col_b", cc[3], 0.02, 0.0, 2.0)
                S.iris_color = cc
                if imgui.button("Apply##c_col_apply") then iris_apply_active_color(cc) end
                imgui.same_line()
                if imgui.button("Reset##c_col_reset") then S.iris_color = { 1.0, 1.0, 1.0, 1.0 }; iris_apply_active_color(S.iris_color) end
                local presets = {
                    { "Grey", { 0.5, 0.5, 0.5, 1 } }, { "Black", { 0.12, 0.12, 0.13, 1 } }, { "White", { 1.5, 1.5, 1.5, 1 } },
                    { "Red", { 0.6, 0.12, 0.1, 1 } }, { "Brown", { 0.35, 0.22, 0.12, 1 } }, { "Blue", { 0.2, 0.3, 0.7, 1 } },
                    { "Gold", { 1.1, 0.75, 0.2, 1 } }, { "Green", { 0.2, 0.5, 0.2, 1 } }, { "Purple", { 0.45, 0.2, 0.6, 1 } },
