            end
            imgui.same_line()
            local ck2 = 0x43
            pcall(function() if _G.IrisCustomize and _G.IrisCustomize.get_key then ck2 = _G.IrisCustomize.get_key() end end)
            imgui.text("(or press " .. iris_key_label(ck2) .. ")")
