        -- the same frame, no timing involved at all.
        imgui.separator()
        local pose_set = (tonumber(C.route3_rider_pose_bank) or -1) >= 0
            and (tonumber(C.route3_rider_pose_clip) or -1) >= 0
        if pose_set then
