                S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil
                save_config(); status("riding pose forgotten -- back to freezing whatever is playing")
            end
        else
            imgui.text("Riding pose: none captured (she freezes on whatever frame is playing)")
        end
