                C.route3_rider_pose_clip = math.floor(tonumber(cur.clip) or 0)
                C.route3_rider_pose_frame = tonumber(cur.frame) or 0.0
                S.rider_pose_frozen = false; S.rider_pose_settle_sig = nil
