            imgui.text_colored("⭐ WHY ARE THE RIDERS DISPLACED AFTER A LOOP?", 0xFF66FF66)
            imgui.text_colored("Hover level, click BEFORE. Do a loop. Click AFTER.", 0xFFAAAAAA)
            if imgui.button("1. BEFORE##c_seatdiag_a") then
                S.route3_seat_diag_a = griffin_seat_diag_capture()
                S.route3_seat_diag_b = nil
                status("seat baseline captured -- now do a loop, then click AFTER")
            end
            imgui.same_line()
            if imgui.button("2. AFTER##c_seatdiag_b") then
                S.route3_seat_diag_b = griffin_seat_diag_capture()
                status("seat baseline compared -- read the deltas in the panel")
            end
            local da, db = S.route3_seat_diag_a, S.route3_seat_diag_b
            if da and db then
                -- The griffin will have FLOWN between captures, so uni/ren move a lot and that is
                -- meaningless on its own. What matters is whether the DERIVED seats moved by more
                -- than the body did -- that is the part that cannot be explained by ordinary flight.
                imgui.text(griffin_seat_diag_line("uni", da, db) .. "   <- body (expected to move)")
                imgui.text(griffin_seat_diag_line("ren", da, db))
                imgui.text(griffin_seat_diag_line("root", da, db))
                imgui.text(griffin_seat_diag_line("spine", da, db))
                imgui.text(griffin_seat_diag_line("rider", da, db) .. "   <- rebased via ROOT")
                imgui.text(griffin_seat_diag_line("pawnseat", da, db) .. "   <- rebased via RENDER")
                -- the discriminator: seat offset RELATIVE to the body, which flight cannot change
                if da.rider and db.rider and da.uni and db.uni then
                    local ax = da.rider.x - da.uni.x; local ay = da.rider.y - da.uni.y; local az = da.rider.z - da.uni.z
                    local bx = db.rider.x - db.uni.x; local by = db.rider.y - db.uni.y; local bz = db.rider.z - db.uni.z
                    imgui.text_colored(string.format(
                        "RIDER offset from body changed by (%+.2f %+.2f %+.2f)  <- THE ANSWER",
                        bx - ax, by - ay, bz - az), 0xFF66FFFF)
                end
                if da.spine and db.spine and da.root and db.root then
                    imgui.text_colored(string.format(
                        "SPINE offset from ROOT changed by (%+.2f %+.2f %+.2f)  <- residual pose?",
                        (db.spine.x - db.root.x) - (da.spine.x - da.root.x),
                        (db.spine.y - db.root.y) - (da.spine.y - da.root.y),
                        (db.spine.z - db.root.z) - (da.spine.z - da.root.z)), 0xFF66FFFF)
                end
                imgui.text(string.format("clip  before b%s:%s@%s   after b%s:%s@%s",
                    tostring(da.bank), tostring(da.clip), tostring(da.frame and math.floor(da.frame)),
                    tostring(db.bank), tostring(db.clip), tostring(db.frame and math.floor(db.frame))))
                imgui.text("fsm   before " .. tostring(da.fsm) .. "   after " .. tostring(db.fsm))
            elseif da then
                imgui.text("baseline captured -- do a loop, then click AFTER")
            end
            if S.base_owner_blocked then
                imgui.text_colored("   last blocked: " .. tostring(S.base_owner_blocked), 0xFFAAAAAA)
            end
            imgui.text("rider pin: " .. tostring(S.route3_rider_seat_follow or "(flat seat - old behaviour)"))
            -- ⛔ WHO ACTUALLY OWNS THE RIDER? The seat-joint fix went into route3_rider_pin_late,
            -- which returns immediately when the puppet seat is active -- and the puppet seat's
            -- own seat_pin_apply returns for a pose_only costume ("the native climb owns
            -- position... never pin"). If BOTH are off, the native climb holds her and no lua
            -- write reaches her at all, which is exactly "hovers where the motion starts".
            do
                local ps_on = false
                pcall(function() ps_on = iris_puppet_seat_active() == true end)
                local owner
                if ps_on then owner = "IrisPuppetSeat (route3_rider_pin_late RETURNS -> my fix never runs)"
                elseif S.route3_rider_puppet_on == true then owner = "route3_rider_puppet WELD (we own her - fix belongs here)"
                elseif S.native_climb_mount == true then owner = "NATIVE CLIMB (no lua write reaches her)"
                else owner = "route3_rider_pin_late (the fix SHOULD be active)" end
                imgui.text_colored("rider owner: " .. owner, 0xFF66FFFF)
            end
            imgui.text_colored("Position only. If he rides the loop but faces wrong, that is the", 0xFF88CCFF)
            imgui.text_colored("NEXT problem (orientation), not this one.", 0xFF88CCFF)

