            -- NODE PICKER: 444 names is unusable as a text box. Filter -> dropdown -> assign.
            -- ⛔-marked entries match route3_rise_node_blocklist (known crashy / camera-breaking);
            -- they can still be picked, but firing one needs the bypass and that resets each launch.
            local ff
            ff, S.node_pick_filter = imgui.input_text("filter##c_nodefilter", tostring(S.node_pick_filter or ""))
            local all = griffin_fsm_node_names()
            local shown, raw = {}, {}
            local filt = tostring(S.node_pick_filter or ""):lower()
            for _, n in ipairs(all) do
                if filt == "" or n:lower():find(filt, 1, true) then
                    raw[#raw + 1] = n
                    shown[#shown + 1] = (griffin_fsm_node_is_blocked(n) and "⛔ " or "   ") .. n
                end
            end
            if #shown == 0 then
                shown[1] = (#all == 0) and "(no live tree -- mount her first)" or "(no match)"
                raw[1] = ""
            end
            S.node_pick_idx = math.min(math.max(1, math.floor(tonumber(S.node_pick_idx) or 1)), #shown)
            local nc
            nc, S.node_pick_idx = imgui.combo(string.format("node (%d/%d)##c_nodecombo", #shown, #all),
                S.node_pick_idx, shown)
            local sel = raw[S.node_pick_idx] or ""
            if imgui.button("set as ASCEND (A)##c_setnodeup") and sel ~= "" then
                C.route3_rise_node_up = sel; save_config(); status("ascend node = " .. sel)
            end
            imgui.same_line()
            if imgui.button("set as DESCEND##c_setnodedown") and sel ~= "" then
                C.route3_rise_node_down = sel; save_config(); status("descend node = " .. sel)
            end
            imgui.same_line()
            if imgui.button("clear both##c_clearnodes") then
                C.route3_rise_node_up = ""; C.route3_rise_node_down = ""; save_config()
                status("rise/dive nodes cleared -- clip only")
            end
            -- profile apply only auto-runs at TAME time; this re-applies (and migrates) the
            -- ACTIVE body's species profile mid-session -- keyed off the live body name, the
            -- same parse tame_creature uses, so it can't mis-key on a stale S value.
            if imgui.button("APPLY species profile now (re-read + migrate)##c_profapply") then
                local dgo = select(2, reacquire_griffin())
                local raw = dgo and (tostring(go_name(dgo) or ""):match("^[^@]+") or "") or ""
                local skey = raw:match("ch%d+_%a_%d+") or raw:match("ch%d+_%d+")
                griffin_species_profile_apply(skey or griffin_species_key())
                save_config()
                status("profile: " .. tostring(S.route3_profile_status))
            end
            -- camera-writer trace: tick, do ONE ascend, wait a second -- the trace dumps
            -- itself to data/..._camtrace.json (who re-poses the camera after our write).
            local ctr
            ctr, C.route3_camtrace = imgui.checkbox("CAMERA TRACE (cling close-up hunt)##c_camtrace",
                C.route3_camtrace == true)
            if ctr then save_config() end
            if S.route3_camtrace_status then imgui.text(tostring(S.route3_camtrace_status)) end
            imgui.text(string.format("cam switches: last=%s vetoed=%d",
                tostring(S.route3_camswitch_last or "(none seen)"),
                tonumber(S.route3_camswitch_veto_count) or 0))
            imgui.text(string.format("cam SETS: last=%s vetoed=%d",
                tostring(S.route3_camset_last or "(none seen)"),
                tonumber(S.route3_camset_veto_count) or 0))
            imgui.text(string.format("climb-flag pins: %d | climb-set FALSE vetoes: %d",
                tonumber(S.route3_climbpin_count) or 0,
                tonumber(S.route3_climbset_veto_count) or 0))
            -- pawn ride toggle surfaced here (old UI's checkbox is gone): untick = the pawn
            -- does not board at the next mount -- the solo-flight knocking A/B.
            local pr
            pr, C.route3_pawn_ride = imgui.checkbox("pawn rides along##c_pawnride",
                C.route3_pawn_ride ~= false)
            if pr then save_config() end
            -- persist the CURRENT tuning (incl. node-picker choices) into the active species'
            -- profile -- without this, a picked rise node lives only in the global config and
            -- the next profile apply overwrites it.
            if imgui.button("SAVE current tuning to species profile##c_profsave") then
                griffin_species_profile_save()
                status("profile: " .. tostring(S.route3_profile_status))
            end
            -- DUMP the live tree to data/ so it can be read offline (species recon: drake etc).
            -- Reads the ACTIVE registered body's tree -- summon/mount the creature first.
            if imgui.button("DUMP node tree to file##c_nodedump") then
                local dump_names = griffin_fsm_node_names()
                local dgo = select(2, reacquire_griffin())
                local who = "unknown"
                pcall(function() who = tostring(dgo:call("get_Name")) end)
                json.dump_file(MOD .. "_nodetree.json",
                    { body = who, count = #dump_names, nodes = dump_names })
                status(string.format("node tree DUMPED: %d nodes (%s) -> data", #dump_names, who))
            end
            imgui.text("ASCEND  (A): " .. (C.route3_rise_node_up ~= "" and tostring(C.route3_rise_node_up) or "(none - clip only)"))
            imgui.text("DESCEND    : " .. (C.route3_rise_node_down ~= "" and tostring(C.route3_rise_node_down) or "(none - clip only)"))
            local function arm_ascend(node_name, label)
                C.route3_rise_node_up = node_name
                C.route3_rise_use_node = true
                C.route3_rise_node_allow_blocked = true  -- "Hovering" is force-blocklisted at load
                C.route3_rise_node_with_clip = false     -- node owns the anim: exactly ONE owner
                save_config()
                status("ascend node ARMED: " .. label .. " -- stable hover, high up, press A once")
            end
            imgui.text_colored(">>> ARMED ON A: " .. (C.route3_rise_node_up ~= "" and tostring(C.route3_rise_node_up)
                or "(nothing - clip only)"), 0xFF00FFFF)
            if imgui.button("STEP 1 -- CONTROL: HoverWait (asks for NO movement)##c_arm_hoverwait") then
                arm_ascend("Fly.Hovering.HoverWait", "HoverWait -- should NOT move her")
            end
            if imgui.button("STEP 2 -- REAL: HoverUpward (only after step 1 is clean)##c_arm_hoverup") then
                arm_ascend("Fly.Hovering.HoverUpward", "HoverUpward")
            end
            if imgui.button("clear ascend##c_clear_up") then
                C.route3_rise_node_up = ""
                save_config()
                status("ascend node cleared -- A is back to clip-only")
            end
            imgui.text_colored("Run 1 FIRST: HoverWait proves the window opens and the standdown", 0xFF88CCFF)
            imgui.text_colored("holds WITHOUT asking her to move. Then 2 asks for movement.", 0xFF88CCFF)
            imgui.text_colored("⚠ ARM also sets the blocklist bypass ('Hovering' is force-blocked).", 0xFF88CCFF)
            imgui.text_colored("That bypass resets OFF every launch -- re-arm after any relaunch.", 0xFF88CCFF)

            imgui.text("FC-lift: " .. tostring(S.route3_rise_fc_status or "(idle)"))
            imgui.text_colored("Read that line: 'NO WRITE ACCEPTED' = wrong door, not a failed idea.", 0xFF88CCFF)

            imgui.separator()
            imgui.text_colored("LOOP-THE-LOOP DIVE TEST -- ⛔ CAN CTD. SAVE FIRST.", 0xFF6666FF)
            imgui.text_colored("Arms the loop node on quick-DESCEND, keeping the 5010 descend", 0xFFAAAAAA)
            imgui.text_colored("clip painted underneath it (node + motion = the crashy combo).", 0xFFAAAAAA)
            local function arm_loop(node_name)
                C.route3_rise_node_down = node_name
                C.route3_rise_node_allow_blocked = true   -- bypass the blocklist for the rise path
                C.route3_rise_node_with_clip = true       -- keep the descend clip underneath
                C.route3_rise_use_node = true
                C.route3_rise_clip_enabled = true
                save_config()
                status("LoopTheLoop dive ARMED: " .. node_name .. " (+clip). Quick-descend to fire.")
            end
            if imgui.button("ARM loop##c_arm_loop") then
                arm_loop("Fly.Flight.Ch253LoopTheLoopFlight")
            end
            imgui.same_line()
            if imgui.button("ARM pre-loop##c_arm_preloop") then
                arm_loop("Fly.Flight.Ch253PreLoopTheLoopFlight")
            end
            imgui.same_line()
            if imgui.button("DISARM##c_disarm_loop") then
                C.route3_rise_node_down = ""
                C.route3_rise_node_allow_blocked = false
                C.route3_rise_node_with_clip = false
                S.route3_rise_bypassed = nil
                save_config()
                status("LoopTheLoop dive DISARMED (descend is back to clip-only)")
            end
            local ac2
            ac2, C.route3_rise_node_with_clip =
                imgui.checkbox("keep the descend clip under the node##c_loop_withclip",
                    C.route3_rise_node_with_clip == true)
            if ac2 then save_config() end
            imgui.text("Dive node: " .. (C.route3_rise_node_down ~= "" and tostring(C.route3_rise_node_down) or "(none - clip only)"))
            imgui.text("Rise/dive state: " .. tostring(S.route3_rise_status or "(idle)"))
            -- ⭐ THE THING TO WATCH (2026-07-26). Descend fires nodes fine, ascend gets refused --
            -- so a descent puts her FSM in the Fly tree and a hover leaves her in Locomotion.Wait.
            -- Whatever transitions her IS the unlock for every ascend node. Watch this line while
            -- you fly: hover, climb, glide, dive. Green = a node may fire, red = it will be refused.
            local live_node = "?"
            pcall(function() live_node = tostring(read_griffin_fsm_node() or "?") end)
            local in_fly = live_node:find("Fly.", 1, true) == 1
            imgui.text_colored((in_fly and "✅ HER FSM: " or "⛔ HER FSM: ") .. live_node,
                in_fly and 0xFF66FF66 or 0xFF6666FF)
            imgui.text_colored(in_fly and "   -> in the Fly tree: ascend nodes CAN fire right now"
                or "   -> not in the Fly tree: any Fly.* node will be refused", 0xFFAAAAAA)
            -- ⚠ HONEST RE-EVALUATION (2026-07-26): this gate was added believing the CTDs were
            -- Locomotion->Fly cross-tree fires. They were NOT -- every one is explained by clip
            -- 5010 (com_hover_idle_loop_heavey), including the LoopTheLoop run, which had
            -- route3_rise_node_with_clip=true painting 5010 underneath the node. With the clip
            -- fixed there is NO evidence a cross-tree fire crashes on its own -- and 07-24 found
            -- Fly.Hovering.* fired airborne+standalone is safe. So this is now a PRECAUTION, not
            -- a proven law, and it is the only thing blocking ascend nodes. Untick to test.
            imgui.text_colored("   (gates removed -- whatever the picker holds WILL fire)", 0xFFAAAAAA)
            imgui.text_colored("Never armed at boot -- a CTD relaunches safe.", 0xFF88CCFF)
            imgui.tree_pop()
        end

        imgui.text_colored("Everything else is pre-tuned.", 0xFFAAAAAA)
        imgui.tree_pop()
    end

    -- The dev workshop lived here: ~2,300 lines exposing 711 config knobs, every probe,
    -- dump and abandoned experiment. It was the last thing referencing most of them, which
    -- is why it was cut LAST -- removing it is what let the dead code be found and deleted.
    -- Recover any of it from git: tag devtools-last-intact, or branch
    -- refactor/griffin-slimdown-precut.
end)

re.on_script_reset(function()
    -- ROUND-47: disarm the transform-write intercept BEFORE any recovery below
    -- writes the player (a live intercept would silently skip the restores)
    S.route3_txi_live = false
    S.route3_our_write = false
    S.route3_rider_pose_gate_until = nil
    -- v14: restore any overridden camera BaseDistance BEFORE S dies (a reload wipes the
    -- saved originals while the field would stay overridden = far-camera-on-foot leak)
    pcall(iris_camdist_restore)
    -- v18: and give back every effect/sound component the quiet sweep muted -- a reload wipes
    -- the restore list, so a mid-flight reset would leave her permanently silent and glowless
    pcall(iris_air_seat_quiet_sweep, false)
    if S.route3_air_lev_mode == true then
        S.route3_air_lev_mode = nil
        pcall(function() iris_air_seat_player_action("NormalLocomotion", 0, 0) end)
    end
    -- v12 air seat (statue law, exit 3 of 3): drop the latch and release the puppet
    -- explicitly -- a reset mid-flight must never strand an FSM-off rider
    S.route3_air_seat_on = false
    S.route3_air_seat_air_since = nil
    S.route3_air_relatch_check_at = nil
    if S.route3_airseat_cam_parked == true then
        S.route3_airseat_cam_parked = nil
        pcall(function()
            griffin_loopcam_cam_switch(tonumber(S.route3_loopcam_game_ct) or 0)
            S.route3_loopcam_cam_ct = nil
        end)
    end
    pcall(function()
        local pl = get_player()
        local at = pl and pl:get_field("<AdjustTerrain>k__BackingField")
        if at then at:call("setEnable", true) end
    end)
    pcall(function() route3_rider_puppet(false) end)
    -- ROUND-56: never orphan a spawned saddle across a reset (the S ref would be
    -- lost and the stool left welded in the world)
    pcall(function() griffin_saddle_despawn() end)
    -- never leave an fc-lift standdown lease open across a reset (= a ride with no writer)
    pcall(function() route3_rise_fc_lift_end("script reset") end)
    pcall(function() route3_recover_rider_state("script reset") end)
    pcall(function() set_rider_hard_lock(false) end)
    pcall(function() restore_rider_disabled() end)
    pcall(function() restore_disabled() end)
    -- ride-pose leases: never leave the player frozen/FSM-dead across a reset
    pcall(function() route3_rider_puppet(false) end)
    -- STEADY SEAT v2 leases: never leave her think-stopped / abort-rejected / FROZEN
    -- across a reset (a Reset Scripts mid-ride would otherwise strand a statue)
    pcall(function()
        local ctrl = get_climb_ctrl(get_player())
        if ctrl then ctrl:set_field("<IsRejectAbortOnDefault>k__BackingField", false) end
    end)
    pcall(function() set_think_stop(get_player(), false) end)
    pcall(function()
        griffin_set_player_fsm_enabled(true)
        griffin_set_player_motion_speed(1.0)
    end)
    -- never leave the player immortal across a reset (ride fall-immunity lease)
    pcall(function() route3_grab_set_immunity(get_player(), false) end)
    -- never leave FlightControl disabled across a reset (slice-0 probe lease = unflyable griffin)
    pcall(function() if S.downed_probe_fc then griffin_probe_fc_restore("script reset") end end)
    -- ⛔ never leave a companion DOWNED across a reset: four leases (immunity, AI, nav, HP pin)
    -- with no state left to unwind them = an immortal brain-dead pet
    pcall(function() griffin_downed_release_all("script reset") end)
    -- never leave the native camera pushed back across a reset
    pcall(function() sdk.get_managed_singleton("app.CameraManager"):call("set_DistanceOffset", 0.0) end)
    pcall(function()
        local human = get_player():call("get_Human")
        if human and human.Fsm then human.Fsm:set_Enabled(true) end
    end)
    pcall(function() griffin_set_player_motion_speed(1.0) end)
    pcall(function() griffin_pause_player_motion_layers(false) end)
    pcall(function() griffin_set_player_fsm_enabled(true) end)
end)

if C.native_observer_log_enabled == true then clear_observe_log() end
save_config()
status("loaded")

-- the TYPING GUARD fallback (the real one lives in IrisTaming; this covers load order /
-- a taming load failure so the probe's hotkeys never die with it)
if not iris_kb then
    function iris_kb(vk9)
        if type(iris_input_blocked) == "function" and iris_input_blocked() then return false end
        if _G.RiftSpeakPromptOpen == true or _G.RiftSpeak_PromptOpen == true then return false end
        local dn9 = false
        pcall(function() dn9 = reframework:is_key_down(vk9) == true end)
        return dn9
    end
end
